  import Main._
  import java.util.Arrays.sort

  import scala.collection.mutable
  import math.{abs, max, min}
  import mutable.ArrayBuffer

  def packUGraph(n: Int, from: Array[Int], to: Array[Int]): Array[Array[Int]] = {
    val t = new Array[Array[Int]](n)
    val p = new Array[Int](n)
    val m = from.length
    REP(m)(i => p(from(i)) += 1)
    REP(m)(i => p(to(i)) += 1)
    REP(n)(i => t(i) = new Array(p(i)))
    REP(m) { i =>
      p(from(i)) -= 1
      t(from(i))(p(from(i))) = to(i)
      p(to(i)) -= 1
      t(to(i))(p(to(i))) = from(i)
    }
    t
  }
}

class Main(out: java.io.PrintWriter, sc: Main.InputReader) {
  import sc._
  import Main._
  import java.util.Arrays.sort

  import scala.collection.mutable
  import math.{abs, max, min}
  import mutable.ArrayBuffer
  import Workspace._

  def solve(): Unit = {
    val N, K = ni()
    val (from, to) = na2(N - 1, -1)
    val g = packUGraph(N, from, to)

    def dfs(v: Int, p: Int, k: Int): Int = {
      if (k == 0) 1
      else {
        var cnt = 1
        REP(g(v).length) { i =>
          val u = g(v)(i)
          if (u != p) {
            cnt += dfs(u, v, k - 1)
          }
        }
        cnt
      }
    }

    var remain = 0
    if (K % 2 == 0) {
      REP(N) { v =>
        remain = max(remain, dfs(v, -1, K / 2))
      }
    } else {
      REP(N - 1) { i =>
        val v = from(i)
        val u = to(i)
        val r = max(
          dfs(v, u, K / 2) + dfs(u, v, K / 2),
          dfs(u, v, K / 2) + dfs(v, u, K / 2))
        remain = max(remain, r)
      }
    }
    out.println(N - remain)
  }
}

