using namespace std;

vector<vector<int>> E;

int N, K;
int d[2000], d2[2000];

void dfs(int pos, int parent) {
	for (int i = 0; i < E[pos].size(); i++) {
		int nxt = E[pos][i];
		if (nxt == parent)continue;

		d[nxt] = d[pos] + 1;
		dfs(nxt, pos);
	}
}

void dfs2(int pos, int parent) {
	for (int i = 0; i < E[pos].size(); i++) {
		int nxt = E[pos][i];
		if (nxt == parent)continue;

		d2[nxt] = d[pos] + 1;
		dfs(nxt, pos);
	}
}

int main() {
	cin >> N >> K;
	E.resize(N);
	for (int i = 0; i < N - 1; i++) {
		int a, b;
		cin >> a >> b;
		a--, b--;
		E[a].push_back(b);
		E[b].push_back(a);
	}

	int ans = 1145141919;

	for (int i = 0; i < N; i++) {
		if (K % 2 == 0) {
			d[i] = 0;
			dfs(i, -1);
		}
		else {
			for (int j = 0; j < E[i].size(); j++) {
				d[i] = 0;
				dfs(i, -1);
				d2[j] = 0;
				dfs2(E[i][j], -1);
			}
		}

		int cnt = 0;
		for (int j = 0; j < N; j++) {
			if (K % 2 == 0) {
				if (d[j] > K / 2)cnt++;
			}
			else {

				if ((d[j] > (K - 1) / 2) && (d2[j] > (K - 1) / 2))
					cnt++;
			}
		}

		ans = min(ans, cnt);

	}
	cout << ans << endl;
	return 0;
}

