int num_nodes,D,dis[MAXN],res=INT_MAX;
bool vis[MAXN];
vector<int> connections[MAXN];
vector<pii> edges;

inline void init(int rt, int ignore){
	memset(vis,false,sizeof vis);
	queue<int> q;
	q.push(rt);
	vis[rt] = true;
	dis[rt] = 0;
	while(q.size()){
		int node = q.front(); q.pop();
		for(int check:connections[node]){
			if(vis[check] || check == ignore) continue;
			vis[check] = true;
			dis[check] = dis[node]+1;
			q.push(check);
		}
	}
}

int main(){
	scanf("%d %d",&num_nodes,&D);
	for(int i=1; i<num_nodes; i++){
		int a,b; scanf(" %d %d",&a,&b);
		connections[a].pb(b);
		connections[b].pb(a);
		edges.pb(mp(a,b));
	}
	if(D%2 == 0){
		for(int rt=1; rt<=num_nodes; rt++){
			init(rt,-1);
			int cnt = 0;
			for(int i=1; i<=num_nodes; i++)
				if(dis[i] > D/2)
					cnt++;
			res = min(res,cnt);
		}
	}else{
		for(pii check:edges){
			init(check.first,check.second);
			init(check.second,check.first);
			int cnt = 0;
			for(int i=1; i<=num_nodes; i++){
				if(dis[i] > D/2)
					cnt++;
			}
			res = min(res,cnt);
		}
	}
	printf("%d\n",res);
}

