bool mark[N];

void bfs(vector<int> e) {
	for (int i = 0; i < n; i++)
		mark[i] = false;
  	queue<int> q;
  	for (int i = 0; i < e.size(); i++) {
    	mark[e[i]] = true;
      	q.push(e[i]);
      	d[e[i]] = 0;
    }
  	while(q.size()) {
    	int root = q.front();
      	q.pop();
      	for (int i = 0; i < adj[root].size(); i++) {
        	if(!mark[adj[root][i]]) {
            	mark[adj[root][i]] = true;
              	d[adj[root][i]] = d[root] + 1;
           		q.push(adj[root][i]);
            }
        }
    }

}

