      	u[i]--, v[i]--;
      	adj[u[i]].push_back(v[i]);
      	adj[v[i]].push_back(u[i]);
    }
  	int ans = n;
  	if(k % 2 == 0) {
    	for (int i = 0; i < n; i++) {
        	vector<int> e;
          	e.push_back(i);
          	bfs(e);
          	int cnt = 0;
          	for (int j = 0; j < n; j++)
            	if(d[j] > k / 2)
                  cnt++;
         	ans = min(ans, cnt);
        }
    }
  	else {
    	for (int i = 0; i < n - 1; i++) {
        	vector<int> e;
          	e.push_back(v[i]);
