using namespace std;
static const int MAX_N = 2000;
static const int INF = 1 << 30;

int N, K;
int A[MAX_N - 1], B[MAX_N - 1];
vector<int> G[MAX_N];
int dist[MAX_N];

void bfs(int s){
	dist[s] = 0;
	queue<int> qa;
	qa.push(s);
	while(!qa.empty()){
		int v = qa.front(); qa.pop();
		for(int i = 0; i < G[v].size(); i++){
			if(dist[G[v][i]] != INF) continue;
			dist[G[v][i]] = dist[v] + 1;
			qa.push(G[v][i]);
		}
	}
	return ;
}

void bfs2(int s1, int s2){
	dist[s1] = 0;
	queue<int> qa;
	while(!qa.empty()){
		int v = qa.front(); qa.pop();
		for(int i = 0; i < G[v].size(); i++){
			if(G[v][i] == s2 || dist[G[v][i]] != INF) continue;
			dist[G[v][i]] = dist[v] + 1;
			qa.push(G[v][i]);
		}
	}
	dist[s2] = 0;
	qa.push(s2);
	while(!qa.empty()){
		int v = qa.front(); qa.pop();
		for(int i = 0; i < G[v].size(); i++){
			if(G[v][i] == s1 || dist[G[v][i]] != INF) continue;
			dist[G[v][i]] = dist[v] + 1;
			qa.push(G[v][i]);
		}
	}
	return ;
}

int main(){
	cin >> N >> K;
	for(int i = 0; i < N - 1; i++){
		cin >> A[i] >> B[i];
		A[i]--; B[i]--;
		G[A[i]].push_back(B[i]);
		G[B[i]].push_back(A[i]);
	}
	int res = N;
	for(int i = 0; i < N; i++){
		fill(dist, dist + N, INF);
		if(K % 2 == 0) bfs(i);
		else bfs2(A[i], B[i]);
		int cnt = 0;
		for(int j = 0; j < N; j++){
			if(dist[j] > K / 2) cnt++;
		}
		res = min(cnt, res);
	}
	cout << res << endl;
	return 0;
}

