using namespace std;

int main(void) {
    int n,k;
    scanf("%d", &n); scanf("%d", &k);
    vector< vector<int> > graph;
    vector<int> degree(n,0);
    graph.resize(n);
    vector< int > edges_a(n-1), edges_b(n-1);

    for (int i = 0; i<n; i++) {
        graph[i].resize(n);
        for (int j=0; j<n; j++) {
            graph[i][j] = 0;
        }
    }

    for (int i =0; i < n-1; i++) {
        int x,y;
        scanf("%d %d", &x, &y);
        graph[x-1][y-1] = 1; graph[y-1][x-1] = 1;
        edges_a[i] = x-1; edges_b[i] = y-1;
    }

    //答えを探すDFS
    int root, node, num_delete_nodes;
    int ans= n+10;
    vector<int> distance(n,n+10);
    vector<int> visited(n,0);
    queue<int> dfs;
    int num_it;
    if(k%2 == 0) {
        num_it = n;
    } else {
        num_it = n-1;
    }

    for (int i=0; i<num_it; i++) {
        // 初期化　始まり
        num_delete_nodes = 0;
        for (int j=0; j<n; j++) {
            visited[j] = 0;
            distance[j] = n+10;
        }

        if (k%2 == 0) {
            visited[i] = 1;
            dfs.push(i);
            distance[i] = 0;
        } else {
            visited[edges_a[i]] = 1;
            dfs.push(edges_a[i]);
            distance[edges_a[i]] = 0;
            visited[edges_b[i]] = 1;
            dfs.push(edges_b[i]);
            distance[edges_b[i]] = 0;
        }
        // 初期化終わり

        // BFS main loop
        while(!dfs.empty()) {
            node = dfs.front();
            dfs.pop();
            for (int j=0; j<n; j++) {
                if(graph[node][j] == 1) {
                    if(visited[j] == 0) {
                        visited[j] = 1;
                        dfs.push(j);
                        distance[j] = distance[node]+1;
                    }
                }
            }
        }

        for (int j=0; j<n; j++) {
            if (distance[j] > (k/2) ) {
                num_delete_nodes++;
            }
        }
        //printf("distance: %d\n",num_delete_nodes);
        if (ans >= num_delete_nodes) {
            ans = num_delete_nodes;
        }
    }
    printf("%d\n", ans);
    return 0;
}

