vector<vector<int>> G;
int N, K;

int MAX = 0;

int f(int idx, int par, int k) {
    if (k <= 0)
        return 0;
    int cnt = 1;
    if (k > 1) {
        for (auto& nxt : G[idx]) {
            if (nxt == par)
                continue;
            cnt += f(nxt, idx, k - 1);
        }
    } else {
        chmax(MAX, (int)(G[idx].size() - 1));
    }
    return cnt;
}

void solve() {
    int ans = INF;
    K++;
    if (K == 2) {
        cout << N - 2 << endl;
        return;
    }
    for (int i = 0; i < N; i++) {
        MAX = 0;
        int tmp = 0;

        if (G[i].size() >= 2) {
            tmp += f(i, -1, (K + 1) / 2);
            if (K % 2 == 0) {
                tmp += MAX;
            }
        } else {
            tmp += f(i, -1, K);
        }
        chmin(ans, N - tmp);
    }
    cout << ans << endl;
}

