		ll a, b;
		cin >> a >> b;
		a--;b--;
		REP(i, n){
			dik[i].add_edge(a, b, 1);
			dik[i].add_edge(b, a, 1);
		}
	}

	ll mx = 0;
	REP(i, n){
		dik[i].run(i);
		REP(j, n){
			ll t = dik[i].get_distance(j);
			if(t != INF){
				mx = max(mx, dik[i].get_distance(j));
			}
		}
	}

	cout << max(0LL, mx - k) << endl;
}

