int N, K;
Vec< Vec< int > > adj;

pii dfs(int v, int p, int d) {
	pii res(1, (d > K ? 1 : 0));

	for (int u : adj[v]) {
		if (u == p) continue;
		pii p = dfs(u, v, d + 1);
		res.first += p.first;
		res.second += p.second;
	}

	return res;
}

void solve() {
	int ans = iINF;

	for_(v,0,N) {
		Vec< int > cn, kn;

		for (int u : adj[v]) {
			pii p = dfs(u, v, 1);
			cn.push_back(p.first);
			kn.push_back(p.second);
		}

		int sum_cn = accumulate(allof(cn), int());
		int m = adj[v].size();
		for_(i,0,m) {
			int del = kn[i] + (sum_cn - cn[i]);
			minUpdate(ans, del);
		}
	}

	cout << ans << endl;
}

