typedef pair<int, int> pii;
const int INF = 1l << 60;
#define u_b upper_bound
#define l_b lower_bound

int N, K;
vector<int> G[2020];
bool deleted[2020];

//return length,vertex
pii farthest(int p, int v) {
    if (deleted[v])return pii(-1, -1);
    pii res = pii(0, v);
    for (int c:G[v]) {
        if (c == p)continue;
        pii tmp = farthest(v, c);
        if (tmp.first == -1)continue;
        tmp.first += 1;
        if (tmp.first > res.first)res = tmp;
    }
    return res;
}

signed main() {
    cin >> N >> K;
    rep(i, N - 1) {
        int a, b;
        cin >> a >> b;
        --a;
        --b;
        G[a].push_back(b);
        G[b].push_back(a);
    }
    int root = 0;
    pii p0 = farthest(-1, root);
    int u = p0.first;
    int ans = 0;
    for (;;) {
        pii p = farthest(-1, u);
        if (p.first <= K)break;
        ans++;
        int v = p.second;
        deleted[v] = true;
        if (v == root) {
            int k = 0;
            while (deleted[++k]) {}
            root = k;
            pii p2 = farthest(-1, root);
            u = p2.first;
        }
    }
    cout << ans << endl;
    return 0;
}

