    cost[root] = 0;
    for (q.push(root); q.size(); q.pop()) {
      int curr = q.front();
      each (next, g[curr]) {
        if (!cost.count(next)) {
          cost[next] = cost[curr] + 1;
          q.push(next);
        }
      }
    }
    pair<int, int> x = *max_element(
      cost.begin(),
      cost.end(),
