const int MAXN = (int)2e3 + 5;
const int L = 12;

vector<int> adj[MAXN];

int par[L][MAXN];

int h[MAXN];

int n, k;

int ans;

void dfs(int v, int pr) {
	par[0][v] = pr;	

	for (int to : adj[v]) {
		if (to == pr) {
			continue;
		}

		h[to] = h[v] + 1;
		dfs(to, v);
	}
}

int getLca(int a, int b) {
	if (h[a] < h[b]) {
		swap(a, b);
	}

	int diff = h[a] - h[b];

	for (int i = 0; i < L; ++i) {
		if (diff & (1 << i)) {
			 a = par[i][a];
		}
	}

	if (a == b) {
		return a;
	}

	for (int i = L - 1; i >= 0; --i) {
		if (par[i][a] != par[i][b]) {
			a = par[i][a];
			b = par[i][b];
		}
	}

	return par[0][a];
}

int dist(int u, int v) {
	return h[u] + h[v] - 2 * h[getLca(u, v)];
}

void solve() {
	scanf("%d %d", &n, &k);

	for (int i = 1, u, v; i < n; ++i) {
		scanf("%d %d", &u, &v);
		adj[u].pb(v);
		adj[v].pb(u);		
	}

	dfs(1, 1);

	for (int i = 1; i < L; ++i) {
		for (int j = 1; j <= n; ++j) {
			par[i][j] = par[i - 1][par[i - 1][j]];
		}
	}

	ans = n - 1;

	for (int a = 1; a <= n; ++a) {
		for (int b = a + 1; b <= n; ++b) {
			int d = dist(a, b);

			if (d > k) {
				continue;
			}

			int cur = 0;

			for (int v = 1; v <= n; ++v) {
				if (max(dist(v, a), dist(v, b)) > d) {
					++cur;
				}
			}

			ans = min(ans, cur);
		}	
	}

	printf("%d\n", ans);
}

int main() {
    int tt = 1;

    while (tt--) {
        solve();
    }

    return 0;
}

