using ll = long long;

const int inf = 1 << 29;

struct state {
    int pos, dist;
    state() {}
    ~state() {}
    state(int pos, int dist): pos(pos), dist(dist) {}
};

int N, K;

vector<vector<int>> graph;
vector<int> active, dists;

int bfs(int v) {
    queue<state> que;
    fill(begin(dists), end(dists), inf);
    dists[v] = 0;
    que.emplace(v, 0);

    int ret = 0;
    while (!que.empty()) {
        state st = que.front(); que.pop();
        ret = st.dist;
        for (int w: graph[st.pos]) {
            if (!active[w]) continue;
            const int ndist = st.dist + 1;
            if (dists[w] > ndist) {
                dists[w] = ndist;
                que.emplace(w, ndist);
            }
        }
    }
    return ret;
}

int main() {
    cin.tie(0); ios::sync_with_stdio(false);
    cin >> N >> K;
    graph.resize(N);
    active.resize(N); fill(begin(active), end(active), 1);
    dists.resize(N);

    for (int j = 0; j < N-1; ++j) {
        int a, b; cin >> a >> b; --a; --b;
        graph[a].push_back(b);
        graph[b].push_back(a);
    }

    int max_dist = bfs(0), idx = 0;
    int ans = 0;

    for (int k = max_dist; k > K; --k) {
        max_dist = bfs(idx);
        int idx1, count1 = 0, count2 = 0;
        for (int j = 0; j < N; ++j) if (dists[j] == max_dist) {
            idx1 = j;
        }

        max_dist = bfs(idx1);
        for (int j = 0; j < N; ++j) if (dists[j] == max_dist) {
            idx = j;
        }

        bfs(idx);
        for (int j = 0; j < N; ++j) if (dists[j] == max_dist) {
            ++count1;
        }

        bfs(idx1);
        for (int j = 0; j < N; ++j) if (dists[j] == max_dist) {
            ++count2;
        }

        if (count1 < count2) {
            bfs(idx);
            for (int j = 0; j < N; ++j) if (active[j] && dists[j] == max_dist) {
                active[j] = 0;
                ++ans;
            }
        } else {
            for (int j = 0; j < N; ++j) if (active[j] && dists[j] == max_dist) {
                active[j] = 0;
                ++ans;
            }
            idx = idx1;
        }
    }

    cout << ans << endl;



    return 0;
}

