int dp[maxn][maxn];
int pref_min[maxn][maxn];
int sz[maxn];
vector < int > g[maxn];

void dfs(int v, int p) {
    sz[v] = 1;
    int child = 0;
    for (auto u : g[v]) {
        if (u == p) continue;
        dfs(u, v);
        child++;
        sz[v] += sz[u];
    }
    dp[v][0] = sz[v];
    if (child == 0) {
        dp[v][1] = 0;
    }
    for (int h = 1; h <= k + 1; ++h) {
        int cur = min(h - 1, k + 1 - h), sum = 0;
        for (auto u : g[v]) {
            if (u == p) continue;
            sum += pref_min[u][cur];
        }
        for (auto u : g[v]) {
            if (u == p) continue;
            dp[v][h] = min(dp[v][h], sum - pref_min[u][cur] + dp[u][h - 1]);
        }
        ans = min(ans, dp[v][h] + n - sz[v]);
    }
    pref_min[v][0] = dp[v][0];
    for (int i = 1; i <= k + 1; ++i) pref_min[v][i] = min(pref_min[v][i - 1], dp[v][i]);
}

