int main()
{
	int n, k;
	vector<vector<int>> g;

	scanf("%d%d", &n, &k);
	g.resize(n);
	for(int i = 0; i < n - 1; ++i) {
		int a, b;
		scanf("%d%d", &a, &b);
		a -= 1; b -= 1;
		g[a].push_back(b);
		g[b].push_back(a);
	}

	bool odd = (k & 1);
	int ans = n;
	vector<bool> visited(n);
	queue<pair<int,int>> q;

	for(int root = 0; root < n; ++root) {

		fill(visited.begin(), visited.end(), false);
		q.push({root, 0});

		while(!q.empty()) {

			int v = q.front().first;
			int d = q.front().second;
			q.pop();

			if(visited[v])
				continue;
			visited[v] = true;

			if(d + 1 > k / 2)
				continue;

			for(auto w : g[v])
				q.push({w, d + 1});
		}

		int count = 0;

		for(int i = 0; i < n; ++i)
			count += visited[i];

		if(odd && count < n)
			count += 1;

		ans = min(ans, n - count);
	}

	printf("%d\n", ans);

	return 0;
}

