inline void bfs()
{
	for(int k=0;k<topQ;k++)
	{
		int v=q[k];
		for(int u : g[v])
		{
			int w=dist[v]+2;
			if(dist[u]<=w)
				continue;
			dist[u]=w;
			q[topQ++]=u;
		}
	}
	return;
}
int solvedian()
{
	for(int i=0;i<n;i++)
		dist[i]=INF;
	dist[v]=0;
