	bfs();
	int res=0;
	for(int i=0;i<n;i++)
		if(dist[i]>k)
			res++;
	return res;
}
int solvebian()
{
	for(int i=0;i<n;i++)
		dist[i]=INF;
	dist[v]=dist[u]=1;
	topQ=0;
	q[topQ++]=v;
	q[topQ++]=u;
	bfs();
	int res=0;
	for(int i=0;i<n;i++)
		if(dist[i]>k)
			res++;
	return res;
}
