void addedge(int from, int to) {
    edge[tot].from = from;
    edge[tot].to = to;
    edge[tot].next = head[from];
    head[from] = tot++;
}

void dfs(int from, int to, int k) {
    tmp++;
    /**
     * k代表还有几条边没走,如果等于0说明边走完了
     * 但是来到最后这个点,点还是要++的
     */
    if (k == 0) return;
    for (int i = head[from]; i != -1; i = edge[i].next) {
        if (edge[i].to != to) {
            dfs(edge[i].to, from, k - 1);
        }
    }
}

