        for (int i = 0; i < tot; i++) {
            tmp = 0;
            dfs(edge[i].from, edge[i].to, k / 2);
            dfs(edge[i].to, edge[i].from, k / 2);
            ans = max(tmp, ans);
        }
    } else {
