signed main()
{
    int n = in_<int>();
    int k = in_<int>();
    REP(i, n - 1){
        int a = in_<int>(), b = in_<int>();
        edge[a].push_back(b);
        edge[b].push_back(a);
    }

    FOR(i, 1, n + 1){
        queue<pii> que;
        for (que.push(pii(i, 0)); sz(que); ){
            pii p = que.front(); que.pop();
            if (visited[i][p.fst]) continue;
            visited[i][p.fst] = true;
            d[i][p.fst] = p.sec;
            for (int j : edge[p.fst]) que.push(pii(j, p.sec + 1));
        }
    }

    set<int> needless;
    FOR(i, 1, n + 1){
        FOR(j, 1, n + 1) if (k < d[i][j]) needless.insert(j);
    }
    // for (auto i : needless) printf(" %d", i);
    // puts("");
    print(sz(needless) / 2);

    return 0;
}

