void dfs(int v,int p,int x,int& dx,int y,int& dy,int d){
	if(d<=x)
		dx++;
	if(d==y)
		dy++;
	for(auto c:tree[v])
		if(c!=p)
			dfs(c,v,x,dx,y,dy,d+1);
}

int Calc(int c,int x,int y){
	int res=1;
	int ad=0;
	for(auto v:tree[c]){
		int w=0;
		dfs(v,c,x,res,y,w,1);
		ad=max(ad,w);
	}
	return res+ad;
}

