ii dfs(int v, int depth){
	ii ans(0,0);

	if(depth <= k/2) ans.first++;
	else if((k%2) && depth <= (k+1)/2) ans.second++; 
	else return ans;

	vis[v] = true;
	REP(i, g[v].size()){
		if(!vis[g[v][i]]){
			ii x = dfs(g[v][i], depth+1);
			ans.first += x.first;
			ans.second += x.second;
		}
	}
	return ans;
}

int main(){
	while(cin >> n >> k){
		int u, v;
		REP(i, n) g[i].clear();
		REP(i, n-1){
			cin >> u >> v;
			g[u].push_back(v);
			g[v].push_back(u);
		}
		int ans = 0;
		REPP(i, 1, n+1){
			vis.reset();
			int tot = 1, gex = 0;
			vis[i] = true;
			REP(j, g[i].size()){
				ii x = dfs(g[i][j], 1);
				tot += x.first; 
				gex = max(gex, x.second);
			}
			tot += gex;
			ans = max(ans, tot);
		}
		ans = n-ans;
		cout << ans << endl;
	}
	return 0;
}

