int N, K;
vector<int> adj[2001];
int sz[2001];
int dp[2001][2001];
int ndp[2001][2001];

void dfs(int u, int p)
{
    sz[u]=1;
    dp[u][0]=1;
    ndp[u][0]=1;
    for(auto& v: adj[u]) if(v!=p)
    {
        dfs(v, u);
        for(int i=0; i<sz[u]; i++)
            for(int j=0; j<sz[v] && i+j+1<=K; j++)
                ndp[u][max(i, j+1)]=max(ndp[u][max(i, j+1)], dp[u][i]+dp[v][j]);
        sz[u]+=sz[v];
        for(int i=0; i<sz[u]; i++)
            dp[u][i]=ndp[u][i];
    }
}

