int read(){
	int num = 0, flag = 1; char c = getchar();
	for(; c < '0' || c > '9'; c = getchar())
		if(c == '-') flag = 0;
	for(; c >= '0' && c <= '9'; c = getchar())
		num = (num<<3)+(num<<1)+c-48;
	return flag? num: -num;
}
void make_line(int x, int y){
	l[++lcnt].y = y; l[lcnt].next = fi[x]; fi[x] = lcnt;
}

void init(){
	n = read(); k = read();
	rep(i, 1, n-1){
		int x = read(), y = read();
		make_line(x, y); make_line(y, x);
	}
}

void get_dis(int x, int f){
	dis[x] = dis[f]+1; fa[x] = f;
	repl(i, x) if(l[i].y != f)
		get_dis(l[i].y, x);
}

int get_ma(int x, int fa, int dis, int ok){
	f[x] = 1;
	if(dis == ok) return f[x];
	repl(i, x){
		int v = l[i].y;
		if(v == fa || flag[v]) continue;
		get_ma(v, x, dis+1, ok);
		f[x] += f[v];
	}
	return f[x];
}

void work(){
	int ans = n, ff = 0;
	rep(i, 1, n){
		get_dis(i, 0);
		rep(j, 1, n) if(dis[j] == k+1){
			ff = 1; pcnt = 0;
			for(int x = j; x != i; x = fa[x])
				p[++pcnt] = x, flag[x] = 1;
			p[++pcnt] = i; flag[i] = 1;
			int cnt = 0;
			rep(j, 1, pcnt)
				cnt += get_ma(p[j], 0, 0, min(j-1, pcnt-j));
			ans = min(ans, n-cnt);
			rep(j, 1, pcnt) flag[p[i]] = 0;
		}
	}
	printf("%d\n", ff? ans: 0);
}

