int solve(int n){
    int res=1<<30;
    for(auto u:G[n]){
        for(int i=1;i<=N;i++)node[i]=false;
        node[n]=true;
        if(K%2)node[u]=true,dfs(u,0);
        dfs(n,0);
        int sum=0;
        for(int i=1;i<=N;i++)if(!node[i])sum++;
        res=std::min(res,sum);
    }
