#include <bits/stdc++.h>
using namespace std;

typedef pair<int, int> T;
int N, K;
vector<T> G[2010];

int dfs(int v, int p){
  int s = 1;
  for(int i = 0; i < G[v].size(); i++){
    int u = G[v][i].first;
    if( u == p ) continue;
    G[v][i].second = dfs( u, v );
    s += G[v][i].second;
  }
  return s;
}

bool used[2000];
int solve(int v){
  int ret = N;
  for(int i = 0; i < G[v].size(); i++){
    fill(used, used + N, false);
    int p = G[v][i].first;
    int t = G[v][i].second;

    queue<T> Q;
    Q.push( T( v, 0 ) );
    used[v] = true;
    if( G[v].size() == 1 ){
      t = 0;
    }else{
      used[ p ] = true;
    }
    while( !Q.empty() ){
      int u = Q.front().first;
      int d = Q.front().second; Q.pop();
      if( d == K ){
	for(int j = 0; j < G[u].size(); j++){
	  if( used[ G[u][j].first ] ) continue;
	  t += G[u][j].second;
	}
      }else{
	for(int j = 0; j < G[u].size(); j++){
	  if( used[ G[u][j].first ] ) continue;
	  Q.push( T(G[u][j].first, d + 1 ) );
	  used[ G[u][j].first ] = true;
	}
      }
    }
    ret = min(ret, t);
  }
  return ret;
}

