#include <bits/stdc++.h>
using namespace std;

vector<int> edg[2005];
vector<int> ch[2005];
int cac[2005][2005];
int n, k, ans;

void dfs(int at, int par=-1)
{
	for (int u: edg[at]) if (u != par)
	{
		ch[at].push_back(u);
		dfs(u, at);
	}
}

int slv(int at, int far)
{
	if (cac[at][far]) return cac[at][far];
	if (far == 0) return cac[at][far]=1;
	if (ch[at].size() >= 1) for (int u: ch[at])
		cac[at][far] = max(cac[at][far], slv(u, far-1));
	if (ch[at].size() >= 2) for (int a = 0;a < far;a++)
	{
		int b = min(far, k-a-1)-1;
		if (b >= 0)
		{
			int t1 = 0, w1 = -1, t2 = 0;
			for (int u: ch[at])
			{
				int alt = slv(u, b);
				if (alt > t1)
				{
					t2 = t1;
					t1 = alt; w1 = u;
				} else if (alt > t2)
					t2 = alt;
			}
			for (int u: ch[at])
			{
				int alt = slv(u, a);
				if (u == w1) alt += t2;
				else alt += t1;
				if (alt > cac[at][far]) cac[at][far] = alt;
			}
		}
	}
	if (ch[at].size() >= 3) for (int giv = 0;giv < far;giv++)
	{
		if (giv+giv > far) break;
		int tot = 0;
		for (int u: ch[at]) tot += slv(u, giv);
		int here = min(far, k-giv-1)-1;
		if (here >= 0) for (int u: ch[at])
		{
			int alt = tot;
			alt -= slv(u, giv);
			alt += slv(u, here);
			cac[at][far] = max(cac[at][far], alt);
		}
	}
	return ++cac[at][far];
}

int main()
{
	scanf("%d%d", &n, &k);
	for (int i = 1;i < n;i++)
	{
		int a, b; scanf("%d%d", &a, &b);
		--a, --b;
		edg[a].push_back(b);
		edg[b].push_back(a);
	}
	dfs(0);
	for (int i = 0;i < n;i++)
		ans = max(ans, slv(i, k));
	printf("%d\n", n-ans);
	return 0;
}

