void bfs(int x)
{
	int visit[n];
	fill(visit,visit+n,0);
	int t=x;
	queue<pair<int,int> >que;
	que.push(make_pair(t,0));
	while(!que.empty())
	{
		int nx=que.front().first;
		int s=que.front().second;
		que.pop();
		for(int i=0;i<vec[nx].size();i++)
		{
			if(visit[vec[nx][i]]) continue;
			visit[vec[nx][i]]=true;
			dist[t][vec[nx][i]]=s+1;
			que.push(make_pair(vec[nx][i],s+1));
		}
	}
}

