using namespace std;

vector<vector<int> > E;

int countChild(int n, int d, int p){
    int ret = 1;
    if(d > 0){
        FORALL(i,E[n]){
            if(*i == p) continue;
            ret += countChild(*i, d-1, n);
        }
    }
    return ret;
}

int main(){
    int N, K;
    cin >> N >> K;
    E = vector<vector<int> >(N);
    REP(i,N-1){
        int A, B;
        cin >> A >> B;
        A--; B--;
        E[A].PB(B);
        E[B].PB(A);
    }
    int ret = N;
    if(K % 2 == 0){
        REP(i,N){
            int tret = N - countChild(i, K/2, -1);
            ret = min(ret, tret);
        }
    }else{
        REP(i,N){
            FORALL(j,E[i]){
                if(i > *j) continue;
                int tret = N - countChild(i, K/2, *j) - countChild(*j, K/2, i);
                ret = min(ret, tret);
            }
        }
    }
    cout << ret << endl;
}

