unordered_set<int> taboo_nodes;
int N, K;
int root;
int dist[MAX_N];
void dfs(int pos) {
  int res = 0;
  for (const int next : edges[pos]) {
    if (taboo_nodes.count(next) > 0)
      continue;
    if (dist[next] != INF)
      continue;
    dist[next] = dist[pos] + 1;
    dfs(next);
  }
}
void fill_dist_inf() {
  for (int i = 0; i < N; i++) {
    dist[i] = INF;
  }
}
bool visited[MAX_N];
bool get_path(int pos, int tar, vector<int> &path) {
  path.push_back(pos);
  visited[pos] = true;
  if (pos == tar) {
    return true;
  }
  for (const int next : edges[pos]) {
    if (taboo_nodes.count(next) > 0)
      continue;
    if (visited[next])
      continue;
    if (get_path(next, tar, path)) {
      return true;
    }
  }
  path.pop_back();
  return false;
}
int main() {
  root = 0;
  memset(deg, 0, sizeof(deg));
  scanf("%d %d\n", &N, &K);
  for (int i = 0; i < N - 1; i++) {
    int a, b;
    scanf("%d %d", &a, &b);
    a--, b--;
    deg[a]++;
    deg[b]++;
    edges[a].push_back(b);
    edges[b].push_back(a);
  }

  auto diameter = [&]() {
    for (int i = 0; i < N; i++) {
      if (taboo_nodes.count(i) == 0) {
        root = i;
        break;
      }
    }
    fill_dist_inf();
    dist[root] = 0;
    dfs(root);
    int left = root;
    for (int i = 0; i < N; i++) {
      if (taboo_nodes.count(i) > 0)
        continue;
      if (dist[left] < dist[i]) {
        left = i;
      }
    }
    fill_dist_inf();
    dist[left] = 0;
    dfs(left);
    int right = root;
    for (int i = 0; i < N; i++) {
      if (taboo_nodes.count(i) > 0)
        continue;
      if (dist[right] < dist[i]) {
        right = i;
      }
    }
    return mt(left, right, dist[right]);
  };
  while (true) {
    auto val = diameter();
    int left, right, len;
    tie(left, right, len) = val;
    if (len <= K)
      break;
    memset(visited, false, sizeof(visited));
    vector<int> path;
    get_path(left, right, path);

    unordered_set<int> path_nodes;

    for (const auto &val : path) {
      path_nodes.insert(val);
      // cerr << val << " ";
    }
    // cerr << endl;
    int par_left, par_right;

    par_left = path[1];
    par_right = path[path.size() - 2];
    int left_cnt,right_cnt;
    left_cnt = right_cnt = 0;
    for (const int &node : edges[par_left]) {
      if (taboo_nodes.count(node) == 0 && deg[node] == 1 &&
	  (path_nodes.count(node) == 0 || node == left)) {
	left_cnt++;
      }
    }
    for (const int &node : edges[par_right]) {
      if (taboo_nodes.count(node) == 0 && deg[node] == 1 &&
	  (path_nodes.count(node) == 0 || node == right)) {
	right_cnt++;
      }
    }
    if (left_cnt <= right_cnt){
      for (const int &node : edges[par_left]) {
	if (taboo_nodes.count(node) == 0 && deg[node] == 1 &&
	    (path_nodes.count(node) == 0 || node == left)) {
	  taboo_nodes.insert(node);
	  deg[par_left]--;
	  deg[node]--;
	}
      }
    }else{
      for (const int &node : edges[par_right]) {
	if (taboo_nodes.count(node) == 0 && deg[node] == 1 &&
	    (path_nodes.count(node) == 0 || node == right)) {
	  taboo_nodes.insert(node);
	  deg[par_right]--;
	  deg[node]--;
	}
      }
    }
  }
  // cerr << left << " " << right << " " << dist[right] << endl;
  cout << taboo_nodes.size() << endl;
  return 0;
}

