    priority_queue<Node> q;
    q.push({src,0});
    vector<ll> res(n,INF);
    while(q.size()){
        Node n = q.top(); q.pop();
        if(res[n.pos] == INF)   res[n.pos] = n.cost;
        else                    continue;

        for(auto e : g[n.pos]){
