      cnt[u][d + 1] += cnt[to][d];
      ++d;
    }
  }
  cnt[u][0] = 1;

  sum[u][0] = 1;
  for (int d = 1; d < LIM; ++d)
    sum[u][d] = sum[u][d - 1] + cnt[u][d];
