    int d = 0;
    while (cnt[to][d]) {
      int dup = k - d - 1;
      if (dup >= 0)
        ans = max(ans, sum[to][d] + 1);
      --dup;
      if (dup >= 0)
        ans = max(ans, sum[to][d] + 1 + up[u][dup]);
      ++d;
    }
