vector<int> edges[2000];
pint visit(int p, int v) {
    pint r(0, v);
    for(int nv : edges[v]) if(nv != p) {
        pint t = visit(v, nv);
        t.first += 1;
        if(r.first < t.first) r = t;
    }
    return r;
}
int memo[2000];//部分木のサイズ
int dfs(int p, int v) {
    memo[v] = 1;
    for(int k : edges[v]) if(k != p)
      memo[v] += dfs(v, k);
    return memo[v];
}
int parent[2000], depth[2000];

void dfs2(int v, int p, int d) {
    parent[v] = p;
    depth[v] = d;
    for(int nv : edges[v])
      if(nv != p) dfs2(nv, v, d + 1);
}
int main() {
    cin.tie(0); ios::sync_with_stdio(false);
    int N, K; cin >> N >> K;
    rep(_, N - 1) {
        int a, b; cin >> a >> b;
        --a; --b;
        edges[a].push_back(b);
        edges[b].push_back(a);
    }
    pint r = visit(-1, 0), t = visit(-1, r.second);
    int dia = t.first;
    int S = r.second, G = t.second;
    dfs(-1, S);
    memset(parent, 0, sizeof(parent));
    dfs2(S, -1, 0);
    vector<int> sum1, sum2;
    for(int v = G; v != S; v = parent[v])
      sum1.push_back(memo[v]);
    sum1.push_back(memo[S]);
    dfs(-1, G);
    memset(parent, 0, sizeof(parent));
    dfs2(G, -1, 0);
    for(int v = S; v != G; v = parent[v])
      sum2.push_back(memo[v]);
    sum2.push_back(memo[G]);
    int ans = INF;
    rep(i, dia - K) {
        if(i == 0) ans = min(ans, sum2[dia - K - 1]);
        else if(i == dia - K - 1) ans = min(ans, sum1[i]);
        else ans = min(ans, sum1[i] + sum2[dia - K - i]);
    }
    if(ans == INF) ans = 0;
    cout << ans << endl;
}

