int N, K;
vector< int > graph[2000];

pair< int, int > dfs(int idx, int prev)
{ 
  pair< int, int > ret = make_pair(0, idx);
  for(int i = 0; i < graph[idx].size(); i++) {
    if(graph[idx][i] != prev) {
      pair< int, int > cost = dfs(graph[idx][i], idx);
      cost.first++;
      ret = max(ret, cost);
    }
  }
  return(ret);
}
pair< int, int > curr;
int Diameter()
{
  pair< int, int > p = dfs(0, -1);
  pair< int, int > q = dfs(p.second, -1);
  curr = {p.second, q.second};
  return(q.first);
}

void dfs2(vector< int >& dist, int idx, int prev = -1)
{
  for(int to : graph[idx]) {
    if(to == prev) continue;
    dist[to] = dist[idx] + 1;
    dfs2(dist, to, idx);
  }
}

