    */



    int min_deg = getMinDeg();
    bool flg = false;
    for(int i = 0; i < N; i++){
      int deg = (int)degree[i];
      if(deg == min_deg){

        int par = *(t[i].begin());
        if(deg == 1 && degree[par] == 2){
          for(list<int>::iterator it = t[par].begin(); it != t[par].end(); it++){
            if(*it == i){
              t[par].erase(it);
              degree[par]--;
              it--;
            }
          }
          t[i].erase(t[i].begin());
          deled++;
          degree[i]--;
          flg = true;
        }else if(deg == 1 && flg){
          for(list<int>::iterator it = t[par].begin(); it != t[par].end(); it++){
            if(*it == i){
              t[par].erase(it);
              it--;
              degree[par]--;
            }
          }
          t[i].erase(t[i].begin());
          degree[i]--;
          break;
        }
      }
      if(diameter - deled == K) break;
    }
  }
  cout << deled << endl;
}

