typedef pair<li, li> PI;

li n,k;
vector<li> edge[2020];

// @returns {#(depth >=k/2), #(depth >=k/2+1)}
PI dfs(li from, li now, li depth){
	PI res(0,0);
	rep(i,sz(edge[now])){
		li next = edge[now][i];
		if(next==from)continue;
		PI tres=dfs(now,next,depth+1);
		res.F+=tres.F;
		res.S+=tres.S;
	}
	if(depth>k/2+1){
		res.S++;
		res.F++;
	}else if(depth>k/2){
		res.F++;
	}
	return res;
}

li solve(li root){
	vector<PI> pis;
	rep(i,sz(edge[root])){
		li next=edge[root][i];
		pis.pb(dfs(root,next,1));
		//p4(root, next, pis[i].F, pis[i].S);
	}
	// k/2よりでかいの全部削除
	li res=0;
	rep(i,sz(pis)){
		res+=pis[i].F;
	}
	if(k%2>0){
		// ひとつだけ2/k+1までOK
		li minus=0;
		rep(i,sz(pis)){
			minus=max(minus, pis[i].F-pis[i].S);
		}
		res-=minus;
	}
	return res;
}

