void solve1(int x){
	head = tail = 0;
	Q[tail++] = x;

	cnt = 0;
	key = x;

	memset(dep, -1, sizeof(dep));
	dep[x] = 0;

    while(head < tail){
		x = Q[head++];
		if(dep[x] > dep[key]){
			cnt = 1;
			key = x;
		} else if(dep[x] == dep[key]){
			cnt++;
		}
		for(int i=0; i<V[x].size(); i++){
			int j = V[x][i];
			if(!f[j] && dep[j]==-1){
				dep[j] = dep[x] + 1;
				Q[tail++] = j;
			}
		}
    }
}

