                    ++ct;
                }
            }
        }
        swap(p, q);
    }
    if (s < 0)return 0;
    else return ct;
}

int dp(int x, int s) {
    vis[x] = 1;
    int ct = 0;
    int tot = 0;
    for (int i = 0; i < v[x].size(); ++i) {
        vv.clear();
        int a1 = bfs(v[x][i], s - 1, 1);
        for (auto j:vv) {
            vis[j] = 0;
        }
        int a2 = bfs(v[x][i], s, 0);
        tot = max(tot, a2 - a1);
        ct += a1;
    }
    return ct + tot + 1;
}

