using namespace std;

#define MAX_N 2005

int N, K;

vector<int> Edge[MAX_N];

int used[MAX_N];
void bfs(int pos, int pre, vector<int> &S){

  typedef pair<int, int> II;
  memset(used, -1, sizeof(used));
  queue<II> que;
  que.push(II(pos, K-1));
  used[pre] = K; used[pos] = K-1;

  while(que.size()){

    II p = que.front();
    que.pop();

    int pos = p.first;
    int cnt = p.second;

    if(cnt == 0)
      continue;

    for(int i = 0; i < (int)Edge[pos].size(); i++){
      int next = Edge[pos][i];
      if(used[next] != -1)
	continue;
      used[next] = cnt-1;
      que.push(II(next, cnt-1));
    }

  }

  bool flag = false;
  for(int i = 0; i < N; i++){
    if(used[i] != -1){
      S.push_back(i);
    }
    if(used[i] == 0)
      flag = true;
  }

  if(!flag)
    S.clear();

}

int solve(){

  int ret = INF;

  for(int pos = 0; pos < N; pos++){
    for(int e = 0; e < (int)Edge[pos].size(); e++){
      vector<int> S;
      bfs(Edge[pos][e], pos, S);
      ret = min(ret, N-(int)S.size());
    }
  }

  if(ret == N)
    ret = 0;

  return ret;

}

