const int INF = 1e+9 + 7;
const int MAX_N = 2005;

int N, K;
int ans = INF;

vector<int> edge[MAX_N];
vector<PII> edge_list;
int depth[2005];

void dfs(int cur, int prev, int d) {
	depth[cur] = d;
	for (int i = 0; i < edge[cur].size(); i++) {
		int adj = edge[cur][i];
		if (adj == prev) continue;
		dfs(adj, cur, d + 1);
	}
}

int calc(int t) {
	int res = 0;
	for (int i = 0; i < N; i++) {
		if (depth[i] > t) {
			res++;
		}
	}
	return res;
}

void solve() {
	if (K % 2 == 0) {
		for (int i = 0; i < N; i++) {
			memset(depth, -1, sizeof(depth));
			dfs(i, -1, 0);
			ans = min(ans, calc(K / 2));
		}
	} else {
		for (int i = 0; i < edge_list.size(); i++) {
			memset(depth, -1, sizeof(depth));
			int u = edge_list[i].first;
			int v = edge_list[i].second;
			dfs(u, v, 0);
			dfs(v, u, 0);
			ans = min(ans, calc((K - 1) / 2));
		}
	}
	cout << ans << endl;
}

