{
	c++;V[c]=v,nxt[c]=Adj[u];Adj[u]=c;
}
int siz[MAXN],mx[MAXN];
void FindRoot(int u,int p)
{
	siz[u]=1;
	for(int i=Adj[u];i;i=nxt[i])
		if(V[i]!=p)
		{
			FindRoot(V[i],u);
			siz[u]+=siz[V[i]];
			mx[u]=max(mx[u],siz[V[i]]);
		}
	mx[u]=max(mx[u],n-siz[u]);
}
void dfs(int u,int p,int dep)
{
	cnt[dep]++;
	if(dep==k) return;
	for(int i=Adj[u];i;i=nxt[i])
		if(V[i]!=p)
			dfs(V[i],u,dep+1);
}
