void add(vector<vector<int> >& C, vector<vector<int> >& D, vector<bool>& flag, int x, int depth, int K){
  if(flag[x]) return;
  if(depth > K) return;

  D[depth].push_back(x);
  flag[x] = true;

  int num_connect = C[x].size();
  for(int i=0; i<num_connect; ++i){
    add(C, D, flag, C[x][i], depth+1, K);
  }

  return;
};

