void bfs(int start){
  queue<int> q;
  q.push(start);
  searched[start] = 1;
  int count=1;
  for(int i=0;i<K/2;i++){
    int l=q.size();
    for(int j=0;j<l;j++){
      int tmp = q.front();
      q.pop();
      int t=v[tmp].size();
      for(int k=0;k<t;k++){
        if(searched[v[tmp][k]] == 0){
          q.push(v[tmp][k]);
          searched[v[tmp][k]] = 1;
          count++;
        }
      }
    }
  }
  if(K%2 != 0){
    int m = 0;
    while(!q.empty()){
      int tmp = q.front();
      q.pop();
      if(v[tmp].size() -1 > m){
        m = v[tmp].size() -1;
      }
    }
    count += m;
  }
  if(N-count < ans) ans = N-count;

}

