multiset <int> st[N];
int n, k;

void dfs(int v) {
    st[v].insert(0);

    set <pii> s;
    for (int i = 0; i < g[v].size(); i++) {
        int to = g[v][i];
        if (!us[to]) {
            us[to] = true;
            nm[to] = v;
            dfs(to);
            if (st[to].size()) {
                auto it = st[to].end();
                it--;
                s.insert({*it, to});
            }
        }
    }

    while (s.size() >= 2) {
        auto it = s.end(); it--;
        auto p1 = *it;
        it--;
        auto p2 = *it;

        if (p1.first + p2.first + 2 > k) {
            auto it2 = st[p1.second].end();
            it2--;
            st[p1.second].erase(it2);
            s.erase(p1);
            if (st[p1.second].size()) {
                it2 = st[p1.second].end();
                it2--;
                s.insert({*it2, p1.second});
            }
        } else
            break;
    }

    for (int i = 0; i < g[v].size(); i++) {
        int to = g[v][i];
        if (nm[to] == v) {
            for (auto p : st[to]) {
                if (p < k - 1) {
                    st[v].insert(p + 1);
                }
            }
            st[to].clear();
        }
    }



}

