void dfs(int node,int p,int sum){
    if(del[node])return;
    if(sum > maxi){
        maxi = sum;
        far = node;
    }
    for(int i=0;i<v[node].size();i++){
        int u = v[node][i];
        if(u!=p){
            dfs(u,node,sum+1);
        }
