        if(Dis <= k)break;
        // try 1
        del[currD.a] = 1;
        diam newD = getD();
        target = newD.b;
        Dis = -1;
        dis(newD.a,newD.a,0);
        int comp = Dis;
        del[currD.a] = 0;
        // try 2
        del[currD.b] = 1;
        newD = getD();
        target = newD.b;
