void solve(int u){
	for(int i=0;i<adj[u].size();i++){
		if(!vis[adj[u][i]]){
			vis[adj[u][i]]=true;
			solve(adj[u][i]);
		}
	}
	for(int i=1;i<=k;i++){
		dp[u][i]=1;
	}
	dp[u][0]=0;
	for(int i=1;i<=k;i++){
		if(i<=(k+1)/2){
			for(int j=0;j<adj[u].size();j++){
				dp[u][i]+=dp[adj[u][j]][i-1];
			}
		}
		if(i>(k+1)/2){
				int suma=0;
				for(int h=0;h<adj[u].size();h++){
					suma+=dp[adj[u][h]][k-i];
				}
				for(int h=0;h<adj[u].size();h++){
				if(dp[u][i]<(suma-dp[adj[u][h]][k-i]+dp[adj[u][h]][i-1]+1)){
					dp[u][i]=suma-dp[adj[u][h]][k-i]+dp[adj[u][h]][i-1]+1;
				}	
				}
			if(dp[u][i]<dp[u][i-1]){
				dp[u][i]=dp[u][i-1];
			}
		}
	}
}
