            int tmp = 0;
            while (!q.empty()) {
                int node = q.front(); q.pop();

                //cout << node << " " << dist[node] << endl;

                if (dist[node] > D) tmp++;

                for (int j = 0; j < adjList[node].size(); j++) {
                    int neighbor = adjList[node][j];

                    if (dist[neighbor] == -1) {
                        dist[neighbor] = dist[node] + 1;
                        q.push(neighbor);
                    }
                }
            }

            ans = min(ans, tmp);
        }
