{
	int v,nxt;
	edge(){}
	edge(int vv,int nn)
	{
		v=vv,nxt=nn;
	}
}E[MAXM];
int w[MAXN];
void addedge(int u,int v)
{
	E[++ncnt]=edge(v,w[u]);
	w[u]=ncnt;
}
int dfs1(int u,int f,int dep)
{
	d[u]=dep;
	jl[u]=1;
	int re=u;
	for(int i=w[u];i;i=E[i].nxt)
	{
		int v=E[i].v;
		if(v!=f&&!vis[v])
		{
			int o=dfs1(v,u,dep+1);
			if(d[re]<d[o])
				re=o;
		}
	}
	return re;
}
void dfs2(int u,int f,int dep)
{
	if(d[u]<dep)
	{
		d[u]=dep;
		jl[u]=2;
	}
	else if(d[u]==dep)
	{
		jl[u]=3;
	}
	for(int i=w[u];i;i=E[i].nxt)
	{
		int v=E[i].v;
		if(v!=f&&!vis[v])
		{
			dfs2(v,u,dep+1);
		}
	}
}
