using namespace std;

typedef struct node{
  vector<node *> nexts;
} node;

int count(node *e, node *bef, int length){
  int sum = 1;
  if(length > 0){
    vector<node *>::iterator it;
    for(it = e->nexts.begin(); it != e->nexts.end(); ++it){
      if((*it) != bef){
        sum += count((*it), e, length-1);
      }
    }
  }
  return sum;
}

int main(int argc, char *argv[]){
  int N, K;
  cin >> N >> K;
  int A[N-1];
  int B[N-1];
  node* e = new node[N];
  int i;
  int a, b;
  for(i=0; i<N-1; ++i){
    cin >> a >> b;
    A[i] = a-1;
    B[i] = b-1;
    e[a-1].nexts.push_back(&e[b-1]);
    e[b-1].nexts.push_back(&e[a-1]);
  }
  int ans;
  if(K%2 == 0){
    int ma = 0;
    for(i=0; i<N; ++i){
      ma = max(ma, count(&e[i], NULL, K/2));
    }
    ans = N - ma;
  }else{
    int ma = 0;
    for(i=0; i<N-1; ++i){
      ma = max( ma, count(&e[A[i]], &e[B[i]], (K-1)/2) + count(&e[B[i]], &e[A[i]], (K-1)/2) );
    }
    ans = N - ma;
  }
  cout << ans << endl;
  delete[] e;
  return 0;
}

