using namespace std;

#define MAXN 2222
vector<int> graph[MAXN];

int dfs(int v, int f, int k) {
  if (k == 0) return 0;
  int ans = 1;
  REP(i, graph[v].size()) if (graph[v][i] != f) {
    ans += dfs(graph[v][i], v, k - 1);
  }
  return ans;
}

int main(int argc, char *argv[]) {
  int N, K;
  scanf("%d%d", &N, &K);
  REP(i, N - 1) {
    int a, b;
    scanf("%d%d", &a, &b); a--; b--;
    graph[a].push_back(b);
    graph[b].push_back(a);
  }
  int ans = 0;
  REP(i, N) {
    int best_diff = 0, total = 1;
    REP(j, graph[i].size()) {
      int tmp1 = dfs(graph[i][j], i, K / 2);
      int tmp2 = dfs(graph[i][j], i, (K + 1) / 2);
      total += tmp1;
      best_diff = max(best_diff, tmp2 - tmp1);
    }
    ans = max(ans, total + best_diff);
  }
  printf("%d\n", N - ans);
  return 0;
}

