int main()
{
	scanf("%d%d",&n,&k);
	for (int i=1; i<=n-1; ++i)
	{
		scanf("%d%d",&u,&v);
		add(u,v); add(v,u);
	}
	while (1)
	{
		int maxn=-1,cnt=-1;

		for (int i=1; i<=n; ++i)
		{
			if (vis[i]) continue;
			memset(dis,-1,sizeof(dis));
			dis[i]=0; q.push(i);
			int now_maxn=0,now_cnt=1;

			while (!q.empty())
			{
				int x=q.front(); q.pop();
				for (int j=head[x]; j; j=edge[j].next)
					if (dis[edge[j].to]==-1 && !vis[edge[j].to])
					{
						dis[edge[j].to]=dis[x]+1;
						if (dis[edge[j].to]==now_maxn) ++now_cnt;
						if (dis[edge[j].to]>now_maxn) now_maxn=dis[edge[j].to],now_cnt=1;
						q.push(edge[j].to);
					}
			}

			if (now_maxn>maxn || now_maxn==maxn && now_cnt>cnt) 
				cut=i,maxn=now_maxn,cnt=now_cnt;
		}

		if (maxn<=k) break;
