void bfs(ll init) {
	for (ll x=0;x<n;x++) dist[x]=INF;
	queue<ll> q;
	dist[init]=0;
	q.push(init);
	while(!q.empty()) {
		ll x=q.front();
		q.pop();
		for (auto &w:g[x]) {
			if (valid[w]&&dist[w]==INF) {
				dist[w]=dist[x]+1;
				q.push(w);
			}
		}
	}
}
ll findfar() {
	pair<ll,ll> ans=MP(-1,-1);
	for (ll x=0;x<n;x++) {
		if(dist[x]!=INF)chkmax(ans,MP(dist[x],x));
	}
	return ans.second;
}
