int n, k;
vector<int>G[2005];
vector<P>edge;
int far[2005];
bool flag;
int dfs(int x, int s) {
	for (int i : G[x]) {
		if (far[i] == inf) {
			far[i] = far[x] + 1;
			dfs(i, s);
		}
	}
	if (x == s && !flag) {
		flag = true;
		int ma = 0, index;
		rep(i, n) {
			if (ma < far[i]) {
				ma = far[i]; index = i;
			}
			far[i] = inf;
		}
		far[index] = 0;
		return dfs(index, index);
	}
	else if (x == s) {
		int ma = 0;
		rep(i, n)chmax(ma, far[i]);
		return ma;
	}
	return 0;
}
void dfs2(int x) {
	for (int i : G[x]) {
		if (far[i] == inf) {
			far[i] = far[x] + 1;
			dfs2(i);
		}
	}
}
