int dfs(int x, int left)
{
	seen[x] = true;
	if (left <= 0) return 0;
	int ret = 1;
	for (int i = 0; i < adjList[x].size(); i++)
	{
		int y = adjList[x][i];
		if (seen[y]) continue;
		ret += dfs(y, left-1);
	}
	return ret;
}

