		adjList[b].push_back(a);
	}
	int ans = 0;
	for (int i = 0; i < n; i++)
	{
		int delta = 0, sum = 1;
		for (int j = 0; j < adjList[i].size(); j++)
		{
			int y = adjList[i][j];

			fill(seen, seen + n, false);
			seen[i] = true;
			int a = dfs(y, k / 2);

			fill(seen, seen + n, false);
			seen[i] = true;
			int b = dfs(y, (k+1)/2);
			delta = max(delta, b - a);
			sum += a;
		}
		ans = max(ans, sum + delta);
	}
	cout << n - ans << '\n';
	return 0;
}

