const int N = 2000 + 5, M = N << 1;

int cnt = 0, toit[M], nxt[M], link[N];

void Add(int x, int y) {
	++ cnt; toit[cnt] = y; nxt[cnt] = link[x]; link[x] = cnt;
	++ cnt; toit[cnt] = x; nxt[cnt] = link[y]; link[y] = cnt;
}

int n, k, ans = 0;
bool vis[N] = {true};
int dis[N];

queue <int> Q;

void Solve() {
	int s = 1;
	for (int i = 1; i <= n; ++ i) if (vis[i]) {s = i; break;}
	while (! Q.empty()) Q.pop();
	memset(dis, 255, sizeof(dis));
	Q.push(s); dis[s] = 0;
	while (! Q.empty()) {
		int x = Q.front(); Q.pop();
		for (int i = link[x]; i; i = nxt[i]) {
			int v = toit[i]; if (vis[v] == false || dis[v] != -1) continue;
			dis[v] = dis[x] + 1;
			Q.push(v);
		}
	}
	int t = s;
	for (int i = 1; i <= n; ++ i) if (vis[i] && dis[i] > dis[t]) t = i;
	while (! Q.empty()) Q.pop();
	memset(dis, 255, sizeof(dis));
	Q.push(t); dis[t] = 0;
	while (! Q.empty()) {
		int x = Q.front(); Q.pop();
		for (int i = link[x]; i; i = nxt[i]) {
			int v = toit[i]; if (! vis[v] || dis[v] != -1) continue;
			dis[v] = dis[x] + 1;
			Q.push(v);
		}
	}
	s = t;
	for (int i = 1; i <= n; ++ i) if (vis[i] && dis[i] > dis[s]) s = i;
	if (dis[s] <= k) return;	
	++ ans;
	vis[s] = false;
	Solve();	
}

int main(void) {
	scanf("%d%d", &n, &k);
	for (int i = 1; i < n; ++ i) {
		int x, y; scanf("%d%d", &x, &y); Add(x, y);
	}
	memset(vis, true, sizeof(vis));
	Solve();
	printf("%d\n", ans);
	return 0;
}

