			for(int j=hr[x];j;j=e[j].nex)if(e[j].to!=fa){
				f[x][i]+=f[e[j].to][min(i-1,k-1-i)];maxx=max(maxx,f[e[j].to][i-1]-f[e[j].to][min(i-1,k-1-i)]);
			}
			f[x][i]-=maxx;
		}
		f[x][k]=inf;
		for(int j=hr[x];j;j=e[j].nex)if(e[j].to!=fa){
			f[x][k]=min(f[x][k],siz[x]-siz[e[j].to]+f[e[j].to][k-1]);
		}
		for(int i=1;i<=k;i++) f[x][i]=min(f[x][i],f[x][i-1]);
	}
	siz[x]++;
}
