// Graph template
template <class... Args>
struct Edge
{
  int from, to;
  tuple<Args...> values;
  Edge(int from, int to, Args... values)
      : from(from), to(to), values(values...) {}
};
template <class E>
auto operator<(const E &e, const E &f)
{
  return e.values > f.values;
}

template <class... Args>
class Graph
{
  using Edges = vector<Edge<Args...>>;
  vector<Edges> graph_;

public:
  Graph(int n) : graph_(n) {}
  size_t size() { return graph_.size(); };
  size_t size() const { return graph_.size(); };
  auto &operator[](unsigned int x) { return graph_[x]; }
  const auto &operator[](unsigned int x) const { return graph_[x]; }
  void AddEdge(int s, int t, Args... v) { graph_[s].emplace_back(s, t, v...); }
};

template <typename T>
struct UnionFind
{
  vector<T> data;
  UnionFind(T n) : data(n, -1) {}
  bool unite(T x, T y)
  {
    x = root(x);
    y = root(y);
    if (x != y)
    {
      if (data[y] < data[x])
        swap(x, y);
      data[x] += data[y];
      data[y] = x;
    }
    return x != y;
  }
  T root(T x)
  {
    return data[x] < 0 ? x : data[x] = root(data[x]);
  }
  bool same(T x, T y)
  {
    return root(x) == root(y);
  }
  T size(T x)
  {
    return -data[root(x)];
  }
};

int dfs(int s, const Graph<> &g, int k)
{
  const int n = g.size();
  vector<bool> visited(n, 0);
  int ret = 0;
  int rest = 0;
  queue<pair<int, int>> qu;
  qu.push({s, 0});
  visited[s] = 1;
  UnionFind<int> uf(n);
  while (!qu.empty())
  {
    auto now = qu.front();
    qu.pop();
    if (now.second <= k / 2)
    {
      ret++;
    }
    else
    {
      break;
    }
    vector<int> buf(n, 0);
    for (auto &&e : g[now.first])
    {
      if (visited[e.to])
        continue;
      visited[e.to] = 1;
      qu.push({e.to, now.second + 1});
      if (now.second > 0)
      {
        uf.unite(e.to, e.from);
      }
      if ((k & 1) && now.second + 1 > k / 2)
      {
        buf[uf.root(e.to)]++;
      }
    }
    for (auto x : buf)
    {
      rest = max(x, rest);
    }
  }
  //cout << rest;
  return ret + rest;
}

