const int INF = 1e9;

Graph g;
int n;
int k;

int solve_even() {
    int ans = 1e9;
    for (int i = 0; i < n; i++) {
        int dist[2010];
        fill(dist, dist + n, INF);
        queue<int> q;
        q.push(i);
        dist[i] = 0;
        int vis = 0;
        while (q.size()) {
            int v = q.front();
            q.pop();
            ++vis;
            if (dist[v] == k / 2) continue;
            for (auto &e : g[v]) {
                int d = e.dst;
                if (dist[d] > dist[v] + 1) {
                    q.emplace(d);
                    dist[d] = dist[v] + 1;
                }
            }
        }
        ans = min(ans, n - vis);
    }
    return ans;
}

int rec(int u, int p, int lim) {
    int res = 1;
    if (lim == 0) return res;
    for (auto &e : g[u]) {
        if (e.dst == p) continue;
        res += rec(e.dst, u, lim - 1);
    }
    return res;
}

int solve_odd() {
    int ans = INF;
    for (auto &es : g) {
        for (auto &e : es) {
            int x = rec(e.src, e.dst, k / 2);
            int y = rec(e.dst, e.src, k / 2);
            //assert(x + y == n);
            ans = min(ans, n - (x + y));
        }
    }
    return ans;
}


int main() {
    while (cin >> n) {
        cin >> k;
        g.assign(n, {});
        for (int i = 0; i < n-1; i++) {
            int a, b;
            cin >> a >> b;
            --a; --b;
            g[a].emplace_back(a, b, 1);
            g[b].emplace_back(b, a, 1);
        }
        if (k % 2 == 0) {
            cout << solve_even() << endl;
        } else {
            cout << solve_odd() << endl;
        }
    }
}

