using namespace std;

const int maxn = 4010;
int n,k,head[maxn],to[maxn],nextt[maxn],tot = 1;
int cut[maxn],p,q,maxx,fa[maxn],S[maxn],top,vis[maxn],ans;
int d[maxn],belong[maxn],dist[maxn];

void add(int x,int y)
{
    to[tot] = y;
    nextt[tot] = head[x];
    head[x] = tot++;
}

void dfs1(int u,int faa,int len)
{
    if (len > maxx)
    {
        maxx = len;
        p = u;
    }
    for (int i = head[u]; i; i = nextt[i])
    {
        int v = to[i];
        if (v == faa || cut[v])
            continue;
        dfs1(v,u,len + 1);
    }
}

void dfs2(int u,int faa,int len)
{
    if (len > maxx)
    {
        maxx = len;
        q = u;
    }
    fa[u] = faa;
    for (int i = head[u]; i; i = nextt[i])
    {
        int v = to[i];
        if (v == faa || cut[v])
            continue;
        dfs2(v,u,len + 1);
    }
}

void dfs3(int u,int faa,int len,int from)
{
    belong[u] = from;
    dist[u] = len;
    for (int i = head[u]; i; i = nextt[i])
    {
        int v = to[i];
        if (v == faa)
            continue;
        if (vis[v] || cut[v])
            continue;
        dfs3(v,u,len + 1,from);
    }
}

int main()
{
    scanf("%d%d",&n,&k);
    for (int i = 1; i < n; i++)
    {
        int x,y;
        scanf("%d%d",&x,&y);
        add(x,y);
        add(y,x);
    }
    maxx = 0;
    dfs1(1,0,0);
    maxx = 0;
    dfs2(p,0,0);
    while (maxx > k)
    {
        memset(d,0,sizeof(d));
        memset(dist,0,sizeof(dist));
        memset(vis,0,sizeof(vis));
        memset(belong,0,sizeof(belong));
        top = 0;
        int temp = q;
        while (temp)
        {
            S[++top] = temp;
            d[temp] = top;
            vis[temp] = 1;
            temp = fa[temp];
        }
        int cnt1 = 0,cnt2 = 0;
        for (int i = 1; i <= top; i++)
            dfs3(S[i],0,0,S[i]);
        for (int i = 1; i <= n; i++)
            if (!vis[i] && !cut[i])
            {
                if (dist[i] == d[belong[i]] - 1)
                    cnt2++;
                if (dist[i] == top - d[belong[i]])
                    cnt1++;
            }
        if (cnt1 < cnt2)
            cut[p] = 1;
        else
            cut[q] = 1;
        ans++;
        maxx = 0;
        dfs1(1,0,0);
        maxx = 0;
        dfs2(p,0,0);
    }
    printf("%d\n",ans);

    return 0;
}

