pair<int, int> dfs(vector<vector<int>> &g, vector<char> &u, int k, int i) {
	u[i] = 1;
	if (k == 2) return {1, 0};
	if (k == 3) return {1, g[i].size() - 1};
	int ans = 1, add = 0;
	for (int j : g[i]) if (!u[j]) {
		pair<int, int> p = dfs(g, u, k - 2, j);
		ans += p.fs;
		add += p.sn;
	}
	//cerr << i << ' ' << ans << ' ' << add << '\n';
	return {ans, add};
}

int solve(vector<vector<int>> &g, int k, int i) {
	int ans = 0, add = 0;
	for (int j : g[i]) {
		vector<char> u(g.size(), 0);
		u[i] = 1;
		pair<int, int> loc = dfs(g, u, k, j);
		ans += loc.fs;
		add = max(add, loc.sn);
	}
	return ans + add + 1;
}

