        if (it == ant) continue;
        dfs(it, nod);
        nrf[nod] += nrf[it];
        for (int i=0;i<k;i++){
            DP[nod][i+1] += DP[it][i];
            if (i+i+1 > k){
                dif[nod][i+1] = min(dif[nod][i+1], -DP[it][k-i-1] + DP[it][i]);
            }
        }
    }
    DP[nod][0] = nrf[nod];
    for (int i=1;i<=k;i++){
        if (i+i-1<=k) continue;
        DP[nod][i] = DP[nod][k-i+1] + dif[nod][i];
    }
    if (nrf[nod]==1) DP[nod][1] = 0;
    for (int i=1;i<=k;i++) DP[nod][i] = min(DP[nod][i], DP[nod][i-1]);
    ans = min(ans, DP[nod][k] + n - nrf[nod]);
}

