void dfs(int v, int p = -1){
    dp[v][0] = 1;
    if (v > 0 && g[v].size() == 1){
        forn1(i, maxn) dp[v][i] = 0;
        return;
    }
    vi U;
    for (int u : g[v]){
        if (u != p){
            U.pb(u);
            dfs(u, v);
            dp[v][0] += dp[u][0];
        }
    }
    int m = U.size();
    int u0 = U[0];
    vi f(k + 1);
    forn(i, k + 1){
        forn1(j, m){
            int u = U[j];
            f[i] += dp[u][i];
        }
    }
    forn(maxd, k + 1){
        forn(d0, maxd + 1){
            int d1 = min(k - d0, maxd);
            dp[v][maxd + 1] = min(dp[v][maxd + 1], dp[u0][d0] + f[d1]);
        }
    }
    forn1(i, maxn) dp[v][i] = min(dp[v][i], dp[v][i - 1]);
}

