            while (!q.empty()) {
                int u = q.front();
                q.pop();
                if (d[u] == K / 2) {
                    continue;
                }
                REP(i, g[u].size()) {
                    int to = g[u][i];
                    if (d[to] > d[u] + 1) {
                        d[to] = d[u] + 1;
                        q.push(to);
                    }
                }
            }
            int n_remove = 0;
            REP(i, N) {
                if (d[i] > K / 2) {
                    n_remove++;
                }
            }
            ret = min(ret, n_remove);
        }
    }
    cout << ret << endl;
    return 0;
}

