vector<int> edges[2010], child[2010];
int dp[2010][2010];
int h[2010], siz[2010];
int k;
int dp2[2010][2010];

void dfs(int i, int p){
  h[i] = 1;
  siz[i] = 1;
  for(auto e: edges[i]){
    if(e == p)continue;
    child[i].pb(e);
    dfs(e, i);
    chmax(h[i], h[e] + 1);
    siz[i] += siz[e];
  }
}

void dfs2(int i){
  for(auto e: child[i])dfs2(e);

  dp2[0][0] = 0;
  int curr = 0;
  rep(j, sz(child[i])){
    int e = child[i][j];
    for(int l = 0; l <= max(h[e], curr); l++)dp2[j+1][l] = inf;
    int tcurr = curr;
    for(int l = 0; l <= curr; l++){
      for(int m = 0; m <= h[e]; m++){
        if(l + 1 + m > k)break;
        chmin(dp2[j+1][max(l, m)], dp2[j][l] + dp[e][m]);
        chmax(tcurr, max(l, m));
      }
    }
    curr = tcurr;
  }

  dp[i][0] = siz[i];
  for(int m = 0; m < h[i]; m++){
    dp[i][m+1] = dp2[sz(child[i])][m];
  }
}

