        a--;
        b--;
        g[a].push_back(b);
        g[b].push_back(a);
    }

    int ans = 0;
    for(int v = 0; v < n; v++)
    {
        for(int nx : g[v])
        {
            int tmp = 2;
            queue<int> que;
            que.push(nx);
            vector<int> d(n);
            d[v] = 1;
            d[nx] = 2;
            bool flag = false;
            while(que.size())
