                    {
                        que.push(cand);
                    }
                    else if(d[cand] == k+1)
                    {
                        flag = true;
                    }
                    tmp++;
                }
            }
            if(flag) ans = max(ans, tmp);
        }
    }
    cout << n - ans << endl;
}

