#include<cstdio>
#include<algorithm>
#include<vector>
using namespace std;

int N, K;
const int NMAX = 2222;
vector<int> g0[NMAX];
vector<int> g[NMAX];

int sub[NMAX];
int h[NMAX];
int dp[NMAX][NMAX]; // dp[u][l]: cost of (to-root length = l)

int dfs1(int u, int fa){
	sub[u] = 1;
	h[u] = 0;
	for (int v : g0[u]) if (v != fa){
		g[u].push_back(v);
		sub[u] += dfs1(v, u);
		h[u] = max(h[u], h[v] + 1);
	}
	return sub[u];
}

void dfs2(int u){
	for (int v : g[u]) dfs2(v);
	if (g[u].empty()){
		dp[u][0] = 1; return;
	}

	dp[u][0] = sub[g[u][0]];
	for (int i = 1; i <= K; i++) dp[u][i] = dp[g[u][0]][i - 1];
	for (int i = 1; i < g[u].size(); i++){
		int v = g[u][i];
		vector<int> now(K + 1);
		for (int j = 0; j <= K; j++){
			now[j] = min(
				dp[u][j] + dp[v][min(j, K - j)],
				dp[v][j] + dp[u][min(j, K - j)]);
		}
		for (int j = 0; j <= K; j++)
			dp[u][j] = now[j];
		for (int j = 1; j <= K; j++) dp[u][j] = min(dp[u][j], dp[u][j - 1]);
	}
}

int main(){
	scanf("%d%d", &N, &K);
	for (int i = 1; i < N; i++){
		int a, b; scanf("%d%d", &a, &b);
		g0[a].push_back(b);
		g0[b].push_back(a);
	}

	if (K == 1){
		printf("%d", N - 2);
		return 0;
	}

	dfs1(1, 0);
	dfs2(1);
	printf("%d", dp[1][K]);
}

