vector <int> graph[2010];
int N, K;
bool used[2010];
#define Length(x) (int)(x).size()

int dfs(int v) {
	used[v] = 1;
	int max_dist = 0;
	for (int j = 0; j < Length(graph[v]); ++j) {
		int to = graph[v][j];
		if (!used[to]) 
			max_dist = max(max_dist, dfs(to) + 1);
	}
	return max_dist;
}

void input() {
	scanf ("%d %d", &N, &K);
	for (int i = 0; i < N - 1; ++i) {
		int x, y;
		scanf ("%d %d", &x, &y);
		graph[x].push_back(y);
		graph[y].push_back(x);
	}
}
int len[2010];
void dfs_get(int v, int len_path) {
	used[v] = 1;
	len[v] = len_path;
	for (int j = 0; j < Length(graph[v]); ++j) {
		int to = graph[v][j];
		if (!used[to]) 
			dfs_get(to, len_path + 1);
	}	
}
void solve() {
	int max_dist = -1;
	int StartVertex = -1;
	for (int i = 1; i <= N; ++i) {
		for (int j = 1; j <= N; ++j)
			used[j] = 0;
		int dist = dfs(i);
		// printf ("%d ", dist);
		if (dist > max_dist) {
			max_dist = dist;
			StartVertex = i;
		}
	}
	// printf ("%d\n", StartVertex);
	for (int i = 1; i <= N; ++i)
		used[i] = 0;
	dfs_get(StartVertex, 0);
	int DoggyStyle = 0;
	for (int i = 1; i <= N; ++i) {
		if (len[i] > K) 
			++DoggyStyle;
		// printf ("%d %d\n", i, len[i]);
	}
	printf ("%d\n", DoggyStyle);
}
