int u,v,n,k,ex,ans;
int dfs(int x,int fa,int deep)
{
	int sum=0;
	for(int i=0;i<G[x].size();i++)
	{
		int to=G[x][i];
		if(to==fa)continue;
		sum+=dfs(to,x,deep-1);
	}
	if(deep<=0)sum++;
	return sum;
}
int main()
{
	scanf("%d%d",&n,&k);
	for(int i=1;i<=n-1;i++)
	{
		scanf("%d%d",&u,&v);
		G[u].push_back(v);
		G[v].push_back(u);
	}
