	for(int rt=1;rt<=n;rt++)
	{
		ex=0;
		int sum=0;
		for(int i=0;i<G[rt].size();i++)
		{
			int to=G[rt][i];
			int val=dfs(to,rt,k/2);
			//printf("%d %d %d\n",rt,to,val);
			sum+=val;
			if(k%2)ex=max(ex,val-dfs(to,rt,k/2+1));
		}
		sum-=ex;
		ans=min(sum,ans);
	}
	printf("%d",ans);
}

