#define M 2010
using namespace std;
int n,num,L,R,ans,tot,k;
int dep[M],head[M],vis[M];
struct edge{int next,to;}e[M<<1];
void add(int from,int to) {
	e[++num]=(edge){head[from],to};
	head[from]=num;
}
void dfs(int x,int fa) {
	dep[x]=dep[fa]+1;
	for(int i=head[x];i;i=e[i].next)
		if(e[i].to!=fa&&!vis[e[i].to]) dfs(e[i].to,x);
}
void Get_LR() {
	L=R=0;
	int rt;
	for(int i=1;i<=n;i++)
		if(!vis[i]) rt=i;
	dfs(rt,0);
	for(int i=1;i<=n;i++)
		if(dep[i]>dep[L]) L=i;
	dfs(L,0);
	for(int i=1;i<=n;i++)
		if(dep[i]>dep[R]) R=i;
}
void Get_sum(int x,int fa,int s) {
	dep[x]=dep[fa]+1;
	if(dep[x]==s) tot++;
	for(int i=head[x];i;i=e[i].next)
		if(e[i].to!=fa&&!vis[e[i].to])
			Get_sum(e[i].to,x,s);
}
void Change(int x,int fa,int s) {
	dep[x]=dep[fa]+1;
	if(dep[x]==s) vis[x]=true;
	for(int i=head[x];i;i=e[i].next)
		if(e[i].to!=fa&&!vis[e[i].to])
			Change(e[i].to,x,s);
}
int main() {
	scanf("%d%d",&n,&k);k++;
	for(int i=1,u,v;i<n;i++) {
		scanf("%d%d",&u,&v);
		add(u,v);add(v,u);
	}
	Get_LR();
	while(dep[R]>k) {
		int sl,sr,mx=dep[R];
		tot=0;Get_sum(L,0,mx);sl=tot;
		tot=0;Get_sum(R,0,mx);sr=tot;
		if(sl<sr) ans+=sl,Change(L,0,mx);
		else ans+=sr,Change(R,0,mx);
		Get_LR();
	}
	printf("%d\n",ans);
	return 0;
}

