int n,k;
vi g[2521];

bool used[2521];

int dfs(int p,int d,int lim){
  if(d>lim)return 0;
  int ret = 1;
  REP(i,g[p].size()){
    int to = g[p][i];
    if(used[to])continue;
    used[to] = true;
    ret += dfs(to,d+1,lim);
  }
  return ret;
}

int main(){
  scanf("%d%d",&n,&k);
  REP(i,n-1){
    int a,b;
    scanf("%d%d",&a,&b);
    --a;--b;
    g[a].push_back(b);
    g[b].push_back(a);
  }
  int ans = n-2;
  if(k&1){
    // check edge
    vector<bool> checked(n,false);
    REP(i,n){
      checked[i] = true;
      REP(j,g[i].size()){
        int to = g[i][j];
        if(checked[to])continue;
        int tmp = 0;
        fill(used,used+n,false);
        used[i]=used[to]=true;
        tmp += dfs(i,0,k/2);
        tmp += dfs(to,0,k/2);
        CHMIN(ans,n-tmp);
      }
    }
  }else{
    // check node
    REP(i,n){
      fill(used,used+n,false);
      used[0]=true;
      CHMIN(ans,n-dfs(i,0,k/2));
    }
  }

  printf("%d\n",ans);
  return 0;
}

