#define INF 100000000

using namespace std;
using ull = unsigned long long;
using Graph = vector<vector<int>>;
using P = pair<int, int>;

int N, K;

vector<int> dijikstra(const Graph& g, int s) {
	priority_queue<P, vector<P>, greater<P>> que;
	vector<int> d(N, INF);
	d[s] = 0;
	que.push(P(0, s));

	while (!que.empty()) {
		P p = que.top();
		que.pop();
		int v = p.second;
		if (d[v] < p.first) continue;

		for (const auto& to : g[v]) {
			if (d[to] > d[v] + 1) {
				d[to] = d[v] + 1;
				que.emplace(d[to], to);
			}
		}
	}

	return d;
}

int main()
{
	cin >> N >> K;

	Graph g(N);

	for (int i = 0; i < N - 1; ++i) {
		int A, B;
		cin >> A >> B;
		A--; B--;

		g[A].emplace_back(B);
		g[B].emplace_back(A);
	}

	vector<bool> need(N, true);

	for (int i = 0; i < N; ++i) {
		if (!need[i]) { continue; }

		auto&& d = dijikstra(g, i);

		for (int j = 0; j < N; ++j) {
			if (d[j] > K) {
				need[j] = false;
			}
		}
	}

