vector<bool> alive;

void dfs(int v) {
    for (auto&& nxt : G[v]) {
        if (d[nxt] == -1) {
            d[nxt] = d[v] + 1;
            dfs(nxt);
        }
    }
}

int dfs2(int v, int pre) {
    int ret = 1;
    for (auto&& nxt : G[v]) {
        if (nxt != pre && alive[nxt]) {
            ret += dfs2(nxt, v);
        }
    }
    return ret;
}

int solve(int s) {
    d.clear();
    d.resize(N, -1);
    d[s] = 0;
    dfs(s);

    // cout << s << ": ";
    // rep(i, N) {
    //     cout << d[i] << " ";
    // }
    // cout << endl;

    alive.clear();
    alive.resize(N, true);
    int kill = 0;
    rep(i, N) {
        if (d[i] > K) {
            alive[i] = false;
            kill++;
        }
    }

    int mi = inf;
    int num_alive_child = 0;
    for (auto&& ch : G[s]) {
        if (alive[ch]) {
            num_alive_child++;
            mi = min(mi, dfs2(ch, s));
        }
    }
    if (num_alive_child > 1) {
        kill += mi;
    }
    return kill;
}


