    if (v != p) {
      for (int k = 0; k <= K - 2; ++k) {
        chmax(ans[u][k + 1], 1 + ans[v][k] + sum[min(k, K - k - 2)] - ans[v][min(k, K - k - 2)]);
      }
      chmax(ans[u][K], 1 + ans[v][K - 1]);
    }
  }
  upd(u);
}

