vector<int> edges[2000];
pint visit(int p, int v) {
    pint r(0, v);
    for(int nv : edges[v]) if(nv != p) {
        pint t = visit(v, nv);
        t.first += 1;
        if(r.first < t.first) r = t;
    }
    return r;
}
int memo[2000];//部分木のサイズ
int dfs(int p, int v) {
    memo[v] = 1;
    for(int k : edges[v]) if(k != p)
      memo[v] += dfs(v, k);
    return memo[v];
}
int parent[100000], depth[100000];

void dfs2(int v, int p, int d) {
    parent[d] = p;
    depth[v] = d;
    for(int nv : edges[v])
      if(nv != p) dfs2(nv, v, d + 1);
}
int main() {
