        edges[a].push_back(b);
        edges[b].push_back(a);
    }
    int a = dfs(-1, 0);
    memset(parent, 0, sizeof(parent));
    dfs2(0, -1, 0);
    pint r = visit(-1, 0), t = visit(-1, r.second);
    int dia = t.first;
    int S = r.second, G = t.second;
    int ans = 0;
    while(dia > K) {
        if(memo[S] < memo[G]) swap(S, G);
        int tmp = memo[G];
        G = parent[G];
        memo[G] -= tmp;
        ans += tmp;
        --dia;
    }
    cout << ans << endl;
}

