void remove(int u, int p) {
	dep[u] = 1;
	sz[u] = 1;
	rep(i, edge[u].size()) {
		if (edge[u][i] == p) {
			edge[u].erase(edge[u].begin() + i);
			i--;
		}
		else {
			remove(edge[u][i], u);
			dep[u] = max(dep[u], dep[edge[u][i]] + 1);
			sz[u] += sz[edge[u][i]];
		}
	}
}


