	for (int d = md; d >= 0; d--) {
		cost1[d][0] = 0;
		for (int i = 1; i < m; i++) {
			cost1[d][i] = dp[edge[u][i - 1]][d] + cost1[d][i - 1];
		}
		cost2[d][m - 1] = 0;
		for (int i = m - 2; i >= 0; i--) {
			cost2[d][i] = dp[edge[u][i + 1]][d] + cost1[d][i + 1];
		}
	}
