using namespace std;

pair<int, int> visit(int p, int v, const vector<vector<int>> &g) {
	auto r = make_pair(0, v);
	for (auto e : g[v]) if (e != p) {
		auto t = visit(v, e, g);
		++t.first;
		if (r.first < t.first) {
			r = t;
		}
	}
	return r;
}

int diameter(const vector<vector<int>> &g, pair<int, int> &p) {
	auto r = visit(-1, 0, g);
	auto t = visit(-1, r.second, g);
	p = make_pair(r.second, t.second);
	return t.first;
}

