const int N = 2e3 + 5;
int n, k;
int f[N], cnt = 0;
int nnext[N << 1], v[N << 1];

inline void add(int a, int b) {
	nnext[++cnt] = f[a];
	f[a] = cnt;
	v[cnt] = b;
}

int dfs(int a, int b, int c, int d) {
	int ans = 1;
	if (c > d) return 0;
	for (int i = f[a]; i; i = nnext[i]) {
		int to = v[i];
		if (to != b) {
			ans += dfs(to, a, c + 1, d);
		}
	}
	return ans;
}

