const int MAXN = 2010;

void setmax (int &a, int b) {
	if (a < b) {
		a = b;
	}
}

int N, K;
int dp[MAXN][MAXN];	//dp[vertex][max_depth]
int par[MAXN];
vector<int> adj[MAXN];

void dfs (int x, int p) {
	auto it = find(adj[x].begin(), adj[x].end(), p);
	if (it != adj[x].end()) {
		adj[x].erase(it);
	}
	for (int t : adj[x]) {
		if (t != p) {
			dfs(t, x);
		}
	}
}

int getdp (int x, int mxd) {
	int &ref = dp[x][mxd];
	if (ref >= 0) {
		return ref;
	}
	//biggest child depth is < mxd - 1.
	if (mxd == 0) {
		return ref = 1;
	}
	ref = getdp(x, mxd - 1);
	//biggest child depth = mxd - 1
	if (mxd == K) {
		//then just do this 
		for (int t : adj[x]) {
			setmax(ref, 1 + getdp(t, mxd - 1));
		}
		return ref;
	}
	int mxallow = min(mxd - 1, K - 1 - mxd);
	int s = 0;
	for (int t : adj[x]) {
		s += getdp(t, mxallow);
	}
	for (int t : adj[x]) {
		setmax(ref, 1 + s + (getdp(t, mxd - 1) - getdp(t, mxallow)));
	}
	return ref;
}

int main() {
	scanf("%d %d", &N, &K);
	for (int i = 1; i < N; i++) {
		int a, b;
		scanf("%d %d", &a, &b);
		adj[a].push_back(b);
		adj[b].push_back(a);
	}

	//ok add this stuff
	dfs(1, 0);
	int ans = 0;
	memset(dp, -2, sizeof(dp));
	for (int i = 0; i <= K; i++) {
		setmax(ans, getdp(1, i));
		//printf("dp[root][%d] = %d\n", i, dp[1][i]);
	}
	printf("%d\n", N - ans);
}

