	int DIA = 0;



	for(int i = 0 ; i < N ; i++)if(!chCnt[i]) leafs.push_back(i);

	int removed = 0;

	while(1)
	{
		pair<int,pair<int,int> > PP = getDiameter(0);

		int firstNode = PP.second.first; int secondNode = PP.second.second;
		DIA = PP.first;

		chCnt[0] = 0;

		//cerr << "Diameter " << DIA << " " << (firstNode+1) <<" " << (secondNode+1) << endl;
