        //assert(dist != MAX_N);
        if (dist <= K) {
            int n_remove = 0;
            REP(i, N) {
                if (d[i] == MAX_N) {
                    n_remove++;
                }
            }
            ret = min(ret, n_remove);
        }
    }
    assert(ret != MAX_N);
    printf("%d\n", ret);
    return 0;
}

