void addedge(int u,int v)
{
	e[++cnt].to=v;e[cnt].next=last[u];last[u]=cnt;
	e[++cnt].to=u;e[cnt].next=last[v];last[v]=cnt;
}

void dp(int id)
{
	int to=e[id].to;vis[id]=1;
	for (int i=last[to];i;i=e[i].next)
	{
		if (i==(id^1)) continue;
		if (!vis[i]) dp(i);
	}
	int a1=0;
	for (int i=last[to];i;i=e[i].next) if (i!=(id^1)) a[++a1]=i;
	f[id][0]=0;
	for (int i=1;i<=a1;i++) f[id][0]+=f[a[i]][0]+1;
	for (int i=1;i<m;i++)
	{
		f[id][i]=0;
		int j=min(i,m-i),mn=inf;
		for (int k=1;k<=a1;k++) f[id][i]+=f[a[k]][j-1],mn=min(mn,f[a[k]][j-1]-f[a[k]][i-1]);
		f[id][i]+=mn;
		f[id][i]=min(f[id][i],f[id][i-1]);
	}
}

