  for(int i = 0; i < N - 1; i++){
    int a, b;
    cin >> a >> b;
    a--; b--;
    G[a].push_back( T(b, 0) );
    G[b].push_back( T(a, 0) );
    E.push_back( T(a, b) );
  }

  for(int v = 0; v < N; v++){
    dfs( v, -1 );
  }

  int ans = N;
  if( K % 2 == 0 ){
    for(int v = 0; v < N; v++)
      ans = min( ans, solve_even(v) );
  }else{
    for(int e = 0; e < N - 1; e++){
      ans = min( ans, solve_odd(e) );
    }
  }

  cout << ans << endl;
}

#include <iostream>
#include <vector>
using namespace std;

int solve(int root, int N, int K, const vector<vector<int>> &Es){
    int k = K / 2;
    vector<int> depth(N, -1);
    depth[root] = 0;
    vector<int> parent(N, -1);
    parent[root] = root;
    vector<int> child(N, 0);
    vector<int> childKp1(N, 0);
    vector<bool> closed(N, false);
    vector<int> stack = {root};
    while (not stack.empty()){
        int v = stack.back();
        if (closed[v]){
            stack.pop_back();
            childKp1[parent[v]] += childKp1[v];
            child[parent[v]] += child[v] + 1;
            continue;
        }
        for (int u : Es[v]){
            if (depth[u] != -1) continue;
            depth[u] = depth[v] + 1;
            parent[u] = v;
            if (depth[u] == k + 1){
                ++childKp1[v];
                continue;
            }
            stack.push_back(u);
        }
        closed[v] = true;
    }
    int cum = 1;
    int maxKp1 = 0;
    for (int v : Es[root]){
        cum += child[v] + 1;
        maxKp1 = max(maxKp1, childKp1[v]);
    }
    int ans = N - cum;
    if (K & 1) ans -= maxKp1;
    return ans;
}


