        int a, b;
        cin >> a >> b;
        Es[a - 1].push_back(b - 1);
        Es[b - 1].push_back(a - 1);
    }
    int ans = N;
    for (int v = 0; v != N; ++v){
        ans = min(ans, solve(v, N, K, Es));
    }
    cout << ans << endl;
    return 0;
}

