using namespace std;

typedef long long ll;

const int MAXN = (int)2e3 + 5;
const int INF = (int)1e5;

vector<int> adj[MAXN];

int dp[MAXN][MAXN];

int lim[MAXN];

int sub[MAXN];

int n, k;

int getDp(int v, int d, bool p) {
	if (p != 0) {
		d = min(d, lim[v]);
	}

	if (d == -1) {
		return sub[v];
	}

    return dp[v][d];
}

void dfs(int v, int pr) {
	bool leaf = 1;
	sub[v] = 1;

	for (int to : adj[v]) {
		if (to == pr) {
			continue;
		}

		leaf = 0;
		dfs(to, v);
		sub[v] += sub[to];
	}

	if (leaf) {
		dp[v][0] = 0;
		return;
	}

	for (int mx = -1; mx <= k - 1; ++mx) {
		int mx2 = min(mx, k - 2 - mx);
		int sum = 0;

		for (int to : adj[v]) {
			if (to == pr) {
				continue;
			}

			sum += getDp(to, mx2, 1);
		}

		for (int to : adj[v]) {
			if (to == pr) {
				continue;
			}

			if (getDp(to, mx, 0) == INF) {
				continue;
			}

			dp[v][mx + 1] = min(dp[v][mx + 1], sum - getDp(to, mx2, 1) + getDp(to, mx, 0));
		}		
	}

	while (lim[v] >= 0 && dp[v][lim[v]] == INF) {
		--lim[v];
	}
}

void solve() {                   
	scanf("%d %d", &n, &k);

    for (int i = 1, u, v; i < n; ++i) {
		scanf("%d %d", &u, &v);
		adj[u].pb(v);
		adj[v].pb(u);    	
    }

    for (int i = 1; i <= n; ++i) {
    	for (int j = 0; j <= k; ++j) {
    		dp[i][j] = INF;
    	}

    	lim[i] = k;
    }

    dfs(1, -1);
    int ans = n;    

    for (int v = 1; v <= n; ++v) {
    	for (int d = 0; d <= k; ++d) {
    		ans = min(ans, dp[v][d] + n - sub[v]);
    	}
    }

    printf("%d\n", ans);
}

int main() {    
    int tt = 1;

    while (tt--) {
        solve();
    }

    return 0;
}

