void dfs(int u , int p , vector<int> &dist)
{
	for(int i = 0; i < g[u].size(); i++)
	{
		int v = g[u][i];
		if(v != p)
		{
			parent[v] = u;
			dist[v] = dist[u] + 1;
			dfs(v , u , dist);
		}
	}
}
int findFur()
{
	int mxDist = 0;
	int fur;
	for(int i = 0; i < n; i++)
	{
		if(dist[i] > mxDist)
		{
			mxDist = dist[i];
			fur = i;
		}
	}
	return fur;
}
void findDiametr()
{
	dist.resize(2000);
	dist[0] = 0;
	dfs(0 , -1 , dist);
	int fur = findFur();
	dist[fur] = 0;
	dfs(fur , -1 , dist);
	int fur2 = findFur();
	while(fur2 != fur)
	{
		diametr.pb(fur2);
		fur2 = parent[fur2];
	}
	diametr.pb(fur);
}
