int dfs1(int u, int fa, int dep) {
	int res = 0;
	for(auto v:G[u]) if(v ^ fa) {
		res += dfs1(v, u, dep + 1);
	}
	return res + (dep > K / 2);
}
int dfs2(int u, int fa, int dep) {
	int res = 0;
	for(auto v:G[u]) if(v ^ fa) {
		res += dfs2(v, u, dep + 1);
	}
	return res + (dep > K / 2);
}
