	for(int i=last[x];i;i=e[i].next)
	{
		int y=e[i].y;
		if(y==ff)continue;
		flag=false;
		dfs(y,x);
		for(int j=2;j<=k;j++)
		g[j]=min(f[x][j]+f[y][min(k-j+t,j-t)],f[x][min(k-j+t,j)]+f[y][j-t]);
		f[x][0]+=f[y][0],f[x][1]+=f[y][0];
		for(int j=3;j<=k;j++)g[j]=min(g[j],g[j-1]);
		for(int j=2;j<=k;j++)f[x][j]=g[j];
	}
	for(int i=1;i<=k;i++)f[x][i]=min(f[x][i],f[x][i-1]);
//	for(int i=0;i<=k;i++)printf("f[%d][%d]=%d\n",x,i,f[x][i]);
}
