const double PI = acos(-1.0);
const int INF = 1000 * 1000 * 1000 + 7;
const LL LINF = INF * (LL)INF;

const int MAX = 2000 + 47;

int D[MAX];
int mark[MAX];
vector<int> g[MAX];
vector<int> V1, V2, V;
int n, k;

void dfs(int v, int d)
{
	D[v] = d;

	FOR(i, 0, SZ(g[v]))
	{
		int to = g[v][i];
		if (!mark[to] && D[to] == INF) dfs(to, d + 1);
	}
}

int getDiameter()
{
	FOR(i, 0, n)
	{
		if (!mark[i])
		{
			FOR(j, 0, n) D[j] = INF;
			dfs(i, 0);

			int max1 = i;
			FOR(j, 0, n)
			{
				if (!mark[j] && D[j] > D[max1]) max1 = j;
			}

			FOR(j, 0, n) D[j] = INF;
			dfs(max1, 0);
			FOR(j, 0, n)
			{
				if (!mark[j] && D[j] > D[max1]) max1 = j;
			}

			int d = D[max1];
			V1.clear();
			V2.clear();
			FOR(j, 0, n)
			{
				if (!mark[j] && D[j] == d)
				{
					V1.push_back(j);
				}
			}

			FOR(j, 0, n) D[j] = INF;
			int max2 = max1;
			dfs(max2, 0);

			FOR(j, 0, n)
			{
				if (!mark[j] && D[j] == d)
				{
					V2.push_back(j);
				}
			}

			if (SZ(V1) < SZ(V2))
			{
				V = V1;
			}
			else
			{
				V = V2;
			}

			return d;
		}
	}
}

