		a--;
		b--;
		g[a].push_back(b);
		g[b].push_back(a);
	}

	int ans = 0;
	while (1)
	{
		int d = getDiameter();
		if (d <= k) break;
		FOR(i, 0, SZ(V))
		{
			ans++;
			mark[V[i]] = 1;
		}
	}

	cout << ans << endl;
}

