void bfs(int node,int mx) {

  queue<iii> q;
  q.push(mp(mp(node,0),0));
  while(!q.empty()) {
    iii t=q.front();
    q.pop();
    if(!vis[t.st.st]) {
      now++;
      vis[t.st.st]=1;
    }
    if(t.st.nd==mx) continue ;
    for(int i=0;i<v[t.st.st].size();i++) {
      if(v[t.st.st][i]!=t.nd) {
        q.push(mp(mp(v[t.st.st][i],t.st.nd+1),t.st.st));
      }
    }
  }

}

void mc(int node1,int node2) {

  memset(vis,0,sizeof(vis));
  bfs(node1,k/2);
  bfs(node2,k/2);
  ans=max(ans,now);
  now=0;

}

