const int maxn = 4010;
using namespace std;

bool vis[maxn];
int n, K, ter[maxn], nxt[maxn], lnk[maxn], opt[maxn], dis[maxn], A[maxn], B[maxn], e;

void add(int x, int y) {
	ter[++ e] = y, nxt[e] = lnk[x], lnk[x] = e;
	ter[++ e] = x, nxt[e] = lnk[y], lnk[y] = e;
}

int main() {
	scanf("%d%d", &n, &K);
	int x, y;
	memset(vis, true, sizeof(vis));
	rep(i, 1, n - 1) scanf("%d%d", &x, &y), add(x, y);
	int ans = 0;
	for (; ; ) {
		rep(i, 1, n) dis[i] = 0;
		int he = 0, ta = 1; 
		rep(i, 1, n) if (vis[i]) { opt[1] = i, dis[i] = 1; break; }
		while (he != ta) {
			++ he; int u = opt[he];
			for (int i = lnk[u]; i; i = nxt[i]) 
				if (vis[ter[i]] && !dis[ter[i]]) 
					dis[ter[i]] = dis[u] + 1, opt[++ ta] = ter[i];
		}
		rep(i, 1, n) dis[i] = 0;
		opt[1] = opt[ta], dis[opt[1]] = 1;
		he = 0, ta = 1;
		while (he != ta) {
			++ he; int u = opt[he];
			for (int i = lnk[u]; i; i = nxt[i])
				if (vis[ter[i]] && !dis[ter[i]])
					dis[ter[i]] = dis[u] + 1, opt[++ ta] = ter[i];
		}
		A[0] = B[0] = 0;
		rep(i, 1, ta) if (dis[opt[i]] == dis[opt[ta]]) A[++ A[0]] = opt[i];
		rep(i, 1, n) dis[i] = 0;
		opt[1] = A[1], dis[A[1]] = 1;
		he = 0, ta = 1;
		while (he != ta) {
			++ he; int u = opt[he];
			for (int i = lnk[u]; i; i = nxt[i])
				if (vis[ter[i]] && !dis[ter[i]])
					dis[ter[i]] = dis[u] + 1, opt[++ ta] = ter[i];
		}
		rep(i, 1, ta) if (dis[opt[i]] == dis[opt[ta]]) B[++ B[0]] = opt[i];
		if (dis[B[1]] - 1 <= K) break;
		if (A[0] < B[0]) {
			ans += A[0];
			rep(i, 1, A[0]) vis[A[i]] = false;
		} else {
			ans += B[0];
			rep(i, 1, B[0]) vis[B[i]] = false;
		}
	}
	printf("%d\n", ans);
 	return 0;
}

