			memset(Vis, 0, sizeof(Vis));
			Count = 0;
			Find(i, Pa[i], 0);
		}
	}
	else {
		K = (K - 1) >> 1;
		for(int i = 1; i <= N; i++) {
			for(int j = 1; j <= N; j++) Flag[j] = true;
			Count = 0;
			Find(Tree[i].From, Tree[i].Next, 0);
			Find(Tree[i].Next, Tree[i].From, 0);
		}
	}
	printf("%d", Ans - 1);
}

