bool rem[MAX];
int state[MAX],dis0[MAX],dis1[MAX],dis2[MAX],N;

void BFS0(int u){
    queue<int> Q;
    for(int i=0;i<N;i++){
        state[i]=0;
        dis0[i]=-INF;
    }
    state[u]=1;
    dis0[u]=0;
    Q.push(u);
    while(!Q.empty()){
        int a=Q.front();
        Q.pop();
        for(int i=0;i<S[a].size();i++){
            int b=S[a][i];
            if(rem[b]&&!state[b]){
                Q.push(b);
                state[b]=1;
                dis0[b]=dis0[a]+1;
            }
        }
    }
}

void BFS1(int u){
    queue<int> Q;
    for(int i=0;i<N;i++){
        state[i]=0;
        dis1[i]=-INF;
    }
    state[u]=1;
    dis1[u]=0;
    Q.push(u);
    while(!Q.empty()){
        int a=Q.front();
        Q.pop();
        for(int i=0;i<S[a].size();i++){
            int b=S[a][i];
            if(rem[b]&&!state[b]){
                Q.push(b);
                state[b]=1;
                dis1[b]=dis1[a]+1;
            }
        }
    }
}

void BFS2(int u){
    queue<int> Q;
    for(int i=0;i<N;i++){
        state[i]=0;
        dis2[i]=-INF;
    }
    state[u]=1;
    dis2[u]=0;
    Q.push(u);
    while(!Q.empty()){
        int a=Q.front();
        Q.pop();
        for(int i=0;i<S[a].size();i++){
            int b=S[a][i];
            if(rem[b]&&!state[b]){
                Q.push(b);
                state[b]=1;
                dis2[b]=dis2[a]+1;
            }
        }
    }
}


int main(){

    int K;cin>>N>>K;
    for(int i=0;i<N-1;i++){
        int a,b;cin>>a>>b;
        a--;b--;
        S[a].push_back(b);
        S[b].push_back(a);
    }
    for(int i=0;i<N;i++){
        rem[i]=1;
    }
    int cnt=0;

    if(K==1) cout<<N-2<<endl;
    else{
    while(1){
        for(int i=0;i<N;i++){
            if(rem[i]){
                BFS0(i);
                break;
            }
        }
        int ma=-1,s;
        for(int i=0;i<N;i++){
            if(dis0[i]>ma){
                ma=dis0[i];
                s=i;
            }
        }
        //cout<<ma;
        BFS1(s);
        int R=-1,t;
        for(int i=0;i<N;i++){
            if(dis1[i]>R){
                R=dis1[i];
                t=i;
            }
        }
        //cout<<" "<<R;
        if(R<=K){
            cout<<cnt<<endl;
            break;
        }
        BFS2(t);
        int cnt1=0,cnt2=0;
        for(int i=0;i<N;i++){
            if(dis1[i]==R) cnt1++;
            if(dis2[i]==R) cnt2++;
        }
        if(cnt1>=cnt2){
            for(int i=0;i<N;i++){
                if(dis2[i]==R) rem[i]=0;
            }
            cnt+=cnt2;
        }else{
            for(int i=0;i<N;i++){
                if(dis1[i]==R) rem[i]=0;
            }
            cnt+=cnt1;
        }
        //cout<<" "<<cnt1<<" "<<cnt2<<endl;
    }
    }
}

#include <bits/stdc++.h>
using namespace std;
using pii = pair<int,int>;

int solve() {
    int N, K, a, b;
    cin >> N >> K;
    vector<vector<int>> G(N);
    for ( int i = 0; i < N-1; i++ ) {
        cin >> a >> b;
        a--, b--;
        G[a].push_back(b);
        G[b].push_back(a);
    }

    // v から距離 k-1, k 以内にある点の数
    function<pii(int,int,int)> dfs = [&](int v, int p, int k) {
        pii r;
        if ( k == 0 ) {
            r.second++;
        } else {
            r.first++;
            r.second++;
            for ( int u : G[v] ) {
                if ( u == p ) continue;
                auto x = dfs(u, v, k-1);
                r.first += x.first;
                r.second += x.second;
            }
        }
        return r;
    };

    int ans = 100000;
    if ( K % 2 == 0 ) {
        for ( int i = 0; i < N; i++ ) {
            pii x = dfs(i, -1, K / 2);
            ans = min(ans, N - x.second );
        }
    } else {
        for ( int i = 0; i < N; i++ ) {
            int s = 1, md = 0;
            for ( int j : G[i] ) {
                auto x = dfs(j, i, (K-1)/2 );
                s += x.first;
                md = max(md, x.second - x.first);
            }
            s += md;
            ans = min(ans, N - s );
        }
    }
    return ans;
}

int main() {
    auto ans = solve();
    cout << ans << "\n";
    return 0;
}

