//n:現在のノード, r:親ノード, ml:残り経路長
long dfs(int n,int r,int ml){
    if(ml<0) return 0;
    int ret=1;
    FORE(nxt,G[n]){
        if(nxt!=r) ret+=dfs(nxt,n,ml-1);
    }
    return ret;
}

int main(void)
{
    cin>>N>>K;
    G=VII(N);
    REP(i,N){
        int a,b; cin>>a>>b;
        a--; b--;
        G[a].emplace_back(b);
        G[b].emplace_back(a);
    }
    long ans=LONG_MAX;
    if(K&1){
        REP(i,N)FORE(j,G[i]){
            long buf=N-(dfs(i,j,(K-1)/2)+dfs(j,i,(K-1)/2)); //DEBUG(buf)
            ans=min(ans,buf);
        }
    }else{
        REP(i,N) ans=min(ans,N-dfs(i,-1,K/2));
    }
    cout<<((ans>=0)?ans:0)<<endl;
    return 0;
}

