struct edge
{
	int v,nxt;
}e[5000];
int head[2005],tot=0,n,k,ans=0,d1[2005]={0},d2[2005]={0},init[2005]={0},use[2005]={0},dis,root;
void add(int a,int b)
{
	tot++;
	e[tot].v=b;
	e[tot].nxt=head[a];
	head[a]=tot;
}
void dfs(int x,int fa)
{
	d1[x]=d2[x]=0;
	for (int i=head[x];i;i=e[i].nxt) if (e[i].v!=fa&&use[e[i].v]==0)
	{
		dfs(e[i].v,x);
		if (d1[e[i].v]+1>d1[x])
		{
			d2[x]=d1[x];
			d1[x]=d1[e[i].v]+1;
		}
		else
		if (d1[e[i].v]+1>d2[x]) d2[x]=d1[e[i].v]+1;
	}
	dis=max(dis,d1[x]+d2[x]);
}
int main()
{
	memset(head,0,sizeof(head));
	scanf("%d%d",&n,&k);
	for (int i=1;i<n;i++)
	{
		int a,b;
		scanf("%d%d",&a,&b);
		add(a,b);
		add(b,a);
		init[a]++;
		init[b]++;
	}
	root=1;
	dis=0;
	dfs(1,0);
	if (dis<=k)
	{
		printf("0");
		return 0;
	}
	for (;;ans++)
	{
		int node=0,tmp=n+1;
		for (int i=1;i<=n;i++) if (init[i]==1&&use[i]==0)
		{
			dis=0;
			use[i]=1;
			if (root==i) for (int j=1;j<=n;j++) if (!use[j])
			{
				root=j;
				break;
			}
			dfs(root,0);
			if (tmp>dis) node=i,tmp=dis;
			use[i]=0;
		}
		if (tmp<=k) break;
		use[node]=1;
		for (int i=head[node];i;i=e[i].nxt) init[e[i].v]--;
	}
	printf("%d\n",ans+1);
}

