            dfs(-1, E[i].second, 0);
            int cnt2= 0;
            for(int i=0; i<N; ++i) {
                if(dist[i] > ((K + 1) / 2)) ++cnt2;
            }
            res = min(res, cnt2);
        }
    }
    cout << res << endl;
}

