//!   .88888.                             dP        !//
//!  d8'   '88                            88        !//
//!  88        88d888b. .d8888b. 88d888b. 88d888b.  !//
//!  88   YP88 88'  '88 88'  '88 88'  '88 88'  '88  !//
//!  Y8.   .88 88       88.  .88 88.  .88 88    88  !//
//!   '88888'  dP       '88888P8 88Y888P' dP    dP  !//
//!                              88                 !//
//!                              dP                 !//
//!=================================================!//
struct Graph
{
    Graph(const std::size_t v) : V{v}, edge(v), rev_edge(v) {}
    void addEdge(const std::size_t from, const std::size_t to) { assert(from < V), assert(to < V), edge[from].push_back(to), rev_edge[to].push_back(from); }
    const std::vector<std::size_t>& operator[](const std::size_t i) const { return assert(i < V), edge[i]; }
    void debugPrint() const
    {
        std::cerr << "[\n";
        for (std::size_t i = 0; i < V; i++) {
            for (const std::size_t to : edge[i]) { std::cerr << i << "->" << to << "\n"; }
        }
        std::cerr << "]\n";
    }
    const std::size_t V;
    std::vector<std::vector<std::size_t>> edge, rev_edge;
};
//!============================================!//
//!    8888ba.88ba             oo              !//
//!    88  '8b  '8b                            !//
//!    88   88   88  .d8888b.  dP  88d888b.    !//
//!    88   88   88  88'  '88  88  88'  '88    !//
//!    88   88   88  88.  .88  88  88    88    !//
//!    dP   dP   dP  '88888P8  dP  dP    dP    !//
//!============================================!//
int main()
{
    int N, K;
    std::cin >> N >> K;
    Graph G(2 * N - 1);
    int min = N;
    for (int i = 0, T = N, A, B; i < N - 1; i++, T++) { std::cin >> A >> B, A--, B--, G.addEdge(A, T), G.addEdge(T, A), G.addEdge(B, T), G.addEdge(T, B); }
    for (int i = 0; i < 2 * N - 1; i++) {
        std::vector<int> d(2 * N - 1, N);
        d[i] = 0;
        auto dfs = [&](auto&& self, const int s, const int p) -> void {
            for (const int to : G[s]) {
                if (to == p) { continue; }
                d[to] = d[s] + 1, self(self, to, s);
            }
        };
        dfs(dfs, i, -1);
        int sum = 0;
        for (int i = 0; i < N; i++) {
            if (d[i] > K) { sum++; }
        }
        chmin(min, sum);
    }
    std::cout << min << std::endl;
    return 0;
}

