	fo(i,0,k)pre[0][i]=suf[m+1][i]=0;
	fo(i,1,m)fo(j,0,k)pre[i][j]=pre[i-1][j]+f[son[i]][j];
	fd(i,m,1)fo(j,0,k)suf[i][j]=suf[i+1][j]+f[son[i]][j];
	f[x][0]=1;
