    read(k);
    for (int i = 1; i < n; ++ i) {
        int u, v;
        read(u), read(v);
        E[u].push_back(v);
        E[v].push_back(u);
        e.push_back(pii(u, v));
    }
    int ans = 0x3f3f3f3f;
    if (k & 1)
        for (int i = 0; i < e.size(); ++ i)
            chkmin(ans, n - dfs(e[i].first, e[i].second, k / 2) - dfs(e[i].second, e[i].first, k / 2));
    else
        for (int i = 1; i <= n; ++ i)
            chkmin(ans, n - dfs(i, 0, k / 2));
    write(ans);
}

