   if(kk == 0) return cc[u];
   int res = 0;
   for(int w : G[u]) {
      if(w == p) continue;
      res += calc2(w, min(K / 2, kk - 1), u);
   }
   return res;
}

int calc(int u, int v) {
   int res = 0, kk = 0, p = -1;
   while(u != v) {
      for(int w : G[u]) {
         if(w == p || (L[w] <= L[v] && L[v] <= R[w])) {
            continue;
         }
         res += calc2(w, min(kk, K - kk), u);
      }
      int w = *find_if(G[u].begin(), G[u].end(), [&](int w) { return w != p && L[w] <= L[v] && L[v] <= R[w]; });
      p = u;
      u = w;
      kk++;
   }
   res += cc[v] - 1;
   return res;
}

int solve() {
   if(diam() <= K) {
      //cerr << "diam <= K\n";
      return 0;
   }
   //cerr << "diam > K\n";
   int mn = N;
   for(int u = 1; u <= N; u++) {
      dfs(u);
      vector<int> diam_v;
      for(int v = 1; v <= N; v++) {
         if(level[v] == K) diam_v.push_back(v);
      }
      //cerr << "u = " << u << "\n";
      for(int v : diam_v) {
         //cerr << "v = " << v << "\n";
         int c = calc(u, v);
         if(c == 0) {
            //cerr << "calc(" << u << ", " << v << ") = " << c << "\n";
         }
         mn = min(mn, c);
      }
   }
   return mn;
}

