int N, K;
Vec< Vec< int > > adj;
Vec< Vec< set< int > > > dst;
Vec< Vec< int > > dtable;

void dfs(int piv, int v, int p, int d) {
	dst[v][d].insert(v);
	dtable[piv][v] = d;

	for (int u : adj[v]) {
		if (u == p) continue;
		dfs(piv, u, v, d + 1);
	}
}

void solve() {
	dst.assign(N, Vec< set< int > >(N + 1, set< int >()));
	dtable.assign(N, Vec< int >(N, 0));

	for_(v,0,N) dfs(v, v, -1, 0);

	int cur_dst = N;
	Vec< bool > del(N, false);

	while (cur_dst > K) {
		int piv = -1, min_v = iINF;

		for_(v,0,N) {
			if (del[v]) continue;
			int m = dst[v][cur_dst].size();
			if (m == 0) continue;

			if (min_v > m) {
				min_v = m;
				piv = v;
			}
		}

		if (piv != -1) {
			for (int u : dst[piv][cur_dst]) {
				del[u] = true;

				for_(v,0,N) {
					int d = dtable[v][u];
					dst[v][d].erase(u);
				}
			}
		}

		--cur_dst;
	}

	int ans = 0;
	for_(i,0,N) if (del[i]) ++ans;
	cout << ans << endl;
}

