int N, K;
vector<int> G[2000];
int U[2000], R[2000];

int dfs(int s, int p) {
  U[s] = p;
  int c = 1;
  for (int t : G[s]) {
    if (t == p) continue;
    c += dfs(t, s);
  }
  R[s] = c-1;
  return c;
}

int dfs2(int s, int p, int d) {
  int c = 1;
  if (d + 1 <= K) {
    for (int t : G[s]) {
      if (t == p) continue;
      c += dfs2(t, s, d+1);
    }
  }
  return c;
}

int f(int x) {
  return R[x] + (N - 1 - dfs2(U[x], x, 1));
}

