int solve_even(int bound, int n) {
  int ret = INF;
  for (int i = 0; i < n; ++i) {
    queue<int> Q;
    Q.push(i);
    fill(d, d + n, -1);
    d[i] = 0;
    while (!Q.empty()) {
      int u = Q.front();
      Q.pop();
      for (auto& v : a[u]) {
        if (d[v] >= 0) continue;
        d[v] = d[u] + 1;
        Q.push(v);
      }
    }
    int cnt = 0;
    for (int j = 0; j < n; ++j) {
      if (d[j] > bound) ++cnt;
    }
    ret = min(ret, cnt);
  }
  return ret;
}

int solve_odd(int bound, int n) {
  int ret = INF;
  for (int i = 0; i < n; ++i) {
    for (auto& j : a[i]) {
      queue<int> Q;
      Q.push(i);
      Q.push(j);
      fill(d, d + n, -1);
      d[i] = d[j] = 0;
      while (!Q.empty()) {
        int u = Q.front();
        Q.pop();
        for (auto& v : a[u]) {
          if (d[v] >= 0) continue;
          d[v] = d[u] + 1;
          Q.push(v);
        }
      }
      int cnt = 0;
      for (int j = 0; j < n; ++j) {
        if (d[j] > bound) ++cnt;
      }
      ret = min(ret, cnt);
    }
  }
  return ret;
}

