    a[x].push_back(y);
    a[y].push_back(x);
  }
  if (m % 2 == 0) {
    printf("%d\n", solve_even(m / 2, n));
  } else {
    printf("%d\n", solve_odd(m / 2, n));
  }
  return 0;
}

