	//a = K - h - 1
	// <= min(h, K - (a + 1))
	int t = remh[i][j + 1];
	//K - 1 - t <= a
	rer(a, h <= t ? 0 : K - t - 1, min(h - 1, height[c]))
		amax(r, rec(c, 0, a) + rec(i, j + 1, min(h, K - (a + 1))));
	if(h > 0)
		amax(r, rec(c, 0, h - 1) + rec(i, j + 1, min(h, K - h)));
	return r;
}

int main() {
	int N;
	while(~scanf("%d%d", &N, &K)) {
		g.assign(N, vi());
		for(int i = 0; i < N - 1; ++ i) {
			int u, v;
			scanf("%d%d", &u, &v), -- u, -- v;
			g[u].push_back(v);
			g[v].push_back(u);
		}
		tree_getorder(g, 0);
		reu(i, 1, N)
			g[i].erase(find(g[i].begin(), g[i].end(), t_parent[i]));
		height.assign(N, 0);
		for(int ix = (int)t_ord.size() - 1; ix > 0; -- ix) {
			int i = t_ord[ix], p = t_parent[i];
			amax(height[p], height[i] + 1);
		}
		remh.assign(N, vi());
		rep(i, N) {
			for(int j : g[i])
				remh[i].push_back(height[j] + 1);
			remh[i].push_back(0);
			for(int j = (int)remh[i].size() - 2; j >= 0; -- j)
				amax(remh[i][j], remh[i][j + 1]);
		}
