int dfs(int now,int fa,int len)
{
	if(len < 0) return 0;
	if(!len) return 1;
	int t = 1;
	for(int i = head[now]; i; i = s[i].nex)
		if(s[i].v != fa)
			t += dfs(s[i].v,now,len - 1);
	return t;
}
int query(int now,int len)
{
	int t = 1;
	for(int i = head[now]; i; i = s[i].nex)
		t += dfs(s[i].v,now,len - 1);
	return t;
}
