int main() {
	scanf("%d%d", &N, &K);
	for (int i = 0, A,B; i < N-1; ++i) {
		scanf("%d%d", &A, &B);
		--A, --B;
		G[A].push_back(B);
		G[B].push_back(A);
	}

	int res = 1<<30;

	for (int i = 0; i < N; ++i) {
		vector<int> checked(N, 0);
		checked[i] = 1;
		queue<pair<int, int>> q;
		q.emplace(i, 0);
		while (q.size()) {
			auto v = q.front(); q.pop();
			checked[v.first] = 1;
			if (v.second < K/2) for (auto& u : G[v.first]) if (!checked[u]) {
				q.emplace(u, v.second+1);
			}
		}
		int mx = 0;
		if (K%2) {
			int mx = 0;
			for (int j = 0; j < N; ++j) if (checked[j]) {
				int cnt = 0;
				for (auto& v : G[j]) if (!checked[j]) {
					++cnt;
				}
				mx = max(mx, cnt);
			}
		}
		int sum = accumulate(checked.begin(), checked.end(), 0)+mx;
		res = min(res, N-sum);
	}

	printf("%d\n", res);

	return 0;
}

