template<class Cost> struct Edge{
    int to;Cost cost;
    Edge(int to,Cost cost):to(to),cost(cost){};
    bool operator<(Edge r) const{ return cost<r.cost;}
    bool operator>(Edge r) const{ return cost>r.cost;}
};
template<class Cost> ostream& operator << (ostream& os, const Edge<Cost>& e){ return os<<"(->"<<e.to <<","<<e.cost<<")";}
template<class Cost> using Graph = vector<vector<Edge<Cost>>>;


vector<bool> deleted;

template<class Cost> pair<Cost,int> far(const Graph<Cost>&g,int r){
	function<pair<Cost,int>(int,int)> dfs = [&](int v,int p)->pair<Cost,int>{
		pair<Cost,int> r(0,v);
		for(auto& e:g[v])if(e.to!=p && !deleted[e.to]){
			auto t=dfs(e.to,v);
			t.first+=e.cost;
			if(r<t)r=t;
		}
		return r;
	};
	return dfs(r,-1);
}

template<class Cost> pair<Cost,int> diam(const Graph<Cost>&g){
	int i = 0; while(deleted[i])i++;
	auto f=far(g,i),t=far(g,f.second);


	int v1c = -1;
	int v1 = f.second;
	{
		int v1p;
		for(auto& e:g[v1])if(!deleted[e.to]) v1p = e.to;
		for(auto& e:g[v1p])if(!deleted[e.to]) v1c++;
	}
	int v2c = -1;
	int v2 = t.second;
	{
		int v2p;
		for(auto& e:g[v2])if(!deleted[e.to]) v2p = e.to;
		for(auto& e:g[v2p])if(!deleted[e.to]) v2c++;
	}
	if(v1c < v2c){
		return make_pair(t.first,v1);
	}else{
		return make_pair(t.first,v2);
	}
}

class Main{
	public:

	void run(){
		int N,K;cin >> N >> K;
		deleted = vector<bool>(N,false);
		Graph<int> g = vector<vector<Edge<int>>>(N);
		for(int i:range(N-1)){
			int a,b;cin >> a >> b;a--;b--;
			g[a].push_back({b,1});
			g[b].push_back({a,1});
		}
		int c = 0;
		while(true){
			auto p = diam(g);
			if(p.first <= K){
				cout << c << endl;
				break;
			}
			c++;
			deleted[p.second] = true;
		}
	}
};

