const int N = 2e3 + 4;

int n, k, kv, ke;
vector<int> g[N];

void read() {
    cin >> n >> k;
    kv = k / 2;
    ke = (k - 1) / 2;
    for (int i = 1; i < n; ++i) {
        int a, b;
        cin >> a >> b;
        g[a].em_back(b);
        g[b].em_back(a);
    }
}

bool used[N];

void dfs(int u, int d, int board) {
    used[u] = 1;
    if (d == board) {
        return;
    }
    for (int to : g[u]) if (!used[to]) {
        dfs(to, d + 1, board);
    }
}

int calcVertex(int u) {
    memset(used, 0, sizeof used);

    used[u]  = 1;
    dfs(u, 0, kv);

    return accumulate(used, used + N, 0);
}

int calcEdge(int u, int v) {
    memset(used, 0, sizeof used);

    used[u] = used[v] = 1;
    dfs(u, 0, ke);
    dfs(v, 0, ke);

    return accumulate(used, used + N, 0);
}

void solve() {
    read();

    int ans = 1e9;
    for (int i = 1; i <= n; ++i) {
        ans = min(ans, n - calcVertex(i));
    }
    for (int u = 1; u <= n; ++u) {
        for (int to : g[u]) {
            ans = min(ans, n - calcEdge(u, to));
        }
    }
    cout << ans << "\n";
}

int main() {
    ios::sync_with_stdio(0);
    cout.tie(0), cin.tie(0);

    int z = 1;
    /// cin >> z;

    while (z--) {
        solve();
    }

    return 0;
}

