namespace G{
	int cnt,res,ans,fir[N],dep[N];
	bool vis[N];
	struct edge{
		int to,nx;
	}eg[N];

	inline void add(const int a,const int b){
		eg[++cnt]=(edge){b,fir[a]};
		fir[a]=cnt;
	}
	inline void init(){
		res=0;
		memset(vis,0,sizeof(vis));
		memset(dep,1,sizeof(dep));
	}

	inline void dfs(const int x){
		vis[x]=1;
		res+=dep[x]>(q+1)>>1;
		for(int i=fir[x];i;i=eg[i].nx){
			const int y=eg[i].to;
			if(!vis[y]){
				apn(dep[y],dep[x]+1);
				dfs(y);
			}
		}
	}
	inline void solve(){
		ans=1e9;
		for(int i=1;i<=n;++i){
			init();
			dep[i]=0;
			dfs(i);
			apn(ans,res);
		}
		for(int i=1;i<=n;++i){
			for(int j=fir[i];j;j=eg[j].nx){
				const int k=eg[j].to;
				if(i<k){
					init();
					dep[i]=dep[k]=1;
					dfs(i);
