using namespace std;

int dfs(int v, int max_len, int p, vector<vector<int> > &g) {
    if (max_len == 0) {
        return 0;
    }
    int res = 1;
    for (int to : g[v]) {
        if (to == p) {
            continue;
        }
        res += dfs(to, max_len - 1, v, g);
    }
    return res;
}

int main() {
    int n, k;
    scanf("%d %d", &n, &k);
    vector<vector<int> > g(n);
    for (int i = 0; i + 1 < n; i++) {
        int fr, to;
        scanf("%d %d", &fr, &to);
        fr--;
        to--;
        g[fr].push_back(to);
        g[to].push_back(fr);
    }
    int res = 0;
    for (int root = 0; root < n; root++) {
        int dp0 = 1, dp1 = 1;
        for (int to : g[root]) {
            int not_use = dfs(to, k / 2, root, g);
            int use = dfs(to, k / 2 + 1, root, g);
            int nextDP1 = max(dp1 + not_use, dp0 + use);
            dp0 += not_use;
            dp1 = nextDP1;
        }
        if (k % 2 == 1) {
            dp0 = dp1;
        }
        res = max(res, dp0);
    }
    printf("%d\n", n - res);
    return 0;
}

