    adjlist[b].push_back(a);
    edge.push_back(make_pair(a, b));
  }

  int ans = 0;
  if(k % 2 == 0){
    for(int i = 0; i < n; i++){
      vector<bool> used(n, false);
      ans = max(ans, dfs(i, k / 2, adjlist, used));
    }
  }
  else{
    for(int i = 0; i < n - 1; i++){
      vector<bool> used(n, false);
      used[edge[i].first] = used[edge[i].second] = true;
      ans = max(ans, dfs(edge[i].first, k / 2, adjlist, used)
                + dfs(edge[i].second, k / 2, adjlist, used));
    }
  }

  cout << n - ans << endl;

  return 0;
}

