        MX[j] = dfs(g[i][j], i, 1, j);
        for(int k = MX[j] - 1; k > half; k--) {
          X[j][k] += X[j][k+1];
        }
        if(MX[j] >= half + 1) {
          sm += X[j][half + 1];
        }
        if(MX[j] >= half + 2) {
          mx = max(X[j][half + 1] - X[j][half + 2], mx);
        } else if(MX[j] == half + 1) {
          mx = max(X[j][half + 1], mx);
        }
      }
      ans = min(ans, sm - mx);
    }
  } else {
    rep(i,1,n+1) {
      trn++;
      int sm = 0;
      rep(j,0,g[i].size()) {
        MX[j] = dfs(g[i][j], i, 1, j);
        for(int k = MX[j] - 1; k > half; k--) {
          X[j][k] += X[j][k+1];
        }
        if(MX[j] >= half + 1) {
          sm += X[j][half + 1];
        }
      }
      ans = min(ans, sm);
    }
  }
  P(ans);

  return 0;
}

