void dfs(int v, int &res, int p = -1, int d = 0) {
	if (d > k / 2) res++;
	for (int to: g[v])
		if (to != p) dfs(to, res, v, d + 1);
}

int get(int x) {
	int res = 0;
	dfs(x, res, k / 2);
	return res;
}

int getEdge(int x) {
	int res = 0;
	dfs(edges[x].F, res, edges[x].S);
	dfs(edges[x].S, res, edges[x].F);
	return res;
}

