typedef pair<int, int> Result;
Result visit(int p, int v, const Graph &g) {
  Result r(0, v);
  for(auto &e:g[v]) if (e != p) {
    Result t = visit(v, e, g);
    t.first += 1;
    if (r.first < t.first) r = t;
  }
  return r;
}
int diameter(const Graph &g,int t) {
  Result x = visit(-1, t, g);
  return x.first;
}

