using namespace std;

vector <int> vec[SIZE];
int dp[SIZE][SIZE];
int nxt[SIZE];
int mx[SIZE],nd[SIZE];
int n,K;

void dfs(int v=0,int p=-1)
{
	mx[v]=0;
	nd[v]=1;
	for(int j=1;j<SIZE;j++) dp[v][j]=SIZE;
	dp[v][0]=0;
	for(int i=0;i<vec[v].size();i++)
	{
		int to=vec[v][i];
		if(to!=p)
		{
			dfs(to,v);
			for(int j=0;j<SIZE;j++) nxt[j]=SIZE;
			for(int j=0;j<=mx[v];j++)
			{
				for(int k=0;k<=mx[to];k++)
				{
					if(j+k>K) break;
					nxt[max(j,k)]=min(nxt[max(j,k)],dp[v][j]+dp[to][k]);
				}
			}
			for(int j=0;j<SIZE;j++) dp[v][j]=nxt[j];
			mx[v]=max(mx[v],mx[to]);
			nd[v]+=nd[to];
		}
	}
	mx[v]++;
	for(int j=mx[v];j>=1;j--) dp[v][j]=dp[v][j-1];
	dp[v][0]=nd[v];

}
