void smain() {
    cin >> n >> k;
    fori (i, n - 1) {
        int u, v;
        cin >> u >> v;
        g[u].push_back(v);
        g[v].push_back(u);
    }

    int ans = 0;

    for (int v = 1; v <= n; ++v) {
        vvi sacks;
        for (int to : g[v]) {
            sacks.push_back({});
            dfs(to, v, sacks.back());
        }
        if (k & 1) {
            int sum = 1;
            int h = k >> 1;
            for (auto sack : sacks) {
                for (int i = 0; i < min((int) sack.size(), h + 1); ++i) {
                    sum += sack[i];
                }
            }
            for (auto sack : sacks) {
                if (sack.size() <= h + 1)
                    continue;
                int cur = sum + sack[h + 1];
                inmax(ans, cur);
            }
        } else {
            int h = k >> 1;
            int cur = 1;
            for (auto sack : sacks) {
                for (int i = 0; i < min((int) sack.size(), h + 1); ++i) {
                    cur += sack[i];
                }
            }
            inmax(ans, cur);
        }
    }
    cout << n - ans;
}

