#include <bits/stdc++.h>

using namespace std;

const int N = 2000 + 7;
int n, k, dp[N][N], sub[N];
vector<int> g[N];

void dfs(int a, int p) {
  sub[a] = 1;
  vector<int> kids;
  for (auto &b : g[a]) {
    if (b != p) {
      dfs(b, a);
      kids.push_back(b);
      sub[a] += sub[b];
    }
  }
  if (kids.empty()) {
    dp[a][0] = 1;
    for (int i = 1; i <= k; i++) {
      dp[a][i] = 0;
    }
    return;
  }
  dp[a][0] = sub[a];
  for (int len = 1; len <= k; len++) {
    dp[a][len] = dp[a][len - 1];
    for (auto &strong : kids) {
      int upd = dp[strong][len - 1];
      for (auto &b : kids) {
        if (b != strong) {
          upd += dp[b][k - len];
        }
      }
      dp[a][len] = min(dp[a][len], upd);
    }
  }
}

int main() {
  ios::sync_with_stdio(false);
  cin.tie(0);

  cin >> n >> k;
  k++;
  for (int i = 1; i < n; i++) {
    int a, b;
    cin >> a >> b;
    g[a].push_back(b);
    g[b].push_back(a);
  }
  dfs(1, -1);
  int ans = dp[1][0];
  for (int len = 1; len <= k; len++) {
    ans = min(ans, dp[1][len]);
  }
  cout << ans << "\n";
}

