using namespace std;
using ll = int64_t;
struct A{
    ll now, par, d;
};
int main(){
    ll N, K;
    cin >> N >> K;
    vector<ll> v[N];
    for(ll i = 0; i < N - 1; i++){
        ll a, b;
        cin >> a >> b;
        v[--a].push_back(--b);
        v[b].push_back(a);
    }
    ll ans = N;
    for(ll i = 0; i < N; i++){
        bool used[N];
        for(ll j = 0; j < N; j++) used[j] = i == j;
        queue<A> q;
        q.push(A{i, -1, 0});
        ll po = 0;
        map<ll, ll> ma;
        while(q.size()){
            auto now = q.front();
            q.pop();
            if(now.d == K / 2 + 1) ma[now.par]++;
            else if(now.d == K / 2 + 2) break;
            if(now.d <= K / 2) po++;
            for(ll next : v[now.now]){
                if(used[next]) continue;
                used[next] = 1;
                q.push(A{next, now.now, now.d + 1});
            }
        }
        if(K & 1){
            ll yo = 0;
            for(auto ite = ma.begin(); ite != ma.end(); ite++) yo = max(yo, ite->second);
            po += yo;
        }
        ans = min(ans, N - po);
    }
    cout << ans << endl;
    return 0;
}

