int N, K;
vector<int> graph[2020];
vector<pair<int, int>> edges;

// [max depth, vertices]
pair<int, int> dfs(int cur, int prv, int lim) {
    if (lim == 0) return make_pair(0, 1);
    pair<int, int> ret(-1, 1);
    for (auto& nxt: graph[cur]) {
        if (nxt == prv) continue;
        auto p = dfs(nxt, cur, lim - 1);
        chmax(ret.first, p.first);
        ret.second += p.second;
    }
    ret.first++;
    return ret;
}

signed main() {

    cin >> N >> K;
    REP(i, N - 1) {
        int A, B;
        cin >> A >> B;
        --A, --B;
        graph[A].emplace_back(B);
        graph[B].emplace_back(A);
        edges.emplace_back(A, B);
    }

    ll res = N;

    if (K & 1) {
        for (auto& [u, v]: edges) {
            auto pu = dfs(u, v, K / 2);
            auto pv = dfs(v, u, K / 2);
            if (pu.first + pv.first + 1 > K) continue;
            chmin(res, N - (pu.second + pv.second));
        }
    } else {
        REP(i, N) {
            int cnt = 1, dep = 0;
            for (auto& nxt: graph[i]) {
                auto p = dfs(nxt, i, K / 2 - 1);
                cnt += p.second;
                if (p.first + 1 >= K / 2) ++dep;
            }
            if (dep >= 2) chmin(res, N - cnt);
        }
    }

    cout << res << endl;

}

