int N, K;
vector<int> G[4000];

int rec(int from, int prev, int dist) {
	if (dist > K) return 0;
	int sum = 1;
	for (int to : G[from]) {
		if (to == prev) continue;
		sum += rec(to, from, dist + 1);
	}
	return sum;
}

int sub(int st) {
	int res = rec(st, -1, 0);
	return 2 * (N - 1) - (res - 1);
}

int main() {
	cin >> N >> K;
	REP(i, 0, N - 1) {
		int a, b;
		cin >> a >> b;
		--a; --b;
		int c = N + i;
		G[a].push_back(c);
		G[c].push_back(a);
		G[b].push_back(c);
		G[c].push_back(b);
	}

	int mn = INF;
	if (K % 2 == 0) {
		REP(i, 0, N) {
			mn = min(mn, sub(i));
		}
	} else {
		REP(i, N, 2 * N - 1) {
			mn = min(mn, sub(i));
		}
	}

	cout << mn / 2 << endl;
	return 0;
}

