		}
		for (int cur = 1; cur <= k; cur++) {
			int R = k - cur;
			tmp[i][cur] = min(tmp[i][cur], mn[min(R, cur)] + dp[ver][cur - 1]);
			if (cur + 1 <= R) {
				q[R].pb(mp(1, dp[ver][cur - 1]));
				q[cur].pb(mp(-1, dp[ver][cur - 1]));
			}
		}
		multiset<int> st;
		for (int max_dist = k; max_dist >= 0; max_dist--) {
			for (auto it : q[max_dist]) {
				if (it.f == -1) {	
					st.erase(st.find(it.s));
				} else {
					st.insert(it.s);
				}
			}
			if (!st.empty())
				tmp[i][max_dist] = min(tmp[i][max_dist], tmp[i - 1][max_dist] + *st.begin());
		}
	}
	for (int max_dist = 0; max_dist <= k; max_dist++) {
		dp[x][max_dist] = tmp[sz(gt)][max_dist];
	}
}

