const int MAXN = 2005;

int n, k;
int par[MAXN], siz[MAXN];
vector <int> v[MAXN], red;
int dp[MAXN][MAXN], tmp[MAXN];

void dfs (int x, int rod) {
    par[x] = rod;
    siz[x] = 1;
    for (auto sus : v[x]) {
        if (sus == rod) continue;
        dfs(sus, x);
        siz[x] += siz[sus];
    }
    red.push_back(x);
}

int nadi_centroid (int x) {
    int mx = 0, ind = -1;
    if (par[x] != 0) {
        mx = n - siz[x];
        ind = par[x];
    }
    for (auto sus : v[x]) {
        if (sus == x) continue;
        if (siz[sus] > mx) {
            mx = siz[sus];
            ind = sus;
        }
    }
    if (2 * mx <= n) return x;
    return nadi_centroid(ind);
}

void update (int x) {
    for (int i = k; i >= 1; i--) {
        dp[x][i] = dp[x][i-1];
    }
    dp[x][0] = siz[x];
}

void spoji (int a, int b) {
    for (int d = 0; d * 2 < k; d++) {
        tmp[d] = dp[a][d] + dp[b][d];
    }
    for (int d = (k + 1)/2; d <= k; d++) {
        tmp[d] = min(dp[a][d] + dp[b][k - d], dp[a][k - d] + dp[b][d]);
        tmp[d] = min(tmp[d-1], tmp[d]);
    }
    for (int i=0; i<=k; i++) {
        dp[a][i] = tmp[i];
    }
}

