using namespace std;

int search(const vector< vector<int> >& g, int p, int prev, int rest){
	if(rest == 0) return 1;
	int res = 1;
	for(int t : g[p]){
		if(t == prev) continue;
		int r = search(g, t, p, rest-1);
		res += r;
	}
	return res;
}

int center(const vector< vector<int> >& g, int s, int k){
	int maxDif = 0;
	int res = 1;
	for(int t : g[s]){
		int r = search(g, t, s, k/2-1);
		if(k%2 == 1){
			int r2 = search(g, t, s, k/2);
			maxDif = max(maxDif, r2 - r);
		}
		res += r;
	}
	return res + maxDif;
}

