        dfs(i, i, 0, i);
    }
    int ans = 0;
    if(k & 1) {
        k >>= 1;
        for(auto edge: edgePairs) {
            int cnt = 0;
            for(int i = 0; i < n; ++ i) {
                cnt += std::min(dist[edge.first][i], dist[edge.second][i]) <= k;
            }
            ans = std::max(ans, cnt);
        }
    } else {
        k >>= 1;
        for(int root = 0; root < n; ++ root) {
            int cnt = 0;
            for(int i = 0; i < n; ++ i) {
                cnt += dist[root][i] <= k;
            }
            ans = std::max(ans, cnt);
        }
    }
    printf("%d\n", n - ans);
}

