			while (!nxt.empty()) {
				int p = nxt.front(); nxt.pop();
				sub[j].pb(dep[p]);
				for (auto to : edge[p]) {
					if (dep[to] == -1) {
						dep[to] = dep[p] + 1;
						nxt.push(to);
					}
				}
			}

			if (k % 2) {
				//奇数
				int rem = upper_bound(all(sub[j]),k/2) - sub[j].begin();
				tmp += sub[j].size() - rem;
				int can = upper_bound(all(sub[j]),k/2+1) - sub[j].begin();
				chmin(odd,rem-can);
			} else {
				int rem = upper_bound(all(sub[j]),k/2) - sub[j].begin();
				tmp += sub[j].size() - rem;
			}
		}
		if (k % 2) {
			chmin(ans,tmp+odd);
		} else {
			chmin(ans,tmp);
		}
	}

	cout << ans << endl;
}

