int k;
int dist[MAX];
vector<int> Graph[MAX];
void distance_measure(int node,int d=0,int parent=-1)
{
    dist[node]=d;
    int i;
    for(i=0;i<Graph[node].size();i++)
    {
        if(Graph[node][i]==parent) continue;
        distance_measure(Graph[node][i],d+1,node);
    }
}
set<int> diameter_leaves;
void initialize(int n)
{
    int i,j,root;
    for(i=1;i<=n;i++)
    {
        distance_measure(i);
        root=i;
        for(j=1;j<=n;j++)
        {
            if(dist[root]<dist[j]) root=j;
        }
        for(j=1;j<=n;j++)
        {
            if(dist[root]==dist[j]) diameter_leaves.insert(j);
        }
    }
}
int subtrees[MAX];
int subtree_size(int node,int parent=-1)
{
    subtrees[node]=1;
    int i;
    for(i=0;i<Graph[node].size();i++)
    {
        if(Graph[node][i]==parent) continue;
        subtrees[node]+=subtree_size(Graph[node][i],node);
    }
    return subtrees[node];
}
int result(int node,int d,int parent=-1)
{
    if(d==0) return subtrees[node]-1;
    int i,ans=0;
    for(i=0;i<Graph[node].size();i++)
    {
        if(Graph[node][i]==parent) continue;
        ans+=result(Graph[node][i],d-1,node);
    }
    return ans;
}
int find_answer(int node,int k)
{
    int ans=subtree_size(node);
    ans=result(node,k);
    return ans;
}
