    scanf("%d %d",&n,&k);
    int u,v,i;
    for(i=1;i<n;i++)
    {
        scanf("%d %d",&u,&v);
        Graph[u].push_back(v);
        Graph[v].push_back(u);
    }
    initialize(n);
    int ans=n;
    set<int>::iterator it;
    for(it=diameter_leaves.begin();it!=diameter_leaves.end();++it)
    {
        ans=min(ans,find_answer((*it),k));
    }
    printf("%d",ans);
    return 0;
}

