  {}
  bool operator>(const Edge& rhs) const{
	return cost > rhs.cost;
  }
  bool operator<(const Edge& rhs) const{
	return cost < rhs.cost;
  }

};
typedef vector< vector<Edge> > Graph;
void add_edge(Graph& graph, int u, int v, int cost){
  graph[u].push_back(Edge(v,cost));
  graph[v].push_back(Edge(u,cost));
}

int N, K;
const int MAX = 2010;
const int LOG_MAX = log2(MAX);
int depth[MAX];
int num[MAX];
int parent[LOG_MAX][MAX];
Graph G(MAX);
// number graph with root. root is first given node
// suppose depth < 0
void dfs(int node, int p = -1, int d = 0)
{
  if(depth[node] >= 0) return;
  depth[node] = d;
  parent[0][node] = p;
  num[node] = 1;
  for(int i=0;i<SZ(G[node]);++i){
	if(G[node][i].to == p) continue;
	dfs(G[node][i].to, node, d+1);
	num[node] += num[G[node][i].to];
  }
}

void init(){
  fill(depth, depth+MAX, -1);
  dfs(0);
  for(int i=0;i+1<LOG_MAX;++i){
	for(int v=0;v<N;++v){
	  if(parent[i][v] == -1) parent[i+1][v] = -1;
	  else parent[i+1][v] = parent[i][parent[i][v]];
	}
  }
}

int LCA(int u, int v){
  if(depth[u] > depth[v]) swap(u, v);
  //depth[u] <= depth[v]
  for(int i=0;i<LOG_MAX;++i)
	if((depth[v] - depth[u]) >> i & 1)
	  v = parent[i][v];
  if(u == v) return u;

  for(int i=LOG_MAX-1;i>=0;--i){
	if(parent[i][u] != parent[i][v]){
	  u = parent[i][u];
	  v = parent[i][v];
	}
  }
  return parent[0][u];
}

int dist(int u, int v){
  return depth[u] + depth[v] - depth[LCA(u,v)];
}

int dfs2(int u, int p, int d){
  int res = 0;
  if(d < 0){
	++res;
  }

  for(auto& e: G[u]){
	if(e.to == p) continue;
	res += dfs2(e.to, u, d-1);
  }
  return res;
}

