	REP(u,N){
	  ans = min(ans, dfs2(u, -1, K/2));
	}
  }
  else{
	REP(u,N){
	  for(auto& e:G[u]){
		ans = min(ans, dfs2(u, e.to, K/2) + dfs2(e.to, u, K/2));
	  }
	}
  }
  cout << ans << endl;

  return 0;
}

