        --a; --b;
        graph.connect(a, b);
    }

    vector<int> deleted(n);
    repeat(cnt,404040){
        int starter = 0;
        while (deleted[starter]) ++starter;

        ll far = 0;
        {
            ll dist = 0;
            function<void(int, int, int)> dfs1 = [&](int idx, int from, int d) {
                if (dist < d) {
                    dist = d;
                    far = idx;
                }
                for (int to : graph.vertex_to[idx]) {
                    if (to == from) continue;
                    if (deleted[to]) continue;
                    dfs1(to, idx, d + 1);
                }
            };
            dfs1(starter, -1, 0);
        }

        vector<int> visited(n);
        ll far2 = 0;
        {
            ll dist = 0;
            function<void(int, int, int)> dfs2 = [&](int idx, int from, int d) {
                if (dist < d) {
                    dist = d;
                    far2 = idx;
                }
                visited[idx] = d;
                for (int to : graph.vertex_to[idx]) {
                    if (to == from) continue;
                    if (deleted[to]) continue;
                    dfs2(to, idx, d + 1);
                }
            };
            dfs2(far, -1, 0);
        }

        ll len = visited[far2];
        if (len <= kei) break;

        ll center = -1;
        {
            function<bool(int, int, int)> dfs3 = [&](int idx, int from, int d) {
                if (d == (len + 1) / 2) {
                    center = idx;
                    return true;
                }
                for (int to : graph.vertex_to[idx]) {
                    if (to == from) continue;
                    if (deleted[to]) continue;
                    if (dfs3(to, idx, d + 1))
                        return true;
                }
                return false;
            };
            dfs3(far2, -1, 0);
        }

        if (len % 2 == 0) {
            // center vertex

            ll fard = 0;
            function<void(int, int, int)> dfs4 = [&](int idx, int from, int d) {
                maxset(fard, (ll)d);
                visited[idx] = d;
                for (int to : graph.vertex_to[idx]) {
                    if (to == from) continue;
                    if (deleted[to]) continue;
                    dfs4(to, idx, d + 1);
                }
            };
            dfs4(center, -1, 0);


            function<int(int, int)> dfs5 = [&](int idx, int from) {
                int cnt = 0;
                for (int to : graph.vertex_to[idx]) {
                    if (to == from) continue;
                    if (deleted[to]) continue;
                    cnt += dfs5(to, idx);
                }
                return cnt + (visited[idx] == fard);
            };

            ll best = 5e15;
            int besti = 0;
            int i = 0;
            for (int to : graph.vertex_to[center]) {
                if (deleted[to]) continue;
                ll r = dfs5(to, center);
                if (r < best) {
                    best = r;
                    besti = i;
                }
                ++i;
            }

            function<void(int, int)> dfs6 = [&](int idx, int from) {
                if (visited[idx] == fard) {
                    deleted[idx] = true;
                }
                for (int to : graph.vertex_to[idx]) {
                    if (deleted[to]) continue;
                    if (to == from) continue;
                    dfs6(to, idx);
                }
            };

            dfs6(graph.vertex_to[center][besti], center);

        }
        else {
            // center edge
            ll center2;

            for (int to : graph.vertex_to[center]) {
                if (visited[to] == visited[center] - 1) {
                    center2 = to;
                }
            }


            ll fard = 0;
            function<void(int, int, int)> dfs4 = [&](int idx, int from, int d) {
                maxset(fard, (ll)d);
                visited[idx] = d;
                for (int to : graph.vertex_to[idx]) {
                    if (to == from) continue;
                    if (deleted[to]) continue;
                    dfs4(to, idx, d + 1);
                }
            };
            dfs4(center, center2, 0);
            dfs4(center2, center, 0);

            function<int(int, int)> dfs5 = [&](int idx, int from) {
                int cnt = 0;
                for (int to : graph.vertex_to[idx]) {
                    if (to == from) continue;
                    if (deleted[to]) continue;
                    cnt += dfs5(to, idx);
                }
                return cnt + (visited[idx] == fard);
            };

            ll z1 = dfs5(center, center2);
            ll z2 = dfs5(center2, center);

            function<void(int, int)> dfs6 = [&](int idx, int from) {
                if (visited[idx] == fard) {
                    deleted[idx] = true;
                }
                for (int to : graph.vertex_to[idx]) {
                    if (deleted[to]) continue;
                    if (to == from) continue;
                    dfs6(to, idx);
                }
            };


            if (z1 < z2) {
                dfs6(center, center2);
            }
            else {
                dfs6(center, center2);
            }
        }
    }

    int result = accumulate(ALL(deleted), 0);

    cout << result << endl;

    return 0;
}

