    }
    LL num=1;
    for(int i=0;i<2000000000;++i)num=num*5%MOD+MOD;
    ans=0;
    if(k&1){
        for(i=1;i<=n;++i){
            for(int l=head[i];~l;l=node[l].next){
                int e=node[l].to;
                if(e<=i)continue;
                int temp=ct(i,e,k/2)+ct(e,i,k/2);
                ans=max(ans,temp);
            }
        }
    }
    else{
        for(i=1;i<=n;++i){
            ans=max(ans,ct(i,-1,k/2));
        }
    }
    printf("%d\n",n-ans);
