int a[N],b[N],n,k,cnt;
void DFS(int u,int fa,int l) {
    if(l>k/2) cnt++;
    for(int i=0;i<vt[u].size();i++) {
        if(vt[u][i]==fa) continue;
        DFS(vt[u][i],u,l+1);
    }
}
int main() {
    scanf("%d%d",&n,&k);
    for(int i=1;i<n;i++) {
        scanf("%d%d",&a[i],&b[i]);
