    int ans=3000;
    for(int i=1;i<=n;i++) {
        cnt=0;
        if(k&1) {
            DFS(a[i],b[i],0);
            DFS(b[i],a[i],0);
        }
        else DFS(i,-1,0);
        ans=min(ans,cnt);
    }
    printf("%d\n",ans);
    return 0;
}

