int N,K;
int dist[SIZE];
int solve(int a,int b){
	REP(i,N+1) dist[i]=INF;
	queue<int> qu;
	int times=0;
	qu.push(a);
	dist[a]=0;
	if(a!=b){
		qu.push(b);
		dist[b]=0;
	}
	while(!qu.empty()){
		int now=qu.front();
		times++;
		qu.pop();
		if(dist[now]==K) continue;
		REP(i,edge[now].size()){
			int next=edge[now][i];
			if(dist[next]==INF){
				dist[next]=dist[now]+1;
				qu.push(next);
			}
		}
	}
	return N-times;
}
