	int minium=INF;
	FOR(i,1,N+1)
		minium=min(minium,solve(i,i));
	return minium;
}
int solveE(){
	int minium=INF;
	REP(i,N-1)
		minium=min(minium,solve(A[i],B[i]));
	return minium;
}
