pair<long long int, pair<long long int, long long int>> length( T tree ) {
	vector<long long int>D( N, LLONG_MAX / 6 );
	queue<long long int>que;
	que.push( 0 );
	D[0] = 0;
	long long int last = 0;
	while( que.size() ) {
		long long int now = que.front(); que.pop();
		for( auto i : tree[now] ) {
			if( D[i] > D[now] + 1 ) {
				D[i] = D[now] + 1;
				que.push( i );
				last = i;
			}
		}
	}
	que.push( last );
	D = vector<long long int>( N, LLONG_MAX / 6 );
	D[last] = 0;
	while( que.size() ) {
		long long int now = que.front(); que.pop();
		for( auto i : tree[now] ) {
			if( D[i] > D[now] + 1 ) {
				D[i] = D[now] + 1;
				que.push( i );
				last = i;
			}
		}
	}
	que.push( last );
	auto last2 = last;
	D = vector<long long int>( N, LLONG_MAX / 6 );
	D[last] = 0;
	while( que.size() ) {
		long long int now = que.front(); que.pop();
		for( auto i : tree[now] ) {
			if( D[i] > D[now] + 1 ) {
				D[i] = D[now] + 1;
				que.push( i );
				last = i;
			}
		}
	}
	return make_pair( D[last], make_pair( last, last2 ) );
}


