using namespace std;


class LCA {
public:
  LCA(const std::vector<std::vector<int>> &graph)
      : m_graph(graph),
        m_parent(graph.size(), std::vector<int>(12, -1)),
        m_depth(graph.size()) {
    dfs(0, -1, 0);
    for (int d = 1; (1<<d) < m_graph.size(); ++d) {
      for (int i = 0; i < m_graph.size(); ++i) {
        if (m_parent[i][d - 1] != -1) {
          m_parent[i][d] = m_parent[m_parent[i][d - 1]][d - 1];
        }
      }
    }
  }


  int query(int u, int v) {
    if (m_depth[u] < m_depth[v]) swap(u, v);

    for (int i = 11; i >= 0; --i) if(m_depth[u] - (1<<i) >= m_depth[v]) {
      u = m_parent[u][i];
    }

    if (u == v) return u;

    for (int i = 11; i >= 0; --i) if (m_parent[u][i] != -1 && m_parent[u][i] != m_parent[v][i]) {
        u = m_parent[u][i];
        v = m_parent[v][i];
    }
    return m_parent[u][0];
  }

private:
  void dfs(int v, int par, int d) {
    m_parent[v][0] = par;
    m_depth[v] = d;
    for (const int u : m_graph[v]) if (u != par) {
      dfs(u, v, d + 1);
    }
  }


  std::vector<std::vector<int>> m_graph;
  std::vector<std::vector<int>> m_parent;
  std::vector<int> m_depth;
};

int main() {
  int N, K;
  cin >> N >> K;

  std::vector<std::vector<int>> edges(N, std::vector<int>(0));
  for (int i = 0; i < N - 1; ++i) {
    int a, b;
    cin >> a >> b;
    a--, b--;
    edges[a].push_back(b);
    edges[b].push_back(a);
  }

  std::vector<int> dist(N, 100000);
  dist[0] = 0;
  std::queue<int> q; q.push(0);
  while (!q.empty()) {
    int v = q.front(); q.pop();
    for (const int w : edges[v]) {
      if (dist[v] + 1 < dist[w]) {
        q.push(w);
        dist[w] = dist[v] + 1;
      }
    }
  }

  std::set<int> leaves;
  for (int i = 0; i < N; ++i) {
    if (edges[i].size() == 1) {
      leaves.insert(i);
    }
  }

  int ans = -1;
  int cost = 10000;
  LCA lca(edges);
  for (const int v : leaves) {
    int c = 0;
    for (int i = 0; i < N; ++i) {
      // cout << v << ", " << i << ", " << dist[i] << "+" << dist[v] << "-"
      //      << 2 * dist[lca.query(i, v)] << endl;

      if (dist[i] + dist[v] - 2 * dist[lca.query(i, v)] > K) {
        c++;
      }
    }
    if (c < cost) {
      cost = c;
      ans = c;
    }
  }

  cout << ans << endl;
  return 0;
}

