void addedge(int u,int v)
{
	en++; e[en].v = v;
	e[en].nxt = fe[u]; fe[u] = en;
}

void dfs(int u)
{
	dp[u][0] = 1; f[u][0] = 1; mx[u] = 0; mx2[u] = e[fe[u]].v==fa[u] ? 1 : 0;
	for(int i=fe[u]; i; i=e[i].nxt)
	{
		if(e[i].v==fa[u]) continue;
		fa[e[i].v] = u;
		dfs(e[i].v);
		mx2[u] = max(mx2[u],mx[u]+1+mx[e[i].v]);
		for(int j=1; j<=mx2[u]; j++)
		{
			for(int k=0; k<mx2[u] && k<j; k++)
			{
				dp[u][j] = max(dp[u][j],sf[u][k]+sf[e[i].v][j-k-1]);
			}
		}
		mx[u] = max(mx[u],mx[e[i].v]+1);
		for(int j=1; j<=mx[u]; j++)
		{
			f[u][j] += f[e[i].v][j-1];
		}
		sf[u][0] = 1;
		for(int j=1; j<=mx[u]; j++) sf[u][j] = sf[u][j-1]+f[u][j];
	}
