int N, K;
const int NMAX = 2222;
vector<int> g0[NMAX];
vector<int> g[NMAX];

int sub[NMAX];
int h[NMAX];
int dp[NMAX][NMAX]; // dp[u][l]: cost of (to-root length = l)

int dfs1(int u, int fa){
	sub[u] = 1;
	h[u] = 0;
	for (int v : g0[u]) if (v != fa){
		g[u].push_back(v);
		sub[u] += dfs1(v, u);
		h[u] = max(h[u], h[v] + 1);
	}
	return sub[u];
}

void dfs2(int u){
	if (g[u].empty()) return;
	for (int v : g[u]) dfs2(v);
	dp[u][0] = sub[g[u][0]];

	for (int i = 1; i <= K; i++) dp[u][i] = dp[g[u][0]][i - 1];
	if (g[u].size() == 1) return;

	for (int i = 1; i < g[u].size(); i++){
		vector<int> now(K);
		int v = g[u][i];
		for (int j = 1; j < K; j++)
			now[j] = min(
			dp[v][j - 1] + dp[u][min(K - 1 - j, j - 1)],
			dp[u][j - 1] + dp[v][min(K - 1 - j, j - 1)]);
		for (int j = 1; j < K; j++) dp[u][j] = now[j];
		dp[u][0] += sub[v];
		dp[u][K] = min(dp[u][K] + sub[v], sub[u] - sub[v] - 1 + dp[v][K - 1]);
		for (int j = 1; j <= K; j++) dp[u][j] = min(dp[u][j - 1], dp[u][j]);
	}
}

