    for(int i = 1 ; i <= N ; ++i) {
	if(!vis[i] && dep[i] > dep[u]) {u = i;}
    }
    dep[u] = 0;fa[u] = 0;
    dfs(u);
    int D = 0,t;
    for(int i = 1 ; i <= N ; ++i) {
	if(!vis[i]) {
	    if(D < dep[i]) {
		D = dep[i];
		t = i;
	    }
	}
    }

    int p = t;
    while(dep[p] != D / 2 + 1) p = fa[p];
    if(D % 2 == 0) cen[0] = fa[p];
    else cen[0] = p,cen[1] = fa[p];
    return D;
}
