using namespace std;

struct edge{int to,cost; };
vector<edge> G[MAX_V];

bool used[MAX_V];
bool c[MAX_V][MAX_V];
int d[MAX_V];
int f[MAX_V][MAX_V];
int V;

void dfs(int s){
	used[s] = true;
	int i = 0;
	while(true){
		edge e = G[s][i];
		if(e.to==-1){
			break;
		}
		if(!used[e.to]){
			i++;
			used[e.to] = true;
			d[e.to] = d[s] + e.cost;
			dfs(e.to);
		}else{
			i++;
		}
	}
}

int main(){
	int i,j,k,g[MAX_V],mx,l,ans=0;
	cin >> V >> k;
	for(i=0;i<V-1;i++){
		int s,t;
		cin >> s >> t;
		s--; t--;
		edge e;
		e.to = t;
		e.cost = 1;
		G[s].push_back(e);
		e.to = s;
		e.cost = 1;
		G[t].push_back(e);
	}
	for(i=0;i<V;i++){
		edge e;
		e.to = -1; e.cost = 0;
		G[i].push_back(e);
	}
	for(i=0;i<V;i++){
		g[i] = 0;
		for(j=0;j<V;j++){
			c[i][j] = 0;
			used[j] = false;
		}
		d[i] = 0;
		dfs(i);
		for(j=0;j<V;j++){
			f[i][j] = d[j];
		}
	}

	for(i=0;i<V;i++){
		for(j=0;j<V;j++){
			if(f[i][j]>k){
				c[i][j] = false;
				g[i]++;
				g[j]++;
			}
		}
	}

	for(i=0;i<V;i++){
		mx = 0;
		for(j=0;j<V;j++){
			if(g[j]>mx){
				mx = g[j];
				l = j;
			}
		}
		if(mx==0){
			break;
		}
		for(j=0;j<V;j++){
			if(!c[j][l]){
				c[j][l] = true;
				g[l]--;
				g[j]--;
			}
			if(!c[l][j]){
				c[l][j] = true;
				g[l]--;
				g[j]--;
			}
		}
		ans++;
	}
	cout << ans << endl;
}

