int head[N],dp[N][N],sum[N][N],f[N][N],son[N],g[N],sz[N];

void add(int x,int y){
	num++;
	mem[num].to=y; mem[num].next=head[x];
	head[x]=num;
}

void dfs(int k,int pre){
	int j,u;
	g[k]=1; sz[k]=1;
	for (j=head[k];j;j=mem[j].next){
		u=mem[j].to;
		if (u==pre) continue;
		dfs(u,k);
		sz[k]+=sz[u];
		d=max(d,g[k]+g[u]);
		g[k]=max(g[k],g[u]+1);
	}
}

void dfs1(int k,int pre){
	int j,u,i,l,cnt=0;
	dp[k][0]=1; dp[k][1]=0;
	for (j=head[k];j;j=mem[j].next){
		u=mem[j].to;
		if (u==pre) continue;
		dfs1(u,k);
	}
	for (j=head[k];j;j=mem[j].next){
		u=mem[j].to;
		if (u==pre) continue;
		son[++cnt]=u;
		dp[k][0]+=dp[u][0]; dp[k][1]+=dp[u][0];
		for (i=0;i<=m;i++)
			if (dp[u][i]!=inf) sum[k][i]+=dp[u][i];
	}
	for (i=1;i<=m;i++){
		l=min(i-1,m-i);
		for (j=1;j<=cnt;j++) if (dp[son[j]][i-1]!=inf){
			u=son[j];
			if (dp[u][l]==inf) w=0;
			else w=dp[u][l];
			dp[k][i]=min(dp[k][i],dp[u][i-1]+sum[k][l]-w);
		}
	}
}

void dfs2(int k,int pre){
	int j,u,i,l,cnt=0;
	for (i=0;i<=m;i++) ans=min(ans,dp[k][i]+f[k][m-i]);
	f[k][0]=n-sz[k];
	for (i=0;i<=m;i++)
		if (f[k][i]!=inf) sum[k][i]+=f[k][i];
	for (j=head[k];j;j=mem[j].next){
		u=mem[j].to;
		if (u==pre) continue;
		son[++cnt]=u;
	}
	for (i=1;i<=m;i++){
		l=min(i-1,m-i); mn=inf;
		if (f[k][i-1]!=inf){
			mn=f[k][i-1];
			if (f[k][l]!=inf) mn-=f[k][l];
		}
		now=mn;
		for (j=1;j<=cnt;j++){
			u=son[j];
			if (now!=inf) f[u][i]=now+sum[k][l]-dp[u][l];
			if (dp[u][i-1]!=inf){
				if (dp[u][l]!=inf) now=min(now,dp[u][i-1]-dp[u][l]);
				else now=min(now,dp[u][i-1]);
			}
		}
		now=mn;
		for (j=cnt;j>=1;j--){
			u=son[j];
			if (now!=inf) f[u][i]=min(f[u][i],now+sum[k][l]-dp[u][l]);
			if (dp[u][i-1]!=inf){
				if (dp[u][l]!=inf) now=min(now,dp[u][i-1]-dp[u][l]);
				else now=min(now,dp[u][i-1]);
			}
		}
	}
	for (j=head[k];j;j=mem[j].next){
		u=mem[j].to;
		if (u==pre) continue;
		dfs2(u,k);
	}
}

