#include<bits/stdc++.h>
using namespace std;

const int maxn=2000+7;

int n,K,ans=0;
int head[maxn],cnt=0,depth[maxn];
int siz[maxn],root=0,root2=0;
struct Edge{int nxt,to,dis;}edge[maxn*2];
bool vis[maxn];

void add(int from,int to,int dis){
	edge[++cnt].nxt=head[from];edge[cnt].to=to;edge[cnt].dis=dis;head[from]=cnt;	
}
void dfs1(int u,int fa,int num){
	siz[u]=1;
	for(int i=head[u];i!=0;i=edge[i].nxt){
		int v=edge[i].to;if(v==fa)continue;
		dfs1(v,u,num);siz[u]+=siz[v];
	}
	if(num==1)if(siz[u]>=n/2&&root==0)root=u;
	if(num==2)if(siz[u]>=n/2&&root2==0)root2=u;
	return;
}
void dfs2(int u,int fa){
	depth[u]=depth[fa]+1;
	for(int i=head[u];i!=0;i=edge[i].nxt){
		int v=edge[i].to;if(v==fa)continue;
		dfs2(v,u);
	}return;
}
void dfs3(int u,int fa){
	depth[u]=depth[fa]+1;
	for(int i=head[u];i!=0;i=edge[i].nxt){
		int v=edge[i].to;
		if(depth[v]>depth[u]+1){
			dfs3(v,u);
		}
	}
}
int main(){
	scanf("%d%d",&n,&K);
	for(int i=1;i<n;i++){
		int x,y;scanf("%d%d",&x,&y);
		add(x,y,1);add(y,x,1);
	}
	root=0;root2=0;dfs1(1,1,1);
	if(K%2)memset(siz,0,sizeof(siz)),dfs1(root,root,2);

	//cout<<root<<' '<<root2<<endl;
	if(K%2==0){
		dfs2(root,root);
		for(int i=1;i<=n;i++)if(depth[i]>1+K/2)ans++;
		printf("%d\n",ans);return 0;
	}else{
		if(root==root2)root2=edge[head[root]].to;
		//cout<<root<<' '<<root2<<endl;
		dfs2(root,root);
		depth[root2]=0;dfs3(root2,root2);
		K--;
		for(int i=1;i<=n;i++)if(depth[i]>1+K/2)ans++;
		printf("%d\n",ans);
	}
	return 0;
}
