using namespace std;

long N, K;
vector<long> way[2001];
long dis[2001];

map<set<long>, long> memo;


void caldis(long pa, long po, set<long> remove){
	//cout << "pa=" << pa << "po " << po << endl;
	for(int i = 0; i < way[po].size(); i++){
		if(way[po][i] != pa && remove.count(way[po][i]) == 0){
			dis[way[po][i]] = dis[po] + 1;
			caldis(po, way[po][i], remove);
		}
	}
}


pair<long, long> getp(set<long> remove){
	for(int i = 0; i < N; i++){
		dis[i] = INT_MAX/3;
	}

	for(int i = 0; i < N; i++){
		if(remove.count(i) == 0){
			dis[i] = 0;
			caldis(-1, i, remove);
			break;
		}
	}
	//cout << "debug0 " << endl;
	long fpoint, fcost = 0;
	long spoint, scost = 0;
	for(int i = 0; i < N; i++){
		//cout << fpoint << "->" << i << "=" << dis[i] << endl;
		if(fcost < dis[i] && remove.count(i) == 0){
			fpoint = i;
			fcost = dis[i];
		}
	}


	for(int i = 0; i < N; i++){
		dis[i] = INT_MAX/3;
	}

	dis[fpoint] = 0;
	caldis(-1, fpoint, remove);

	for(int i = 0; i < N; i++){
		//cout << fpoint << "->" << i << "=" << dis[i] << endl;
		if(scost < dis[i]&& remove.count(i) == 0){
			spoint = i;
			scost = dis[i];
		}
	}
	if(scost <= K){
		return make_pair(0,0);
	}
	return make_pair(fpoint, spoint);
}


long dfs(set<long>remove){
	if(memo.count(remove) != 0){
		return memo[remove];
	}
	//cout << "remove size = " << remove.size() << endl;
	//cout << "dfs " << endl;
	pair<long, long> p;
	p = getp(remove);
	//cout << p.first << "," << p.second << endl;
	if(p.first == 0 && p.second == 0){
		return remove.size();
	}
	long ret = INT_MAX/3;

	remove.insert(p.first);
	ret = min(ret, dfs(remove));

 	remove.erase(p.first);
	remove.insert(p.second);
	ret = min(ret, dfs(remove));

	memo[remove] = ret;
	return ret;
}


