	cin >> N >> K;
	for(int i = 0; i < N - 1; i++){
		long a, b;
		cin >> a >> b;
		a--;b--;
		way[a].push_back(b);
		way[b].push_back(a);
	}
	set<long> remove;
	cout << dfs(remove) << endl;;
}

