vector<int> adj[2005];

int n;
int k;
bool vis[2005];
int lala[2005];

int bfs(int x){
	memset(vis,0,sizeof(vis));
	memset(lala,0,sizeof(lala));
	vis[x] = 1;
	queue<int> qx,qy;
	qx.push(x);
	qy.push(0);
	int tmp = 0;
	int ret = 1;
	while(!qx.empty()){
		int pan = qx.size();
		tmp++;
		if(tmp>k/2) break;
		while(pan--){
			int nx = qx.front(); qx.pop();
			int ny = qy.front(); qy.pop();
			for(int i=0;i<adj[nx].size();i++){
				int cx = adj[nx][i];
				int cy = ny;
				if(tmp == 1) cy = i;
				if(vis[cx]) continue;
				vis[cx] = 1;
				ret++;
				qx.push(cx);
				qy.push(cy);
			}
		}
	}
	int ma = 0;
	while(!qy.empty()){
		lala[qy.front()]++;
		ma = max(ma,lala[qy.front()]);
		qy.pop();
	}
	if(k%2==1) ret+=ma;
	return ret;
}

