#include<algorithm>
using namespace std;

int n,k1,d[2000][2000];
vector<int> g[2000];
bool f[2000];

int dfs(int u,int v){
	f[v]=true;
	if(d[u][v]>k1){
		return 0;
	}else if(d[u][v]==k1){
		return 1;
	}
	int r=1;
	for(int j=0;j<g[v].size();++j){
		int w=g[v][j];
		if(f[w]){
			continue;
		}
		d[u][w]=d[u][v]+1;
		r+=dfs(u,w);
	}
	return r;
}

int main(){
	int k,ans=1;
	cin>>n>>k;
	for(int j=0;j<n-1;++j){
		int a,b;
		cin>>a>>b;
		g[--a].push_back(--b);
		g[b].push_back(a);
	}
	if(k%2==0){
		k1=(k+1)/2;
		for(int v=0;v<n;++v){
			d[v][v]=0;
			fill(f,f+n,false);
			ans=max(ans,dfs(v,v));
		}
	}else{
		for(int v=0;v<n;++v){
			int a=0,b=0;
			vector<int> V;
			fill(f,f+n,false);
			f[v]=true;
			k1=(k-1)/2;
			for(int j=0;j<g[v].size();++j){
				d[v][g[v][j]]=1;
				V.push_back(dfs(v,g[v][j]));
				a+=V[j];
			}
			fill(f,f+n,false);
			f[v]=true;
			++k1;
			for(int j=0;j<g[v].size();++j){
				b=max(dfs(v,g[v][j])-V[j],b);
			}
			a+=(b+1);
			ans=max(ans,a);
		}
	}
	cout<<n-ans<<endl;
}

#include<bits/stdc++.h>
#define int long long int
#define PB push_back
using namespace std;
const int INF = 3643648101919114514;
typedef vector<int> VI;

int n, k, a[2010], b[2010];
int ans = 0;
VI node[2010];

int solve(int now, int pre, int times)
{
  if(times == k / 2){
    return 1;
  }
  else{
    int ret = 0;
    for(auto pt:node[now])
      if(pt != pre)
	ret += solve(pt, now, times + 1);
    return ret + 1;
  }
}

signed main()
{
  cin >> n >> k;
  for(int i = 1; i <= n - 1; i++)
    cin >> a[i] >> b[i];

  for(int i = 1; i <= n - 1; i++){
    node[a[i]].PB(b[i]);
    node[b[i]].PB(a[i]);
  }

  if(k % 2)
    for(int i = 1; i <= n - 1; i++)
      ans = max(ans, solve(a[i], b[i], 0) + solve(b[i], a[i], 0));
  else
    for(int i = 1; i <= n; i++)
      ans = max(ans, solve(i, -1, 0));

  cout << n - ans << endl;
