using namespace std;
template<class T, class T2> inline void chkmax(T &x, const T2 &y) { if(x < y) x = y; }
template<class T, class T2> inline void chkmin(T &x, const T2 &y) { if(x > y) x = y; }
const int MAXN = (1 << 20);

int n, k;
vector<int> adj[MAXN];
int dep[MAXN];

void read()
{
	cin >> n >> k;
	for(int i = 0; i < n - 1; i++)
	{
		int u, v;
		cin >> u >> v;
		adj[u].push_back(v);
		adj[v].push_back(u);
	}
}

void dfs_visit(int u, int pr = -1, int d = 0)
{
	chkmin(dep[u], d);
	for(int v: adj[u])
		if(v != pr)
			dfs_visit(v, u, d + 1);
}

int solve_vertex(int u)
{
	for(int i = 1; i <= n; i++) dep[i] = n + 1;
	dfs_visit(u);

	int cnt = 0;
	for(int i = 1; i <= n; i++)
		if(dep[i] <= k / 2) 
			cnt++;

	return n - cnt;
}

int solve_edge(int u, int v)
{
	for(int i = 1; i <= n; i++) dep[i] = n + 1;
	dfs_visit(u);
	dfs_visit(v);

	int cnt = 0;
	for(int i = 1; i <= n; i++)
		if(dep[i] <= k / 2) 
			cnt++;

	return n - cnt;
}


void solve()
{
	int answer = n;
	if(k % 2 == 1)
		for(int i = 1; i <= n; i++)
			for(int j: adj[i])
				chkmin(answer, solve_edge(i, j));
	else
		for(int i = 1; i <= n; i++)
			chkmin(answer, solve_vertex(i));

	cout << answer << endl;
}

int main()
{
	ios_base::sync_with_stdio(false);
	cin.tie(NULL);

	read();
	solve();
	return 0;
}

