int n,m;

int bfs(int i)
{
  int r=INT_MAX;
  bitset<2005> hsh;
  queue<pair<int,int> > q;

  hsh[i]=true;
  for(int c=0;c<gph[i].size();c++)
  {
    int rem=gph.size()-1-1;
    q.push(mkp(gph[i][c],1));
    while(!q.empty())
    {
      if (!hsh[q.front().node]&&q.front().cost<=m)
      {
        hsh[q.front().node]=true;
        rem--;
        for(int c2=0;c2<gph[q.front().node].size();c2++)
        q.push(mkp(gph[q.front().node][c2],q.front().cost+1));
      }
      q.pop();
    }
    r=min(r,rem);
  }
  return r;
}

