bool dchk[2050];
int N, K;
int dp[2050][2050];
int sz[2050];

int tdp1[2050];
int tdp2[2050];
void DFS(int n) {
	dchk[n] = true;
	sz[n] = 1;
	for (auto it : conn[n]) {
		if (dchk[it]) continue;
		son[n].push_back(it);
		DFS(it);
		sz[n] += sz[it];
	}

	for (int i = 0; i <= K; i++) tdp1[i] = 0;
	for (auto it : son[n]) {
		for (int i = 0; i <= K; i++) tdp2[i] = tdp1[i] + sz[it];
		for (int i = 1; i <= K; i++) {
			// max(a, b+1) = i

			int a, b;
			a = i, b = min(i - 1, K - 1 - a);
			if (b >= 0) tdp2[i] = min(tdp2[i], tdp1[a] + dp[it][b]);

			b = i - 1, a = min(i, K - 1 - b);
			tdp2[i] = min(tdp2[i], tdp1[a] + dp[it][b]);
		}
		for (int i = 1; i <= K; i++) tdp2[i] = min(tdp2[i - 1], tdp2[i]);
		for (int i = 0; i <= K; i++) tdp1[i] = tdp2[i];
	}
	for (int i = 0; i <= K; i++) dp[n][i] = tdp1[i];
}
int main() {
