	scanf("%d %d", &N, &K);
	for (i = 1; i < N; i++) {
		int t1, t2;
		scanf("%d %d", &t1, &t2);
		conn[t1].push_back(t2);
		conn[t2].push_back(t1);
	}
	DFS(1);

	int ans = N;
	for (i = 1; i <= N; i++) ans = min(ans, N - sz[i] + dp[i][K]);
	return !printf("%d\n", ans);
}

