    --A, --B;
    graph[A].push_back(B);
    graph[B].push_back(A);
  }

  int ptr = 0, k;
  while((k = Diameter()) > K) {
    vector< int > a(N), b(N);
    a[curr.first] = b[curr.second] = 0;
    dfs2(a, curr.first);
    dfs2(b, curr.second);
    int poyo[3003] = {}, poyo2[3003] = {};
    for(int i = 0; i < N; i++) poyo[a[i]]++;
    for(int i = N - 1; i >= 0; i--) poyo[i] += poyo[i + 1];
    for(int i = 0; i < N; i++) poyo2[b[i]]++;
    for(int i = N - 1; i >= 0; i--) poyo2[i] += poyo2[i + 1];
    if(poyo[k] > poyo2[k]) live[curr.first] = true;
    else live[curr.second] = true;
    ++ptr;
  }
  cout << ptr << endl;
}

