	for(int r = 0; r < n; ++r){
		auto &row = mat[r];
		queue<int> q;
		row[r] = 0;
		q.push(r);
		while(!q.empty()){
			const int u = q.front();
			q.pop();
			for(const int v : conn[u]){
				if(row[v] < INF){ continue; }
				row[v] = row[u] + 1;
				q.push(v);
			}
		}
	}
	int answer = INF;
	if(k % 2 == 1){
		for(int u = 0; u < n; ++u){
			for(const int v : conn[u]){
				int count = 0;
				for(int i = 0; i < n; ++i){
					if(mat[u][i] + mat[v][i] <= k){ ++count; }
				}
				answer = min(answer, n - count);
			}
		}
	}else{
		for(int i = 0; i < n; ++i){
			int count = 0;
			for(int j = 0; j < n; ++j){
				if(mat[i][j] <= k / 2){ ++count; }
			}
			answer = min(answer, n - count);
		}
	}
	cout << answer << endl;
	return 0;
}

