struct edge{int to,next;}e[2*maxm];
int tot,last[maxn];
inline void add(int x,int y)
{
    e[++tot]=(edge){y,last[x]};
    last[x]=tot;
}
inline int read()
{
    int re=0,x=1;char c='^';
    for(;!isdigit(c);c=getchar())if(c=='-')x=-1;
    for(;isdigit(c);c=getchar())re=(re<<3)+(re<<1)+c-'0';
    return re*x;
}
int n,k,ans=(1<<29),sum=0,cnt;
int deep[maxn],fa[maxn],first[maxn];
int st[2*maxn][21];
inline void dfs(int x)
{
    st[++cnt][0]=x;first[x]=cnt;
    for(int i=last[x],y=e[i].to;i;i=e[i].next,y=e[i].to)
        if(fa[x]!=y)
        {
            fa[y]=x;deep[y]=deep[x]+1;
            dfs(y);
            st[++cnt][0]=x;
        }
}
inline int st_max(int x,int y)
{
    if(deep[x]<=deep[y])return x;
    else return y;
}
inline void st_maker()
{
    for(int j=1;j<=21;j++)
        for(int i=1;i+(1<<(j-1))-1<=2*n;i++)
            st[i][j]=st_max(st[i][j-1],st[i+(1<<(j-1))][j-1]);
}
inline int query(int x,int y)
{
    x=first[x];y=first[y];
    if(x>y)swap(x,y);int z=log2(y-x+1);
    return st_max(st[x][z],st[y-(1<<z)+1][z]);
}
inline int leth(int x,int y)
{
    int lca=query(x,y);
    return deep[x]+deep[y]-(deep[lca]<<1);
}
