        q.pop();

        pt.pb(p1);
        cnt[d[p1]]++;

        for(int p2 : graf[p1]) {
            if(d[p2] > d[p1] + 1) {
                d[p2] = d[p1] + 1;
                q.push(p2);
            }
        }
