    cnt[0] = 0;
    FOR(i, 1, n) {
        if(cnt[i] == 0) break;
        cnt[i] += cnt[i - 1];
        kek = cnt[i];
    }
    paii p = {cnt[k / 2 - 1], cnt[k / 2]};
    if(p.fr == 0) p.fr = kek;
    if(p.sc == 0) p.sc = kek;
    loop(i, n) {
        if(cnt[i] == 0) break;
        cnt[i] = 0;
    }
    for(int c : pt) d[c] = inf;
    return p;
}

void solve() {
    loop(i, MAXN) d[i] = inf;
    loop(i, MAXN) cnt[i] = 0;
    cin >> n >> k;
    loop(i, n - 1) {
        int a, b;
