        --a, --b;
        graf[a].pb(b);
        graf[b].pb(a);
    }
    int ans = 0;
    loop(p1, n) {
        //cout << p1 + 1 << ": " << endl;
        vec<paii> t;
        for(int p2 : graf[p1]) {
            t.pb(bfs(p2, p1));
        }
        if(k % 2 == 1) {
            int sum = 1;
            for(paii p : t) sum += p.sc;
            ans = max(ans, sum);
        } else {
            int sum = 1;
            for(paii p : t) sum += p.fr;
            for(paii p : t) {
                int k = sum - p.fr + p.sc;
                ans = max(ans, k);
            }
        }
        //cout << endl;
    }
    cout << n - ans << endl;
}

