diam getD(){
    for(int i=0;i<n;i++){
        if(!del[i]){
            maxi = 0;
            dfs(i,i,0);
            break;
        }
    }
    int a = far;
    dfs(a,a,0);
    int b = far;
    diam ret;
    ret.a = a;
    ret.b = b;
    return ret;
}
int target , Dis= -1;
void dis(int node,int p,int sum){
    if(node == target){
        Dis = sum;
        return;
    }
    if(Dis != -1)return;
    for(int i=0;i<v[node].size();i++){
        int u = v[node][i];
        if(u!=p){
            dis(u,node,sum+1);
        }
    }
}
