void dijkstra(int s) {
  dist[s][s]=0;
  priority_queue<P, vector<P>, greater<P> > pq;
  pq.push(P(0, s));
  while(!pq.empty()) {
    P p = pq.top();pq.pop();
    int v =p.second;
    if(dist[s][v]<p.first) continue;
    rep(i, G[v].size()) {
      edge e = G[v][i];
      if (dist[s][e.to] > dist[s][v]+e.cost) {
        dist[s][e.to]=dist[s][v]+e.cost;
        pq.push(P(dist[s][e.to], e.to));
      }
    }
  }
}
