const int MAXN = 2010;
int n, K, e, Begin[MAXN], ans;
int to[MAXN<<1], Next[MAXN<<1];
int fa[MAXN];

inline int read() {
	int x = 0, f = 1;
	char ch = getchar();
	for(; !isdigit(ch); ch = getchar()) if(ch=='-') f=-1;
	for(; isdigit(ch); ch = getchar()) x = (x<<1)+(x<<3)+(ch^48);
	return x * f;
}

inline void Add(int u, int v) {
	to[++e] = v, Next[e] = Begin[u];
	Begin[u] = e;
}

int dfs(int u, int K) {
	if(K == 0) return 1;
	int i, res = 1;
	for(i = Begin[u]; i; i = Next[i]) {
		if(to[i] == fa[u]) continue;
		fa[to[i]] = u;
		res += dfs(to[i], K-1);
	}
	return res;
}

int main() {
	int i;
	n = read(), K = read();
	for(i = 1; i < n; i++) {
		int u = read(), v = read();
		Add(u, v), Add(v, u);
	}
	ans = n;
	if(K & 1) {
		for(i = 1; i < n; i++) {
			int x = to[(i<<1)-1], y = to[i<<1];
			fa[x] = y, fa[y] = x;
			ans = min(ans, n-dfs(x, K>>1)-dfs(y, K>>1));
		}
	}
	else {
		for(i = 1; i <= n; i++) {
			fa[i] = 0;
			ans = min(ans, n-dfs(i, K>>1));
			printf(":%d\n", ans);
		}
	}
	printf("%d\n", ans);
	return 0;
}

