void dfs(int x, int pa) {
	for (auto t : g[x]) if (t != pa) {
		dfs(t, x);
		c[x].push_back(t);
	}

	if (c[x].size() == 0) {
		res[x][0] = 1;
		for (int i = 1; i <= m; i ++) 
			res[x][i] = 0;
		return;	
	}

	res[x][0] = 1;
	for (int t : c[x]) {
		res[x][0] += res[t][0];
	}
	for (int h = 1; h <= m; h ++) {
		int fi = h - 1, sc = min(fi, m - h);
		if (c[x].size() == 1) {
			res[x][h] = res[c[x][0]][fi];
			continue;
		}
		int s = 0, d = 0;
		for (int t : c[x]) {
			s += res[t][sc];
			d = max(d, res[t][sc] - res[t][fi]);
		}
		res[x][h] = min(res[x][h - 1], s - d);
	}
}


