constexpr int nax = 2e3;

using namespace std;
using Graph = array< vector< int >, nax + 1 >;
using Ain = array< int, nax + 1 >;

struct Dfs
{
    const int n, r;
    const Graph& gr;
    Dfs(const int n, const int r, const Graph& gr) : n(n), r(r), gr(gr) {}

    Ain gl{}, kd{};

    pair< Ain, Ain > operator()()
    {
        for (int s : gr[r])
            dfs(s, r, s);

        return make_pair(gl, kd);
    }

    void dfs(int v, int oj, int f)
    {
        ++kd[f];
        gl[v] = gl[oj] + 1;
        for (int s : gr[v])
            if (s != oj)
                dfs(s, v, f);
    }

};

int analyze(const int n, const int k, const Ain& gl, const Ain& kd)
{
    int len = (k / 2);
    int cnt = 0;
    for (int i = 1; i <= n; ++i)
        if (gl[i] > len)
            ++cnt;

    if (k & 1)
    {
        Ain zl{};

        for (int i = 1; i <= n; ++i)
            if (gl[i] == len + 1)
                ++zl[kd[i]];

        cnt -= *max_element(begin(zl), end(zl));
    }

    return cnt;
}

int solve(const int n, const int k, const Graph& gr)
{
    if (k == 1) return n - 2;

    int res = n;
    for (int i = 1; i <= n; ++i)
    {
        Ain gl, kd;
        tie(gl, kd) = Dfs(n, i, gr)();

        //cout << i << ": ";
        //for (int i = 1; i <= n; ++i)
            //cout << gl[i] << ' ';
        //cout << '\n';


        res = min(res, analyze(n, k, gl, kd));
    }
    return res;
}


