int main(void) {
    int n,k;
    scanf("%d", &n); scanf("%d", &k);
    vector< vector<int> > graph;
    vector<int> degree(n,0);
    graph.resize(n);

    for (int i = 0; i < n; i++) {
        graph[i].resize(n);
    }
    for (int i = 0; i<n; i++) {
        for (int j=0; j<n; j++) {
            graph[i][j] = 0;
        }
    }

    for (int i =0; i < n-1; i++) {
        int x,y;
        scanf("%d %d", &x, &y);
        graph[x-1][y-1] = 1; graph[y-1][x-1] = 1;
        degree[x-1]++; degree[y-1]++;
    }
    queue<int> leafs;
    for (int i=0; i<n; i++) {
        if (degree[i] == 1) {
            leafs.push(i);
        }
    }

    int root, dist, node, num_delete_nodes;
    int ans= n+10;
    vector<int> distance(n,n+10);
    vector<int> visited(n,0);
    while (!leafs.empty()) {
        root = leafs.front();
        leafs.pop();
        // BFS(root);

        // 初期化　始まり
        dist = 0;
        num_delete_nodes = 0;
        for (int i=0; i<n; i++) {
            visited[i] = 0;
            distance[i] = n+10;
        }
        visited[root] = 1;
        queue<int> dfs;
        dfs.push(root);
        distance[root] = 0;
        // 初期化終わり

        // BFS main loop
        while(!dfs.empty()) {
            node = dfs.front();
            dfs.pop();
            for (int i=0; i<n; i++) {
                if(graph[node][i] == 1) {
                    if(visited[i] == 0) {
                        visited[i] = 1;
                        dfs.push(i);
                        distance[i] = distance[node]+1;
                    }
                }
            }
        }

        for (int i=0; i<n; i++) {
            if (distance[i] > k) {
                num_delete_nodes++;
            }
        }
        //printf("distance: %d\n",num_delete_nodes);
        if (ans >= num_delete_nodes) {
            ans = num_delete_nodes;
        }
    }
    printf("%d\n", ans);
    return 0;
}

