int main() {

	ll N, K;
	cin >> N >> K;

	vector<vector<ll>> g(N + 1);

	repn(i, N-1) {
		ll a, b;
		cin >> a >> b;
		g[a].push_back(b);
		g[b].push_back(a);
	}

	ll ans = INF;

	repn(v, N) {
		for (ll w : g[v]) {
			vector<ll> dis(N + 1,-1);
			queue<ll> q;
			q.push(w);
			dis[v] = 0;
			dis[w] = 1;

			while (!q.empty()) {
				ll u = q.front();
				q.pop();
				for (ll x : g[u]) {
					if (dis[x] != -1) { continue; }
					dis[x] = dis[u] + 1;
					q.push(x);
				}
			}

			ll t = 0;
			repn(v, N) {
				if (dis[v] >= K + 1||dis[v]==-1) { t++; }
			}
			ans = min(t, ans);
		}
	}

	cout << ans;

	system("PAUSE");
}

