using namespace std;
const int N=2005;
const int M=4005;
int n,i,k,u,v;
int h[N],nx[M],to[M],cnt;
int f[N][N],g[N][N],ans;
void addedge(int u,int v)
{
	cnt++;
	to[cnt]=v;
	nx[cnt]=h[u];
	h[u]=cnt;
}
void up(int u,int p)
{
	f[u][0]=1;
	for (int i=h[u];i;i=nx[i])
		if (to[i]!=p)
		{
			up(to[i],u);
			for (int j=0;f[to[i]][j];j++)
				f[u][j+1]+=f[to[i]][j];
		}
}
void down(int u,int p)
{
	for (int j=0;f[u][j];j++)
		g[u][j]+=f[u][j];
	for (int i=h[u];i;i=nx[i])
		if (to[i]!=p)
		{
			for (int j=0;g[u][j];j++)
				g[to[i]][j+1]+=g[u][j]-(j-1>=0?f[to[i]][j-1]:0);
			down(to[i],u);
		}
}
void getans(int u,int p)
{
	if ((k&1)^1)
	{
		int t=0;
		for (int i=0;i<=k/2;i++)
			t+=g[u][i];
		if (n-t<ans)
			ans=n-t;
	}
	for (int i=h[u];i;i=nx[i])
		if (to[i]!=p)
		{
			getans(to[i],u);
			if (k&1)
			{
				int t=0;
				for (int j=0;j<=k/2;j++)
					t+=f[to[i]][j];
				for (int j=0;j<=k/2;j++)
					t+=g[u][j]-(j-1>=0?f[to[i]][j-1]:0);
				if (n-t<ans)
					ans=n-t;
			}
		}
}
int main()
{
	scanf("%d%d",&n,&k);
	for (i=1;i<n;i++)
	{
		scanf("%d%d",&u,&v);
		addedge(u,v);
		addedge(v,u);
	}
	ans=n;
	up(1,0);
	down(1,0);
	getans(1,0);
	printf("%d\n",ans);
	return 0;
}

