void bfs(int s){
	queue<int> q;
	q.push(s);
	dist[s][s] = 0;
	while (!q.empty()) {
		int from = q.front();
		q.pop();
		for(auto to: edge[from]){
			if(dist[s][to]==-1){
				q.push(to);
				dist[s][to] = dist[s][from]+1;
			}
		}
	}
	return;
}

