void DFS(int cur, int fa, int deep)
{
	dep[cur] = deep;
	for(vector<int>::iterator itr = Adj[cur].begin(); itr != Adj[cur].end(); ++itr)
		if(*itr != fa)
			DFS(*itr, cur, deep + 1);
}

int main()
{
