		if (v==f) continue;
		dfs1(v,x,d+1);
	}
}
void find(int x,int f){
	if (deep[x]==(k/2)+1) ++kkk;
	if (deep[x]>=(k/2)+1) return;
	for (int i=first[x];i;i=next[i]){
		int v=get[i];
		if (v==f) continue;
		find(v,x);
	}
}
