  rep(i,N) dist[i] = -1;
  queue< pair<int,int> > que;
  que.push(make_pair(v,0));
  int mx = -1;
  while(!que.empty()){
    pair<int,int> p = que.front(); que.pop();
    if(dist[p.first] != -1) continue;
    dist[p.first] = p.second;
    if(dist[p.first]>K) ret++;
    mx = max(mx, dist[p.first]);
    rep(i,G[p.first].size()){
      if(dist[G[p.first][i]]==-1) que.push(make_pair(G[p.first][i],p.second+1));
    }
  }

  return ret;
}

vector<int> solve(int v){
  rep(i,N) dist[i] = -1;
  queue< pair<int,int> > que;
  que.push(make_pair(v,0));
  int mx = -1;
  while(!que.empty()){
    pair<int,int> p = que.front(); que.pop();
    if(dist[p.first] != -1) continue;
    dist[p.first] = p.second;
    mx = max(mx, dist[p.first]);
    rep(i,G[p.first].size()){
      if(dist[G[p.first][i]]==-1) que.push(make_pair(G[p.first][i],p.second+1));
    }
  }
  vector<int> ret;
  rep(i,N){
    if(dist[i] == mx) ret.push_back(i);
  }
  return ret;
}

