struct state {
    int pos, dist;
    state() {}
    ~state() {}
    state(int pos, int dist): pos(pos), dist(dist) {}
};

int N, K;

vector<vector<int>> graph;
vector<int> active, dists;

int bfs(int v) {
    queue<state> que;
    fill(begin(dists), end(dists), inf);
    dists[v] = 0;
    que.emplace(v, 0);

    int ret = 0;
    while (!que.empty()) {
        state st = que.front(); que.pop();
        ret = st.dist;
        for (int w: graph[st.pos]) {
            if (!active[w]) continue;
            const int ndist = st.dist + 1;
            if (dists[w] > ndist) {
                dists[w] = ndist;
                que.emplace(w, ndist);
            }
        }
    }
    return ret;
}

int main() {
