	if(k % 2 == 0){

		//Each Vertex
		for(int i = 0; i < n; i++){
			int covered = bfs(adj, i, k / 2, -1);
			maxC = max(maxC, covered);
		}

	}else{

		//Each edge
		for(int i = 0; i < n; i++){

			for(int v : adj[i]){

				int c1 = bfs(adj, i , k / 2, v);
