const int MAXN = 2005;
const int INF = 1e9;

int n, k;
int diam[MAXN], dist[MAXN], lvl[MAXN], sz[MAXN];
int dp[MAXN][MAXN];
vi gr[MAXN];
int ans = 0;

void init(int u, int par) {
    int other = 0;
    sz[u] = 1;
    for (auto v : gr[u]) {
        if (v == par) continue;
        lvl[v] = lvl[u] + 1;
        init(v, u);
        diam[u] = max(diam[u], diam[v]);
        if (dist[v] + 1 > dist[u]) {
            other = dist[u];
            dist[u] = dist[v] + 1;
        } else if (dist[v] + 1 > other) {
            other = dist[v] + 1;
        }
        dist[u] = max(dist[u], dist[v] + 1);
        sz[u] += sz[v];
    }
    diam[u] = max(diam[u], dist[u] + other);
}

void dfs(int u, int par) {
    for (auto v : gr[u]) {
        if (v == par) continue;
        dfs(v, u);
    }
    dp[u][0] = sz[u] - 1;
    for (int l = 1; l <= k; l++) {
        dp[u][l] = dp[u][l - 1];
        int sum = 0, best = INF;
        for (auto v : gr[u]) {
            if (v == par) continue;
            int num = (k - l - 1 < 0 ? sz[v] : dp[v][k - l - 1]);
            sum += num;
            best = min(best, -num + dp[v][l - 1]);
        }
        sum += best;
        dp[u][l] = min(dp[u][l], sum);
    }
}

int main() {
    //freopen("", "r", stdin);
    //freopen("", "w", stdout);
    scanf("%d %d", &n, &k);
    for (int i = 1; i < n; i++) {
        int u, v;
        scanf("%d %d", &u, &v);
        gr[u].pb(v);
        gr[v].pb(u);
    }
    init(1, 0);
    dfs(1, -1);
    ans = INF;
    for (int l = 0; l <= k; l++)
        ans = min(ans, dp[1][l]);
    printf("%d\n", ans);
    return 0;
}

