Graph<int, MAXN> g;

pair <int, int> dfs(int v, int k) {
    used[v] = true;
    if (k == 0) {
        return {0, 1};
    }

    pair <int, int> res = {1, 0};

    for (int& to : g[v]) {
        if (!used[to]) {
            auto it = dfs(to, k - 1);
            res.first += it.first;
            res.second += it.second;
        }
    }
    return res;
};

