using namespace std;

long N, K;
long dis[2001][2001];

map<set<long>, long> memo;


void caldis(){
	for(int k = 0; k < N; ++k)
		for(int i = 0; i < N; ++i)
			for(int j = 0; j < N; ++j) dis[i][j] = min(dis[i][j], dis[i][k] + dis[k][j]);
}


pair<long, long> getp(set<long> remove){
	long fpoint, spoint, mdis = 0;
	for(int i = 0; i < N; i++){
		for(int j = 0; j < N; j++){
			if(mdis < dis[i][j] && remove.count(i) == 0 && remove.count(j) == 0){
				fpoint = i;
				spoint = j;
				mdis = dis[i][j];
			}
		}
	}
	if(mdis <= K){
		return make_pair(0, 0);
	}
	return make_pair(fpoint, spoint);
}


long dfs(set<long>remove){
	if(memo.count(remove) != 0){
		//cout << "memo" << endl;
		return memo[remove];
	}
	//cout << "remove size = " << remove.size() << endl;
	//cout << "dfs " << endl;
	pair<long, long> p;
	p = getp(remove);
	//cout << p.first << "," << p.second << endl;
	if(p.first == 0 && p.second == 0){
		return remove.size();
	}
	long ret = INT_MAX/3;

	remove.insert(p.first);
	ret = min(ret, dfs(remove));

 	remove.erase(p.first);
	remove.insert(p.second);
	ret = min(ret, dfs(remove));

	memo[remove] = ret;
	return ret;
}


int main(){
	cin >> N >> K;
