	for(int e=first[u];~e;e=edge[e].nxt){
		int v=edge[e].to;
		if(v==fa || v==wson[u]) continue;
		pre(v,u);
	}
}
int g[maxn],h[maxn],ans;
void dfs(int u,int fa){
	if(wson[u]) dfs(wson[u],u);
	f[u][0] = wson[u] ? sz[wson[u]] : 0;
//	printf("#8999 %d %d\n",u,mxdep[u]);
	int m = min(k,mxdep[u]);
//	Rep(i,0,m) wri(f[u][i]);puts("");
	for(int e=first[u];~e;e=edge[e].nxt){
		int v = edge[e].to;
		if(v==wson[u] || v==fa) continue;
		dfs(v,u);
		int len = min(k,mxdep[v] + 1);
		g[0] = sz[v];Rep(i,1,len) g[i] = f[v][i-1];
		Rep(i,0,len) h[i] = f[u][i];
//		puts("~~"); 
//		wri(g[0]),writeln(h[0]);

//		Rep(i,0,len) wri(g[i]);puts("");
//		Rep(i,0,len) wri(h[i]);puts("");
//		puts("~~~~~~~~~~~~");

		Rep(i,0,len) f[u][i] = min(g[i]+h[min(i,k-i)],g[min(i,k-i)] + h[i]);
		Rep(i,len+1,min(m,k-len-1)) f[u][i] += g[len];
		Rep(i,max(len+1,k-len),min(m,k)) f[u][i] += g[k-i];

		Rep(i,1,len) f[u][i] = min(f[u][i],f[u][i-1]);
//		Rep(i,max(len+1,k-len),min(m,k)) f[u][i] = min(f[u][i],f[u][i-1]);
	}Rep(i,1,m) assert(f[u][i] <= f[u][i-1]);
	ans = min(ans,n - sz[u] + f[u][min(k,m)]);
	//从root往上搞一格
}
