	int n; cin >> n >> k;
	for(int i = 0; i < n - 1; i++){
		int x, y; cin >> x >> y; e[x].push_back(y); e[y].push_back(x);
	}
	int res = 0;
	for(int i = 1; i <= n; i++) {
		res = max(res, best(i, 0, 0));
	}
	cout << n - res << endl;
	return 0;
}

