bool simulate() {
	int root = 1;
	for(int i = 1; i <= n; i++) {
		if(!del[i]) root = i;
	}
	d[root] = 0;
	dfs(root, 0);
	int p1 = root;
	for(int i = 1; i <= n; i++) {
		if(!del[i] && d[p1] < d[i]) {
			p1 = i;
		}
	}
	d[p1] = 0;
	dfs(p1, 0);
	int p2 = p1;
	for(int i = 1; i <= n; i++) {
		if(!del[i] && d[p2] < d[i]) {
