using namespace std;

vector<int> graph[4000];
bool visited[4000];
int subtreeSize[4000];
int n, k;

int dfsTree(int u, int distance, bool isRoot)
{
	visited[u] = true;
	subtreeSize[u] = 1;

	if (distance == (k+1)/2)
	{
		return 1;
	}

	int total = 0;
	int maxK = 0;

	for (auto v: graph[u])
	{
		if (!visited[v])
		{
			int curr = dfsTree(v, distance + 1, false);
			total += curr;
			maxK = max(maxK, curr);
			subtreeSize[u] += subtreeSize[v];
		}
	}

	if (isRoot)
	{
		return n - (subtreeSize[u] - (k % 2 ? (total - maxK) : 0));
	}
	else
	{
		return total;
	}
}

