int main(int argc, char const *argv[]) {
  int N, K, a, b;
  std::cin >> N >> K;
  for(int i=0;i<N-1;i++){
    std::cin >> a >> b;
    G[a].push_back(b);
    G[b].push_back(a);
  }
  if(getTreeDiameter(1)<=K){
    std::cout << 0 << '\n';
    return 0;
  }
  int ans = 1000000007;
  for(int i=1;i<=N;i++){
    if(check(i, K)){
      int ad = (K%2==0?0:addd(i, (K+1)/2));
