pair<int,int> farthest_vertex(const vector<set<pair<int,int>>> &graph,int v,int p){
    pair<int,int> res(v,0); //(最も遠い頂点,距離)
    for(auto &e:graph[v]){
        if(e.first==p) continue;

        auto tmp=farthest_vertex(graph,e.first,v);
        tmp.second+=e.second;
        if(res.second<tmp.second) res=tmp;
    }
    return res;
}

