#define int long long

int N, K;
vector<int> edge[2000];

pair<int, int> GetMax(int v, int par, int sum, bool isUsed[2000])
{
	if (isUsed[v]) return make_pair(0ll, -1ll);
	pair<int, int> res = make_pair(sum, v);
	for (int i = 0; i < edge[v].size(); i++)
	{
		int to = edge[v][i];
		if (to == par) continue;
		res = max(res, GetMax(to, v, sum + 1, isUsed));
	}
	return res;
}

int Delete(int v, int par, int sum, bool isUsed[2000])
{
	if (isUsed[v]) return 0;
	if (sum == 0)
	{
		isUsed[v] = true;
		return 1;
	}
	int res = 0;
	for (int i = 0; i < edge[v].size(); i++)
	{
		int to = edge[v][i];
		if (to == par) continue;
		res += Delete(to, v, sum - 1, isUsed);
	}
	return res;
}

int Solve(bool isUsed[2000])
{
	int res = 0;
	for (int i = 0; i < N; i++)
	{
		if (isUsed[i]) continue;
		int cnt = 0;
		for (int j = 0; j < edge[i].size(); j++)
		{
			if (isUsed[edge[i][j]]) continue;
			cnt++;
		}
		if (cnt == 1)
		{
			pair<int, int> ma = GetMax(i, -1, 0, isUsed);
			if (ma.first > K)
			{
				isUsed[ma.second] = true;
				return Solve(isUsed) + 1;
			}
		}
	}
	return 0;
}

signed main()
{
	cin >> N >> K;
	for (int i = 0; i < N - 1; i++)
	{
		int a, b;
		cin >> a >> b; a--; b--;
		edge[a].push_back(b);
		edge[b].push_back(a);
	}
	bool isUsed[2000] = {};
	printf("%lld\n", Solve(isUsed));
	return 0;
}

