			dp2[at+1][j]=max(dp2[at+1][j],dp2[at][j]);
			for(int k=0;j+k+1<=K;k++){
				dp2[at+1][max(j,k+1)]=max(dp2[at+1][max(j,k+1)],dp2[at][j]+dp[g[a][i]][k]);
			}
