using namespace std;

#define REP(var, n)  for (decltype(n) var = 0; var < (n); var++)
#define RREP(var, n)  for (auto var = n - 1; var != static_cast<decltype(var)>(-1); var--)
#define FOR(var, a, b)  for (auto var = (a); var < (b); var++)
#define RFOR(var, a, b)  for (auto var = b - 1; var != a; var--)

typedef vector<int> vi;
typedef long long ll;
#define all(c) begin(c),end(c)

auto solve() {
    int N, K;
    cin >> N >> K;
    vector<vi> edges(N);
    vector<pair<int,int>> edge_memo(N-1);
    REP(i, N - 1) {
        int a, b;
        cin >> a >> b;
        --a, --b;
        edges[a].push_back(b);
        edges[b].push_back(a);
        edge_memo[i] = make_pair(a,b);
    }

    // get diameter
    function<int(int, int)> node_len = [&](int v, int prev) -> int {
        int mlen = 0;
        for (auto &&cv: edges[v]) {
            if (cv != prev)
                mlen = max(mlen, node_len(cv, v));
        }
        return 1 + mlen;
    };
    int d = 0;
    for (auto &&re: edges[0])
        d += node_len(re, 0);

    function<int(int, int, int)> child_count = [&](int v, int prev, int sum) -> int {
        int c = 0;
        for (auto &&cv: edges[v]) {
            if (cv != prev && sum < K/2)
                c += child_count(cv, v, sum + 1);
        }
        return 1 + c;
    };

    if (K % 2 == 0) {
        // traverse all the nodes
        int res = 0;
        REP(center, N) {
            int cc =child_count(center, -1, 0);
            res = max(res, cc);
        }
        return N - res;
    } else {
        // traverse all the edges
        K--;
        int res = 0;
        for(auto&& c_edge: edge_memo) {
            int lhs = child_count(c_edge.first, c_edge.second, 0);
            int rhs = child_count(c_edge.second, c_edge.first, 0);
            res = max(res, lhs+rhs);
        }
        return N - res;
    }
}

