const int INF = (int)3e5;

int dp[MAXN][MAXN];

vector<int> adj[MAXN];

bool leaf[MAXN];

int sub[MAXN];

int n, k;

int getDp(int v, int d) {
	if (d == -1) {
		return sub[v];
	}

	int ret = INF;

	for (int i = 0; i <= d; ++i) {
		ret = min(ret, dp[v][i]);
	}

	return ret;       		
}

void dfs(int v, int pr) {
	sub[v] = 1;

	for (int to : adj[v]) {
		if (to == pr) {
			continue;
		}

		leaf[v] = 0;
		dfs(to, v);
		sub[v] += sub[to];
	}

	if (leaf[v]) {
		dp[v][0] = 0;
		return;				
	}	

	for (int mx = -1; mx <= k - 1; ++mx) {
		int mx2 = min(mx, k - 2 - mx);

		if (mx2 < -1) {
			continue;		
		}

		int sum = 0;

		for (int to : adj[v]) {
			if (to == pr) {
				continue;
			}

			sum += getDp(to, mx2);
		} 

		for (int to : adj[v]) {
			if (to == pr) {
				continue;
			}

			if (mx != -1 && dp[to][mx] == -1) {
				continue;
			}

			sum -= getDp(to, mx2);
			dp[v][mx + 1] = min(dp[v][mx + 1], sum + dp[to][mx]);
			sum += getDp(to, mx2);
		}
	}		
}

