int N, K;
vector<vector<int>> tree;

void rec(int v, int p, int d, vector<int> &depth) {
    depth[v] = d;
    for(auto u : tree[v]) {
        if(u == p) continue;
        rec(u, v, d + 1, depth);
    }
}

void solve() {
    cin >> N >> K;
    tree.assign(N, vector<int>());
    rep(i, N - 1) {
        int a, b; cin >> a >> b; a --; b --;
        tree[a].push_back(b); tree[b].push_back(a);
    }
    vector<int> depth(N);
    int ans = N;
    if(K % 2 == 0) {
        rep(v, N) {
            rec(v, -1, 0, depth);
            int cnt = 0;
            rep(u, N) {
                if(depth[u] > K / 2) cnt ++;
            }
            ans = min(ans, cnt);
        }
    } else {
        rep(v, N) {
            for(auto u : tree[v]) {
                rec(u, v, 0, depth); rec(v, u, 0, depth);
                int cnt = 0;
                rep(w, N) {
                    if(depth[w] > K / 2) cnt ++;
                }
                ans = min(ans, cnt);
            }
        }
    }
    cout << ans << endl;
}

