inline void fstart(ll lf,ll rt){
	num++;
	a[num].rt=rt;
	a[num].lf=head[lf];
	head[lf]=num;
}
inline void dfs(ll x,ll step){
	register int i,j;
	if(step>k/2)return ;
	for(i=head[x];i!=0;i=a[i].lf){
		ll p=a[i].rt;
		if(!vis[p])vis[p]=true,dfs(p,step+1),tot++;
	}
}
