		fstart(rt,lf);
	}
	if(k%2==0){
		for(i=1;i<=n;i++){
			memset(vis,false,sizeof(vis));
			vis[i]=true;
			tot=1;
		    dfs(i,1);
		    ans=max(ans,tot);
		}
	}
	else{
		k--;
		for(i=1;i<=n;i++){
			for(j=head[i];j!=0;j=a[j].lf){
				memset(vis,false,sizeof(vis));
				ll p=a[j].rt;
				vis[i]=true;vis[p]=true;
				tot=2;
				dfs(i,1);dfs(p,1);
				ans=max(ans,tot);
			}
		}
	}
	cout<<n-ans<<endl;
	return 0;
}

