		for(int i = 0; i < adj[u].size(); i++)
		{
			int x = adj[u][i];
			if(!visit[x] && !rmv[x])
			{
				visit[x] = true;
				h[x] = h[u] + 1;
				dad[x] = u;
				q.push(x);
			}
		}
	}
	return;
}

void strt()
{
	for(int i = 0; i < n; i++)
	{
		visit[i] = 0;
		dad[i] = 0;
		h[i] = 0;
	}
	return;
}

