{
	int cnt = 0;
	int mxv, mxh = INT_MAX;
	while(mxh > k)
	{
		strt();
		int last = 0;
		while(last < n && rmv[last])
			last++;
		if(last == n)
			break;
		bfs(last);
		mxh = 0;
		for(int i = 0; i < n; i++)
		{
			if(h[i] > mxh)
			{
				mxh = h[i];
				mxv = i;
			}
		}
		strt();
		bfs(mxv);
		mxh = 0;
		for(int i = 0; i < n; i++)
		{
			if(h[i] > mxh)
			{
