typedef int Weight;
struct Edge {
  int src, dst;
  Weight weight;
  Edge(int src, int dst, Weight weight) :
    src(src), dst(dst), weight(weight) { }
};
bool operator < (const Edge &e, const Edge &f) {
  return e.weight != f.weight ? e.weight > f.weight : // !!INVERSE!!
    e.src != f.src ? e.src < f.src : e.dst < f.dst;
}
typedef vector<Edge> Edges;
typedef vector<Edges> Graph;

typedef pair<Weight, int> Result;
Result visit(int p, int v, const Graph &g) {
//    cout << p+1 << " " << v+1 << endl;
  Result r(0, v);
  FOR(e, g[v]) if (e->dst != p) {
    Result t = visit(v, e->dst, g);
    t.first += e->weight;
    if (r.first < t.first) r = t;
  }
  return r;
}
Weight diameter(const Graph &g) {
  Result r = visit(-1, 0, g);
  Result t = visit(-1, r.second, g);
  //cout << "OK" << r.second+1 << t.second+1 << endl;
  return t.first; // (r.second, t.second) is farthest pair
}

int visit2(int p, int v, int dist, const Graph &g) {
//    cout << p+1 << " " << v+1 << endl;
    int ret = 1;
    dist--;
    if(dist > 0) {
        FOR(e, g[v]) if (e->dst != p) {
            int t = visit2(v, e->dst, dist, g);
            ret += t;
        }
    }
    return ret;
}

