void dfs(int x, int par) {
	for(auto i : g[x]) {
		if(del[i]) continue;
		if(i - par) {
			d[i] = 1 + d[x];
			dfs(i, x);
		}
	}
}

int degree(int x) {
	int cnt = 0;
	for(auto i : g[x]) {
		if(!del[i]) ++cnt;
	} 
	return cnt;
}

bool simulate() {
	int root = 1;
	for(int i = 1; i <= n; i++) {
		if(!del[i]) root = i;
	}
	d[root] = 0;
	dfs(root, 0);
	int p1 = root;
	for(int i = 1; i <= n; i++) {
		if(!del[i] && d[p1] < d[i]) {
			p1 = i;
		}
	}
	d[p1] = 0;
	dfs(p1, 0);
	int p2 = p1;
	for(int i = 1; i <= n; i++) {
		if(!del[i] && d[p2] < d[i]) {
			p2 = i;
		}
	}
	if(d[p2] <= k) return true;
	int par1 = p1;
	int par2 = p2;
	// cout << p1 << ' ' << p2 << endl;
	for(auto i : g[p1]) {
		if(!del[i]) {
			par1 = i;
		}
	}
	for(auto i : g[p2]) {
		if(!del[i]) {
			par2 = i;
		}
	}
	if(degree(par1) < degree(par2)) {
		swap(par1, par2);
		swap(p1, p2);
	}
	for(auto i : g[par2]) {
		if(!del[i] && degree(i) == 1) {
			// printf("delete %d\n", i);
			del[i] = true;
			++ans;
		}
	}
	return false;
}

