pair<int, int> solve(int i, int d) {
  if (d > K) return {0, 0};
  // res = self + child num
  int res = 1;
  int mx = 0;
  used[i] = true;
  for (auto j: G[i]) {
    if (!used[j]) {
      auto p = solve(j, d + 1); 
      int n = p.first, r = p.second;
      if (r == -1 || r + mx >= K) {
        used[i] = false;
        return {-1, -1};
      }
      mx = max(mx, r);
      res += n;
    }
  }
  used[i] = false;
  return {res, mx + 1};
}

