pii dfs(int x, int p, int d) {
    pii ret = pii(0, 0);
    if (k + 1 < d) ret.first = 1;
    else if (k + 1 == d) ret.second = 1;
    for (int i : edge[x]) {
        if (i == p) continue;
        pii c = dfs(i, x, d + 1);
        ret.first += c.first;
        ret.second += c.second;
    }
    return ret;
}

int getAns(int x) {
    int sum = 0, mx = 0;

    for (int i : edge[x]) {
        pii ret = dfs(i, x, 1);
        sum += ret.first + ret.second;
        mx = max(mx, ret.second);
    }
    return sum - mx * t;
}

