                            que.push(e);
                        }
                    }
                }

                ll tmp = 0;
                for (ll i = 0; i < n; i++) {
                    if (d[i] > k / 2) tmp++;
                }
                chmin(ans, tmp);
            }
        }
    } else {
        for (ll i = 0; i < n; i++) {
            vll d(n, HIGHINF); d[i] = 0;
            queue<int> que; que.push(i);
            while (!que.empty()) {
                int q = que.front(); que.pop();
                for (int e: edges[q]) {
                    if (d[e] > d[q] + 1) {
                        d[e] = d[q] + 1;
                        que.push(e);
                    }
                }
            }

            ll tmp = 0;
            for (ll i = 0; i < n; i++) {
                if (d[i] > k / 2) tmp++;
            }
            chmin(ans, tmp);
        }
    }
    cout << ans << '\n';
    return 0;
}

