// depth, id
pair<int, int> dfs(int node, VVI & edges, unordered_set<int>& visited, int  depth)
{
    PII ret(depth, node);
    visited.insert(node);

    for(auto to: edges[node]){
        if(visited.find(to) != visited.end())
            continue;
        PII tmp = dfs(to, edges, visited, depth+1);

        if (tmp.first > ret.first)
            ret = tmp;
    }
    return ret;
}

//nodes
PII farthest_pair(VVI & edges, unordered_set<int> & valid_nodes, int& dist)
{
    unordered_set<int> visited1, visited2;
    int s0 = *valid_nodes.begin();
    PII ret = dfs(s0, edges, visited1,  0);
    int s1 = ret.second;
    ret = dfs(s1, edges, visited2, 0);
    int s2 = ret.second;

    dist = ret.first;
    return make_pair(s1, s2);
}

