        edges[a].push_back(b);
        edges[b].push_back(a);
    }

    unordered_set<int> valid_nodes;

    REP(i,n){
        valid_nodes.insert(i);
    }


    int ans = 0;
    while(true){
        int dist;
        PII ret = farthest_pair(edges, valid_nodes, dist);
        int n1 = ret.first, n2 = ret.second;
        if (dist <= k)
            break;
        int pa1 = edges[n1][0], pa2 = edges[n2][0];
        if(edges[pa1].size() > edges[pa2].size()){
            swap(n1, n2);
            swap(pa1, pa2);
        }

        for(auto ch = edges[pa1].begin(); ch != edges[pa1].end();){
            if(edges[*ch].size() <=2){
                ans++;
                valid_nodes.erase(*ch);
                ch = edges[pa1].erase(ch);
            }
            else
                ch++;
        }
    }

    cout << ans << endl;
    return 0;
}

