pair<pt, int> d[N];

void dfs (int v, int pr, int deep)
{
	d[v] = mp(mp(0, 0), 0);
	if (deep == k / 2)
		d[v].ft.ft++;
	if (deep == k / 2 + 1)
		d[v].ft.sc++;
	if (deep > k / 2 + 1)
		d[v].sc++;

	forn (i, sz(g[v]))
	{
		int to = g[v][i];

		if (to == pr)
			continue;

		dfs(to, v, deep + 1);

		d[v].ft.ft += d[to].ft.ft;
		d[v].ft.sc += d[to].ft.sc;		
		d[v].sc += d[to].sc;
	}
}

inline int calc (int v)
{
	dfs(v, -1, 0);

	if (k & 1)
	{
		int ans = INF;

		int sum1 = 0, sum2 = 0, sum3 = 0;

		forn (i, sz(g[v]))
		{
			int to = g[v][i];

			sum1 += d[to].ft.ft, sum2 += d[to].ft.sc, sum3 += d[to].sc;
		}

		forn (i, sz(g[v]))
		{
			int to = g[v][i];

			int cur = sum3 + sum2 - d[to].ft.sc;
			ans = min(ans, cur);
		}

		return ans;
	}
	else
		return d[v].ft.sc + d[v].sc;
}

inline void solve()
{
	int ans = INF;
	forn (i, n)
		ans = min(ans, calc(i));

	cout << ans << endl;
}

