#define Min(A, B) A < B ? A : B
const int MaxN = 1e6 + 10;
const int Inf = 1 << 30;
struct Edge {
	int To, Next;
}Tree[MaxN];
int N, K;
int Cnt = 0, Last[MaxN];
void Add(int U, int V) {
	Tree[++Cnt] = (Edge){V, Last[U]}, Last[U] = Cnt; 
}
int Pa[MaxN], F[MaxN][30], Dep[MaxN];
void Dfs(int Now, int Fa, int Depth) {
	Pa[Now] = Fa; Dep[Now] = Depth; F[Now][0] = Fa;
	for(int i = 0; i <= 20; i++) F[Now][i] = F[F[Now][i - 1]][i - 1];
	for(int i = Last[Now]; i; i = Tree[i].Next) {
		int To = Tree[i].To;
		if(To ^ Fa) Dfs(To, Now, Depth + 1);
	}
}

int Lca(int A, int B) {
	if(!(A ^ B)) return A; 
	while(Dep[A] > Dep[B])
		for(int i = 20; i > 0; i--) 
			if(Dep[F[A][i]] >= Dep[B]) A = F[A][i];
	while(A ^ B) {
		for(int i = 20; i >= 0; i--) 
			if(F[A][i] ^ F[B][i]) 
				A = F[A][i], B = F[B][i];
		if(!(Pa[A] ^ Pa[B])) A = B = Pa[A];
	}
	return A;
}
bool Vis[MaxN];
int Size[MaxN];
int Ans = Inf;
int Count = 0;
void Find(int Now, int Fa, int Depth) {
	Vis[Now] = true; Size[Now] = 1;	
	if(Depth >= K) {  
		Ans = Min(Ans, N - Count);
		return;
	}
	for(int i = Last[Now]; i; i = Tree[i].Next) {
		int To = Tree[i].To;
		if(!Vis[To]) {	
			Count += 1; 
			Find(To, Now, Depth + 1);
			Size[Now] += Size[To];
		}
	}
}

int main() {
	scanf("%d%d", &N, &K);
	for(int i = 1; i <= N - 1; i++) {
		int A, B; scanf("%d%d", &A, &B);
		Add(A, B), Add(B, A);
	}
	Dfs(1, 0, 1);
	if(K & 1) K = (K - 1) >> 1;
	else K >>= 1; 
	for(int i = 1; i <= N; i++) {
		memset(Vis, 0, sizeof(Vis));
		Count = 0;
		Find(i, Pa[i], 0);
	}
	printf("%d", Ans - 1);
}

