class Solve {
public:
    Int N, K;
    vector<vector<int>> G;
    vector<pair<int, int>> edge;
    vector<int> d;

    void bfs(int s1, int s2 = -1) {
        fill(all(d), INF);
        d[s1] = 0;
        if (s2 != -1) d[s2] = 0;

        queue<int> que;
        que.push(s1);
        if (s2 != -1) que.push(s2);

        while (!que.empty()) {
            int top = que.front();
            que.pop();
            for (auto v : G[top]) {
                if (d[v] == INF) {
                    d[v] = d[top] + 1;
                    que.push(v);
                }
            }
        }
    }

    void solve() {
        cin >> N >> K;
        G.resize(N);
        edge.resize(N);
        d.resize(N);
        for (int i = 0; i + 1 < N; ++i) {
            int a, b;
