            int ans = INF;
            for (int i = 0; i < N; ++i) {
                bfs(i);
                int tmp = 0;
                for (int i = 0; i < N; ++i) {
                    if (d[i] > K / 2) {
                        tmp++;
                    }
                }
                chmin(ans, tmp);
            }
            cout << ans << endl;
        }


    }
};


