int a, K;
int ar[maxn], ans;
vector<int> w[maxn];

bool comp( const ii &a, const ii &b ) {
    return ar[a.fi] < ar[b.fi];
}

vector<ii> dfs( int n, int back, int s ) {
    vector<ii> v;
    ar[n] = s;
    vector<int> ss;

    for(int i=0;i<w[n].size();i++) { ss.pb( 0 );
        if( w[n][i] != back ) {
            vector<ii> t = dfs( w[n][i], n, s + 1 );
            for(int j=0;j<t.size();j++)
                v.pb( ii( t[j].fi, i ) ), ss[i]++;
        }
    }
    sort( all( v ), comp );
    for(int i=0,j=0,k=v.size()-1;i<=K-i;i++) {
        int l = K-i;
        while( k >= 0 && ar[v[k].fi] > s+l ) ss[v[k].se]--, k--;
        while( j < v.size() && ar[v[j].fi] <= s+i ) ss[v[j].se]--, j++;
        int maxi = 0;
        for(int m=0;m<ss.size();m++) umax( maxi, ss[m] );
        //printf("asd (%d)%d --> %d %d\n",n,i,j,maxi);
        umax( ans, j + maxi );
    }

    v.pb( ii( n, 0 ) );
    return v;
}

