vector<vector<int> > road(2001);
int n, k;

int solve_even()
{
    int ans = 2000;
    for(int i = 1; i <= n; i++){
        vector<int> depth(n + 1, -1);
        depth[i] = 0;
        queue<int> qu;
        qu.push(i);
        int nowans = 1;
        while(!qu.empty()){
            int now = qu.front();
            qu.pop();
            if(depth[now] >= k / 2) continue;
            for(int j = 0; j < road[now].size(); j++){
                int next = road[now][j];
                if(depth[next] == -1){
                    depth[next] = depth[now] + 1;
                    qu.push(next);
                    nowans++;
                }
            }
        }
        ans = min(ans, n - nowans);
    }
    return ans;
}

int solve_odd()
{
    int ans = 2000;
    for(int i = 1; i <= n; i++){
        for(int j = 0; j < road[i].size(); j++){
            vector<int> depth(n + 1, -1);
            depth[i] = 0;
            depth[road[i][j]] = 0;
            queue<int> qu;
            qu.push(i);
            qu.push(road[i][j]);
            int nowans = 2;
            while(!qu.empty()){
                int now = qu.front();
                qu.pop();
                if(depth[now] >= (k - 1) / 2) continue;
                for(int k = 0; k < road[now].size(); k++){
                    int next = road[now][k];
                    if(depth[next] == -1){
                        depth[next] = depth[now] + 1;
                        qu.push(next);
                        nowans++;
                    }
                }
            }
            ans = min(ans, n - nowans);
        }
    }
    return ans;
}

int main()
{
    cin >> n >> k;
    for(int i = 0; i < n - 1; i++){
        int a, b;
        cin >> a >> b;
        road[a].push_back(b);
        road[b].push_back(a);
    }
    if(k % 2 == 0) cout << solve_even() << endl;
    else cout << solve_odd() << endl;
    return 0;
}

