using namespace std;
static const int MAX = 2000;
static const int NIL = -1;

vector<int> G[MAX];
int cut_size[MAX];
int res=1001001001;

void bfs(int r, int k){
  int i;
  queue<int> s;
  s.push(r);
  cut_size[r] = 0;
  int dist = 0;
  vector<int> b(MAX);
  while(!s.empty()){
    int u= s.front();s.pop();
    dist++;
    REP(i,(int)G[u].size()){
      int v=G[u][i];
      if(b[v]==NIL) continue;
      if(dist>k) cut_size[r]++;
      b[v]=NIL;
      s.push(v);
    }
  }
  res = min(res, cut_size[r]);
}

int main(void){
  int n,k,s,t;
  cin >> n >> k;
  REP(i,n-1){ 
    cin >> s >> t;
    G[s].push_back(t);
    G[t].push_back(s);
  }
  REP(i,n) if(G[i].size()==1) bfs(i,k);
  cout << res << endl;
  return 0;
}

