void dfs1(int cur, int tmp, int dis, vector<vector<int> > &G, int &v1, vector<bool> &used){
    if(tmp > dis){
        dis = tmp;
        v1 = cur;
    }
    used[cur] = true;
    for(auto nxt : G[cur]){
        if(!used[nxt]) dfs1(nxt, tmp + 1, dis, G, v1, used);
    }
}

int dfs2(int cur, int tmp, vector<vector<int> > &G, vector<bool> &used){
    used[cur] = true;
    int ret = 0;
    for(auto nxt : G[cur]){
        if(!used[nxt]){
            ret += dfs2(nxt, tmp + 1, G, used);
        }
    }

    if(tmp > k) ret++;
    return ret;
}

