void VISIT(int M, int num) {

	if (num > K) { return; }
	check[M] = 1;
	dis[M] = num;

	for (int h = 0; h < (int)Adj[M].size(); h++) {
		int J = Adj[M][h];
		if (check[J] == 0) { VISIT(J, num + 1); }
	}
}

int COUNT(void) {
	int ret = 0;
	for (int i = 1; i <= N; i++) { if (check[i] != 0) { ret++; } }
	return ret;
}

