t2 get_longest(const V<ll> linklist[], const bool invalid[], ll root, ll n)
{
    queue<ll> q;
    bool checked[n+1];
    ll level[n+1];
    ll max_level = 0LL;
    ll max_level_n = root;

    memset(checked, 0, sizeof(checked));
    memset(level, 0, sizeof(level));

    q.push(root);
    checked[root] = true;
    level[root] = 0LL;

    for ( ; !(q.empty()); ) {
        ll now = q.front(); q.pop();
        for (auto next : linklist[now]) {
            if (checked[next]) continue;
            if (invalid[next]) continue;
            q.push(next);
            checked[next] = true;
            level[next] = level[now] + 1LL;

            if (level[next] > max_level) {
                max_level = level[next];
                max_level_n = next;
            }
        }
    }

    return t2(max_level_n, max_level);
}

bool set_invalid(const V<ll> linklist[], bool invalid[], ll root, ll n, ll k)
{
    queue<ll> q;
    bool checked[n+1];
    ll level[n+1];

    memset(checked, 0, sizeof(checked));
    memset(level, 0, sizeof(level));

    q.push(root);
    checked[root] = true;
    level[root] = 0LL;

    for ( ; !(q.empty()); ) {
        ll now = q.front(); q.pop();

        for (auto next : linklist[now]) {
            if (checked[next]) continue;
            if (invalid[next]) continue;

            q.push(next);
            checked[next] = true;
            level[next] = level[now] + 1LL;
        }
    }

    bool ret = true;
    rep (i, n+1) if (level[i] > k) {
        invalid[i] = true;
        ret = false;
    }

    return ret;
}

int _main()
{
    ll n; llin(n);
    ll k; llin(k);
    V<t2> ablist; llinl2(ablist, n-1);

    static V<ll> linklist[2003];
