const int INF = 1000 * 1000 * 1000 + 7;
const LL LINF = INF * (LL)INF;

const int MAX = 2000 + 47;

int D[MAX];
int mark[MAX];
vector<int> g[MAX];
int n, k;

void dfs(int v, int d)
{
	D[v] = d;

	FOR(i, 0, SZ(g[v]))
	{
		int to = g[v][i];
		if (!mark[to] && D[to] == INF) dfs(to, d + 1);
	}
}

PII getDiameter()
{
	FOR(i, 0, n)
	{
		if (!mark[i])
		{
			FOR(j, 0, n) D[j] = INF;
			dfs(i, 0);

			int maxx = i;
			FOR(j, 0, n)
			{
				if (!mark[j] && D[j] > D[maxx]) maxx = j;
			}

			FOR(j, 0, n) D[j] = INF;
			dfs(maxx, 0);
			FOR(j, 0, n)
			{
				if (!mark[j] && D[j] > D[maxx]) maxx = j;
			}

			return MP(maxx, D[maxx]);
		}
	}
}

int main()
{
	//freopen("in.txt", "r", stdin);
	//freopen("out.txt", "w", stdout);
	//ios::sync_with_stdio(false); cin.tie(0);
	cin >> n >> k;
	FOR(i, 0, n)
	{
		int a, b;
		cin >> a >> b;
		a--;
		b--;
		g[a].push_back(b);
		g[b].push_back(a);
	}

	int ans = 0;
	while (1)
	{
		PII v = getDiameter();
		if (v.second <= k) break;
		mark[v.first] = 1;
		ans++;
	}

	cout << ans << endl;
}

