using namespace std;
int n,k;
int ans,dep[N],jd[N],size[N];
int s[N],cnt;
struct node
{
	int num,next;
}mp[N<<1];
void init(int x,int y)
{
	mp[++cnt].num=y;
	mp[cnt].next=s[x];
	s[x]=cnt;
}
void dfs(int x,int f,int d,int de[],int v)
{
	de[d]+=v;
	size[x]=1;
	for(int i=s[x];i;i=mp[i].next)
	{
		int y=mp[i].num;
		if(y==f)continue;
		dfs(y,x,d+1,de,v);
		size[x]+=size[y];
	}
}
void solve(int x,int f)
{
	dfs(x,f,0,dep,1);
	for(int i=1;dep[i];i++)dep[i]+=dep[i-1];
	for(int i=s[x];i;i=mp[i].next)
	{
		int y=mp[i].num;
		if(y==f)continue;
		dfs(y,x,1,jd,1);
		for(int j=1;jd[j];j++)jd[j]+=jd[j-1];
		for(int j=1;jd[j]&&j<=k;j++)
			if(dep[k-j])
				ans=max(ans,dep[k-j]-jd[k-j]+jd[j]);
		for(int j=1;jd[j];j++)jd[j]=0;
	}
	for(int i=0;dep[i];i++)dep[i]=0;
	for(int i=s[x];i;i=mp[i].next)
	{
		int y=mp[i].num;
		if(y==f)continue;
		solve(y,x);
	}

}
