	for(int i=1;i<n;i++)
	{
		int x,y;
		scanf("%d%d",&x,&y);
		init(x,y);
		init(y,x);
	}
	solve(1,1);
	if(ans==0)ans=n;
	printf("%d",n-ans);
}

