void doDP(int c) {
    FO (i,0,allC[c].size()) doDP(allC[c][i]);
    FO (i,0,allC[c].size()) {
        int cC = allC[c][i];
        for (int p = K-1; p >= 0; p--) {
            dp[cC][p+1] = dp[cC][p];
        }
        dp[cC][0]++;
        FO (p,0,K+1) {
            newDP[p] = INF;
        }
        FO (p,0,K+1) {
            int oth = K-p;
            newDP[p] = min(dp[c][p]+dp[cC][min(p,oth)],dp[c][min(p,oth)]+dp[cC][p]);
        }
        FO (p,0,K+1) dp[c][p] = newDP[p];
        FO (p,1,K+1) dp[c][p] = min(dp[c][p],dp[c][p-1]);
    }
