{
  int ret = 114514;
  for(int u = 0; u < N; u++) {
    for(int to : g[u]) {
      memset(v, false, sizeof(v));
      v[u] = v[to] = true;
      ret = min(ret, N - dfs(u, K / 2) - dfs(to, K / 2));
    }
  }
  return(ret);
}

