		for (int i = 0; i < N; i++) {
			fill(d, d + N, 1 << 30);
			dfs(i, -1, 0);
			int cnt = 0;
			for (int j = 0; j < N; j++) {
				if (d[j] > K / 2) cnt++;
			}
			ans = min(ans, cnt);
		}
	}
	else {
		for (int i = 0; i < N - 1; i++) {
			fill(d, d + N, 1 << 30);
			dfs(E[i].first, -1, 0);
			dfs(E[i].second, -1, 0);
			int cnt = 0;
			for (int j = 0; j < N; j++) {
				if (d[j] > K / 2) cnt++;
			}
			ans = min(ans, cnt);
