int main(){
  int n, k;
  cin >> n, k;
  vector<vector<int>> G (n);
  vector<vector<int>> dp(n);
  for(int i=0; i<n-1; i++){
    int a,b;
    cin >> a,b;

    a--; b--;
    G[a].push_back(b);
    G[b].push_back(a);
    dp[a].push_back(-1);
    dp[b].push_back(-1);
  }

  int ans = 0;

  vector<bits> bb(n);
  for(int i=0; i<n; i++){
    function<void(int,int, int)> dfs = [&](int pos, int last, int dist){
      bb[i].set(pos);
      if(dist == k) return;
      for(int nx : G[pos]){
        if(nx == last) continue;
        dfs(nx, pos, dist+1);
      }
    };

    dfs(i, i, 0);
  }

  vector<int> ord(n);
  iota(ord.begin(), ord.end(), 0);
  shuffle(ord.begin(), ord.end(), mt);

  for(int r_=0; r_<min(n, 500); r_++){
    int r = ord[r_];
    vector<int> dist(n);

    function<void(int,int)> dfs = [&](int pos, int last){
      dist[pos] = dist[last] + 1;
      if(dist[pos] == k) return;

      for(int nx : G[pos]){
        if(nx == last) continue;
        dfs(nx, pos);
      }
    };

    dist[r] = -1;
    dfs(r, r);

    vector<pair<int,int>> dd;
    for(int i : range(n)){
      dd.push_back({dist[i], i});
    }
    sort(dd.begin(), dd.end());

    bits s;
    s.set(r);

    for(int i=0; i<dd.size(); i++){
      int j = i;
      s.set( dd[i].second );
      while(j+1<dd.size() && dd[j+1].first == dd[i].first){
        s.set(dd[j+1].second);
        j++;
      }

      while(1){
        ans = max<int>(ans, (s & bb[i]).count() );
        if(i==j) break;
        i++;
      }

      i = j;
    }
  }

  println( n - ans );
  return 0;
}

