namespace March
{
	inline void check_min(int a,int &b){if(a<b)b=a;}
	inline void check_max(int a,int &b){if(a>b)b=a;}
	typedef std::pair<int,int> pii;
	const int N=2050,M=N*2,INF=2147483647;
	int begin[N],next[M],to[M];
	int n,m,e,ans;
	bool cmp(pii a,pii b){return a.y<b.y;}
	void add(int x,int y,bool k=1)
	{
		to[++e]=y;
		next[e]=begin[x];
		begin[x]=e;
		if(k)add(y,x,0);
	}
	int inc[N];
	pii dfs(int p,int h,int dep)
	{
		if(dep>m)return pii(0,0);
		std::vector<pii> S;
		pii ret=pii(0,0);
		for(int i=begin[p];i;i=next[i])
			if(to[i]!=h)S.push_back(dfs(to[i],p,dep+1));
		std::sort(S.begin(),S.end(),cmp);

		inc[0]=0;
		for(int i=1,j=(int)S.size();i<=j;i++)
			inc[i]=S[i-1].x+inc[i-1];
		int inda=0;
		for(int i=S.size()-1;i>=inda;i--)
		{
			while(inda<i && S[inda].y+S[i].y<=m)inda++;

			int tmp=inc[inda]+S[i].x;
			if(tmp>ret.x)ret.x=tmp,ret.y=S[i].y;
		}
		ret.x++,ret.y++;
//		printf("%d :%d\n",p,ret.x);
		return ret;
	}
	void work(int rt)
	{
//		printf("rt = %d\n",rt);
		for(int i=begin[rt];i;i=next[i])
			check_min(n-(1+dfs(to[i],rt,1).x),ans);
	}
	void initialize()
	{
		scanf("%d%d",&n,&m);
		for(int i=1,u,v;i<n;i++)
			scanf("%d%d",&u,&v),add(u,v);
	}
	void solve()
	{
		initialize();
		ans=INF;
		for(int i=1;i<=n;i++)
			work(i);
		printf("%d\n",ans);
	}
}
int main()
{
	March::solve();
	return 0;
}

