void visit(ll v, vll& dist) {
    assert(alive.count(v));
    rep(i, p[v].size()) {
        ll ch = p[v][i];
//        cout << v << " " << ch << endl;
        if (!alive.count(ch))
            continue;
        if (dist[ch] >= 0)
            continue;
        dist[ch] = dist[v] + 1;
        visit(ch, dist);
    }
}
int main(void) {
