    ll ret = 0;
    while (1) {
        dist1 = vll(n, -1);
        dist1[*(alive.begin())] = 0;
        visit(*(alive.begin()), dist1);
//        cout << dist1 << endl;
        ll farest = (ll)(max_element(all(dist1)) - dist1.begin());

        dist2 = vll(n, -1);
        dist2[farest] = 0;
        visit(farest, dist2);
