vector<int> graph[2010];

int dfs(int cur, int prv, int lim) {
    if (lim == 0) return 1;
    int ret = 1;
    for (auto& nxt: graph[cur]) {
        if (nxt == prv) continue;
        ret += dfs(nxt, prv, lim - 1);
    }
    return ret;
}

// top2
pair<pair<int, int>, pair<int, int>> tall(int cur, int prv) {
    if (graph[cur].size() == 1 and graph[cur][0] == prv) return make_pair(make_pair(-1, -1), make_pair(0, 0));
    pair<int, int> ret(0, 0);
    int mx1 = -1, mx2 = -1;
    for (auto& nxt: graph[cur]) {
        if (nxt == prv) continue;
        int tmp = tall(nxt, cur).second.first + 1;
        if (ret.first < tmp) {
            mx2 = mx1;
            mx1 = nxt;
            ret.second = ret.first;
            ret.first = tmp;
        } else if (ret.second < tmp) {
            mx2 = nxt;
            ret.second = tmp;
        }
    }
    return make_pair(make_pair(mx1, mx2), ret);
}

pair<int, int> dfs2(int cur, int prv) {
    pair<int, int> ret(0, cur);
    for(auto& nxt : graph[cur]) {
        if (nxt == prv) continue;
        auto cost = dfs2(nxt, cur);
        cost.first++;
        ret = max(ret, cost);
    }
    return ret;
}

int tree_diameter() {
    auto p = dfs2(0, -1);
    auto q = dfs2(p.second, -1);
    return q.first;
}

signed main() {

    SS(int, N, K);

    vector<pair<int, int>> edges;
    REP(i, N - 1) {
        SS(int, A, B);
        --A, --B;
        graph[A].emplace_back(B);
        graph[B].emplace_back(A);
        edges.emplace_back(A, B);
    }

    if (tree_diameter() <= K) return print(0);

    ll res = INFF;
    if (K % 2 == 0) {
        REP(i, N) {
            if (graph[i].size() == 1) continue;
            auto tl1 = tall(i, graph[i][0]);
            auto tl2 = tall(i, tl1.first.first);
            vector<pair<int, int>> prs; // dep, idx
            prs.emplace_back(tl1.second.first, tl1.first.first);
            prs.emplace_back(tl1.second.second, tl1.first.second);
            prs.emplace_back(tl2.second.first, tl2.first.first);
            prs.emplace_back(tl2.second.second, tl2.first.second);
            UNIQUE(prs);
            int sz = prs.size();
            if (sz < 2 or prs[sz - 2].first < K / 2) continue;

            vector<int> dep;
            for (auto& nxt: graph[i]) dep.emplace_back(dfs(nxt, i, K / 2 - 1));
            ll sm = 0;
            EACH(e, dep) sm += e;
            chmin(res, N - 1 - sm);
        }
    } else {
        for (auto& [u, v]: edges) {
            print(u, v, ':', tall(u, v).second.first, tall(v, u).second.first);
            if (tall(u, v).second.first < K / 2) continue;
            if (tall(v, u).second.first < K / 2) continue;
            int uu = dfs(u, v, K / 2);
            int vv = dfs(v, u, K / 2);
            // print(u, v, ':', uu, vv);
            // if (uu < K / 2) continue;
            // if (vv < K / 2) continue;
            chmin(res, N - (uu + vv));
        }
    }
    if (res == INFF) res = 0;
