vector<int> G[MAX_N];
int dist[MAX_N];

void bfs(int s){
	dist[s] = 0;
	queue<int> qa;
	qa.push(s);
	while(!qa.empty()){
		int v = qa.front(); qa.pop();
		for(int i = 0; i < G[v].size(); i++){
			if(dist[G[v][i]] != INF) continue;
			dist[G[v][i]] = dist[v] + 1;
			qa.push(G[v][i]);
		}
	}
	return ;
}

void bfs2(int s1, int s2){
	dist[s1] = 0;
	queue<int> qa;
	qa.push(s1);
	while(!qa.empty()){
		int v = qa.front(); qa.pop();
		for(int i = 0; i < G[v].size(); i++){
			if(G[v][i] == s2 || dist[G[v][i]] != INF) continue;
			dist[G[v][i]] = dist[v] + 1;
			qa.push(G[v][i]);
		}
	}
	dist[s2] = 0;
	qa.push(s2);
	while(!qa.empty()){
		int v = qa.front(); qa.pop();
		for(int i = 0; i < G[v].size(); i++){
			if(G[v][i] == s1 || dist[G[v][i]] != INF) continue;
			dist[G[v][i]] = dist[v] + 1;
			qa.push(G[v][i]);
		}
	}
	return ;
}

