	for(int i = 0; i < N - 1; i++){
		cin >> A[i] >> B[i];
		A[i]--; B[i]--;
		G[A[i]].push_back(B[i]);
		G[B[i]].push_back(A[i]);
	}
	int res = N;
	if(K % 2 == 0){
		for(int i = 0; i < N; i++){
			fill(dist, dist + N, INF);
			bfs(i);
			int cnt = 0;
			for(int j = 0; j < N; j++){
				if(dist[j] > K / 2) cnt++;
			}
			res = min(cnt, res);
		}
	}else{
		for(int i = 0; i < N - 1; i++){
			fill(dist, dist + N, INF);
			bfs2(A[i], B[i]);
			int cnt = 0;
			for(int j = 0; j < N; j++){
				if(dist[j] > (K - 1) / 2) cnt++;
			}
			res = min(cnt, res);
		}
	}
	cout << res << endl;
	return 0;
}

