int n, K, Res, D[2010], P[2010], CC[2010];
vector<int>E[2100];
void DFS(int a, int pp, int rr){
    P[a] = rr;
    for(int i=0;i<E[a].size();i++){
        if(E[a][i]!=pp){
            D[E[a][i]] = D[a]+1;
            if(pp == 0) rr = E[a][i];
            DFS(E[a][i],a,rr);
        }
    }
}
void Do(int a){
    D[a]=0;
    DFS(a,0,-1);
    int i, c = 0;
    for(i=1;i<=n;i++){
        CC[i]=0;
        if(D[i] <= K/2) c++;
    }
    if(K%2==1){
        for(i=1;i<=n;i++){
            if(D[i] == (K+1)/2) CC[P[i]]++;
        }
        int M = 0;
        for(i=1;i<=n;i++)M=max(M,CC[i]);
        c+=M;
    }
    Res = min(Res, n - c);
}
