using namespace std;

int N, K, ans, vol[2018], old[2018], dp[2018][2018];
const int INF = 1e6;
vector < int > v[2018];

void solve (int nod, int tata)
{
    dp[nod][0] = 0, dp[nod][1] = -INF, vol[nod] = 1;
    for (auto it : v[nod])
        if (it != tata)
        {
            solve (it, nod);
            for (int i=0; i<=vol[nod]; i++)
                old[i] = dp[nod][i];
            for (int i=0; i<=vol[nod] + vol[it]; i++)
                dp[nod][i] = INF;
            for (int i=0; i<=vol[nod]; i++)
                for (int j=0; j<=vol[it]; j++)
                    if (old[i] + dp[it][j] + 1 <= K)
                        dp[nod][i + j] = min (dp[nod][i + j], max (old[i], dp[it][j] + 1));
            vol[nod] += vol[it];
        }
    for (int j=0; j<=vol[nod]; j++)
        if (dp[nod][j] <= K)
            ans = min (ans, j + N - vol[nod]);
}

