		adj[b].pb(a);
	}
	int ret=INF;
	for (int root=0;root<n;root++) {
		memset(vis,0,sizeof(vis));
		memset(dead,0,sizeof(dead));
		for (int i=0;i<n;i++) len[i].clear();
		dfs(root);
		ret=min(ret,ans);
		ans=0;
	}
	printf("%d\n", ret);
}

