		Maxdep = 0;
		dfs(i, 0);
		int Cnt = 0;
		for (int j = K / 2 + 1; j <= Maxdep; ++j)
			Cnt += Sum[j];
		int Maxsize = -1;
		if (K & 1)
		{
			int k = -1, add = 0;
			for (int j = 1; j <= N; ++j)
				if (Dep[j] == K / 2)
				{
					if (Son[j] == Maxsize && Fa[j] == Fa[k] && Fa[j] != 1)
					{
						add += Maxsize;
					}
					else if (Son[j] > Maxsize)
					{
						k = j;
						Maxsize = Son[j];
					}
					//Maxsize = max (Maxsize, Son[j]);
				}
			Maxsize += add;
			if (!(K / 2)) Maxsize = 1;
