int bfs(int start,int start2, int maxCou){
    queue<pair<int, int> > que;
    que.push(make_pair(start, 0));
    if(start2 != -1) que.push(make_pair(start2, 0));
    bool used[2001] = {};

    int count = 0;

    while(que.size()){
        int now = que.front().first;
        int cou = que.front().second;
        que.pop();

        if(used[now]) continue;
        if(cou > maxCou) continue;
        used[now] = true;
        count++;

        for(int i = 0;i < edge[now].size();i++){
            que.push(make_pair(edge[now][i], cou + 1));
        }
    }

    return n - count;
}

