	    dep[v] = dep[u] + 1;
	    fa[v] = u;
	    dfs(v);
	}
    }
}
int lim,dp[MAXN];
void clear(int u,int fa) {
    if(dep[u] == lim) {vis[u] = 1;++ans;}
    for(int i = head[u] ; i; i =  E[i].next) {
	int v = E[i].to;
	if(!vis[v] && v != fa) {
	    clear(v,u);
	}
    }
}
void dfs1(int u) {
    if(dep[u] == lim) dp[u] = 1;
    for(int i = head[u] ; i ; i = E[i].next) {
	int v = E[i].to;
	if(!vis[v] && v != fa[u]) {
	    fa[v] = u;
	    dep[v] = dep[u] + 1;
	    dfs1(v);
	    dp[u] += dp[v];
	}
    }
    if(u == cen[0]) {
	int d = 0;
	for(int i = head[u] ; i ; i = E[i].next) {
	    int v = E[i].to;
	    if(v != fa[u] && !vis[v]) {
		if(dp[v] > dp[d]) d = v;
	    }
	}
	for(int i = head[u] ; i ; i = E[i].next) {
	    int v = E[i].to;
	    if(v != fa[u] && !vis[v]) {
		if(v != d) clear(v,u);
	    }
	}
    }
}
int getdiameter() {
    int rt = 0;
    for(int i = 1 ; i <= N ; ++i) {
	if(!vis[i]) {rt = i;break;}
    }
    dep[rt] = 0;fa[rt] = 0;
    dfs(rt);
    int u = rt;
    for(int i = 1 ; i <= N ; ++i) {
	if(!vis[i] && dep[i] > dep[u]) {u = i;}
    }
    dep[u] = 0;fa[u] = 0;
    dfs(u);
    int D = 0,t;
    for(int i = 1 ; i <= N ; ++i) {
	if(!vis[i]) {
	    if(D < dep[i]) {
		D = dep[i];
		t = i;
	    }
	}
    }

    int p = t;
    while(dep[p] != D / 2 + 1) p = fa[p];
    if(D % 2 == 0) cen[0] = fa[p];
    else cen[0] = p,cen[1] = fa[p];
    return D;
}
void Solve() {
    read(N);read(K);
    int a,b;
    for(int i = 1 ; i < N ; ++i) {
	read(a);read(b);
	add(a,b);add(b,a);
    }
    while(1) {
	int D = getdiameter();
	if(D <= K) break;
	if(D % 2 == 0) {
	    dep[cen[0]] = 0;fa[cen[0]] = 0;
	    memset(dp,0,sizeof(dp));lim = D / 2;
	    dfs1(cen[0]);

	}
	else {
	    dep[cen[0]] = 0;dep[cen[1]] = 0;
	    fa[cen[0]] = cen[1];fa[cen[1]] = cen[0];
	    memset(used,0,sizeof(used));
	    dfs(cen[0]);
	    int c[2] = {0};
	    vector<int> v[2];
	    for(int i = 1 ; i <= N ; ++i) {
		if(used[i] && dep[i] == D / 2) {
		    ++c[0];
		    v[0].pb(i);
		}
	    }
	    memset(used,0,sizeof(used));
	    dfs(cen[1]);
	    for(int i = 1 ; i <= N ; ++i) {
		if(used[i] && dep[i] == D / 2) {
		    ++c[1];
		    v[1].pb(i);
		}
	    }
	    int id = c[0] < c[1] ? 0 : 1;
	    ans += min(c[0],c[1]);
	    for(auto t : v[id]) vis[t] = 1;
	}
    }
    out(ans);enter;
}

