void addEdge(int a,int b)
{
	static int c=0;
	e[++c]=(Edge){b,head[a]};
	head[a]=c;
	e[++c]=(Edge){a,head[b]};
	head[b]=c;
}
bool b[MAXN+10];
void dfs(int now,int d,int fa)
{
	if (d<0) return;
	b[now]=true;
	for(int i=head[now]; i!=0; i=e[i].next) {
		int v=e[i].to;
		if (v==fa) continue;
		dfs(v,d-1,now);
	}
}
void solve(long long N, long long K, vector<long long> A, vector<long long> B){
	for(int i=0; i<N-1; ++i) {
		addEdge(A[i],B[i]);
	}
	int ans=0;
	if (K%2==0) {
		for(int i=1; i<=N; ++i) {
			memset(b,false,sizeof(b));
			dfs(i,K/2,0);
			int cnt=0;
			for(int j=1; j<=N; ++j) {
				if (b[j]) ++cnt;
			}
			ans=max(ans,cnt);
		}
	} else {
		for(int i=0; i<N-1; ++i) {
			memset(b,false,sizeof(b));
			dfs(A[i],K/2,0);
			dfs(B[i],K/2,0);
