	if(dep[x]>k)return 0;
	ans[x]+=-r[min(k-dep[x],BB)]+l[min(k-dep[x],AA)]+1;
	for(int i=h[x];i;i=Next[i]){
		if(p[v[i]]==1)continue;
		if(v[i]==fa)continue;
		afs(v[i],x);
