	for(int i=1;i<=AA;i++)l[i]+=l[i-1];
	ans[x]+=l[min(AA,k)];
	for(int i=h[x];i;i=Next[i]){
		if(p[v[i]]==1)continue;
		BB=0;
		ifs(v[i],x);
		for(int i=1;i<=BB;i++)r[i]+=r[i-1];
		afs(v[i],x);
		ccfs(v[i],x);
