int bfs_even(int s) {
    int dist[MAX_V];

    queue<int> que;
    fill(dist, dist + MAX_V, INF);
    dist[s] = 0;
    que.push(s);
    while (!que.empty()) {
        int q = que.front();
        que.pop();
        for (auto e : E[q]) {
            if (dist[e] == INF) {
                que.push(e);
                dist[e] = dist[q] + 1;
            } else if (dist[e] > dist[q] + 1) {
                dist[e] = dist[q] + 1;
            }
        }
    }

    int cnt = 0;
    rep2(i, n) if (dist[i] > k / 2) cnt++;
    return cnt;
}

int bfs_odd(int s, int t) {
    int dist[MAX_V];

    queue<int> que;
    fill(dist, dist + MAX_V, INF);
    dist[s] = 0;
    que.push(s);
    while (!que.empty()) {
        int q = que.front();
        que.pop();
        for (auto e : E[q]) {
            if (e == t) continue;
            if (dist[e] == INF) {
                que.push(e);
                dist[e] = dist[q] + 1;
            } else if (dist[e] > dist[q] + 1) {
                dist[e] = dist[q] + 1;
            }
        }
    }

    int cnt = 0;
    rep2(i, n) if (dist[i] != INF && dist[i] > k / 2) cnt++;
    return cnt;
}

