    int Min = INF;

    if (k % 2 == 0) {
        rep2(i, n) Min = min(Min, bfs_even(i));
    } else if (k % 2 == 1) {
        rep2(i, n) for (auto e : E[i]) Min = min(Min, bfs_odd(i, e) + bfs_odd(e, i));
