#define nMax 2000+9
int deg[nMax], par[nMax], del[nMax];
int sth[nMax];
//
bool isLeave(int u, int p){
    return deg[u] == 0;
}
void DFS(int u, int p){

    int sz = G[u].size();
    deg[u] = sz;
    if(p != -1) deg[u]--;
    par[u] = p;

    sth[u] = 0;
    for(int i=0; i<sz; i++)
    {
        int v = G[u][i];
        if(v == p) continue;
        DFS(v, u);
        sth[u] += isLeave(v, u);
    }
}
int further(int u, int p){
    int ret = 0;
    for(int i=0,sz=G[u].size(); i<sz; i++)
    {
        int v = G[u][i];
        if(v == p) continue;
        if(del[v]) continue;
        ret = max(ret, 1 + further(v, u));
    }
    return ret;
}
void fur_nodes(int u, int p, int len = 0){
    if(len == limit)
    {
        V.PB(u);
    }

    for(int i=0,sz=G[u].size(); i<sz; i++)
    {
        int v = G[u][i];
        if(v == p) continue;
        if(del[v]) continue;
        fur_nodes(v, u, 1 + len);
    }
}
//
void dele(int u){

    if(u != root)
    {
        int p = par[u];
        deg[p]--;
        del[u] = 1;
        sth[p]--;
    }
    else
    {
        assert(deg[u] == 1);

        int cho = -1;
        for(int i=0,sz=G[u].size(); i<sz; i++)
            if(!del[G[u][i]])
                cho = G[u][i];

        root = cho;
        par[cho] = -1;
        del[u] = 1;
    }
}
