int main()
{
    read_file();
    while(scanf("%d%d", &n, &K)!=EOF)
    {
        G.assign(n, vi());
        for(int i=0; i<n-1; i++)
        {
            int u, v;
            scanf("%d%d", &u, &v);
            u--, v--;
            G[u].PB(v);
            G[v].PB(u);
        }
        root = 0;

        DFS(root, -1);
        memset(del, 0, sizeof del);

        int ans = 0;
        while(true)
        {
            limit = further(root, -1);
            V.clear();
            fur_nodes(root, -1);

            worst.clear();
            for(int i=0,sz=V.size(); i<sz; i++)
                worst.PB( V[i] );

            limit = further(worst[0], -1);
            V.clear();
            for(int i=0; i<worst.size(); i++)
                fur_nodes(worst[i], -1);

            for(int i=0,sz=V.size(); i<sz; i++)
                worst.PB( V[i] );

            int diam = limit;

            if(diam <= K)
                break;

            int cho = -1, num = OO;
            for(int i=0, sz=worst.size(); i<sz; i++)
            {
                int u = worst[i];
                int p = par[u];

                if(p == -1)
                {
                    assert(u == root);
                    int nw;

                    int node;
                    int cnt = 0;
                    for(int j=0,szz=G[u].size(); j<szz; j++)
                        if(!del[G[u][j]])
                            node = G[u][j], cnt++;

                    assert(cnt == 1);
                    nw = sth[node] + 1;

                    if(num > nw)
                    {
                        num = nw;
                        cho = u;
                    }
                }
                else if(sth[p] < num)
                {
                    num = sth[p];
                    cho = u;
                }
            }

            ans++;
            dele(cho);

//            DEBUG(cho);
//            DEBUG(root);
        }

        printf("%d\n", ans);
    }
}

