typedef bitset<2024> B;

int main() {
  int N, K;
  while (cin >> N >> K) {
    vector<vector<int>> g(N);
    for (int i : range(N - 1)) {
      int a, b;
      cin >> a >> b;
      a--;
      b--;
      g[a].push_back(b);
      g[b].push_back(a);
    }

    vector<B> bs(N);
    for (int i : range(N)) {
      queue<pair<int, int>> q;
      q.push({i, 0});
      while (!q.empty()) {
        int v = q.front().first;
        int d = q.front().second;
        q.pop();

        if (bs[i][v]) continue;
        bs[i][v] = 1;

        if (d >= K / 2) continue;
        for (int u : g[v]) {
          if (bs[i][u]) continue;
          q.push({u, d + 1});
        }
      }
    }

    int res = N;
    for (int i : range(N)) {
      if (K % 2 == 0) {
        res = min(res, N - static_cast<int>(bs[i].count()));
      } else {
        for (int j : g[i]) {
          res = min(res, N - static_cast<int>((bs[i] | bs[j]).count()));
        }
      }
    }

    cout << res << endl;
  }
}

