void bfs(int x)
{
	d[x]=0;
	queue<int> q;
	while (!q.empty()) q.pop();
	q.push(x);
	do
	{
		int p=q.front();
		q.pop();
		int i=head[p];
		while (i!=0)
		{
			if (d[adj[i]]>d[p]+1)
			{
				d[adj[i]]=d[p]+1;
				q.push(adj[i]);
			}
			i=link[i];
		}
	}
	while (!q.empty());
}
