#define C getchar()-48
int read()
{
    int s=0,t=1,k=C;
  for (;k>9||k<0;k=C) if (k==-3) t=-1;
  for (;k>=0&&k<=9;k=C) s=(s<<1)+(s<<3)+k;
  return s*t;
}

  int t;
  int h[N+N];
  struct hh
    {
      int n,r;
    }e[N+N];
void ins()
{
  int x=read(),y=read();
  e[++t]=(hh){h[x],y};h[x]=t;
  e[++t]=(hh){h[y],x};h[y]=t;
}

  int n,m;
void in()
{
  cin>>n>>m;
  ++m;
  for (int i=0;++i<n;)
    ins();
}

  int L;
  int l[N],s[N];
#define P(i) e[i].r
void fir(int k,int F)
{
	s[k]=l[k]=1;
  for (int i=h[k];i;i=e[i].n)
    if (P(i)^F)
      {
        fir(P(i),k);
        s[k]+=s[P(i)];
        L=max(L,l[k]+l[P(i)]);
        l[k]=max(l[k],l[P(i)]+1);
      }
}

  int x,y;
void sec(int k,int F)
{
  if (l[k]==L+1>>1) x=k,y=F;
  if (l[k]<=L+1>>1) return;
  for (int i=h[k];i;i=e[i].n)
    if (P(i)^F) sec(P(i),k);
}

  int f[N][N];
  int d[N];
void thr(int k,int F)
{
	l[k]=1;
  for (int i=h[k];i;i=e[i].n)
    if (P(i)^F)
      {
        thr(P(i),k);
        for (int j=0;j<=l[P(i)];++j)
          f[k][j+1]+=f[P(i)][j];
        l[k]=max(l[k],l[P(i)]+1);
      }
  f[k][0]=f[k][1]+1;
}

  int A=1e8;
void fou(int R)
{
  for (int i=0;i<=L+1>>1&&i<=m;++i)
    for (int j=h[R];j;j=e[i].n)
      A=min(A,f[R][i]-f[P(j)][i-!!i]+f[P(j)][m-i]);
}

  int R;
void wor()
{
  fir(1,0);
  sec(1,0);
  if (L&1) R=x;
  else R=(s[x]>s[1]-s[x]) ? x : y;
  thr(R,0);
  fou(R);
}

void out()
{
  cout<<A;
}

int main()
{
  in();
  wor();
  out();
  exit(0);
}

