        chs[b].push_back( a );
    }
    rootTr ( root );
    solve( root );
    int ans = 1<<20;
    for ( int i = 1 ; i <= n ; i ++ ) {
        ans = min( ans, dp[i][k+1] + (n-sz[i]) );
    }
    cout << ans << "\n";

    return 0;
}

