int n,k;
vector<vector<int> > adj;
int parent[2001][11];
int dep[2001]={0,};
void dfs2(int here,int dad,int d){
    parent[here][0]=dad;
    dep[here]=d;
    for(int i=0;i<adj[here].size();i++){
        int there=adj[here][i];
        if(there==dad)
            continue;
        dfs2(there,here,d+1);
    }
}
int dfs(int here,int dad,int d,int mx){
    int ans=1;
    if(mx==d)
        return ans;
    for(int i=0;i<adj[here].size();i++){
        int there=adj[here][i];
        if(there==dad)
            continue;
        ans+=dfs(there,here,d+1,mx);
    }
    return ans;
}
int getLca(int u,int v){
    if(dep[u]>dep[v])
        swap(u,v);
    int d=dep[v]-dep[u];
    int i=0;
    while(d){
        if(d&(1<<i)){
            d-=(1<<i);
            v=parent[v][i];
        }
        i++;
    }
    if(u==v)
        return u;
    for(int i=10;i>=0;i--){
        if(parent[u][i]!=parent[v][i])
            u=parent[u][i],v=parent[v][i];
    }
    return parent[u][0];
}
