        adj[from].push_back(to);
        adj[to].push_back(from);
    }
    int ans=0;
    dfs2(1,-1,0);
    for(int i=1;i<11;i++){
        for(int j=1;j<=n;j++){
            if(parent[j][i-1]<0)
                parent[j][i]=-1;
            else
                parent[j][i]=parent[parent[j][i-1]][i-1];
        }
    }
    if(k%2==0){
        for(int i=1;i<=n;i++)
            ans=max(ans,dfs(i,-1,0,k/2));
    }
    else{
        for(int i=1;i<=n;i++){
            for(int j=i+1;j<=n;j++){
                if(dep[i]+dep[j]-2*dep[getLca(i,j)]==1){
                    ans=max(ans,max(ans,dfs(i,j,0,k/2)+dfs(j,i,0,k/2)));
                }
            }
        }
    }
    cout<<n-ans;
    return 0;
}

