short n,k,step[2000][2000],M,countMax,x,y,result;
vector<short> v[2000],leaf,delet;
bool lef[2000];

void reduceDiameter()
{
    M=countMax=0; delet.clear();
    for(int i=0;i<leaf.size();++i) for(int j=0;j<leaf.size();++j) if(step[leaf[i]][leaf[j]]>M) M=step[leaf[i]][leaf[j]];

    for(int i=0;i<leaf.size() && M>k;++i)
    {
        x=0;
        for(int j=0;j<leaf.size();++j) if(step[leaf[i]][leaf[j]]==M) ++x;

        if(x>countMax) {countMax=x; delet.clear(); delet.push_back(leaf[i]);}
        else if(x==countMax) delet.push_back(leaf[i]);
    }

    for(int i=0;i<delet.size() && M>k;++i) for(int j=i+1;j<delet.size();++j) if(step[delet[i]][delet[j]]==M) {delet.erase(delet.begin()+j); --j;}
    //printf("delet ::  "); for(int i=0;i<delet.size();++i) printf("%i  ",delet[i]); printf("\n");
    for(int i=0;i<delet.size() && M>k;++i) for(int j=0;j<leaf.size();++j) if(leaf[j]==delet[i]) {leaf.erase(leaf.begin()+j); break;}
    for(int i=0;i<delet.size() && M>k;++i) for(int j=0;j<v[delet[i]].size();++j) if(lef[v[delet[i]][j]]==false) {lef[v[delet[i]][j]]=true; leaf.push_back(v[delet[i]][j]);}
    result+=delet.size();
}

