constexpr int INF = (1 << 30) - 1;

int N, K;
vector < int > G[2005];
int flag[2005];

int searchDepth(int node, int value)
{
        int ret = 0;

        if ( flag[node] == value ) return ( 0 );
        flag[node] = value;
        for ( auto &to : G[node] ) ret = max(ret, searchDepth(to, value));
        return ( ret + 1 );
}

int calcNum(int node, int value)
{
        int ret = 1;
        if ( flag[node] == value ) return ( 0 );
        flag[node] = value;
        for ( auto &to : G[node] ) ret += calcNum(to, value);
        return ( ret );
}

int main()
{
        cin >> N >> K;
        memset(flag, -1, sizeof(flag)); 
        for ( int i = 0; i < N - 1; i++ ) {
                int a, b;
                cin >> a >> b; --a, --b;
                G[a].push_back(b);
                G[b].push_back(a);
        }

        int minv = INF;
        int cnt = 0;
        for ( int root = 0; root < N; root++ ) {
                vector < bool > f(G[root].size());
                vector < int > vec1, vec2;

                for ( auto &to : G[root] ) {
                        flag[root] = ++cnt;
                        if ( searchDepth(to, cnt) > K ) {
                                flag[root] = ++cnt;
                                vec2.push_back(calcNum(to, cnt));
                        } else {
                                flag[root] = ++cnt;
                                vec1.push_back(calcNum(to, cnt));
                        }
                }
                sort(begin(vec1), end(vec1));
                sort(begin(vec2), end(vec2));
                if ( vec1.size() == 0 ) continue;


                int sum = 0;
                for ( int i = 0; i < vec1.size() - 1; i++ ) sum += vec1[i];
                for ( int i = 0; i < vec2.size(); i++ ) sum += vec2[i];
                minv = min(minv, sum);
        }

        cout << minv << endl;

        return ( 0 );
}

