    for(int i=0;i<n;i++)
      if(par[i].F==ri)rcnt++;
    if(lcnt>rcnt){
      ans+=rcnt;
      ri--;
    }else{
      ans+=lcnt;
      le++;
    }
  }
  cout<<ans<<endl;
  return 0;
}

