void dfs(int cur, int parent)
{
	sub[cur] = 1;
	par[cur] = parent;
	for(int it : adj[cur]){
		if(it != parent){
			dfs(it, cur);
			sub[cur] += sub[it];
		}
	}
}

int solve(int cur, int ht, int parent)
{
	if(ht==0)
		return sub[cur];
	if(dp[cur][ht] != -1)
		return dp[cur][ht];
	int ret = solve(cur, ht-1, parent), sum = 0, nht;
	if(adj[cur].size() == 1){
		for(int it : adj[cur]){
			if(it != parent)
				sum += solve(it, ht-1, cur);
		}
		return dp[cur][ht] = sum;
	}
	nht = min(ht-1, k-ht+1);
	for(int it : adj[cur]){	
		if(it != parent)
			sum += solve(it, nht, cur);
	}
	for(int it : adj[cur]){
		if(it != parent)
			ret = min(ret, sum - solve(it, nht, cur) + solve(it, ht-1, cur));
	}
	return dp[cur][ht] = ret;
}

