		lst[s].push_back(t);
		lst[t].push_back(s);
	}
	int ans = INT_MAX;
	Loop(i, n) {
		Foreach(b, lst[i]) {
			judge = true;
			if (judge) ans = min(ans, solve(i, b, -1, 0).fst);
		}
	}
	cout << ans << endl;
}

