ll N, K;
const int MAX_N = 2000;
int A[MAX_N], B[MAX_N];
vi G[MAX_N];

int check_v(int v, int d) {
  bool used[N];
  REP(i, N) used[i] = false;
  queue<pi> q;
  q.push(pi(0, v));
  used[v] = true;

  int res = 0;
  while(!q.empty()) {
    pi u = q.front();
    q.pop();
    used[u.S] = true;
    if(u.F > d / 2) res++;
    REP(i, G[u.S].size()) {
      if(!used[G[u.S][i]]) q.push(pi(u.F + 1, G[u.S][i]));
    }
  }
  return res;
}

int check_e(int e, int d) {
  bool used[N];
  REP(i, N) used[i] = false;
  queue<pi> q;
  q.push(pi(0, A[e] - 1));
  used[A[e] - 1] = true;
  q.push(pi(0, B[e] - 1));
  used[B[e] - 1] = true;

  int res = 0;
  while(!q.empty()) {
    pi u = q.front();
    q.pop();
    used[u.S] = true;
    if(u.F > d / 2) res++;
    REP(i, G[u.S].size()) {
      if(!used[G[u.S][i]]) q.push(pi(u.F + 1, G[u.S][i]));
    }
  }
  return res;
}

int main(){
  cin >> N >> K;
  REP(i, N - 1) cin >> A[i] >> B[i];
  REP(i, N - 1) {
    G[A[i] - 1].pb(B[i] - 1);
    G[B[i] - 1].pb(A[i] - 1);
  }

  int ans = INFi;
  if(K % 2 == 0) {
    REP(i, N) {
      ans = min(ans, check_v(i, K));
    }
  } else {
    REP(i, N - 1) {
      ans = min(ans, check_e(i, K));
    }
  }

  cout << ans << endl;

  return 0;
}

