int N, K;
Vec< Vec< int > > adj;
Vec< pii > edges;
Vec< bool > vis;

void dfs(int v, int p, int d, int cap) {
	if (d > cap) return;
	vis[v] = true;
	for (int u : adj[v]) if (u != p) dfs(u, v, d + 1, cap);
}

void solve() {
	int ans = 0;

	if (K % 2 == 0) {
		for_(v,0,N) {
			vis.assign(N, false);
			dfs(v, -1, 0, K / 2);
			int ans_v = 0;
			for_(u,0,N) if (vis[u]) ++ans_v;
			maxUpdate(ans, ans_v);
		}
	} else {
		for (pii p : edges) {
			vis.assign(N, false);
			dfs(p.first, -1, 0, K / 2);
			dfs(p.second, -1, 0, K / 2);
			int ans_v = 0;
			for_(u,0,N) if (vis[u]) ++ans_v;
			maxUpdate(ans, ans_v);
		}
	}

	cout << N - ans << endl;
}

int main() {
	cin >> N >> K;
	adj.assign(N, Vec< int >());
	for_(i,0,N-1) {
		int a, b;
		cin >> a >> b;
		--a; --b;
		adj[a].push_back(b);
		adj[b].push_back(a);
		edges.push_back(pii(a,b));
	}

	solve();
}

