constexpr int INF = (1 << 30);

int main() {
	int n, k;
	std::cin >> n >> k;
	std::vector<std::vector<int>> g(n);
	std::vector<std::pair<int, int>> edge;
	for (int i = 0; i < n - 1; i++) {
		int a, b;
		std::cin >> a >> b;
		a--; b--;
		edge.emplace_back(a, b);
		g[a].push_back(b);
		g[b].push_back(a);
	}

	std::vector<int> dist(n);
	auto bfs = [&] (int str, int par) -> void {
		std::queue<std::pair<int, int>> que;
		que.emplace(str, par);
		dist[str] = 0;
		while (not que.empty()) {
			auto [v, p] = que.front(); que.pop();
			for (int u : g[v]) if (u != p) {
				dist[u] = dist[v] + 1;
				que.emplace(u, v);
			}
		}
	};

	int ans = n, h = (k >> 1);

	if (k & 1) {
		for (const auto [a, b] : edge) {
			std::fill(dist.begin(), dist.end(), INF);
			bfs(a, b); bfs(b, a);
			int count = 0;
			for (int d : dist) if (d > h) count++;
			ans = std::min(ans, count);
		}
	} else {
		for (int v = 0; v < n; v++) {
			std::fill(dist.begin(), dist.end(), INF);
			bfs(v, -1);
			int count = 0;
			for (int d : dist) if (d > h) count++;
			ans = std::min(ans, count);
		}
	}

	std::cout << ans << '\n';

	return 0;
}

