const int inf=1e9+1e7,MAXN=2e3+1e1;

struct Node{
	int u,v;
}ed[MAXN];
struct Edge{
	int nxt,to;
}e[MAXN<<1];
bool vis[MAXN];
int head[MAXN],dep[MAXN],n,k,cnt,tot=0,ans=inf;

void Addedge(int u,int v){
	e[++tot]=(Edge){head[u],v};
	head[u]=tot;
	return;
}

void Dfs(int u,int depth){
	vis[u]=true,dep[u]=depth;
	for(int i=head[u];i;i=e[i].nxt){
		int v=e[i].to;
		if(!vis[v]) Dfs(v,depth+1);
	}
	return;
}

void Solve(int x){
	memset(vis,false,sizeof(vis)),cnt=0;
	if(k&1){
		if(x==n) return;
		int u=ed[x].u,v=ed[x].v;
		vis[u]=true,Dfs(v,0),Dfs(u,0);
	}
	else Dfs(x,0);
	for(int i=1;i<=n;i++) if(dep[i]>(k/2)) ++cnt;
	ans=min(cnt,ans);
	return;
}

int main(void){

	// freopen("testdata.in","r",stdin);
