	for(int i=1;i<n;i++){
		ed[i].u=readint,ed[i].v=readint;
		Addedge(ed[i].u,ed[i].v),Addedge(ed[i].v,ed[i].u);
	}
	for(int i=1;i<=n;i++) Solve(i);
	printf("%d\n",max(ans,0));

	return 0;
}

