using namespace std;
typedef pair<int, int> P;

int n, k;
vector<int> G[2005];
int depth[2005];

void dfs(int v, int prev, int dep)
{
	depth[v] = dep;
	for(int i = 0; i < G[v].size(); i++){
		if(G[v][i] == prev) continue;
		dfs(G[v][i], v, dep+1);
	}
}

P cntdfs(int v, int prev, int dep)
{
	P ret = make_pair(0, 0);
	if(depth[v] <= dep) ret.first++;
	if(depth[v] == dep+1) ret.second++;
	for(int i = 0; i < G[v].size(); i++){
		if(G[v][i] == prev) continue;
		P res = cntdfs(G[v][i], v, dep);
		ret.first += res.first;
		ret.second += res.second;
	}
	return ret;
}

int main(void)
{
	cin >> n >> k;
	int a, b;
	for(int i = 0; i < n-1; i++){
		cin >> a >> b;
		G[a].push_back(b);
		G[b].push_back(a);
	}

	int ans = 0;
	for(int i = 1; i <= n; i++){
		dfs(i, -1, 0);
		int cnt = 1, mx = 0;
		for(int j = 0; j < G[i].size(); j++){
			P res = cntdfs(G[i][j], i, k/2);
			cnt += res.first;
			mx = max(mx, res.second);
		}
		if(k % 2) cnt += mx;
		ans = max(ans, cnt);
	}

	cout << n - ans << endl;
	return 0;
}

