pii diam[N];

pii count(int u, int p, int c) {
  bool leaf = true;
  int a = 0, b = 0;
  for (int v : adj[u]) {
    if (v != p) {
      leaf = false;
      pii ans = count(v, u, c + 1);
      if (ans.y > b) {
        b = ans.y;
        a = ans.x;
      } else if (ans.y == b) {
        a += ans.x;
      }
    }
  }
  if (leaf) 
    return pii({1, c});
  return pii({a, b});
}

int dfs (int u, int p, int g, int c) {
  int ret = 0;
  if (c > g)
    ++ret;
  for (int v : adj[u])
    if (v != p)
      ret += dfs(v, u, g, c + 1);
  return ret;
}

