constexpr int INF = (1 << 30) - 1; 
int N, K;
vector < int > G[2005];

int calcDelete(int prev, int node, int depth) {
        int ret = depth >= K;
        for ( auto &to : G[node] ) if ( to != prev ) ret += calcDelete(node, to, depth + 1);
        return ( ret );
}

Pi visit(int p, int v)
{
        Pi r(0, v);
        for ( auto &to : G[v] ) {
                if ( p != to ) {
                        Pi d = visit(v, to);
                        d.first++;
                        if ( d.first > r.first ) r = d;
                }
        }
        return ( r );
}

int diameter()
{
        Pi r = visit(-1, 0);
        Pi t = visit(-1, r.second);
        return ( t.first );
}

