int Lca(int A, int B) {
	if(!(A ^ B)) return A; 
	while(Dep[A] > Dep[B])
		for(int i = 20; i > 0; i--) 
			if(Dep[F[A][i]] >= Dep[B]) A = F[A][i];
	while(A ^ B) {
		for(int i = 20; i >= 0; i--) 
			if(F[A][i] ^ F[B][i]) 
				A = F[A][i], B = F[B][i];
		if(!(Pa[A] ^ Pa[B])) A = B = Pa[A];
	}
	return A;
}
