		return;
	}
	for(int i = Last[Now]; i; i = Tree[i].Next) {
		int To = Tree[i].To;
		if(!Vis[To]) {	
			Count += 1; 
			Find(To, Now, Depth + 1);
			Size[Now] += Size[To];
		}
	}
}
