	Vis[Now] = true; Size[Now] = 1;	
	if(Depth >= K) {  
		Ans = Min(Ans, N - Count);
		return;
	}
	if(Flag[Now]) {
		Flag[Now] = false;
		Count += 1;
	}
	for(int i = Last[Now]; i; i = Tree[i].Next) {
		int To = Tree[i].To;
		if(!Vis[To]) {	
			Find(To, Now, Depth + 1);
