void up(int u,int p)
{
	f[u][0]=1;
	for (int i=h[u];i;i=nx[i])
		if (to[i]!=p)
		{
			up(to[i],u);
			for (int j=0;f[to[i]][j];j++)
				f[u][j+1]+=f[to[i]][j];
		}
}
void down(int u,int p)
{
	for (int j=0;f[u][j];j++)
		g[u][j]+=f[u][j];
	for (int i=h[u];i;i=nx[i])
		if (to[i]!=p)
		{
			for (int j=0;g[u][j];j++)
				g[to[i]][j+1]+=g[u][j]-(j-1>=0?f[to[i]][j-1]:0);
			down(to[i],u);
		}
}
