	int to;
	edge *nxt;
}edges[MAXN*2 + 5], *adj[MAXN + 5], *ecnt = &edges[0];
void addedge(int u, int v) {
	edge *p = (++ecnt);
	p->to = v, p->nxt = adj[u], adj[u] = p;
	p = (++ecnt);
	p->to = u, p->nxt = adj[v], adj[v] = p;
}
queue<int>que;
int dis[MAXN + 5], vis[MAXN + 5], N, K;
int solve() {
	int ret = 0;
	while( !que.empty() ) {
		int f = que.front(); que.pop();
		if( dis[f] > K/2 ) ret++;
		for(edge *p=adj[f];p!=NULL;p=p->nxt) {
			if( !vis[p->to] ) {
				vis[p->to] = true;
				dis[p->to] = dis[f] + 1;
				que.push(p->to);
			}
		}
	}
	return ret;
}
int main() {
	scanf("%d%d", &N, &K);
	for(int i=1;i<N;i++) {
		int A, B;
