				if( i > p->to ) continue;
				for(int j=1;j<=N;j++) {
					vis[j] = false;
					dis[j] = 0;
				}
				vis[i] = true; que.push(i);
				vis[p->to] = true; que.push(p->to);
				ans = min(ans, solve());
			}
		}
	}
	printf("%d\n", ans);
}

