				dist[it.second][edge[it.first][i]] = dist[it.first][it.second]+1;
				q.push(make_pair(it.second, edge[it.first][i]));
			}
		}
		for (int i = 0; i < edge[it.second].size(); i++) {
			if (dist[it.first][edge[it.second][i]] >= 1 << 25) {
				dist[it.first][edge[it.second][i]] = dist[it.first][it.second]+1;
				q.push(make_pair(it.first, edge[it.second][i]));
			}
		}
	}
	for (int i = 0; i < n; i++) {
		for (int j = 0; j < n; j++) {
			if (dist[i][j] > k)	cnt[i]++;
		}
	}
	for (int ret = 0;; ret++) {
		int erase = -1, num = 0;
		for (int i = 0; i < n; i++) {
			if (num < cnt[i])	num = cnt[i], erase = i;
		}
		if (erase == -1) {
			cout << ret << endl;
			return 0;
		}
		for (int i = 0; i < n; i++) {
			if (dist[i][erase] > k)	cnt[i]--;
		}
		cnt[erase] = -1;
	}
}

