// -----------------------------------------------------------------------------

const int N = 2e3 + 5, INF = 1e7 + 5;
int n, k;
int q[N], q_top = 0, d[N];
vector<int> g[N];

void bfs() {
	for (int k = 0; k < q_top; ++k) {
		int u = q[k];
		for (int v : g[u]) {
			int dist = d[u] + 2;
			if (d[v] <= dist) continue;
			d[v] = dist;
			q[q_top++] = v;
		}
	}
}

int solve_vertex(int u) {
	for (int i = 0; i < n; ++i) d[i] = INF;
	q_top = 0;
	d[u] = 0; q[q_top++] = u;
	bfs();
	int cnt = 0;
	for (int i = 0; i < n; ++i) {
		if (d[i] > k) {
			++cnt;
		}
	}
	return cnt;
}

int solve_edge(int u, int v) {
	for (int i = 0; i < n; ++i) d[i] = INF;
	q_top = 0;
	d[u] = 1; q[q_top++] = u;
	d[v] = 1; q[q_top++] = v;
	bfs();
	int cnt = 0;
	for (int i = 0; i < n; ++i) {
		if (d[i] > k) {
			++cnt;
		}
	}
	return cnt;
}

