		g[v].push_back(u);
	}
	int ans = INF;
	for (int u = 0; u < n; ++u) {
		ans = min(ans, solve_vertex(u));
		for (int v : g[u]) {
			if (u < v) {
				ans = min(ans, solve_edge(u, v));
			}
		}
	}
	cout << ans << endl;
}

