using namespace std;
using ull = unsigned long long;
using Graph = vector<vector<int>>;
using P = pair<int, int>;

int N;

vector<int> dijikstra(const Graph& g, int s) {
	priority_queue<P, vector<P>, greater<P>> que;
	vector<int> d(N, INF);
	d[s] = 0;
	que.push(P(0, s));

	while (!que.empty()) {
		P p = que.top();
		que.pop();
		int v = p.second;
		if (d[v] < p.first) continue;

		for (const auto& to : g[v]) {
			if (d[to] > d[v] + 1) {
				d[to] = d[v] + 1;
				que.emplace(d[to], to);
			}
		}
	}

	return d;
}

int main()
{
