		A--; B--;

		g[A].emplace_back(B);
		g[B].emplace_back(A);
	}

	int ans = 20000;

	for (int i = 0; i < N; ++i) {
		auto&& d = dijikstra(g, i);
		int count = count_if(d.begin(), d.end(), [K](const int& di) { return di > K / 2; });

		ans = min(ans, count);
	}

	cout << ans << endl;

	return 0;
}

