#include <bits/stdc++.h>
using namespace std;
using pii = pair<int, int>;

const int MAX = 2000;
vector<int> G[MAX];

int calc(int v, int prev, int K, int d = 0) {
	int res = d <= K;
	for (auto to : G[v]) if (to != prev) {
		res += calc(to, v, K, d + 1);
	}
	return res;
}

int main()
{
	int N, K;
	cin >> N >> K;
	for (int i = 0; i < N - 1; i++) {
		int A, B;
		cin >> A >> B; --A, --B;
		G[A].push_back(B);
		G[B].push_back(A);
	}
	if (K % 2 == 0) {
		int ma = 0;
		for (int i = 0; i < N; i++) {
			ma = max(ma, calc(i, -1, K / 2));
		}
		cout << N - ma << endl;
		return 0;
	}
	K /= 2;
	int ma = 0;
	for (int i = 0; i < N; i++) {
		int all = 1, d = 0;
		for (auto to : G[i]) {
			int a = calc(to, i, K, 1), b = calc(to, i, K + 1, 1);
			all += a;
			d = max(d, b - a);
		}
		ma = max(ma, all + d);
	}
	cout << N - ma << endl;
	return 0;
}

