    cin.tie(nullptr);
    int n, k;
    cin >> n >> k;
    vector<vector<int>> tree(n);
    vector<pair<int, int>> edges(n - 1);
    for (auto& i : edges) {
        cin >> i.first >> i.second;
        i.first--; i.second--;
        tree[i.first].push_back(i.second);
        tree[i.second].push_back(i.first);
    }
    vector<vector<int>> dists(n, vector<int>(n, -1));
    for (auto i = 0; i < n; i++) {
        queue<int> que;
        que.push(i);
        dists[i][i] = 0;
        while (!que.empty()) {
            auto pos = que.front();
            que.pop();
            for (auto& j : tree[pos]) {
                if (dists[i][j] >= 0) continue;
                dists[i][j] = dists[i][pos] + 1;
                que.push(j);
            }
        }
    }
    int result = n;
    if (k % 2) {
        for (auto& i : edges) {
            int cnt = 0;
            for (auto j = 0; j < n; j++)
                if (min(dists[i.first][j], dists[i.second][j]) > k / 2) cnt++;
            result = min(result, cnt);
        }
    }
    else {
        for (auto i = 0; i < n; i++) {
            int cnt = 0;
            for (auto j = 0; j < n; j++)
                if (dists[i][j] > k / 2) cnt++;
            result = min(result, cnt);
        }
    }
    cout << result << endl;
    return 0;
}

