using vertex = int;
using edge = pair<vertex, vertex>;
using graph = map<vertex, vector<edge>>;

int diam(graph g, vertex s) {
  {
    queue<pair<vertex, int>> q;
    q.push({s, 0});

    set<vertex> visited;
    visited.insert(s);

    pair<vertex, int> p;
    while (!q.empty()) {
      p = q.front();
      visited.insert(p.first);
      q.pop();

      for (auto&& p2 : g[p.first]) {
        if (visited.find(p2.second) != visited.end()) continue;
        q.push({p2.second, p.second + 1});
      }
    }
    s = p.first;
  }
  {
    queue<pair<vertex, int>> q;
    q.push({s, 0});

    set<vertex> visited;
    visited.insert(s);

    pair<vertex, int> p;
    while (!q.empty()) {
      p = q.front();
      visited.insert(p.first);
      q.pop();

      for (auto&& p2 : g[p.first]) {
        if (visited.find(p2.second) != visited.end()) continue;
        q.push({p2.second, p.second + 1});
      }
    }
    return p.second;
  }
}

