template <class T> bool chmin(T &a, T b) { if (a > b) { a = b; return true; } return false; }
template <class T> bool chmax(T &a, T b) { if (a < b) { a = b; return true; } return false; }
void dfs(vvi &g, vvi &dp, int v, int p) {
	dp[v][0] = 1;
	REP(i, g[v].size()) {
		if (g[v][i] == p)continue;
		dfs(g, dp, g[v][i], v);
		REP(j, dp[g[v][i]].size()) {
			if (dp[g[v][i]][j] == 0)break;
			dp[v][j + 1] += dp[g[v][i]][j];
		}
	}
}

void dfs2(vvi &g, const vvi &dp, vvi &dp2, int v, int p) {
	if (p < 0) {
		FOR(i, 1, dp2[v].size())dp2[v][i] = dp[v][i];
	}
	else {
		dp2[v][0] = 1;
		FOR(i, 1, dp2[v].size())dp2[v][i] = dp[v][i] + dp2[p][i - 1] - (i > 1 ? dp[v][i - 2] : 0);
	}
	REP(i, g[v].size()) {
		if (g[v][i] == p)continue;
		dfs2(g, dp, dp2, g[v][i], v);
	}
}
int f(vvi &g, int s) {
	int n = g.size();
	queue<int> q;
	q.push(s);
	vi d(n, INF);
	d[s] = 0;
	while (!q.empty()) {
		int p = q.front(); q.pop();
		REP(i, g[p].size()) {
			if (d[g[p][i]] == INF) {
				d[g[p][i]] = d[p] + 1;
				q.push(g[p][i]);
			}
		}
	}
	int pos = s, tmp = 0;
	REP(i, n) {
		if (chmax(tmp, d[i])) {
			pos = i;
		}
	}
	return pos;
}
int diam(vvi &g) {
	int s = f(g, 0);
	int t = f(g, s);
	queue<int> q;
	q.push(s);
	int n = g.size();
	vi d(n, INF);
	d[s] = 0;
	while (!q.empty()) {
		int p = q.front(); q.pop();
		REP(i, g[p].size()) {
			if (d[g[p][i]] == INF) {
				d[g[p][i]] = d[p] + 1;
				q.push(g[p][i]);
			}
		}
	}
	return d[t];

}

