#include <bits/stdc++.h>
using namespace std;

const int MAX = 2005;
int n, k, t, rad, td[MAX], tf[MAX], mk[MAX], d[MAX], sz[MAX];
vector <int> g[MAX];

void dfs(int u, int p = -1, int l = 0) {
	d[u] = l;
	td[u] = ++t;

	for(int v : g[u]) {
		if(v != p) {
			dfs(v, u, l + 1);
			sz[u] += sz[v];
		}
	}

	tf[u] = t;
	sz[u]++;
}

int main() {
	scanf("%d%d", &n, &k);

	for(int i = 1; i < n; i++) {
		int a, b; scanf("%d%d", &a, &b);
		g[a].push_back(b);
		g[b].push_back(a);
	}

	queue <int> q;

	for(int i = 1; i <= n; i++)
		if((int) g[i].size() == 1)
			q.push(i);

	while(!q.empty()) {
		int u = q.front();
		q.pop();

		if(mk[u])
			continue;

		rad = u;
		mk[u] = 1;

		for(int v : g[u]) {
			if(!mk[v])
				q.push(v);
		}
	}

	dfs(rad);

	int ans = INT_MAX;
	for(int u = 1; u <= n; u++) {
		int cost = 0, M = -1;

		for(int v = 1; v <= n; v++) {
			if(d[v] < d[u])
				continue;

			cost += d[v] - d[u];

			if(td[v] >= td[u] && td[v] <= tf[u])
				continue;

			if(d[u] + d[v] <= k)
				M = max(M, d[v]);
		}

		if(M == -1)
			continue;

		cost -= M - d[u];
		ans = min(ans, cost);
	}

	for(int u = 1; u <= n; u++) {
		int subtree = 0;

		for(int v : g[rad]) {
			if(td[u] >= td[v] && td[u] <= tf[v]) {
				subtree = v;
				break;
			}
		}

		int cost = n - sz[subtree] - 1;

		for(int v = 1; v <= n; v++) {
			if(td[v] >= td[subtree] && td[v] <= tf[subtree])
				cost += max(0, d[v] - d[u]);
		}

		ans = min(ans, cost);
	}

	printf("%d\n", ans);
	return 0;
}

