int n, k;
int depth[2][MAXN];
int mark[MAXN];
vector<int> net[MAXN];

void dfs(int v, int d, int t) {
    mark[v] = 1;
    depth[t][d]++;

    for(int i = 0; i < SZ(net[v]); ++i) {
        if(!mark[net[v][i]])
            dfs(net[v][i], d + 1, t);
    }
}

int main() {
    //freopen("input.txt", "r", stdin);
    //freopen("output.txt", "w", stdout);

    cin >> n >> k;
    for(int i = 0; i < n-1; ++i) {
        int u, v; cin >> u >> v;
        u--, v--;
        net[u].push_back(v);
        net[v].push_back(u);
    }
    int ans = INT_MAX;
    if(k%2 == 0) {
        for(int i = 0; i < n; ++i) {
            CLR(mark, 0);
            //CLR(depth, 0);
            for(int i = 0; i < n; ++i)
                depth[0][i] = 0;

            dfs(i, 0, 0);

            int res = 0;
            for(int i = k/2 + 1; i < n; ++i)
                res += depth[0][i];
            ans = min(res, ans);
        }
    } else {
        for(int i = 0; i < n; ++i) {
            for(int j = 0; j < SZ(net[i]); ++j) {
                CLR(mark, 0);
                //CLR(depth, 0);
                for(int i = 0; i < n; ++i)
                    depth[0][i] = depth[1][i] = 0;

                mark[net[i][j]] = 1;
                dfs(i, 0, 0);

                mark[net[i][j]] = 0;
                mark[i] = 1;
                dfs(net[i][j], 0, 1);

                int a = 0;
                int b = 0;
                for(int i = k/2 + 2; i < n; ++i) {
                    a += depth[0][i];
                    b += depth[1][i];
                }
                int res = min(a + b + depth[0][k/2 + 1], a + b + depth[1][k/2 + 1]);
                ans = min(ans, res);
            }
        }

    }
    cout << ans << endl;

    return 0;
}

