#include <cstdio>
#include <vector>
std::vector < int > E[2001];
int N, K, q[2001], fa[2001], f[2001][2001], O = 1000000000;
int main()
{
	scanf("%d%d", &N, &K);
	for (int i = 1, u, v; i < N; i++)
	{
		scanf("%d%d", &u, &v);
		E[u].push_back(v);
		E[v].push_back(u);
	}
	int H = 0, T = 1;
	q[1] = 1;
	while (H < T)
	{
		int u = q[++H];
		for (int v : E[u])
			if (v != fa[u])
				fa[q[++T] = v] = u;
	}
	for (int i = N; i; i--)
	{
		int u = q[i];
		f[u][0] = 1;
		for (int v : E[u])
			if (v != fa[u])
				f[u][0] += f[v][0];
		for (int j = 0; j <= K; j++)
		{
			int small = std::min(K - j, j), big = j, M = 0;
			for (int v : E[u])
				if (v != fa[u])
				{
					f[u][j + 1] += f[v][small];
					M = std::min(M, f[v][big] - f[v][small]);
				}
			f[u][j + 1] += M;
		}
		for (int j = 1; j <= K + 1; j++)
			f[u][j] = std::min(f[u][j], f[u][j - 1]);
		O = std::min(O, N - f[u][0] + f[u][K + 1]);
	}
	printf("%d\n", O);
	return 0;
}

