#pragma GCC optimize("O3")
#include <bits/stdc++.h>
using namespace std;
constexpr int MAXN = 2000;
vector<int> G[MAXN * 2]; //1 ~ 2N - 1
int height[MAXN * 2], depth[MAXN * 2];
void build(int u, int p, int d) {
	int h = 0;
	for (int v : G[u]) {
		if (v == p) continue;
		build(v, u, d + 1);
		h = max(h, height[v] + 1);
	}
	height[u] = h, depth[u] = d;
}
int uAsCenter(int N, int K, int u) {
	if (G[u].size() == 1) return N - 1;
	vector<int> vh;
	build(u, -1, 0);
	transform(G[u].begin(), G[u].end(), back_inserter<decltype(vh)>(vh), [](int v) {
		return height[v] + 1;
	});
	nth_element(vh.begin(), vh.begin() + 1, vh.end(), greater<int>());
	int _K = min(K, vh[1]);
	return count_if(depth + 1, depth + N + 1, [_K](int d) {
		return d > _K;
	});
}
int main() {
	ios::sync_with_stdio(false);
	cin.tie(nullptr);
	int N, K;
	cin >> N >> K;
	for (int i = 1; i < N; i++) {
		int u, v, w = N + i;
		cin >> u >> v;
		G[u].push_back(w), G[w].push_back(v);
		G[v].push_back(w), G[w].push_back(u);
	}
	int ans = N - 1;
	for (int i = 1; i < 2 * N; i++) {
		ans = min(ans, uAsCenter(N, K, i));
	}
	cout << ans << endl;
	return 0;
}

