#include <bits/stdc++.h>
using namespace std;
typedef pair<int,int> pii;

const int MAXN = 2000 + 10;
const int MAXM = 2000 + 10;

vector<int> G[MAXN+10];
vector<pii> E;

void addedge(int u, int v)
{
    G[u].push_back(v);
    G[v].push_back(u);
    E.push_back(pii(u, v));
}

void bfs(int n, int s, bool vis[], int d[])
{
    for (int i=1; i<=n; i++) vis[i] = false;
    queue<int> q;
    q.push(s);
    d[s] = 0;
    vis[s] = true;
    while(!q.empty())
    {
        int u = q.front(); q.pop();
        for (auto v : G[u])
        {
            if (!vis[v])
            {
                vis[v] = true;
                d[v] = d[u] + 1;
                q.push(v);
            }
        }
    }
}

bool vis[MAXN+10];
int d[MAXN+10], d1[MAXN+10];

int main()
{
    int n, k;
    scanf("%d%d", &n, &k);
    for (int i=1; i<=n-1; i++)
    {
        int u, v;
        scanf("%d%d", &u, &v);
        addedge(u, v);
    }
    int ans = n;
    if (k%2 == 0)
    {
        for (int u = 1; u <= n; u++)
        {
            bfs(n, u, vis, d);
            int cnt = 0;
            for (int v = 1; v <= n; v++)
            {
                if (d[v] > k/2) cnt++;
            }
            ans = min(ans, cnt);
        }
    }
    else
    {
        for (auto e : E)
        {
            int cnt = 0;
            int u = e.first;
            int v = e.second;
            bfs(n, u, vis, d);
            bfs(n, v, vis, d1);
            for (int i = 1; i <= n; i++)
            {
                if (min(d[i], d1[i]) > (k-1)/2) cnt++;
            }
            ans = min(ans, cnt);
        }
    }
    printf("%d", ans);
}

