int MOD=1000000007;
int inf=1e9+7;
struct Node{
    int no;
    int par;
    int dist;
    bool use;
    vector<Node*> child;
    void build(int i){
        no=i;
        par=i;
        dist=0;
        use=false;
    }
};
struct Tree{
    int n;
    vector<Node> node;
    vector<int> euler;
    Tree(int k){
        n=k;
        node.resize(n+1);
        for(int i=1;i<=n;++i){
            node[i].build(i);
        }
    }
    void input(int k){
        for(int i=0;i<k;++i){
            int a,b;cin>>a>>b;
            node[a].child.push_back(&node[b]);
            node[b].child.push_back(&node[a]);
        }
    }
    void BFS(int s){
        rep1(i,n){
            node[i].build(i);
        }
        queue<Node> que;
        que.push(node[s]);
        while(!que.empty()){
            Node buf=que.front();que.pop();
            int num=buf.child.size();
            for(int i=0;i<num;++i){
                if(buf.child[i]->no!=buf.par){
                    buf.child[i]->par=buf.no;
                    buf.child[i]->dist=buf.dist+1;
                    que.push(*buf.child[i]);
                }
            }
        }
    }
    void BFS3(int s){
        rep1(i,n){
            node[i].par=i;
            node[i].dist=0;
        }
        queue<Node> que;
        que.push(node[s]);
        while(!que.empty()){
            Node buf=que.front();que.pop();
            int num=buf.child.size();
            for(int i=0;i<num;++i){
                if(buf.child[i]->no!=buf.par){
                    buf.child[i]->par=buf.no;
                    buf.child[i]->dist=buf.dist+1;
                    que.push(*buf.child[i]);
                }
            }
        }
    }
    int BFS2(int s,int& res,int k){
        rep1(i,n){
            node[i].use=false;
        }
        queue<Node> que;
        que.push(node[s]);
        int cnt=1;
        int mx=0;
        int mxind;
        while(!que.empty()){
            ++cnt;
            Node buf=que.front();que.pop();
            node[buf.no].use=true;
            int num=buf.child.size();
            for(int i=0;i<num;++i){
                if(buf.child[i]->no!=buf.par){
                    buf.child[i]->par=buf.no;
                    if(buf.child[i]->dist>k){
                        ++res;
                    }
                    if(buf.child[i]->dist>mx){
                        mxind=buf.child[i]->no;
                        mx=buf.child[i]->dist;
                    }
                    que.push(*buf.child[i]);
                }
            }
        }
        Tree sub=*this;
        sub.BFS3(mxind);
        int D=0;
        rep1(i,n){
            if(sub.node[i].use){
                D=max(D,sub.node[i].dist);
            }
        }
        if(D>k)res=inf;
        return cnt;
    }
    void DFS(Node& node){
        if(node.child.size()==1&&node.par!=node.no){
            return;
        }
        else{
            int num=node.child.size();
            for(int i=0;i<num;++i){
                if(node.child[i]->no!=node.par){
                    DFS(*node.child[i]);
                }
            }
        }
    }
    void solve(int k){
        int res=inf;
        rep1(i,n){
            BFS(i);
            int num=node[i].child.size();
            rep(j,num){
                int buf=0;
                int cnt=BFS2(node[i].child[j]->no,buf,k);
                res=min(res,buf+n-cnt);
            }
        }
        cout<<res<<endl;
    }
};

signed main(){
    int n,k;cin>>n>>k;
    Tree tree(n);
    tree.input(n-1);
    tree.solve(k);
    return 0;
}

