bool comp( const ii &a, const ii &b ) {
    return ar[a.fi] < ar[b.fi];
}

void dfs( int n, int back, int s ) {
    vector<ii> v;
    ar[n] = s;
    vector<int> ss;
    beg[n] = ++cnt;
    name[cnt] = n;
    for(int i=0;i<w[n].size();i++) { ss.pb( 0 );
        if( w[n][i] != back ) {
            dfs( w[n][i], n, s + 1 );
            //, printf("--- %d %d\n",n,t[j].fi);
        }
    }
    en[n] = cnt;
    for(int i=0;i<w[n].size();i++)
        if( w[n][i] != back ) {
            int t = w[n][i];
            for(int j=beg[t];j<=en[t];j++)
                v.pb( ii( name[j], i ) ), ss[i]++;
        }
    sort( all( v ), comp );
    for(int i=0,j=0,k=v.size()-1;i<=K-i;i++) {
        int l = K-i;
        while( k >= 0 && ar[v[k].fi] > s+l ) ss[v[k].se]--, k--;
        while( j < v.size() && ar[v[j].fi] <= s+i ) ss[v[j].se]--, j++;
        int maxi = 0;
        for(int m=0;m<ss.size();m++) umax( maxi, ss[m] );
        //printf("asd (%d)%d --> %d %d (%d)\n",n,i,j,maxi,v.size());
        umax( ans, j + maxi );
    }

    v.pb( ii( n, 0 ) );
}

