void add ( int x, int y ) {
	To[++e] = y ;
	Next[e] = Begin[x] ;
	Begin[x] = e ;
}
void dfs ( int x ) {
	int i, u ;
	if (dis[x] == m) return ;
	for ( i = Begin[x] ; i ; i = Next[i] ) {
		u = To[i] ;
		if (vis[u]) continue ;
		dis[u] = dis[x]+1 ;
		vis[u] = 1 ;
		dfs(u) ;
	}
}
void solve_even() {
