		vis[i] = 1 ;
		dfs(i) ;
		for ( j = 1, x = n ; j <= n ; j ++ )
			if (vis[j]) x -- ;
		ans = min(ans, x) ;
	}
}
void solve_odd() {
	int i, j, x ;
	m >>= 1 ;
	for ( i = 2 ; i <= e ; i += 2 ) {
		memset ( dis, 0, sizeof dis ) ;
		memset ( vis, 0, sizeof vis ) ;
		vis[To[i]] = vis[To[i^1]] = 1 ;
		dfs(To[i]) ;
		dfs(To[i^1]) ;
		for ( j = 1, x = n ; j <= n ; j ++ )
			if (vis[j]) x -- ;
		ans = min(ans, x) ;
	}
}
