inline void dfs (int u, int p) {
	for (int e = head[u]; e; e = nxt[e]) {
		int v = to[e];
		if (v == p) continue;
		s[u].push_back (v);
		dfs (v, u);
		f[u][0] += f[v][0] + 1;
	}
	if (!s[u].size ()) return;
	for (int i = 1; i <= k; i++) {
		int p = i - 1, q = min (i - 1, k - i - 1);
		if (s[u].size () == 1) { f[u][i] = f[s[u][0]][p]; continue; }
		l[s[u][0]] = q < 0 ? f[s[u][0]][0] + 1 : f[s[u][0]][q];
		for (int x = 1; x < s[u].size (); x++) l[s[u][x]] = l[s[u][x - 1]] + (q < 0 ? f[s[u][x]][0] + 1 : f[s[u][x]][q]);
		r[s[u][s[u].size () - 1]] = q < 0 ? f[s[u][s[u].size () - 1]][0] + 1 : f[s[u][s[u].size () - 1]][q];
		for (int x = s[u].size () - 2; x >= 0; x--) r[s[u][x]] = r[s[u][x + 1]] + (q < 0 ? f[s[u][x]][0] + 1 : f[s[u][x]][q]);
		f[u][i] = min (f[s[u][0]][p] + r[s[u][1]], f[s[u][s[u].size () - 1]][p] + l[s[u][s[u].size () - 2]]);
		for (int x = 1; x < s[u].size () - 1; x++) f[u][i] = min (f[u][i], l[s[u][x - 1]] + r[s[u][x + 1]] + f[s[u][x]][p]);
		f[u][i] = min (f[u][i], f[u][i - 1]);
	}
}
