const int MAXN = 2005;
int N, K;

int f[MAXN];
int dep[MAXN];
int wei[MAXN];
vector< int > T[MAXN];

struct cmp {
  bool operator()(int a, int b) {
    if (dep[a] != dep[b])
      return dep[a] > dep[b];
    return a < b;
  }
};

set< int, cmp > S[MAXN];

void calc(int i, int dad = -1, int d = 0) {
  S[i].clear();
  dep[i] = d;
  wei[i] = 1;

  int best = -1;

  for (int j : T[i]) {
    if (j != dad) {
      calc(j, i, d + 1);
      wei[i] += wei[j];
      if (best == -1 || wei[j] > wei[best])
	best = j;
    }
  }

  S[i].swap(S[best]);
  S[i].insert(i);

  for (int j : T[i]) 
    if (j != dad) 
      for (int k : S[j])
	S[i].insert(k);

  while (!S[i].empty() && dep[*S[i].begin()] > min(K, 2 * dep[i] - 2))
    S[i].erase(S[i].begin());

  f[i] = S[i].size();
}

int kill[MAXN];

void dfs(int i, int dad = -1, int killed = 0) {
  kill[i] = killed + wei[i] - 1;

  int sum = 0;

  for (int j : T[i]) 
    if (j != dad)
      sum += wei[j] - f[j];

  for (int j : T[i])
    if (j != dad)
      dfs(j, i, killed + sum - wei[j] + f[j]);
}

int solve(int i) {
  calc(i);
  dfs(i);

  int sol = 1e9;
  FOR(j, 1, N + 1)
    if (dep[j] <= K)
      sol = min(sol, kill[j]);

  return sol;
}

