    diam.push_back(now);
    ll nowdis = t.first;
    for (int i = 0; i < t.first; i++) {
        int s = G[now].size();
        for (int j = 0; j < s; j++) {
            if (d[G[now][j].to] == nowdis - G[now][j].cost && gsub[t.second][G[now][j].to]) {
                nowdis -= G[now][j].cost;
                now = G[now][j].to;
                diam.push_back(now);
                break;
            }
        }
    }
    return t.first;
}

