int cc[MAXN + 10];
int level[MAXN + 10];
int L[MAXN + 10], R[MAXN + 10];
int ii = 0;

void dfs(int u, int p = -1) {
   cc[u] = 1;
   L[u] = ++ii;
   level[u] = p == -1 ? 0 : level[p] + 1;

   for(int v : G[u]) {
      if(v == p) continue;
      dfs(v, u);
      cc[u] += cc[v];
   }

   R[u] = ii;
}

int diam() {
   dfs(1);
   int u = max_element(level + 1, level + N + 1) - level;
   dfs(u);
   return *max_element(level + 1, level + N + 1);
}

int calc2(int u, int kk, int p) {
   if(kk == 0) return cc[u];
   int res = 0;
   for(int w : G[u]) {
      if(w == p) continue;
      res += calc2(w, min(kk / 2, kk - 1), u);
   }
   return res;
}

int calc(int u, int v) {
   int res = 0, kk = 0, p = -1;
   while(u != v) {
      for(int w : G[u]) {
         if(w == p || L[w] <= L[v] && R[v] <= R[w]) {
            continue;
         }
         res += calc2(w, min(kk, K - kk), u);
      }
      int w = *find_if(G[u].begin(), G[u].end(), [&](int w) { return w != p && L[w] <= L[v] && L[v] <= R[w]; });
      p = u;
      u = w;
   }
   return res;
}

int solve() {
   if(diam() <= K) return 0;
   int mn = N - K;
   for(int u = 1; u <= N; u++) {
      dfs(u);
      vector<int> diam_v;
      for(int v = 1; v <= N; v++) {
         if(level[v] == K) diam_v.push_back(v);
      }
      for(int v : diam_v) {
         mn = min(mn, calc(u, v));
      }
   }
   return mn;
}

