void bfs()
{
	for(int i=0;i<N;i++)for(int j=0;j<N;j++)dist[i][j]=1e9;
	queue<int>q;
	for(int i=0;i<n;i++)
	{
		q.push(0);
		q.push(i);
		q.push(i);
	}
	while(!q.empty())
	{
		int move=q.front();q.pop();
		int org=q.front();q.pop();
		int now=q.front();q.pop();
		if(dist[org][now]<=move)continue;
		dist[org][now]=move;
		for(int i=0;i<v[now].size();i++)
		{
			int to=v[now][i];
			q.push(move+1);
			q.push(org);
			q.push(to);
		}
	}

}
