using namespace std;

using vertex = int;
using edge = pair<vertex, vertex>;
using graph = map<vertex, vector<edge>>;

set<vertex> deleted;

pair<vertex, int> diam(graph g, vertex s) {
  {
    queue<pair<vertex, int>> q;
    q.push({s, 0});

    set<vertex> visited;
    visited.insert(s);

    pair<vertex, int> p;
    while (!q.empty()) {
      p = q.front();
      visited.insert(p.first);
      q.pop();
      if (deleted.find(p.first) != deleted.end()) continue;
      for (auto&& p2 : g[p.first]) {
        if (deleted.find(p2.second) != deleted.end()) continue;
        if (visited.find(p2.second) != visited.end()) continue;
        q.push({p2.second, p.second + 1});
      }
    }
    s = p.first;
  }
  {
    queue<pair<vertex, int>> q;
    q.push({s, 0});

    set<vertex> visited;
    visited.insert(s);

    pair<vertex, int> p;
    while (!q.empty()) {
      p = q.front();
      visited.insert(p.first);
      q.pop();
      if (deleted.find(p.first) != deleted.end()) continue;
      for (auto&& p2 : g[p.first]) {
        if (deleted.find(p2.second) != deleted.end()) continue;
        if (visited.find(p2.second) != visited.end()) continue;
        q.push({p2.second, p.second + 1});
      }
    }
    return {p.first, p.second};
  }
}

int main() {
  std::ios::sync_with_stdio(false);

  int N, K;
  cin >> N >> K;

  graph g;
  for (int i = 0; i < N - 1; ++i) {
    int a, b;
    cin >> a >> b;
    g[a].push_back({a, b});
    g[b].push_back({b, a});
  }

  int ans = 0;
  int s = 1;
  while (true) {
    pair<vertex, int> d = diam(g, s);
    if (d.second - K <= 0) break;
    deleted.insert(d.first);
    ++ans;
    for (int i = 0; i < N; ++i) {
      if (!g[i].empty()) s = i;
    }
  }
  cout << ans << endl;
}

