int w[2222] ; 
int wp1[2222] ; 
int sol(int root, int K){
    memset(w, 0, sizeof(w)) ; 
    memset(wp1, 0, sizeof(wp1)) ; 
    int wsum = 0 ; 
    for(auto x: adj[root]){
        w[x] = count(x, K/2, root) ; 
        wsum += w[x] ; 
    }
    if(K%2){
        for(auto x: adj[root])
