const int maxn = 2000;
const int oo = 1000000000;
int n,k,head[maxn+1],link[maxn*2],adj[maxn*2],d[maxn+1];
void enter()
{
	cin >> n >> k;
	for (int i=1; i<=n-1; i++)
	{
		int a,b;
		cin >> a >> b;
		link[i*2-1]=head[a];
		adj[i*2-1]=b;
		head[a]=i*2-1;
		link[i*2]=head[b];
		adj[i*2]=a;
		head[b]=i*2;
	}
}
int bfs(int s,int diameter)
{
	for (int i=1; i<=n; i++)
		d[i]=oo;
	d[s]=0;
	queue<int> q;
	q.push(s);
	int res=1;
	do
	{
		int t=q.front();
		q.pop();
		if (d[t]==diameter) break;
		int i=head[t];
		while (i!=0)
		{
			if (d[adj[i]]>d[t]+1)
			{
				if (d[adj[i]]==oo) res++;
				d[adj[i]]=d[t]+1;
				q.push(adj[i]);
			}
			i=link[i];
		}
	}
	while (!q.empty());
	return res;
}
void solve()
{
	int res=0;
	if (k%2==0)
	{
		for (int i=1; i<=n; i++)
			res=max(res,bfs(i,k/2));
	}
	else
	{
		for (int i=1; i<=n; i++)
		{
			int j=head[i];
			while (j!=0)
			{
				res=max(res,max(bfs(i,k/2),bfs(adj[j],k/2)));
				j=link[j];
			}
		}
	}
	cout << n-res;
}
