void BFS0(int u){
    queue<int> Q;
    for(int i=0;i<N;i++){
        state[i]=0;
        dis0[i]=-INF;
    }
    state[u]=1;
    dis0[u]=0;
    Q.push(u);
    while(!Q.empty()){
        int a=Q.front();
        Q.pop();
        for(int i=0;i<S[a].size();i++){
            int b=S[a][i];
            if(rem[b]&&!state[b]){
                Q.push(b);
                state[b]=1;
                dis0[b]=dis0[a]+1;
            }
        }
    }
}

void BFS1(int u){
    queue<int> Q;
    for(int i=0;i<N;i++){
        state[i]=0;
        dis1[i]=-INF;
    }
    state[u]=1;
    dis1[u]=0;
    Q.push(u);
