int n;

int find(vec<vec<int>> edge, int k, int s)
{
	vec<int> dp(n, 0);
	queue<pii> keep;
	keep.push(mp(s, 0));
	int ans = 0;
	while(!keep.empty()) {
		pii get = keep.front();
		keep.pop();
		if (dp[get.first]) continue;
		if (get.second > k) break;
		ans++;
		dp[get.first] = 1;
		if (get.second == k) continue;
		rep(i, edge[get.first].size()) {
			keep.push(mp(edge[get.first][i], get.second + 1));
		}
	}
	return ans;
}


int find1(vec<vec<int>> edge, int k, int s)
{
	vec<int> dp(n, 0);
	queue<pii> keep;
	vec<int> check(n, 0);
	int max_check = 0;
	keep.push(mp(s, 0));
	vec<int> count(n, 0);
	int ans = 0;
	while(!keep.empty()) {
		pii get = keep.front();
		keep.pop();
		if (dp[get.first]) continue;
		if (get.second > k) break;
		dp[get.first] = 1;
		if (get.second == k) {
			count[check[get.first]]++;
			continue;
		}
		ans++;
		rep(i, edge[get.first].size()) {
			keep.push(mp(edge[get.first][i], get.second + 1));
			if (get.second == 0) {
				check[edge[get.first][i]] = max_check;
				max_check++;
			} else {
				check[edge[get.first][i]] = check[get.first];
			}
		}
	}
	int ret = 0;
	rep(i, max_check) ret = max(ret, count[i]);
	ans += ret;
	return ans;
}

