		List=vvi(v);
	}
	void add_edge(int s,int t){
		List[s].push_back(t);
		List[t].push_back(s);
	}
	int solve(int k){
		int ans=inf;
		if(k%2==0){
			for(int i=0;i<V;i++) ans=min(ans,bfs(i,-1,k/2));
		}
		else{
			for(int i=0;i<V;i++) for(auto j=List[i].begin();j!=List[i].end();j++){
				if(*j>i) ans=min(ans,bfs(i,*j,k/2));
			}
		}
		return ans;
	}
};

