void count() {
    int n, k;
    scanf("%d%d", &n, &k);
    vector<pair<int, int>> edgePairs;
    for(int i = 1; i < n; ++ i) {
        int u, v;
        scanf("%d%d", &u, &v);
        -- u, -- v;
        edges[u].push_back(v);
        edges[v].push_back(u);
        edgePairs.push_back(make_pair(u, v));
    }
    for(int i = 0; i < n; ++ i) {
        dfs(i, i, 0, i);
    }
    int ans = 0;
    if(k & 1) {
        k >>= 1;
        for(auto edge: edgePairs) {
            int cnt = 0;
            for(int i = 0; i < n; ++ i) {
                cnt += min(dist[edge.first][i], dist[edge.second][i]) <= k;
            }
            ans = max(ans, cnt);
        }
    } else {
        k >>= 1;
        for(int root = 0; root < n; ++ root) {
            int cnt = 0;
            for(int i = 0; i < n; ++ i) {
                cnt += dist[root][i] <= k;
            }
            ans = max(ans, cnt);
        }
    }
    printf("%d\n", n - ans);
}

