	{
		x=edge[i].F;
		y=edge[i].S;
		cnt=0;
		for(j=1;j<=n;j++)
		{
			if(min(dist(x,j),dist(y,j))>k/2)
			cnt++;
		}
		ans=min(ans,cnt);
	}
