int see(int v, int par, int d) {
  int res = 1;
  if(d == 0) return res;
  for(int w : A[v]) {
    if(w == par) continue;
    res += see(w, v, d - 1);
  }
  return res;
}

int main() {
  cin >> N >> K;
  for(int i = 0; i < N - 1; ++i) {
    int a, b; cin >> a >> b; --a; --b;
    A[a].push_back(b); A[b].push_back(a); E[i] = {a, b};
  }
  int res = N;
  if(K % 2 == 0) {
    for(int v = 0; v < N; ++v) {
      res = min(res, N - see(v, -1, K / 2));
    }
  } else {
    for(int i = 0; i < N - 1; ++i) {
      int a = E[i].first, b = E[i].second;
      res = min(res, N - see(a, b, (K - 1) / 2) - see(b, a, (K - 1) / 2));
    }
  }
  cout << res << endl;
  return 0;
}

