int set_dist(
	boost::multi_array<int, 2>& dist,
	boost::multi_array<bool, 2>& flags,
	std::vector<std::set<int>>const& graph,
	int from, int to)
{
	if (flags[from][to])
	{
		return dist[from][to];
	}
	if (flags[to][from])
	{
		dist[from][to] = dist[to][from];
		flags[from][to] = true;
		return dist[from][to];
	}
	int min = graph.size();
	for (int v : graph[from])
	{
		if (v == to)
		{
			min = 1;
			break;
		}
		dist[from][v] = 1;
		flags[from][v] = true;
		min = std::min(min, set_dist(dist, flags, graph, v, to) + 1);
	}
	dist[from][to] = min;
	flags[from][to] = true;
	return min;
}
