typedef math::modulo_number<1000000007> modulo;
modulo combinate(int N, int K)
{
	static boost::multi_array<boost::optional<modulo>, 2> memo(boost::extents[8001][4001]);
	if (memo[N][K])
		return *memo[N][K];
	if (K == 0)
	{
		memo[N][0] = 1;
		return 1;
	}
	if (N == K)
	{
		memo[N][N] = 1;
		return 1;
	}
	memo[N][K] = combinate(N - 1, K - 1) + combinate(N, K - 1);
	return *memo[N][K];
}
void Main(std::integral_constant<int, 5>)
{
	std::vector<std::pair<int, int>> data;
