	}
	modulo mod{};
	for (int i{};i < N;++i)
	{
		for (int j = i + 1;j < N;++j)
		{
			mod += combinate(
				data[i].first + data[i].second + data[j].first + data[j].second,
				std::min(
					data[i].first + data[j].first, 
					data[i].second + data[j].second));
		}
	}
	std::cout << mod.get() << std::endl;
}

