        g[u].pb(v);
        g[v].pb(u);
    }
    int bst = 0;
    vector <int> d(n, INF);
    if (k % 2 == 0)
    {
        for (int i = 0; i < n; ++i)
        {
            vector <int> cur;
            queue <int> q;
            q.emplace(i);
            d[i] = 0;
            while (!q.empty())
            {
                int v = q.front();
                q.pop();
                cur.pb(v);
                for (auto &to : g[v])
                {
                    if (d[to] > d[v] + 1 && d[v] + 1 <= k / 2)
                    {
                        d[to] = d[v] + 1;
                        q.emplace(to);
                    }
                }
            }
            bst = max(bst, (int)cur.size());
            for (auto &v : cur)
                d[v] = INF;
        }
    }
    else
    {
        for (int i = 0; i < n; ++i)
        {
            for (int j : g[i])
            {
                vector <int> cur;
                queue <int> q;
                q.emplace(i);
