void dfs(int me, vector<int> &visited, vector<vector<int> > &table, int left) {
    if (visited[me]==1) return;
    if (left<0) return;

    visited[me]=1;
    for (int i=0; i<table[me].size(); i++)
        dfs(table[me][i], visited, table, left-1);
}

int main() {
    std::ios::sync_with_stdio(false);
    int n, k; cin>>n>>k;
    vector<vector<int> > table(n);

    for (int i=0; i<n-1; i++) {
        int tmp1, tmp2; cin>>tmp1>>tmp2;
        table[tmp1-1].push_back(tmp2-1);
        table[tmp2-1].push_back(tmp1-1);
    }


    int ans=n;
    for (int i=0; i<n; i++) {
        vector<int> visited(n, 0);

        visited[i]=1;
        for (int j=0; j<table[i].size(); j++)
            dfs(table[i][j], visited, table, (k/2)-1);

        int rem=0;
        if (k==1) rem=1;
        else if (k%2==1) {
            for (int i=0; i<visited.size(); i++) if (visited[i]==1) {
                int tmp=0;
                for (int j=0; j<table[i].size(); j++)
                    if (visited[table[i][j]]==0) tmp++;
                rem=max(rem, tmp);
            }
        }

        int tmp=0;
        for (int i=0; i<n; i++) if (visited[i]==0) tmp++;
        if (k%2==1) ans=min(ans, tmp-rem);
        else ans=min(ans, tmp);
    }

    cout<<ans<<endl;
    return 0;
}

