    int a, b;
    for (int i = 1; i < n; ++ i) {
        cin >> a >> b;
        graph[a].push_back(b);
        graph[b].push_back(a);
    }

    dfs(1, 0);

    int ans = NMAX;

    for (int root = 1; root <= n; ++ root) {
        int current = NMAX;

        for (int l = 0; l <= k + 1; ++ l)
            upd(current, dp[root][l]);
        upd(ans, n - sz[root] + current);
    }

    cout << ans << '\n';

    return 0;
}

