int deg[MAX_N];
bool mark[MAX_N];
vector<int> G[MAX_N];

pii dfs(int u, int fa = -1, int dis = 0) {
  pii res = MP(dis, u);
  for (int v : G[u]) {
    if (v != fa && !mark[v]) res = max(res, dfs(v, u, dis + 1));
  }
  return res;
}

int main() {
