int ans=1<<30;
std::vector<int> G[2010];

void dfs(int n,int s,int &sum){
    node[n]=true;
    if(s==K/2){
        for(auto u:G[n]){
            if(!node[u])sum++;
        }
        return;
    }
    for(auto u:G[n]){
        if(!node[u])dfs(u,s+1,sum);
    }
}

int solve(int n){
    for(int i=1;i<=N;i++)node[i]=false;
    int M=0;
    node[n]=true;
    for(auto u:G[n]){
        int sum=0;
        dfs(u,1,sum);
        M=std::max(sum,M);
    }
    int sum=N;
    for(int i=1;i<=N;i++){
        if(node[i])sum--;
    }
    if(K%2)sum-=M;
    return sum;
}

