	memset(dist, -1, sizeof(dist));
	queue<int> q;

	dist[st] = 0;
	q.push(st);
	while (!q.empty()) {
		int u = q.front();
		q.pop();
		if (dist[u] >= lmt) {
			continue;
		}

		for (int v : graph[u]) {
			if (dist[v] == -1) {
				dist[v] = dist[u] + 1;
				q.push(v);
			}
		}
	}

	int cnt = 0;
	for (int i = 1; i <= n; ++i) {
		if (dist[i] == -1) {
			++cnt;
		}
	}
	return cnt;
}

int countMaxhalf(int u, int par, int maxhalfval) {
	if (dist[u] == maxhalfval) {
		return 1;
	}

	int sum = 0;
	for (int v : graph[u]) {
		if (v == par) {
			continue;
		}
		sum += countMaxhalf(v, u, maxhalfval);
	}
	return sum;
}

void proc() {
	scanf("%d %d", &n, &k);
	for (int i = 0; i < n - 1; ++i) {
		int a, b;
		scanf("%d %d", &a, &b);
		graph[a].push_back(b);
		graph[b].push_back(a);
	}

	auto d = diameter();
	if (get<2>(d) <= k) {
		printf("0");
		return;
	}

	fardist(get<0>(d), distr1);
	fardist(get<1>(d), distr2);

	int ans = n;
	for (int i = 1; i <= n; ++i) {
		if (distr1[i] + distr2[i] != get<2>(d)) {
			continue;
		}

		int maxhalf = (k + 1) / 2;
		int minhalf = k / 2;
		if (maxhalf == minhalf) {
			ans = min(ans, check(i, maxhalf));
		}
		else {
			int cnt = check(i, maxhalf);

			int pmin = n;
			for (int v : graph[i]) {
				int p = countMaxhalf(v, i, maxhalf);
				pmin = min(pmin, p);
			}

			ans = min(ans, cnt + pmin);
		}
	}

	printf("%d", ans);
}

int main() {
	//freopen("input.txt", "r", stdin);
	proc();
	return 0;
}

