int dfs(int cur, int tmp, vector<vector<int> > &G, int d, vector<bool> &used, int u, int v){

    used[cur] = true;
    int ret = 0;
    for(auto nxt : G[cur]){
        if(!used[nxt]){
            if(cur == u && nxt == v) continue;
            if(cur == v && nxt == u) continue;
            ret += dfs(nxt, tmp + 1, G, d, used, u, v);
