    FOR(e, g[v]){
      if((*e) == p) continue;
      cost -= gdp[(*e)][x];
      //check
      int ncost = cost + gdp[(*e)][y];
      ans = min(ans, ncost);

      cost += gdp[(*e)][x];
    }
  }
}

