/*
树的重心有一个特性：每个点离它的距离都<=d/2
于是枚举边/点直接 DFS 判断即可。
*/

#include <bits/stdc++.h>
using namespace std;
const int maxn=2000+10;
const int inf=0x3f3f3f3f;
int n,k,head[maxn],to[maxn<<1],nxt[maxn<<1],dep[maxn],tot,sum;

void add(int x,int y){
	to[++tot]=y;
	nxt[tot]=head[x];
	head[x]=tot;
}
void dfs(int x,int fa){
	if(dep[x]>k/2) sum++;
	for(int i=head[x],y;i;i=nxt[i]){
		y=to[i];
		if(y==fa) continue;
		dep[y]=dep[x]+1;
		dfs(y,x);
	}
}

int main()
{
	int u,v,val,ans=inf,flag1,flag2;
	scanf("%d%d",&n,&k);
	for(int i=1;i<n;i++){
		scanf("%d%d",&u,&v);
		add(u,v);add(v,u);
	}
	if(!(k&1)){
		for(int rt=1;rt<=n;rt++){
			dep[rt]=0;
			sum=0;
			dfs(rt,0);
			ans=min(ans,sum);
		}
		printf("%d\n",ans);
	}
	else {
		for(int rt=1;rt<=n;rt++){
			for(int i=head[rt];i;i=nxt[i]){
				sum=0;
				dep[rt]=0;
				dfs(rt,to[i]);
				dep[to[i]]=0;
				dfs(to[i],rt);
				ans=min(ans,sum);
			}
		}
		printf("%d\n",ans);
	}
	return 0;
}

#include <bits/stdc++.h>

using namespace std;

const int inf = 1e9;

int k;
vector <int> g[2010];
int sz[2010];
int sum[2010];
int f[2010][2010];

void dfs(int x, int pa = -1) {
  sz[x] = 1;
  for (int y : g[x]) {
    if (y != pa) {
      dfs(y, x);
      sz[x] += sz[y];
    }
  }
  for (int i = 0; i <= k; ++i) {
    sum[i] = 0;
    for (int y : g[x]) {
      if (y != pa) {
        sum[i] += f[y][i];
      }
    }
  }
  f[x][0] = sz[x] - 1;
  for (int i = 1; i <= k; ++i) {
    //int mn[3] = {inf, inf, inf};
    for (int y : g[x]) {
      if (y != pa) {
        f[x][i] = min(f[x][i], (sz[x] - 1) + f[y][i - 1] - sz[y]);

        //mn[2] = f[y][i - 1] - sz[y];
        //sort(mn, mn + 3);
      }
    }
   // if (mn[0] == inf) {
     // continue;
   // }
   // f[x][i] = (sz[x] - 1) + mn[0];
   // if (mn[1] == inf) {
     // continue;
    //}
    if (i + i <= k) {
      f[x][i] = min(f[x][i], sum[i - 1]);
      //f[x][i] = min(f[x][i], (sz[x] - 1) + mn[0] + mn[1]);
    } else {
      if (k - i - 1 >= 0) {
        for (int y : g[x]) {
          if (y != pa) {
            f[x][i] = min(f[x][i], sum[k - i - 1] + f[y][i - 1] - f[y][k - i - 1]);
          }
        }
      }
    }
  }
  for (int i = 0; i < k; ++i) {
    f[x][i + 1] = min(f[x][i + 1], f[x][i]);
  }
}

int main() {
  int n;
  scanf("%d %d", &n, &k);
  for (int i = 0; i < n; ++i) {
    g[i].clear();
  }
  for (int i = 0; i < n - 1; ++i) {
    int x, y;
    scanf("%d %d", &x, &y);
    --x;
    --y;
    g[x].push_back(y);
    g[y].push_back(x);
  }
  for (int i = 0; i < n; ++i) {
    for (int j = 0; j <= k; ++j) {
      f[i][j] = inf;
    }
  }
  dfs(0);
  int ans = inf;
  for (int i = 0; i < n; ++i) {
    ans = min(ans, (n - sz[i]) + f[i][k]);
  }
  printf("%d\n", ans);
  return 0;
}

