const int inf=1<<28;


VI bfs(int s) {
	VI dd(n,inf);
	queue< int > que;
	que.push(s); dd[s]=0;
	while(!que.empty()){
		int cx = que.front();
		que.pop();
		for(auto xr : r[cx]){
			if(dd[xr]==inf){
				dd[xr] = dd[cx] + 1;
				que.push(xr);
			}
		}
	}
	return dd;
}


