#include<bits/stdc++.h>
using namespace std;

int N,K;
vector<int> G[2222];

typedef pair<int,int> P;


P dfs(int id, int pr){
  P ret = P(-1,-1);
  if( G[id].empty() ) return P(0,id);
  bool f = false;
  for( int to : G[id] ){
    if( pr == to ) continue;
    f = true;
    ret = max( ret, dfs( to , id) );    
  }
  if( !f ) return P(0,id);
  ret.first += 1;
  return ret;
}

void bfs(int id,int *A){
  queue<int> q; q.push(id); A[id] = 0;
  while( !q.empty() ){
    int p = q.front(); q.pop();
    for( int to : G[p] ){
      if( A[to] == -1 ){
        A[to] = A[p] + 1;
        q.push( to );
      }
    }    
  }
}


int main(){
  cin >> N >> K;
  for(int i=0;i<N-1;i++){
    int a,b; cin >> a >> b; --a; --b;
    G[a].push_back( b );
    G[b].push_back( a );
  }

  int A[2222];
  int B[2222];
  memset( A, -1, sizeof( A ) );
  memset( B, -1, sizeof( B ) );
  P ret = dfs( 0, 0 );
  bfs( ret.second, A );
  ret = dfs( ret.second, ret.second );
  bfs( ret.second, B );

  if( ret.first <= K ) { cout << 0 << endl; return 0; }

  vector<int> V;
  for(int i=0;i<N;i++){
    if( A[i] == B[i] || abs( A[i]-B[i] ) == 1 ) V.push_back( i );
  }

  memset( A, -1, sizeof( A ) );
  memset( B, -1, sizeof( B ) );

  int res = 0;

  if( K & 1 ){//k
    bfs( V[0], A );
    if( V.size() ==1 ){
      res = N;
      int ret = 0;      
      for( int nx : G[V[0]] ) {
        memset( B, -1, sizeof( B ) );
        bfs( nx, B );
        for(int i=0;i<N;i++)
          if( min( A[i], B[i] ) > K/2 ) ret++;
        res = min( res, ret );      
      }
    } else {
      bfs( V[1], B );
      for(int i=0;i<N;i++) if( min( A[i], B[i] ) > K/2 ) res++;      
    }
  } else {//g
    bfs( V[0], A );
    if( V.size() == 2 ) bfs( V[1], B );
    for(int i=0;i<N;i++)
      if( A[i] > K/2 || B[i] > K/2 ) res++;    
  }

  cout << res << endl;

}

