typedef long long ll;
int n,k;
const int MAXN=2005;
struct Edge
{
	int v,next;
}e[MAXN*2];
int h[MAXN],cnt,size[MAXN];
void addEdge(int u,int v)
{
	e[++cnt].v=v;e[cnt].next=h[u];h[u]=cnt;
	e[++cnt].v=u;e[cnt].next=h[v];h[v]=cnt;
}
int dfs1(int u,int anc,int dep)
{
	int tmp=1;
	if(dep==k/2)
		return 1;
	else
		for(int i=h[u];i;i=e[i].next)
			if(e[i].v!=anc)tmp+=dfs1(e[i].v,u,dep+1);
	return tmp;
}
int dfs2(int u,int anc,int dep)
{
	int tmp=0;
	if(dep==k/2)
		return size[u]-1;
	else if(dep==0)
		for(int i=h[u];i;i=e[i].next)
			if(e[i].v!=anc)tmp=max(tmp,dfs2(e[i].v,u,dep+1));
	else
		for(int i=h[u];i;i=e[i].next)
			if(e[i].v!=anc)tmp+=dfs2(e[i].v,u,dep+1);
	return tmp;
}
int main()
{
	cin>>n>>k;
	for(int i=1;i<n;i++)
	{
		int x,y;
		cin>>x>>y;
		addEdge(x,y);
		size[x]++;
		size[y]++;
	}
	int ans=0;
	for(int i=1;i<=n;i++)
	{
		int tmp=dfs1(i,0,0);
		if(k%2==1)
			tmp+=dfs2(i,0,0);
		ans=max(ans,tmp);
	}
	cout<<n-ans<<endl;
	return 0;
}

