const int maxn = 2010;
vector<int> edge[maxn];
int n, k, res = maxn;
vector<int> dp[maxn];
int sz[maxn];
void dfs1(int now, int last = -1){
	sz[now] = 1;
	for(int u : edge[now])if(u != last)
		dfs1(u, now), sz[now] += sz[u];
}
void dfs2(int now, int last = -1){
	dp[now] = {0};
	int mx = 1;
	for(int u : edge[now])if(u != last){
		dfs2(u, now);
		mx = max(mx, (int)dp[u].size());
	}
	dp[now].resize(mx);
	if(sz[now] != 1) for(int i = 0;i < dp[now].size();++i){
		int sum = 0;
		auto get = [&](auto &v, int p){
			return p > v.size()-1 ? v.back() : v[p];
		};
		for(int u : edge[now])if(u != last){
			sum += get(dp[u], min(i, k-i));
		}
		dp[now][i] = maxn;
		for(int u : edge[now])if(u != last)
			dp[now][i] = min(dp[now][i], 
					sum - get(dp[u], min(i, k-i)) + get(dp[u], i));
	}
//	cerr << "now " << now << '\n';
//	for(int i : dp[now])
//		cerr << i << ' ';
//	cerr << '\n';
	for(int i = 1;i < dp[now].size();++i)
		dp[now][i] = min(dp[now][i], dp[now][i-1]);
	if(last == -1)
		res = min(res, dp[now].back());
		//cout << dp[now].back() << '\n';
	auto tmp = dp[now];
	dp[now].pb(0);
	for(int i = 0;i < tmp.size();++i)
		dp[now][i+1] = tmp[i];
	dp[now][0] = sz[now];
	for(int i = 1;i < dp[now].size();++i)
		assert(dp[now][i] <= dp[now][i-1]);
	while(dp[now].size()-1 > k)
		dp[now].pop_back();
}
