const int N=2050;
vector<int> E[N];

int DFS(int x,int p,int d,int mx)
{
	int ans=1;
	if(d!=mx){
		for(int y=0;y<E[x].size();y++){
			if(E[x][y]==p)continue;
			ans+=DFS(E[x][y],x,d+1,mx);
		}
	}
	return ans;
}

int main()
{
	int n,k;
	cin >>n>>k;
	for(int i=0;i<n-1;i++){
		int a,b;
