		a--;b--;
		E[a].push_back(b);
		E[b].push_back(a);
	}

	int ans=0;
	if(k%2==0){
		for(int v=1;v<=n;v++){
			ans=max(ans,DFS(v,-1,0,k/2));
		}
	}
	else {
		for(int v=1;v<=n;v++){
			for(int u=0;u<E[v].size();u++){
				ans=max(ans,DFS(E[v][u],u,0,k/2)+DFS(u,E[v][u],0,k/2));
			}
		}
	}

	ans=n-ans;
	cout << ans;
	return 0;
}

