        if(d[t] != -1) continue;
        d[t] = d[s] + 1;
        dfs(t, d);
    }
}

vector<int> dist(int c1, int c2){
    vector<int> d(N, -1);
    d[c1] = 0;
    for(int t : G[c1]){
        if(t == c2) continue;
        d[t] = 1;
        dfs(t, d);
    }
    return d;
}

int solve(int c[], int k){
    vector<int> d[2];
    for(int i=0; i<2; i++)
        d[i] = dist(c[i], c[1-i]);
    int cnt = 0;
    for(int i=0; i<2; i++)
        for(int j=0; j<N; j++)
            if(d[i][j] > k)
                cnt++;

    if(c[0] == c[1]) cnt /= 2;
    return cnt;
}

