#define N 2010
using namespace std;
int n,k;
int ans,dep[N],jd[N],dep1,dep2;
int s[N],cnt;
struct node
{
	int num,next;
}mp[N<<1];
void init(int x,int y)
{
	mp[++cnt].num=y;
	mp[cnt].next=s[x];
	s[x]=cnt;
}
int dfs(int x,int f,int d,int de[],int v)
{
	de[d]+=v;
	int dp=0;
	for(int i=s[x];i;i=mp[i].next)
	{
		int y=mp[i].num;
		if(y==f)continue;
		dp=max(dp,dfs(y,x,d+1,de,v));
	}
	return dp;
}
void solve(int x,int f)
{
	int tx=0,dp,kmax;
	dfs(x,f,0,dep,1);
	dep2=dep1=0;
	for(int i=s[x];i;i=mp[i].next)
	{
		int y=mp[i].num;
		if(y==f)continue;
		++tx;
		dp=dfs(x,f,0,dep,1);
		if(dp>dep1)
			kmax=y,dep2=dep1,dep1=dp;
		else if(dp>dep2)dep2=dp;
	}
	for(int i=1;dep[i];i++)dep[i]+=dep[i-1];
	if(tx==1)ans=max(ans,dep[k]);
	else
	{
		for(int i=s[x];i;i=mp[i].next)
		{
			int y=mp[i].num;
			if(y==f)continue;
			dfs(y,x,1,jd,1);
			int t=0;
			for(t=2;jd[t];t++)jd[t]+=jd[t-1];
			--t;
			for(int j=1;jd[j]&&j<=k;j++)
				if(dep[k-j]&&(y!=kmax||k-j<=dep2))
				{
					if(k-j>t)
						ans=max(ans,dep[k-j]-jd[t]+jd[j]);
					else ans=max(ans,dep[k-j]-jd[k-j]+jd[j]);
				}
			for(int j=1;jd[j];j++)jd[j]=0;
		}
	}
	for(int i=0;dep[i];i++)dep[i]=0;
	if(ans==0)
	{
		ans=n;
		return;
	}
	for(int i=s[x];i;i=mp[i].next)
	{
		int y=mp[i].num;
		if(y==f)continue;
		solve(y,x);
	}
}
int main()
{
	scanf("%d %d",&n,&k);
	for(int i=1;i<n;i++)
	{
		int x,y;
		scanf("%d%d",&x,&y);
		init(x,y);
		init(y,x);
	}
	solve(1,1);
	printf("%d",n-ans);
}

