using namespace std;
using pii = pair<int, int>;

const int MAX = 2000;
vector<int> G[MAX];

pii far(int v, int prev) {
	pii p(0, v);
	for (auto to : G[v]) if (to != prev) {
		auto q = far(to, v);
		q.first += 1;
		p = max(p, q);
	}
	return p;
}

int calc(int v, int prev, int K, int d = 0) {
	int res = d > K;
	for (auto to : G[v]) if (to != prev) {
		res += calc(to, v, K, d + 1);
	}
	return res;
}

