{
	int N, K;
	cin >> N >> K;
	for (int i = 0; i < N - 1; i++) {
		int A, B;
		cin >> A >> B; --A, --B;
		G[A].push_back(B);
		G[B].push_back(A);
	}
	int v1 = far(0, -1).second;
	int v2 = far(v1, -1).second;
	cout << min(calc(v1, -1, K), calc(v2, -1, K)) << endl;
	return 0;
}

