#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
typedef pair<int, pair<int, int>> Diameter;
const int MOD = 1000000007;

const int N = 2001;

vector<int> edges[N];

int dist[N][N];
int numPaths[N][N];
bool removed[N];

int main()
{
	int n, k;
	cin >> n >> k;
	for (int i = 1; i < n; ++i) {
		int a, b;
		scanf("%d%d", &a, &b);
		edges[a].push_back(b);
		edges[b].push_back(a);
	}
	for (int i = 1; i <= n; ++i) {
		queue<int> q;
		q.push(i);
		while (!q.empty()) {
			int cur = q.front();
			q.pop();
			for (int j = 0; j < edges[cur].size(); ++j) {
				int next = edges[cur][j];
				if (next != i && !dist[i][next]) {
					dist[i][next] = dist[i][cur] + 1;
					q.push(next);
				}
			}
		}
	}
	int cnt = 0;
	priority_queue<Diameter, vector<Diameter>, less<Diameter>> q;
	for (int i = 1; i <= n; ++i) {
		for (int j = 1; j <= n; ++j) {
			++numPaths[i][dist[i][j]];
			++numPaths[j][dist[i][j]];
			q.push({dist[i][j], {i, j}});
		}
	}
	while (!q.empty() && q.top().first > k) {
		int diameter = q.top().first;
		int u = q.top().second.first;
		int v = q.top().second.second;
		q.pop();
		//cout << diameter << ' ' << u << ' ' << v << endl;
		if (!removed[u] && !removed[v]) {
			if (numPaths[u][diameter] > numPaths[v][diameter]) {
				removed[u] = true;
				--numPaths[v][diameter];
			} else {
				removed[v] = true;
				--numPaths[u][diameter];
			}
			++cnt;
		}
	}
	cout << cnt << endl;
	return 0;
}

