using T = int; // データ型
int n; // 頂点
vector<vector<int>> tree;
vector<vector<T>> dist; // 根付き木中の i の
vector<vector<T>> ans; // ans[i][j] : 頂点iを葉とする部分木で直径がj以下のものの最大サイズ

void dfs1(int v, int p = -1) {
    for (auto &u : tree[v]) {
        if (u == p) continue;
        dfs1(u, v);
    }
    dist[v][0] = 1;
    for (int i = 1; i < n; i++) {
        T res = 1;
        for (auto &u : tree[v]) {
            if (u == p) continue;
            res += dist[u][i - 1];
        }
        dist[v][i] = res;
    }
}

void dfs2(int v, vector<T> d_par, int p = -1) {
    // v における答えの計算
    ans[v][0] = 1;
    for (int i = 1; i < n; i++) {
        for (int &u : tree[v]) {
            if (p == u) {
                ans[v][i] = max(ans[v][i], d_par[i - 1] + 1);
            }
            else {
                ans[v][i] = max(ans[v][i], dist[u][i - 1] + 1);
            }
        }
    }

    // 左右からの累積演算を用いて子に送る d_par の計算
    // lf[i] : [:i-1]の演算結果
    // ri[i] : [i+1:]の演算結果
    auto f = [](T a, T b) { return a + b; }; // 演算
    int e = 0; // 演算の単位元
    vector<vector<T>> lf(n, vector<T>(tree[v].size(), e)), ri(n, vector<T>(tree[v].size(), e)); // 累積配列
    for (int j = 1; j < n; j++) {
        for (int i = 1; i < tree[v].size(); i++) {
            if (tree[v][i - 1] == p) lf[j][i] = f(d_par[j - 1], lf[j][i - 1]);
            else lf[j][i] = f(dist[tree[v][i - 1]][j - 1], lf[j][i - 1]);
        }
        for (int i = tree[v].size() - 2; i >= 0; i--) {
            if (tree[v][i + 1] == p) ri[j][i] = f(d_par[j - 1], ri[j][i + 1]);
            else ri[j][i] = f(dist[tree[v][i + 1]][j - 1], ri[j][i + 1]);
        }
    }
    // lf[0][i], ri[0][i] = 1;
    for (int i = 0; i < tree[v].size(); i++) {
        if (tree[v][i] == p) continue;
        vector<T> next_d_par(n);
        next_d_par[0] = 1;
        if (1 < n) next_d_par[1] = tree[v].size();
        for (int j = 2; j < n; j++) {
            next_d_par[j] = f(lf[j][i], ri[j][i]) + 1;
        }
        /*
        if (tree[v][i] == 1) {
            for (int j = 0; j < n; j++) {
                cout << tree[v][i] + 1 << " " << j << " = " << next_d_par[j] << endl;
            }
        }
        */
        dfs2(tree[v][i], next_d_par, v);
    }
}

int main() {
    int k;
    cin >> n >> k;
    tree.resize(n);
    dist.resize(n, vector<T>(n));
    ans.resize(n, vector<T>(n));
    for (int i = 0; i < n - 1; i++) {
        int u, v; cin >> u >> v;
        u--; v--;
        tree[u].push_back(v);
        tree[v].push_back(u);
    }
    dfs1(0);
    dfs2(0, {});
    int res = 0;
    for (int i = 0; i < n; i++) {
        res = max(res, ans[i][k]);
    }
    cout << n - res << endl;
    return 0;
}

