void dfs(int now){
    child[now]++;
    dp[now][0] = 1;
    dp[now][1] = 0;
    for(auto nex:edges[now]){
        if (prt[now]==nex)
            continue;
        prt[nex] = now;
        dfs(nex);
        //dp[nex]が求まった。
        //dp[now]がmxまで定まっているとする。最大でもchild
        //dp[now][i]とdp[nex][j]をマージすることを考える。
        //nexの最大深さはchild[nex]程度

        repr(i,1+child[now],-1){
            ll tmp = dp[now][i];
            dp[now][i] = infi;
            repr(j,1+child[nex],-1){
                //i+j+1>kの場合は完全に切り離すだけ。
                //もしそうじゃないなら切り離すか、くっつつけるか選べる。
                if (i+j-1>k){
                    dp[now][i] = min(dp[now][i], tmp + child[nex]);
                }
                else{
                    //くっつつけてよい
                    if (j+1>i){
                        dp[now][j + 1] = min(dp[now][j + 1], tmp + dp[nex][j]);
                        dp[now][i] = min(dp[now][i], tmp + child[nex]);
                    }
                    else{
                        //くっつつけられて増えないならそのまま
                        dp[now][i] = min(dp[now][i], tmp + dp[nex][j]);
                    }
                }
            }
        }
        child[now] += child[nex];
    }
}
