int Delete(int v, int par, int sum, bool isUsed[2000])
{
	if (isUsed[v]) return 0;
	if (sum == 0)
	{
		isUsed[v] = true;
		return 1;
	}
	int res = 0;
	for (int i = 0; i < edge[v].size(); i++)
	{
		int to = edge[v][i];
		if (to == par) continue;
		res += Delete(to, v, sum - 1, isUsed);
	}
	return res;
}

int Solve(bool isUsed[2000])
{
	int res = 0;
	pair<int, int> ma(0, 0);
	for (int i = 0; i < N; i++)
	{
		if (isUsed[i]) continue;
		int cnt = 0;
		for (int j = 0; j < edge[i].size(); j++)
		{
			if (isUsed[edge[i][j]]) continue;
			cnt++;
		}
		if (cnt == 1)
		{
			ma = max(ma, make_pair(GetMax(i, -1, 0, isUsed).first, i));
		}
	}
	if (ma.first <= K) return 0;
	isUsed[ma.second] = true;
	return Solve(isUsed) + 1;
}

