void DFS(int start, vector<int>& dist, int depth, const vector<vector<int> >& G) {
	dist[start] = depth;
	for (auto to : G[start]) {
		if (dist[to] == -1) {
			DFS(to, dist, depth+1, G);
		}
	}
}

vector<int> DFS(int start, const vector<vector<int> >& G) {
	vector<int> dist(G.size(), -1);
