void solve() {
	int N, K; cin >> N >> K;
	vector<vector<int> > G(N);
	vector<pii> edge;
	for (int i = 0; i < N-1; ++i) {
		int a, b; cin >> a >> b;
		--a, --b;
		G[a].push_back(b);
		G[b].push_back(a);
		edge.emplace_back(a, b);
	}
	vector<int> leaves;
	REP(i, N) {
		if (G[i].size() == 1) {
			leaves.push_back(i);
		}
	}

	vec2<int> dist(N);
	for (int i = 0; i < N; ++i) {
		dist[i] = DFS(i, G);
	}

	int res = inf;
	if (K % 2 == 0) {
		for (int node = 0; node < N; ++node) {
			int r = 0;
			for (int i = 0; i < N; ++i) {
				if (dist[node][i] > K/2) {
					++r;
				}
			}
			res = min(res, r);
		}
	}
	else{
		--K;
		for(auto &a:edge){
			int r = 0;
			for (int i = 0; i < N; ++i) {
				if (min(dist[a.first][i], dist[a.second][i]) > K/2) {
					++r;
				}
			}
			res = min(res, r);
		}
	}
	cout << res << endl;
}

