int main()
{
    int N, K; cin >> N >> K;
    vector<vector<int>> G(N);
    for (int i = 0; i < N-1; i++) {
        int a, b; cin >> a >> b; a--, b--;
        G[a].push_back(b);
        G[b].push_back(a);
    }
    int s, t, maxdist, maxnode;
    vector<pair<int, int>> P(N);
    maxdist = maxnode = 0;
    dfs(G, 0, [&](int i, int d) { if (d > maxdist) maxnode = i, maxdist = d; });
    s = maxnode;
    maxdist = maxnode = 0;
    dfs(G, s, [&](int i, int d) { if (d > maxdist) maxnode = i, maxdist = d; P[i].first = d; });
    t = maxnode;
    dfs(G, t, [&](int i, int d) { P[i].second = d; });
    vector<vector<int>> S(maxdist+2, vector<int>(maxdist+2));
    for (auto &p : P) S[p.first+1][p.second+1]++;
    for (int i = 1; i < maxdist+2; i++)
        for (int j = 0; j < maxdist+2; j++)
            S[i][j] += S[i-1][j];
    for (int i = 0; i < maxdist+2; i++)
        for (int j = 1; j < maxdist+2; j++)
            S[i][j] += S[i][j-1];
    int ans = 1e9;
    for (int a = 0; a <= maxdist - K; a++) {
        // a + (K+1) + b == maxdist+1
        int b = maxdist - K - a;
        ans = min(ans, N - S[a+K+1][b+K+1]);
    }
    cout << ans << endl;
    return 0;
}

