		for(int j = 0; j < N; j++){
			if(D[j] <= K/2) ok ++; 
			if(D[j] == (K+1)/2) giri ++; 
		}
		if(K % 2 == 0) nokori = ok; 
		else nokori = ok + ((giri > 0) ? 1 : 0);
		ans = min(ans, N - nokori); 
	}
	cout << ans << endl; 
}

