typedef struct node{
  vector<node *> nexts;
} node;

int count(node *e, node *bef, int length){
  int sum = 1;
  if(length > 0){
    vector<node *>::iterator it;
    for(it = e->nexts.begin(); it != e->nexts.end(); ++it){
      if((*it) != bef){
        sum += count((*it), e, length-1);
      }
    }
  }
  return sum;
}

