    cin >> a >> b;
    A[i] = a-1;
    B[i] = b-1;
    e[a-1].nexts.push_back(&e[b-1]);
    e[b-1].nexts.push_back(&e[a-1]);
  }
  int ans;
  if(K%2 == 0){
    int ma = 0;
    for(i=0; i<N; ++i){
      ma = max(ma, count(&e[i], NULL, K/2));
    }
    ans = N - ma;
  }else{
    int ma = 0;
    for(i=0; i<N-1; ++i){
      ma = max( ma, count(&e[A[i]], &e[B[i]], (K-1)/2) + count(&e[B[i]], &e[A[i]], (K-1)/2) );
    }
    ans = N - ma;
  }
  cout << ans << endl;
  return 0;
}

