    d[u][0] = cnt[u] - 1;
    for (int i = 1; i <= k; ++i) {
        d[u][i] = d[u][i - 1];
        int sum = 0;
        int allh = min(i, k - i);
        int bestd = 0;
        for (int v: g[u]) {
            if (v != prev) {
                int need = (allh == 0 ? cnt[v] : d[v][i - 1]);
                sum += need;
                bestd = min(bestd, d[v][i - 1] - need);
            }
        }
        d[u][i] = min(d[u][i], sum + bestd);
        //cerr << u + 1 << ' ' << i << ' ' << d[u][i] << '\n';
    }
    ans = min(ans, d[u][k] + n - cnt[u]);
}

