double_sweep_ret solve(int n) {
	//nはノードの数
	//return 木の直径の{start,goal,cost}
	//木 T の直径を D とする．
	// D が偶数ならば，ある頂点 v が存在して v から他の頂点への距離が D / 2以下となる．
	// D が奇数ならば，ある辺 e が存在して e から他の頂点への距離が(D −1) / 2以下となる．
	//v と e は木の中心とよばれる．

	int st, go, co = 0;
	for (int i = 1;i <= n;i++) {
		d[i] = INF;
	}
	d[1] = 0;
	dfs(1, 0);
	int  mx = 0;
	for (int i = 1;i <= n;i++) {
		if (mx < d[i])mx = d[i], st = i;
	}
	for (int i = 1;i <= n;i++) {
		d[i] = INF;
	}
	d[st] = 0;
	dfs(st, 0);
	for (int i = 1;i <= n;i++) {
		if (co < d[i])co = d[i], go = i;
	}
	return double_sweep_ret{ st,go,co };
}

