	++k;
	for(int i=1;i<n;i++)
	{
		int x,y;
		scanf("%d%d",&x,&y);
		init(x,y);
		init(y,x);
	}
	for(int i=1;i<=k;i++)
		dep[i]=1;
	dfs(1,1);
	printf("%d",n-res);
}

