int tl, md, sz[2001];
bool vis[2001];

void fl(int u, int l = 0, int p = -1) {
	if (l > lng.first)lng = make_pair(l, u);
	f(i, 0, tr[u].size())if (tr[u][i] != p && !vis[tr[u][i]])fl(tr[u][i], l + 1, u);
}

int pl(int u, int p = -1) {
	sz[u] = 1;
	f(i, 0, tr[u].size())if (tr[u][i] != p && !vis[tr[u][i]])sz[u] += pl(tr[u][i], u);
	return sz[u];
}

int fi(int u, int d,bool dl, int p = -1, int l = 0) {
	if (d == l) {
		if (dl)vis[u] = 1;
		return sz[u];
	}
	int an = 0;
	f(i, 0, tr[u].size())if (tr[u][i] != p && !vis[tr[u][i]])an += fi(tr[u][i], d,dl, u, l + 1);
	return an;
}

int main() {
	int n ,k;
	scanf("%d%d", &n, &k);
	f(i, 1, n) {
		int a, b;
