		tr[a].push_back(b);
		tr[b].push_back(a);
	}
	int an = 0;
	lng.first = -1;
	fl(1);
	int t = lng.second;
	lng.first = -1;
	fl(t);
	tl = lng.first;
	while (tl > k) {
		int a, b;
		pl(t);
		a = fi(t, k + 1, false);
		pl(lng.second);
		b = fi(lng.second, k + 1, false);
		if (a > b)fi(lng.second, k + 1, true);
		else fi(t, k + 1, true);
		an += min(a, b);
		lng.first = -1;
		if (a > b)fl(lng.second);
		else fl(t);
		t = lng.second;
		lng.first = -1;
		fl(t);
		tl = lng.first;
	}
	printf("%d\n", an);
}

