int n, k;
vector<int> g[maxn];
int d[maxn], took[maxn];

void dfs(int u, int p) {
	d[u] = p == -1 ? 0 : d[p] + 1;
	for(int v : g[u]) {
		if(p - v and !took[v]) {
			dfs(v, u);
		}
	}
}

int diameter(int &u, int &v) {
	for(int i = 1; i <= n; i++) {
		if(!took[i]) {
			dfs(i, -1);
			break;
		}
	}
	u = -1;
	int mx = -1;
	for(int i = 1; i <= n; i++) {
		if(took[i]) continue;
		if(mx < d[i]) {
			mx = d[i];
			u = i;
		}
	}
	dfs(u, -1);
	mx = -1, v = -1;
	int cnt_v = 0;
	for(int i = 1; i <= n; i++) {
		if(took[i]) continue;
		if(mx < d[i]) {
			mx = d[i];
			v = i;
		}
	}
	for(int i = 1; i <= n; i++)
		if(!took[i] and d[i] == mx) cnt_v++;
	dfs(u, -1);
	mx = -1;
	for(int i = 1; i <= n; i++) {
		if(!took[i]) mx = max(mx, d[i]);
	}
	int cnt_u = 1;
	for(int i = 1; i <= n; i++) {
		if(!took[i] and mx == d[i]) cnt_u++;
	}
	if(cnt_u > cnt_v) {
		int tmp = u;
		u = v;
		v = tmp;
	}
	return mx;
}

