const int maxn = 2005;
int cnt[maxn][maxn];
int val[maxn][maxn];
int depth[maxn];
vector<int> adj[maxn];
int sum[maxn];
void dfs(int u, int dep, int mem, int par, int dx)
{
	cnt[mem][dep] += dx;
	depth[mem] = max(depth[mem], dep);
	for(auto v : adj[u])
	{
		if(v == par) continue;
		dfs(v, dep+1, mem, u, dx);
	}
}
int n, k;
int solve(int mag)
{
	memset(sum, 0, sizeof sum);
	memset(depth, 0, sizeof depth);
	for(auto u : adj[mag])
	{
		dfs(u, 1, u, mag, 1);
		for(int i = depth[u]; i>= 1; i--)
		{
			//printf("cnt[%d][%d] = %d\n", u, i, cnt[u][i]);
			val[u][i] = val[u][i+1] + cnt[u][i];
			sum[i] += val[u][i];
		}
	}
	int best = 1e9;
	for(auto u : adj[mag])
	{
		for(int i = 0; i<= min(k, depth[u]); i++)
		{
			int other = k-i;
			int one = val[u][i+1];
			int two = val[u][other+1];
			best = min(best, one-two+sum[other+1]);
		}
	}
	for(auto u : adj[mag])
	{
		dfs(u, 1, u, mag, -1);
	}
	return best;
}
