vector<int> G[2005];
int f(int cent, int par, int len, int depth = 0){  
    int cut = 0;
    if (depth > len)
        ++cut;
    for(int i : G[cent]){
        if (i == par) 
            continue;
        cut += f(i, cent, len, depth + 1);
    }

    return cut;
}

