namespace March
{
	inline void check_min(int a,int &b){if(a<b)b=a;}
	const int N=2050,M=N*2,INF=2147483647;
	int begin[N],next[M],to[M];
	int n,m,e,ans;
	void add(int x,int y,bool k=1)
	{
		to[++e]=y;
		next[e]=begin[x];
		begin[x]=e;
		if(k)add(y,x,0);
	}
	int dfs(int p,int h,int dep)
	{
		if(dep>m)return 0;
		int ret=1;
		for(int i=begin[p];i;i=next[i])
			if(to[i]!=h)ret+=dfs(to[i],p,dep+1);
		return ret;
	}
	void work(int rt)
	{
		for(int i=begin[rt];i;i=next[i])
			check_min(n-(1+dfs(to[i],rt,1)),ans);
	}
	void initialize()
	{
		scanf("%d%d",&n,&m);
		for(int i=1,u,v;i<n;i++)
			scanf("%d%d",&u,&v),add(u,v);
	}
	void solve()
	{
		initialize();
		ans=INF;
		for(int i=1;i<=n;i++)
			work(i);
		printf("%d\n",ans);
	}
}
