struct TreeDiameter {
  vector<int> d;
  const vector<vector<pair<int, int> > > &T;

  TreeDiameter(vector<vector<pair<int, int> > > &T) : d(T.size()), T(T) {}

  int bfs(int start) {
    fill(d.begin(), d.end(), -1);
    queue<int> que;
    que.push(start);
    d[start] = 0;
    int mav = start;
    while (!que.empty()) {
      int cur = que.front(); que.pop();
      if (d[cur] > d[mav]) mav = cur;
      int sz = T[cur].size();
      for (int i = 0; i < sz; i++) {
        int nex = T[cur][i].first;
        int nec = T[cur][i].second;
        if (d[nex] != -1) continue;
        d[nex] = d[cur] + nec;
        que.push(nex);
      }
    }
    return mav;
  }

  int td(int root=0) {
    return d[bfs(bfs(root))];
  }
};

