int n, k;
int diam[MAXN], dist[MAXN], lvl[MAXN], sz[MAXN];
int dp[MAXN][MAXN];
vi gr[MAXN];
int ans = 0;

void init(int u, int par) {
    int other = 0;
    sz[u] = 1;
    for (auto v : gr[u]) {
        if (v == par) continue;
        lvl[v] = lvl[u] + 1;
        init(v, u);
        diam[u] = max(diam[u], diam[v]);
        if (dist[v] + 1 > dist[u]) {
            other = dist[u];
            dist[u] = dist[v] + 1;
        } else if (dist[v] + 1 > other) {
            other = dist[v] + 1;
        }
        //dist[u] = max(dist[u], dist[v] + 1);
        sz[u] += sz[v];
    }
    diam[u] = max(diam[u], dist[u] + other);
}

void dfs(int u, int par) {
    for (auto v : gr[u]) {
        if (v == par) continue;
        dfs(v, u);
    }
    dp[u][0] = sz[u] - 1;
    for (int l = 1; l <= k; l++) {
        dp[u][l] = dp[u][l - 1];
        int sum = 0, best = INF;
        int neigh = (int)gr[u].size() - (par != -1);
        int which;
        if (neigh <= 2)
            which = k - l - 1;
        else
            which = min(k - l - 1, l - 1);
        for (auto v : gr[u]) {
            if (v == par) continue;
            int num = (which < 0 ? sz[v] : dp[v][which]);
            sum += num;
            best = min(best, -num + dp[v][l - 1]);
        }
        sum += best;
        dp[u][l] = min(dp[u][l], sum);
    }
}

