#include <bits/stdc++.h>
using namespace std;

vector<int> bfs(int N, vector<vector<int>>& edges, vector<int> starts)
{
    auto distances = vector<int>(N, numeric_limits<int>::max());
    auto queue = std::queue<int>();
    for (auto v : starts)
    {
        distances[v] = 0;
        queue.push(v);
    }

    while (!queue.empty())
    {
        auto v = queue.front(); queue.pop();
        for (auto w : edges[v]) if (distances[w] == numeric_limits<int>::max())
        {
            distances[w] = distances[v]+1;
            queue.push(w);
        }
    }
    return distances;
}

int solve(int N, int K, vector<vector<int>> edges)
{
    auto result = numeric_limits<int>::max();
    for (auto center = 0; center < N; center++)
    {
        auto distances = bfs(N, edges, {center});
        auto option = static_cast<int>(count_if(begin(distances), end(distances), [K](int d) { return d > K/2; }));
        result = min(result, option);
    }
    for (auto center1 = 0; center1 < N; center1++) for (auto center2 : edges[center1])
    {
        auto distances = bfs(N, edges, {center1, center2});
        auto option = static_cast<int>(count_if(begin(distances), end(distances), [K](int d) { return d > (K-1)/2; }));
        result = min(result, option);
    }
    return result;
}

