int n, K, Res, D[2010];
vector<int>E[2100];
void DFS(int a, int pp){
    for(int i=0;i<E[a].size();i++){
        if(E[a][i]!=pp){
            D[E[a][i]] = D[a]+1;
            DFS(E[a][i],a);
        }
    }
}
void Do(int a){
    D[a]=0;
    DFS(a,0);
    sort(D+1,D+n+1);
    int i;
    for(i=n;i>=1;i--){
        if(D[i]+D[i-1]<=K)break;
    }
    Res=min(Res,n-i);
}
