const int LIM = 2016;

vector<vector<int>> g(LIM);
vector<vector<int>> cnt(LIM, vector<int>(LIM, 0));
vector<vector<int>> sum(LIM, vector<int>(LIM, 0));
vector<vector<int>> up(LIM, vector<int>(LIM, 0));
int ans = 0;
int n, k;

void dfs(int u, int p = -1) {
  for (int to : g[u]) {
    if (to == p)
      continue;
    dfs(to, u);
    int d = 0;
    while (cnt[to][d]) {
      cnt[u][d + 1] += cnt[to][d];
      ++d;
    }
  }
  cnt[u][0] = 1;

  sum[u][0] = 1;
  for (int d = 1; d < LIM; ++d)
    sum[u][d] = sum[u][d - 1] + cnt[u][d];
}

void dfs2(int u, int  p = -1) {
  for (int to : g[u]) {
    if (to == p)
      continue;
    int d = 0;
    while (cnt[to][d]) {
      int dup = k - d - 1;
      if (dup >= 0)
        ans = max(ans, sum[to][d] + 1);
      --dup;
      if (dup >= 0)
        ans = max(ans, sum[to][d] + 1 + up[u][dup]);
      ++d;
    }
    for (d = 0; d < LIM; ++d)
      up[u][d] += sum[to][d];
  }
  for (int to : g[u]) {
    if (to == p)
      continue;
    up[to][0] = 1;
    for (int d = 0; d < LIM - 1; ++d)
      up[to][d + 1] = up[u][d] - sum[to][d] + 1;
    dfs2(to, u);
  }
}

