        memset(invalid, 0, sizeof(invalid));

        for ( ; ; ) {
            t2 longest = get_longest(linklist, invalid, root, n);
            ll newroot = get<0>(longest);
            bool done = set_invalid(linklist, invalid, newroot, n, k);
            if (done) break;
        }

