  if (pos == tar) {
    return true;
  }
  for (const int next : edges[pos]) {
    if (taboo_nodes.count(next) > 0)
      continue;
    if (visited[next])
      continue;
    if (get_path(next, tar, path)) {
      return true;
    }
  }
  path.pop_back();
  return false;
}
