#include <bits/stdc++.h>

using namespace std;

int N, K;
vector<int> g[2010];

void dfs(int cur, int par, vector<int>& d) {
	for (int nex : g[cur]) {
		if (nex == par) continue;
		d[nex] = d[cur] + 1;
		dfs(nex, cur, d);
	}
}

int solve_even(int center) {
	vector<int> d(N, N);
	d[center] = 0;
	dfs(center, -1, d);
	int res = 0;
	for (int i = 0; i < N; i++) {
		res += (d[i] > K / 2);
	}
	return res;
}

int solve_odd(int center1, int center2) {
	vector<int> d1(N, 0), d2(N, 0);
	dfs(center1, center2, d1);
	dfs(center2, center1, d2);
	int res = 0;
	for (int i = 0; i < N; i++) {
		res += (d1[i] > K / 2);
		res += (d2[i] > K / 2);
	}
	return res;	
}

int main() {
	cin.tie(0);
	ios::sync_with_stdio(false);
	cin >> N >> K;
	for (int i = 1; i < N; i++) {
		int a, b;
		cin >> a >> b;
		a--;
		b--;
		g[a].push_back(b);
		g[b].push_back(a);
	}

	int ans = N;
	if (K % 2 == 0) {
		for (int i = 0; i < N; i++) {
			ans = min(ans, solve_even(i));
		}		
	} else {
		for (int i = 0; i < N; i++) {
			for (int j : g[i]) {
				ans = min(ans, solve_odd(i, j));
			}
		}
	}
	cout << ans << endl;
	return 0;
}

