					w[u][j] = max(w[u][j], t);
				}
			}
		}
	}
}
void dfs2(int u, int pre = -1) {
	for (int i = p[u]; ~i; i = e[i].next) {
		int v = e[i].u;
		if (v != pre) {
			g[v][0] = 0, g[v][1] = 1;
			//for (int j = 2; j <= d; ++j) {
			//g[v][j] = w[u][j - 1] - w[v][j - 2];
			//}
			for (int j = 2; j <= d; ++j) {
				g[v][j] = 1;
				for (int k = p[u]; ~k; k = e[k].next) {
					int v2 = e[k].u;
					if (v2 != pre && v2 != v) {
						g[v][j] += w[v2][j - 2];
					}
				}
			}
			dfs2(v, u);
		}
	}
}

