		int now=Qmax.top();
		Qmax.pop();
		int sec=Qmax.top();
		for(;Q[now].top()+Q[sec].top()>k;++tans){
			Q[now].pop();
			Qmax.push(now);
			now=Qmax.top();
			Qmax.pop();
			sec=Qmax.top();
		}
