#include <bits/stdc++.h>
using namespace std;
#define pb push_back
#define mp make_pair
typedef long long ll;
typedef vector<int> vi;
typedef vector<vi> vvi;
#define sz(c) (int)(c).size()
#define ALL(c) (c).begin(), (c).end()

void dfs (int x, int p, const vvi &g, vi &h, vvi &dp, int k)
{
    h[x] = 0;
    int sons = 0;

    for (int dest : g[x])
    if (dest != p)
    {
        dfs(dest, x, g, h, dp, k);
        h[x] = max(h[x], h[dest] + 1);
        sons++;
    }

    dp[x].resize(min(h[x] + 1, k + 1));
    dp[x][0] = 1;

    if (sons >= 1)
    {
        for (int dest : g[x])
        if (dest != p)
        {
            for (int h1 = 0; h1 < k && h1 < sz(dp[dest]); h1++)
                dp[x][h1 + 1] = max(dp[x][h1 + 1], dp[dest][h1] + 1);
        }

        for (int i = 1; i < sz(dp[x]); i++)
            dp[x][i] = max(dp[x][i], dp[x][i - 1]);

        if (sons == 1)
            return;
    }

    for (int h2 = 0; h2 < k; h2++)
    {
        int cur = 1;

        for (int dest : g[x])
        if (dest != p)
            cur += dp[dest][min(sz(dp[dest]) - 1, h2)];

        for (int who : g[x])
        if (who != p)
        for (int h1 = h2; h1 < sz(dp[who]) && h1 < k && h1 + h2 + 2 <= k; h1++)
        {
            cur -= dp[who][min(sz(dp[who]) - 1, h2)];
            cur += dp[who][min(sz(dp[who]) - 1, h1)];
            dp[x][h1 + 1] = max(dp[x][h1 + 1], cur);
            cur -= dp[who][min(sz(dp[who]) - 1, h1)];
            cur += dp[who][min(sz(dp[who]) - 1, h2)];
        }
    }

    for (int i = 1; i < sz(dp[x]); i++)
        dp[x][i] = max(dp[x][i], dp[x][i - 1]);

//    cerr << x << " : ";
//    for (int i = 0; i < sz(dp[x]); i++)
//        cerr << dp[x][i] << ' ';
//    cerr << endl;
}

void solve (int n)
{
    vvi g(n);
    int k;
    cin >> k;
    for (int i = 1; i < n; i++)
    {
        int a, b;
        cin >> a >> b;
        --a, --b;
        g[a].pb(b);
        g[b].pb(a);
    }

    vvi dp(n);
    vi h(n);
    dfs(0, -1, g, h, dp, k);

    int ans = 0;
    for (const vi &cur : dp)
        ans = max(ans, *max_element(ALL(cur)));
    cout << n - ans << endl;
}

