					dist[X[a1][i]] = dist[a1] + 1;
					Q.push(X[a1][i]);
				}
			}
		}
		int sum = 0;
		for (int i = 1; i <= n; i++) {
			if (dist[i] <= p)sum++;
		}
		maxn = max(maxn, sum);
	}
	return n - maxn;
}
int search_2(int p) {
	int maxn = 0;
	for (int t = 1; t <= n; t++) {
		for (int i = 0; i < 3000; i++)dist[i] = 100000;
		dist[t] = 0; Q.push(t);
		while (!Q.empty()) {
			int a1 = Q.front(); Q.pop();
			for (int i = 0; i < X[a1].size(); i++) {
				if (dist[X[a1][i]]>dist[a1] + 1) {
					dist[X[a1][i]] = dist[a1] + 1;
					Q.push(X[a1][i]);
				}
			}
		}
		int sum = 0;
		for (int i = 1; i <= n; i++) {
			if (dist[i] <= p)sum++;
		}
		int D = 0;
		for (int i = 0; i < X[1].size(); i++) {
			for (int j = 0; j < 3000; j++)I[j] = false;
			Q.push(X[t][i]); I[X[t][i]] = true;
			while (!Q.empty()) {
				int a1 = Q.front(); Q.pop();
