      sum[i][l + 1] += dp[j][l];
  }
  sum[i][0] = s[i] - 1;
  for (int l = 0; 2 * l <= k; l++)
    dp[i][l] = sum[i][l];
  for (int l = k; 2 * l > k; l--)
    dp[i][l] = (s[i] == 1 ? 0 : n);
  for (int j : e[i]) {
    if (j == p)
      continue;
    for (int l = k; 2 * l > k; l--)
      dp[i][l] = min(dp[i][l], dp[j][l - 1] + sum[i][k - l] - (l == k ? s[j] : dp[j][k - l - 1]));
  }
  for (int l = 1; l <= k; l++)
    dp[i][l] = min(dp[i][l], dp[i][l - 1]);
}

