	int maxDepth = 0;
	while (!queue.empty()) {
		int now = queue.front(); queue.pop();
		maxDepth = std::max(maxDepth, g[now].first);
		REP(i, g[now].second.size()) {
			int check = g[now].second[i];
			if (g[check].first == -1) {
				g[check].first = g[now].first + 1;
