void proc(int u, int v)
{
	fr = rr = 0;
	for (int i = 1; i <= n; ++i) dist[i] = maxn;
	if (u) dist[qu[++rr] = u] = 0;
	if (v) dist[qu[++rr] = v] = 0;
	int cur = n;
    while (fr < rr) {
        u = qu[++fr];
        if (dist[u] <= k) --cur;
        else break;

        for (int v : G[u]) if (dist[u] + 1 < dist[v]) {
            dist[qu[++rr] = v] = dist[u] + 1;
        }
    }
    ans = min(ans, cur);
}

