            int x = q.front();
            q.pop();
            if (d[x] == K) {
                continue;
            }
            for (int i = 0; i < g[x].size(); i++) {
                int to = g[x][i];
                if (d[to] > d[x] + 1) {
                    d[to] = d[x] + 1;
                    q.push(to);
                }
            }
        }
        int y = -1;
