int dfs(int v) {
	vis[v]=1;
	len[v].pb(mp(mp(0,v),v));
	for (int i=0;i<sz(adj[v]);i++) {
		int x=adj[v][i];
		if (vis[x]) continue;
		dfs(x);
		for (pair<ii,int> p:len[x]) {
			if (!dead[p.second]) len[v].pb(mp(mp(p.first.first+1,x),p.second));
		}
	}
	while(1) {
		int v1=-1,i1;
		for (int i=0;i<sz(len[v]);i++) {
			if (dead[len[v][i].second]) continue;
			if (len[v][i].first.first>v1) {
				v1=len[v][i].first.first;
				i1=i;
			}
		}
		if (v1>k) {
			dead[len[v][i1].second]=1;
			ans++;
			continue;
		}
		int v2=-1,i2;
		for (int i=0;i<sz(len[v]);i++) {
			if (dead[len[v][i].second]) continue;
			if (len[v][i].first.second==len[v][i1].first.second) continue;
			if (len[v][i].first.first>v2) {
				v2=len[v][i].first.first;
