#include <bits/stdc++.h>
using namespace std;
const int N = 2003;
int n, k, res;
vector <int> e[N], f[N];
int ances[N][15], level[N];;

void dfs(const int u, const int p) {
    for (auto v: e[u])
        if (v != p) {
            level[v] = level[u] + 1;
            ances[v][0] = u;
            dfs(v, u);
        }
}

void make_lca() {
    for (int k = 1; k < 15; k++)
        for (int i = 1; i <= n; i++)
            ances[i][k] = ances[ances[i][k - 1]][k - 1];
}

int lca(int u, int v) {
    if (level[u] < level[v]) swap(u, v);
    for (int i = 14; i > - 1; i--)
        if (level[ances[u][i]] >= level[v])
            u = ances[u][i];
    if (u == v) return u;
    for (int i = 14; i > - 1; i--)
        if (ances[u][i] != ances[v][i]) {
            u = ances[u][i];
            v = ances[v][i];
        }
    return ances[u][0];
}

int dist(const int u, const int v) {
    return level[u] + level[v] - 2 * level[lca(u, v)];
}

int dfs2(const int root, const int u, const int p) {
    int ans = 0;
    if (dist(u, root) > k / 2) ans++;
    for (auto v: e[u])
        if (v != root && v != p)
            ans += dfs2(root, v, u);
    return ans;
}

void prepare(const int u) {
    f[u].resize(e[u].size());
    for (int i = 0; i < e[u].size(); i++) {
        int v = e[u][i];
        f[u][i] = dfs2(u, v, -1);
    }
}

void progress() {
    for (int i = 1; i <= n; i++)
        prepare(i);
    if (k % 2 == 0) {
        for (int u = 1; u <= n; u++) {
            int cnt = 0;
            for (int i = 0; i < e[u].size(); i++)
                cnt += f[u][i];
            res = min(res, cnt);
        }
    } else {
        for (int u = 1; u <= n; u++) {
            int cnt1 = 0;
            for (int i = 0; i < e[u].size(); i++)
                cnt1 += f[u][i];
            for (int i = 0; i < e[u].size(); i++) {
                int v = e[u][i];
                int cnt2 = 0;
                for (int j = 0; j < e[v].size(); j++)
                    if (e[v][j] != u)
                        cnt2 += f[v][j];
                res = min(res, cnt1 + cnt2 - f[u][i]);
            }
        }
    }
}

int main() {
    ios_base :: sync_with_stdio(false); cin.tie(NULL); cout.tie(NULL);
    cin >> n >> k;
    res = n;
    for (int i = 0; i < n - 1; i++) {
        int u, v; cin >> u >> v;
        e[u].push_back(v);
        e[v].push_back(u);
    }
    dfs (1, -1);
    make_lca();
    progress();
    cout << res;
    return 0;
}

