int dfs(int x,int p,int deepth,int mx)
{
	int s=1;
	if(deepth!=mx)
		for(int y=0;y<g[x].size();y++)
		{
			if(g[x][y]==p)
				continue;
			s+=dfs(g[x][y],x,deepth+1,mx);
		}
	return s;
}
int main()
{
	cin>>n>>k;
	for(int i=0;i<n-1;i++)
	{
		int x,y;
