int count(int u, int prev, int r, vvi& next) {
    set<int> visited;
    visited.insert(prev);
#ifdef DEBUG
    fprintf(stderr, "count(u=%d, prev=%d,..., r=%d)", u,prev,r);
#endif

    queue<ii> q;
    q.push(ii(u,r));
    int cnt = 0;
    while (!q.empty()) {
        auto t = q.front(); q.pop();
        int u = t.first, rest = t.second;
        visited.insert(u);
        ++cnt;
        if (rest == 0) continue;
        for (int v: next[u]) {
            if (found(visited, v)) continue;
            q.push(ii(v,rest-1));
        }
    }
#ifdef DEBUG
    fprintf(stderr, " = %d\n", cnt);
#endif
    return cnt;
}

int solve(int N,int K,vi& a,vi& b) {
    vvi next(N);
    rep(i,N-1) {
        next[a[i]].pb(b[i]);
        next[b[i]].pb(a[i]);
    }

    int cmax = 0;
    if (K % 2) {
#ifdef DEBUG
        fprintf(stderr, "ODD; r=%d\n", K/2);
#endif
        rep(e,N-1) {
            int a0=a[e], b0=b[e];
#ifdef DEBUG
            fprintf(stderr, " e=%d-%d\n", a0, b0);
#endif
            int c = count(a0, b0, K/2, next) + count(b0, a0, K/2, next);
            cmax = max(cmax, c);
        }
    } else {
#ifdef DEBUG
        fprintf(stderr, "EVEN; r=%d\n", K/2);
#endif
        rep(u,N){
#ifdef DEBUG
            fprintf(stderr, " u=%d\n", u);
#endif
            int c = 1;
            for (int v: next[u]) {
#ifdef DEBUG
                fprintf(stderr, "  -> v=%d\n", v);
#endif
                c += count(v, u, K/2-1, next);
            }
            cmax = max(cmax, c);
        }
    }
    return N - cmax;
}

int main() {
    int N,K; cin >> N >> K;
    vi a(N-1),b(N-1);
    rep(i,N-1) {
        cin >> a[i] >> b[i];
        --a[i]; --b[i];
    }
    cout << solve(N,K,a,b) << endl;
    return 0;
}

