ll solve(){
    ll res = 0;
    ll N,K; cin >> N >> K;
    vector<vector<ll>> G(N);
    for(int i = 0; i < N-1;i++){
        ll A,B; cin >> A >> B; A--; B--;
        G[A].push_back(B); G[B].push_back(A);
    }
    queue<ll> q;
    vector<ll> dist(N,INF);
    dist[0] = 0; q.push(0);
    while(q.size()){
        ll n = q.front(); q.pop();
        for(ll next : G[n]){
            if(dist[next] > dist[n] + 1){
                dist[next] = dist[n] + 1;
                q.push(next);
            }
        }
    }

    ll l = max_element(dist.begin(), dist.end()) - dist.begin();
    vector<ll> distl(N,INF);
    distl[l] = 0; q.push(l);
    while(q.size()){
        ll n = q.front(); q.pop();
        for(ll next : G[n]){
            if(distl[next] > distl[n] + 1){
                distl[next] = distl[n] + 1;
                q.push(next);
            }
        }
    }
    ll r = max_element(distl.begin(), distl.end()) - distl.begin();
    vector<ll> distr(N,INF);
    distr[r] = 0; q.push(r);
    while(q.size()){
        ll n = q.front(); q.pop();
        for(ll next:G[n]){
            if(distr[next] > distr[n] + 1){
                distr[next] = distr[n] + 1;
                q.push(next);
            }
        }
    }

    vector<int> ok(N,false);
//    dfs(l,ok,G,l,r);

    ll lK,rK,lrK; lK = rK = lrK = distl[r];

    vector<int> f(N,false);
    vector<vector<ll>> L(lK+1),R(rK+1);
    for(int i = 0; i < N;i++){
        L[distl[i]].push_back(i);
        R[distr[i]].push_back(i);
    }

    while(lrK > K){
        ll cntl = 0;
        ll cntr = 0;
        for(auto v:L[lK]){
            if(f[v]) continue;
            cntl++;
        }
        for(auto v:R[rK]){
            if(f[v]) continue;
            cntr++;
        }
        if(cntl > cntr){
            for(auto v:R[lK]){
                if(f[v]) continue;
                f[v] = true; res++;
            }
            lK--;
        }else{
            for(auto v:L[rK]){
                if(f[v]) continue;
                f[v] = true; res++;
            }
            rK--;
        }
        lrK--;
    }
    return res;
}
int main(void) {
	cin.tie(0); ios::sync_with_stdio(false);
    cout << solve() << endl;
	return 0;
}

