vector<int> G[2002];

int calc(int v, int pre, int d){
	int res = 0;

	if (d < 0) res++;

	rep (i, G[v].size()){
		int u = G[v][i];
		if (u == pre) continue;
		res += calc(u, v, d - 1);
	} // end rep

	return res;
}

int main()
{
	ios_base::sync_with_stdio(0);
	cin.tie(0);
	int N, K; cin >> N >> K;
	rep (i, N) G[i].clear();

	rep (i, N-1){
		int a, b; cin >> a >> b; 
		--a, --b;
		G[a].push_back(b);
		G[b].push_back(a);
	} // end rep

	int res = N;
	if (K % 2 != 0){
		rep (i, N){
			rep (j, G[i].size()){
				int u = G[i][j];
				res = min (res, calc(i, u, K / 2) + calc(u, i, K / 2));
			} // end rep
		} // end rep
	}else{
		rep (i, N){
			res = min(res, calc(i, -1, K / 2));
		} // end rep
	} // end if

	cout << res << endl;

	return 0;
}

#include <bits/stdc++.h>

template<typename T> inline int chkmin(T &x, T y) { return x > y ? x = y, 1 : 0; }

const int MAXN = 2000;

int n, k, ans = 0x3f3f3f3f;

struct Graph {
    int ver[MAXN + 9 << 1], nxt[MAXN + 9 << 1];
    int head[MAXN + 9], edgecnt = 1;

    inline void AddEdge(int u, int v) {
        ver[++edgecnt] = v, nxt[edgecnt] = head[u], head[u] = edgecnt;
    }
} G;

int d[MAXN + 9], lim;

void Dfs(int u, int fa) {
    for (int i = G.head[u]; i; i = G.nxt[i]) {
        int v = G.ver[i];
        if (v == fa) continue;
        d[v] = d[u] + 1;
        Dfs(v, u);
    }
}

int Update() {
    int res = 0;
    for (int i = 1; i <= n; d[i] = 0, ++i)
        if (d[i] > lim)
            ++res;
    return res;
}

int main() {
    scanf("%d%d", &n, &k);
    for (int i = 1; i < n; ++i) {
        int u, v;
        scanf("%d%d", &u, &v);
        G.AddEdge(u, v), G.AddEdge(v, u);
    }

    if (!(k & 1)) {
        lim = k >> 1;
        for (int i = 1; i <= n; ++i) {
            Dfs(i, 0);
            chkmin(ans, Update());       
        }
    } else {
        lim = k - 1 >> 1;
        for (int i = 2; i <= G.edgecnt; i += 2) {
            int u = G.ver[i ^ 1], v = G.ver[i];
            int res = 0;
            Dfs(u, v); res += Update();
            Dfs(v, u); res += Update();
            chkmin(ans, res);
        }
    }

    printf("%d\n", ans);

    return 0;
}

