void init(int u,int fa){
	mxdep[u] = 0;son[u] = 0;sz[u] = 1;
	for(int e=head[u];~e;e=edge[e].nxt){
		int v=edge[e].to;
		if(v == fa) continue;
		init(v,u);
		mxdep[u] = max(mxdep[u],mxdep[v] + 1);
		sz[u] += sz[v];
		if(!son[u] || mxdep[v] > mxdep[son[u]])
			son[u] = v;
	}
}
void pre(int u,int fa){
	dfx[dfn[u] = ++*dfn] = u;
	f[u] = dp + dfn[u];
	if(son[u]) pre(son[u],u);
	for(int e=head[u];~e;e=edge[e].nxt){
		int v=edge[e].to;
		if(v==fa || v==son[u]) continue;
		pre(v,u);
