		rep(i,len+1,k-len) if(i<=m) f[u][i] += g[len];
		rep(i,1,m+1) f[u][i] = min(f[u][i],f[u][i-1]);
	}
	ans = min(ans,n - sz[u] + f[u][min(k,m)]);
