    for (int i = 0; i < n-1; i++) {
        G[a[i]].push_back(b[i]);
        G[b[i]].push_back(a[i]);
    }

    int res = inf;
    bool used[2010];
    if (k % 2 == 0) {
        for (int i = 0; i < n; i++) {
            memset(used, false, sizeof(used));
            used[i] = true;
            queue<P> que;
            que.push(P(i, 0));
            while (!que.empty()) {
                P p =que.front(); que.pop();
                if (p.second >= k/2) continue;
                for (int v : G[p.first]) {
                    if (!used[v]) {
                        used[v] = true;
                        que.push(P(v, p.second+1));
                    }
                }
            }
            int cnt = 0;
            for (int i = 0; i < n; i++) {
                if (used[i])
                    cnt++;
            }
            res = min(res, n-cnt);
        }
    } else {
        for (int i = 0; i < n-1; i++) {
            memset(used, false, sizeof(used));
            used[a[i]] = true;
            used[b[i]] = true;
            queue<P> que;
            que.push(P(a[i], 0));
            que.push(P(b[i], 0));
            while (!que.empty()) {
                P p =que.front(); que.pop();
                if (p.second >= k/2) continue;
                for (int v : G[p.first]) {
                    if (!used[v]) {
                        used[v] = true;
