#include <bits/stdc++.h>

using namespace std;

const int maxn = 4000;

int f[maxn][maxn];
int cnt[maxn];
int n, k;

bool used[maxn];

vector < int > g[maxn];

void dfs(int v) {
  used[v] = true;
  vector < int > child;
  child.clear();
  for (auto u : g[v]) {
    if (!used[u]) {
      dfs(u);
      cnt[v] += cnt[u];
      child.push_back(u);
    }
  }
  cnt[v]++;
  int sum[n + 1];
  for (int i = 0; i <= n; i++) {
    sum[i] = 0;
    for (auto u : child) {
      sum[i] += f[u][i];
    }
  }
  f[v][0] = cnt[v];
  for (int i = 1; i <= n; i++) {
    for (auto u : child) {
      int j = min(k - i, i - 1);
      if (j < 0)
          continue;
      f[v][i] = min(f[v][i], f[u][i - 1] + sum[j] - f[u][j]);
    }
  }  
}

