int dfs(int s, int p, int r) {
  U[s] = p, R[s] = r;
  int c = 1;
  for (int t : G[s]) {
    if (t == p) continue;
    c += dfs(t, s, r+1);
  }
  C[s] = c-1;
  return c;
}

int dfs2(int s, int p, int d) {
  int c = !B[s] && d > K;
  for (int t : G[s]) {
    if (t == p) continue;
    c += dfs2(t, s, d+1);
  }
  return c;
}

int f(int x) {
  return C[x] + (U[x]==x ? 0 : dfs2(U[x], x, 1));
}

