		if(dist1[v1] < dist1[i]) v1 = i;
	}

	memset(chk+1, 0, sizeof(int)*n);
	memset(dist1+1, 0, sizeof(int)*n);
	dfs(v1, 0, dist1);

	for(int i = 1; i <= n; i++){
		if(dist1[v2] < dist1[i]) v2 = i;
	}
	int pv = v2;
	while(par[pv] != v1){
		nxt[par[pv]] = pv;
		pv = par[pv];
	}
	nxt[v1] = pv;
	memset(chk+1, 0, sizeof(int)*n);
	dfs(v2, 0, dist2);
