const int MAXN = 2010;

void setmax (int &a, int b) {
	if (a < b) {
		a = b;
	}
}

int N, K;
int dp[MAXN][MAXN];	//dp[vertex][max_depth]
int par[MAXN];
vector<int> adj[MAXN];

void dfs (int x, int p) {
	auto it = find(adj[x].begin(), adj[x].end(), p);
	if (it != adj[x].end()) {
		adj[x].erase(it);
	}
	for (int t : adj[x]) {
		if (t != p) {
			dfs(t, x);
		}
	}
}

int getdp (int x, int mxd) {
	if (mxd == -1) {
		return 0;
	} else if (mxd < -1) {
		return -1e5;
	}
	int &ref = dp[x][mxd];
	if (ref >= 0) {
		return ref;
	}
	//biggest child depth is < mxd - 1.
	if (mxd == 0) {
		return ref = 1;
	}
	ref = getdp(x, mxd - 1);
	//biggest child depth = mxd - 1
	int mxallow = min(mxd - 1, K - 1 - mxd);
	int s = 0;
	for (int t : adj[x]) {
		s += getdp(t, mxallow);
	}
	for (int t : adj[x]) {
		setmax(ref, 1 + s + (getdp(t, mxd - 1) - getdp(t, mxallow)));
	}
	return ref;
}

int main() {
