		adj[a].push_back(b);
		adj[b].push_back(a);
	}

	//ok add this stuff
	dfs(1, 0);
	int ans = 0;
	memset(dp, -2, sizeof(dp));
	for (int i = 0; i <= K; i++) {
		setmax(ans, getdp(1, i));
		//printf("dp[root][%d] = %d\n", i, dp[1][i]);
	}
	printf("%d\n", N - ans);
}

