const int N=6000;

int n,m;
VI e[N];

int in[N],stk[N];
void get_in( int p, int f, int lv ) {
    stk[lv]=p;
    in[stk[(lv+1)/2]]++;
    if ( lv==m ) return;
    for ( int i:e[p] ) if ( i!=f ) get_in(i,p,lv+1);
}

int dfs_mx;
void dfs( int p, int f, int s, int lv ) {
    s+=in[p];
    dfs_mx=max(dfs_mx,s);
    if ( lv==m ) return;
    for ( int i:e[p]) if ( i!=f ) dfs(i,p,s,lv+1);
}

int solve( int rt ) {
    memset(in,0,sizeof(in));
    get_in(rt,0,0);
    dfs_mx=0;
    dfs(rt,0,0,0);
    return n-dfs_mx;
}

