#include <iostream>
#include <vector>
using namespace std;

int N, K;

vector<int> G[2001];
vector<int> dp[2001][2001];
vector<int> dp2[2001][2001];
int back[2001][2001];

int gcount(int pos, int b, int k) {
  if(k < 0) return 0;
  int& bpos = dp[pos][k][back[pos][b]];
  if(bpos == -1) {
    bpos = 1;
    if(k > 0) {
      for(int i = 0; i < G[pos].size(); i++) {
        if(G[pos][i] == b) continue;
        bpos += gcount(G[pos][i], pos, k - 1);
      }
    }
  }
  return bpos;
}
int solve2(int i, int b, int K) {
  if(K < 0) return 0;
  if(b != -1 && dp2[i][K][back[i][b]] >= 0) return dp2[i][K][back[i][b]];
  int ans = 1;
  for(int k = 0; k * 2 <= K; k++) {
    if(k * 2 > K) break;
    int sum = 1;
    for(int j = 0; j < G[i].size(); j++) {
      if(G[i][j] == b)continue;
      sum += gcount(G[i][j], i, k - 1);
    }
    for(int j = 0; j < G[i].size(); j++) {
      if(G[i][j] == b)continue;
      ans = max(ans, sum - gcount(G[i][j], i, k - 1) + solve2(G[i][j], i, K - k - 1));
    }
  }
  if(b != -1) {
    return dp2[i][K][back[i][b]] = ans;
  }else{
    return ans;
  }
}
int main() {
  cin >> N >> K;
  for(int i = 0; i < N - 1; i++) {
    int A,B;
    cin >> A >> B;
    A--;B--;
    back[A][B] = G[A].size();
    G[A].push_back(B);
    back[B][A] = G[B].size();
    G[B].push_back(A);
  }
  for(int i = 0; i < N; i++) {
    for(int j = 0; j <= K; j++) {
      dp[i][j] = vector<int>(G[i].size(), -1);
      dp2[i][j] = vector<int>(G[i].size(), -1);
    }
  }
  int ans = 0;
  for(int i = 0; i < N; i++) {
    ans = max(ans, solve2(i, -1, K));
  }
  cout << N - ans << endl;
}

