int main(void)
{
    int N, K;
    cin >> N >> K;
    vector<int> g[MAX_N];
    REP(i, N - 1) {
        int A, B;
        cin >> A >> B;
        A--;
        B--;
        g[A].pb(B);
        g[B].pb(A);
    }
    int ret = MAX_N;
    REP(k, N) {
        int d[MAX_N];
        fill(d, d + N, MAX_N);
        queue<int> q;
        q.push(k);
        d[k] = 0;
        while (!q.empty()) {
            int x = q.front();
            q.pop();
            if (d[x] == K) {
                continue;
            }
            for (int i = 0; i < g[x].size(); i++) {
                int to = g[x][i];
                if (d[to] > d[x] + 1) {
                    d[to] = d[x] + 1;
                    q.push(to);
                }
            }
        }
        int y = -1;
        int max_dist = -1;
        REP(i, N) {
            if (d[i] != MAX_N && max_dist < d[i]) {
                y = i;
                max_dist = d[i];
            }
        }
        assert(y != -1);
        int dy[MAX_N];
        fill(dy, dy + N, MAX_N);
        q.push(y);
        dy[y] = 0;
        while (!q.empty()) {
            int x = q.front();
            q.pop();
            for (int i = 0; i < g[x].size(); i++) {
                int to = g[x][i];
                if (d[to] == MAX_N) {
                    continue;
                }
                if (dy[to] > dy[x] + 1) {
                    dy[to] = dy[x] + 1;
                    q.push(to);
                }
            }
        }
        int dist = 0;
        REP(i, N) {
            if (d[i] != MAX_N) {
                dist = max(dist, dy[i]);
            }
        }
        if (dist <= K) {
            int n_remove = 0;
            REP(i, N) {
                if (d[i] == MAX_N) {
                    n_remove++;
                }
            }
            ret = min(ret, n_remove);
        }
    }
    printf("%d\n", ret);
    return 0;
}

