typedef long long int LL;

std::vector<std::vector<LL>>G;
std::vector<bool>vis;
std::vector<LL>depth;

void dfs(LL v, LL d)
{
	if (vis[v]) return;
	vis[v] = true;
	depth[v] = d;
	for (auto u : G[v]) dfs(u, d + 1);
}

int main()
{
	LL N, K;
	in >> N >> K;
	std::vector<LL>A(N - 1), B(N - 1);
	rep(i, N - 1) in >> A[i] >> B[i];

	G.resize(N + 1);
	rep(i, N - 1)
	{
		G[A[i]].push_back(B[i]);
		G[B[i]].push_back(A[i]);
	}

	LL ans = N;
	if (K % 2 == 0)
	{
		for (int i = 1; i <= N; ++i)
		{
			vis.clear(); vis.resize(N + 1, false);
			depth.clear(); depth.resize(N + 1, 0);
			dfs(i, 0);

			LL res = 0;
			for (int j = 1; j <= N; ++j) if (depth[j] <= K / 2) ++res;
			ans = std::min(ans, N - res);
		}
	}
	else
	{
		rep(i, N - 1)
		{
			vis.clear(); vis.resize(N + 1, false);
			depth.clear(); depth.resize(N + 1, 0);
			vis[B[i]] = true;
			dfs(A[i], 0);
			vis[B[i]] = false;
			dfs(B[i], 0);

			LL res = 0;
			for (int j = 1; j <= N; ++j) if (depth[j] <= K / 2) ++res;
			ans = std::min(ans, N - res);
		}
	}

	out << ans << std::endl;
}

