std::vector<int> edges[2000];

int dfs(int node,int parent,int depth){
  if(depth==0) return 1;
  int cnt=1;
  for(int child:edges[node]){
    if(child!=parent){
      cnt+=dfs(child,node,depth-1);
    }
  }
  return cnt;
}

int main(){
  int N,K;
  std::cin>>N>>K;
  for(int i=0;i<N-1;i++){
    int A,B;
    std::cin>>A>>B;
    A--,B--;
    edges[A].push_back(B);
    edges[B].push_back(A);
  }
  int best=0;
  for(int i=0;i<N;i++){
    for(int j:edges[i]){
      best=std::max(best,dfs(j,i,K/2)+dfs(i,j,(K-1)/2));
    }
  }
  std::cout<<N-best<<std::endl;
  return 0;
}

