int N, K;
int A[2016], B[2016];
bool used[2016];
vector<int> G[2016];

pair<int, int> solve(int i, int d) {
  if (d > K) return {0, 0};
  // res = self + child num
  int res = 1;
  used[i] = true;
  int mx = 0;
  for (auto j: G[i]) {
    if (!used[j]) {
      auto p = solve(j, d + 1); 
      int n = p.first, r = p.second;
      if (r == -1 || r + mx > K) {
          return {-1, -1};
      }
      mx = max(mx, r);
      res += n;
    }
  }
  used[i] = false;
  return {res, mx + 1};
}

