    G[B[i] - 1].push_back(A[i] - 1);
  }

  int ans = N;
  rep(i, N) {
    used[i] = true;
    for (auto j: G[i]) {
      auto p = solve(j, 1);
      if (p.second == -1) continue;
      ans = min(ans, N - p.first - 1);
    }
    used[i] = false;
  } 

  cout << ans << endl;

  return 0;
}

