void Dfs2(int u){
    q[++pos]=u,vis[u]=true;
    if(!hson[u]){
        while(pos) ls[q[pos-1]]=q[pos],top[q[pos--]]=q[1];
        return;
    }
    Dfs2(hson[u]);
    for(int i=head[u];i;i=edge[i].nxt){
        int v=edge[i].to;
        if(!vis[v] && hson[u]!=v) Dfs2(v);
