pair<vector<int>, int> fardist(int st, int dist[]) {
	memset(dist, -1, sizeof(int) * (n + 1));
	queue<int> q;

	int ansd = 0;
	vector<int> anslist{ st };

	dist[st] = 0;
	q.push(st);
	while (!q.empty()) {
		int u = q.front();
		q.pop();
		if (ansd < dist[u]) {
			ansd = dist[u];
			anslist = { u };
		}
		else if (ansd == dist[u]) {
			anslist.push_back(u);
		}

		for (int v : graph[u]) {
			if (dist[v] == -1) {
				dist[v] = dist[u] + 1;
				q.push(v);
			}
		}
	}

	return { anslist, ansd };
}

tuple<int, int, int> diameter() {
	auto d1 = fardist(1, dist);
	auto d2 = fardist(d1.first[0], dist);
	return make_tuple(d1.first[0], d2.first[0], d2.second);
}

int check(int st, int lmt) {
	memset(dist, -1, sizeof(dist));
	queue<int> q;

	dist[st] = 0;
	q.push(st);
	while (!q.empty()) {
		int u = q.front();
		q.pop();
		if (dist[u] >= lmt) {
			continue;
		}

		for (int v : graph[u]) {
			if (dist[v] == -1) {
				dist[v] = dist[u] + 1;
				q.push(v);
			}
		}
	}

	int cnt = 0;
	for (int i = 1; i <= n; ++i) {
		if (dist[i] == -1) {
			++cnt;
		}
	}
	return cnt;
}

int countMaxhalf(int u, int par, int maxhalfval) {
	if (dist[u] == -1) {
		return 0;
	}
	if (dist[u] == maxhalfval) {
		return 1;
	}

	int sum = 0;
	for (int v : graph[u]) {
		if (v == par) {
			continue;
		}
		sum += countMaxhalf(v, u, maxhalfval);
	}
	return sum;
}

void proc() {
	scanf("%d %d", &n, &k);
	for (int i = 0; i < n - 1; ++i) {
		int a, b;
		scanf("%d %d", &a, &b);
		graph[a].push_back(b);
		graph[b].push_back(a);
	}

	auto d = diameter();
	if (get<2>(d) <= k) {
		printf("0");
		return;
	}

	fardist(get<0>(d), distr1);
	fardist(get<1>(d), distr2);

	int ans = n;
	for (int i = 1; i <= n; ++i) {
		int maxhalf = (k + 1) / 2;
		int minhalf = k / 2;
		if (maxhalf == minhalf) {
			ans = min(ans, check(i, maxhalf));
		}
		else {
			int cnt = check(i, maxhalf);

			int pmax = 0, psum = 0;
			for (int v : graph[i]) {
				int p = countMaxhalf(v, i, maxhalf);
				psum += p;
				pmax = max(pmax, p);
			}

			int cnt2 = 0;
			for (int i = 1; i <= n; ++i) {
				cnt2 += (dist[i] < maxhalf) ? 1 : 0;
			}
			ans = min(ans, cnt2 + (psum - pmax));
		}
	}

	printf("%d", ans);
}

