using namespace std;

int n, k, dep[2005], sz[2005];
set<int> Tree[2005];
vector<int> L, R;

void dfs(int x, int fa){
	dep[x] = dep[fa] + 1;
	//printf("x = %d fa = %d dep[%d] = %d\n", x, fa, x, dep[x]);
	//getchar();

	set<int>::iterator it;	
	for (it = Tree[x].begin(); it != Tree[x].end(); ++it)
		if (*it != fa){
			//printf("%d %d\n", *it, fa);			
			dfs(*it, x);
		}
}

int diam(int x){
	dep[0] = -1;
	dfs(x, 0);
	int l, r; L.clear(); R.clear();
	l = x;
	REP(i, 1, n) if (sz[i] && dep[i] > dep[l]) l = i;
	REP(i, 1, n) if (sz[i] && dep[i] == dep[l]) L.push_back(i);
	dfs(l, 0);
	r = x;
	REP(i, 1, n) if (sz[i] && dep[i] > dep[r]) r = i;
	REP(i, 1, n) if (sz[i] && dep[i] == dep[r]) R.push_back(i);
	return dep[r];
}

int del(int x){
	int fa = *Tree[x].begin();
	sz[fa]--; sz[x]--;
	Tree[x].erase(fa);
	Tree[fa].erase(x);
	return fa;
}

int main(){
	scanf("%d%d", &n, &k);
	REP(i, 1, n - 1){
		int u, v;
		scanf("%d%d", &u, &v);
		Tree[u].insert(v);
		Tree[v].insert(u);
		++sz[u]; ++sz[v];
	}
	int d = diam(1), ans = 0;
	while (d > k){
		int t; ans += min(L.size(), R.size());
		if (L.size() < R.size())
			RVC(i, L) t = del(L[i]);
		else RVC(i, R) t = del(R[i]);		
		d = diam(t);
	}
	printf("%d\n", ans);
	return 0;
}

