  os << edge.from << " -> " << edge.to << " (" << edge.cost << ")";
  return os;
}

// グラフテンプレート(隣接リスト)
template <typename E = Edge<ll>>
struct GraphL {
  // 頂点数、辺数
  int n, m;
  // 隣接リスト
  vector<vector<E>> adj;
  GraphL(int n_)
      : n(n_), m(0), adj(n_) {}

  template <typename... Args>
  void add_edge(int from, int to, Args... args) {
    adj[from].emplace_back(from, to, args...);
    m++;
  }
  vector<E> &operator[](int i) { return adj[i]; }
};
template <typename E = Edge<ll>>
ostream &operator<<(ostream &os, GraphL<E> graph) {
  os << "V = " << graph.n << ", E = " << graph.m << "\n";
  for (const auto &ev : graph.adj) {
    for (const auto &e : ev) {
      os << e << "\n";
    }
  }
  return os;
}


int main() {
  cin.tie(0);
  ios::sync_with_stdio(false);
  cout << fixed << setprecision(20);
  ll n, k;
  cin >> n >> k;
  GraphL<> g(n);
  rep(i, n-1){
    ll a, b;
    cin >> a >> b;
    a--; b--;
    g.add_edge(a, b);
    g.add_edge(b, a);
  }
  vector<bool> visited(n, false);
  auto bfs = [&](int start, int md) -> ll{
    ll ret = 0;
    queue<pair<int, int>> q;
    q.emplace(start, 0);
    visited[start] = true;
    while(q.size()){
      ret++;
      ll node = q.front().first;
      ll d = q.front().second;
      q.pop();
      for(auto&& e: g[node]){
        if(!visited[e.to]){
          visited[e.to] = true;
          if(d < md) q.emplace(e.to, d+1);
        }
      }
    }
    return ret;
  };
  ll ans = 0;
  if(k&1){
    rep(i, n){
      for(auto&& e: g[i]){
        visited.assign(n, false);
        visited[e.from] = true;
        visited[e.to] = true;
        chmax(ans, bfs(e.from, k/2) + bfs(e.to, k/2));
      }
    }
  }else{
    rep(i, n){
      visited.assign(n, false);
      chmax(ans, bfs(i, k/2));
    }
  }
  print(n-ans);
}

