void dfs(int u,int fa)
{
    hasup[u]=hasdown[u]=0;
    if(dep[u]==up)hasup[u]=1;
    if(dep[u]==down)hasdown[u]=1;

    if(dep[u]<=up)totup[u]=1;
    if(dep[u]<=down)totdown[u]=1;

    if(dep[u]==up)
        return;

