	REP(i,N){
		RSQ[i].init(dist[i]);
		RMQ[i].init(dist[i]);
	}

	Segment_Tree_Range_Maximum_Query<P<P<ll, ll>, int>> Seg;
	V<P<P<ll, ll>, int>> a(N);
	REP(i, N) a[i] = { { RMQ[i].getvar(0,N), RSQ[i].getvar(0, N) },i };
	Seg.init(a, { {0,0},0 });

