int N, K;
vector<int> G[2000];

int main() {
	scanf("%d%d", &N, &K);
	for (int i = 0, A,B; i < N-1; ++i) {
		scanf("%d%d", &A, &B);
		--A, --B;
		G[A].push_back(B);
		G[B].push_back(A);
	}

	int res = 1<<30;

	if (K%2) {
		vector<vector<bool>> chosen(N, vector<bool>(N, 0));
		for (int i = 0; i < N; ++i) {
			for (auto& j : G[i]) if (!chosen[i][j]) {
				chosen[i][j] = chosen[j][i] = 1;
				vector<int> checked(N, 0);
				checked[i] = checked[j] = 1;
				queue<pair<int, int>> q;
				q.emplace(i, 0), q.emplace(j, 0);
				while (q.size()) {
					auto p = q.front(); q.pop();
					if (p.second < (K-1)/2) for (auto& d : G[p.first]) if (!checked[d]) {
						checked[d] = 1;
						q.emplace(d, p.second+1);
					}
				}
				res = min(res, N-accumulate(checked.begin(), checked.end(), 0));
			}
		}
	} else {
		for (int i = 0; i < N; ++i) {
			vector<int> checked(N, 0);
			checked[i] = 1;
			queue<pair<int, int>> q;
			q.emplace(i, 0);
			while (q.size()) {
				auto p = q.front(); q.pop();
				if (p.second < K/2) for (auto& d : G[p.first]) if (!checked[d]) {
					checked[d] = 1;
					q.emplace(d, p.second+1);
				}
			}
			res = min(res, N-accumulate(checked.begin(), checked.end(), 0));
		}
	}

	printf("%d\n", res);

	return 0;
}

