int count(int a, int p, int d) {
	if (d == 0) return 0;
	int res = 1;
	REP(i, es[a].size()) {
		if (es[a][i] == p) continue;
		res += count(es[a][i], a, d - 1);
	}
	return res;
}

int main(int argc, char **argv) {
