		es[a].push_back(b);
		es[b].push_back(a);
		e[i] = MP(a, b);
	}
	int res = N;
	int h = K / 2;
	REP(i, N - 1) {
		int a = e[i].first, b = e[i].second;
		int cnt = count(a, b, h) + count(b, a, h);
		res = min(res, N - cnt);
	}
	REP(i, N) {
		int cnt = 0;
		REP(j, es[i].size()) {
			cnt += count(es[i][j], i, h);
		}
		++cnt;
		res = min(res, N - cnt);
	}
	cout << res << endl;
	return 0;
}

