int solve(int root) {
    vi d(n), fp(n);
	for (auto x: g[root]) {
		d[x] = 1; fp[x] = x;
		dfs(x, d, fp, root);
	}

	vi mi(n, -inf);
	for (int i = 0; i < n; i++)
		if (i != root)
			mi[fp[i]] = max(mi[fp[i]], d[i]);
	int t = inf;
	for (int i = 0; i < n; i++)
		if (mi[i] != -inf)
			t = min(t, mi[i]);		
	int ans = 0;
