		assert(0);
		vi tmp(n);
		if (m / 2 <= t) {
			for (int i = 0; i < n; i++) {
				if (i == root) continue; 
				if (d[i] > m / 2) ans++;
				if (d[i] == m / 2 + 1) tmp[fp[i]]++;
			}
			ans -= *max_element(all(tmp));
		} else {
		 	for (int i = 0; i < n; i++)
		 		if (d[i] > t + 1) ans++;
		}
	} else {
		if (m / 2 <= t) {
			for (int i = 0; i < n; i++)
				if (d[i] > m / 2) ans++;
		} else {
			for (int i = 0; i < n; i++)
				if (d[i] > t + 1) ans++;
		}
		re ans;	
	}
	re ans;
}

