const int N = 2003;

int n, k;
vector<int> g[N];
int dp[N], h[N], tin[N], tout[N], timer = 0;;

void dfs(int v, int par = -1) {
	if (par == -1) h[v] = 0;
	else h[v] = h[par] + 1;
	tin[v] = ++timer;
	dp[v] = 1;
	for (int to : g[v]) {
		if (to == par) continue;
		dfs(to, v);
		dp[v] += dp[to];
	}
	tout[v] = ++timer;
}
bool anc(int u, int v) { return tin[u] <= tin[v] && tout[u] >= tout[v];}

signed main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);
	cin >> n >> k;
	for (int i = 0; i < n - 1; ++i) {
		int u, v;
		cin >> u >> v;
		g[u].emplace_back(v);
		g[v].emplace_back(u);
	}
	int ans = n;
	for (int c = 1; c <= n; ++c) {
		for (int i = 1; i <= n; ++i) dp[i] = n + n + n;
		dfs(c);
		if (k % 2 == 0) {
			int cur = 0;
			cout << "c=" << c << endl;
			for (int v = 1; v <= n; ++v) {
				if (h[v] == k / 2) {
					cur += dp[v] - 1;
				}
			}
			uin(ans, cur);
		} else {
			int sz = (int)g[c].size();
			vector<int> val1(sz), val2(sz);
			int sum = 0;
			for (int i = 0; i < g[c].size(); ++i) {
				int to = g[c][i];
				for (int v = 1; v <= n; ++v) {
					if (anc(to, v)) {
						if (h[v] == k / 2) val1[i] += dp[v] - 1;
						else if (h[v] == k / 2 + 1) val2[i] += dp[v] - 1;
					}
				}
				sum += val1[i];
			}
			uin(ans, sum);
			for (int i = 0; i < sz; ++i) {
				uin(ans, sum - val1[i] + val2[i]);
			}
		}
	}
	cout << ans << endl;
    return 0;
}
