using namespace std;

const int MAXN = 2005;

struct node {
	int to, next;
} edge[MAXN*2];
int head[MAXN], top = 0;
inline void push(int i, int j)
{ edge[++top] = (node) {j, head[i]}, head[i] = top; }

int n, K;
int dp[MAXN][MAXN], maxdep[MAXN];
int c[MAXN];

void dfs(int nd, int f)
{
	maxdep[nd] = 1;
	for (register int i = head[nd]; i; i = edge[i].next) {
		int to = edge[i].to;
		if (to == f) continue;
		dfs(to, nd);
	}
	dp[nd][0] = 0, dp[nd][1] = 1;
	int cur = 1;
	for (register int i = head[nd]; i; i = edge[i].next) {
		int to = edge[i].to;
		if (to == f) continue;
		memset(c, 0, sizeof c);
		for (register int j = 1; j <= maxdep[nd]; j++)
			for (register int k = 0; k <= maxdep[to]; k++)
				if (j+k-1 <= K)
					c[max(j, k+1)] = max(c[max(j, k+1)], dp[nd][j]+dp[to][k]);
		memcpy(dp[nd], c, sizeof c);
		maxdep[nd] = max(maxdep[nd], maxdep[to]+1);
	}
}

