int main() {
    int N, K;
    cin >> N >> K;

    vector<Edge> E;
    for (int i = 0; i < N - 1; i++) {
        int A, B;
        cin >> A >> B;
        A--; B--;

        tree[A].push_back(B);
        tree[B].push_back(A);

        E.emplace_back(A, B);
    }

    for (int u = 0; u < N; u++) {
        dfs(u, u, -1, 0);
    }

    int ans = MAXN;

    // 木の中心を全探索
    if (K % 2 == 0) {
        // ある頂点u in Vが存在して, 任意の頂点v in Vに対してdist[u][v] <= K / 2
        for (int u = 0; u < N; u++) {
            int score = 0;
            for (int v = 0; v < N; v++) {
                if (dist[u][v] > K / 2) score++;
            }
            ans = min(ans, score);
        }
    } else {
        // ある辺e in Eが存在して, 任意の頂点v in Vに対してdist[e.endpoint][v] <= (K - 1) / 2
        for (Edge& e : E) {
            int end1, end2;
            tie(end1, end2) = e;

            int score = 0;
            for (int v = 0; v < N; v++) {
                if (min(dist[end1][v], dist[end2][v]) > (K - 1) / 2) score++;
            }
            ans = min(ans, score);
        }
    }

    cout << ans << endl;

    return 0;
}

