using Graph = vector<vector<int>>;
using P = pair<int, int>;
P dfs(const auto& G, auto cur, auto pre, auto K) {
  P res(K<=0, 1);
  for(auto nex: G[cur]) if(nex != pre) {
    auto p = dfs(G, nex, cur, K-1);
    res = P(res.first + p.first, res.second + p.second);
  }
  return res;
}
