    G[A].push_back(B);
    G[B].push_back(A);
  }
  auto res = N+1;
  for(auto u=0; u<N; ++u) {
    for(auto v: G[u]) {
      auto p = dfs(G, v, u, K);
      auto s = N - (1 + p.second - p.first);
      res = min(res, s);
    }
  }
  cout << res << endl;
}

