void bfs(int pos, int cnt){

  typedef pair<int, int> II;
  memset(used, 0, sizeof(used));
  queue<II> que;
  que.push(II(pos, cnt));
  used[pos] = true;

  while(que.size()){

    II p = que.front();
    que.pop();

    int pos = p.first;
    int cnt = p.second;

    if(cnt == 0)
      continue;

    for(int i = 0; i < (int)Edge[pos].size(); i++){
      int next = Edge[pos][i];
      if(used[next])
	continue;
      used[next] = true;
      que.push(II(next, cnt-1));
    }

  }

  for(int i = 0; i < N; i++){
    if(used[i]){
      SS.insert(i);
    }
  }

}

void dfs(int pos, int cnt, int pre){

  if(cnt == 0){

    SS.clear();

    //cerr << "*** " << SS.size() << " " << List.size() << endl;
    for(int i = 0; i < (int)List.size(); i++){
      bfs(List[i], min(i, (int)List.size()-1-i));
      SS.insert(List[i]);
      //cerr << SS.size() << endl;
    }
    ans = min(ans, N-(int)SS.size());
    return;

  }
  else{
    for(int i = 0; i < (int)Edge[pos].size(); i++){
      if(Edge[pos][i] != pre){
	List.push_back(Edge[pos][i]);
	dfs(Edge[pos][i], cnt-1, pos);
	List.erase(List.end()-1);
      }
    }
  }

}


