struct Edge
{
	int to;
	int nxt;
}edge[MAXN << 1];

int n,m,id,ans;
int size[MAXN];
int depth[MAXN];
int first[MAXN];
int f[MAXN][MAXN];

void addE(int u,int v)
{
	edge[++id] = (Edge){v,first[u]};
	first[u] = id;
}

void dfs(int u,int fa)
{
	size[u] = 1;
	depth[u] = 0;
	f[u][0] = 0;
	for (int i = first[u];i;i = edge[i].nxt)
	{
		int v = edge[i].to;
		if (v == fa)
			continue;
		dfs(v,u);
		size[u] += size[v];
		depth[u] = max(depth[u],depth[v] + 1);
		for (int j = min(m,depth[u]);j >= 0;j--)
		{
			int MIN = min(f[u][j] + size[v],(j ? f[v][j - 1] : size[v]) + size[u] - size[v] - 1);
			for (int k = 0;k <= min(m - 1,min(j - 1,depth[v]));k++)
				MIN = min(MIN,f[u][min(j,m - k - 1)] + f[v][k]);
			f[u][j] = MIN;
		}
	}
	for (int i = 1;i <= depth[u];i++)
		f[u][i] = min(f[u][i],f[u][i - 1]);
//	for (int i = 0;i <= depth[u];i++)
//		cout << "f[" << u << "][" << i << "]=" << f[u][i] << endl;
	ans = min(ans,f[u][min(depth[u],m)] + n - size[u]);
}

