ll solve(const V<ll> edges[], ll n, ll k, ll root)
{
    ll border = k / 2LL;
    ll extra = border;
    if (k  & 1LL) extra++;

    ll dlist[2005];
    rep (i, 2005) dlist[i] = -1;

    dlist[root] = 0;
    ll total = 1;
    ll extra_max = 0;

    for (auto sv : edges[root]) {
        queue<ll> q;
        ll extra_cnt = 0;
        dlist[sv] = 1;
        q.push(sv);
        total++;
        while (q.size()) {
            ll v = q.front(); q.pop();
            ll nd = dlist[v] + 1LL;
            if (nd > extra) continue;
            for (auto nv : edges[v]) {
                if (dlist[nv] >= 0) continue;
                dlist[nv] = nd;
                if (dlist[nv] <= border) total++;
                else if (dlist[nv] == extra) extra_cnt++;
                q.push(nv);
            }
        }
        extra_max = max(extra_max, extra_cnt);
    }

    total += extra_max;
    debug_printf("root=%lld n=%lld total=%lld\n", root, n, total);
    return n - total;
}

void _main()
{
    ll n; llin(n);
    ll k; llin(k);
    V<t2> uvlist; llinl2(uvlist, n-1);

    if (k == 1) {
        cout << max(0LL, n - 2LL) << endl;
        return;
    }

    V<ll> edges[2005];
    for (auto uv : uvlist) {
        ll u = get<0>(uv);
        ll v = get<1>(uv);
        edges[u].pb(v);
        edges[v].pb(u);
    }

    ll ans = n;

    srep (root, 1, n+1) {
        ans = min(ans, solve(edges, n, k, root));
    }

    debug_printf("---- ans\n");
    cout << ans << endl;
}

