int dfs(int v, int p, int d, const vector<vi> &tree){
  if(d<0) return 0;

  int ans = 1;
  for(int u : tree[v]){
    if(u == p) continue;
    ans += dfs(u,v,d-1,tree);
  }
  return ans;
}

int solve(int v, int k, const vector<vi> &tree){
  int l = k/2, h = k-l;
  vi f,c;
  for(int u : tree[v]){
    f.pb(dfs(u,v,l-1,tree));
    c.pb(dfs(u,v,h-1,tree));
