struct TREE{
    int N;
    vector<vector<int> >path;
    queue<int>Q;
    vector<int>depth;
    vector<int>A;
    vector<int>B;
    void init(int n){
        N = n;
        path = vector<vector<int> >(N);
        depth = vector<int>(N, 0);
        A.clear();
        B.clear();
    }
    TREE(int n){
        init(n);
    }
    void addPath(int a, int b){
        A.push_back(a);
        B.push_back(b);
        path[a].push_back(b);
        path[b].push_back(a);
    }
    void resetDepth(){
        for(int i=0; i<N; i++)depth[i] = -1;
    }
    void addRoot(int id){
        depth[id] = 0;
        Q.push(id);
    }
    void calcDepth(){
        while(!Q.empty()){
            int id = Q.front();
            Q.pop();
            for(int i=0;i<path[id].size();i++){
                int nxt = path[id][i];
                if(depth[nxt] < 0){
                    depth[nxt] = depth[id] + 1;
                    Q.push(nxt);
                }
            }
        }
    }
};

int main(){

    int N, K;
    cin >> N >> K;
    TREE tree(N+1);
    for(int i=0;i<N-1;i++){
        int a, b;
        cin >> a >> b;
        tree.addPath(a, b);
    }

    int mx = 0;
    if(K%2 == 0){
        K/=2;
        for(int i=1; i<=N; i++){
            tree.resetDepth();
            tree.addRoot(i);
            tree.calcDepth();
            int cnt = 0;
            for(int i=1;i<=N;i++){
                if(0<=tree.depth[i] && tree.depth[i]<=K)cnt++;
            }
            mx = max(mx, cnt);
        }
    }
    else{
        K/=2;
        for(int i=0;i<tree.A.size();i++){
            tree.resetDepth();
            tree.addRoot(tree.A[i]);
            tree.addRoot(tree.B[i]);
            tree.calcDepth();
            int cnt = 0;
            for(int i=1;i<=N;i++){
                if(0<=tree.depth[i] && tree.depth[i]<=K)cnt++;
            }
            mx = max(mx, cnt);
        }
    }
    cout << N - mx << endl;

    return 0;
}

#include <bits/stdc++.h>

using namespace std;
const int MAXN = 2010;

void setmax (int &a, int b) {
	if (a < b) {
		a = b;
	}
}

int N, K;
int dp[MAXN][MAXN];	//dp[vertex][max_depth]
int par[MAXN];
vector<int> adj[MAXN];

void dfs (int x, int p) {
	auto it = find(adj[x].begin(), adj[x].end(), p);
	if (it != adj[x].end()) {
		adj[x].erase(it);
	}
	for (int t : adj[x]) {
		if (t != p) {
			dfs(t, x);
		}
	}
}

int getdp (int x, int mxd) {
	int &ref = dp[x][mxd];
	if (ref >= 0) {
		return ref;
	}
	//biggest child depth is < mxd - 1.
	if (mxd == 0) {
		return ref = 1;
	}
	ref = getdp(x, mxd - 1);
	//biggest child depth = mxd - 1
	if (mxd == K) {
		//then just do this 
		for (int t : adj[x]) {
			setmax(ref, 1 + getdp(t, mxd - 1));
		}
		return ref;
	}
	int mxallow = min(mxd - 1, K - 1 - mxd);
	int s = 0;
	for (int t : adj[x]) {
		s += getdp(t, mxallow);
	}
	for (int t : adj[x]) {
		setmax(ref, 1 + s + (getdp(t, mxd - 1) - getdp(t, mxallow)));
	}
	return ref;
}

int main() {
	scanf("%d %d", &N, &K);
	for (int i = 1; i < N; i++) {
		int a, b;
		scanf("%d %d", &a, &b);
		adj[a].push_back(b);
		adj[b].push_back(a);
	}

	//ok add this stuff
	dfs(1, 0);
	int ans = 0;
	memset(dp, -2, sizeof(dp));
	for (int i = 1; i <= N; i++) {
		for (int j = 0; j <= K; j++) {
			setmax(ans, getdp(i, j));
		}
	}
	printf("%d\n", N - ans);
}

