vector<int> way[2005];
int inc[2005];
int cur;
int res;

void dfs(int pos, int d, int from){
    if(d > K) return;
    res = max(res, cur);
    for(int i=0; i<way[pos].size(); i++){
        if(!inc[way[pos][i]]) cur++, inc[way[pos][i]] = 1;
    }
    for(int i=0; i<way[pos].size(); i++){
        if(way[pos][i] == from) continue;
        dfs(way[pos][i], d+1, pos);
    }
    for(int i=0; i<way[pos].size(); i++) if(way[pos][i] != from) cur--, inc[way[pos][i]]--;
    return;
}

int main(){
    scanf("%d%d", &N, &K);
    if(K == 1){ printf("%d", N-2);  return 0; }
    else if(K == 0){ printf("%d", N-1); return 0; }
    for(int i=0; i<N-1; i++){
        int u, v;
        scanf("%d%d", &u, &v);
        way[u].push_back(v);
        way[v].push_back(u);
    }
    for(int i=1; i<=N; i++){
        for(int i=1; i<=N; i++) inc[i] = 0;
        inc[i] = 1;
        cur = 1;
        dfs(i, 1, 0);
    }
    printf("%d", N-res);
    return 0;
}

