int slv(int at, int far)
{
	if (cac[at][far]) return cac[at][far];
	if (ch[at].size() == 0 || far == 0) return cac[at][far]=1;
	if (ch[at].size() == 1) return cac[at][far]=slv(ch[at][0], far-1)+1;
	if (ch[at].size() == 2) for (int a = 0;a < far;a++)
	{
		int b = min(far, k-a-1)-1;
		if (b >= 0)
		{
			int alt = slv(ch[at][0], a)+slv(ch[at][1], b);
			if (alt > cac[at][far]) cac[at][far] = alt;
		}
	} else for (int giv = 0;giv < far;giv++)
	{
		if (giv+giv > far) break;
		int tot = 0;
		for (int u: ch[at]) tot += slv(u, giv);
		int here = min(far, k-giv-1)-1;
		for (int u: ch[at])
		{
			int alt = tot;
			alt -= slv(u, giv);
			alt += slv(u, here);
			cac[at][far] = max(cac[at][far], alt);
		}
	}
	for (int u: ch[at]) cac[at][far] = max(cac[at][far], slv(u, far-1));
	return ++cac[at][far];
}

