int n, k, dep[N], ans = 0;
Pii A[N];
vector<int> G[N];

int BFS(int a, int b, int k) {
    int res = 0;
    memset(dep, 0, sizeof(dep));
    queue<int> Q; Q.push(a); if(a^b) Q.push(b);
    while(!Q.empty()) {
        int x = Q.front(); Q.pop();
        if(dep[x] <= k) res++;
        int sz = G[x].size();
        for(int i = 0;i < sz; ++i) {
            int u = G[x][i];
            if(!dep[u]) {
                dep[u] = dep[x] + 1;
                if(dep[u] <= k) {
                    Q.push(u);
                }
            }
        }
    }
    return res;
}

