        G[v].push_back(u);
        A[i] = make_pair(u, v);
    }
    for(int i = 1;i <= n; ++i) {
        ans = max(ans, BFS(i, i, k / 2));
        ans = max(ans, BFS(A[i].first, A[i].second, (k - 1) / 2));
    }
    cout << n - ans << endl;
    return 0;
}

