void BFSParent(int start) {
	parent[start] = -1;
	Q.push(start);
	while (!Q.empty()) {
		int u = Q.front();
		Q.pop();
		REP(i, sz(graph[u])) {
			if (parent[graph[u][i]] == 0) {
				parent[graph[u][i]] = u;
				Q.push(graph[u][i]);
			}
		}
	}
