para srednica() {

	int v;
	RI(i, n) {
		if (!used[i]) {
			v = i;
			break;
		}
	}
	odl[v] = 0;
	Q.push(v);
	int vert = 1, maxim = 0;
	while (!Q.empty()) {
		int u = Q.front();
		Q.pop();
		REP(i, sz(graph[u])) {
			if (odl[graph[u][i]] == -inf && !used[graph[u][i]]) {
				odl[graph[u][i]] = odl[u] + 1;
				Q.push(graph[u][i]);
				if (maxim < odl[u] + 1) {
					maxim = odl[u] + 1;
					vert = graph[u][i];
				}
			}
		}
	}
	//printf("%d %d\n",vert,maxim);
	maxim = 0;
	int z = vert;
	Q.push(vert);
	odl2[vert] = 0;
	while (!Q.empty()) {
		int u = Q.front();
		Q.pop();
		REP(i, sz(graph[u])) {
			//printf("Kr : %d %d %d %d\n",u, graph[u][i], odl2[u], odl2[graph[u][i]]);
			if (odl2[graph[u][i]] == -inf && !used[graph[u][i]]) {
				//printf("Kr : %d %d\n",u, graph[u][i]);
				odl2[graph[u][i]] = odl2[u] + 1;
				Q.push(graph[u][i]);
				if (maxim < odl2[u] + 1) {
					maxim = odl2[u] + 1;
					vert = graph[u][i];
				}
			}
		}
	}

	return para(pii(z, vert), odl2[vert]);
}

