struct Node{
	vector<Node*> nodes;
	bool valid = true;
	Node* furthest(int& furthestsNum, int& maxLen, Node* cand = nullptr, int len = 0, Node* from = nullptr){
		// cout<<this<<' '<<&nodes<<endl;
		int size = 0;
		for(Node* n : nodes) if(n -> valid){
			size++;
		}
		if(size <= 1 && from != nullptr){
			if(maxLen < len){
				furthestsNum = 1;
				maxLen = len;
				return this;
			}else if(maxLen == len){
				furthestsNum++;
			}
			return cand;
		}
		for(Node* n : nodes) if(n -> valid && n != from){
			Node* tmp = n -> furthest(furthestsNum, maxLen, cand, len + 1, this);
			if(tmp != nullptr){
				cand = tmp;
			}
			// cout<<"cand "<<cand<<endl;
		}
		return cand;
	}
	void del(){
		valid = false;
	}
};

int main(){
	int n, k;
	cin >> n >> k;
	vector<Node> nodes(n);
	for(int i=0;i<n-1;i++){
		int a, b;
		cin >> a >> b;
		a--;
		b--;
		// cout<<&nodes[a]<<' '<<&nodes[b]<<endl;
		nodes[a].nodes.push_back(&nodes[b]);
		nodes[b].nodes.push_back(&nodes[a]);
	}
	int ans = 0;
	Node* next = &nodes[0];
	while(1){
		int hoge = 0, fuga = 0;
		Node* f1 = next -> furthest(hoge, fuga);
		// cout<<-1<<' '<<f1<<endl;
		int furthestsNum1 = 0;
		hoge = 0;
		Node* f2 = f1 -> furthest(furthestsNum1, hoge);
		// cout<<0<<' '<<f2<<endl;
		int furthestsNum2 = 0, diameter = 0;
		f2 -> furthest(furthestsNum2, diameter);
		// cout<<1<<endl;
		if(diameter <= k){
			break;
		}
		// cout<<2<<' '<<diameter<<endl;
		if(furthestsNum1 > furthestsNum2){
			f1 -> del();
			next = f2;
		}else{
			f2 -> del();
			next = f1;
		}
		ans++;
		// cout<<3<<' '<<ans<<' '<<next<<endl;
	}
	cout << ans << endl;
	return 0;
}

