	for (auto v : E[x]) if (v != fa) dfs(v, x), siz[x] += siz[v], son[x]++;
	dp[x][0] = siz[x] - 1;

	if (son[x]) {
		for (int i = 1; i <= K / 2; i++) {
			int ans = 0;
			for (auto v : E[x]) if (v != fa) {
				ans += dp[v][i - 1];
			}
			dp[x][i] = min(dp[x][i], ans);
			dp[x][i] = min(dp[x][i], dp[x][i - 1]);
		}
		for (int i = K / 2 + 1; i <= K; i++) {
			int ans = 0;
			for (auto v : E[x]) if (v != fa) {
				ans = min(ans, dp[v][i - 1] - (i == K ? siz[v] : dp[v][K - i - 1]));
			}
			dp[x][i] = min(dp[x][i], dp[x][K - i] + ans);
			dp[x][i] = min(dp[x][i], dp[x][i - 1]);
		}
	}
	else for (int i = 1; i <= K; i++) dp[x][i] = min(dp[x][i], dp[x][i - 1]);

}


