struct Node{
    int no;
    int par;
    int dist;
    vector<Node*> child;
    void build(int i){
        no=i;
        par=i;
        dist=0;
    }
};
struct Tree{
    int n;
    vector<Node> node;
    Tree(int k){
        n=k;
        node.resize(n+1);
        for(int i=1;i<=n;++i){
            node[i].build(i);
        }
    }
    void input(int k){
        for(int i=0;i<k;++i){
            int a,b;cin>>a>>b;
            node[a].child.push_back(&node[b]);
            node[b].child.push_back(&node[a]);
        }
    }
    void BFS(int s){
        rep1(i,n){
            node[i].build(i);
        }
        queue<Node> que;
        que.push(node[s]);
        while(!que.empty()){
            Node buf=que.front();que.pop();
            int num=buf.child.size();
            for(int i=0;i<num;++i){
                if(buf.child[i]->no!=buf.par){
                    buf.child[i]->par=buf.no;
                    buf.child[i]->dist=buf.dist+1;
                    que.push(*buf.child[i]);
                }
            }
        }
    }
    int BFS2(int s,int& res,int k){
        queue<Node> que;
        que.push(node[s]);
        int cnt=1;
        while(!que.empty()){
            ++cnt;
            Node buf=que.front();que.pop();
            int num=buf.child.size();
            for(int i=0;i<num;++i){
                if(buf.child[i]->no!=buf.par){
                    buf.child[i]->par=buf.no;
                    if(buf.child[i]->dist>k){
                        ++res;
                    }
                    que.push(*buf.child[i]);
                }
            }
        }
        return cnt;
    }
    void DFS(Node& node){
        if(node.child.size()==1&&node.par!=node.no){
            return;
        }
        else{
            int num=node.child.size();
            for(int i=0;i<num;++i){
                if(node.child[i]->no!=node.par){
                    DFS(*node.child[i]);
                }
            }
        }
    }
    void solve(int k){
        int res=inf;
        rep1(i,n){
            BFS(i);
            int num=node[i].child.size();
            rep(j,num){
                int buf=0;
                int cnt=BFS2(node[i].child[j]->no,buf,k);
                res=min(res,buf+n-cnt);
            }
        }
        cout<<res<<endl;
    }
};
signed main(){
    int n,k;cin>>n>>k;
    Tree tree(n);
    tree.input(n-1);
    tree.solve(k);
    return 0;
}

