        ll X,Y; cin>>X>>Y;
        edge[X-1].pb(Y-1);
        edge[Y-1].pb(X-1);
    }
    vector<vector<bool>> flag(N,vector<bool>(N));
    vector<std::bitset<2000>> memo(N);
    rep(i,0,N){
        vi dist(N,inf);
        dist[i]=0;
        std::queue<ll> que;
        que.push(i);
        while(!que.empty()){
            ll X=que.front(); que.pop();
            if(dist[X]<=K) memo[i].set(X);
            if(dist[X]==K) flag[i][X]=1;
            rep(j,0,edge[X].size()){
                ll Y=edge[X][j];
                if(dist[Y]>dist[X]+1){
                    dist[Y]=dist[X]+1;
                    que.push(Y);
                }
            }
        }
    }
    ll ans=0;
    rep(i,0,N){
        rep(j,0,N){
            if(flag[i][j]){
                std::bitset<2000> bit=memo[i]&memo[j];
                ans=std::max(ans,(ll)bit.count());
