queue<int> Q;

void BFSParent(int start) {
	parent[start] = -1;
	Q.push(start);
	while (!Q.empty()) {
		int u = Q.front();
		Q.pop();
		REP(i, sz(graph[u])) {
			if (parent[graph[u][i]] == 0) {
				parent[graph[u][i]] = u;
				Q.push(graph[u][i]);
			}
		}
	}
}

para srednica() {

	int v;
	RI(i, n) {
		if (!used[i]) {
			v = i;
			break;
		}
	}
	odl[v] = 0;
	Q.push(v);
	int vert = 1, maxim = 0;
	while (!Q.empty()) {
		int u = Q.front();
		Q.pop();
		REP(i, sz(graph[u])) {
			if (odl[graph[u][i]] == -inf && !used[graph[u][i]]) {
				odl[graph[u][i]] = odl[u] + 1;
				Q.push(graph[u][i]);
				if (maxim < odl[u] + 1) {
					maxim = odl[u] + 1;
					vert = graph[u][i];
				}
			}
		}
	}
	//printf("%d %d\n",vert,maxim);
	maxim = 0;
	int z = vert;
	Q.push(vert);
	odl2[vert] = 0;
	while (!Q.empty()) {
		int u = Q.front();
		Q.pop();
		REP(i, sz(graph[u])) {
			//printf("Kr : %d %d %d %d\n",u, graph[u][i], odl2[u], odl2[graph[u][i]]);
			if (odl2[graph[u][i]] == -inf && !used[graph[u][i]]) {
				//printf("Kr : %d %d\n",u, graph[u][i]);
				odl2[graph[u][i]] = odl2[u] + 1;
				Q.push(graph[u][i]);
				if (maxim < odl2[u] + 1) {
					maxim = odl2[u] + 1;
					vert = graph[u][i];
				}
			}
		}
	}

	return para(pii(z, vert), odl2[vert]);
}

int main() {
	scanf("%d%d",&n,&k);
	if (n == 2) {
		printf("0\n");
		return 0;
	}
	REP(i, n - 1) {
		scanf("%d%d",&a,&b);
		graph[a].pb(b);
		graph[b].pb(a);
		odl[i + 1] = odl2[i + 1] = -inf;
	}
	odl[n] = odl2[n] = -inf;
	int v = 1;
	RI(i, n) {
		if (sz(graph[i]) != 1) {
			v = i;
			break;
		}
	}
	BFSParent(v);
	para x = srednica();
	//printf("%d %d %d\n",x.st.st, x.st.nd, x.second);
	while (x.nd > k) {
		if (x.st.nd == v) {
			//printf("Here %d\n", graph[x.st.nd][0]);
			REP(i, sz(graph[v]))
				if (!used[graph[v][i]])
					parent[v] = graph[v][i];
		}
		int size1 = 0, size2 = 0;
		REP(i, sz(graph[parent[x.st.st]])) {
			size1 += (!used[graph[parent[x.st.st]][i]]);
		}
		REP(i, sz(graph[parent[x.st.nd]])) {
			size2 += (!used[graph[parent[x.st.nd]][i]]);
		}
		//printf("Rozm %d %d\n",size1, size2);
		if (size1 > size2) {
			swap(x.st.st, x.st.nd);
			//printf("zamieniam");
		}
		used[x.st.st] = true;
		//printf("Usuwam %d\n",x.st.st);
		ans++;
		RI(i, n) {
			odl[i] = odl2[i] = -inf;
		}
		x = srednica();
		//printf("%d %d %d\n",x.st.st, x.first.second, x.second);
	}
	printf("%d\n",ans);
	return 0;
}

