int N,sumE,head[MAXN],dep[MAXN],K,fa[MAXN],ans,cnt[MAXN];
vector<pii > Ed;
void add(int u,int v) {
    E[++sumE].to = v;
    E[sumE].next = head[u];
    head[u] = sumE;
}
void dfs(int u) {
    cnt[dep[u]]++;
    for(int i = head[u] ; i ; i = E[i].next) {
        int v = E[i].to;
        if(v != fa[u]) {
            fa[v] = u;
            dep[v] = dep[u] + 1;
            dfs(v);
        }
    }
}
void Solve() {
    read(N);read(K);
    int a,b;
    for(int i = 1 ; i < N ; ++i) {
    	read(a);read(b);
    	add(a,b);add(b,a);
        Ed.pb(mp(a,b));
    }
    int ans = N;
    for(int i = 1 ; i <= N ; ++i) {
        int u = i;
        fa[u] = 0;dep[u] = 0;
        memset(cnt,0,sizeof(cnt));
        dfs(u);
        int res = 0;
        for(int j = K / 2 + 1 ; j <= N ; ++j) res += cnt[j];
        ans = min(ans,res);
    }
    if(K % 2 == 0) --K;
	for(auto t : Ed) {
        fa[t.fi] = t.se;fa[t.se] = t.fi;dep[t.fi] = dep[t.se] = 0;
        dfs(t.fi);dfs(t.se);
        int res = 0;
        for(int i = K / 2 + 1 ; i <= N ; ++i) res += cnt[i];
        ans = min(ans,res);
    }
    out(ans);enter;
}

