int N, K;

vector<vector<int>> tree;

int dfsGT(int v, int u, int d0, int d) {
    int ans = d > d0;
    for (int w : tree[v])
        if (w != u)
            ans += dfsGT(w, v, d0, d + 1);
    return ans;
}

int dfsEQ(int v, int u, int d0, int d) {
    if (d == d0)
        return 1;
    int ans = 0;
    for (int w : tree[v])
        if (w != u)
            ans += dfsEQ(w, v, d0, d + 1);
    return ans;
}

int chop(int v) {
    if (K % 2) {
        int ans = dfsGT(v, v, (K + 1) / 2, 0);
        vector<int> subtrees;
        for (int w : tree[v])
            subtrees.push_back(dfsEQ(w, v, (K + 1) / 2, 1));
        sort(subtrees.begin(), subtrees.end(), greater<int>());
        for (int i = 1; i < (int) subtrees.size(); i++)
            ans += subtrees[i];
        return ans;
    } else {
        return dfsGT(v, v, K / 2, 0);
    }
}

