int bfs(vvi &adj, vector<bool> &removed, int s, int k){

	int ret = 0;

	int dist = 0;

	queue<int> q;
	q.push(s);
	unordered_set<int> visited;

	while(!q.empty()){

		int n = (int)q.size();

		for(int i = 0; i < n; i++){

			int curr = q.front(); q.pop();

			if(visited.count(curr)) continue;

			// cout << curr + 1 << endl;

			for(int child : adj[curr]){
				if(!visited.count(child) && !removed[child]) q.push(child);
			}

			ret++;
			visited.insert(curr);
		}

		// cout << ret << ' ' << dist << endl;

		if(dist == k) break;

		dist++;
	}

	return ret;
}


void solve(){

	int n, k;
	cin >> n >> k;

	vvi adj(n);

	for(int i = 0; i < n - 1; i++){
		int u, v;
		cin >> u >> v;
		u--; v--;

		adj[u].push_back(v);
		adj[v].push_back(u);
	}

	int ans = 0;
	vector<bool> removed(n);

	bool goodTree = false;

	while(1){

		int minC = n, rn = 0;

		for(int i = 0; i < n; i++){
			if(!removed[i]){

				int covered = bfs(adj, removed, i, k);

				// cout << i + 1 << " " << covered << endl;

				if(covered < minC){
					rn = i;
					minC = covered;
				}

			}
		}

		goodTree = (minC == n - ans);
		if(goodTree) break;

		removed[rn] = true;
		ans++;
	}


	cout << ans << endl;
}


