vector<int> path[3000];
int N, K;

int solve(int r) {
    bool visit[3000];
    fill(visit, visit + 3000, false);
    visit[r] = true;

    int ret = 0;
    for (int sr : path[r]) {
        int d[3000];
        fill(d, d + 3000, 3000);
        d[sr] = 1;
        queue<int> que;
        que.push(sr);
        visit[sr] = true;

        int cnt = 2;
        while (!que.empty()) {
            int v = que.front();
            que.pop();

            if (d[v] >= K) continue;

            for (int sv : path[v]) {
                if (visit[sv]) continue;
                ++cnt;
                que.push(sv);
                visit[sv] = true;
                d[sv] = d[v] + 1;
            }
        }

        ret = max(ret, cnt);
    }
    return ret;
}

