int f[2010][2010];

void dfs(int x, int pa = -1) {
  sz[x] = 1;
  for (int y : g[x]) {
    if (y != pa) {
      dfs(y, x);
      sz[x] += sz[y];
    }
  }
  f[x][0] = sz[x] - 1;
  for (int i = 1; i <= k; ++i) {
    int mn[3] = {inf, inf, inf};
    for (int y : g[x]) {
      if (y != pa) {
        mn[2] = f[y][i - 1] - sz[y];
        sort(mn, mn + 3);
      }
    }
    if (mn[0] == inf) {
      continue;
    }
    f[x][i] = (sz[x] - 1) + mn[0];
    if (mn[1] == inf) {
      continue;
    }
    if (i + i <= k) {
      f[x][i] = min(f[x][i], (sz[x] - 1) + mn[0] + mn[1]);
    }
  }
  for (int i = 0; i < k; ++i) {
    f[x][i + 1] = min(f[x][i + 1], f[x][i]);
  }
}

