	{
		to[++e]=y;
		next[e]=begin[x];
		begin[x]=e;
		if(k)add(y,x,0);
	}
	int make_it_shorter()
	{
		static int dl[N],dis[N];
		static bool vis[N];
		memset(vis,0,sizeof(vis));
		int u=0,d=0,tmp;

		for(tmp=1;ded[tmp];tmp++);
		vis[dl[++u]=tmp]=1;
		dis[tmp]=0;

		for(int p,q;u>d;)
		{
			p=dl[++d];
			for(int i=begin[p];i;i=next[i])
				if(!vis[q=to[i]] && !ded[q])vis[dl[++u]=q]=1,dis[q]=dis[p]+1;
		}
		S1.clear();
		for(int i=u;dis[dl[i]]==dis[dl[u]];i--)
			S1.push_back(dl[i]);

		memset(vis,0,sizeof(vis));
		u=0,d=0;
		vis[dl[++u]=S1[0]]=1;
		dis[S1[0]]=0;
		for(int p,q;u>d;)
		{
			p=dl[++d];
			for(int i=begin[p];i;i=next[i])
				if(!vis[q=to[i]] && !ded[q])vis[dl[++u]=q]=1,dis[q]=dis[p]+1;
		}
		S2.clear();
		for(int i=u;dis[dl[i]]==dis[dl[u]];i--)
			S2.push_back(dl[i]);

		if(dis[S2[0]]<=m)return 0;

		int ret;
		std::vector<int>::iterator t;
		if(S1.size()<S2.size())ret=S1.size(),t=S1.begin();
		else ret=S2.size(),t=S2.begin();
		for(int i=0;i<ret;i++)
			ded[t[i]]=1;
		return ret;
	}
	void initialize()
	{
		scanf("%d%d",&n,&m);
		for(int i=1,u,v;i<n;i++)
			scanf("%d%d",&u,&v),add(u,v);
	}
	void solve()
	{
		initialize();
		ans=0;
		for(int x;(x=make_it_shorter())!=0;)
			ans+=x;
		printf("%d\n",ans);
	}
