#define SIZE 2000//頂点数
int gen;
int mini = 1000000000;
class FOREST
{
public:
	int num;//頂点数
	vector<int>pat[SIZE];
	vector<int>ko[SIZE];
	int depth[SIZE];//深さ
	int ord[SIZE];//ord
	int fin[SIZE];//fin 閉区間
	int rord[SIZE];//ordの逆配列
	bool flag[SIZE];
	int subsiz[SIZE];//部分木サイズ
	int par[SIZE];
	int ordpt;
	void adde(int s, int t)//s-t辺を追加
	{
		pat[s].push_back(t);
		pat[t].push_back(s);
	}
	void initdfs(int node, int d)
	{
		if (flag[node])return;
		flag[node] = true;
		subsiz[node] = 1;
		rord[ordpt] = node;
		ord[node] = ordpt++;
		depth[node] = d;
		for (int i = 0; i < pat[node].size(); i++)
		{
			if (!flag[pat[node][i]])
			{
				initdfs(pat[node][i], d + 1);
				ko[node].push_back(pat[node][i]);
				subsiz[node] += subsiz[pat[node][i]];
				par[pat[node][i]] = node;
			}
		}
		fin[node] = ordpt - 1;
	}
	vector<int>calc(int node)
	{
		vector<int>ret;
		ret.resize(1);
		for (int i = 0; i < ko[node].size(); i++)
		{
			vector<int>t = calc(ko[node][i]);
			vector<int>n;
			n.resize(max(ret.size(), t.size()));
			fill(n.begin(), n.end(), 1000000000);
			for (int j = 0; j < ret.size(); j++)
			{
				for (int k = 0; k < t.size(); k++)
				{
					if (j + k <= gen)
					{
						n[max(j, k)] = min(n[max(j, k)], ret[j] + t[k]);
					}
				}
			}
			ret = n;
		}
		int g = min(gen, int(ret.size()) - 1);
		for (int i = 0; i <= g; i++)mini = min(mini, ret[i] + subsiz[0] - subsiz[node]);
		reverse(ret.begin(), ret.end());
		ret.push_back(subsiz[node]);
		reverse(ret.begin(), ret.end());
		/*printf("%d ", node + 1);
		for (int i = 0; i < ret.size(); i++)printf("  %d", ret[i]); printf("\n");*/
		return ret;
	}
};
FOREST tree;
int main()
{
	int num;
	scanf("%d%d", &num, &gen);
	for (int i = 0; i < num - 1; i++)
	{
		int za, zb;
		scanf("%d%d", &za, &zb);
		za--;
		zb--;
		tree.adde(za, zb);
	}
	tree.initdfs(0, 0);
	vector<int>t = tree.calc(0);
	printf("%d\n", mini);
}

