int n, k;
int solve(int mag)
{
	memset(sum, 0, sizeof sum);
	memset(depth, 0, sizeof depth);
	for(auto u : adj[mag])
	{
		dfs(u, 1, u, mag, 1);
		for(int i = depth[u]; i>= 1; i--)
		{
			//if(mag == 2) printf("cnt[%d][%d] = %d\n", u, i, cnt[u][i]);
			val[u][i] = val[u][i+1] + cnt[u][i];
			sum[i] += val[u][i];
		}
	}
	int best = 1e9;
	for(auto u : adj[mag])
	{
		for(int i = 0; i<= min(k, depth[u]); i++)
		{
			int other = k-i;
			if(i<= k-i) continue;
			int one = val[u][i+1];
