int n, k;
vector<int> graph[2001];

int dist[2001];

pair<vector<int>, int> fardist(int st) {
	memset(dist, -1, sizeof(dist));
	queue<int> q;

	int ansd = 0;
	vector<int> anslist{ st };

	dist[st] = 0;
	q.push(st);
	while (!q.empty()) {
		int u = q.front();
		q.pop();
		if (ansd < dist[u]) {
			ansd = dist[u];
			anslist = { u };
		}
		else if (ansd == dist[u]) {
			anslist.push_back(u);
		}

		for (int v : graph[u]) {
			if (dist[v] == -1) {
				dist[v] = dist[u] + 1;
				q.push(v);
			}
		}
	}

	return { anslist, ansd };
}

tuple<int, int, int> diameter() {
	auto d1 = fardist(1);
	auto d2 = fardist(d1.first[0]);
	return make_tuple(d1.first[0], d2.first[0], d2.second);
}

int check(int st) {
	memset(dist, -1, sizeof(dist));
	queue<int> q;

	dist[st] = 0;
	q.push(st);
	while (!q.empty()) {
		int u = q.front();
		q.pop();
		if (dist[u] >= k) {
			continue;
		}

		for (int v : graph[u]) {
			if (dist[v] == -1) {
				dist[v] = dist[u] + 1;
				q.push(v);
			}
		}
	}

	int cnt = 0;
	for (int i = 1; i <= n; ++i) {
		if (dist[i] == -1) {
			++cnt;
		}
	}
	return cnt;
}

void proc() {
	scanf("%d %d", &n, &k);
	for (int i = 0; i < n - 1; ++i) {
		int a, b;
		scanf("%d %d", &a, &b);
		graph[a].push_back(b);
		graph[b].push_back(a);
	}

	auto d = diameter();
	if (get<2>(d) <= k) {
		printf("0");
		return;
	}

	int ans = n;
	for (int i = 1; i <= n; ++i) {
		if (graph[i].size() > 1) {
			continue;
		}
		auto di = fardist(i);
		if (di.second != get<2>(d)) {
			continue;
		}

		ans = min(ans, check(i));
	}
	printf("%d", ans);
}

int main() {
	//freopen("input.txt", "r", stdin);
	proc();
	return 0;
}

