ll get_newroot(const V<ll> linklist[], bool invalid[], ll root, ll n, ll k)
{
    queue<ll> q;
    bool checked[n+1];
    ll level[n+1];
    ll ret = root;
    ll maxlevel = 0LL;

    memset(checked, 0, sizeof(checked));
    memset(level, 0, sizeof(level));

    q.push(root);
    checked[root] = true;
    level[root] = 0LL;

    for ( ; !(q.empty()); ) {
        ll now = q.front(); q.pop();
        for (auto next : linklist[now]) {
            if (checked[next]) continue;
            if (invalid[next]) continue;
            q.push(next);
            checked[next] = true;
            level[next] = level[now] + 1LL;

            if (level[next] <= k && maxlevel < level[next]) ret = next;
        }
    }

    rep (v, n+1) if (level[v] > k) invalid[v] = true;

    return ret;
}

bool set_invalid(const V<ll> linklist[], bool invalid[], ll root, ll n, ll k)
{
    queue<ll> q;
    bool checked[n+1];
    ll level[n+1];

    memset(checked, 0, sizeof(checked));
    memset(level, 0, sizeof(level));

    q.push(root);
    checked[root] = true;
    level[root] = 0LL;

    for ( ; !(q.empty()); ) {
        ll now = q.front(); q.pop();

        for (auto next : linklist[now]) {
            if (checked[next]) continue;
            if (invalid[next]) continue;

            q.push(next);
            checked[next] = true;
            level[next] = level[now] + 1LL;
        }
    }

    bool ret = true;
    rep (i, n+1) if (level[i] > k) {
        invalid[i] = true;
        ret = false;
    }

    return ret;
}

