int dist[2010][2010];

void dfs(int cur, int ini, int cnt=0, int prev=-1) {
    dist[ini][cur] = cnt++;
    for(auto x : to[cur]) {
        if(x == prev) continue;
        dfs(x, ini, cnt, cur);
    }
