signed main() {
    memset(dist, -1, sizeof(dist));
    cin >> N >> K;
    rep(i,0,N-1) {
        int u, v; cin >> u >> v;
        u--; v--;
        to[u].push_back(v);
        to[v].push_back(u);
        es.push_back(pii(u, v));
    }
    rep(i,0,N) dfs(i, i);

    int ans = INF;
    if(K % 2 == 0) {
        // 各頂点を中心として、K / 2 を超えている頂点数の最小を求める
        rep(i,0,N) {
            int temp = 0;
            rep(j,0,N) {
                if(dist[i][j] > K / 2) temp++;
            }
            chmin(ans, temp);
        }
    }
    else {
        // 各辺を中心として、(K - 1) / 2 を超えている頂点数の最小を求める
        rep(i,0,es.size()) {
            int u = es[i].first, v = es[i].second, temp = 0;
            rep(j,0,N) {
                int d = min(dist[u][j], dist[v][j]);
                if(d > (K - 1) / 2) temp++;
            }
            chmin(ans, temp);
        }
    }
    cout << ans << endl;
    return 0;
}

