void search(int at, int dep) {
    vis[at] = 1;
    depth[dep]++;
    for (auto &i : G[at]) {
        if (!vis[i]) search(i, dep + 1);
    }
}

int val(int r) {
    for (int i = 0; i < n; i++) depth[i] = vis[i] = 0;
    search(r, 0);
    int res = 0;
    for (int i = k / 2 + 1; i < n; i++) res += depth[i];
    /*
