    }
    cerr << endl;*/
    return res;
}

int valodd(int p, int q) {
    for (int i = 0; i < n; i++) depth[i] = vis[i] = 0;
    vis[q] = 1;
    search(p, 0);
    vis[q] = 0;
    search(q, 0);
    int res = 0;
    for (int i = k / 2 + 1; i < n; i++) res += depth[i];
    /*
    for (int i = 0; i < n; i++) {
        cerr << depth[i] << " ";
    }
    cerr << endl;*/
    return res;
}

