//木の直径 verified AOJ GRL_5_A
#define MAX_V 2000

struct edge{ int to,cost; };
pii dfs(int prev, int v, const vector<edge> graph[MAX_V]){   //searching farthest node
    pii r(0,v);

    rep(i,graph[v].size()){
        struct edge e = graph[v][i];
        if(e.to == prev) continue;
        pii tmp = dfs(v,e.to,graph);
        tmp.first += e.cost;
        if(r.first < tmp.first) r = tmp;
    }
    return r;
}

int diameter( const vector<edge> graph[MAX_V] ) {
    pii r = dfs(-1, 0, graph);
    pii t = dfs(-1, r.second, graph);
    return t.first;
}


vector<edge> G[MAX_V];

int dfs(int cur, int prev, int dist){
    if(dist==0)return 1;

    int ret = 0;
    for(auto e:G[cur]){
        if(e.to==prev)continue;
        ret += dfs(e.to,cur,dist-1);
    }

    return ret;
}

int main(){
    int n,k;
    cin>>n>>k;

    vector<pii> edges;
    rep(i,n-1){
        int u,v;
        cin>>u>>v;
        u--,v--;
        edges.pb(pii(u,v));
        G[u].pb(edge{v,1});
        G[v].pb(edge{u,1});
    }

    int d = diameter(G);
    if(d<=k){
        cout<<0<<endl;
        return 0;
    }

    int ans = INF;
    if(k%2==0){
        rep(i,n){
            int t = dfs(i,-1,k/2)+1;
            ans = min(ans,n-t);
        }
    }else{
        for(pii e : edges){
            int u,v;
            tie(u,v) = e;
            int t = dfs(u,v,(k-1)/2) + dfs(v,u,(k-1)/2)+2;
            ans = min(ans,n-t);
        }
    }
