int dim(int n) {
  for (int i = 0; i < N; i++) dist[i] = vis[i] = 0;

  dfs(n, -1);

  int mx = 0, del1;
  for (int i = 0; i < N; i++) {
    if (mx < dist[i]) {
      mx = dist[i];
      del1 = i;
    }
  }

  for (int i = 0; i < N; i++) dist[i] = vis[i] = 0;

  dfs(del1, -1);

