int solve(int cur, int ht, int parent)
{
	if(ht==0)
		return sub[cur];
	if(dp[cur][ht] != -1)
		return dp[cur][ht];
	int ret = inf, sum = 0, nht;
	if(adj[cur].size() == 1){
