                continue;
            }
            sum += dp[to][mx - 1 + 1];
            mn = min(mn, dp[to][i - 1 + 1] - dp[to][mx - 1 + 1]);
        }
        dp[v][i + 1] = min(dp[v][i], sum + mn);
    }
}

