using namespace std;
const int maxn = 2345;
int upto[maxn][maxn], sz[maxn], k;
vector<int> e[maxn];
map<long long, int> magic;
long long access(int u, int v, int k){
	return 1ll * u * maxn * maxn + v * maxn + k;
}
int get_upto(int u, int v, int k){
	if(k < 0) return 0;
	long long ind = access(u, v, k);
	auto it = magic.find(ind);
	if(it != magic.end()) return it->second;
	int ans = 1;
	for(int nxt : e[u]) if(nxt != v) ans += get_upto(nxt, u, k - 1);
	return magic[ind] = ans;
}
int best(int u, int v, int dist){
	if(dist > k) return 0;
	int can = min(dist, k - dist);
	int tot = 0;
	for(int nxt : e[u]) if(nxt != v){
		if(can) tot += get_upto(nxt, u, can - 1);
	}
	int res = 0;
	for(int nxt : e[u]) if(nxt != v){
		int ntot = tot;
		if(can) ntot -= get_upto(nxt, u, can - 1);
		res = max(res, ntot + best(nxt, u, dist + 1));
	}
	return res + 1;
}
int main(){
	int n; cin >> n >> k;
	for(int i = 0; i < n - 1; i++){
		int x, y; cin >> x >> y; e[x].push_back(y); e[y].push_back(x);
	}
	int res = 0;
	for(int i = 1; i <= n; i++) {
		res = max(res, best(i, 0, 0));
	}
	cout << n - res << endl;
	return 0;
}

