using namespace std;
typedef long long ll;
typedef unsigned long long ull;
typedef pair<int, int> PII;

struct edge {
  int to, cost;
  edge(int to, int cost) : to(to), cost(cost) {}
};
typedef vector<vector<edge> > Graph;
Graph G(2001);

void add_edge(int from, int to, int cost) {
  G[from].push_back(edge(to, cost));
}

edge visit(int p, int v, Graph &g) {
  edge r(v, 0);
  for (edge e : g[v]) {
    if (e.to != p) {
      edge t = visit(v, e.to, g);
      t.cost += 1;
      if (r.cost < t.cost) {
        r = t;
      }
    }
  }
  return r;
}

// (r.to, t.to) is farthest pair
int diameter(vector<vector<edge> > &g) {
  edge r = visit(-1, 0, g);
  edge t = visit(-1, r.to, g);
  return t.cost;
}


int N, K;


int countV(int p, int v, int dist) {
  int c = 0;
  if (dist > K / 2) {
    c++;
  }
  for (edge e : G[v]) {
    if (e.to != p) {
      c += countV(v, e.to, dist + 1);
    }
  }
  return c;
}

void solve() {
  int m = diameter(G), ans = INF;
  if (m < K) {
    cout << 0 << endl;
    return;
  }
  if (m % 2 == 0) {
    // 直径が偶数→すべての頂点に関して, 距離K/2以上の頂点を数え,それの最小値が答え
    REP(i, N) {
      ans = min(ans, countV(-1, i, 0));
    }
  } else {
    // 直径が奇数→すべての辺に関して, 距離(K - 1)/2 以上となる頂点を数え, それの最小値が答え
    REP(i, N) {
      for (edge e : G[i]) {
        int l = countV(e.to, i, 0);
        int r = countV(i, e.to, 0);
        ans = min(ans, l + r);
      }
    }
  }
  cout << ans << endl;
}

int main(void) {
  cin.tie(0);
  ios::sync_with_stdio(false);

  cin >> N >> K;
  REP(i, N - 1) {
    int a, b;
    cin >> a >> b;
    add_edge(a - 1, b - 1, 1);
    add_edge(b - 1, a - 1, 1);
  }
  solve();
  return 0;
}

