	e[++tot].next=h[u],h[u]=tot,e[tot].r=v,e[tot].v=x;
}
int size[N],sum,fake[N],ans;
int getmax(int x,int fa){
	size[x]=1;
	int cnt=0;
	for(int i=h[x];i;i=e[i].next)if(!fake[i]){
		int y=e[i].r;
		if(y==fa)continue;
		int w=getmax(y,x);
		size[x]+=size[y];
		if(max(sum-size[e[cnt].r],size[e[cnt].r])>max(sum-size[e[w].r],size[e[w].r]))cnt=w;
		if(max(sum-size[y],size[y])<max(sum-size[e[cnt].r],size[e[cnt].r]))cnt=i;
	}
	return cnt;
}
int dep[N],cnt1[N],cnt2[N],depmax;
void calc1(int x,int fa,int v){
	size[x]=1;dep[x]=dep[fa]+v;depmax=max(dep[x],depmax);cnt1[dep[x]]++;
	for(int i=h[x];i;i=e[i].next)if(!fake[i]){
		int y=e[i].r;
		if(y==fa)continue;
		calc1(y,x,e[i].v);
		size[x]+=size[y];
	}
}
void calc2(int x,int fa,int v){
	size[x]=1;dep[x]=dep[fa]+v;depmax=max(dep[x],depmax);cnt2[dep[x]]++;
	for(int i=h[x];i;i=e[i].next)if(!fake[i]){
		int y=e[i].r;
		if(y==fa)continue;
		calc2(y,x,e[i].v);
		size[x]+=size[y];
	}
}
void sol(int x){
	sum=size[x];
	if(sum==1)return;
	x=getmax(x,0);
	fake[x]=fake[x^1]=1;
	int p=e[x].r,q=e[x^1].r;
	calc1(p,0,0);
	calc2(q,0,0);
	int ret=k-e[x].v;
	if(depmax*2+e[x].v<=k){
		ans=max(ans,sum);
		for(int i=0;i<=depmax;i++)cnt1[i]=cnt2[i]=0;
		return;
	}
	for(int i=1;i<=ret;i++)cnt1[i]+=cnt1[i-1],cnt2[i]+=cnt2[i-1];
	for(int i=0;i<=ret;i++)ans=max(cnt1[i]+cnt2[ret-i],ans);
	for(int i=0;i<=depmax;i++)cnt1[i]=cnt2[i]=0;
	sol(p);sol(q);
}
