int N, K;
vector<int> graph[2020];
int sub[2020];

int dfs(int p, int rt)
{
	sub[p] = 1;
	for (int q : graph[p]) if (q != rt) sub[p] += dfs(q, p);
	return sub[p];
}

int ultimate = 23486932;

vector<int> solve(int p, int rt)
{
	vector<vector<int> > tmp;
	vector<int> ch;
	for (int q : graph[p]) if (q != rt) {
		ch.push_back(q);
		tmp.push_back(solve(q, p));
	}

	vector<int> ret;
	ret.push_back(sub[p]);
	for (int i = 0; i <= K; ++i) {
		int j = K - i;
		if (i <= j) {
			int sco = 0;
			for (auto &a : tmp) sco += a[i];
			sco = min(sco, ret[ret.size() - 1]);
			ret.push_back(sco);
		} else {
			int ans = 202020, pres = 0;
			for (auto &a : tmp) pres += a[j];
			for (auto &a : tmp) {
				ans = min(ans, pres - a[j] + a[i]);
			}
			if (ch.size() == 0) ans = 0;
			ans = min(ans, ret[ret.size() - 1]);
			ret.push_back(ans);
		}
	}
	ultimate = min(ultimate, (sub[0] - sub[p]) + ret[ret.size() - 1]);
	return ret;
}

