bool used[MAX_N];
int bfs(int pos, int cnt, int pre){

  typedef pair<int, int> II;

  memset(used, 0, sizeof(used));
  used[pos] = true;
  queue<II> que;
  que.push(II(pos, cnt));

  int ret = 1;
  while(que.size()){

    II p = que.front();
    que.pop();

    if(p.second == 0)
      continue;

    for(int i = 0; i < (int)Edge[p.first].size(); i++){
      int next = Edge[p.first][i];
      if(!used[next] && next != pre){
	used[next] = true;
	ret++;
	que.push(II(next, p.second-1));
      }
    }

  }

  return ret;

}

int solve(){

