  for(int i = 0; i < N; i++){
    if(K%2 == 0){
      ret = min(ret, N-bfs(i, K/2, -1));
    }
    else{
      for(int e = 0; e < (int)Edge[i].size(); e++){
	ret = min(ret, N-(bfs(i, K/2, Edge[i][e]) + bfs(Edge[i][e], K/2, i)));
      }
    }
  }

  return ret;

}

