struct Graph {
    struct Vertex { int n; };
    struct Edge { int i, n; };
    Graph(int n, int m) : v(n, { -1 }), e(m), n(n), m(0) {}
    void add_edge(int i, int j) {
        e[m] = { j, v[i].n };
        v[i].n = m;
        m++;
    }
    int dfs(int i, int p, int d) {
        int k = 1;
        if (d == 0) return k;
        for (int j = v[i].n; j >= 0; j = e[j].n) {
            Edge& o = e[j];
            if (o.i == p) continue;
            k += dfs(o.i, i, d - 1);
        }
        return k;
    }
    int solve(int d) {
        int r = 0;
        if (d % 2 == 0) {
            for (int i = 0; i < n; i++) {
                r = max(r, dfs(i, -1, d / 2));
            }
        } else {
            for (int i = 0; i < n; i++) {
                for (int j = v[i].n; j >= 0; j = e[j].n) {
                    Edge& o = e[j];
                    if (o.i < i) continue;
                    r = max(r, dfs(i, o.i, d / 2) + dfs(o.i, i, d / 2));
                }
            }
        }
        return n - r;
    }
    vector<Vertex> v;
    vector<Edge> e;
    int n, m;
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);

    int n, k;
