P dfs(int id, int pr){
  P ret = P(-1,-1);
  if( G[id].empty() ) return P(0,id);
  bool f = false;
  for( int to : G[id] ){
    if( pr == to ) continue;
    if( used[to] ) continue;
    f = true;
    ret = max( ret, dfs( to , id) );    
  }
  if( !f ) return P(0,id);
  ret.first += 1;
  return ret;
}

