inline void add(int x,int y){get[++top]=y;next[top]=first[x];first[x]=top;}
void dfs(int x,int f,int d){
	deep[x]=d; fa[x]=f; if (deep[x]>k/2) ++now;
	for (int i=first[x];i;i=next[i]){
