#define FOR(i,a,b) for(int i = (a);i < (int) (b);i++)
#define PB push_back
#define MP make_pair
#define ALL(x) (x).begin(),(x).end()
typedef long long ll;
using namespace std;

int N,K;
list<int> edge [2001];
const int INF = 1e9;

void bfs(int start,vector<int>& distance)
{
	queue< pair<int,int> > q;
	q.push(MP(start,0));

	while(q.empty() != true){
		int node = q.front().first;
		int cost = q.front().second;
		q.pop();

		if(distance [node] <= cost) continue;
		distance [node] = cost;

		for(auto&& it : edge [node]){
			q.push(MP(it,cost + 1));
		}
	}
}

int solve1()
{
	int res = INF;
	FOR(i,1,N + 1){
		vector<int> distance(N + 1,INF);
		bfs(i,distance);

		int cnt = 0;
		FOR(i,1,N + 1){
			if(distance [i] > K / 2){
				cnt++;
			}
		}
		res = min(cnt,res);
	}

	return res;
}

int solve2(int par,int cur)
{
	int res = INF;
	for(auto&& it : edge [cur]){
		if(it != par){
			vector<int> distance1(N + 1,INF),distance2(N + 1,INF);
			bfs(cur,distance1);
			bfs(it,distance2);

			int cnt = 0;
			FOR(i,1,N + 1){
				if(distance1 [i] > K / 2 && distance2 [i] > K / 2){
					cnt++;
				}
			}
			res = min({solve2(cur,it),cnt,res});
		}
	}

	return res;
}

