vector< vector<int> > G;
ll dfs(int v, int prev, int depth, int th) {
    ll res = 0;
    if (depth >= th) ++res;
    EACH(to, G[v]) {
        if (to == prev) continue;
        res += dfs(to, v, depth+1, th);
    }
    return res;
}
int main() {
    std::ios::sync_with_stdio(false);
    std::cin.tie(0);
    int n, k; cin >> n >> k;
    G.resize(n);
    REP(i, n-1) {
        int a, b; cin >> a >> b; --a, --b;
        G[a].pb(b);
        G[b].pb(a);
    }
    ll ans = inf;
    REP(i, n) {
        ll sum = 0;
        ll M = 0;
        EACH(to, G[i]) {
            ll cnt1 = dfs(to, i, 0, k/2);
            ll cnt2 = dfs(to, i, 0, (k+1)/2);
            M = max(M, cnt1-cnt2);
            sum += cnt1;
        }
        sum -= M;
        ans = min(ans, sum);
    }
    cout << ans << endl;
}

