using namespace std;

class LowestCommonAncestor {

public:
    vector<vector<int>> graph;
    int log_v;
    vector<vector<int>> parent;
    vector<int> depth;

    // graph[ノード番号] = リンク先のノード番号のリスト (e.g. graph[0] = [1, 2, 3])
    LowestCommonAncestor(const vector<vector<int>> &graph) :graph(graph) {
        int v = graph.size();
        this->log_v = int(log2(v)) + 1;
        this->parent = vector<vector<int>>(log_v, vector<int>(v));
        this->depth = vector<int>(v);
    }

    void init(int root) {
        dfs(root, -1, 0);

        for (int k = 0; k + 1 < this->log_v; k++) {
            for (int v = 0; v < this->graph.size(); v++) {
                if (parent[k][v] < 0) parent[k + 1][v] = -1;
                else parent[k + 1][v] = parent[k][parent[k][v]];
            }
        }
    }
    // uとvの最近共通祖先
    int lca(int u, int v) {
        if (depth[u] > depth[v]) {
            swap(u, v);
        }
        for (int k = 0; k < this->log_v; ++k) {
            if ((depth[v] - depth[u]) >> k & 1) {
                v = parent[k][v];
            }

        }
        if (u == v) {
            return u;
        }

        for (int k = this->log_v - 1; k >= 0; --k) {
            if (parent[k][u] != parent[k][v]) {
                u = parent[k][u];
                v = parent[k][v];
            }
        }
        return parent[0][u];
    }

private:
    void dfs(int v, int p, int d) {
        parent[0][v] = p;
        depth[v] = d;
        for (int i = 0; i < graph[v].size(); ++i) {
            if (graph[v][i] != p) {
                dfs(graph[v][i], v, d + 1);
            }
        }
    }
};

void dfs(int v, int parent, vector<int> &dist, const map<int, vector<pair<int, int>>> &edges) {
    FOE(p, edges.at(v)) {
        if (p.first != parent && p.first != v) {
            dist[p.first] = dist[v] + p.second;
            dfs(p.first, v, dist, edges);
        }
    }
}

// 木のrootからの各頂点への距離を求める
// n: 頂点数
// edges: edges[v] = [{u1, cost1}, {u2, cost2}, ...]
vector<int> get_distance(unsigned int n, int root, const map<int, vector<pair<int, int>>> &edges) {
    vector<int> dist(n, INT_MAX);
    dist[root] = 0;
    dfs(root, -1, dist, edges);
    return dist;
}


int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    int N, K, A, B;
    cin >> N >> K;

    map<int, vector<pair<int, int>>> edges;
    vector<vector<int>> graph(N);

    FOR(i, 0, N - 1) {
        cin >> A >> B;
        --A; --B;
        graph[A].push_back(B);
        graph[B].push_back(A);

        edges[A].push_back({B, 1});
        edges[B].push_back({A, 1});
    }

    LowestCommonAncestor lca(graph);
    lca.init(0);

    vector<int> dist = get_distance(N, 0, edges);

    int ans = N - 1;
    FOE(e, edges) {

        if (e.second.size() == 1) {
            int num = 0;
            int v = e.first;
            FOR(w, 0, N) {
                if (w == v) { continue; }
                int d = dist[v] + dist[w] - 2 * dist[lca.lca(v, w)];
                num += (d > K);
            }
            ans = min(ans, num);
        }
    }

    cout << ans << endl;

    return 0;
}

