const int MAXN = 2 * 1000 + 10;
vector <int> adj[MAXN];
int h[MAXN];
bool visit[MAXN];
int dad[MAXN];
bool rmv[MAXN];
queue <int> q;
int n, k;

void bfs(int v)
{
	visit[v] = true;
	q.push(v);
	h[v] = 0;
	dad[v] = -1;
	while(!q.empty())
	{
		int u = q.front();
		q.pop();
		for(int i = 0; i < adj[u].size(); i++)
		{
			int x = adj[u][i];
			if(!visit[x] && !rmv[x])
			{
				visit[x] = true;
				h[x] = h[u] + 1;
				dad[x] = u;
				q.push(x);
			}
		}
	}
	return;
}

void strt()
{
	for(int i = 0; i < n; i++)
	{
		visit[i] = 0;
		dad[i] = 0;
		h[i] = 0;
	}
	return;
}

int shortd()
{
	int cnt = 0;
	strt();
	bfs(0);
	int mxv, mxh = 0;
	for(int i = 0; i < n; i++)
	{
		if(h[i] > mxh)
		{
			mxh = h[i];
			mxv = i;
		}
	}
	strt();
	bfs(mxv);
	mxh = 0;
	for(int i = 0; i < n; i++)
	{
		if(h[i] > mxh)
		{
			mxh = h[i];
			mxv = i;
		}
	}
	while(mxh > k)
	{
		int x = mxv;
		while(dad[x] != -1 && h[x] > k)
		{
			rmv[x] = true;
			cnt++;
			x = dad[x];
		}
		strt();
		int last = 0;
		while(rmv[last])
			last++;
		bfs(last);
		mxh = 0;
		for(int i = 0; i < n; i++)
		{
			if(h[i] > mxh)
			{
				mxh = h[i];
				mxv = i;
			}
		}
		strt();
		bfs(mxv);
		mxh = 0;
		for(int i = 0; i < n; i++)
		{
			if(h[i] > mxh)
			{
				mxh = h[i];
				mxv = i;
			}
		}
	}
	return cnt;
}

int main()
{
	ios_base::sync_with_stdio(false); cin.tie(0); cout.tie(0);
	cin >> n >> k;
	for(int i = 1; i < n; i++)
	{
		int a, b;
		cin >> a >> b;
		a--, b--;
		adj[a].push_back(b);
		adj[b].push_back(a);
	}
	for(int i = 0; i < n; i++)
		rmv[i] = false;
	int ans = shortd();
	cout << ans << endl;
	return 0;
}

