        --a;
        --b;
        graph[a].insert(make_pair(b,1));
        graph[b].insert(make_pair(a,1));
        graph_[a].push_back(b);
        graph_[b].push_back(a);
    }

    lca_solver ls(graph_,0);
    vector<vector<int>> dist(n,vector<int>(n,inf));
