#include<bits/stdc++.h>
using namespace std;
const int N=2005;
int head[N],ver[N*2],nxt[N*2],tot;
int n,k;
int dp[N];
int g[N];
void add(int x,int y)
{
	ver[++tot]=y;
	nxt[tot]=head[x];
	head[x]=tot;
}
void dfs(int rt,int fa,int dep)
{
	for(int i=head[rt]; i; i=nxt[i])
	{
		int y=ver[i];
		if(y!=fa)
		{
			dfs(y,rt,dep+1);
			g[rt]+=g[y]+1;
			dp[rt]+=dp[y];
		}
	}
	if(dep>k/2)
		dp[rt]=g[rt];
}
int main()
{
	scanf("%d%d",&n,&k);
	int x,y;
	for(int i=1; i<n; i++)
	{
		scanf("%d%d",&x,&y);
		add(x,y);
		add(y,x);
	}
	int ans=1e9;
	if(k%2==0)
	{
		for(int i=1; i<=n; i++)
		{
			memset(dp,0,sizeof(dp));
			memset(g,0,sizeof(g));
			dfs(i,i,1);
			ans=min(ans,dp[i]);
			//cout<<dp[i]<<endl;
		}
	}
	else
	{
		for(int x=1;x<=n;x++)
