		for(int v=0;v<n;++v){
			d[v][v]=0;
			fill(f,f+n,false);
			ans=max(ans,dfs(v,v));
		}
	}else{
		for(int v=0;v<n;++v){
			int a=0,b=0;
			vector<int> V,W;
			fill(f,f+n,false);
			f[v]=true;
