paii bfs(int st, int pr) {
    vec<int> pt;
    pt.pb(pr);
    d[pr] = -1;
    d[st] = 0;
    queue<int> q;
    q.push(st);
    while(!q.empty()) {
        int p1 = q.front();
        q.pop();

        pt.pb(p1);
        cnt[d[p1]]++;

        for(int p2 : graf[p1]) {
            if(d[p2] > d[p1] + 1) {
                d[p2] = d[p1] + 1;
                q.push(p2);
            }
        }
    }
    /*cout << st + 1 << ": ";
    loop(i, 5) cout << cnt[i] << " ";
    cout << endl*/;

    int kek = 0;
    cnt[0] = 0;
    FOR(i, 1, k / 2 + 1) {
        if(cnt[i] == 0) break;
        cnt[i] += cnt[i - 1];
        kek = cnt[i];
    }
    paii p = {cnt[k / 2 - 1], cnt[k / 2]};
    if(p.fr == 0) p.fr = kek;
    if(p.sc == 0) p.sc = kek;
    loop(i, n) {
        if(cnt[i] == 0) break;
        cnt[i] = 0;
    }
    for(int c : pt) d[c] = inf;
    return p;
}

void solve() {
    loop(i, MAXN) d[i] = inf;
    loop(i, MAXN) cnt[i] = 0;
    cin >> n >> k;
    loop(i, n - 1) {
        int a, b;
        cin >> a >> b;
        --a, --b;
        graf[a].pb(b);
        graf[b].pb(a);
    }
    int ans = 0;
    loop(p1, n) {
        //cout << p1 + 1 << ": " << endl;
        vec<paii> t;
        for(int p2 : graf[p1]) {
            t.pb(bfs(p2, p1));
        }
        if(k % 2 == 1) {
            int sum = 1;
            for(paii p : t) sum += p.sc;
            ans = max(ans, sum);
        } else {
            int sum = 1;
            for(paii p : t) sum += p.fr;
            for(paii p : t) {
                int k = sum - p.fr + p.sc;
                ans = max(ans, k);
            }
        }
        //cout << endl;
    }
    cout << n - ans << endl;
}

