void dik(long start){
	priority_queue<pair<long, long>, vector<pair<long,long> >, greater<pair<long,long> > > Q;
	Q.push(make_pair(0, start));
	while(!Q.empty()){
		long po, cost;
		cost = Q.top().first;
		po = Q.top().second;
		//cout << "start" << start << "po=" << po << "cost" << cost << endl;
		Q.pop();
		if(dis[start][po] != INF){
			//cout << "con" << endl;
			continue;
		}
		dis[start][po] = cost;
		for(int i = 0; i < way[po].size(); i++){
			if(dis[start][way[po][i]] != INF){
				continue;
			}
			Q.push(make_pair(dis[start][po] + 1, way[po][i]));
		}
	}
}


