int dfs(int now, int prev, int left) {
    if (left == 0) return 1;

    int ret = 0;
    for (int i = 0; i < N; i++) {
	if (prev == i) continue;
	if (now == i) continue;
	if (!con[i][now]) continue;
	ret += dfs(i, now, left - 1);
    }

    return ret + 1;
}

int count(int num) {
    return dfs(num, -1, K);
}

