}

int lca(int u, int v){
	if(d[u] > d[v])swap(u, v);
	int dd = d[v]-d[u];
	//printf("%lld ", dd);
	rep(i,15)if(dd & (1<<i))v = vs[i][v];
	if(v == u)return v;
	drep(i,14,0){
		if(vs[i][u] == -1)continue;
		if(vs[i][u] != vs[i][v]){u = vs[i][u];v = vs[i][v];}
	}
	return vs[0][v];
}

