const int maxn=2000+7;

int n,K,ans=0,length;
int head[maxn],cnt=0;
int dist[maxn],Dist[maxn],root=0,root2=0;
int up[maxn],down[maxn],siz[maxn];
struct Edge{int nxt,to,dis;}edge[maxn*2];
bool p[maxn];

void add(int from,int to,int dis){
	edge[++cnt].nxt=head[from];edge[cnt].to=to;edge[cnt].dis=dis;head[from]=cnt;	
}
void dfs1(int u,int fa){
	for(int i=head[u];i!=0;i=edge[i].nxt){
		int v=edge[i].to;if(v==fa)continue;
		dist[v]=dist[u]+1;
		if(dist[v]>dist[root])root=v;
		dfs1(v,u);
	}return;
}
void dfs2(int u,int fa){
	for(int i=head[u];i!=0;i=edge[i].nxt){
		int v=edge[i].to;if(v==fa)continue;
		Dist[v]=Dist[u]+1;up[v]=u;
		if(Dist[v]>Dist[root2])root2=v;
		dfs2(v,u);
	}
}
void dfs3(int u){
	siz[u]=1;
	for(int i=head[u];i!=0;i=edge[i].nxt){
		int v=edge[i].to;if(v==up[u]||p[v])continue;
		dfs3(v);siz[u]+=siz[v];
	}return;
}
int main(){
	scanf("%d%d",&n,&K);
	for(int i=1;i<n;i++){
		int x,y;scanf("%d%d",&x,&y);
		add(x,y,1);add(y,x,1);
	}
	dfs1(1,1);dfs2(root,root);length=Dist[root2];
	memset(p,0,sizeof(p));
	int box=root2;
	while(box!=root){p[box]=1;down[up[box]]=box;box=up[box];}p[box]=1;
	for(box=down[root];box!=root2;box=down[box])dfs3(box);
	int l=root,r=root2;
	siz[root]=siz[root2]=1;
	while(length>K){
		length--;
		if(siz[l]<=siz[r])ans+=siz[l],l=down[l];
		else ans+=siz[r],r=up[r];
	}
	printf("%d\n",ans);
	return 0;
}

