using namespace std;
const long long int MOD = 1000000007;

long long int N,K;
list <int>edge[2001];
list<int>over[2001];
int dis[2001][2001];
int s, e;
bool flag[2001] = {};
queue<int>Q;
int f;
int box[2001];
int bag;
int ans;

int main() {
	cin >> N>>K;
	for (int i = 1; i <= N; i++) {
		flag[i] = true;
	}
	for (int i = 0; i < N-1; i++) {
		cin >> s >> e;
		edge[s].push_back(e);
		edge[e].push_back(s);
	}
	for (int i = 1; i <= N; i++) {
		box[i] = 0;
		if (flag[i]) {

			for (int j = 1; j <= N; j++) {
				if (i != j) {
					dis[i][j] = INT_MAX;
				}
			}
			Q.push(i);
			while (!Q.empty()) {
				f = Q.front();
				for (auto j = edge[f].begin(); j != edge[f].end(); ++j) {
					if (flag[*j]) {
						if (dis[i][*j] > dis[i][f] + 1) {
							dis[i][*j] = dis[i][f] + 1;
							Q.push(*j);
							if (dis[i][*j] > K) {
								box[i]++;
								over[i].push_back(*j);
							}
						}
					}
				}
				Q.pop();
			}
		}
	}
	while(1){
		bag = 0;
		for (int i = 1; i <= N; i++) {
				bag = max(bag, box[i]);
		}
		if (bag) {
			ans++;
			for (int i = 1; i <= N; i++) {
				if (box[i] == bag) {
					flag[i] = false;
					for (auto j = over[i].begin(); j != over[i].end(); ++j) {
						if(flag[*j])box[*j]--;
					}
					break;
				}
			}
		}
		else break;
	}
	cout << ans << endl;
	return 0;
}

