#define rep(i,N) for(LL i=0;i<N;++i)
typedef long long int LL;

std::vector<std::vector<LL>>G;
std::vector<bool>vis, exist;
std::vector<LL>depth, vs;
LL maxD;

void dfs(LL v, LL d)
{
	if (vis[v] || !exist[v]) return;
	vis[v] = true;
	depth[v] = d;
	if (maxD < d)
	{
		maxD = d;
		vs.clear();
	}
	if (maxD == d) vs.push_back(v);
	for (auto u : G[v]) dfs(u, d + 1);
}

int main()
{
	LL N, K;
	in >> N >> K;
	std::vector<LL>A(N - 1), B(N - 1);
	rep(i, N - 1) in >> A[i] >> B[i];

	G.resize(N + 1); exist.resize(N + 1, true);
	rep(i, N - 1)
	{
		G[A[i]].push_back(B[i]);
		G[B[i]].push_back(A[i]);
	}

	LL ans = 0;
	while (true)
	{
		vis.clear(); vis.resize(N + 1, false);
		depth.clear(); depth.resize(N + 1);
		vs.clear();
		maxD = 0;
		for (int i = 1; i <= N; ++i)
		{
			if (exist[i])
			{
				dfs(i, 0);
				break;
			}
		}

		std::map<LL, LL>cnt;
		auto vs_ = vs;
		vs.clear();
		maxD = 0;
		for (auto i : vs_)
		{
			vis.clear(); vis.resize(N + 1, false);
			depth.clear(); depth.resize(N + 1);
			auto prevN = vs.size();
			dfs(i, 0);
			cnt[i] += (LL)vs.size() - prevN;
		}
		for (auto i : vs) ++cnt[i];

		if (maxD <= K) break;
		++ans;

		LL max_cnt = 0, v = -1;
		for (auto i : cnt)
		{
			if (max_cnt < i.second)
			{
				max_cnt = i.second;
				v = i.first;
			}
		}
		exist[v] = false;
	}

	out << ans << std::endl;
}

