int N, K;

vector<int> G[2001];
vector<int> dp[2001][2001];
int back[2001][2001];

int gcount(int pos, int b, int k) {
  int& bpos = dp[pos][k][back[pos][b]];
  if(bpos == -1) {
    bpos = 1;
    if(k > 0) {
      for(int i = 0; i < G[pos].size(); i++) {
        if(G[pos][i] == b) continue;
        bpos += gcount(G[pos][i], pos, k - 1);
      }
    }
  }
  return bpos;
}
int main() {
  cin >> N >> K;
  for(int i = 0; i < N - 1; i++) {
    int A,B;
    cin >> A >> B;
    A--;B--;
    back[A][B] = G[A].size();
    G[A].push_back(B);
    for(int j = 0; j <= K; j++) {
      dp[A][j].push_back(-1);
      dp[B][j].push_back(-1);
    }
    back[B][A] = G[B].size();
    G[B].push_back(A);
  }
  int ans = 0;
  for(int i = 0; i < N; i++) {
    for(int j = 0; j < G[i].size(); j++) {
      int A = i;
      int B = G[i][j];
      // pair
      for(int k = 0; k <= K - 1; k++) {
        ans = max(ans, gcount(A, B, k) + gcount(B, A, K - k - 1));
      }
    }
  }
  cout << N - ans << endl;
}

