const int INF = 1001001001;

int n, k;
vvi graph;

struct Data
{
    int p, v, h;

    bool operator==(const Data& d) const {
        return tie(p, v, h) == tie(d.p, d.v, d.h);
    }
};

namespace std
{
    template<>
    struct hash<Data>
    {
        size_t operator()(const Data& d) const {
            hash<int> h;
            return h(d.p) ^ h(d.v) ^ h(d.h);
        }
    };
}

vector<unordered_map<int, int>> height;

int calc_height(int v, int p)
{
    if(height[v].count(p)){
        return height[v][p];
    }

    if(graph[v].size() - (p != -1) == 0){
        return height[v][p] = 0;
    }

    int ans = INF;
    for(int s : graph[v]){
        if(s == p) continue;
        ans = min(ans, calc_height(s, v));
    }

    return height[v][p] = ans;
}

unordered_map<Data, int> memo;

int func(Data d)
{
    if(memo.count(d)){
        return memo[d];
    }

    if(d.h == -1){
        return memo[d] = func({d.p, d.v, 0}) + 1;
    }

    if(d.h == 0){
        int sum = 0;
        for(int u : graph[d.v]){
            if(u == d.p) continue;
            sum += func({d.v, u, 0}) + 1;
        }
        return memo[d] = sum;
    }

    int nc = graph[d.v].size() - (d.p != -1);
    if(nc == 0){
        return memo[d] = 0;
    }

    int mh = INF;
    for(int u : graph[d.v]){
        if(u == d.p) continue;
        mh = max(mh, calc_height(u, d.v));
    }
    mh = min(mh, d.h - 1);

    int ans = INF;

    for(; mh>=-1; --mh){
        int ch = min(d.h - 1, k - mh - 2);
        if(mh < ch) break;

        int sum = 0;
        for(int u : graph[d.v]){
            if(u == d.p) continue;
            sum += func({d.v, u, ch});
        }

        for(int u : graph[d.v]){
            if(u == d.p) continue;
            ans = min(ans, sum - func({d.v, u, ch}) + func({d.v, u, mh}));
        }
    }

    return memo[d] = ans;
}

