		a--;
		b--;
		edge[a].pb(b);
		edge[b].pb(a);
	}

	int ans = 0;
	rep(i, n) {
		if (k % 2) {
			ans = max(ans, find(edge, k / 2, i));
			ans = max(ans, find(edge, k / 2 + 1, i));
		} else {
			ans = max(ans, find(edge, k / 2, i));
		}
	}
	cout << n - ans << endl;
	return 0;
}

