struct P {
    int id;
    int w;
};

vector<int> vs[N];
int n,k;
int p[N];

bool av[N];

P ar[N];


int sc(int start){
    queue<int> que;
    for(int i=0;i<n;i++) p[i] = INF;
    que.push(start);
    p[start] = 0;
    while(que.size()){
        int now = que.front(); que.pop();
        vector<int> v = vs[now];
        int len = v.size();
        for(int i=0;i<len;i++){
            int next = v[i];
            if(p[next] == INF && av[next]){
                p[next] = p[now] + 1;
                que.push(next);
            }
        }
    }
    int bg=0,sm=0;
    for(int i=0;i<n;i++){
        if(p[i]<=k&& av[i]){
            sm++;
        } else if(p[i]>=n-k-1&& av[i]){
            bg++;
        }
    }
    if(bg<=sm){
        for(int i=0;i<n;i++){
            if(p[i]>=n-k-1 && av[i]){
                av[i] = false;
            }
        }
    } else {
        for(int i=0;i<n;i++){
            if(p[i]<= k && av[i]){
                av[i] = false;
            }
        }
    }
    return min(bg,sm);
}

bool cmp(P x, P y){
    return x.w > y.w;
}
int scmx(int start){
    int  ans = 0;
    queue<int> que;
    for(int i=0;i<n;i++) p[i] = INF;
    que.push(start);
    p[start] = 0;
    while(que.size()){
        int now = que.front(); que.pop();
        vector<int> v = vs[now];
        int len = v.size();
        for(int i=0;i<len;i++){
            int next = v[i];
            if(p[next] == INF){
                p[next] = p[now] + 1;
                ans = max(p[next], ans);
                que.push(next);
            }
        }
    }
    return ans;
}

int main(){
    for(int i=0;i<N;i++) av[i] = true;
    cin >> n >> k;
    for(int i=0;i<n-1;i++){
        int a,b;
        cin >> a >> b;
        a--; b--;
        vs[a].push_back(b);
        vs[b].push_back(a);
    }
    for(int i=0;i<n;i++){
        ar[i].id = i;
        if (vs[i].size()==1){
         ar[i].w = scmx(i);
        } else {
            ar[i].w = -1;
        }
    }

    sort(ar,ar+n, cmp);

    int ans = 0;
    for(int i=0;i<n;i++){
        P now = ar[i];
        if(now.w>k){
            if(av[now.id] && (vs[now.id].size()==1)){
                ans += sc(now.id);
            }

        } else {
            break;
        }
    }
    cout << ans << endl;

}

