typedef pair<int, int> T;
int N, K;
vector<T> G[2010];
vector<T> E;

int dfs(int v, int p){
  int s = 1;
  for(int i = 0; i < G[v].size(); i++){
    int u = G[v][i].first;
    if( u == p ) continue;
    G[v][i].second = dfs( u, v );
    s += G[v][i].second;
  }
  return s;
}

bool used[2010];
int solve_even(int v){
  int ret = N;
  for(int i = 0; i < G[v].size(); i++){
    fill(used, used + 2010, false);
    int p = G[v][i].first;
    int t = G[v][i].second;

    queue<T> Q;
    Q.push( T( v, 0 ) );
    used[v] = true;
    if( G[v].size() == 1 ){
      t = 0;
    }else{
      used[ p ] = true;
    }
    while( !Q.empty() ){
      int u = Q.front().first;
      int d = Q.front().second; Q.pop();
      if( d == K / 2 ){
	for(int j = 0; j < G[u].size(); j++){
	  if( used[ G[u][j].first ] ) continue;
	  t += G[u][j].second;
	}
      }else{
	for(int j = 0; j < G[u].size(); j++){
	  if( used[ G[u][j].first ] ) continue;
	  Q.push( T(G[u][j].first, d + 1 ) );
	  used[ G[u][j].first ] = true;
	}
      }
    }
    ret = min(ret, t);
  }
  return ret;
}

int solve_odd(int e){
  int ret = N;
  fill(used, used + 2010, false);

  queue<T> Q;
  Q.push( T( E[e].first, 0 ) );
  Q.push( T( E[e].second, 0 ) );
  used[ E[e].first ] = true;
  used[ E[e].second ] = true;

  while( !Q.empty() ){
    int u = Q.front().first;
    int d = Q.front().second; Q.pop();
    if( d == K / 2 ){
      for(int j = 0; j < G[u].size(); j++){
	if( used[ G[u][j].first ] ) continue;
	ret += G[u][j].second;
      }
    }else{
      for(int j = 0; j < G[u].size(); j++){
	if( used[ G[u][j].first ] ) continue;
	Q.push( T(G[u][j].first, d + 1 ) );
	used[ G[u][j].first ] = true;
      }
    }
  }

  return ret;
}

int main(){
  cin >> N >> K;
  for(int i = 0; i < N - 1; i++){
    int a, b;
    cin >> a >> b;
    a--; b--;
    G[a].push_back( T(b, 0) );
    G[b].push_back( T(a, 0) );
    E.push_back( T(a, b) );
  }

  for(int v = 0; v < N; v++){
    dfs( v, -1 );
  }

  int ans = N;
  if( K % 2 == 0 ){
    for(int v = 0; v < N; v++)
      ans = min( ans, solve_even(v) );
  }else{
    for(int e = 0; e < N - 1; e++){
      ans = min( ans, solve_odd(e) );
    }
  }

  cout << ans << endl;
}

