const int maxn = 2000;

int n, diameter;
vector<int> adj[maxn];

int dist[maxn];

int solve(int x, int y, int limit)
{
    queue<int> Q;
    memset(dist, -1, sizeof(dist));
    dist[x] = dist[y] = 0;
    Q.push(x);
    if (x != y)
        Q.push(y);
    int ret = 0;
    while (!Q.empty()) {
        int p = Q.front();
        Q.pop();
        ret ++;
        if (dist[p] == limit)
            continue;
        for (int q : adj[p]) {
            if (dist[q] < 0) {
                dist[q] = dist[p] + 1;
                Q.push(q);
            }
        }
    }
    return ret;
}

