        adj[ai].push_back(bi);
        adj[bi].push_back(ai);
    }
    int maxSize = 0;
    for (int i = 0; i < n; i++) {
        if (diameter % 2 == 0) {
            maxSize = max(maxSize, solve(i, i, diameter / 2));
        } else {
            for (int j : adj[i])
                maxSize = max(maxSize, solve(i, j, diameter / 2));
        }
    }
    printf("%d\n", n - maxSize);
}

