void f(int i, int d) {
	dep[i] = d;
	for(int v : G[i]) if(!dep[v]) {
		f(v, d+1);
		upmax(mxl[i], mxl[v]+1);
	}
	for(int v : G[i]) if(dep[v] > dep[i]) {
		for(int l = mxl[v]+1; l < mxl[i]; l++)
			dp[v][l] = dp[v][mxl[v]];
