	const int N=2050,M=N*2,INF=2147483647;
	int begin[N],next[M],to[M];
	int n,m,e,ans;
	void add(int x,int y,bool k=1)
	{
		to[++e]=y;
		next[e]=begin[x];
		begin[x]=e;
		if(k)add(y,x,0);
	}
	int dfs(int p,int h=0,int dis=0)
	{
		if(dis>m/2)return 0;
		int ret=1;
		for(int i=begin[p],q;i;i=next[i])
			if((q=to[i])!=h)ret+=dfs(q,p,dis+1);
		return ret;
	}
	void work(int p)
	{
		int ret=dfs(p)+(m&1);check_min(n,ret);
		check_min(n-ret,ans);
	}
	void initialize()
	{
		scanf("%d%d",&n,&m);
		for(int i=1,u,v;i<n;i++)
			scanf("%d%d",&u,&v),add(u,v);
	}
	void solve()
	{
		initialize();
		ans=n;
		for(int i=1;i<=n;i++)
			work(i);
		printf("%d\n",ans);
	}
}
