using namespace std;
vector<int> edge[2010];
int dis[2010];
bool used[2010];
int n, k;

int main() {
	int  a, b,ma=100000;
	cin >> n >> k;
	for (int i = 0; i < n - 1; i++) {
		scanf("%d %d", &a, &b);
		a--; b--;
		edge[a].push_back(b);
		edge[b].push_back(a);
	}
	if (k % 2 == 0) {
		for (int i = 0; i < n; i++) {
			evencalc(i, i, 0);
			ma = min(ma, dis[i]);
			for (int i = 0; i < n; i++)used[i] = false;
		}
		cout << ma << endl;
	}
	else {
		for (int i = 0; i < n; i++) {
			if (edge[i].empty())continue;
			for (int j = 0; j < edge[i].size; j++) {
				ma = min(ma, oddcalc(i, edge[i][j]));
			}
		}
		cout << ma << endl;
	}
}

void evencalc(int t, int s, int count) {
	int r;
	if (count > (int)k / 2)dis[s]++;
	if (edge[t].empty())return;
	for (int i = 0; i < edge[t].size() && !used[edge[t][i]]; i++) {
		r = edge[t][i];
		used[edge[t][i]] = true;
		evencalc(r, s, count+1);
	}
}

int oddcalc(int t,int s) {
	used[t] = used[s] = true;
	evencalc(t, t, 0);
	evencalc(s, s, 0);
	return dis[t]+ dis[s];
}

#include <bits/stdc++.h>
#define INF 99999999

using namespace std;

int n, k, ans;
vector<vector<int>> G(INF);
int d[INF];
void search(int s, int sum){
	if(sum > k/2)return;
	d[s] = sum;
	for(int i = 0; i < (int)G[s].size(); i++)search(G[s][i],sum+1);
}
int D[INF];
void search2(int s, int sum){
	if(D[s] < sum)return;
	D[s] = sum;
	for(int i = 0; i < (int)G[s].size(); i++)search(G[s][i],sum+1);
}


int main(){
	ans = INF;
	cin >> n >> k;
	for(int i = 0; i < n-1; i++){
		int a, b;
		cin >> a >> b;
		a--, b--;
		G[a].push_back(b);
		G[b].push_back(a);
	}
	if(k%2==0){
		for(int i = 0; i < n; i++){
			fill(d, d+n, INF);
			d[i] = 0;
			search(i, 0);
			sort(d, d+n);
			int pre = 0;
			for(int i = 0; i < n; i++)if(d[i] > k/2)pre++;
			ans = min(ans, pre);
		}
	}
	else{
		for(int i = 0; i < n; i++){
			fill(d, d+n, INF);
			d[i] = 0;
			search(i, 0);
			for(int j = 0; j < (int)G[i].size(); j++){
				if(i < G[i][j])continue;
				fill(D, D+n, INF);
				D[j] = 0;
				search2(j, 0);
				int pre = 0;
				for(int kk = 0; kk < n; kk++)if(min(d[kk], D[kk]) > k/2)pre++;
				ans = min(ans, pre);
			}
		}
	}
	cout << ans << endl;
    return 0;
}

