using namespace std;
int n,k,doe,ans,num;
int pre[5050],now[2020],son[5050];
void add(int x,int y)
{
	++doe;
	pre[doe]=now[x];
	now[x]=doe;
	son[doe]=y;
}
void dfs(int x,int deep,int fa)
{
	if (deep>k) return;
	++num;
	int p=now[x];
	while (p)
	{
		int y=son[p];
		if (y!=fa) dfs(y,deep+1,x);
		p=pre[p];
	}
}
int main()
{
	scanf("%d%d",&n,&k);
	int x,y;
	for (int i=1;i<n;++i)
	{
		scanf("%d%d",&x,&y);
		add(x,y);
		add(y,x);
	}
	if (k%2==0)
	{
		k/=2;
		for (int i=1;i<=n;++i)
			num=0,dfs(i,0,0),ans=max(ans,num);
	}
	else
	{
		k/=2;
		for (int i=1;i<=n;++i)
		{
			int p=now[i];
			while (p)
			{
				int j=son[p];
				num=0;
				dfs(i,0,j);
				dfs(j,0,i);
				ans=max(num,ans);
				p=pre[p];
			}

		}
	}
	printf("%d\n",n-ans);
	return 0;
}

