int n,k;
vi g[2521];

bool used[2521];

int ans;
// height, size
vi dfs(int p){
  used[p] = true;
  vector<vi> chs;
  vi ch(1,1);
  REP(i,g[p].size()){
    int to = g[p][i];
    if(used[to])continue;
    vi tmp = dfs(to);
    if(tmp.size()+1 > ch.size()){
      int x = ch.size();
      ch.resize(tmp.size()+1);
      FOR(j,x,ch.size())ch[j]=1;
    }
    REP(j,tmp.size()){
      ch[j+1] += tmp[j];
    }
    chs.push_back(tmp);
  }
  REP(i,chs.size())REP(j,i){
    REP(x,chs[i].size())REP(y,chs[j].size()){
      if(x+y+2 > k)break;
      int lim = min(x,y);
      int cnt = chs[i][x] + chs[j][y];
      REP(ii,chs.size()){
        if(ii==i || ii==j)continue;
        cnt += chs[ii][min<int>(lim,chs[ii].size()-1)];
      }
      cnt += 1;
      CHMIN(ans,n-cnt);
    }
  }
  REP(i,chs.size()){
    int s = min<int>(chs[i].size(),k);
    CHMIN(ans,n-chs[i][s-1]-1);
  }
  return ch;
}

