	fill_n(h + 1, n, 0);
	dep[rt] = 0;
	dfs(rt, 0, m / 2, f);
	dfs(rt, 0, m - m / 2, h);
	int ans = 0;
	for(auto u : g[rt]) ans += f[u];
	int res = ans;
	for(auto u : g[rt]) res = max(res, ans - f[u] + h[u]);
	res++;
	return res;
}

