	std::cin.tie(0);
	cin >> n >> m;
	rep(i, 1, n) {
		int u, v; cin >> u >> v;
		g[u].pb(v), g[v].pb(u);
	}
	int ans = 0;
	rep(i, 1, n + 1) ans = max(ans, solve(i));
	cout << n - ans << endl;
	return 0;
}

