int sub[maxn], par[maxn], dp[maxn][maxn];

void dfs(int cur, int parent)
{
	sub[cur] = 1;
	par[cur] = parent;
	for(int it : adj[cur]){
		if(it != parent){
			dfs(it, cur);
			sub[cur] += sub[it];
		}
	}
}

int solve(int cur, int ht, int parent)
{
	if(ht==0)
		return sub[cur];
	if(dp[cur][ht] != -1)
		return dp[cur][ht];
	int ret = inf, sum = 0, nht;
	if(adj[cur].size() == 1){
		for(int it : adj[cur]){
			if(it != parent)
				sum += solve(it, ht-1, cur);
		}
		return dp[cur][ht] = sum;
	}
	nht = min(ht-1, k-ht+1);
	for(int it : adj[cur]){	
		if(it != parent)
			sum += solve(it, nht, cur);
	}
	for(int it : adj[cur]){
		if(it != parent)
			ret = min(ret, sum - solve(it, nht, cur) + solve(it, ht-1, cur));
	}
	return dp[cur][ht] = ret;
}

int main() 
{
	// freopen("i.txt", "r", stdin);
	// freopen("o.txt", "w", stdout);
	memset(dp, -1, sizeof(dp));
	int u, v, i, j;
	scanf("%d%d", &n, &k);
	for(i=1; i<n; i++){
		scanf("%d%d", &u, &v);
		adj[u].pb(v);
		adj[v].pb(u);
	}
	dfs(1, 0);
	int ans = inf;
	for(i=1; i<=n; i++){
		// cout << i << " " << solve(i, k+1, par[i]) << "\n";
		ans = min(ans, solve(i, k+1, par[i]) + n - sub[i]);
	}
	printf("%d\n", ans);
	return 0;
}

