static int dfs(const std::vector<std::vector<int>>& g, std::vector<int>& d, const std::vector<bool>& r, int s, int t, int k)
{
    auto m=d[t]=k;
    for(auto v:g[t]) if(v!=s && r[v]) m=std::max(m,dfs(g,d,r,t,v,k+1));
    return m;
}

int main()
{
    std::cin.tie(0);
    std::ios_base::sync_with_stdio(false);
    for(int N,K; std::cin >> N >> K; )
    {
        std::vector<std::vector<int>> g(N,std::vector<int>());
        for(int i=1; i<N; ++i)
        {
            int A,B; std::cin >> A >> B;
            --A; --B;
            g[A].push_back(B);
            g[B].push_back(A);
        }
        std::vector<int> d(N);
        std::vector<bool> r(N,true);
        auto k = dfs(g,d,r,-1,0,0);
        int s=0;
        for(int i=0; i<N; ++i) if(d[i]==k){ s=i; break; }
        int c=0;
        while(true)
        {
            k=dfs(g,d,r,-1,s,0);
            if(k<=K) break;
            std::vector<int> d1; d1.reserve(N);
            for(int i=0; i<N; ++i) if(r[i] && d[i]==k) d1.push_back(i);
            dfs(g,d,r,-1,d1[0],0);
            std::vector<int> d2; d2.reserve(N);
            for(int i=0; i<N; ++i) if(r[i] && d[i]==k) d2.push_back(i);
            if(d1.size()>d2.size()) d1.swap(d2);
            c+=d1.size();
            for(auto v:d1) r[v]=false;
        }
        std::cout << c << std::endl;
    }
}

