int N,K;
vint G[2222];

int dist[2222];

int calc(int a,int b){
    fill_n(dist,N,INT_MAX);
    dist[a]=dist[b]=0;
    queue<int>que;
    que.push(a);que.push(b);
    while(que.size()){
        int v=que.front();
        que.pop();
        for(auto u:G[v]){
            if(dist[u]!=INT_MAX)continue;
            dist[u]=dist[v]+1;
            que.push(u);
        }
    }

    int ret=0;
    rep(i,N)if(dist[i]>K/2)ret++;
    return ret;
}

signed main(){
    cin>>N>>K;
    vint A(N-1),B(N-1);
    rep(i,N-1){
        cin>>A[i]>>B[i];
        A[i]--;B[i]--;
        G[A[i]].pb(B[i]);
        G[B[i]].pb(A[i]);
    }

    int ans=INT_MAX;
    if(K&1){
        rep(i,N-1)chmin(ans,calc(A[i],B[i]));
    }
    else{
        rep(i,N)chmin(ans,calc(i,i));
    }
    cout<<ans<<endl;
    return 0;
}

