int get(int x) {
    memset(dis, -1, sizeof dis);
    queue<int>q;
    q.push(x);
    dis[x] = 0;
    while(q.size()) {
        int x = q.front();
        q.pop();
        for(auto t: g[x]) {
            if(dis[t] == -1) {
                dis[t] = dis[x] + 1;
                q.push(t);
            }
        }
    }
    int ans = 0;
    for(int i = 0; i < n; i++) if(dis[i] >= (k + 1) / 2) ans++;
    return ans;
}

