int n,k,a,b;
vector<int> nei[2007];
queue<int> q;
int juli[2007];

void bfs()
{
	while(!q.empty())
	{
		int v=q.front();
		int w=juli[v]+2;
		q.pop();
		for(int i=0;i<SZ(nei[v]);i++)
		{
			if(juli[nei[v][i]]<=w)continue;
			juli[nei[v][i]]=w;
			q.push(nei[v][i]);
		}
	}
}

int solvevertex(int what)
{
	FOR(i,n)
		juli[i]=Inf;
	juli[what]=0;
	q.push(what);
	bfs();
	int cnt=0;
	FOR(i,n)
		if(juli[i]>k)
			cnt++;
	return cnt;
}

int solveedge(int what1,int what2)
{
	FOR(i,n)
		juli[i]=Inf;
	juli[what1]=juli[what2]=1;
	q.push(what1);
	q.push(what2);
	bfs();
	int cnt=0;
	FOR(i,n)
		if(juli[i]>k)
			cnt++;
	return cnt;
}

