struct DistHelper {
  const Tree& tree;
  const int dist;
  DistHelper(const Tree& tree, int diameter) : tree(tree), dist(diameter / 2) {}
  int count(int v, int p = -1, int d = 0) const {
    int r = d > dist;
    for (int u : tree[v]) {
      if (u == p) continue;
      r += count(u, v, d + 1);
    }
    return r;
  }
};

