    if(g[v][e] != INF) {
        Result t = visit(v, e, g);
        t.first += g[v][e];
        if (r.first < t.first) r = t;
    }
  }
  return r;
}
int diameter(vector< vector<int> > &g) {
  Result r = visit(-1, 1, g);
  Result t = visit(-1, r.second, g);
  return t.first;
}

