const int MAX_V = 2001;
vector<int> E[MAX_V];
int n, k;

int bfs_even(int s) {
    int dist[MAX_V];

    queue<int> que;
    fill(dist, dist + MAX_V, INF);
    dist[s] = 0;
    que.push(s);
    while (!que.empty()) {
        int q = que.front();
        que.pop();
        for (auto e : E[q]) {
            if (dist[e] == INF) {
                que.push(e);
                dist[e] = dist[q] + 1;
            } else if (dist[e] > dist[q] + 1) {
                dist[e] = dist[q] + 1;
            }
        }
    }

    int cnt = 0;
    rep2(i, n) if (dist[i] > k / 2) cnt++;
    return cnt;
}

int bfs_odd(int s, int t) {
    int dist[MAX_V];

    queue<int> que;
    fill(dist, dist + MAX_V, INF);
    dist[s] = 0;
    que.push(s);
    while (!que.empty()) {
        int q = que.front();
        que.pop();
        for (auto e : E[q]) {
            if (dist[e] == INF) {
                if (e != t) que.push(e);
                dist[e] = dist[q] + 1;
            } else if (dist[e] > dist[q] + 1) {
                dist[e] = dist[q] + 1;
            }
        }
    }

    int cnt = 0;
    rep2(i, n) if (dist[i] != INF && dist[i] > k / 2) cnt++;
    return cnt;
}

int main() {
    cin >> n >> k;

    rep(i, n - 1) {
        int a, b;
        cin >> a >> b;
        E[a].push_back(b);
        E[b].push_back(a);
    }

    int Min = INF;

    if (k % 2 == 0) {
        rep2(i, n) Min = min(Min, bfs_even(i));
    } else if (k % 2 == 1) {
        rep2(i, n) for (auto e : E[i]) Min = min(Min, bfs_odd(i, e) + bfs_odd(e, i));
    }

    cout << Min << endl;
    return 0;
}

