const int N = 4000 + 5;

int n , m , u , v;

struct Edge
{
    int to; Edge *nxt;
} E[N<<1] , *pre[N];

void addedge(int u , int v)
{
    static int tot = 0;
    E[++tot] = (Edge){v , pre[u]} , pre[u] = &E[tot];
    E[++tot] = (Edge){u , pre[v]} , pre[v] = &E[tot];
}

int dis[N] , sz[N] , k;
int dp[N][N] , f[N][N];

const int INF = 0x3f3f3f3f;

void dfs(int u , int fa)
{
    sz[u] = 1;
    for(Edge *i = pre[u] ; i ; i = i->nxt)
    {
        int v = i->to;
        if(v == fa) continue ;
        dfs(v , u);
        sz[u] += sz[v];
    }
    int U = 0 , S = 0;
    for(Edge *i = pre[u] ; i ; i = i->nxt)
    {
        int v = i->to;
        // if(v == fa) continue ;
        rep(j , 0 , m) f[U][j] = -INF;
        U++ , S += sz[v];
    }
    U = S = 0 , f[0][0] = 1;
    for(Edge *i = pre[u] ; i ; i = i->nxt)
    {
        int v = i->to;
        if(v == fa) continue ;
        rep(j , 0 , S)
        {
            chkmax(f[U + 1][j] , f[U][j]);
            rep(k , 0 , m - j - 1)
            {
                chkmax(f[U + 1][max(j , k + 1)] ,
                       f[U][j] + dp[v][k]);
            }
        }
        U++ , S += sz[v];
    }
    rep(i , 0 , m) dp[u][i] = f[U][i];
}

int main()
{
    read(n) , read(m);
    rep(i , 1 , n - 1)
    {
        read(u) , read(v) , addedge(u , v);
    }
    dfs(1 , 0);
    int Ans = 0;
    rep(i , 1 , n) rep(j , 0 , m)
        chkmax(Ans , dp[i][j]);
    return printf("%d\n" , n - Ans) , 0;
}

