#include<cstdio>
#include<cstring>
#include<algorithm>
#include<vector>
using namespace std;
const int N=2000;
int n,k;
vector<int> lnk[N+5];
bool del[N+5];
void DFS(int dep,int u,int pre,int &ans,int &pnt) {
	if(ans<dep) {
		ans=dep;
		pnt=u;
	}
	for(int i=0; i<lnk[u].size(); i++) {
		int v=lnk[u][i];
		if(pre==v || del[v]) continue;
		DFS(dep+1,v,u,ans,pnt);
	}
}
int GetDir(int &A,int &B) {
	int fA=0,fB=0;
	for(int i=1; i<=n; i++)
		if(!del[i]) {
			DFS(0,i,0,fA,A);
			break;
		}
	DFS(0,A,0,fB,B);
	return fB;
}
int GetSon(int u){
	int ret=0;
	for(int i=0;i<lnk[u].size();i++)
		if(!del[lnk[u][i]])
			ret++;
	return ret;
}
int main() {
	scanf("%d%d",&n,&k);
	for(int i=1; i<n; i++) {
		int u,v;
		scanf("%d%d",&u,&v);
		lnk[u].push_back(v);
		lnk[v].push_back(u);
	}
	int A,B,tot=0;
	while(GetDir(A,B)>k){
		tot++;
		int fA,fB;
		for(int i=0;i<lnk[A].size();i++)
			if(!del[lnk[A][i]]){
				fA=GetSon(lnk[A][i]);
				break;
			}
		for(int i=0;i<lnk[B].size();i++)
			if(!del[lnk[B][i]]){
				fB=GetSon(lnk[B][i]);
				break;
			}
		if(fA<fB) del[A]=true;
		else del[B]=true;
	}
	printf("%d\n",tot);
	return 0;
}

