	int cnt=0;
	if(depth>=k)cnt++;
	for(auto d:G[t]){
		if(d==f)continue;
		cnt+=dfs(d,t,k,depth+1);
	}
	return cnt;
}

int main(){
	cin >> n >> k;
	for(int i=0;i<n-1;i++){
		int a,b; cin >> a >> b;
