	for(int i=0;i<n;i++){
		int cnt=0;
		for(int t:G[i]){
			cnt+=dfs(t,i,k/2);
		}
		ans=min(ans,cnt);
	}
	for(int i=0;i<n;i++){
		for(int t:G[i]){
			int cnt=dfs(t,i,(k+1)/2)+dfs(i,t,(k+1)/2);
			ans=min(ans,cnt);
		}
	}
	cout << ans << endl;
}

