using namespace std;

int N;
vector<set<int>> roads;
vector<int> direction;

void move(int now, int back, int direction_now){
    direction[now] = direction_now;
    for(auto i = roads[now].begin(); i != roads[now].end(); i++){
        if(*i != back){
            move(*i, now, direction_now + 1);
        }
    }
}

int farthest_point(int point){
    move(point, -1, 0);
    int ans = 0;
    for(int i = 1; i < N; i++){
        if(direction[i] > direction[ans]){
            ans = i;
        }
    }
    return ans;
}

int main(){
    int K;
    cin >> N >> K;
    roads.resize(N);
    for(int i = 0; i < N - 1; i++){
        int start, goal;
        cin >> start >> goal;
        roads[start - 1].insert(goal - 1);
        roads[goal - 1].insert(start - 1);
    }
    set<int> points;
    for(int i = 0; i < N; i++){
        points.insert(i);
    }
    direction.resize(N);
    for(int i = 0; true; i++){
        int farthest = farthest_point(*points.begin());
        if(direction[farthest_point(farthest)] <= K){
            cout << i << endl;
            return 0;
        }
        points.erase(farthest);
        for(auto j = roads[farthest].begin(); j != roads[farthest].end(); j++){
            roads[*j].erase(farthest);
        }
        while(!roads[farthest].empty()){
            roads[farthest].erase(*roads[farthest].begin());
        }
    }
}

