const int MAXN = 2005;
int N, K;

int f[MAXN];
int dep[MAXN];
int wei[MAXN];
vector< int > T[MAXN];

int idx[MAXN];
set< pair< int, int > > S[MAXN];

void calc(int i, int dad = -1, int d = 0) {
  dep[i] = d;
  wei[i] = 1;

  int best = -1;

  for (int j : T[i]) {
    if (j != dad) {
      calc(j, i, d + 1);
      wei[i] += wei[j];
      if (best == -1 || wei[j] > wei[best])
	best = j;
    }
  }

  if (best == -1)
    idx[i] = i;
  else
    idx[i] = idx[best];

  int id = idx[i];

  S[id].insert({-dep[i], i});

  for (int j : T[i]) 
    if (j != dad && j != best) 
      for (auto k : S[idx[j]])
	S[id].insert(k);

  while (!S[id].empty() && -(S[id].begin()->first) > min(K, 2 * dep[i] - 2))
    S[id].erase(S[id].begin());

  f[i] = S[id].size();
}

int kill[MAXN];

void dfs(int i, int dad = -1, int killed = 0) {
  kill[i] = killed + wei[i] - 1;

  int sum = 0;

  for (int j : T[i]) 
    if (j != dad)
      sum += wei[j] - f[j];

  for (int j : T[i])
    if (j != dad)
      dfs(j, i, killed + sum - wei[j] + f[j]);
}

