int dfs(int now, int depth, vector<vector<int> >& adjlist, vector<bool>& used){
  if(depth <= 0){ return 1; }
  int count = 1;
  for(int i = 0; i < (int)adjlist[now].size(); i++){
    if(!used[adjlist[now][i]]){
      used[adjlist[now][i]] = true;
      count += dfs(adjlist[now][i], depth - 1, adjlist, used);
    }
  }
  return count;
}

