VL min(const unordered_multimap<ll, ll> graph, ll n, ll begin) {
	VL cost(n, -1);

	queue<PAIR> q;
	q.emplace(begin, 0);
	cost[begin] = 0;
	while (!q.empty()) {
		ll from = q.front().first;
		ll l = q.front().second;
		q.pop();
		auto range = graph.equal_range(from);
		REPI2(itr, range.first, range.second) {
			ll to = itr->second;
			if (cost[to] == -1) {
				cost[to] = l + 1;
				q.emplace(to, l + 1);
			}
		}
	}
	return cost;
}

signed main() {
	ll n, k;
	cin >> n >> k;
	unordered_multimap<ll, ll> graph;

	list<PAIR> od;
	REP(_, n - 1) {
		ll a, b;
		cin >> a >> b;
		--a; --b;
		od.emplace_back(a, b);
		graph.emplace(a, b);
		graph.emplace(b, a);
	}

	if (k & 1) {
		ll ans = 1e10;
		REPC(p, od) {
			auto len1 = min(graph, n, p.first);
			auto len2 = min(graph, n, p.second);
			ll tmp = 0;
			REP(j, n) if (std::min(len1[j], len2[j]) > k / 2) { ++tmp; }
			MIN(ans, tmp);
		}
		cout << ans << endl;

	} else {
		ll ans = 1e10;
		REP(i, n) {
			auto len = min(graph, n, i);
			ll tmp = 0;
			REP(j, n) if (len[j] > k / 2) { ++tmp; }
			MIN(ans, tmp);
		}
		cout << ans << endl;
	}
}

