#define MAX_V  2001       //グラフの頂点数
#define MAX_LOG_V 10        //log(頂点数)

vector<int> G[MAX_V];       //グラフの隣接リスト表現
int root;                   //グラフ(木)の根のノード番号

int parent[MAX_LOG_V][MAX_V];   //parent[k][v]:vから親を2^k回辿って到達する頂点
int depth[MAX_V];           //根からの深さ

//再帰的に初期化する
void dfs(int v,int p,int d){
    // v : 頂点
    // p : 親
    // d : 深さ
    parent[0][v]=p; //親をpにする
    depth[v]=d;     //深さd
    for(int i=0;i<G[v].size();i++){
        //隣接しているノードの内,親以外のもの(G[v][i]!=p)について
        //自分を親,深さをd+1としてdfsを呼ぶ
        if(G[v][i]!=p) dfs(G[v][i],v,d+1);
    }
}

//初期化
void init(int V){
    //parent[0],depthを初期化
    dfs(root,-1,0);     //根の親を-1,深さを0としておく
    //parentを初期化
    for(int k=0;k+1<MAX_LOG_V;k++){     //2^k回辿った親から2^(k+1)回辿った親を探す
        for(int v=0;v<V;v++){           //各ノードについて
            if(parent[k][v]<0){
                //もし2^k辿った時に根を通り過ぎるなら2^(k+1)回辿っても根を通り過ぎる
                parent[k+1][v]=-1;
            }else{
                //2^k回辿った親がt=parent[k][v]ならば2^(k+1)回辿った親はparent[k][t]
                parent[k+1][v]=parent[k][parent[k][v]];
            }
        }
    }
}

// uとvのLCAを求める
int lca(int u,int v){
    //uとvの深さが同じになるまで親を辿る
    if(depth[u]>depth[v]) swap(u,v);        // depth[u]<=depth[v]となる(vの方が深くにいる)
    for(int k=0;k<MAX_LOG_V;k++){
        //ダブリングでdepth[u]==depth[v]になるまで登る
        if((depth[v]-depth[u])>>k & 1){
            v=parent[k][v];
        }
    }
    if(u==v) return u;

    //二分探索でLCAを求める
    for(int k=MAX_LOG_V-1;k>=0;k--){
        if(parent[k][u] != parent[k][v]){
            u = parent[k][u];
            v = parent[k][v];
        }
    }
    return parent[0][u];
}

int N,K;
int main(){
    cin >> N >> K;
    root = 0;
    vector<int> a(N-1),b(N-1);
    rep(i,N-1){
        cin >> a[i] >> b[i];
        a[i]--;
        b[i]--;
        G[a[i]].push_back(b[i]);
        G[b[i]].push_back(a[i]);
    }

    rep(i,N){
        if(G[i].size()==1){
            root = i;
            break;
        }
    }
    init(N);

    queue<int> que;
    int d[2001];
    rep(i,2001) d[i] = INF;
    d[root] = 0;
    que.push(root);
    while(que.size()){
        int q=que.front();
        que.pop();

        for(int i=0;i<G[q].size();i++){
            int nx = G[q][i];
            if(d[nx]==INF){
                d[nx]=d[q]+1;
                que.push(nx);
            }
        }
    }

    ll ans = 0;
    rep(i,N) rep(j,N) if(i!=j){
        int pa = lca(i,j);
        int dd = d[i]+d[j]-d[pa];
        if(dd>K){
            cout << dd - K << endl;
            return 0;
        }
    }
    cout << ans << endl;
}

