int dfs(int curr, int par, int depth) {
  if(depth == 0) return 1;
  int ret = 1;
  for(int out: edges[curr]) {
    if(out == par) continue;
    ret += dfs(out, curr, depth-1);
  }
  return ret;
}

void solve() {
  int n, k;
