      maxIn = max(maxIn, dfs(i, -1, k/2));
    }
  }
  else {
    for(int i = 1; i <= n; i++) {
      for(int out: edges[i]) {
        maxIn = max(maxIn, dfs(i, out, k/2) + dfs(out, i, k/2));
      }
    }
  }
  cout << n - maxIn << "\n";
}

