int main() {
  int N, K;
  while (cin >> N >> K) {
    vector<vector<int>> g(N);
    for (int i : range(N - 1)) {
      int a, b;
      cin >> a >> b;
      a--;
      b--;
      g[a].push_back(b);
      g[b].push_back(a);
    }

    int res = N;
    for (int i : range(N)) {
      vector<char> vis(N, 0);
      queue<pair<int, int>> q;
      q.push({i, 0});
      int furthest = -1;
      while (!q.empty()) {
        int v = q.front().first;
        int d = q.front().second;
        q.pop();

        if (vis[v]) continue;
        vis[v] = 1;
        furthest = v;

        if (d >= K) continue;
        for (int u : g[v]) {
          if (vis[u]) continue;
          q.push({u, d + 1});
        }
      }

      int count = accumulate(vis.begin(), vis.end(), 0);
      q.push({furthest, 0});
      while (!q.empty()) {
        int v = q.front().first;
        int d = q.front().second;
        q.pop();

        if (vis[v] != 1) continue;
        vis[v] = 2;

        if (d >= K) continue;
        for (int u : g[v]) {
          if (vis[u] != 1) continue;
          q.push({u, d + 1});
        }
      }

      bool good = 1;
      for (auto v : vis) if (v == 1) good = 0;

      if (good) {
        res = min(res, N - count);
      }
    }

    cout << res << endl;
  }
}

