void shortestPath(const vector<vector<int> >& edges, int start, vector<int>& dist)
{
    int n = edges.size();
    dist.assign(n, INT_MAX);
    dist[start] = 0;
    queue<int> q;
    q.push(start);

    while(!q.empty()){
        int v = q.front();
        q.pop();
        for(unsigned i=0; i<edges[v].size(); ++i){
            int u = edges[v][i];
            if(dist[u] == INT_MAX){
                dist[u] = dist[v] + 1;
                q.push(u);
            }
        }
    }
}

void shortestPath(const vector<vector<int> >& edges, vector<vector<int> >& dist)
{
    dist.resize(edges.size());
    for(unsigned i=0; i<edges.size(); ++i)
        shortestPath(edges, i, dist[i]);
}

int main()
{
    int n, k;
    cin >> n >> k;
    vector<vector<int> > edges(n);
    for(int i=0; i<n-1; ++i){
        int a, b;
        cin >> a >> b;
        -- a;
        -- b;
        edges[a].push_back(b);
        edges[b].push_back(a);
    }

    vector<vector<int> > dist;
    shortestPath(edges, dist);

    int tmp = max_element(dist[0].begin(), dist[0].end()) - dist[0].begin();
    int diameter = *max_element(dist[tmp].begin(), dist[tmp].end());

    int ans = INT_MAX;
    for(int i=0; i<n; ++i){
        if(*max_element(dist[i].begin(), dist[i].end()) < diameter)
            continue;

        int cnt = 0;
        for(int j=0; j<n; ++j){
            if(dist[i][j] > k)
                ++ cnt;
        }
        ans = min(ans, cnt);
    }
    cout << ans << endl;

    return 0;
}

