			for (int cur = 1; cur <= k; cur++) {
				if (max_dist + cur > k) continue;
				tmp[i][max(max_dist, cur)] = min(tmp[i][max(max_dist, cur)], tmp[i - 1][max_dist] + dp[ver][cur - 1]);
			}
		}
	}
	for (int max_dist = 0; max_dist <= k; max_dist++) {
