const int INF = 1001001001;

int n, k;
vvi graph;

struct Data
{
    int p, v, h;
    bool operator< (const Data& d) const {
        return tie(p, v, h) < tie(d.p, d.v, d.h);
    }
};

map<Data, int> memo;


int func(Data d)
{
    if(memo.count(d)){
        return memo[d];
    }

    if(d.h == -1){
        return memo[d] = func({d.p, d.v, 0}) + 1;
    }

    if(d.h == 0){
        int sum = 0;
        for(int u : graph[d.v]){
            if(u == d.p) continue;
            sum += func({d.v, u, 0}) + 1;
        }
        return memo[d] = sum;
    }

    int nc = graph[d.v].size() - (d.p != -1);
    if(nc == 0){
        return memo[d] = 0;
    }

    int ans = INF;

    for(int mh = d.h-1; mh>=-1; --mh){
        int ch = k - mh - 2;

        int sum = 0;
        for(int u : graph[d.v]){
            if(u == d.p) continue;
            sum += func({d.v, u, ch});
        }

        for(int u : graph[d.v]){
            if(u == d.p) continue;
            ans = min(ans, sum - func({d.v, u, ch}) + func({d.v, u, mh}));
        }
    }

    return memo[d] = ans;
}

