int dfs(int u, int p, int d) {
    int ret = 1;
    if (d != K/2) {
        for (int v: G[u]) {
            if (v == p) continue;
            ret += dfs(v, u, d+1);
        }
    }
    return ret;
}

int solve() {
    int ret = 0;
    if (K % 2 == 0) {
        for (int u = 1; u <= N; u++)
            ret = max(ret, dfs(u, -1, 0));
