const int inf = 1e7;

int main()
{
	int n, k;
	vector<vector<int>> g;

	scanf("%d%d", &n, &k);
	g.resize(n);
	for(int i = 0; i < n - 1; ++i) {
		int a, b;
		scanf("%d%d", &a, &b);
		a -= 1; b -= 1;
		g[a].push_back(b);
		g[b].push_back(a);
	}

	bool odd = (k & 1);
	int ans = n;
	vector<pair<int,int>> dist(n);
	queue<pair<int,pair<int,int>>> q;
	vector<int> count(n);

	for(int root = 0; root < n; ++root) {

		pair<int, int> init_value = {inf, 0};
		fill(dist.begin(), dist.end(), init_value);
		q.push({root, {0, -1}});

		while(!q.empty()) {

			int v = q.front().first;
			int d = q.front().second.first;
			int b = q.front().second.second;
			q.pop();

			if(dist[v].first < inf)
				continue;
			dist[v] = {d, b};

			for(auto w : g[v]) {
				int nb = (b == -1) ? w : b;
				q.push({w, {d + 1, nb}});
			}
		}

		int base = 0;

		for(int i = 0; i < n; ++i) {
			if(dist[i].first <= k / 2)
				base += 1;
		}

		fill(count.begin(), count.end(), 0);
		for(int i = 0; i < n; ++i) {
			if(odd && dist[i].first == k / 2 + 1)
				count[dist[i].second] += 1;
		}

		int top = 0;
		for(int i = 0; i < n; ++i)
			top = max(top, count[i]);

		ans = min(ans, n - base - top);
	}

	printf("%d\n", ans);

	return 0;
}

