template<class T>
T next(istream& in) {
    T ret;
    in >> ret;
    return ret;
}


void solve(istream& in, ostream& out) {
  auto n = next<int>(in);
  auto k = next<int>(in);
  vec2d<int> g(n);
  FOR(i, n-1) {
    auto x = next<int>(in) - 1;
    auto y = next<int>(in) - 1;
    g[x].push_back(y);
    g[y].push_back(x);
  }
  vec<int> u(n, 0);
  int marked = 0;

  function<void(int, int, int)> dfs = [&] (int v, int p, int k) {
    u[v] = true;
    ++marked;
    if (k == 0) {
      return;
    }
    for (auto to : g[v]) {
      if (to != p) {
        dfs(to, v, k-1);
      }
    }
  };

  int res = n - k;
  if (k % 2 == 1) {
    FOR(i, n) {
      for (auto to : g[i]) {
        u = vec<int>(n, 0);
        marked = 0;
        dfs(to, i, k / 2);
        dfs(i, to, k / 2);
        res = min(res, n - marked);
      }
    }
  } else {
    FOR(i, n) {
      u = vec<int>(n, 0);
      marked = 0;
      dfs(i, -1, k / 2);
      res = min(res, n - marked);
    }
  }
  out << res << "\n";
}

