struct TreeDiameter {
  int u;
  vector<int> d;
  const vector<vector<int > > &T;

  TreeDiameter(vector<vector<int > > &T) : d(T.size()), T(T) {}

  int bfs(int start) {
    fill(d.begin(), d.end(), -1);
    queue<int> que;
    que.push(start);
    d[start] = 0;
    int mav = start;
    while (!que.empty()) {
      int cur = que.front(); que.pop();
      if (d[cur] > d[mav]) mav = cur;
      int sz = T[cur].size();
      for (int i = 0; i < sz; i++) {
        int nex = T[cur][i];
        int nec = 1;
        if (d[nex] != -1) continue;
        d[nex] = d[cur] + nec;
        que.push(nex);
      }
    }
    return mav;
  }

  int td(int root=0) {
    u = bfs(root);
    return bfs(u);
  }
};

void dfs(int cur, int pre) {
  forr(nex, E[cur]) {
    if (nex != pre) {
      D[nex] = D[cur] + 1;
      dfs(nex, cur);
    }
  }
}

