int bfs(vvi &adj, int s, int k, int e){

	int ret = 0;

	int dist = 0;

	queue<int> q;
	q.push(s);
	unordered_set<int> visited;

	if(e != -1) visited.insert(e);

	while(!q.empty()){

		int n = (int)q.size();

		for(int i = 0; i < n; i++){

			int curr = q.front(); q.pop();

			if(visited.count(curr)) continue;

			// cout << curr + 1 << endl;

			for(int child : adj[curr]){
				if(!visited.count(child)) q.push(child);
			}

			ret++;
			visited.insert(curr);
		}

		// cout << ret << ' ' << dist << endl;

		if(dist == k) break;

		dist++;
	}

	return ret;
}


void solve(){

	int n, k;
	cin >> n >> k;

	vpii edges(n);
	vvi adj(n);

	for(int i = 0; i < n - 1; i++){
		int u, v;
		cin >> u >> v;
		u--; v--;

		adj[u].push_back(v);
		adj[v].push_back(u);

		edges.push_back( mp(u , v) );
	}

	int maxC = 0;

	if(k % 2 == 0){

		//Each Vertex
		for(int i = 0; i < n; i++){
			int covered = bfs(adj, i, k / 2, -1);
			maxC = max(maxC, covered);
		}

	}else{

		//Each edge
		for(auto e : edges){

			int c1 = bfs(adj, e.ff , k / 2, e.ss);
			int c2 = bfs(adj, e.ss , k / 2, e.ff);

			maxC = max(maxC, c1 + c2);	

		}
	}

	cout << n - maxC << endl;

}


