    int now=0;
    for(auto s:G[e]){
        if(s==x)continue;
        int tmp=sum-v[now];
        res=max(res,1+tmp+dfs(s,e,t+1));
        now++;
    }
    return mpp[e*1e10+x*1e5+t]=res;
}
