int dfs(int node,int d,int parent=-1)
{
    if(dp[node][d]!=-1)
    {
        return dp[node][d];
    }
    dp[node][d]=MAX*3;
    if(d>0) dp[node][d]=0;
    int i,remove_it=1;
    for(i=0;i<Graph[node].size();i++)
    {
        if(Graph[node][i]==parent) continue;
        remove_it=remove_it+dfs(Graph[node][i],k,node);
        if(d>0) dp[node][d]=dp[node][d]+dfs(Graph[node][i],d-1,node);
    }
    dp[node][d]=min(dp[node][d],remove_it);
    return dp[node][d];
}
void distance_measure(int node,int d=0,int parent=-1)
{
    dist[node]=d;
    int i;
    for(i=0;i<Graph[node].size();i++)
    {
        if(Graph[node][i]==parent) continue;
        distance_measure(Graph[node][i],d+1,node);
    }
}
