int dfs(int pos, int prev, int cdep, int maxdep)
{
	subsz[pos] = 1;
	int ret = 0;
	for (int i = 0; i < G[pos].size(); ++i)
	{
		if(G[pos][i] != prev)
		{
			ret+=dfs(G[pos][i], pos, cdep+1, maxdep);
			subsz[pos]+=subsz[G[pos][i]];
		}
	}
	if(cdep > maxdep)
		return subsz[pos];
	return ret;
