int topQ;
int dist[4008];
inline void bfs()
{
	for(int k=0;k<topQ;k++)
	{
		int v=q[k];
		for(int u : g[v])
		{
			int w=dist[v]+2;
			if(dist[u]<=w)
				continue;
			dist[u]=w;
			q[topQ++]=u;
		}
	}
	return;
}
int solvedian(int v)
{
	for(int i=0;i<n;i++)
		dist[i]=INF;
	dist[v]=0;
	topQ=0;
	q[topQ++]=v;
	bfs();
	int res=0;
	for(int i=0;i<n;i++)
		if(dist[i]>k)
			res++;
	return res;
}
int solvebian(int v,int u)
{
	for(int i=0;i<n;i++)
		dist[i]=INF;
	dist[v]=dist[u]=1;
	topQ=0;
	q[topQ++]=v;
	q[topQ++]=u;
	bfs();
	int res=0;
	for(int i=0;i<n;i++)
		if(dist[i]>k)
			res++;
	return res;
}
