ll n, k;
V< V<int> > edges;

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    cin >> n >> k;
    edges.resize(n);
    for (ll i = 0; i < n - 1; i++) {
        int a, b; cin >> a >> b;
        a--, b--;
        edges[a].emplace_back(b);
        edges[b].emplace_back(a);
    }

    ll ans = HIGHINF;
    for (ll i = 0; i < n; i++) {
        vll d(n, HIGHINF); d[i] = 0;
