int main()
{
    cin.tie(nullptr); ios::sync_with_stdio(false);
    int N, K; cin >> N >> K;
    vector<vector<int>> G(N);
    for (int i = 0; i < N-1; i++) {
        int A, B; cin >> A >> B; A--, B--;
        G[A].push_back(B);
        G[B].push_back(A);
    }
    int ans = N;
    vector<bool> visited(N);
    function<void(int, int)> recur = [&](int i, int k) {
        visited[i] = true;
        if (k == 0) return;
        for (int next : G[i]) if (!visited[next]) {
            recur(next, k-1);
        }
    };
    if (K % 2 == 0) {
        for (int i = 0; i < N; i++) {
            fill(begin(visited), end(visited), false);
            visited[i] = true;
            recur(i, K/2);
            ans = min<int>(ans, N-count(begin(visited), end(visited), true));
        }
    } else {
        for (int i = 0; i < N; i++) for (int j : G[i]) if (i < j) {
            fill(begin(visited), end(visited), false);
            visited[i] = visited[j] = true;
            recur(i, K/2);
            recur(j, K/2);
            ans = min<int>(ans, N-count(begin(visited), end(visited), true));
        }
    }
    cout << ans << '\n';
    return 0;
}

