/*
<url:https://agc001.contest.atcoder.jp/tasks/agc001_c>
問題文============================================================
 N 頂点の木があり、頂点には 1~N の番号がついています。
 N−1 本の辺について、i(1≦i≦N−1) 本目の辺は頂点 Ai と頂点 Bi を繋いでいます。

 この木の直径を K 以下にするために削除する必要のある頂点数の最小値を求めてください。
 ただし、頂点を削除した後のグラフは連結になっていなければなりません。

 木の直径とは、2 つの頂点間の距離の最大値のことを指します。
 2 つの頂点間の距離とは、2 つの頂点を結ぶパスに含まれる辺の本数を指します。

 制約
 2≦N≦2000
 1≦K≦N−1
 1≦Ai≦N,1≦Bi≦N
 与えられるグラフは木である。

=================================================================

解説=============================================================

================================================================
*/

ll solve(){
    ll res = INF;
    ll N,K; cin >> N >> K;
    vector<vector<ll>> G(N);
    vector<pll> edge(N);
    for(int i = 0; i < N-1;i++){
        ll A,B; cin >> A >> B; A--; B--;
        G[A].push_back(B); G[B].push_back(A);
        edge[i] = {A,B};
    }
    queue<ll> q;
    vector<ll> dist(N,INF);
    dist[0] = 0; q.push(0);
    while(q.size()){
        ll n = q.front(); q.pop();
        for(ll next : G[n]){
            if(dist[next] > dist[n] + 1){
                dist[next] = dist[n] + 1;
                q.push(next);
            }
        }
    }
    ll _n = max_element(dist.begin(), dist.end()) - dist.begin();
    fill(dist.begin(),dist.end(),INF);
    dist[_n] = 0; q.push(_n);
    while(q.size()){
        ll n = q.front(); q.pop();
        for(ll next : G[n]){
            if(dist[next] > dist[n] + 1){
                dist[next] = dist[n] + 1;
                q.push(next);
            }
        }
    }

    if(K&1){
        for(auto& e:edge){
            vector<int> f(N,false);
            for(int i = 0; i < N;i++){
                if(abs(dist[e.first] - dist[i]) <= (K-1)/2) f[i] = true;
                if(abs(dist[e.second] - dist[i]) <= (K-1)/2) f[i] = true;
            }
            res = min(res,N - accumulate(f.begin(), f.end(), 0));
        }
    }else{
       // for(auto v:dist) cout << v << " "; cout << endl;
        for(int i = 0; i < N;i++){
            vector<int> f(N,false);
            for(int j = 0; j < N;j++){
                if(abs(dist[i]-dist[j]) <= K/2) f[j] = true;
            }
            res = min(res,N - accumulate(f.begin(),f.end(),0));
        }
    }
    return res;
}
int main(void) {
	cin.tie(0); ios::sync_with_stdio(false);
    cout << solve() << endl;
	return 0;
}

