typedef vector<int> V;
typedef vector<V> VV;
typedef pair<int, int> P;
typedef queue<P> Q;

int N, K;
VV t;

int count_node(V s, int r) {
  Q q;
  V u;
  u.resize(N);
  for (int i = 0; i < N; ++i) {
    u[i] = 0;
  }
  for (auto n : s) {
    q.push(P(n, 0));
  }
  int count = 0;
  while (!q.empty()) {
    auto p = q.front();
    q.pop();
    auto n = p.first;
    auto d = p.second;
    if (u[n]) continue;
    u[n] = 1;
    ++count;
    if (d >= r) continue;
    for (auto a : t[n]) {
      if (u[a]) continue;
      q.push(P(a, d + 1));
    }
  }
  return count;
}

int main() {
  cin >> N >> K;

  t.resize(N);
  for (int i = 0; i < N - 1; ++i) {
    int a, b;
    cin >> a >> b;
    --a, --b;
    t[a].push_back(b);
    t[b].push_back(a);
  }

  V s;
  int m = 0;
  if (K % 2 == 0) {
    s.resize(1);
    for (int i = 0; i < N; ++i) {
      s[0] = i;
      m = max(m, count_node(s, K / 2));
    }
  } else {
    s.resize(2);
    for (int i = 0; i < N; ++i) {
      s[0] = i;
      for (auto a : t[i]) {
        if (a <= i) continue;
        s[1] = a;
        m = max(m, count_node(s, K / 2));
      }
    }
  }
  cout << N - m << endl;
}

