int head[maxn],ok[maxn],alive[maxn],d[maxn];
struct node{int obj,pre,id;}e[maxn];
void insert(int x,int y,int id){
    e[++tot].obj=y; e[tot].pre=head[x]; head[x]=tot; 
    e[tot].id=id;
}
void dfs(int u,int fa){
    for (int j=head[u];j;j=e[j].pre) if (ok[e[j].id]){
        int v=e[j].obj;
        if (v==fa||!alive[v]) continue;
        d[v]=d[u]+1;
        dfs(v,u);
    }
}
int main(){
    scanf("%d%d",&n,&k);
    rep(i,2,n){
        scanf("%d%d",&x,&y);
        insert(x,y,i);
        insert(y,x,i);
        ok[i]=1;
    }
    rep(i,1,n) alive[i]=1;
    while (1){
        s=0,t=0,rt=0;
        rep(i,1,n) if (alive[i]) {s=i; break;}
        d[s]=0;
        dfs(s,0);
        rep(i,1,n) if (alive[i]&&d[i]>d[rt]) rt=i;
        /* puts("test");
        rep(i,1,n) if (alive[i]) printf("%d %d\n",i,d[i]);*/
        d[rt]=0;
        dfs(rt,0);
        rep(i,1,n) if (alive[i]&&d[i]>d[t]) t=i;
        if (d[t]<=k) break;
        for (int j=head[t];j;j=e[j].pre) ok[e[j].id]=0;
        alive[t]=0;
        ans++;
    }
    printf("%d\n",ans);
    return 0;
