typedef pair<int, int> pii;

struct edge {
    int v;
    ll w;
    edge() {}
    edge(int v, ll w) : v(v), w(w) {};
};

vector<ll> dijkstra(int n, vector<vector<edge> >& G, int s) {
    vector<ll> d(n, LLONG_MAX/10); d[s] = 0;
    priority_queue<pair<ll, int> > que;
    que.push(make_pair(0ll, s));
    while (!que.empty()) {
        auto p = que.top(); que.pop();
        int u = p.second;
        ll dist = -p.first;
        if (dist > d[u]) continue;
        for (edge e : G[u]) {
            if (d[e.v] > d[u]+e.w) {
                d[e.v] = d[u] + e.w;
                que.push(make_pair(-d[e.v], e.v));
            }
        }
    }
    return d;
}

void dfs(int v, int p, vi& vs, const vector<vector<edge> >& G) {
    vs.push_back(v);
    for (auto e : G[v]) if (e.v != p) {
        dfs(e.v, v, vs, G);
    }
}

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    int N, K;
    cin >> N >> K;
    vector<vector<edge> > G(N);
    for (int i = 0; i < N-1; i++) {
        int u, v;
        cin >> u >> v;
        u--; v--;
        G[u].emplace_back(v, 1);
        G[v].emplace_back(u, 1);
    }
    int ans = N;
    for (int i = 0; i < N; i++) if (G[i].size() == 1) {
        auto d = dijkstra(N, G, i);
        int cnt = 0;
        for (int j = 0; j < N; j++) {
            if (d[j] > K) cnt++;
        }
        ans = min(ans, cnt);
    }
    for (int i = 0; i < N; i++) if (G[i].size() > 1) {
        auto d = dijkstra(N, G, i);
        for (auto e : G[i]) {
            int ch = e.v;
            vi vs;
            dfs(ch, i, vs, G);
            int cnt = N-vs.size()-1;
            for (int v : vs) {
                if (d[v] > K) cnt++;
            }
            ans = min(ans, cnt);
        }
    }
    cout << ans << endl;
    return 0;
}

