using namespace std;
typedef long long ll;

int n, limit;

vector<int> g[2005];
bool removed[2005];
int visited[2005];
int dist[2005];
int counter;

vector<int> far;

int q[100000];
int bfs(int s) {
  ++counter;
  int qbg = 0;
  int qed = 0;
  q[qed++] = s;
  visited[s] = counter;
  int res = dist[s] = 0;
  while(qbg < qed) {
    int cur = q[qbg++];
    REP(i, g[cur].size()){
      int next = g[cur][i];
      if(!removed[next] && visited[next] != counter) {
        q[qed++] = next;
        visited[next] = counter;
        res = dist[next] = dist[cur] + 1;
      }
    }
  }
  far.clear();
  REP(i, n) {
    if(visited[i] == counter && dist[i] == res) {
      far.push_back(i);
    }
  }
  return res;
}

int main(void) {
  scanf("%d%d", &n, &limit);
  REP(i, n-1) {
    int a, b;
    scanf("%d%d", &a, &b);
    --a;
    --b;
    g[a].push_back(b);
    g[b].push_back(a);
  }

  int res = 0;
  for(;; ++res) {
    int s = 0;
    while(removed[s])
      ++s;
    bfs(s);
    int t1 = far[0];
    int d = bfs(t1);
    if(d <= limit)
      break;
    int sz1 = far.size();
    int t2 = far[0];
    bfs(t2);
    int sz2 = far.size();
    if(sz1 < sz2) {
      removed[t2] = true;
    } else {
      removed[t1] = true;
    }
  }
  cout << res << endl;

  return 0;
}

