#include <bits/stdc++.h>
using namespace std;
const int Maxn = 4000 + 100;
int Begin[Maxn], To[Maxn], Next[Maxn], e;
int Sum[Maxn], Dep[Maxn];
int N, K, Maxdep;

inline void add_edge(int x, int y)
{
	To[++e] = y;
	Next[e] = Begin[x];
	Begin[x] = e;
}

inline void dfs (int x, int fa)
{
	Maxdep = max(Maxdep, Dep[x]);
	Sum[Dep[x]] ++;
	for (int i = Begin[x]; i; i = Next[i])
	{
		int y = To[i];
		if (y == fa) continue;
		Dep[y] = Dep[x] + 1;
		dfs(y, x);
	}
}

int main()
{
#ifdef hk_cnyali
	freopen("C.in", "r", stdin);
	freopen("C.out", "w", stdout);
#endif
	scanf("%d%d", &N, &K);
	for (int i = 1; i < N; ++i)
	{
		int x, y;
		scanf("%d%d", &x, &y);
		add_edge(x, y);
		add_edge(y, x);
	}
	int Ans = 0x3f3f3f3f;
	for (int i = 1; i <= N; ++i)
	{
		memset(Sum, 0, sizeof(Sum));
		memset(Dep, 0, sizeof(Dep));
		Maxdep = 0;
		dfs(i, 0);
		int Cnt = 0;
		for (int j = K / 2 + 1; j <= Maxdep; ++j)
			Cnt += Sum[j];
		int Maxsize = 0;
		if (!(K & 1))Ans = min(Ans, Cnt);
		else 
		{
			for (int j = Begin[i]; j; j = Next[j])
			{
				int y = To[j];
				int tmp = 0;
				memset(Sum, 0, sizeof(Sum));
				memset(Dep, 0, sizeof(Dep));
				Maxdep = 0;
				dfs(i, y);
				for (int k = K / 2 + 1; k <= Maxdep; ++k)
					tmp += Sum[k];
				memset(Sum, 0, sizeof(Sum));
				memset(Dep, 0, sizeof(Dep));
				Maxdep = 0;
				dfs(y, i);
				for (int k = K / 2 + 1; k <= Maxdep; ++k)
					tmp += Sum[k];
				Ans = min(Ans, tmp);
			}
		}
	}
	cout<<Ans<<endl;
	return 0;
}

