int Count = 0;
void Find(int Now, int Fa, int Depth) {
	Vis[Now] = true; Size[Now] = 1;	
	if(Depth >= K) {  
		Ans = Min(Ans, N - Count);
		return;
	}
	for(int i = Last[Now]; i; i = Tree[i].Next) {
		int To = Tree[i].To;
		if(!Vis[To]) {	
			Count += 1; 
			Find(To, Now, Depth + 1);
			Size[Now] += Size[To];
		}
	}
}
bool Flag[MaxN];
void FindEdge(int Now, int Fa, int Depth) {
	Vis[Now] = true; Size[Now] = 1;	
	if(Depth >= K) {  
		Ans = Min(Ans, N - Count);
		return;
	}
	if(Flag[Now]) {
		Flag[Now] = false;
		Count += 1;
	}
	for(int i = Last[Now]; i; i = Tree[i].Next) {
		int To = Tree[i].To;
		if(To ^ Fa) Find(To, Now, Depth + 1);

