  for (int u : edges[v]) {
    if (u == p) continue;
    dfs(u, v);
    vector<int> ndp(sz[v] + sz[u] + 1, INF);
    ndp[sz[v] + sz[u]] = 0;
    for (int s = 0; s < sz[v]; s++) {
      for (int p = 0; p < sz[u]; p++) {
        if (mdp[u][p] + 1 + dp[s] <= diam) {
          ndp[s + p] = min(ndp[s + p], max(mdp[u][p] + 1, dp[s]));
        }
      }
      if (dp[s] <= diam) {
        ndp[s + sz[u]] = min(ndp[s + sz[u]], dp[s]); // all vertices
      }
    }
    for (int p = 0; p < sz[u]; p++) {
      if (mdp[u][p] + 1 <= diam) {
        ndp[sz[v] + p] = min(ndp[sz[v] + p], mdp[u][p] + 1);
      }
    }
    sz[v] += sz[u];
    dp = ndp;
  }
  mdp[v] = dp;
}

void solve() {
  cin >> n >> diam;
  for (int i = 0; i < n - 1; i++) {
    int v, u; cin >> v >> u;
    edges[v].push_back(u); edges[u].push_back(v);
  }
  dfs(1);
  for (int cnt = 0; cnt < mdp[1].size(); cnt++) {
    if (mdp[1][cnt] != INF) {
      cout << cnt; return;
    }
  }
}

