const int N = 2010;
int _w;

int n, k, ans;

namespace Tree {
	int head[N], nxt[N*2], to[N*2], eid;
	void init() {
		eid = 0;
		memset(head, -1, sizeof head);
	}
	void link( int u, int v ) {
		to[eid] = v, nxt[eid] = head[u], head[u] = eid++;
		to[eid] = u, nxt[eid] = head[v], head[v] = eid++;
	}
}

int f[N], g[N], fk, gk, sz[N];

void dfs( int u, int fa, int d ) {
	using namespace Tree;
	sz[u] = 1;
	f[u] = d <= fk;
	g[u] = d <= gk;
	for( int i = head[u]; ~i; i = nxt[i] ) {
		int v = to[i];
		if( v == fa ) continue;
		dfs(v, u, d+1);
		sz[u] += sz[v];
		f[u] += f[v];
		g[u] += g[v];
	}
}

int solve( int u ) {
	using namespace Tree;
	memset(f, 0, sizeof f);
	memset(g, 0, sizeof g);
	fk = gk = k/2, gk += k&1;
	int fs = 0;
	for( int i = head[u]; ~i; i = nxt[i] ) {
		int v = to[i];
		dfs(v, u, 1);
		f[v] = sz[v] - f[v];
		g[v] = sz[v] - g[v];
		fs += f[v];
	}
	int ans = fs;
	if( k & 1 )
		for( int i = head[u]; ~i; i = nxt[i] ) {
			int v = to[i];
			ans = min( ans, fs - f[v] + g[v] );
		}
	return ans;
}

int main() {
	cin >> n >> k, ans = n;
	Tree::init();
	for( int i = 0; i < n-1; ++i ) {
		int u, v;
		cin >> u >> v;
		Tree::link(u, v);
	}
	for( int i = 1; i <= n; ++i )
		ans = min( ans, solve(i) );
	printf( "%d\n", ans );
	return 0;
}

