#include<bits/stdc++.h>
#define pb push_back
using namespace std;
const int N=2005;
vector<int>v[N];
int n,m,a,b,dist[N][N];
inline bool cmp(vector<int>x,vector<int>y){return x.size()>y.size();}
void bfs()
{
    for(int i=0;i<N;i++)for(int j=0;j<N;j++)dist[i][j]=1e9;
    queue<int>q;
    for(int i=0;i<n;i++)
    {
        q.push(0);
        q.push(i);
        q.push(i);
    }
    while(!q.empty())
    {
        int move=q.front();q.pop();
        int org=q.front();q.pop();
        int now=q.front();q.pop();
        if(dist[org][now]<=move)continue;
        dist[org][now]=move;
        for(int i=0;i<v[now].size();i++)
        {
            int to=v[now][i];
            q.push(move+1);
            q.push(org);
            q.push(to);
        }
    }

}
void solve()
{
    bfs();
    int pnt=0,ans=0;
    vector<int>e[N];
    for(int i=0;i<n;i++)
        for(int j=0;j<n;j++)
            if(dist[i][j]>m)
                e[i].pb(j),pnt++;
    for(int i=0;i<n;i++)sort(e[i].begin(),e[i].end());
    while(pnt)
    {
        int MAX=0,num=-1;
        for(int i=0;i<n;i++)
        {
            if(MAX<e[i].size())
            {
                num=i;
                MAX=e[i].size();
            }
        }
        for(int i=0;i<e[num].size();i++)
        {
            int to=e[num][i];
            e[to].erase(lower_bound(e[to].begin(),e[to].end(),num));
        }
        ans++;
        pnt-=e[num].size()*2;
        e[num].clear();
    }
    cout<<ans<<endl;
    return;
}
int main()
{
    cin>>n>>m;
    for(int i=0;i<n-1;i++)
    {
        cin>>a>>b;
        a--,b--;
        v[a].pb(b);
        v[b].pb(a);
    }
    solve();
    return 0;
}

#include <bits/stdc++.h>
using namespace std;
using Int = long long;
template <typename F>
void dfs(const vector<vector<int>>& G, int i, F f, int p = -1, int d = 0)
{
    f(i, d);
    for (int next : G[i]) if (next != p) dfs(G, next, f, i, d+1);
}
int main()
{
    int N, K; cin >> N >> K;
    vector<vector<int>> G(N);
    for (int i = 0; i < N-1; i++) {
        int a, b; cin >> a >> b; a--, b--;
        G[a].push_back(b);
        G[b].push_back(a);
    }
    int s, t, maxdist, maxnode;
    vector<pair<int, int>> P(N);
    maxdist = maxnode = 0;
    dfs(G, 0, [&](int i, int d) { if (d > maxdist) maxnode = i, maxdist = d; });
    s = maxnode;
    maxdist = maxnode = 0;
    dfs(G, s, [&](int i, int d) { if (d > maxdist) maxnode = i, maxdist = d; P[i].first = d; });
    t = maxnode;
    dfs(G, t, [&](int i, int d) { P[i].second = d; });
    vector<vector<int>> S(maxdist+2, vector<int>(maxdist+2));
    for (auto &p : P) S[p.first+1][p.second+1]++;
    for (int i = 1; i < maxdist+2; i++)
        for (int j = 0; j < maxdist+2; j++)
            S[i][j] += S[i-1][j];
    for (int i = 0; i < maxdist+2; i++)
        for (int j = 1; j < maxdist+2; j++)
            S[i][j] += S[i][j-1];
    int ans = 1e9;
    for (int a = 0; a <= maxdist - K; a++) {
        // a + (K+1) + b == maxdist+1
        int b = maxdist - K - a;
        ans = min(ans, N - S[a+K+1][b+K+1]);
    }
    if (ans == 1e9) ans = 0;
    cout << ans << endl;
    return 0;
}

#include <cstdio>
#include <queue>
#include <cstring>
const int MAXN = 2005;
struct { int v, next; } e[MAXN * 2];
int cnt_edge, head[MAXN];
inline void add_edge(int u, int v) {
	e[cnt_edge] = { v, head[u] };
	head[u] = cnt_edge++;
}
int n, k, dis[MAXN];
int solve(std::queue<int> &que) {
	int cur = 0;
	while(!que.empty()) {
		int u = que.front(); que.pop();
		if(dis[u] > k / 2) cur++;
		for(int j = head[u]; j != -1; j = e[j].next) {
			if(dis[e[j].v] > dis[u] + 1) {
				dis[e[j].v] = dis[u] + 1;
				que.push(e[j].v);
			}
		}
	}
	return cur;
}
int main() {
	scanf("%d%d", &n, &k);
	memset(head, 0xff, sizeof(head));
	for(int i = 1; i < n; i++) {
		int a, b; scanf("%d%d", &a, &b);
		add_edge(--a, --b);
		add_edge(b, a);
	}
	int ans = 1e9;
	if(k % 2 == 0) {
		for(int i = 0; i < n; i++) {
			memset(dis, 0x3f, sizeof(dis));
			std::queue<int> que;
			dis[i] = 0;
			que.push(i);
			int cur = solve(que);
			if(ans > cur) ans = cur;
		}
	}
	else {
		for(int i = 0; i < cnt_edge; i += 2) {
			memset(dis, 0x3f, sizeof(dis));
			std::queue<int> que;
			dis[e[i].v] = dis[e[i + 1].v] = 0;
			que.push(e[i].v); que.push(e[i + 1].v);
			int cur = solve(que);
			if(ans > cur) ans = cur;
		}
	}
	printf("%d\n", ans);
	return 0;
}

