//return length,vertex
pii farthest(int p, int v) {
    if (deleted[v])return pii(-1, -1);
    pii res = pii(0, v);
    for (int c:G[v]) {
        if (c == p)continue;
        pii tmp = farthest(v, c);
        if (tmp.first == -1)continue;
        tmp.first += 1;
        if (tmp.first > res.first)res = tmp;
    }
    return res;
}

signed main() {
