        G[a].push_back(b);
        G[b].push_back(a);
    }
    int root = 0;
    pii p0 = farthest(-1, root);
    int u = p0.second;
    int ans = 0;
    for (;;) {
        pii p = farthest(-1, u);
        if (p.first <= K)break;
        ans++;
        int v = p.second;
        deleted[v] = true;
        if (v == root) {
            int k = 0;
            while (deleted[++k]) {}
            root = k;
            pii p2 = farthest(-1, root);
            u = p2.second;
        }
    }
    cout << ans << endl;
    return 0;
