void mergeTo(int a[], int lenA, int b[], int lenB) {
	static int res[N];
	for (int i = 0; i <= lenA; i++) {
		res[i] = a[i];
	}
	for (int x = 0; x <= lenA; x++) {
		for (int y = 0; y <= lenB && x + y + 1 <= k; y++) {
			chmax(res[max(x, y + 1)], a[x] + b[y]);
		}
	}
	for (int i = 0; i <= lenA; i++) {
		a[i] = res[i];	
	}
}

