typedef long long ll;

using namespace std;

int dfs(int me, vector<int> &visited, vector<vector<int> > &table, int left) {
    if (visited[me]==1) return 0;

    int freeSons=0;
    if (left==0) {
        for (int i=0; i<table[me].size(); i++)
            if (visited[table[me][i]]==0) freeSons++;
        return freeSons;
    }

    visited[me]=1;
    for (int i=0; i<table[me].size(); i++)
        freeSons=max(freeSons, dfs(table[me][i], visited, table, left-1));
    return freeSons;
}

int main() {
    std::ios::sync_with_stdio(false);
    int n, k; cin>>n>>k;
    vector<vector<int> > table(n);

    for (int i=0; i<n-1; i++) {
        int tmp1, tmp2; cin>>tmp1>>tmp2;
        table[tmp1-1].push_back(tmp2-1);
        table[tmp2-1].push_back(tmp1-1);
    }


    int ans=n;
    for (int i=0; i<n; i++) {
        vector<int> visited(n, 0);
        int rem=0;

        visited[i]=1;
        for (int j=0; j<table[i].size(); j++)
            rem=max(rem, dfs(table[i][j], visited, table, k/2));

        int tmp=0;
        for (int i=0; i<n; i++) if (visited[i]==0) tmp++;
        if (k%2==1) ans=min(ans, tmp-rem);
        else ans=min(ans, tmp);
    }

    cout<<ans<<endl;
    return 0;
}

