int ndp[maxn][maxn];

int k;
int h[maxn];
int sz[maxn];

void dfs(int v, int p) {
    h[v] = 0;
    sz[v] = 1;
    for (int to : g[v]) {
        if (to != p) {
            dfs(to, v);
            chmax(h[v], 1 + h[to]);
            sz[v] += sz[to];
        }
    }
}

void dfs2(int v, int p) {
    vector<int> ch;
    for (int to : g[v]) {
        if (to != p) {
            ch.pb(to);
            dfs2(to, v);
        }
    }

    if (ch.empty()) {

    } else {
        fill(dp[v], dp[v] + maxn, 0);

        dp[v][0] = sz[ch[0]];
        for (int i = 1; i <= h[v]; i++) {
            dp[v][i] = dp[ch[0]][i - 1];
        }



        for (int i = 1; i < ch.size(); i++) {
            fill(ndp[v], ndp[v] + maxn, inf);
            int to = ch[i];
            for (int j = 0; j <= h[v]; j++) {
                ndp[v][j] = dp[v][j] + sz[to];
            }

            for (int j = 0; j <= h[v]; j++) {
                for (int f = 0; f <= h[to]; f++) {
                    if (f + 1 + j <= k) {
                        chmin(ndp[v][max(f + 1, j)], dp[v][j] + dp[to][f]);
                    }
                }
            }

            for (int j = 0; j <= h[v]; j++) {
                dp[v][j] = ndp[v][j];
                if (j) {
                    dp[v][j] = min(dp[v][j - 1], dp[v][j]);
                }
            }
        }
    }
}



