#include <bits/stdc++.h>
using namespace std;

const int MAXN = 2001;

int n, max_diam;
vector<int> nxt[MAXN];
vector<pair<int, int> > edges;

bool vis[MAXN];

int get_tree_size(int v, int depth) {
    vis[v] = 1;
    int ret = 0;
    if(depth < max_diam / 2) {
        for(int w : nxt[v]) {
            if(!vis[w]) {
                ret += get_tree_size(w, depth + 1);
            }
        }
    }
    return ret + 1;
}

int main() {
    ios_base::sync_with_stdio(0);
    cin >> n >> max_diam;
    for(int i = 0; i < (n-1); i++) {
        int a, b;
        cin >> a >> b;
        edges.push_back(make_pair(a, b));
        nxt[a].push_back(b);
        nxt[b].push_back(a);
    }

    int ans = MAXN;

    if(max_diam % 2 == 0) {
        for(int v = 1; v <= n; v++) {

            for(int w = 1; w <= n; w++) vis[w] = 0;

            int a = get_tree_size(v, 0);
            ans = min(ans, n - a);
        }   
    } else {
        for(int e = 0; e < (n-1); e++) {

            for(int w = 1; w <= n; w++) vis[w] = 0;

            int v = edges[e].first,
                w = edges[e].second;

            vis[v] = vis[w] = 1;
            int av = get_tree_size(v, 0),
                aw = get_tree_size(w, 0);
            ans = min(ans, n - (av + aw));
        }
    }

    cout << ans << '\n';

    return 0;
}

