		Rep(i,0,len) f[u][i] = min(g[i]+h[min(i,k-i)],g[min(i,k-i)] + h[i]);
		Rep(i,0,len) if(k-i>len && k-i<=m) f[u][k-i] += g[i];
		Rep(i,len+1,k-len-1) f[u][i] += g[len];
	}
//	Rep(i,0,m) wri(f[u][i]);puts("");
	ans = min(ans,n - size[u] + f[u][min(k,m)]);
	//从root往上搞一格
}
