#define M 4010
#define rep(i,x,y) for(int i=(x);i<=(y);++i)
struct Edge{
	int u,v,Next;
} G[M];
int n,k;
int head[M],tot;
inline void add(int u,int v){
	G[++tot]=(Edge){u,v,head[u]};
	head[u]=tot;
}
int f[M][2010];
int g[M][2010];
inline void dfs(int x,int fa){
	for(int i=head[x];i!=-1;i=G[i].Next){
		if(G[i].v==fa)continue;
		dfs(G[i].v,x);
	}
	rep(j,0,n){
		for(int i=head[x];i!=-1;i=G[i].Next){
			if(G[i].v==fa)continue;
			g[x][j+1]+=f[G[i].v][j];
		}
	}
	f[x][0]=1;
	rep(j,1,k){
		for(int i=head[x];i!=-1;i=G[i].Next){
			if(G[i].v==fa)continue;
			int wt=min(k-j-1,j-1);
			f[x][j]=max(f[x][j],1+f[G[i].v][j-1]+g[x][wt]-(wt-1>=0?f[G[i].v][wt-1]:0));
		}
	}
	rep(i,1,k)f[x][i]=max(f[x][i-1],f[x][i]);
}
