ll dfs(ll v , ll k , ll p)
{
    if (k < 0) return 0;
    if (k == 0) return 1;

    ll sum = 1;
    for (ll i = 0; i < vertex[v].size(); i++)
    {
        if (vertex[v][i] != p)
        {
            sum += dfs(vertex[v][i] , k - 1 , v);
        }
    }

    return sum;
}

