    {
        ll res = 1 , w = 0;
        for (ll j = 0; j < vertex[i].size(); j++)
        {
            ll x = dfs(vertex[i][j] , (k / 2) - 1 , i);
            if (k & 1) w = max(w , dfs(vertex[i][j] , (k / 2) , i) - x);
            res += x;
        }
        res += w;
        ans = max(ans , res);
    }

    cout << n - ans;
}

