int cnt[N];


void dfs1(int v, int p = -1, int d = 0)
{
    dist[v] = d;
    for (int u : vertices[v])
        if (u != p)
            dfs1(u, v, d + 1);
}


void dfs2(int v, int p = -1) {
    cnt[v]++;

    for (int u : vertices[v])
        if (u != p)
        {
            dfs2(u, v);
            cnt[v] += cnt[u];
        }

    dp[v][0] = cnt[v] - 1;
    for (int i = 1; i < N; ++i)
        for (int u : vertices[v])
        {
            if (u == p)
                continue;

            dp[v][i] += dp[u][i - 1];
        }
}


