const int N = 2005;
int n, k, mx, cnt, vis[N], now;
vector<int> edge[N];

void dfs(int x, int p, int dep = 1) {
  if (dep * 2 > k) {
    cnt++;
    return ;
  }
  vis[x] = now;
  int cnt = 0;
  for (auto y: edge[x]) if (y != p) {
    dfs(y, x, dep + 1);
    cnt++;
  }
}

int main() {
  ios::sync_with_stdio(0);
  cin >> n >> k;
  for (int i = 0; i < n - 1; i++) {
    int x, y;
