    edge[x].push_back(y);
    edge[y].push_back(x);
  }
  int ans = 0;
  for (int i = 1; i <= n; i++) {
    mx = 0;
    now = vis[i] = i;
    for (auto &y: edge[i]) {
      cnt = 0;
      dfs(y, i), mx = max(mx, cnt);
    }
    int res = 0;
    for (int j = 1; j <= n; j++) if (vis[j] == i) res++;
    if (k % 2 == 0) mx = 0;
    ans = max(ans, res + mx);
  }
  cout << n - ans << endl;

  return 0;
}

