  P p;
  q.push(P(x,0));
  bool used[2000]={};
  while(!q.empty()){
    p=q.front();q.pop();
    x=p.first;
    if(used[x]) continue;
    used[x]=true;
    if(p.second>k/2) s++;
    for(int i=0;i<v[x].size();i++) q.push(P(v[x][i],p.second+1));
  }
  return s;
