	{
		int cur=q[i];
		for(int j:pos[cur])
		{
			int w=dist[cur]+2;
			if(dist[j]<=w) continue;
			dist[j]=w;
			q[sz++]=j;
		}
	}
}

inline int solveVertex(int i)
{
	fill(dist,dist+n,1e9);
	dist[i]=0;
	sz=0;

	q[sz++]=i;
	bfs();
	int sum=0;
	for(int j=0;j<n;j++) if(dist[j]>k) sum++;

	return sum;
}

inline int solveEdge(int i,int j)
{
	fill(dist,dist+n,1e9);
	dist[i]=dist[j]=1;
	sz=0;

	q[sz++]=i;
	q[sz++]=j;
	bfs();
	int sum=0;
	for(int m=0;m<n;m++) if(dist[m]>k) sum++;

	return sum;
}

