    int ret = 1;
    for (auto &n: g[cur]) {
        if (n == prev) continue;
        ret += cnt(n, cur);
    }
    return ret;
}

int solve(int cur, int prev, int dep)
{
    // cout << cur << ", " << prev << ", " << dep << endl;

    if (dep <= 0) {
        return cnt(cur, prev);
    }

    int ans = 0;

    for (int i = 0; i < g[cur].size(); i++) {
        if (g[cur][i] == prev) continue;
        ans += solve(g[cur][i], cur, dep - 1);
    }

    return ans;
}

