        for (auto lng: g[center]) {
            int tmp = 0;
            for (auto root: g[center]) {
                tmp += solve(root, center, k / 2 + ((k % 2 == 1 && lng == root) ? 1 : 0));
            }
            // cout << center + 1 << " -> " << lng + 1 << ": " << tmp << endl;
            ans = min(ans, tmp);
        }
    }

    cout << ans << endl;

