		}
		reep(i,1,K+1){
			maxs(dp[x][i],dp[y][i-1]+1);
		}
	}
	reep(j,1,h+1){
		int a = min(K-j,K/2);
		if(a<=0) break;
		for(int y:vv[x]){
			if(y==pre) continue;
			maxs(dp[x][j],dp[y][j-1]+v[a-1]-dp[y][a-1]+1);
		}
