void dfs(int v, int p = -1){
    for (int u : s[v]){
        if (u != p){
            dfs(u, v);
            for (int d = 0; d < maxn - 1; d++)
                dp[v][d + 1] += dp[u][d];
            dp[v][0] += dp[u][0] + 1;
