int dist[N][N];
bool removed[N];

int main()
{
	int n, k;
	cin >> n >> k;
	for (int i = 1; i < n; ++i) {
		int a, b;
		scanf("%d%d", &a, &b);
		edges[a].push_back(b);
		edges[b].push_back(a);
	}
	for (int i = 1; i <= n; ++i) {
		queue<int> q;
		q.push(i);
		while (!q.empty()) {
			int cur = q.front();
			q.pop();
			for (int j = 0; j < edges[cur].size(); ++j) {
				int next = edges[cur][j];
				if (!dist[i][next]) {
					dist[i][next] = dist[i][cur] + 1;
					q.push(next);
				}
			}
		}
	}
	int cnt = 0;
	priority_queue<Diameter, vector<Diameter>, less<Diameter>> q;
	for (int i = 1; i <= n; ++i) {
		for (int j = 1; j <= n; ++j) {
			q.push({dist[i][j], {i, j}});
		}
	}
	while (!q.empty() && q.top().first > k) {
		int diameter = q.top().first;
		int u = q.top().second.first;
		int v = q.top().second.second;
		q.pop();
		if (!removed[u] && !removed[v]) {
			removed[u] = true;
			++cnt;
		}
	}
	cout << cnt << endl;
	return 0;
}

