#include <bits/stdc++.h>
using namespace std;
const int Maxn = 4000 + 100;
int Begin[Maxn], To[Maxn], Next[Maxn], e;
int Sum[Maxn], Dep[Maxn];
int Son[Maxn];
int N, K, Maxdep;

inline void add_edge(int x, int y)
{
	To[++e] = y;
	Next[e] = Begin[x];
	Begin[x] = e;
}

inline void dfs (int x, int fa)
{
	Son[x] = 0;
	Maxdep = max(Maxdep, Dep[x]);
	Sum[Dep[x]] ++;
	for (int i = Begin[x]; i; i = Next[i])
	{
		int y = To[i];
		if (y == fa) continue;
		++Son[x];
		Dep[y] = Dep[x] + 1;
		dfs(y, x);
	}
}

