	{
		int x, y;
		scanf("%d%d", &x, &y);
		add_edge(x, y);
		add_edge(y, x);
	}
	int Ans = 0x3f3f3f3f;
	for (int i = 1; i <= N; ++i)
	{
		memset(Sum, 0, sizeof(Sum));
		memset(Dep, 0, sizeof(Dep));
		Maxdep = 0;
		dfs(i, 0);
		int Cnt = 0;
		for (int j = K / 2 + 1; j <= Maxdep; ++j)
			Cnt += Sum[j];
		int Maxsize = 0;
		if (K & 1)
		{
		for (int j = 1; j <= N; ++j)
			if (Dep[j] == K / 2)
				Maxsize = max (Maxsize, Son[j]);
		if (!(K / 2)) Maxsize = 1;
		//cout<<i<<" "<<Cnt<<" "<<Maxdep<<" "<<Maxsize<<endl;
//		for (int j = 1; j <= Maxdep; ++j)
//			cout<<Sum[j]<<" ";
//		cout<<endl;
		Cnt = max(0, Cnt - Maxsize);
		}
		Ans = min(Ans, Cnt);
	}
	cout<<Ans<<endl;
	return 0;
}

