int n,k;
vi g[2521];

bool used[2521];

int ans;
// height, size
vi dfs(int p){
  used[p] = true;
  vector<vi> chs;
  vi ch(1,1);
  REP(i,g[p].size()){
    int to = g[p][i];
    if(used[to])continue;
    vi tmp = dfs(to);
    if(tmp.size()+1 > ch.size()){
      ch.assign(tmp.size()+1,1);
    }
    chs.push_back(tmp);
  }
  REP(i,ch.size())ch[i]=1;
  REP(i,chs.size()){
    REP(j,ch.size()-1){
      ch[j+1] += (j < chs[i].size()) ? chs[i][j] : chs[i][chs[i].size()-1];
    }
  }
  REP(i,chs.size())REP(j,i){
    REP(x,chs[i].size())REP(y,chs[j].size()){
      if(x+y+2 > k)break;
      int lim = min(x,y);
      int cnt = ch[lim+1];
      cnt += chs[i][x] - chs[i][lim];
      cnt += chs[j][y] - chs[j][lim];
      CHMIN(ans,n-cnt);
    }
  }
  REP(i,chs.size()){
    int s = min<int>(chs[i].size(),k);
    CHMIN(ans,n-chs[i][s-1]-1);
  }
  return ch;
}

pii poi(int p){
  pii ret = pii(0,p);
  used[p]=true;
  REP(i,g[p].size()){
    int to = g[p][i];
    if(used[to])continue;
    pii tmp = poi(to);
    tmp.first += 1;
    if(tmp.first > ret.first)ret = tmp;
  }
  return ret;
}

