	G.resize(N + 1); exist.resize(N + 1, true);
	rep(i, N - 1)
	{
		G[A[i]].push_back(B[i]);
		G[B[i]].push_back(A[i]);
	}

	LL ans = 0;
	while (true)
	{
		vis.clear(); vis.resize(N + 1, false);
		depth.clear(); depth.resize(N + 1);
		vs.clear();
		maxD = 0;
		for (int i = 1; i <= N; ++i)
		{
			if (exist[i])
			{
				dfs(i, 0);
				break;
			}
		}

		std::map<LL, LL>cnt;
		auto vs_ = vs;
		vs.clear();
		maxD = 0;
		for (auto i : vs_)
		{
			vis.clear(); vis.resize(N + 1, false);
			depth.clear(); depth.resize(N + 1);
			auto prevN = vs.size();
			dfs(i, 0);
			cnt[i] += (LL)vs.size() - prevN;
		}
		for (auto i : vs) ++cnt[i];

		if (maxD <= K) break;
		++ans;

		LL max_cnt = 0, v = -1;
		for (auto i : cnt)
		{
			if (max_cnt < i.second)
			{
				max_cnt = i.second;
				v = i.first;
			}
		}
		exist[v] = false;
	}

	out << ans << std::endl;
}

