const int N = 2010;

vector<int> V[N];

int n, k;
bool f[N];
int Q[N], head, tail, dep[N], cnt, key;

void solve1(int x){
	head = tail = 0;
	Q[tail++] = x;

	cnt = 0;
	key = x;

	memset(dep, -1, sizeof(dep));
	dep[x] = 0;

    while(head < tail){
		x = Q[head++];
		if(dep[x] > dep[key]){
			key = x;
		}

		if(dep[x] > k){
			cnt++;
		}

		for(int i=0; i<V[x].size(); i++){
			int j = V[x][i];
			if(!f[j] && dep[j]==-1){
				dep[j] = dep[x] + 1;
				Q[tail++] = j;
			}
		}
    }
}

int solve(){
    int ret = 0;
    int key1, key2, cnt1, cnt2;
    bool flag;

    while(1){
		flag = 1;
    	for(int i=1; i<=n; i++){
			if(!f[i]){
				solve1(i);
				key1 = key;
				solve1(key1);
				cnt1 = cnt;
				key2 = key;

				if(dep[key2] <= k){
					flag = 0;
					break;
				}

				solve1(key2);
				cnt2 = cnt;

				if(cnt1 >= cnt2){
					f[key1] = 1;
				} else {
					f[key2] = 1;
				}

				break;
			}
    	}
    	if(!flag){
			break;
    	}
    	ret++;
    }

    return ret;
}

int main(){
	int x, y;
	while(~scanf("%d %d", &n, &k)){
		for(int i=1; i<=n; i++){
			V[i].clear();
			f[i] = 0;
		}
		for(int i=1; i<n; i++){
			scanf("%d %d", &x, &y);
			V[x].push_back(y);
			V[y].push_back(x);
		}
		if(k == n-1){
			puts("0");
		} else {
			printf("%d\n", solve());
		}
	}
	return 0;
}

