#define FO(i,a,b) for (int i = (a); i < (b); i++)
#define sz(v) int(v.size())

using namespace std;

int n, k;
vector<int> u[2005];
int ss[2005];
int f[2005][2005];
int tmp[2005];

void go(int i, int p) {
    ss[i] = 1;
    vector<int> c;
    for (int j : u[i]) if (j != p) {
        go(j, i);
        ss[i] += ss[j];
        c.push_back(j);
    }
    //printf("ss[%d]=%d\n", i, ss[i]);
    int cs = 1;
    for (int j : c) {
        int ncs = cs + ss[j];
        FO(a,0,ncs) tmp[a] = 1e9;
        FO(a,0,cs) FO(b,0,ss[j]) if (a+b+1 <= k) {
            tmp[max(a,b+1)] = min(tmp[max(a,b+1)], f[i][a]+f[j][b]);
        }
        FO(a,0,ncs) f[i][a] = min(tmp[a], f[i][a] + ss[j]);
        FO(a,1,ncs) f[i][a] = min(f[i][a], f[i][a-1]);
        cs = ncs;
    }

    //FO(j,0,ss[i]) printf("f[%d][%d]=%d\n", i+1, j, f[i][j]);
}

int main() {
    scanf("%d %d", &n, &k);
    FO(i,0,n-1) {
        int a, b; scanf("%d %d", &a, &b); a--; b--;
        u[a].push_back(b);
        u[b].push_back(a);
    }
    go(0,-1);
    int res = 1e9;
    FO(i,0,n) {
        res = min(res, f[i][ss[i]-1] + n - ss[i]);
    }
    printf("%d\n", res);
}

