int ke[maxn]={},vis[maxn]={};
int val[maxn][maxn]={};
int zz[maxn]={};
void init(int x,int y){
	e[++tot].y=y;e[tot].next=head[x];head[x]=tot;
}
void dfs(int x,int f){
	int y;dep[x]=dep[f]+1;d[x][0]=f;
	for(int i=head[x];i;i=e[i].next){
		y=e[i].y;++ke[x];
		if(y==f)continue;
		dfs(y,x);
	}
}
inline void getd(){
	mx=0;
	for(int i=1;i<=n;i<<=1){
		mx++;
		for(int j=1;j<=n;j++){
			d[j][mx]=d[d[j][mx-1]][mx-1];
		}
	}
}
int getdis(int x,int y){
	if(dep[y]<dep[x])swap(x,y);
	int z=dep[y]-dep[x];
	for(int i=1,j=0;i<=z;i<<=1,j++)
		if(i&z)
			y=d[y][j];
	if(x!=y){
		for(int i=mx;i>=0;i--){
			if(d[x][i]!=d[y][i]){
				x=d[x][i];y=d[y][i];
			}
		}
		x=d[x][0];
	}return x;
}
int main(){
	//freopen("c.in","r",stdin);
	//freopen("c.out","w",stdout);
	scanf("%d%d",&n,&k);
	int x,y,ans=0;
	for(int i=1;i<n;i++){
		scanf("%d%d",&x,&y);
		init(x,y);init(y,x);
	}
	dfs(1,1);getd();
	int w=0;
	for(int i=1;i<=n;i++){
		for(int j=i+1;j<=n;j++){
			x=getdis(i,j);
			y=dep[i]+dep[j]-2*dep[x];
			w=max(w,y);//if(y>27)cout<<y<<endl;
			if(y>k){zz[i]++;zz[j]++;}
			val[i][j]=val[j][i]=y;
		}
	}
	//for(int i=1;i<=n;i++)cout<<i<<' '<<zz[i]<<' '<<ke[i]<<endl;
	for(;;){
		y=0;
		for(int i=1;i<=n;i++){
			if(ke[i]==1&&(!vis[i])){
				if(zz[i]>y){
					x=i;y=zz[i];
				}
			}
		}vis[x]=1;
		if(y==0)break;ans++;
		for(int i=1;i<=n;i++)
			if(val[x][i]>k)zz[i]--;
		for(int i=head[x];i;i=e[i].next){
			y=e[i].y;ke[y]--;
		}
	}
	printf("%d\n",ans);
	return 0;
}
