inline void dfs(int pos,int fa)
{
	deep[pos]=deep[fa]+1;
	if(deep[pos]>(m)/2)
	sum++;
	for(int i=head[pos];i;i=edge[i].next)
	{
		int v=edge[i].to;
		if(v==fa)
		continue;
		dfs(v,pos);
	}
}
inline void dfs2(int pos,int fa)
{
	deep[pos]=deep[fa]+1;
	son[pos]=1;
	if(deep[pos]==m/2)
	maxo=0,++sumi;
	if(deep[pos]>m/2)
	sum++;
	for(int i=head[pos];i;i=edge[i].next)
	{
		int v=edge[i].to;
		if(v==fa)
		continue;
		if(deep[pos]==m/2)
		maxo++;
		dfs2(v,pos);
		son[pos]+=son[v];
	}
	if(deep[pos]==m/2)
	sumo=max(sumo,maxo);
}
