int main() {
	cin >> N>>K;
	for (int i = 0; i < N-1; i++) {
		cin >> s >> e;
		edge[s].push_back(e);
		edge[e].push_back(s);
	}
	for (int i = 1; i <= N; i++) {
		box[i] = 0;

		for (int j = 1; j <= N; j++) {
			if (i != j) {
				dis[i][j] = INT_MAX;
			}
		}
		Q.push(i);
		while (!Q.empty()) {
			f = Q.front();
			for (auto j = edge[f].begin(); j != edge[f].end(); ++j) {
				if (dis[i][*j] > dis[i][f] + 1) {
					dis[i][*j] = dis[i][f] + 1;
