bool visited[2002];

ll dfs_odd(ll now, ll depth){
    if(visited[now])return 0;
    visited[now] = true;
    if(depth > lim)d[now] = 1;
    for(int i = 0; i < graph[now].size(); i++){
        dfs_odd(graph[now][i], depth + 1);
    }
    return 0;
}

ll dfs_even(ll now, ll depth){
    if(visited[now])return 0;
    visited[now] = true;
    if(nex[now] == 1){
        parent = now;
    }
    if(depth > lim)d[now] = 1;
    if(depth == lim + 1){
        dis[parent]++;
    }
    for(int i = 0; i < graph[now].size(); i++){
        dfs_even(graph[now][i], depth + 1);
    }
    return 0;
}

