array<ll,2001>dp(ll a,ll b){
    if(l.count(p({a,b})))return l[p({a,b})];
    l[p({a,b})][0]=1;
    l[p({a,b})][1]=1;
    if(graph[b].size()==1)return l[p({a,b})];
    each(i,graph[b])if(i!=a){
        auto c=dp(b,i);
        rep(i,1,2000)l[p({a,b})][i+1]+=c[i];
    }
    return l[p({a,b})];
}
