LL dfs (vector<vector<LL> > &G, LL v, LL pre, LL K) {
    LL res = K < 0;
    for (LL i = 0; i < G[v].size(); i++) {
        if (G[v][i] == pre) continue;
        res += dfs(G, G[v][i], v, K-1);
    }
    return res;
}

void solve () {
    LL N, K;
    cin >> N >> K;
    vector<vector<LL> > G(N);
    vector<bool> leaf(N);
    for (LL i = 0; i < N-1; i++) {
        LL src, dst;
        cin >> src >> dst;
        src--; dst--;
        G[src].push_back(dst);
        G[dst].push_back(src);
    }
    for (LL i = 0; i < N; i++) leaf[i] = G[i].size() == 1;
    LL ans = INFL;
    for (LL i = 0; i < N; i++) {
        if (leaf[i]) {
            ans = min(ans, dfs(G, i, -1, K));
        }
    }
    cout << ans << endl;
}

