using namespace std;

using Graph = vector<vector<int>>;

int dfs(const Graph& g, int p, int s, int dis){
  if(dis == 0) return 1;

  int cnt = 0;
  for(int i=0; i<g[s].size(); i++){
    int nxt = g[s][i];
    if(nxt == p) continue;
    cnt += dfs(g, s, nxt, dis-1);
  }

  return cnt + 1;
}

int main(){
  int n, k; cin >> n >> k;

  Graph g(n);
  vector<pair<int, int>> e(n-1);

  for(int i=0; i<n-1; i++){
    int a, b; cin >> a >> b;
    a--, b--;

    g[a].push_back(b);
    g[b].push_back(a);

    e[i] = {a, b};
  }

  int cnt = 0;
  if(k % 2 == 0){
    for(int i=0; i<n; i++){
      cnt = max(cnt, dfs(g, -1, i, k/2));
    }
  }
  else{
    for(int i=0; i<n-1; i++){
      int l = (k-1) / 2;
      int a = e[i].first, b = e[i].second;
      cnt = max(cnt, dfs(g, a, b, l) + dfs(g, b, a, l));
    }
  }

  cout << n - cnt << endl;

  return 0;
}

