const int MAXN = 1005;
const int INF = 1e9;

int N, K, dist[MAXN];
vector<int> adjList[MAXN];

int main() {

    scanf("%d%d", &N, &K);
    for (int i = 1, u, v; i < N; i++) {
        scanf("%d%d", &u, &v);

        adjList[u].push_back(v);
        adjList[v].push_back(u);
    }

    int D = K / 2;

    int ans = INF;
    for (int i = 1; i <= N; i++) {
        memset(dist, -1, sizeof(dist)); dist[i] = 0;
        queue<int> q; q.push(i);

        int tmp = 0;
        while (!q.empty()) {
            int node = q.front(); q.pop();

            //cout << node << " " << dist[node] << endl;

            if (dist[node] > D) tmp++;

            for (int j = 0; j < adjList[node].size(); j++) {
                int neighbor = adjList[node][j];

                if (dist[neighbor] == -1) {
                    dist[neighbor] = dist[node] + 1;
                    q.push(neighbor);
                }
            }
        }

        ans = min(ans, tmp);
    }

    printf("%d\n", ans);

    return 0;
}

