using namespace std;

const int N = 2000;
struct Edge
{
	int v,nxt;
} e[(N<<1)+2];
int dp[N+3][N+3];
int f[N+3][N+3];
int sf[N+3][N+3];
int fe[N+3];
int fa[N+3];
int mx2[N+3];
int mx[N+3];
int n,m,en;

void addedge(int u,int v)
{
	en++; e[en].v = v;
	e[en].nxt = fe[u]; fe[u] = en;
}

void dfs(int u)
{
	dp[u][0] = 1; sf[u][0] = f[u][0] = 1; mx[u] = 0; mx2[u] = e[fe[u]].v==fa[u] ? 1 : 0;
	for(int i=fe[u]; i; i=e[i].nxt)
	{
		if(e[i].v==fa[u]) continue;
		fa[e[i].v] = u;
		dfs(e[i].v);
		mx2[u] = max(mx2[u],mx[u]+1+mx[e[i].v]);
		for(int j=1; j<=mx2[u]; j++)
		{
			for(int k=0; k<j; k++)
			{
				dp[u][j] = max(dp[u][j],sf[u][k]+sf[e[i].v][j-k-1]);
			}
		}
		mx[u] = max(mx[u],mx[e[i].v]+1);
		for(int j=1; j<=mx[u]; j++)
		{
			f[u][j] += f[e[i].v][j-1];
		}
		sf[u][0] = f[u][0];
		for(int j=1; j<=mx[u]; j++) sf[u][j] = sf[u][j-1]+f[u][j];
	}
//	printf("mxII[%d]=%d\n",u,mx2[u]);
//	for(int i=0; i<=mx2[u]; i++) printf("%d %d dp%d f%d\n",u,i,dp[u][i],sf[u][i]);
}

int main()
{
	scanf("%d%d",&n,&m);
	for(int i=1; i<n; i++)
	{
		int x,y; scanf("%d%d",&x,&y);
		addedge(x,y); addedge(y,x);
	}
	dfs(1);
	int ans = 0;
	for(int i=1; i<=n; i++)
	{
		for(int j=0; j<=m; j++)
		{
			ans = max(ans,dp[i][j]);
		}
	}
	ans = n-ans;
	printf("%d\n",ans);
	return 0;
}
