constexpr int INF = (1 << 30) - 1; 
int N, K;
vector < int > G[2005];
bool flag[2005];

int calcDelete(int node, int depth)
{
        if ( flag[node] ) return ( 0 );
        flag[node] = true;
        int ret = depth >= K;
        for ( auto &to : G[node] ) ret += calcDelete(to, depth + 1);
        return ( ret );
}

Pi visit(int p, int v)
{
        Pi r(0, v);
        for ( auto &to : G[v] ) {
                if ( p != to ) {
                        Pi d = visit(v, to);
                        d.first++;
                        if ( d.first > r.first ) r = d;
                }
        }
        return ( r );
}

int diameter()
{
        Pi r = visit(-1, 0);
        Pi t = visit(-1, r.second);
        return ( t.first );
}

int main()
{
        int A[2005], B[2005];
        cin >> N >> K;
        for ( int i = 0; i < N - 1; i++ ) {
                cin >> A[i] >> B[i]; --A[i], --B[i];
                G[A[i]].push_back(B[i]);
                G[B[i]].push_back(A[i]);
        }

        int minv = INF;
        if ( diameter() % 2 == 0 ) {
                for ( int root = 0; root < N; root++ ) {
                        fill_n(flag, 2005, false);
                        minv = min(minv, calcDelete(root, 0));
                }
        } else {
                for ( int i = 0; i < N - 1; i++ ) {
                        minv = min(minv, calcDelete(A[i], 1) + calcDelete(B[i], 1));
                }
        }
        cout << minv << endl;

        return ( 0 );
}

