int n, k, ans = INF;

void dfs(int r, int v, int dep)
{
	used[v] = true;
	D[v] = dep;
	REP(i, SZ(G[v]))
	{
		int to = G[v][i];
		if (!used[to]) dfs(r, to, dep + 1);
		if (v != r) S[v] += S[to];
	}
	if (dep == k / 2 + 1) S[v] = 1;
}

