int N, K;
vector<int> G[2005];

int f(int s) {
    map<int, int> dmap;
    dmap[s] = 0;

    queue<int> q;
    q.push(s);
    while (!q.empty()) {
        int t = q.front();
        q.pop();
        REP(i, G[t].size()) {
            int k = G[t][i];
            if (dmap.count(k) > 0) continue;
            dmap[k] = dmap[t] + 1;
            q.push(k);
        }
    }

    int res = 0;
    for (auto kv : dmap) {
        if (kv.second > K / 2) res++;
    }

    return res;
}

int g(pair<int, int> s) {
    map<int, int> dmap;
    dmap[s.first] = 0;
    dmap[s.second] = 0;

    queue<int> q;
    q.push(s.first);
    q.push(s.second);
    while (!q.empty()) {
        int t = q.front();
        q.pop();
        REP(i, G[t].size()) {
            int k = G[t][i];
            if (dmap.count(k) > 0) continue;
            dmap[k] = dmap[t] + 1;
            q.push(k);
        }
    }

    int res = 0;
    for (auto kv : dmap) {
        if (kv.second > (K - 1) / 2) res++;
    }

    return res;


}


