    			res += (depth[j] > k/2);
    		ans = min(ans, res);
    	}
    }
    else{
    	for(int i = 1; i <= n; i++){
    		depth[i] = 0;
    		dfs(i, 0);
    		int res = 0;
    		for(int j = 1; j <= n; j++){
    			if(depth[j] > k/2)
    				res++;
    		}
    		ans = min(ans, res);
    	}
    }
    print(ans);

    cerr << "\nTime elapsed: " << 1000 * clock() / CLOCKS_PER_SEC << "ms\n";
    return 0;
}

