    int sum = 0, mx = (int) 1e9;
    for (auto &b : kids) {
      sum += mindel[b][other];
      mx = min(mx, mindel[b][len - 1] - mindel[b][other]);
    }
    mindel[a][len] = min(mindel[a][len - 1], sum + mx);
  }
}

