            sum[i] += d[i];
    }

    vector<int> dp(k + 1, 1919810);
    rep(len, k)
    {
        rep(child_i, dps.size())
        {
            int other_len = max(0, k - len);
            upmin(dp[len + 1], dps[child_i][len] + (sum[other_len] - dps[child_i][other_len]));
        }
    }

    dp[0] = sum[0] + 1;

    if (dps.empty())
    {
        dp[0] = 1;
        dp[1] = 0;
    }

    rep(i, k)
        upmin(dp[i + 1], dp[i]);

    return dp;
}
