            queue<pll> q;
            q.push(pll(i, 0));
            while (!q.empty())
            {
                pll t = q.front();
                q.pop();
                n++;
                if (t.second >= k)
                    continue;
                REP(j, V[t.first].node.size())
                {
                    int next = V[t.first].node[j];
                    if (U[next])
                        continue;
                    U[next] = true;
                    q.push(pll(next, t.second + 1));
                }
            }
        }

        if (K % 2 == 0)
        {
            min = std::min(min, N - n);
            continue;
        }
        //! 奇数の場合には、隣のノードからk個目の数を調べる
        memset(U, 0, sizeof(U));
        U[i] = true;
        REP(j, V[i].node.size())
        {
            int p = V[i].node[j];
            U[p] = true;
            queue<pll> q;
            q.push(pll(p, 0));
            int m = 0;
            while (!q.empty())
            {
                pll t = q.front();
                q.pop();
                if (t.second == k)
                {
                    m++;
                    continue;
                }
                REP(x, V[t.first].node.size())
                {
                    int next = V[t.first].node[x];
                    if (U[next])
                        continue;
                    U[next] = true;
                    q.push(pll(next, t.second + 1));
                }
            }
            min = std::min(min, N - (n + m));
        }
    }
    cout << min << endl;
    return 0;
}

