typedef int cost_t;

class Edge {
public:
	int to;
	cost_t cost;

	Edge(){
	}

	Edge(int x,cost_t y){
		to = x;
		cost = y;
	}

	bool operator< (const Edge& x) const {
		return cost < x.cost;
	}

	bool operator> (const Edge& x) const {
		return cost > x.cost;
	}
};

