template<typename T>
WeightedGraph<T> wgraph(int N , int M = -1 ,bool is_1origin = true){
  WeightedGraph<T> g(N);
  if(M == -1) M = N - 1;
  for(int _ = 0 ; _ < M ; _++){
    int x , y; cin >> x >> y;
    T c; cin >> c;
    if(is_1origin) x-- , y--;
    g[x].eb(y , c);
    g[y].eb(x , c);
  }
  return g;
}

void solve(){
  ini(N , K);
  auto g = graph(N);

  auto dfs = [&](auto rec,int cur,int par,int rest) -> int{
    int ret = 1;
    if(rest == 0) return ret;
    each(dst , g[cur]){
      if(dst == par) continue;
      ret += rec(rec , dst , cur , rest - 1);
    }
    return ret;
  };
  trc(dfs(dfs , 0 , -1 , K));
  trc(dfs(dfs , 0 , -1 , 1));

  if(K % 2 == 0)
  {
    int nokosu = 0;
    rep(i , N){
      amax(nokosu , dfs(dfs , i , -1 , K / 2));
    }
    out(N - nokosu);
  }
  else{
    int nokosu = 0;
    each(e , nyaan){
      int cur = 0;
      cur += dfs(dfs , e.first , e.second , K / 2);
      cur += dfs(dfs , e.second, e.first  , K / 2);
      amax(nokosu , cur);
    }
    out(N - nokosu);
  }

}

