int n, k;
vector<Edge> g[2000];
set<int> st;

set<int> count(int now, int dist, int before){
    set<int> res;
    if(k < dist)    res.insert(now);
    for(auto e : g[now]){
        if(e.to != before && 0 < st.count(e.to)){
            set<int> tmp = count(e.to, dist+1, now);
            for(auto s : tmp)   res.insert(s);
        }
    }
    return res;
}

