    rep(i, n-1){
        int a, b;
        cin >> a >> b;
        g[a-1].push_back({b-1, 1});
        g[b-1].push_back({a-1, 1});
    }

    rep(i, n)   st.insert(i);

    vector<Node> vert(n);
    for(auto node : st){
        vert[node] = {node, count(node, 0, -1)};
    }

    while(true){
        priority_queue<Node> q;
        for(auto node : st){
            q.push(vert[node]);
        }

        if(q.size() == 0 || q.top().stc.size() <= 0) break;

        int del = q.top().pos;
        st.erase(del);
        for(auto node : st){
            vert[node].stc.erase(del);
        }
    }


    cout << n-st.size() << endl;



    return 0;
}

