void cal(ll w, ll x) {
    if(x == 1) { ans += 2 * w - 1; return; }
    ll t = w / x;
    if(w % x == 0) {
        ans += 2 * t * x - x;
    }
    else if(w % x != 0){
        ans += 2 * t * x;
        cal(x, w % x);
    }
}



