		for (int j = 1; j <= n; ++j) {
			if (dist[i][j] > k) {
				B[i].set(j, 1);
			}
		}
	}

	ans = n - 1;

	for (int a = 1; a <= n; ++a) {
		for (int b = a + 1; b <= n; ++b) {
			int d = dist[a][b];

			if (d != k) {
				continue;
			}

			int cur = (B[a] | B[b]).count();            
			ans = min(ans, cur);
		}	
	}

