int dfs(int now, int prev, int left) {
    if (left == 0) return 1;

    int ret = 0;
    for (int i = 0; i < next[now].size(); i++) {
	if (prev == next[now][i]) continue;
	ret += dfs(next[now][i], now, left - 1);
    }

    return ret + 1;
}

