const int N = 2020;

int n, k;
vector<int> g[N];
int maxLen[N];
int f[N][N];


void calc(int v, int p) {
	maxLen[v] = 0;
	for (int to : g[v]) {
		if (to == p) continue;
		calc(to, v);
		maxLen[v] = max(maxLen[v], maxLen[to] + 1);
	}
}

void mergeTo(int a[], int & sz, int b[], int lenB) {
	static int res[N];
	for (int i = 0, r = max(sz, lenB + 1); i <= r; i++) {
		res[i] = a[i];
	}
	for (int x = 0; x <= sz; x++) {
		for (int y = 0; y <= lenB && x + y + 1 <= k; y++) {
			chmax(res[max(x, y + 1)], a[x] + b[y]);
		}
	}
	sz = max(sz, lenB + 1);
	for (int i = 0; i <= sz; i++) {
		a[i] = res[i];	
	}
}

void dfs(int v, int p) {
	f[v][0] = 1;
	int sz = 0;
	for (int to : g[v]) {
		if (to == p) continue;
		dfs(to, v);
		mergeTo(f[v], sz, f[to], maxLen[to]);
	}
}

