const int MAXN = 2005;

int n, d, g[MAXN], to[MAXN << 1], nxt[MAXN << 1], edgeSize;

int count(int x, int fa, int lim){
	if(!lim) return 1;
	int ret = 1, p;
	for(p = g[x]; p; p = nxt[p])
		if(to[p] != fa) ret += count(to[p], x, lim - 1);
	return ret;
}
void addEdge(int u, int v){
	nxt[++ edgeSize] = g[u];
	to[g[u] = edgeSize] = v;
}
int main(){
	int i, a, b, ans = 0, p;
	scanf("%d%d", &n, &d);
	for(i = 1; i < n; ++ i){
		scanf("%d%d", &a, &b);
		addEdge(a, b), addEdge(b, a);
	}
	for(i = 1; i <= n; ++ i)
		if(d & 1)
			for(p = g[i]; p; p = nxt[p])
				ans = max(ans, count(i, to[p], d >> 1) + count(to[p], i, d >> 1));
		else ans = max(ans, count(i, -1, d >> 1));
	printf("%d\n", n - ans);
	return 0;
}

