void solve() {
  int v, u, w;
  vector <int> d(n + 1);
  for (int i = 1; i <= n; ++i) {
    if (!used[i]) {
      v = u = w = i;
      break;
    }
  }
  vector <bool> was(n + 1);
  queue <int> q;
  q.push(v);
  was[v] = 1;
  while (!q.empty()) {
    int cur = q.front();
    q.pop();
    for (auto to : g[cur]) {
      if (!was[to] && !used[to]) {
        d[to] = d[cur] + 1;
        q.push(to);
        was[to] = 1;
      }
    }
  }
  for (int i = 1; i <= n; ++i) {
    was[i] = 0;
    if (d[i] > d[u])
      u = i;
  }
  q.push(u);
  was[u] = 1;
  d[u] = 0;
  while (!q.empty()) {
    int cur = q.front();
    q.pop();
    for (auto to : g[cur]) {
      if (!was[to] && !used[to]) {
        d[to] = d[cur] + 1;
        q.push(to);
        was[to] = 1;
      }
    }
  }
  int distance = d[w];
  for (int i = 1; i <= n; ++i) {
    if (d[i] > d[w]) {
      w = i;
      distance = d[i];
    }
  }
  if (distance < k) {
    cout << ret;
    exit(0);
  }
  used[w] = 1;
  ++ret;
}

