void solve(int n, int k, int now, int parent) {
  for (auto nxt : G[now]) {
    if (nxt == parent) continue;
    solve(n, k, nxt, now);
  }
  for (int i = 0; i <= (k - 1) / 2; i ++) {
    int sum = 0;
    int diff_max = 0;
    for (auto nxt : G[now]) {
      sum += dp[nxt][i];
      diff_max = max(diff_max, dp[nxt][k-1-i] - dp[nxt][i]);
    }
    dp[now][i+1] = sum + 1;
    dp[now][k-i] = sum + diff_max + 1;
    best = max(best, sum + diff_max + 1);
  }
}

