		for(int j=0;j<k;j++)
		{
			tmp[j+1]+=f[v][j];
			if(j==k-1) f[u][j+1]=max(f[u][j+1],f[v][j]);
			else if(2*(j+1)>k) f[u][j+1]=max(f[u][j+1],f[v][j]-f[v][k-j-2]);
		}
	}
	for(int j=0;j<=k;j++)
	{
		if(2*j<=k) f[u][j]=tmp[j]+1;
