vector<int> ShortestPathTree(const vector<vector<int>>& g, int s) {
	int V = g.size();
	vector<int> dist(V);
	function<void(int, int, int)> dfs = [&](int v, int p, int depth) {
		dist[v] = depth;
		for (int e : g[v])if (e != p) {
			dfs(e, v, depth + 1);
		}
	};
	dfs(s, -1, 0);
	return dist;
}

int main() {
	ini(n, k);
	VVI g(n);
	VP edges(n - 1);
	rep(i, n - 1) {
		int a = in--, b = in--;
		g[a].push_back(b);
		g[b].push_back(a);
		edges[i] = make_pair(a, b);
	}

	int ans = n;

	if (k % 2 == 0) {
		rep(i, n) {
			VI dist = ShortestPathTree(g, i);
			int cnt = CountIf(dist, [&](int x) {return x > k / 2; });
			chmin(ans, cnt);
		}
	} else {
		rep(i, n - 1) {
			VI d1 = ShortestPathTree(g, edges[i].first);
			VI d2 = ShortestPathTree(g, edges[i].second);
			int cnt = step(n).count_if([&](int i) {return min(d1[i], d2[i]) > k / 2; });
			chmin(ans, cnt);
		}
	}

	out(ans);
}

