#include <bits/stdc++.h>

const int MAXN = 2000 + 10;

std::vector<int> G[MAXN];
int dis[MAXN], sz[MAXN], ht[MAXN];
int valid[MAXN];
int n, m;

int get_diameter() {
  std::queue<int> Q;
  for (int i = 0; i < n; ++i) dis[i] = -1;
  Q.push(0);
  dis[0] = 0;
  while (!Q.empty()) {
    int u = Q.front();
    Q.pop();
    for (auto &&v: G[u]) {
      if (dis[v] == -1) {
        dis[v] = dis[u] + 1;
        Q.push(v);
      }
    }
  }
  int src = 0;
  for (int i = 0; i < n; ++i) {
    if (dis[src] < dis[i]) src = i;
  }
  for (int i = 0; i < n; ++i) dis[i] = -1;
  Q.push(src);
  dis[src] = 0;
  while (!Q.empty()) {
    int u = Q.front();
    Q.pop();
    for (auto &&v: G[u]) {
      if (dis[v] == -1) {
        dis[v] = dis[u] + 1;
        Q.push(v);
      }
    }
  }
  for (int i = 0; i < n; ++i) {
    if (dis[src] < dis[i]) src = i;
  }
  return dis[src];
}

void dfs(int u, int f = -1, int d = 0) {
  dis[u] = d;
  sz[u] = 1;
  ht[u] = 0;
  for (auto &&v: G[u]) {
    if (v != f) {
      dfs(v, u, d + 1);
      sz[u] += sz[v];
      ht[u] = std::max(ht[u], ht[v] + 1);
    }
  }
}

int dfs_lim(int u, int f, int lim) {
  if (dis[u] > lim) return 0;
  int ret = 1;
  for (auto &&v: G[u]) {
    if (v != f) ret += dfs_lim(v, u, lim);
  }
  return ret;
}

int solve(int rt) {
  dfs(rt);
  for (auto &&u: G[rt]) {
    valid[u] = dfs_lim(u, rt, m / 2);
  }
  int x = (m + 1) / 2, y = m / 2;
  int ret = n;
  for (auto &&u: G[rt]) {
    if (ht[u] < x) continue;
    int now = dfs_lim(u, rt, x);
    bool flag = false;
    for (auto &&v: G[rt]) {
      if (u == v) continue;
      if (ht[v] + 1 >= y) flag = true;
      now += valid[v];
    }
    if (!flag) continue;
    ret = std::min(ret, n - now - 1);
  }
  return ret;
}

void run() {
  std::cin >> n >> m;
  for (int i = 1; i < n; ++i) {
    int u, v;
    std::cin >> u >> v;
    --u, --v;
    G[u].push_back(v);
    G[v].push_back(u);
  }
  int dia = get_diameter();
  int ret = n;
  if (dia <= m) ret = 0;
  for (int i = 0; i < n; ++i) {
    ret = std::min(ret, solve(i));
  }
  printf("%d\n", ret);
}

int main() {
  run();
  return 0;
}

