bool flag[2001] = {};
queue<int>Q;
int f;
int box[2001];
int bag;
int ans;

int main() {
	cin >> N>>K;
	for (int i = 1; i <= N; i++) {
		flag[i] = true;
	}
	for (int i = 0; i < N-1; i++) {
		cin >> s >> e;
		edge[s].push_back(e);
		edge[e].push_back(s);
	}
	while(1){
		for (int i = 1; i <= N; i++) {
			box[i] = 0;
			if (flag[i]) {

				for (int j = 1; j <= N; j++) {
					if (i != j) {
						dis[i][j] = INT_MAX;
					}
				}
				Q.push(i);
				while (!Q.empty()) {
					f = Q.front();
					for (auto j = edge[f].begin(); j != edge[f].end(); ++j) {
						if (flag[*j]) {
							if (dis[i][*j] > dis[i][f] + 1) {
								dis[i][*j] = dis[i][f] + 1;
								Q.push(*j);
								if (dis[i][*j] > K) {
									box[i]++;
								}
							}
						}
					}
					Q.pop();
				}
				if (box[i])bag++;
			}
		}
		bag = 0;
		for (int i = 1; i <= N; i++) {
			bag = max(bag, box[i]);
		}
		if (bag) {
			ans++;
			for (int i = 1; i <= N; i++) {
				if (box[i] == bag) {
					flag[i] = false;
					break;
				}
			}
		}
		else break;
	}
	cout << ans << endl;
	return 0;
}

