using namespace std;

typedef long long int64;
typedef long double ld;
typedef unsigned long long lint;

const int inf = (1 << 30) - 1;
const int64 linf = (1ll << 62) - 1;
const int N = 3001;

int n, k;
vector<int> g[N];
int dp[N][N];
int sz[N], h[N];

inline void dfs(int v, int p = -1) {
    sz[v] = 1;
    h[v] = 0;
    for (int to : g[v]) {
        if (to == p) {
            continue;
        }
        dfs(to, v);
        sz[v] += sz[to];
        h[v] = max(h[v], h[to] + 1);
    }
    if (p != -1 && len(g[v]) == 1) {
        for (int i = 1; i <= k; i++) {
            dp[v][i] = 0;
        }
        dp[v][0] = sz[v];
        return ;
    }
    dp[v][0] = sz[v];
    for (int i = 0; i <= k; i++) {
        int sum = 0, mn = inf;
        int mx = min(k - i, i);
        for (int to : g[v]) {
            if (to == p) {
                continue;
            }
            sum += dp[to][mx - 1 + 1];
            mn = min(mn, dp[to][i - 1 + 1] - dp[to][mx - 1 + 1]);
        }
        dp[v][i + 1] = min(dp[v][i], sum + mn);
    }
}

int main() {
