        int a, b; scanf("%d%d", &a, &b), a--, b--;
        g[a].pb(b), g[b].pb(a);
    }
    int ans = inf;
    for (int it = 0; it < 10; it++) {
        int root = rand() % n;
        dfs(root);
        ans = min(ans, dp[root][k + 1]);
    }
    cout << ans << endl;
    return 0;
}

