int bfs(vector<vector<int>> &E,int start,int next,int K){
	vector<int> dis(E.size(),Inf);
	dis[start] = 0;
	dis[next] = 1;
	queue<int> que;
	que.push(next);
	while(que.size()!=0){
		int now = que.front();
		que.pop();
		for(int i=0;i<E[now].size();i++){
			int to = E[now][i];
			if(dis[to]!=Inf)continue;
			if(dis[now]==K)continue;
			dis[to] = dis[now] + 1;
			que.push(to);
		}
	}

	int cnt = 0;
	for(int i=0;i<E.size();i++){
		if(dis[i]<=K)cnt++;
	}

	return cnt;
}




