bool upper(int a, int b){
      return tin[a] <= tin[b] && tout[a] >= tout[b];
}

int lca(int a, int b){
      if(upper(a, b)) return a;
      if(upper(b, a)) return b;
      for(int i = 11; i >= 0; i --){
            if(!upper(p[i][a], b) && p[i][a]) a = p[i][a];
      }
      return p[0][a];
}

int dist(int a, int b){
      return (d[a] + d[b]) - d[lca(a, b)] * 2;
}

