int dfs(int v,int p,int h){
	if(h>K/2)return 0;
	int ret = 1;
	for(int u:path[v]){
		if(u==p)continue;
		ret += dfs(u,v,h+1);
	}
	return ret;
}

void solve(){
	int ans = 0;

