		for(int i=1;i<=N;i++){
			ans = max(ans, dfs(i,i,0));
		}
	}else{
		for(int v=1;v<=N;v++){
			for(int u:path[v]){
				ans = max(ans, dfs(u,v,0)+dfs(v,u,0));
			}
		}
	}
	cout << N - ans << endl;
}

