void addedge(int u,int v){
    node &p=edge[++ecnt];
    p.v=v;
    p.nex=head[u];
    head[u]=ecnt;
}

int dfs(int u,int fa=0){
    dep[u]=dep[fa]+1;
    siz[u]=1;
    int cnt=0,t=0,sum=0;
    for(int i=head[u];i;i=edge[i].nex){
        int v=edge[i].v;
        if(v==fa) continue;
        t=dfs(v,u);
        if(fa==0) extra=max(extra,t);
        sum+=t;
        siz[u]+=siz[v];
        if((K&1)&&dep[u]==K/2) cnt++;
    }
    if(fa==0&&!(K/2)) extra=max(extra,1);
    if(dep[u]==K/2+1) now+=siz[u];
    return sum+cnt;
}

