void f(int deep,int p,int oya){
	for(int i=0;i<vec[p].size();i++){
		int p2=vec[p][i];
		if(p2==oya)continue;
		f(deep+1,p2,p);
		for(int j=0;j<n;j++){
			cs2[p][j+1]+=cs2[p2][j];
		}
	}
	cs2[p][0]=1;
