void g(int deep,int p,int oya){
	if(deep==0){
		memcpy(cs3[1],cs2[1],sizeof(cs3[1]));
	}else{
		for(int i=0;i<n;i++){
			cs3[p][i+1]=cs3[oya][i]+cs2[p][i+1];
		}
		cs3[p][0]=1;
	}

	for(int i=0;i<vec[p].size();i++){
		int p2=vec[p][i];
		if(p2==oya)continue;
		for(int j=1;j<=n;j++){
			cs3[p][j]-=cs2[p2][j-1];
		}
		//printf("b<%d %d>",p,p2);
