			L+=cs2[p2][j];
			R+=cs3[p][j];
			sumL[j]=L;
			sumR[j]=R;
		}

		//printf("\n%d %d\n",p,p2);
		//printf("<%d>",sumL[k]);
		if(sumL[k-1]>ans){	
			ans=sumL[k];
		}

		for(int j=k-2;j>=0;j--){
			int LR=sumL[j]+sumR[k-j-2];
			//printf(" %d ",LR);
			if(ans<LR){
				ans=LR;
			}
		}
