  vector<vector<pair<int, T> > > edge;
  vector<T> dis;
  Graph(int n): n(n) {
    edge.resize(n);
    dis.resize(n);
  }
  void dijkstra(int s){
    dijkstra(s, 0);
  }
  T dijkstra(int s, int t){
    // initialize
    fill(dis.begin(), dis.end(), -1);
    vector<bool> used(n, false);
    dis[s] = 0;
    // dijkstra
    priority_queue<pair<T, int>, vector<pair<T, int> >, greater<pair<T, int> > > q;
    q.push(make_pair(0, s));
    while(!q.empty()){
      pair<T, int> p = q.top(); q.pop();
      int at = p.second;
      T distance = p.first;
      if(used[at])continue;
      used[at] = true;
      for(auto itr = edge[at].begin(); itr != edge[at].end(); ++itr){
        int to = (*itr).first;
        T cost = (*itr).second;
        if(used[to])continue;
        if(dis[to] == -1 || dis[to] > distance + cost){
          q.push(make_pair(distance + cost, to));
          dis[to] = distance + cost;
        }
      }
    }
    return dis[t];
  }
  void adde(int at, int to, T cost){
    edge[at].push_back(make_pair(to, cost));
  }
  [[deprecated("This function takes O(|edge[at]|).")]]
  void remove(int at, int to){
    int index = -1;
    for(int i = 0; i < edge[at].size(); i++){
      if(edge[at][i].first == to){
        index = i;
        break;
      }
    }
    edge[at].erase(edge[at].begin() + index);
  }
};

using GraphI = Graph<int>;
using GraphL = Graph<ll>;
using GraphD = Graph<double>;

int u[2010], v[2010];

int main(int argc, char const* argv[])
{
  int n, k; cin >> n >> k;
  GraphI g(n);
  rep(i, n - 1){
    int a, b; cin >> a >> b; a--; b--;
    g.adde(a, b, 1);
    g.adde(b, a, 1);
    u[i] = a, v[i] = b;
  }
  int res = inf;
  if(k & 1){
    rep(i, n - 1){
      g.dijkstra(u[i]); vector<int> vu = g.dis;
      g.dijkstra(v[i]); vector<int> vv = g.dis;
      int sum = 0;
      rep(j, n){
        if(vu[j] > k / 2 && vv[j] > k / 2)++sum;
        chmin(res, sum);
      }
    }
  }else{
    rep(i, n){
      g.dijkstra(i);
      int sum = 0;
      rep(j, n){
        if(g.dis[j] > k / 2)++sum;
      }
      chmin(res, sum);
    }
  }
  cout << res << endl;
  return 0;
}

#include <bits/stdc++.h>
using namespace std;

vector<int> edg[2005];
vector<int> ch[2005];
int cac[2005][2005];
int n, k, ans;

void dfs(int at, int par=-1)
{
	for (int u: edg[at]) if (u != par)
	{
		ch[at].push_back(u);
		dfs(u, at);
	}
}

int slv(int at, int far)
{
	if (cac[at][far]) return cac[at][far];
	if (far == 0) return cac[at][far]=1;
	if (ch[at].size() >= 1) for (int u: ch[at])
		cac[at][far] = max(cac[at][far], slv(u, far-1));
	if (ch[at].size() >= 2) for (int a = 0;a < far;a++)
	{
		int b = min(far, k-a-1)-1;
		if (b >= 0)
		{
			int t1 = 0, w1 = -1, t2 = 0;
			for (int u: ch[at])
			{
				int alt = slv(u, b);
				if (alt > t1)
				{
					t2 = t1;
					t1 = alt; w1 = u;
				} else if (alt > t2)
					t2 = alt;
			}
			for (int u: ch[at])
			{
				int alt = slv(u, a);
				if (u == w1) alt += t2;
				else alt += t1;
				if (alt > cac[at][far]) cac[at][far] = alt;
			}
		}
	}
	if (ch[at].size() >= 3) for (int giv = 0;giv < far;giv++)
	{
		if (giv+giv+2 > k) break;
		int tot = 0;
		for (int u: ch[at]) tot += slv(u, giv);
		int here = min(far, k-giv-1)-1;
		if (here >= 0) for (int u: ch[at])
		{
			int alt = tot;
			alt -= slv(u, giv);
			alt += slv(u, here);
			cac[at][far] = max(cac[at][far], alt);
		}
	}
	return ++cac[at][far];
}

int main()
{
	scanf("%d%d", &n, &k);
	for (int i = 1;i < n;i++)
	{
		int a, b; scanf("%d%d", &a, &b);
		--a, --b;
		edg[a].push_back(b);
		edg[b].push_back(a);
	}
	dfs(0);
	for (int i = 0;i < n;i++)
		ans = max(ans, slv(i, k));
	printf("%d\n", n-ans);
	return 0;
}

