ll const MAX = 5005;
vll v[MAX];

ll dist[MAX];
ll fr[MAX];
ll stk[MAX];

ll f(ll start, ll n, ll k) {
	REP(i, 1, n) {
		dist[i] = -1;
		fr[i] = -1;
		stk[i] = 0;
	}
	queue<ll> qu;
	qu.push(start);
	dist[start] = 0;
	REP(i, 0, SIZE(v[start])-1) {
		ll nbd = v[start][i];
		fr[nbd] = nbd;
	}
	ll ans = 1;
	while (!qu.empty()) {
		ll cur = qu.front();
		qu.pop();
		REP(i, 0, SIZE(v[cur]) - 1) {
			ll next = v[cur][i];
			if (dist[next] == -1) {
				dist[next] = dist[cur] + 1;
				if (fr[cur] != -1) {
					fr[next] = fr[cur];
				}
				if (dist[next] <= k / 2) {
					ans++;
					qu.push(next);
				}
				if (dist[next] == k / 2 + 1) {
					stk[fr[cur]]++;
				}
			}
		}
	}
	ll mos = 0;
	if(k % 2 == 1) {
		REP(i, 1, n) {
			mos = max(mos, stk[i]);
		}
	}
	//cout << start << " " << ans + mos << endl;
	return ans + mos;
}

int main(){
	ll n, k;
	cin >> n >> k;
	REP(i, 1, n - 1) {
		ll a, b;
		cin >> a >> b;
		v[a].push_back(b);
		v[b].push_back(a);
	}
	ll max_v = -1;
	REP(i, 1, n) {
		ll t = f(i, n,k);
		max_v = max(max_v, t);
	}
	cout << n - max_v << endl;
}

