#define REP(i,a) FOR(i,0,a)

using namespace std;

const int MAX_N=2000,INF=1e8;

typedef pair<int,int> P;

int N,K;
P edge[MAX_N];
vector<int> G[MAX_N];

int d[MAX_N];
bool used[MAX_N];

void bfs(int s){
	fill(used,used+N,false);
	d[s]=0;
	used[s]=true;
	queue<int> q;
	q.push(s);
	while (!q.empty()){
		int v=q.front();
		q.pop();
		REP(i,G[v].size()){
			int to=G[v][i];
			if (!used[to]){
				used[to]=true;
				d[to]=d[v]+1;
				q.push(to);
			}
		}
	}
}

void bfs(int s,int t){
	fill(used,used+N,false);
	d[s]=0;
	d[t]=0;
	used[s]=used[t]=true;
	queue<int> q;
	q.push(s);
	q.push(t);
	while (!q.empty()){
		int v=q.front();
		q.pop();
		REP(i,G[v].size()){
			int to=G[v][i];
			if (!used[to]){
				used[to]=true;
				d[to]=d[v]+1;
				q.push(to);
			}
		}
	}
}

