				if (d[j]>K/2){
					s++;
				}
			}
			ans=min(ans,s);
		}
	}else{
		REP(i,N-1){
			bfs(edge[i].first,edge[i].second);
			int s=0;
			REP(j,N){
				if (d[j]>(K-1)/2){
					s++;
				}
