class Edges{
public:
	int next , to;
};
Edges edge[MAXN * 2];
int n , k , te = 0;
void add(int s , int t){
	++ te;
	edge[te].to = t;
	edge[te].next = first[s];
	first[s] = te;
}
void dfs(int x , int y){
	for(int e = first[x] ; e ; e = edge[e].next){
		int to = edge[e].to;
		if(to == y) continue;
		dfs(to , x);
	}
	int cnt = 0;
	for(int e = first[x] ; e ; e = edge[e].next){
		int to = edge[e].to;
		if(to == y) continue;
		son[++ cnt] = to;
		dep[x] = max(dep[to] + 1 , dep[x]);
	}
	if(!cnt){
		dep[x] = 1;
		f[x][0] = 0;
		for(int i = 1 ; i <= k + 1 ; ++ i)
			f[x][i] = 1;
		return ;
	}
	f[x][0] = 0;
	f[x][1] = 1;
	int cur = 1;
	for(int i = 2 ; 2 * i <= k + 2 && i <= dep[x] ; ++ i){
		cur = i;
		f[x][i] = 0;
		for(int j = 1 ; j <= cnt ; ++ j)
			f[x][i] += f[son[j]][i - 1];
		f[x][i] ++;
	}
	for(int i = cur + 1 ; i <= k + 1 && i <= dep[x] ; ++ i){
		int sum = 0 , maxn = -(n + 1);
		for(int j = 1 ; j <= cnt ; ++ j){
			sum += f[son[j]][k + 1 - i];
			if(f[son[j]][i - 1] - f[son[j]][k + 1 - i] >= maxn) maxn = f[son[j]][i - 1] - f[son[j]][k + 1 - i];
		}
		f[x][i] = sum + maxn + 1;
	}
	for(int i = 2 ; i <= k + 1 ; ++ i)
		f[x][i] = max(f[x][i] , f[x][i - 1]);
}
int main(){
	cin >> n >> k;
	for(int i = 1 ; i < n ; ++ i){
		int x , y;
		cin >> x >> y;
		add(x , y);
		add(y , x);
	}
	dfs(1 , 0);
	int ans = 0;
	for(int i = 1 ; i <= n ; ++ i)
		for(int j = 1 ; j <= k + 1 ; ++ j)
			ans = max(ans , f[i][j]);
	cout << n - ans << endl;
	return 0;
}

