		to = g[v][i];
		if (to == pr || used[to])
			continue;
		check1(to, cur + 1, v);
	}
}

void check2(int v = 1, int cur = 0, int pr = 0) {
	if (cur == d2 && v != id1) {
		++cnt[v];
		++cnt[id2];
	}
	for (int i = 0, to; i < g[v].size(); ++i) {
		to = g[v][i];
		if (to == pr || used[to])
