const int MAX = 2000;
vector<int> G[MAX];

int get_size(int v, int prev) {
	int res = 1;
	for (auto to : G[v]) if (to != prev) {
		res += get_size(to, v);
	}
	return res;
}

int calc(int v, int prev, int K, int d = 1) {
	int res = d > K;
	for (auto to : G[v]) if (to != prev) {
		res += calc(to, v, K, d + 1);
	}
	return res;
}

int main()
{
	int N, K;
