		G[A].push_back(B);
		G[B].push_back(A);
	}
	int res = N;
	for (int i = 0; i < N; i++) {
		for (auto to : G[i]) {
			int val = N - 1 - get_size(to, i);
			val += calc(to, i, K);
			res = min(res, val);
		}
	}
	cout << res << endl;
	return 0;
}

