const int MAX = 2000 + 47;

int U[MAX];
vector<int> g[MAX];
int n, k;
int cnt = 0;

void fill(int A[], int val)
{
	FOR(i, 0, MAX) A[i] = val;
}

void dfs(int v, int d)
{
	if (d > k / 2) return;
	//cout << "*" << v + 1 << ": " << d << endl;
	cnt++;
	U[v] = 1;

	FOR(i, 0, SZ(g[v]))
	{
		int to = g[v][i];
		if (!U[to]) dfs(to, d + 1);
	}
}

int calc(int i)
{
	fill(U, 0);
	cnt = 0;
	dfs(i, 0);
	//cout << "?? " << i + 1 << " " << cnt << endl;
	int maxx = 0;
	int ind = -1;
	if (k % 2)
	{
		FOR(j, 0, n)
		{
			if (U[j])
			{
				int c = 0;
				FOR(k, 0, SZ(g[j]))
				{
					if (!U[g[j][k]])
					{
						c++;
					}
				}

				if (maxx < c)
				{
					maxx = c;
					ind = j;
				}
			}
		}

		FOR(i, 0, SZ(g[ind])) U[g[ind][i]] = 1;
	}

	return cnt + maxx;
}

int D[MAX];

void dfs1(int v, int p, int d)
{
	D[v] = d;
	FOR(i, 0, SZ(g[v]))
	{
		int to = g[v][i];
		if (U[to] && D[to] == -1) dfs1(to, v, d + 1);
	}
}

bool check(int v)
{
	fill(D, -1);
	dfs1(v, -1, 0);
	int maxx = v;
	FOR(i, 0, n)
	{
		if (D[i] > D[maxx]) maxx = i;
	}

	FILL(D, -1);
	dfs1(maxx, -1, 0);
	FOR(i, 0, n)
	{
		if (D[i] > D[maxx]) maxx = i;
	}

	if (D[maxx] <= k) return true;
	return false;
}

int main()
{
	//freopen("in.txt", "r", stdin);
	//freopen("out.txt", "w", stdout);
	ios::sync_with_stdio(false); cin.tie(0);
	cin >> n >> k;
	FOR(i, 0, n - 1)
	{
		int a, b;
		cin >> a >> b;
		a--;
		b--;
		g[a].push_back(b);
		g[b].push_back(a);
	}

	if (k == 1)
	{
		cout << n - 2 << endl;
		return 0;
	}

	int ans = INF;
	int ind = -1;
	FOR(i, 0, n)
	{
		int cnt = calc(i);
		if (ans > n - cnt)
		{
			ans = n - cnt;
			ind = i;
		}
	}

	calc(ind);
	if (!check(ind))
	{
		//cout << "-------------" << endl;
		throw - 1;
	}

	cout << ans << endl;
}

