int n;
int k;
bool judge;
vvi lst;

P solve(int a, int to, int from, int d) {
	P ret = { 0, -1 };
	vi ds;
	if (d > k) ret.fst++;
	else ret.snd = d;
	if (to != -1) {
		Foreach(b, lst[a]) {
			if (b != to) {
				P buf = solve(b, -1, a, n);
				ret.fst += buf.fst;
			}
		}
		P buf = solve(to, -1, a, d + 1);
		ret.fst += buf.fst;
		if (buf.snd != -1) {
			ret.snd = max(ret.snd, buf.snd);
			ds.push_back(buf.snd);
		}
	}
	else {
		Foreach(b, lst[a]) {
			if (b != from) {
				P buf = solve(b, -1, a, d + 1);
				ret.fst += buf.fst;
				if (buf.snd != -1) {
					ret.snd = max(ret.snd, buf.snd);
					ds.push_back(buf.snd);
				}
			}
		}
	}
	sort(ds.begin(), ds.end(), greater<int>());
	if (ds.size() >= 2) {
		if (ds[0] - d + ds[1] - d > k) judge = false;
	}
	return ret;
}

int main() {
	quickio();
	cin >> n >> k;
	lst = vvi(n);
	Loop(i, n - 1) {
		int s, t; cin >> s >> t; s--; t--;
		lst[s].push_back(t);
		lst[t].push_back(s);
	}
	int ans = INT_MAX;
	Loop(i, n) {
		Foreach(b, lst[i]) {
			judge = true;
			int buf = solve(i, b, -1, 0).fst;
			if (judge) ans = min(ans, buf);
		}
	}
	cout << ans << endl;
}

