pair<vector<int>, vector<int>> bfs(int s) {
	vector<int> cost(N, 1<<29);
	vector<int> pre(N, -1);
	cost[s] = 0;
	queue<int> q;
	q.push(s);
	while (q.size()) {
		int v = q.front(); q.pop();
		for (auto u : G[v]) if (!deleted[u]) {
			if (cost[v]+1 < cost[u]) {
				cost[u]=cost[v]+1;
				pre[u]=v;
				q.push(u);
			}
		}
	}
	return make_pair(cost, pre);
}

