int mx , cnt , sv[ N ];
int dfs( int now , int prt , int dep ){
  if( ( k % 2 ) && dep == ( k + 1 ) / 2 ){
    return sv[ now ] = 1;
  }
  if( dep > k / 2 ) return sv[ now ] = 0;
  cnt ++; sv[ now ] = 0;
  for( int son : v[ now ] ){
    if( son == prt ) continue;
    sv[ now ] += dfs( son , now , dep + 1 );
  }
  return sv[ now ];
}
inline int cal( int now ){
  cnt = 0;
  dfs( now , -1 , 0 );
  if( k % 2 ){
    int bst = 0;
    for( int son : v[ now ] )
      bst = max( bst , sv[ son ] );
    cnt += bst;
  }
  return cnt;
}
void solve(){
  mx = 1;
  for( int i = 1 ; i <= n ; i ++ )
    mx = max( mx , cal( i ) );
  printf( "%d\n" , n - mx );
}
