int N, K, deg[2005];
vector<int> G[2005];

int dfs(int u, int p, int d){
    int res = 0;
    for(auto v : G[u]){
        if(v != p) res += dfs(v, u, d+1);
    }
    if(d>K) res++;
    return res;
}

int main(){
    ios::sync_with_stdio(false), cin.tie(nullptr);
    cin >> N >> K;
    for(int i=0;i<N-1;i++){
        int a, b; cin >> a >> b;
        deg[a]++; deg[b]++;
        G[a].push_back(b); G[b].push_back(a);
    }

    int ans = N;
    for(int i=1;i<=N;i++) if(deg[i]==1) ans = min(ans, dfs(i, -1, 0));

    cout << ans << endl;
    return 0;
}

