#include <bits/stdc++.h>

using namespace std;

int main() {
  ios::sync_with_stdio(false);
  cin.tie(nullptr);
  int n, k;
  cin >> n >> k;
  vector< vector<int> > g(n);
  vector<int> a(n), b(n);
  for (int i = 0; i < n - 1; i++) {
    int x, y;
    cin >> x >> y;
    x--; y--;
    g[x].push_back(y);
    g[y].push_back(x);
    a[i] = x;
    b[i] = y;
  }
  vector< vector<int> > dist(n, vector<int>(n));
  function<void(int, int, int, int)> dfs = [&](int v, int p, int root, int d) {
    dist[root][v] = d;
    for (int& u : g[v]) {
      if (u == p) {
        continue;
      }
      dfs(u, v, root, d + 1);
    }
  };
  for (int i = 0; i < n; i++) {
    dfs(i, -1, i, 0);
  }
  int ans = n;
  {
    for (int v = 0; v < n; v++) {
      int cnt = 0;
      for (int u = 0; u < n; u++) {
        if (2 * dist[v][u] > k) {
          cnt++;
        }
      }
      ans = min(ans, cnt);
    }
  }
  {
    for (int ei = 0; ei < n - 1; ei++) {
      int ai = a[ei];
      int bi = b[ei];
      int cnt = 0;
      for (int u = 0; u < n; u++) {
        if (2 * min(dist[ai][u], dist[bi][u]) + 1 > k) {
          cnt++;
        }
      }
      ans = min(ans, cnt);
    }
  }
  cout << ans << '\n';
  return 0;
}

