/** Idea: Every diameter has a center. IF length of diameter is even than the center
is a node. IF length of diameter is odd than the center is an edge. Assume every node
as center of k length diameter. Then calculate how many node u have to erase if it's
a center. Take minimum of all **/

#define sz 2005
vi graph[sz];
int n,k,bad=0,vis[sz],level[sz],parent[sz];

void DFS(int u,int par)
{
    vis[u] = 1;
    parent[u] = par;
    for(auto v:graph[u]){
        if(!vis[v])
            DFS(v , u);
    }
}

void DFS2(int u,int lev,int opposite)
{
    vis[u] = 1;
    level[u] = lev;
    if(level[u] > k/2){
        bad++;
    }
    for(auto v:graph[u]){
        if(!vis[v] && v!=opposite)
            DFS2(v , 1+lev , opposite);
    }
}

void Solve(int t)
{
    int i,j,u,v,ans;
    scin2(n , k);
    for(i=1 ; i<=n-1 ; i++){
        scin2(u , v);
        graph[u].pb(v);
        graph[v].pb(u);
    }
    if(k == 1){
        cout<<n-2<<endl;
        return;
    }
    else
        ans = n;
    DFS(1 , -1);
    if(k%2 == 0){
        for(i=1 ; i<=n ; i++){
            ms(vis , 0);
            bad = 0;
            DFS2(i , 0 , -1);
            ans = min(ans , bad);
        }
    }
    else{
        for(i=1 ; i<=n ; i++){
            u = i;
            v = parent[i];
            if(v != -1){
                ms(vis , 0);
                bad = 0;
                DFS2(u , 0 , v);
                DFS2(v , 0 , u);
                ans = min(ans , bad);
            }
        }
    }
    cout<<ans<<endl;
}

int main()
{
    int t,T;
    T = 1;
