vector<vector<int>> G;
int N, K;

int MAX = 0;

int f(int idx, int par, int k) {
    if (k <= 0)
        return 0;
    int cnt = 1;
    if (k > 1) {
        for (auto& nxt : G[idx]) {
            if (nxt == par)
                continue;
            cnt += f(nxt, idx, k - 1);
        }
    } else {
        chmax(MAX, (int)(G[idx].size() - 1));
    }
    return cnt;
}

void solve() {
    int ans = INF;
    K++;
    if (K % 2)
        for (int i = 0; i < N; i++) {
            MAX = 0;
            int tmp = 0;

            tmp += f(i, -1, (K + 1) / 2);
            chmin(ans, N - tmp);
        }
    else {
        for (int i = 0; i < N; i++) {
            for (auto& j : G[i]) {
                int tmp = 0;
                tmp += f(i, j, K / 2);
                tmp += f(j, i, K / 2);
                chmin(ans, N - tmp);
            }
        }
    }
    cout << ans << endl;
}

