int dfs(int c, int p, int d) {
  dep[c] = d;
  P[c] = p;
  int res = c;
  rep(i,0,g[c].size()) {
    int u = g[c][i];
    if(u == p) continue;
    int f = dfs(u, c, d+1);
    if(dep[f] > dep[res]) {
      res = f;
    }
  }
  return res;
}

void dfs1(int c, int p1, int p2, int d, int s) {
  X[s][d]++;
  rep(i,0,g[c].size()) {
    int u = g[c][i];
    if(u == p1 || u == p2) continue;
    dfs1(u, c, c, d+1, s);
  }
}

int main() {
