    g[u].push_back(v);
    g[v].push_back(u);
  }
  int c = dfs(1, -1, 0);
  int d = dfs(c, -1, 0);

  int ans = n + 1;
  rep(it,1,n+1) if(dep[it] == dep[d]) {
    vi path;
    int tmp = it;
    while(tmp != -1) {
      path.push_back(tmp);
      tmp = P[tmp];
    }

    if(path.size() <= k + 1) {
      P(0);
      return 0;
    }

    rep(i,0,path.size()) {
      int c = path[i];
      dfs1(c, (i + 1 < path.size()) ? path[i+1] : -1, i ? path[i-1] : -1, 0, c);
      for(int j = n - 1; j >= 0; j--) X[c][j] += X[c][j+1];
    }

    for(int i = 0; i + k < path.size(); i++) {
      int tmp = 0;
      rep(j,0,path.size()) {
        if(j < i || j > i + k) {
          tmp += X[path[j]][0];
          continue;
        }
        tmp += X[path[j]][min(j - i, i + k - j) + 1];
      }
      ans = min(ans, tmp);
    }
  }
  P(ans);

  return 0;
}

