inline void dfs(int v, int p = -1) {
    sz[v] = 1;
    h[v] = 0;
    for (int to : g[v]) {
        if (to == p) {
            continue;
        }
        dfs(to, v);
        sz[v] += sz[to];
        h[v] = max(h[v], h[to] + 1);
    }
    if (p != -1 && len(g[v]) == 1) {
        for (int i = 1; i <= k; i++) {
            dp[v][i] = 0;
