    dp[v][0] = sz[v];
    for (int i = 0; i <= k; i++) {
        int sum = 0, mn = inf;
        int mx = min(k - i, i);
        for (int to : g[v]) {
            if (to == p) {
                continue;
            }
            sum += dp[to][mx - 1 + 1];
            mn = min(mn, dp[to][i - 1 + 1] - dp[to][mx - 1 + 1]);
        }
        dp[v][i + 1] = min(dp[v][i], sum + mn);
    }
}

