	int ans = INF;
	if (k % 2 == 0) {
		rep(i, n) {
			clr(vis);
			ans = min(ans, dfs(i, 0, k / 2));
		}
	}
	else {
		each(i, e) {
			clr(vis);
			vis[i.first] = vis[i.second] = 1;
			ans = min(ans, dfs(i.first, 0, k / 2) + dfs(i.second, 0, k / 2));
		}
	}
	cout << ans << endl;

	return 0; 
}

