void gdfs(int p, int v, vector<vi> &g){
  FOR(e, g[v]){
    if((*e) == p) continue;
    gdfs(v, (*e), g);
  }
  gdp[v][0] = 1;
  REP(i, k){
    if(!i){
      FOR(e, g[v]){
        if((*e) == p) continue;
        gdp[v][0] += gdp[(*e)][0];
      }
      continue;
    }
    FOR(e, g[v]){
      if((*e) == p) continue;
      gdp[v][i] += gdp[(*e)][i-1];
    }
    // min_cost
    int m = g[v].size();
    for(int x = 0; x <= k / 2; x++){
      int cost = n - gdp[v][0];
      FOR(e, g[v]){
        if((*e) == p) continue;
        cost += gdp[(*e)][x];
      }
      int y = k - x;
      //cout << "cost" << v << " " << x << " " << cost << endl;
      FOR(e, g[v]){
        if((*e) == p) continue;
        cost -= gdp[(*e)][x];
        //check
        int ncost = cost + gdp[(*e)][y];
        ans = min(ans, ncost);

        cost += gdp[(*e)][x];
      }
    }
  }
}

