    graph.adde(b, a, 1);
    vec.pb(mk(a, b));
  }
  int res = inf;
  if(k % 2 == 0){
    rep(i, n){
      int tmp = 0;
      graph.dijkstra(i);
      rep(j, n){
        if(graph.dis[j] > k / 2)tmp++;
      }
      res = min(res, tmp);
    }
  }else{
    rep(i, n - 1){
      int tmp = 0;
      int a = vec[i].first;
      int b = vec[i].second;
      graph.dijkstra(a);
      vector<int> dis(n);
      rep(j, n)dis[j] = graph.dis[j];
      graph.dijkstra(b);
      rep(j, n){
        dis[j] = min(dis[j], graph.dis[j]);
        if(dis[j] > (k - 1) / 2)tmp++;
      }
      res = min(res, tmp);
    }
  }
  cout << res << endl;
	return 0;
}

