		pp = pq.top();
		LL cos = pp.first, vv = pp.second;
		pq.pop();
		if (d[vv] < pp.first)continue;
		for (int i = 0; i < vec[vv].size(); i++) {
			if (vec[vv][i].cost + d[vv] < d[vec[vv][i].to]) {
				d[vec[vv][i].to] = vec[vv][i].cost + d[vv];
				pq.push(make_pair(d[vec[vv][i].to], vec[vv][i].to));
			}
		}
	}
}

