	return sqrt((double)abs(x1-x2)*(double)abs(x1-x2)+(double)abs(y1-y2)*(double)abs(y1-y2));
}

bool solve() {
	int n, k; cin >> n >> k;
	vvi edge = vvi(n);
	REP (i,n-1) {
		int a,b; cin >> a >> b;
		edge[--a].pb(--b);
		edge[b].pb(a);
	}

	int ans = INF;
	vi dep(n);
	REP (i,n) {
		vvi sub(edge[i].size());
		fill(all(dep),-1);//各頂点は一度しか訪れないので
		dep[i] = 0;
		int tmp = 0;
		int odd = INF;

		REP (j,sub.size()) {
			dep[edge[i][j]] = 1;
			queue<int> nxt; nxt.push(edge[i][j]);
			while (!nxt.empty()) {
				int p = nxt.front(); nxt.pop();
				sub[j].pb(dep[p]);
				for (auto to : edge[p]) {
					if (dep[to] == -1) {
						dep[to] = dep[p] + 1;
						nxt.push(to);
					}
				}
			}

			if (k % 2) {
				//奇数
				int rem = upper_bound(all(sub[j]),k/2) - sub[j].begin();
				tmp += sub[j].size() - rem;
				int can = upper_bound(all(sub[j]),k/2+1) - sub[j].begin();
				chmin(odd,rem-can);
			} else {
				int rem = upper_bound(all(sub[j]),k/2) - sub[j].begin();
				tmp += sub[j].size() - rem;
			}
		}
		if (k % 2) {
			chmin(ans,tmp+odd);
		} else {
			chmin(ans,tmp);
		}
	}

	cout << ans << endl;
}

signed main() {
	cin.tie(0);
	ios::sync_with_stdio(false);
	solve();
}

