vector<int> edges[2010];
int siz[2010], h[2010], hm[2010];
ll dp[2010][2010];
ll tmp[2010], tmp2[2010];
int k, n;

void dfs(int i, int p){
  siz[i] = 1;
  hm[i] = h[i];
  if(p != -1 && sz(edges[i]) == 1){
    dp[i][0] = 1;
    dp[i][1] = 0;
    return;
  }
  int fi = -1;
  for(auto e: edges[i]){
    if(e == p)continue;
    if(fi == -1)fi = e;
    h[e] = h[i] + 1;
    dfs(e, i);
    chmax(hm[i], hm[e]);
    siz[i] += siz[e];
  }
  fill(tmp, tmp + n, inf);
  rep(j, hm[fi] - h[fi] + 2)tmp[j] = dp[fi][j];
  int b = min(k, hm[fi] - h[fi] + 1);
  for(auto e: edges[i]){
    if(e == p || e == fi)continue;
    int bt = b;
    rep(j, bt + 1)tmp2[j] = inf;
    for(int l = 0; l <= hm[e] - h[e] + 1; l++){
      for(int m = 0; m <= b; m++){
        if(l + m > k)break;
        chmax(bt, max(l, m));
        chmin(tmp2[max(l, m)], tmp[m] + dp[e][l]);
      }
    }
    swap(tmp, tmp2);
    b = bt;
  }
  rep(j, b + 1){
    dp[i][j+1] = tmp[j];
  }
  dp[i][0] = siz[i];
  //rep(j, b + 2)cerr << i << " " << j << " " << dp[i][j] << endl;
}

int main(int argc, char const* argv[])
{
  cin >> n >> k;
  rep(i, n - 1){
    int a, b; cin >> a >> b, a--, b--;
    edges[a].pb(b);
    edges[b].pb(a);
  }
  rep(i, n)rep(j, n + 1)dp[i][j] = inf;
  dfs(0, -1);
  ll res = inf;
  rep(i, k + 2)chmin(res, dp[0][i]);
  cout << res << endl;
  return 0;
}

