pair<int,int> farthest_vertex(const vector<set<pair<int,int>>> &graph,int v,int p){
    pair<int,int> res(v,0); //(最も遠い頂点,距離)
    for(auto &e:graph[v]){
        if(e.first==p) continue;

        auto tmp=farthest_vertex(graph,e.first,v);
        tmp.second+=e.second;
        if(res.second<tmp.second) res=tmp;
    }
    return res;
}

void solve(){
    int n,k;
    cin >> n >> k;
    vector<set<pii>> graph(n);
    rep(i,0,n-1){
        int a,b;
        cin >> a >> b;
        --a;
        --b;
        graph[a].insert(make_pair(b,1));
        graph[b].insert(make_pair(a,1));
    }

    set<int> not_erase;
    rep(i,0,n) not_erase.insert(i);
    int ans=0;
    while(true){
        auto p=farthest_vertex(graph,*not_erase.begin(),-1);
        p=farthest_vertex(graph,p.first,-1);
        if(p.second<=k){
            cout << ans << endl;
            return;
        }
        int v=graph[p.first].begin()->first;
        graph[v].erase(make_pair(p.first,1));
        not_erase.erase(p.first);
        ++ans;
    }
}

