		hld.add_edge(x, y);
		edge.pb(P(x, y));
	}
	hld.build();
	rep(i,n)rep(j,n)dis[i][j] = hld.distance(i, j);

	int ans = INF;
	if(k%2 == 1){
		rep(i,edge.size()){
			int u = edge[i].fi, v = edge[i].se, res = 0;
			rep(j,n)res += min(dis[u][j], dis[v][j]) > k/2;
			chmin(ans, res);
		}
	}else{
		rep(i,n){
			int res = 0;
			rep(j,n)if(dis[i][j] > k/2)res++;
			chmin(ans, res);
		}
	}

	printf("%lld\n", ans);
	return 0;
}

