int calc(int center) {
	vid++;
	queue<int> Q;
	vis[center] = vid;
	Q.push(center);
	int lim = k / 2;
	int res = 0;
	while (SZ(Q) && lim >= 0) {
		int sz = SZ(Q);
		while (sz--) {
			int cur = Q.front();
			Q.pop();
			res++;
			for (auto to : adj[cur]) {
				if (vis[to] == vid)
					continue;
				Q.push(to);
				vis[to] = vid;
			}
		}
		lim--;
	}
	int mx = 0;
	while (k % 2 == 1 && SZ(Q)) {
		int cur = Q.front();
		Q.pop();
		int last = 0;
		for (auto to : adj[cur]) {
			if (vis[to] == vid)
				continue;
			last++;
		}
		mx = max(mx, last);
	}
	res += mx;
	return n - res;
}

