ll N, K;
vector<ll> E[2000];

void dfs(ll v, ll p, vector<ll> &vec, ll depth) {
  vec[depth]++;
  REP(i, 0, E[v].size()) if(E[v][i] != p) dfs(E[v][i], v, vec, depth + 1);
}

ll solve(ll v) {
  vector< vector<ll> > subtree(E[v].size(), vector<ll>(N + 1, 0));
  REP(i, 0, E[v].size()) {
    dfs(E[v][i], v, subtree[i], 1);
    subtree[i][0]++;
  }

  vector<ll> all(N + 1);
  dfs(v, -1, all, 0);

  REP(i, 0, E[v].size()) {
    for(ll j = subtree[i].size() - 1; j >= 1; j--) {
      subtree[i][j - 1] += subtree[i][j];
    }
  }
  for(ll j = all.size() - 1; j >= 1; j--) {
    all[j - 1] += all[j];
  }

  ll ret = INF;
  REP(i, 0, E[v].size()) {
    REP(j, 0, K + 1) {
      if(j <= K - j) ret = min(ret, all[j + 1] - subtree[i][j + 1] + subtree[i][K - j + 1]);
    }
  }

  return ret;
}

