	for(int i=0; i<n-1; i++){
		cin >> a >> b;
		a--;
		b--;
		ms[a].push_back(b);
		ms[b].push_back(a);
	}
	int sol=n;
	for(int i=0; i<n; i++){
		sol=min(sol, solve(i));
		while(!q.empty()){
			q.pop();
		}
		bio.reset();
	}
	cout << sol << '\n';
	return 0;
}

