//		puts("~~~~~~~~~~~~");

		Rep(i,0,len)
			f[u][i] = min(g[i]+h[min(i,k-i)],g[min(i,k-i)] + h[i]);

//		Rep(i,0,m) wri(f[u][i]);puts("");
//		Rep(i,0,len) wri(f[u][i]);puts("");

