typedef long long ll;

const int N = 2001;
const int INF = 1e9;
vector<int> mdp[N];
int sz[N];
int n, diam;
vector<int> edges[N];

void dfs(int v, int p = -1) {
  sz[v] = 1;
  vector<int> dp(sz[v] + 1);
  for (int u : edges[v]) {
    if (u == p) continue;
    dfs(u, v);
    vector<int> ndp(sz[v] + sz[u] + 1, INF);
    for (int s = 0; s <= sz[v]; s++) {
      for (int p = 0; p < sz[u]; p++) {
        if (mdp[u][p] + 1 + dp[s] <= diam) {
          ndp[s + p] = min(ndp[s + p], max(mdp[u][p] + 1, dp[s]));
        }
      }
      if (dp[s] <= diam) {
        ndp[s + sz[u]] = min(ndp[s + sz[u]], dp[s]);
      }
    }
    sz[v] += sz[u];
    dp = ndp;
  }
  mdp[v] = dp;
}

void solve() {
  cin >> n >> diam;
  for (int i = 0; i < n - 1; i++) {
    int v, u; cin >> v >> u;
    edges[v].push_back(u); edges[u].push_back(v);
  }
  dfs(1);
  for (int cnt = 0; cnt < mdp[1].size(); cnt++) {
    if (mdp[1][cnt] != INF) {
      cout << cnt; return;
    }
  }
}

