                int temp = 0;
                while(!qu.empty()){
                    int node = qu.front();
                    qu.pop();
                    FOR(z,adjList[node].size()){
                        int next = adjList[node][z];
                        if(dist[next] > dist[node] + 1){
                            dist[next] = dist[node] + 1;
                            if(dist[next] <= (k-1)/2){
                                temp++;
                            }
                            qu.push(next);
                        }
                    }
                }
                //cout<<"temp: "<<temp<<endl;
                mxcount = max(mxcount, temp);
            }
        }
        cout<<(n-mxcount)<<endl;
    }else{
        //try each vertex.
        int mxcount = 0;
        FOR(i,n){
            FOR(j,n)dist[j] = INF;
            dist[i] = 0;
            int temp = 1;
            queue<int> qu;
            qu.push(i);
            while(!qu.empty()){
                int node = qu.front();
                qu.pop();
                FOR(i,adjList[node].size()){
                    int next = adjList[node][i];
                    if(dist[next] > dist[node] + 1){
                        dist[next] = dist[node] + 1;
                        if(dist[next] <= k/2){
                            temp++;
                        }
                        qu.push(next);
                    }
                }
            }
            mxcount = max(mxcount, temp);
        }
        cout<<(n-mxcount)<<endl;
    }

    return 0;
}

