template <typename T>
struct edge{
  int from, to;
  T w;
  edge(){}
  edge(int from, int to, T w): from(from), to(to), w(w){}
};

int start, en;

template <typename T>
struct Tree{
  int n = 0;
  vector<vector<edge<T>>> edges;
  vector<T> dis;
  Tree(){}
  explicit Tree(int n): n(n){
    edges.resize(n);
    dis.resize(n);
  }
  void adde(int from, int to, T cost){
    edges[from].emplace_back(from, to, cost);
  }
  void dfs(int i){
    for(auto e: edges[i]){
      if(dis[e.to] == -1){
        dis[e.to] = dis[i] + e.w;
        dfs(e.to);
      }
    }
  }
  T diameter(){
    dis.assign(n, -1);
    dis[0] = 0;
    dfs(0);
    int at = 0;
    T maxi = -1;
    for(int i = 0; i < n; i++){
      if(maxi < dis[i]){
        maxi = dis[i];
        at = i;
      }
    }
    dis.assign(n, -1);
    dis[at] = 0;
    start = at;
    dfs(at);
    T res = -1;
    for(int i = 0; i < n; i++){
      bool b = chmax(res, dis[i]);
      if(b)en = i;
    }
    return res;
  }
};


vector<int> edges[2010];
int siz[2010], h[2010], hm[2010];
ll dp[2010][2010];
ll tmp[2010], tmp2[2010];
int k, n;
vector<int> v;
bool dfs2(int i, int p, int tar){
  if(i == tar)return true;
  v.pb(i);
  for(auto e: edges[i]){
    if(e == p)continue;
    bool b = dfs2(e, i, tar);
    if(b)return true;
  }
  v.pop_back();
  return false;
}

void dfs(int i, int p){
  siz[i] = 1;
  hm[i] = h[i];
  if(p != -1 && sz(edges[i]) == 1){
    dp[i][0] = 1;
    dp[i][1] = 0;
    return;
  }
  int fi = -2;
  for(auto e: edges[i]){
    if(e == p)continue;
    if(fi == -2)fi = e;
    h[e] = h[i] + 1;
    dfs(e, i);
    chmax(hm[i], hm[e]);
    siz[i] += siz[e];
  }
  fill(tmp, tmp + n + 1, inf);
  rep(j, hm[fi] - h[fi] + 2)tmp[j] = dp[fi][j];
  int b = min(k, hm[fi] - h[fi] + 1);
  for(auto e: edges[i]){
    if(e == p || e == fi)continue;
    int bt = b;
    rep(j, min(k, b + hm[e] - h[e] + 1) + 1)tmp2[j] = inf;
    for(int l = 0; l <= max(k, hm[e] - h[e] + 1); l++){
      for(int m = 0; m <= b; m++){
        if(l + m > k)break;
        chmax(bt, max(l, m));
        chmin(tmp2[max(l, m)], tmp[m] + dp[e][l]);
      }
    }
    swap(tmp, tmp2);
    b = bt;
  }
  rep(j, b + 1){
    dp[i][j+1] = tmp[j];
  }
  dp[i][0] = siz[i];
  //rep(j, b + 2)cerr << i << " " << j << " " << dp[i][j] << endl;
}

