#include <bits/stdc++.h>
using namespace std;

pair<int, int> dfs(int node, auto& g, auto& seen, int depth, int k, bool is_root) {
    seen[node] = true;
    vector<pair<int, int>> sons;

    for (int v : g[node]) {
        if (seen[v])
            continue;
        auto result = dfs(v, g, seen, depth + 1, k, false);
        sons.push_back(result);
    }

    pair<int, int> current_res = make_pair(depth > k / 2, depth == (k / 2) + 1);

    for (auto son : sons) {
        current_res.first += son.first;
        current_res.second += son.second;
    }

    if (not is_root) {
        return current_res;
    }

    if (k % 2 == 0) {
        return current_res;
    }

    int best = 0;

    for (auto son : sons) {
        best = max(best, son.second);
    }

    return make_pair(current_res.first - best, -1);
}

int main() {
   int n, k; cin >> n >> k;
   vector<vector<int>> g(n);

   for (int i = 0; i < n - 1; i += 1) {
        int a, b; cin >> a >> b;
        a -= 1, b -= 1;
        g[a].push_back(b);
        g[b].push_back(a);
   }

   int ans = n;

   for (int center = 0; center < n; center += 1) {
       vector<int> seen(n, 0);
       auto res = dfs(center, g, seen, 0, k, true);

       ans = min(ans, res.first);
   }

   cout << ans << "\n";
}

