int solve(int u, int p){
	size[ u ] = 1;
	for (auto v : adj[ u ]) if (v != p){
		size[ u ] += solve(v, u);
		sm[u][0] += size[v];
		for (int i = 0; i <= size[v]; ++i)
			sm[u][i + 1] = min( sm
				[u][i + 1] + dp[v][i], oo);
	}

	memset(dp[u], oo, sizeof dp[u]);
	dp[u][0] = size[u] - 1;

	for (auto v : adj[u]) if (v != p){
		for (int i = 1; i <= min(size[v], k); ++i){
			int j = min(i, k - i);			
			dp[u][i] = min( dp[u][i], 
							dp[v][i - 1] + sm[u][j] - 
							(j == 0 ? size[v] : dp[v][j - 1]) );
		}
	}

	int limit = min( size[u], k );
	for (int i = 1; i <= limit; ++i)
		dp[u][i] = min( dp[u][i], dp[u][i - 1] );
	answer = min(answer, dp[u][limit] + n - size[u]);


	return size[ u ];
}

