int BFS(int u1, int u2, int t)
{
    queue<int>q;
    memset(vis, 0, sizeof(vis));
    memset(dis, INF, sizeof(dis));
    q.push(u1), vis[u1] = 1, dis[u1] = 0;
    if(t == 2)q.push(u2), vis[u2] = 1, dis[u2] = 0;
    while(!q.empty())
    {
        int u = q.front();
        q.pop();
        for(int i = 0; i < G[u].size(); i++)
        {
            int v = G[u][i];
            if(vis[v])continue;
            vis[v] = 1;
            dis[v] = dis[u] + 1;
            q.push(v);
        }
    }
    int ans = 0;
    for(int i = 1; i <= n; i++)if(dis[i] > k / 2)ans++;
    return ans;
}
