#include <bits/stdc++.h>
using namespace std;

struct Graph
{
    struct Edge { int a, b; };
    int N;
    vector<vector<int>> adjacency_list;
    vector<Edge> edges;

    Graph(int N) : N(N), adjacency_list(vector<vector<int>>(N)), edges(vector<Edge>()) {}

    void add_edge(int a, int b)
    {
        edges.push_back({a, b});
        adjacency_list[a].push_back(b);
        adjacency_list[b].push_back(a);
    }

    vector<int>& neighbors(int v) { return adjacency_list[v]; }
};

vector<int> bfs(int N, Graph& graph, initializer_list<int> sources)
{
    auto distances = vector<int>(N, numeric_limits<int>::max());
    auto queue = std::queue<int>();
    for (auto v : sources)
    {
        distances[v] = 0;
        queue.push(v);
    }

    while (!queue.empty())
    {
        auto v = queue.front(); queue.pop();
        for (auto w : graph.neighbors(v)) if (distances[w] == numeric_limits<int>::max())
        {
            distances[w] = distances[v]+1;
            queue.push(w);
        }
    }
    return distances;
}

int solve(int N, int K, Graph tree)
{
    auto result = numeric_limits<int>::max();
    for (auto v = 0; v < N; v++)
    {
        auto distances = bfs(N, tree, {v});
        auto option = 0;
        for (auto d : distances)
            option += 2*d > K;
        result = min(result, option);
    }
    for (auto edge : tree.edges)
    {
        auto distances = bfs(N, tree, {edge.a, edge.b});
        auto option = 0;
        for (auto d : distances)
            option += 2*d+1 > K;
        result = min(result, option);
    }
    return result;
}

int main()
{
    int N, K; cin >> N >> K;

    auto tree = Graph(N);
    for (auto i = 0; i < N-1; i++)
    {
        int a, b; cin >> a >> b;
        a--; b--;
        tree.add_edge(a, b);
    }

    cout << solve(N, K, tree) << endl;
}

