struct Node{
    int pos;
    int cost;
    bool operator< (const Node &r) const{
        return cost > r.cost;
    }
};


int n, k, INF = 2005;
vector<int> g[2005];

int count(int src, int avoid){
    priority_queue<Node> q;
    q.push({src,0});
    vector<ll> res(n,INF);

    int inside = 0;
    while(q.size()){
        Node n = q.top(); q.pop();
        res[n.pos] = n.cost;
        inside++;

        for(auto to : g[n.pos]){
            if(to != avoid)
            if(res[to] == INF)
            if(n.cost+1 <= k/2.0) q.push({to, n.cost + 1});
        }
    }

    return inside;
}


int main(){
