        g[b-1].push_back(a-1);
    }

    priority_queue<int, vector<int>, greater<int>> q;
    rep(src, n){
        if(k%2 == 0)    q.push(n-count(src, -1));
        else{
            for(auto avoid : g[src]){
                q.push(n-count(src, avoid)-count(avoid, src));
            }
        }
    }


    cout << q.top() << endl;


