vector<vector<int> > dp;
vector<vector<int> > sum; // sum[v][dep] = dp[v][0] + ... + dp[v][dep]

void dfs(int v, int p)
{
    subtree[v] = 1;
    vector<int> sons;
    for (int to : g[v]) {
        if (to != p) {
            dfs(to, v);
            sons.pb(to);
            subtree[v] += subtree[to];
        }
    }
    dp[v][0] = subtree[v] - 1;
    for (int dep = 1; dep < k; ++dep) {
        int x = min(dep - 1, k - dep - 1);
        int s = 0;
        for (int son : sons) {
            s += sum[son][x];
        }
        for (int son : sons) {
            dp[v][dep] = min(dp[v][dep], dp[son][dep - 1] + s - dp[son][x]);
        }
    }
    int s = subtree[v] - 1;
    for (int son : sons) {
        dp[v][k] = min(dp[v][k], dp[son][k - 1] + s - subtree[son]);
    }
    sum[v][0] = dp[v][0];
    for (int dep = 1; dep <= k; ++dep) {
        sum[v][dep] = sum[v][dep - 1] + dp[v][dep];
    }
}

