vector<int> edges[2010];
int siz[2010], h[2010], hm[2010];
ll dp[2010][2010];
ll tmp[2010], tmp2[2010];
int k, n;

void dfs(int i, int p){
  siz[i] = 1;
  hm[i] = h[i];
  if(p != -1 && sz(edges[i]) == 1){
    dp[i][0] = 1;
    dp[i][1] = 0;
    return;
  }
  int fi = -1;
  for(auto e: edges[i]){
    if(e == p)continue;
    if(fi == -1)fi = e;
    h[e] = h[i] + 1;
    dfs(e, i);
    chmax(hm[i], hm[e]);
    siz[i] += siz[e];
  }
  fill(tmp, tmp + n + 1, inf);
  rep(j, hm[fi] - h[fi] + 2)tmp[j] = dp[fi][j];
  int b = min(k, hm[fi] - h[fi] + 1);
  for(auto e: edges[i]){
    if(e == p || e == fi)continue;
    int bt = b;
    rep(j, min(k + 1, b + hm[e] - h[e] + 1) + 1)tmp2[j] = inf;
    for(int l = 0; l <= max(k, hm[e] - h[e] + 1); l++){
      for(int m = 0; m <= b; m++){
        if(l + m > k)break;
        chmax(bt, max(l, m));
        chmin(tmp2[max(l, m)], tmp[m] + dp[e][l]);
      }
    }
    swap(tmp, tmp2);
    b = bt;
  }
  rep(j, b + 1){
    dp[i][j+1] = tmp[j];
  }
  dp[i][0] = siz[i];
  //rep(j, b + 2)cerr << i << " " << j << " " << dp[i][j] << endl;
}

