    edges[a].pb(b);
    edges[b].pb(a);
  }
  rep(i, n)rep(j, n + 1)dp[i][j] = inf;
  dfs(0, -1);
  ll res = inf;
  rep(i, k + 2)chmin(res, dp[0][i]);
  cout << res << endl;
  return 0;
}

