		mxd = max(mxd, Dfs(v, now, D+1));
		siz[now] += siz[v];
	}
	int down = mxd - D + 1;

	Min[now][0] = f[now][0] = siz[now] - 1;

	int r, sum, cc;
	For(j, 1, min(rk, down)){
		f[now][j] = oo; r = max(min(j-1, rk-j-1), -1);
		sum = 0; cc = 0;

		For(i, 0, G[now].size()-1)
			if(v != F){
