					sum += Min[v][r];
					cc = max(cc, Min[v][r] - f[v][j-1]);
				}else{
					sum += f[v][0] + 1;
					cc = max(cc, (f[v][0]+1) - f[v][j-1]);
				}
			}

		sum -= cc; f[now][j] = min(f[now][j], sum);
		Min[now][j] = min(Min[now][j-1], f[now][j]);

	}

	int beg = min(rk, down);
	For(j, beg+1, rk) Min[now][j] = Min[now][j-1], f[now][j] = oo;

