{
	for(int i=1; i<=amount; ++i)
	{
		cout<<i<<" <- ";
		for(int j=1; j<=amount; ++j)
		{
			cout<<input[i][j]<<", ";
		}
		cout<<endl;
	}
	return;
}
void fillingGraph()
{
	cin>>amount>>diameter;
	int vertex0, vertex1;
	for(int i=1; i<amount; ++i)
	{
		cin>>vertex0>>vertex1;
		graph[vertex0].push_back(vertex1);
		graph[vertex1].push_back(vertex0);
	}
	return;
}
void dfs(int root, int first, int distance)
{
	visited0[root][first]=true;
	for(int second : graph[first])
	{
		if(!visited0[root][second])
		{
			dfs(root, second, distance+1);
		}
	}
	distances[root][first]=distance;
	return;
}
void usingDfs()
{
	for(int point=1; point<=amount; ++point)
	{
		dfs(point, point, 0);
	}
	for(int i=1; i<=amount; ++i)
	{
		for(int j=1; j<=amount; ++j)
		{
			if(distances[i][j]<=diameter && !visited1[i][j] && !visited1[j][i])
			{
				visited1[i][j]=true;
				visited1[j][i]=true;
				int number=0;
				for(int k=1; k<=amount; ++k)
				{
					if(distances[k][i]>diameter && distances[k][j]>diameter)
					{
						if(!visited2[k][i] && !visited2[i][k] && !visited2[k][j] && !visited2[j][k])
						{
							visited2[k][i]=true;
							visited2[i][k]=true;
							visited2[k][j]=true;
							visited2[j][k]=true;
							++number;
						}
					}
				}
				exceeded.push_back(number);
			}
		}
	}
	answer=exceeded[0];
  	for(int i=1; i<exceeded.size(); ++i)
    {
    	answer=max(answer, exceeded[i]);
    }
  	cout<<answer;
  	return;
}
