        }
    }
}

int Even(int n, int k, vector<vector<int>> &tree) {
    int min_remove = n;
    for (int v = 0; v < n; ++v) {
        vector<int> d(n, 0);
        Dfs(-1, v, tree, d);

        int remove = 0;
        for (int u = 0; u < n; ++u)
            if (d[u] > k / 2)
                ++remove;

        min_remove = min(min_remove, remove);
    }

    return min_remove;
}

int Odd(int n, int k, vector<vector<int>> &tree) {
    int min_remove = n;
    for (int v = 0; v < n; ++v) {
        for (auto u : tree[v]) {
            vector<int> d(n, 0);
            Dfs(u, v, tree, d);
            Dfs(v, u, tree, d);

            int remove = 0;
            for (int i = 0; i < n; ++i)
                if (d[i] > (k - 1) / 2)
                    ++remove;

            min_remove = min(min_remove, remove);
        }
    }

    return min_remove;
}

