    int n, k, a, b;

    cin >> n >> k;
    vector<vector<int>> tree(n);
    for (int i = 0; i < n - 1; ++i) {
        cin >> a >> b;
        tree[a - 1].push_back(b - 1);
        tree[b - 1].push_back(a - 1);
    }

    if (k % 2 == 0)
        cout << Even(n, k, tree) << endl;
    else
        cout << Odd(n, k, tree) << endl;

    return 0;
}

