#define MAX_N 2005

int n,K;
vector<int> G[MAX_N];
int dp[MAX_N][MAX_N];
int size[MAX_N];
int height[MAX_N];

void dfs(int pos,int prev){
  height[pos]=1;
  int cnt=1;
  for(int i=0;i<(int)G[pos].size();i++){
    int to=G[pos][i];
    if(to==prev)continue;
    dfs(to,pos);
    cnt+=size[to];
    height[pos]=max(height[pos], height[to]+1);
  }
  size[pos]=cnt;

  dp[pos][0]=cnt;

  if(size[pos]==1){
    dp[pos][1]=0;
    for(int i=2;i<=n;i++){
      dp[pos][i]=1e8;
    }
    return;
  }

  for(int i=1;i<=n;i++){
    if(i>K+1){
      dp[pos][i]=1e8;
      continue;
    }
    if(i>height[pos]){
      dp[pos][i]=dp[pos][i-1];
      continue;
    }

    dp[pos][i]=cnt;
    int cost=0,maxm=-1e9;
    for(int j=0;j<(int)G[pos].size();j++){
      int to=G[pos][j];
      if(to==prev)continue;


      cost+=( K-i+1 < 0? (int)1e8 : dp[to][K-i+1] );
      maxm=max(maxm, ( K-i+1 < 0? (int)1e8 : dp[to][K-i+1] ) - dp[to][i-1] );

    }

    dp[pos][i]=min(dp[pos][i], cost-maxm );

  }

}

