using namespace std;

vector<lli> adj[2010];
bool visited[2010];
lli level,save;

lli bfs(lli s){
	queue<int> q;
	memset(visited,false,sizeof visited);
	q.push(s);
	q.push(-1);
	lli current;
	level = -1;
	while(!q.empty()){
		current = q.front();
		q.pop();
		//cout<<current<<endl;
		if(current==-1){
			if(!q.empty()){
				q.push(-1);
			}
			level++;
			continue;
		}
		visited[current] = true;
		for(int i=0;i<adj[current].size();i++){
			if(!visited[adj[current][i]]){
				visited[adj[current][i]] = true;
				q.push(adj[current][i]);
			}
		}
		save = current;
	}
	return save;
}



