void bfs(int root){
	queue<int> q;
	dis[root][root]=0;
	q.push(root); 
	while(!q.empty()){
		int last=q.front();
		q.pop();
		for(int i=0;i<nei[last].size();i++){
			if(dis[root][nei[last][i]]==-1){
				dis[root][nei[last][i]]=dis[root][last]+1;
				q.push(nei[last][i]);
			}
		}
	}
}
