	dp[point][1] = dp[point][0] - 1;
	for (j = K+1; j > 1; j--)
	{
		int minSum = 0;
		for (i = s[point]; i < s[point+1]; i++)
		{
			if (a[i] != par)
			{
				mins[a[i]] = min(mins[a[i]], dp[a[i]][K-j+1]);
				minSum += mins[a[i]];
			}
		}
		dp[point][j] = MYINF;
		for (i = s[point]; i < s[point+1]; i++)
		{
			if (a[i] != par)
			{
				int temp = dp[a[i]][j-1] + minSum - mins[a[i]];
				dp[point][j] = min(dp[point][j], temp);
			}
		}
	}
	for (j = 0; j <= K+1; j++)
	{
		res = min(res, dp[point][j] + (N - dp[point][0]));
	}
}

