bitset < maxn > bio;
queue < pair < int, int > > q;

void bfs(int x){
	pair < int, int > p;
	bio[x]=1;
	q.push({x, 0});
	while(!q.empty()){
		p=q.front();
		if(p.second==k/2){
			break;
		}
		q.pop();
		x=p.first;
		for(int i=0; i<ms[x].size(); i++){
			if(!bio[ms[x][i]]){
				bio[ms[x][i]]=1;
				q.push({ms[x][i], p.second+1});
			}
		}
	}
}

int solve(int x){
	bfs(x);
	int br=bio.count();
	if(k%2){
		int maksi=0;
		while(!q.empty()){
			maksi=max(maksi, (int)ms[q.front().first].size()-1);
			q.pop();
		}
		br+=maksi;
	}
	return n-br;
}

