{
    vvi g(n);
    int k;
    cin >> k;
    for (int i = 1; i < n; i++)
    {
        int a, b;
        cin >> a >> b;
        --a, --b;
        g[a].pb(b);
        g[b].pb(a);
    }

    vvi dp(n);
    vi h(n);
    dfs(0, -1, g, h, dp, k);

    int ans = 0;
    for (const vi &cur : dp)
        ans = max(ans, *max_element(ALL(cur)));
    cout << n - ans << endl;
}

