				int c = 0;
				FOR(k, 0, SZ(g[j]))
				{
					if (!U[g[j][k]])
					{
						c++;
					}
				}

				if (maxx < c)
				{
					maxx = c;
					ind = j;
				}
			}
		}

		FOR(i, 0, SZ(g[ind])) U[g[ind][i]] = 1;
	}

	return cnt + maxx;
}

