const int maxn = 2000;
const int oo = 1000000000;
int n,k,head[maxn+1],link[maxn*2],adj[maxn*2],d[maxn+1];
int d1[maxn+1],d2[maxn+1];
void enter()
{
	cin >> n >> k;
	for (int i=1; i<=n-1; i++)
	{
		int a,b;
		cin >> a >> b;
		link[i*2-1]=head[a];
		adj[i*2-1]=b;
		head[a]=i*2-1;
		link[i*2]=head[b];
		adj[i*2]=a;
		head[b]=i*2;
	}
}
int bfs(int s,int diameter)
{
	for (int i=1; i<=n; i++)
		d[i]=oo;
	d[s]=0;
	queue<int> q;
	q.push(s);
	int res=1;
	do
	{
		int t=q.front();
		q.pop();
		if (d[t]==diameter) break;
		int i=head[t];
		while (i!=0)
		{
			if (d[adj[i]]>d[t]+1)
			{
				if (d[adj[i]]==oo) res++;
				d[adj[i]]=d[t]+1;
				q.push(adj[i]);
			}
			i=link[i];
		}
	}
	while (!q.empty());
	return res;
}
int bfs2(int x,int y,int diameter)
{
	for (int i=1; i<=n; i++)
		d1[i]=oo;
	d1[x]=0;
	for (int i=1; i<=n; i++)
		d2[i]=oo;
	d2[y]=0;
	queue<int> q;
	q.push(x);
	do
	{
		int t=q.front();
		q.pop();
		int i=head[t];
		while (i!=0)
		{
			if (d1[adj[i]]>d1[t]+1)
			{
				d1[adj[i]]=d1[t]+1;
				q.push(adj[i]);
			}
			i=link[i];
		}
	}
	while (!q.empty());
	while (!q.empty()) q.pop();
	q.push(y);
	do
	{
		int t=q.front();
		q.pop();
		int i=head[t];
		while (i!=0)
		{
			if (d2[adj[i]]>d2[t]+1)
			{
				d2[adj[i]]=d2[t]+1;
				q.push(adj[i]);
			}
			i=link[i];
		}
	}
	while (!q.empty());
	int res=0;
	for (int i=1; i<=n; i++)
		if (min(d1[i],d2[i])<=diameter) res++;
	return res;
}
void solve()
{
	int res=0;
	if (k%2==0)
	{
		for (int i=1; i<=n; i++)
			res=max(res,bfs(i,k/2));
	}
	else
	{
		for (int i=1; i<=n; i++)
		{
			int j=head[i];
			while (j!=0)
			{
				res=max(res,bfs2(i,adj[j],k/2));
				j=link[j];
			}
		}
	}
	cout << n-res;
}
int main()
{
	ios_base::sync_with_stdio(0);
	//freopen("C.inp","r",stdin);
	//freopen("C.out","w",stdout);
	enter();
	solve();
	return 0;
}

#include <cstdio>
using namespace std;
const int N=2005;
const int M=4005;
int n,i,k,u,v;
int h[N],nx[M],to[M],cnt;
int f[N][N],ans;
void addedge(int u,int v)
{
	cnt++;
	to[cnt]=v;
	nx[cnt]=h[u];
	h[u]=cnt;
}
void up(int u,int p)
{
	f[u][0]=1;
	for (int i=h[u];i;i=nx[i])
		if (to[i]!=p)
		{
			up(to[i],u);
			for (int j=0;f[to[i]][j];j++)
				f[u][j+1]+=f[to[i]][j];
		}
}
void down(int u,int p)
{
	for (int i=h[u];i;i=nx[i])
		if (to[i]!=p)
		{
			for (int j=0;f[u][j];j++)
				f[to[i]][j+1]+=f[u][j]-(j-1>=0?f[to[i]][j-1]:0);
			down(to[i],u);
		}
}
void getans(int u,int p)
{
	if ((k&1)^1)
	{
		int t=0;
		for (int i=0;i<=k/2;i++)
			t+=f[u][i];
		if (n-t<ans)
			ans=n-t;
	}
	for (int i=h[u];i;i=nx[i])
		if (to[i]!=p)
		{
			getans(to[i],u);
			if (k&1)
			{
				int t=0;
				for (int j=0;j<=k/2;j++)
					t+=f[to[i]][j];
				for (int j=0;j<=k/2;j++)
					t+=f[u][j]-(j-1>=0?f[to[i]][j-1]:0);
				if (n-t<ans)
					ans=n-t;
			}
		}
}
int main()
{
	scanf("%d%d",&n,&k);
	for (i=1;i<n;i++)
	{
		scanf("%d%d",&u,&v);
		addedge(u,v);
		addedge(v,u);
	}
	ans=n;
	up(1,0);
	if ((k&1)^1)
		down(1,0);
	getans(1,0);
	printf("%d\n",ans);
	return 0;
}

