// kが偶数なら点、奇数なら辺を中心にして、そこからの距離がk/2を超える点を全部消せばok
int n, k, a[2020], b[2020], d[2020], res = inf;
vector<int> e[2020];

void rec(int v) {
	each(i,e[v]) if (d[i]==-1) d[i] = d[v]+1, rec(i);
}

void ev() {
	rep(i,n) {
		rep(j,n) d[j] = -1;
		d[i] = 0;
		rec(i);
		int cnt = 0;
		rep(j,n) if (d[j]>k/2) cnt++;
		chmin(res, cnt);
	}
}

void od() {
	rep(i,n-1) {
		rep(j,n) d[j] = -1;
		d[a[i]] = d[b[i]] = 0;
		rec(a[i]), rec(b[i]);
		int cnt = 0;
		rep(j,n) if (d[j]>k/2) cnt++;
		chmin(res, cnt);
	}
}

signed main() {
	cin >> n >> k;
	rep(i,n-1) {
		cin >> a[i] >> b[i];
		a[i]--, b[i]--;
		e[a[i]].push_back(b[i]), e[b[i]].push_back(a[i]);
	}
	if (k%2==0) ev();
	else od();
	cout << res << endl;
}

