const int MAXN = 2000 + 5;

struct Tree {
  int hed[MAXN], nxt[MAXN * 2], to[MAXN * 2], fa[MAXN], size[MAXN], f[MAXN][MAXN], g[MAXN][MAXN], cnt;

  void addEdge(int u, int v) {
    ++ cnt;
    to[cnt] = v;
    nxt[cnt] = hed[u];
    hed[u] = cnt;
  }

  void DFS(int u) {
    size[u] = 1;
    f[u][1] = 0;
    g[u][1] = 0;
