        --a; --b;
        G[a].push_back(b);
        G[b].push_back(a);
    }

    auto lca = LCA(G);

    vi cnt(N);
    vector<tuple<int, int, int>> vs;
    rep(i, N)FOR(j, i+1, N){
        int d = lca.distance(i, j);
        if(d > K){
            cnt[i]++;
            cnt[j]++;
            vs.emplace_back(d, i, j);
        }
    }

    vi rem(N);
    sort(all(vs), greater<tuple<int, int, int> >());
    each(a, vs){
