int dfs(int e,int x,int t){
    int mem=mpp[e*1e10+x*1e5+t];
    if(mem)return mem;
    int res=1;
    if(t>k)return 0;
    int sum=0;
    int v[2010];
    int cnt=0;
    for(auto s:G[e]){
        if(s!=x){
            v[cnt]=dfs2(s,e,min(t,k-t)-1);
            sum+=v[cnt];
            cnt++;
        }
    }
    int now=0;
    for(auto s:G[e]){
        if(s==x)continue;
        int tmp=sum-v[now];
        res=max(res,1+tmp+dfs(s,e,t+1));
        now++;
    }
    return mpp[e*1e10+x*1e5+t]=res;
}
