void BFS(int u)
{
	mark.clear();
	mark[u] = true;
	q.push_back(u);	
	p[u] = 1;
	while(!q.empty())
	{
		int x = q.back();
		q.pop_back();
		for(int i = 0; i < adj[x].size(); i++)
