#include <bits/stdc++.h>

using namespace std;


vector<int> g[2000];

pair<int, int> dfs(int start, int cur, int prev, int tot) {

    pair<int, int> res = {tot, cur};
    for (auto &&c: g[cur]) {
        if (prev != c) res = max(res, dfs(start, c, cur, tot + 1));
    }
    return res;
}

void collect(int start, int cur, int prev, int tot, vector<int> &res) {
    if (tot == 0) {
        res.push_back(cur);
    }
    for (auto &&c: g[cur]) {
        if (prev != c) collect(start, c, cur, tot - 1, res);
    }
}


bool dead[2000];

int random_v(){
    for(int i = 0 ; i < 2000 ; i++)
        if( !dead[i] )
            return i;
    return -1;
}


pair<int, pair<int, int> > f() {
    int s = random_v();
    assert(s != -1);
    pair<int, int> res1 = dfs(s, s, -1, 0);
    pair<int, int> res2 = dfs(res1.second, res1.second, -1, 0);
    return {res2.first, {res1.second, res2.second}};
}

void del(int x){
    for(int i = 0 ; i < 2000 ; i++){
        auto it = find(g[i].begin(), g[i].end(), x);
        if( it != g[i].end() ){
            g[i].erase(it);
        }
    }
}
int step(int K) {
    auto r = f();
    if( r.first <= K ) return true;

    vector<int> r1;
    collect(r.second.first, r.second.first, -1, r.first, r1);
    vector<int> r2;
    collect(r.second.second, r.second.second, -1, r.first, r2);
    if( r1.size() > r2.size() ) swap(r1, r2);

    for( auto i : r1 ) {
        dead[i] = true;
        del(i);
    }
    return false;
}


void solve(long long N, long long K, vector<long long> A, vector<long long> B) {
    for (int i = 0; i < A.size(); i++) {
        A[i]--;
        B[i]--;
        g[A[i]].push_back(B[i]);
        g[B[i]].push_back(A[i]);
    }
    while(true){
        if( step(K) ){
            break;
        }
    }
    cout << count(dead, dead + 2000, true) << endl;

}

int main() {
    long long N;
    scanf("%lld", &N);
    long long K;
