using namespace std;
vector<int> edge[2010];
int dis[2010];
bool used[2010];
int n, k;

void evencalc(int t, int s, int count) {
	used[t] = true;
	int r;
	if (count > (int)k / 2)dis[s]++;
	bool flag = false;
	for (int i = 0; i < edge[t].size() ; i++) {
		if (used[edge[t][i]] == true)continue;
		evencalc(r, s, count + 1);
		flag = true;
	}
	if (!flag)return;
}

int oddcalc(int t, int s) {
	used[t] = used[s] = true;
	evencalc(t, t, 0);
	evencalc(s, s, 0);
	return dis[t] + dis[s];
}

