		edge[b].push_back(a);
	}
	if (k % 2 == 0) {
		for (int i = 0; i < n; i++) {
			evencalc(i, i, 0);
			ma = min(ma, dis[i]);
			for (int i = 0; i < n; i++)used[i] = false;
