const int INF = 10000010;
const int N = 4040;

int n, k;
int ans = N;
int topQ;
int q[N];
int dist[N];
vector<int> G[N];

void BFS() {

	rep(k, topQ) {
		int v = q[k];
		for(auto u : G[v]) {
			int w = dist[v] + 2;
			if(dist[u] <= w) {
                continue;
            } 
			dist[u] = w;
			q[topQ++] = u;
		}
	}

	return;
}

int solveVertex(int v) {

	rep(i, n) {
        dist[i] = INF;
    }

	dist[v] = 0;
	topQ = 0;
	q[topQ++] = v;

	BFS();

	int res = 0;
	rep(i, n) {
        if(dist[i] > k) {
            res++;
        }
    }

	return res;
}

int solveEdge(int v, int u) {

	rep(i, n) {
		dist[i] = INF;
	}

	dist[v] = dist[u] = 1;
	topQ = 0;
	q[topQ++] = v;
	q[topQ++] = u;

	BFS();

	int res = 0;
	rep(i, n) {
		if(dist[i] > k) {
			res++;
		}
	}

	return res;
}

