	}

	rep(v, n) {
		ans = min(ans, solveVertex(v));
	}

	rep(v, n) {
		for(auto u : G[v]) {
			if(u > v) {
				ans = min(ans, solveEdge(v, u));
			}
		}
	}

	cout << ans << endl;
	return 0;
}

