#include <bits/stdc++.h>
using namespace std;

const int N = 2001;
const int INF = 1e9;
vector<int> edges[N];
int blocked[N];
int n, k;

vector<int> bfs(int s) {
    vector<int> d(n + 1, INF);
    d[s] = 0;
    queue<int> q;
    q.push(s);
    while (!q.empty()) {
        int v = q.front();
        q.pop();
        for (auto u : edges[v]) {
            if (blocked[u])
                continue;
            if (d[u] > d[v] + 1) {
                d[u] = d[v] + 1;
                q.push(u);
            }
        }
    }
    return d;
}

int notBlocked() {
    for (int i = 1; i <= n; i++) {
        if (!blocked[i])
            return i;
    }
}

int diameter() {
    int ans = 0;
    while (true) {
        int fromFirst = notBlocked();
        vector<int> distFirst = bfs(fromFirst);
        int farFirst = fromFirst;
        for (int i = 1; i <= n; i++) {
            if (blocked[i])
                continue;
            if (distFirst[i] > distFirst[farFirst])
                farFirst = i;
        }

        vector<int> distSecond = bfs(farFirst);
        int farSecond = farFirst;
        for (int i = 1; i <= n; i++) {
            if (blocked[i])
                continue;
            if (distSecond[i] > distSecond[farSecond])
                farSecond = i;
        }

        if (distSecond[farSecond] <= k) {
            break;
        }

        for (int i = 1; i <= n; i++) {
            if (blocked[i])
                continue;
            if (distSecond[i] == distSecond[farSecond]) {
                blocked[i] = 1;
                ans++;
            }
        }
    }
    return ans;
}

void solve() {
    cin >> n >> k;
    for (int i = 0; i < n - 1; i++) {
        int v, u;
        cin >> v >> u;
        edges[v].push_back(u);
        edges[u].push_back(v);
    }

    cout << diameter();
}

int main() {
    ios::sync_with_stdio(NULL), cin.tie(0), cout.tie(0);
    cout.setf(ios::fixed), cout.precision(20);
    solve();
    return 0;
}

#include <iostream>
