void evencalc(int t, int s, int count) {
	int r;
	if (count > (int)k / 2)dis[s]++;
	if (edge[t].empty())return;
	for (int i = 0; i < edge[t].size() && !used[edge[t][i]]; i++) {
		r = edge[t][i];
		used[edge[t][i]] = true;
		evencalc(r, s, count + 1);
	}
}

int oddcalc(int t, int s) {
	used[t] = used[s] = true;
	evencalc(t, t, 0);
	evencalc(s, s, 0);
	return dis[t] + dis[s];
}

