void dfs(int v) {
  used[v] = true;
  vector < int > child;
  child.clear();
  for (auto u : q[v]) {
    if (!used[u]) {
      dfs(u);
      cnt[v] += cnt[u];
      child.push_back(u);
    }
  }
  cnt[v]++;
  int sum[n + 1];
  for (int i = 0; i <= n; i++) {
    sum[i] = 0;
    for (auto u : child) {
      sum[i] += g[u][i];
    }
  }
  f[v][0] = cnt[v];
  f[v][1] = cnt[v] - 1;
  int m = child.size();
  for (int i = 2; i <= k; i++) {
    for (auto u : child) {
      int j = min(k - i, i - 1);
      f[v][i] = min(f[v][i], f[u][i - 1] + sum[j] - g[u][j]);
    }
  }
  if (child.size() == 0) {
    for (int j = 1; j <= n; j++)
      f[v][j] = 0;
  }
  g[v][0] = f[v][0];
  for (int i = 1; i <= n; i++)
      g[v][i] = min(f[v][i - 1], f[v][i]);
}

