void dfs(vvi &g, vvi &dp, int v, int p) {
	dp[v][0] = 1;
	REP(i, g[v].size()) {
		if (g[v][i] == p)continue;
		dfs(g, dp, g[v][i], v);
		REP(j, dp[g[v][i]].size()) {
			if (dp[g[v][i]][j] == 0)break;
			dp[v][j + 1] += dp[g[v][i]][j];
		}
	}
