	int n = g.size();
	queue<int> q;
	q.push(s);
	vi d(n, INF);
	d[s] = 0;
	while (!q.empty()) {
		int p = q.front(); q.pop();
		REP(i, g[p].size()) {
			if (d[g[p][i]] == INF) {
				d[g[p][i]] = d[p] + 1;
				q.push(g[p][i]);
			}
		}
	}
	int pos = -1, tmp = 0;
	REP(i, n) {
		if (chmax(tmp, d[i])) {
			pos = i;
		}
	}
	return pos;
}
int diam(vvi &g) {
	int s = f(g, 0);
	int t = f(g, s);
	queue<int> q;
