	dist[root] = 0;

	int cnt = 1;
	while(!que.empty()) {
		int x = que.front(); que.pop();

		for(int to : graph[x]) {
			if(!used[to] && dist[x] < K / 2) {
				used[to] = 1;
				dist[to] = dist[x] + 1;
				que.push(to);
				cnt++;
			}
		}
	}

	return N - cnt;
}

int bfs2(int root1, int root2)
{
	vector<int> used(N);
	vector<int> dist(N);

	queue<int> que;
	que.push(root1);
	que.push(root2);
	used[root1] = 1;
	dist[root1] = 0;
	used[root2] = 1;
	dist[root2] = 0;

	int cnt = 2;
	while(!que.empty()) {
		int x = que.front(); que.pop();

		for(int to : graph[x]) {
			if(!used[to] && dist[x] < K / 2) {
				used[to] = 1;
				dist[to] = dist[x] + 1;
				que.push(to);
				cnt++;
			}
		}
	}

	return N - cnt;
}

