void rootTr ( int x ) {
    sz[x] = 1;
    for ( int i = 0 ; i < chs[x].size() ; i ++ ) {
        if ( chs[x][i] == p[x] ) {
            swap( chs[x][i], chs[x][ chs[x].size()-1 ] );
            chs[x].pop_back();
            i --;
        }else {
            p[ chs[x][i] ] = x;
            rootTr ( chs[x][i] );
            sz[x] += sz[ chs[x][i] ];
        }
    }
}

void solve ( int x ) {
    for ( int i = 0 ; i < chs[x].size() ; i ++ ) {
        solve( chs[x][i] );
    }
    dp[x][0] = sz[x];
    dp[x][1] = sz[x]-1;

    for ( int l = 2 ; l <= k+1 ; l ++ ) {
        dp[x][l] = dp[x][l-1];

        int sum = 0;
        for ( int i = 0 ; i < chs[x].size() ; i ++ ) {
            sum += dp[ chs[x][i] ][ min( k-l+1, l-1 ) ];
        }
        for ( int i = 0 ; i < chs[x].size() ; i ++ ) {
            int nSum = sum - dp[ chs[x][i] ][ min( k-l+1, l-1 ) ] + dp[ chs[x][i] ][ l-1 ];
            dp[x][l] = min( dp[x][l], nSum );
        }

    }
}

