vector<vector<int>> dp;
vector<int> result;

void BuildResult(int v, int pr) {
    for (int u : g[v]) {
        if (u == pr) {
            continue;
        }

        BuildResult(u, v);
    }
    vector<int> buf[2];
    int curPtr = 0;
    buf[curPtr].assign(k + 1, -1);
    buf[curPtr][0] = 1;
    for (int u : g[v]) {
        if (u == pr) {
            continue;
        }

        int nxtPtr = 1 - curPtr;
        buf[nxtPtr] = buf[curPtr];

        for (int h1 = 0; h1 <= k; ++h1) {
            if (buf[curPtr][h1] == -1) {
                continue;
            }
            for (int h2 = 0; h2 < k; ++h2) {
                if (dp[u][h2] == -1) {
                    continue;
                }

                if (h1 + h2 + 1 > k) {
                    continue;
                }

                int newH = max(h1, h2 + 1);

                if (buf[nxtPtr][newH] == -1 || buf[curPtr][h1] + dp[u][h2] > buf[nxtPtr][newH]) {
                    buf[nxtPtr][newH] = buf[curPtr][h1] + dp[u][h2];
                }
            }
        }

        swap(curPtr, nxtPtr);
    }
    for (int h = 0; h <= k; ++h) {
        dp[v][h] = buf[curPtr][h];
    }
    for (int h = 0; h <= k; ++h) {
        if (dp[v][h] == -1) {
            continue;
        }
        int curResult = n - dp[v][h];
        if (result[v] == -1 || curResult < result[v]) {
            result[v] = curResult;
        }
    }
    for (int u : g[v]) {
        if (u == pr) {
            continue;
        }

        if (result[u] != -1) {
            if (result[v] == -1 || result[u] < result[v]) {
                result[v] = result[u];
            }
        }
    }
}

