const int N = 2002;

vi g[N];
int P[N], dep[N];

int X[N][N];

int dfs(int c, int p, int d) {
  dep[c] = d;
  P[c] = p;
  int res = c;
  rep(i,0,g[c].size()) {
    int u = g[c][i];
    if(u == p) continue;
    int f = dfs(u, c, d+1);
    if(dep[f] > dep[res]) {
      res = f;
    }
  }
  return res;
}

void dfs1(int c, int p1, int p2, int d, int s) {
  X[s][d]++;
  rep(i,0,g[c].size()) {
    int u = g[c][i];
    if(u == p1 || u == p2) continue;
    dfs1(u, c, c, d+1, s);
  }
}

void dfs2(int c, int p) {
  P[c] = p;
  rep(i,0,g[c].size()) {
    int u = g[c][i];
    if(u == p) continue;
    dfs2(u, c);
  }
}

int main() {
  int n,k;
  S2(n,k);
  rep(i,0,n-1) {
    int u,v;
    S2(u,v);
    g[u].push_back(v);
    g[v].push_back(u);
  }
  int c = dfs(1, -1, 0);
  int d = dfs(c, -1, 0);

  int ans = n + 1;
  vi cand;
  cand.push_back(c);
  rep(it,1,n+1) if(dep[it] == dep[d]) {
    cand.push_back(it);
  }

  rep(a,0,cand.size()) rep(b,a+1,cand.size()) if(a != b) {
    c = cand[a];
    d = cand[b];
    dfs2(c, -1);
    // printf("%d %d\n",c,d);
    vi path;
    memset(X, 0, sizeof(X));
    int tmp = d;
    while(tmp != -1) {
      path.push_back(tmp);
      tmp = P[tmp];
    }

    if(path.size() <= k + 1) {
      P(0);
      return 0;
    }

    rep(i,0,path.size()) {
      int c = path[i];
      dfs1(c, (i + 1 < path.size()) ? path[i+1] : -1, i ? path[i-1] : -1, 0, c);
      for(int j = n - 1; j >= 0; j--) X[c][j] += X[c][j+1];
    }

    for(int i = 0; i + k < path.size(); i++) {
      int tmp = 0;
      rep(j,0,path.size()) {
        if(j < i || j > i + k) {
          tmp += X[path[j]][0];
          continue;
        }
        tmp += X[path[j]][min(j - i, i + k - j) + 1];
      }
      ans = min(ans, tmp);
    }
  }
  P(ans);

  return 0;
}

