const int maxn=2010;
int n,k,tans,ans,x,y;
bool vis[maxn];
vector <int> e[maxn];
priority_queue <int> Q[maxn];
struct cmp{
	bool operator()(const int &t1,const int &t2){return Q[t1].top()<Q[t2].top();}
};
priority_queue <int,vector<int>,cmp> Qmax;
void dfs(int root,int node,int dep){
	//cout<<node<<endl;
	Q[root].push(dep);
	vis[node]=1;
	for(int i=0;i<e[node].size();++i)
		if(!vis[e[node][i]])dfs(root,e[node][i],dep+1);
}
int main(){
	scanf("%d%d",&n,&k);
	for(int i=1;i<n;++i){
		scanf("%d%d",&x,&y);
		e[x].push_back(y);
		e[y].push_back(x);
	}
	ans=n-k-1;
	for(int i=1;i<=n;++i){
		for(;!Qmax.empty();Qmax.pop());
		if(e[i].size()<2)continue;
		tans=0;
		memset(vis,0,sizeof(vis));
		vis[i]=1;
		for(int j=0;j<e[i].size();++j){
			int t=e[i][j];
			for(;!Q[t].empty();Q[t].pop());
			dfs(t,t,1);
			Qmax.push(t);
		}
		int now=Qmax.top();
		Qmax.pop();
		int sec=Qmax.top();
		for(;Q[now].top()+Q[sec].top()>k;++tans){
			Q[now].pop();
			Qmax.push(now);
			now=Qmax.top();
			Qmax.pop();
			sec=Qmax.top();
		}
		ans=min(ans,tans);
	}
	printf("%d\n",ans);
	return 0;
}

