int N,K;
const int MAX_N=2010;

mat path,farNodes;

int a[20][MAX_N],h[MAX_N];
int chk[MAX_N];

int tree[4*MAX_N],treeV[4*MAX_N],sz;

void init(){
	for(sz=1;sz<N;sz<<=1);
	sz--;
	for(int i=1;i<=N;i++)treeV[i+sz]=i;
}

void update(int x,int c){
	x+=sz;
	tree[x]+=c;
	x>>=1;
	while(x){
		tree[x]=tree[x*2+1];
		treeV[x]=treeV[x*2+1];
		if(tree[x]<tree[x*2]){
			tree[x]=tree[x*2];
			treeV[x]=treeV[x*2];
		}
		x>>=1;
	}
}

int query(){
	return treeV[1];
}

void bfs(){
	queue<int> Q;
	Q.push(1);
	h[1]=1;
	a[0][1]=1;
	while(!Q.empty()){
		int v=Q.front();Q.pop();
		for(auto& u:path[v]){
			if(h[u])continue;
			Q.push(u);
			h[u]=h[v]+1;
			a[0][u]=v;
		}
	}
	for(int i=1;i<20;i++){
		for(int j=1;j<=N;j++){
			a[i][j]=a[i-1][a[i-1][j]];
		}
	}
}

int dist(int x,int y){
	if(h[x]<h[y])swap(x,y);
	int dif=h[x]-h[y];
	int ret=0;
	for(int i=0;i<20;i++){
		if(dif>>i&1){
			x=a[i][x];
			ret+=1<<i;
		}
	}
	for(int i=19;i>=0;i--){
		if(a[i][x]!=a[i][y]){
			x=a[i][x];
			y=a[i][y];
			ret+=2<<i;
		}
	}

	if(x==y)return ret;
	return ret+2;
}

int main(){
	scanf("%d%d",&N,&K);
	path.assign(N+1,vec());
	farNodes.assign(N+1,vec());

	for(int i=0,x,y;i<N-1;i++){
		scanf("%d%d",&x,&y);
		path[x].pb(y);
		path[y].pb(x);
	}

	bfs();
	init();

	for(int i=1;i<=N;i++){
		for(int j=i+1;j<=N;j++){
			if(dist(i,j)>K){
				farNodes[i].pb(j);
				farNodes[j].pb(i);
				chk[i]++;
				chk[j]++;
			}
		}
	}

	for(int i=1;i<=N;i++){
		update(i,chk[i]);
	}

	int ans=0;
	while(chk[query()]>0){
		int v = query();ans++;
		update(v,-chk[v]);
		chk[v]=0;
		for(auto& u:farNodes[v]){
			if(chk[u]>0){
				update(u,-1);
				chk[u]--;
			}
		}
	}

	printf("%d\n",ans);

	return 0;
}

