void gdfs(int p, int v, vector<vi> &g){
  FOR(e, g[v]){
    if((*e) == p) continue;
    gdfs(v, (*e), g);
  }
  gdp[v][0] = 1;
  REP(i, n){
    if(!i){
      FOR(e, g[v]){
        if((*e) == p) continue;
        gdp[v][0] += gdp[(*e)][0];
      }
    }
    else if(i - 1 <= k / 2){
      FOR(e, g[v]){
        if((*e) == p) continue;
        gdp[v][i] += gdp[(*e)][i-1];
      }
    } else {
      int l = 0;
      FOR(e, g[v]){
        if((*e) == p) continue;
        gdp[v][i] += gdp[(*e)][max(0, (k-(i-1)))];
        l = min(l, gdp[(*e)][i-1] - gdp[(*e)][max(0, (k-(i-1)))]);
      }
      gdp[v][i] += l;
    }
  }
  // min_cost
  int m = g[v].size();
  for(int x = 0; x <= (k / 2); x++){
    int cost = n - gdp[v][0];
    FOR(e, g[v]){
      if((*e) == p) continue;
      cost += gdp[(*e)][x];
    }
    int y = k - x;
    //cout << "cost" << v << " " << x << " " << cost << endl;
    FOR(e, g[v]){
      if((*e) == p) continue;
      cost -= gdp[(*e)][x];
