    v--;
    g.AddEdge(u, v);
    g.AddEdge(v, u);
  }
  int ans = 1e9;
  for (int i = 0; i < n; ++i)
  {
    ans = min(ans, n - dfs(i, g, k));
  }
  //cout << dfs(1, g, k) << endl;
  cout << ans << endl;
}

