                int e=node[l].to;
                if(e<=i)continue;
                int temp=ct(i,e,k/2)+ct(e,i,k/2);
                ans=max(ans,temp);
            }
        }
    }
    else{
        for(i=1;i<=n;++i){
            ans=max(ans,ct(i,-1,k/2));
        }
    }
    printf("%d\n",n-ans);
    return 0;
}

