using Tree = vec<vec<int>>;
bool deleted[2020];
struct DistHelper {
  const Tree& tree;
  vec<int> dist;
  DistHelper(const Tree& tree) : tree(tree), dist(tree.size(), -inf) {}
  vec<int> build(int root) {
    dfs(root);
    return dist;
  }
  void dfs(int v, int p = -1, int d = 0) {
    dist[v] = d;
    for (int u : tree[v]) {
      if (u == p) continue;
      if (deleted[u]) continue;
      dfs(u, v, d + 1);
    }
  }
};

signed main() {
  int N = in(), K = in();
  Tree tree(N);
  REP(i, N - 1) {
    int A = in() - 1, B = in() - 1;
    tree[A].pb(B);
    tree[B].pb(A);
  }
  int ans = 0;
  while (1) {
    int r;
    REP(i, N) {
      if (not deleted[i]) {
        r = i;
        break;
      }
    }
    auto dist = DistHelper(tree).build(r);
    int a = max_element(ALL(dist)) - dist.begin();
    auto dista = DistHelper(tree).build(a);
    int b = max_element(ALL(dista)) - dista.begin();
    auto distb = DistHelper(tree).build(b);

    int diam = dista[b];

    if (diam <= K) break;
    int cnt = 0;
    for (int x : dist) {
      if (x == -inf) continue;
      cnt++;
    }
    assert(cnt == N - ans);
    int maxa = std::count(ALL(dista), diam);
    int maxb = std::count(ALL(distb), diam);
    if (maxa < maxb) {
      deleted[b] = true;
    } else {
      deleted[a] = true;
    }
    ans++;
  }
  cout << ans << endl;
  return 0;
}

