        chmax(bt, max(l, m));
        chmin(tmp2[max(l, m)], tmp[m] + dp[e][l]);
      }
    }
    swap(tmp, tmp2);
    b = bt;
  }
  rep(j, b + 1){
    dp[i][j+1] = tmp[j];
  }
  dp[i][0] = siz[i];
  //rep(j, b + 2)cerr << i << " " << j << " " << dp[i][j] << endl;
}

