        G[a].push_back(b);
        G[b].push_back(a);
    }

    auto lca = LCA(G);

    vi cnt(N);
    vector<vi> ngs(N, vi(N));
    int ng = 0;
    rep(i, N)FOR(j, i+1, N){
        int d = lca.distance(i, j);
        if(d > K){
            cnt[i]++;
            cnt[j]++;
            ngs[i][j] = 1;
            ngs[j][i] = 1;
            ++ng;
        }
    }

    vector<pii> vs(N);
    rep(i, N)
        vs[i] = mp(cnt[i], i);
    sort(vs.rbegin(), vs.rend());

    int ans = 0;
