    	for (int j = 0; j <= k; ++j) {
    		dp[i][j] = INF;
    	}
    }

    dfs(1, -1);
    int ans = n;

    for (int i = 0; i <= k; ++i) {
    	ans = min(ans, dp[1][i]);    
    }

    printf("%d\n", ans);
}

