auto dfs_tree(int root, const vector<vector<int>>& g) {
    stack<int> h;
    h.push(root);
    int n = g.size();
    vector<int> dist(n), pi(n, -1);
    while(!h.empty()) {
        int u = h.top();
        h.pop();
        for(auto v : g[u]) {
            if(pi[u] != v) {
                pi[v] = u;
                h.push(v);
                assert(dist[v] == 0);
                dist[v] = dist[u] + 1;
            }
        }
    }
    return make_tuple(dist, pi);
}
