void spoji (int a, int b) {
    for (int d = 0; d * 2 < k; d++) {
        tmp[d] = dp[a][d] + dp[b][d];
    }
    for (int d = (k + 1)/2; d <= k; d++) {
        tmp[d] = min(dp[a][d] + dp[b][k - d], dp[a][k - d] + dp[b][d]);
        tmp[d] = min(tmp[d-1], tmp[d]);
    }
    for (int i=0; i<=k; i++) {
        dp[a][i] = tmp[i];
    }
