            for(int w = 1; w <= n; w++) vis[w] = 0;

            int v = edges[e].first,
                w = edges[e].second;
            vis[v] = vis[w] = 1;

            int av = get_tree_size(v, 0),
                aw = get_tree_size(w, 0);
            ans = min(ans, n - (av + aw));
        }
    }
    cout << ans << '\n';

    return 0;
}

