#include <bits/stdc++.h>

constexpr int nax = 2e3;

using namespace std;
using Graph = array< vector< int >, nax + 1 >;
using Ain = array< int, nax + 1 >;

struct Dfs
{
    const int n, r;
    const Graph& gr;
    Dfs(const int n, const int r, const Graph& gr) : n(n), r(r), gr(gr) {}

    Ain gl{}, kd{};

    pair< Ain, Ain > operator()()
    {
        dfs(r, r);
        return make_pair(gl, kd);
    }

    void dfs(int v, int oj)
    {
        gl[v] = gl[oj] + 1;
        for (int s : gr[v])
            if (s != oj)
                dfs(s, v), ++kd[v];
    }

};

int analyze(const int n, const int k, const Ain& gl, const Ain& kd)
{
    int len = (k / 2);
    int cnt = 0;
    for (int i = 1; i <= n; ++i)
        if (gl[i] - 1 > len)
            ++cnt;

    if (k & 1)
    {
        int naj = 0;
        for (int i = 1; i <= n; ++i)
            if (gl[i] - 1 == len)
                naj = max(naj, kd[i]);
        cnt -= naj;
    }

    return cnt;
}

int solve(const int n, const int k, const Graph& gr)
{
    if (k == 1) return n - 2;

    int res = n;
    for (int i = 1; i <= n; ++i)
    {
        Ain gl, kd;
        tie(gl, kd) = Dfs(n, i, gr)();

        cout << i << ": ";
        for (int i = 1; i <= n; ++i)
            cout << gl[i] << ' ';
        cout << '\n';


        res = min(res, analyze(n, k, gl, kd));
    }
    return res;
}


int main()
{
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, k;

    cin >> n >> k;

    Graph gr;

    for (int i = 0; i < n - 1; ++i)
    {
        int p, q; cin >> p >> q;
        gr[p].push_back(q);
        gr[q].push_back(p);
    }

    cout << solve(n, k, gr) << '\n';
}

