				else if (j + j <= d) w[u][j] = max(w[u][j], f[u][j]);
				else {
					int t = f[u][d - j] - f[v][d - j - 1] + f[v][j - 1];
					w[u][j] = max(w[u][j], t);
				}
			}
		}
	}
