int bfs(int s,int diameter)
{
	for (int i=1; i<=n; i++)
		d[i]=oo;
	d[s]=0;
	queue<int> q;
	q.push(s);
	int res=1;
	do
	{
		int t=q.front();
		q.pop();
		if (d[t]==diameter) break;
		int i=head[t];
		while (i!=0)
		{
			if (d[adj[i]]>d[t]+1)
			{
				if (d[adj[i]]==oo) res++;
				d[adj[i]]=d[t]+1;
				q.push(adj[i]);
			}
			i=link[i];
		}
	}
	while (!q.empty());
	return res;
}
int bfs2(int x,int y,int diameter)
{
	for (int i=1; i<=n; i++)
		d1[i]=oo;
	d1[x]=0;
	for (int i=1; i<=n; i++)
		d2[i]=oo;
	d2[y]=0;
	queue<int> q;
	q.push(x);
	do
	{
		int t=q.front();
		q.pop();
		int i=head[t];
		while (i!=0)
		{
			if (d1[adj[i]]>d1[t]+1)
			{
				d1[adj[i]]=d1[t]+1;
				q.push(adj[i]);
			}
			i=link[i];
		}
	}
	while (!q.empty());
	while (!q.empty()) q.pop();
	q.push(y);
	do
	{
		int t=q.front();
		q.pop();
		int i=head[t];
		while (i!=0)
		{
			if (d2[adj[i]]>d2[t]+1)
			{
				d2[adj[i]]=d2[t]+1;
				q.push(adj[i]);
			}
			i=link[i];
		}
	}
	while (!q.empty());
	int res=0;
	for (int i=1; i<=n; i++)
		if (max(d1[i],d2[i])<=diameter) res++;
	return res;
}
void solve()
{
	int res=0;
	if (k%2==0)
	{
		for (int i=1; i<=n; i++)
			res=max(res,bfs(i,k/2));
	}
	else
	{
		for (int i=1; i<=n; i++)
		{
			int j=head[i];
			while (j!=0)
			{
				res=max(res,bfs2(i,adj[j],k/2));
				j=link[j];
			}
		}
	}
	cout << n-res;
}
