constexpr int INF = (1 << 30) - 1;

int N, K;
vector < int > G[2005];
int flag[2005];

Pi searchDepth(int node, int value)
{
    int ret = 0, maxv = 0;
    priority_queue < int > pq;
    if ( flag[node] == value ) return ( Pi(0, 0) );
    flag[node] = value;

    for ( auto &to : G[node] ) {
        auto dat = searchDepth(to, value);
        pq.push(dat.first);
        maxv = max(maxv, dat.second);
    }
    if ( !pq.empty() ) { ret = pq.top(); maxv = max(maxv, ret + 1); pq.pop(); }
    if ( !pq.empty() ) { maxv = max(maxv, ret + pq.top()); }

    return ( Pi(ret + 1, maxv) );
}

int calcNum(int node, int value)
{
    int ret = 1;
    if ( flag[node] == value ) return ( 0 );
    flag[node] = value;
    for ( auto &to : G[node] ) ret += calcNum(to, value);
    return ( ret );
}

int main()
{
    cin >> N >> K;
    memset(flag, -1, sizeof(flag)); 
    for ( int i = 0; i < N - 1; i++ ) {
        int a, b;
        cin >> a >> b; --a, --b;
        G[a].push_back(b);
        G[b].push_back(a);
    }

    int minv = INF;
    int cnt = 0;
    for ( int root = 0; root < N; root++ ) {
        vector < int > vec1, vec2;

        for ( auto &to : G[root] ) {
            flag[root] = ++cnt;
            if ( searchDepth(to, cnt).second > K ) {
                flag[root] = ++cnt;
                vec2.push_back(calcNum(to, cnt));
            } else {
                flag[root] = ++cnt;
                vec1.push_back(calcNum(to, cnt));
            }
        }

        sort(begin(vec1), end(vec1));

        if ( vec1.size() == 0 ) continue;

        int sum = 0;
        for ( int i = 0; i < vec1.size() - 1; i++ ) sum += vec1[i];
        for ( int i = 0; i < vec2.size(); i++ ) sum += vec2[i];
        minv = min(minv, sum);
    }

    cout << minv << endl;

    return ( 0 );
}

