const int N = 1e5 + 100;

vector<int> G[N];
int n, K;
bool del[N];
void DFS(int u, int fa, int val, int &maxn, int &to) {
	if(maxn < val) {
		maxn = val;
		to = u;
	}	
	for(auto v: G[u]) {
		if(v == fa || del[v]) continue;
		DFS(v, u, val + 1, maxn, to);
	}
}

vector<int> A, B;
void DFS(int u, int fa, int val, int &maxn, vector<int> &C) {
	if(val == maxn) C.PB(u);
	for(int v: G[u]) {
		if(v == fa || del[v]) continue;
		DFS(v, u, val + 1, maxn, C);
	}
}

int BFS(int &s, int &g) {
	REP(u, 1, n + 1) if(del[u] == 0) { s = u; break; }
	int maxn = 0;
	DFS(s, s, 0, maxn, g);
	maxn = 0;
	DFS(g, g, 0, maxn, s);
	return maxn;
}

int main() {
	RD(n), RD(K);
	REP(i, 1, n) {
		int u, v;
		RD(u), RD(v);
		G[u].PB(v);
		G[v].PB(u);
	}
	int ans = 0;
	while(true) {
		int s = 0, g = 0;
		int len = BFS(s, g);
		if(len <= K) break;
		A.clear();
		DFS(s, s, 0, len, A);
		B.clear();
		DFS(g, g, 0, len, B);
		if(A.size() < B.size()) {
			ans += A.size();
			for(int v: A) del[v] = true;
		}
		else {
			ans += B.size();
			for(int v: B) del[v] = true;
		}
	}
	printf("%d\n", ans);
}

