            for (auto &&j : edges[x]) {
                if(c+1 < dist[j]) S.emplace(j, c+1);
            }
            dist[x] = min(dist[x], c);
        }
        for (int j = 0; j < n; ++j) {
            if(dist[j] > k/2) p++;
        }
        ans = min(ans, p);
