int getLca(int u,int v){
    if(dep[u]>dep[v])
        swap(u,v);
    int d=dep[v]-dep[u];
    int i=0;
    while(d){
        if(d&(1<<i)){
            d-=(1<<i);
            v=parent[v][i];
        }
        i++;
    }
    if(u==v)
        return u;
    for(int i=10;i>=0;i--){
        if(parent[u][i]!=parent[v][i])
            u=parent[u][i],v=parent[v][i];
    }
    return parent[u][0];
}
