		bag = 0;
		for (int i = 1; i <= N; i++) {
			bag = max(bag, box[i]);
		}
		if (bag) {
			ans++;
			for (int i = 1; i <= N; i++) {
				if (box[i] == bag) {
					flag[i] = false;
					break;
				}
			}
		}
		else break;
	}
	cout << ans << endl;
	return 0;
}

