int kotae=0;
deque<int> solve(int ter,int K){
	int i;
	deque<int>ans(K+1);
	deque<int>mai(K+1);
	for(auto it:ko[ter]){
		auto ret=solve(it,K);
		ret.puf(ret[0]+1);
		for(i=0;i<=K;i++){ans[i]+=ret[min(i,K-i)];maxeq(mai[i],ret[K-i]-ret[i]);}
	}
	for(i=0;i<=K;i++){ans[i]-=mai[i];}
	for(i=0;i<K;i++){mineq(ans[i+1],ans[i]);}
	maxeq(kotae,ans[K]);
	return ans;
}
