const i64 N = 2005;
vector<i64> edges[N];
i64 k;

vector<i64> recur(i64 pos, i64 parent = -1)
{
  vector<vector<i64>> costs;
  vector<i64> res(k + 1, bit(50));
  for(int edge: edges[pos])if(edge != parent) costs.push_back(recur(edge, pos));
  vector<i64> total(k + 1, 0);
  for(vector<i64> &cost: costs)rep(i, k + 1) total[i] += cost[i];

  res[0] = total[0] + 1;
  if(sz(costs)){
    rep(i, sz(costs))rep(j, k){
        i64 maxi = min(j, (k - 1) - j);
        //DEBUG(total[maxi], costs[i][maxi], costs[i][j]);
        res[j + 1] = min(res[j + 1], total[maxi] - costs[i][maxi] + costs[i][j]);
      }
  }else{
    rep(i, k) res[i + 1] = 0;
  }
  rep(i, k) res[i + 1] = min(res[i + 1], res[i]);
  return res;
}

int main()
{
  i64 n;
  cin >> n >> k;
  k += 1;
  rep(i, n - 1){
    i64 a, b;
    cin >> a >> b;
    edges[a - 1].push_back(b - 1);
    edges[b - 1].push_back(a - 1);
  }
  vector<i64> v = recur(0);
  cout << v[k] << endl;
}

