priority_queue <int,vector<int>,cmp> Q;
void dfs(int node,int depth){
	//cout<<node<<endl;
	//cout<<node<<" "<<depth<<endl;
	dep[node]=depth;
	vis[node]=1;
	for(int i=0;i<e[node].size();++i)
		if(!vis[e[node][i]]){
			fa[e[node][i]]=node;
			dfs(e[node][i],depth+1);
			son[node]++;
		}
	for(int i=0;i<e[node].size();++i)
		if(fa[e[node][i]]==node){
			Q.push(e[node][i]);
		}
}
