template<typename T> struct Edge
{
  int src, dst; T w;
  Edge() {};
  Edge(int src, int dst): src(src), dst(dst) {w=1;}
  Edge(int src, int dst, T w): src(src), dst(dst), w(w){}
  bool operator<(const Edge &e)const{return w != e.w ? w > e.w : (src != e.src ? src < e.src : dst < e.dst);}
  bool operator==(const Edge &e){return src == e.src && dst == e.dst;}
};

template<typename T> class Graph : public vector<vector<Edge<T>>>
{
private:
  pair<T,int> farthest(int p, int v)
  {
    pair<T,int> r(0,v);
    for(auto e : (*this)[v]) if(e.dst != p)
    {
      auto t = farthest(v,e.dst);
      t.first += e.w;
      if(t.first > r.first) r=t;
    }
    return r;
  }

public:
  T inf;
  set<int> path;
  Graph(int n){(*this).resize(n);inf=numeric_limits<T>::max();path=set<int>{};}
  void direct(int s, int t){(*this)[s].push_back(Edge<T>(s,t));}
  void direct(int s, int t, T w){(*this)[s].push_back(Edge<T>(s,t,w));}
  void undirect(int s, int t){direct(s,t);direct(t,s);}
  void undirect(int s, int t, T w){direct(s,t,w);direct(t,s,w);}

  /*
    cost : O(|V|)
  */
  tuple<int,int,T> diameter(void)
  {
    auto r = farthest(-1,0);
    auto t = farthest(-1,r.second);
    return make_tuple(r.second,t.second,t.first);
  }

  bool way(int now, int parent ,int to)
  {
    if(now==to) return true;
    for(auto e:(*this)[now])
    {
      if(e.dst==parent) continue;
      if(way(e.dst,e.src,to))
      {
        path.insert(e.src);
        return true;
      }
    }
    return false;
  }

  T cost(int now,int parent)
  {
    T c=1;
    for(auto e:(*this)[now])
    {
      if(e.dst!=parent) c+=cost(e.dst,e.src);
    }
    return c;
  }

  bool find(int i)
  {
    return (*this).path.find(i)!=(*this).path.end();
  }
};

int main()
{
  ll n,k; cin>>n>>k;
  Graph<int> g(n);
  REP(i,n-1)
  {
    int s,t; cin>>s>>t;s--;t--;
    g.undirect(s,t);
  }
  auto tmp=g.diameter();
  int x0=get<0>(tmp);
  int x1=get<1>(tmp);
  int len=get<2>(tmp);
  // cerr << x0 << " " << x1 << endl;
  g.way(x0,-1,x1);
  int a0=0,a1=0,y0=-1,y1=-1,t0,t1;
  // for(auto v : g.path) cout << v << endl;
  while(len>k)
  {
    for(auto e : g[x0])
    {
      if(e.dst==y0) continue;
      if(!g.find(e.dst)) a0+=g.cost(e.dst,x0);
      else t0=e.dst;
    }
    a0+=1;y0=x0;x0=t0;
    for(auto e : g[x1])
    {
      if(e.dst==y1) continue;
      if(!g.find(e.dst)) a0+=g.cost(e.dst,x1);
      else t1=e.dst;
    }
    a1+=1;y1=x1;x1=t1;
    len--;
  }
  cout<<min(a0,a1)<<endl;
}

