const int INF = 1e9;

int count(const vector< vector<int> > &G, int v, int p, int dist, int dist_max){
  if(dist > dist_max) return 0;
  int ret = 1;
  for(size_t i = 0; i < G[v].size(); ++i){
    int v_ = G[v][i];
    if(v_ == p) continue;
    ret += count(G,v_,v,dist+1,dist_max);
  }
  return ret;
}

int main(){
  int N, K;
  cin >> N >> K;
  vector< vector<int> > T(N);
