    --a,--b;
    T[a].push_back(b);
    T[b].push_back(a);
  }
  int ans = N;
  if(K%2){
    for(int i = 0; i < N; ++i){
      for(size_t j = 0; j < T[i].size(); ++j){
        int k = T[i][j];
        ans = min(ans,N-count(T,i,k,0,K/2)-count(T,k,i,0,K/2));
      }
    }
  }else{
    for(int i = 0; i < N; ++i){
      ans = min(ans,N-count(T,i,-1,0,K/2));
    }
  }
  cout << ans << endl;
}

