int bfs(int i, int j) {
	queue<pair<int, int>> q;
	q.emplace(i, 0);
	vector<int> vis(n);
	while (q.size()) {
		int x = q.front().first;
		int y = q.front().second;
		q.pop();
		if (x == j) {
			return y;
		}
		if (vis[x]) continue;
		vis[x] = 1;
		for (int node : a[x]) {
			q.emplace(node, y + 1);
		}
	}
	return INT_MAX;
}

