int n, K;
vector<int> to[2048];
int sz[2048], dp[2048][2048];

int prep(int at, int pre) {
    sz[at] = 1;
    rep (i, to[at].size()) if (to[at][i] != pre) {
        int u = to[at][i];
        sz[at] += prep(u, at);
    }
    return sz[at];
}

void rec(int at, int pre) {
    rep (i, to[at].size()) if (to[at][i] != pre) {
        int u = to[at][i];
        rec(u, at);
        for (int k = K - 1; k >= 0; k--) {
//            printf("%d[%d]: %d\n", u+1, k, dp[u][k]);
//            printf("%d, %d\n", dp[at][min(k, K - k - 1)], dp[u][k]);
            dp[at][k+1] = min(dp[at][min(k + 1, K - k - 1)] + dp[u][k], dp[at][k+1] + sz[u]);
//            printf("%d[%d] / %d: %d\n", at+1, k+1, u+1, dp[at][k+1]);
        }
        dp[at][0] += sz[u];
        rep (i, K) dp[at][i+1] = min(dp[at][i+1], dp[at][i]);
//        printf("%d[%d] / %d: %d\n", at+1, 0, u+1, dp[at][0]);
    }
}

int main() {
    scanf("%d%d", &n, &K);
    rep (i, n-1) {
        int a, b;
        scanf("%d%d", &a, &b);
        to[a-1].push_back(b-1);
        to[b-1].push_back(a-1);
    }
    prep(0, -1);
    rec(0, -1);
    printf("%d\n", dp[0][K]);
    return 0;
}

