const int maxn = 300010;
bool bye[maxn];
vector<int> edge[maxn];
int n, k, res;
int dfs(int now, int last = -1){
	vector<int> down;
	for(int u : edge[now])if(u != last){
		int v = dfs(u, now);
		if(v)down.pb(v);
	}
	sort(down.begin(), down.end(), greater<int>());
	if(down.empty())return 1;
	if(down[0] == k){
		++res, bye[now] = true;
		return 0;
	}
	if(down.size() == 1)
		return down[0]+1;
	if(down[0] + down[1] >= k){
		++res, bye[now] = true;
		return 0;
	}
	return down[0] + 1;
}
