vector<int> e[2000];

Pii diameter_dfs(int p, int v) {
	Pii ret(0, v);
	for (auto to : e[v]) if (to != p) {
		Pii tmp = diameter_dfs(v, to);
		tmp.first++;
		if (ret.first < tmp.first) ret = tmp;
	}
	return ret;
}
int diameter(int v) {
	Pii x = diameter_dfs(-1, v);
	Pii y = diameter_dfs(-1, x.second);
	return y.first;
}

int child[2000];
int dfs(int v, int par, int dep) {
	if (dep < 0) return 0;
	int ret = 1;
	for (auto to : e[v]) {
		if (to == par) continue;
		ret += dfs(to, v, dep - 1);
	}
	return child[v] = ret;
}

int main() {
