		cout << 0 << endl;
		return 0;
	}

	int mx = 0;
	if (k % 2 == 0) {
		FOR(i, n) {
			int tmp = dfs(i, -1, k / 2);
			mx = max(mx, tmp);
		}
	} else {
		FOR(i, n - 1) {
			FOR(_, n) e[_].clear();
