int D[14][2005];
int h[2005];
vector < int > s[2005];
int S[2005];
void dfs(int node = 1,int prev = 0)
{
    h[node] = h[prev] + 1;
    D[0][node] = prev;
    for (auto it : s[node])
        if (it != prev)
            dfs(it,node),S[node]++;
}
int shift(int a,int b)
{
    for (int k = 12;k+1;--k)
        if ((b >> k)&1)
            a = D[k][a];
    return a;
}
int lca(int a,int b)
{
    if (h[a] > h[b])
        a = shift(a,h[a] - h[b]);
    else
        b = shift(b,h[b] - h[a]);
    for (int k = 12;k+1;--k)
        if (D[k][a] != D[k][b])
            a = D[k][a],b = D[k][b];
    if (a == b) return a;
    return D[0][a];
}
int d[2005][2005];
int get(int a,int b)
{
    return d[a][b];
}
int was[1 << 20];
multiset < int , greater < int > > Lca[2005];
int Count[2005];
int main(void)
{
    # ifdef CF
    freopen("input","r",stdin);
    # endif // CF
    srand(time(0));
    fo << fixed << setprecision(7);
    cerr << fixed << setprecision(7);
    int n,k;
    IOS;
    fi>>n>>k;
    rep1(n - 1)
    {
        int a,b;
        fi>>a>>b;
        s[a].push_back(b);
        s[b].push_back(a);
    }
    dfs();
    for (int T = 1;T < 13;++T)
        for (int i = 1;i <= n;++i)
            D[T][i] = D[T-1][D[T-1][i]];
    int Dr = 0;
    for (int i = 1;i <= n;++i)
        for (int j = 1;j <= n;++j)
            d[i][j] = h[i] + h[j] - 2 * h[lca(i,j)];
    for (int i = 1;i <= n;++i)
        for (int j = 1;j <= n;++j)
            if (i != j)
                Dr = max(Dr,d[i][j]),Lca[i].insert(d[i][j]);
    for (int i = 1;i <= n;++i)
        for (int j = 1;j <= n;++j)
            Count[i] += d[i][j] == 2 && !S[j];
    int cnt = 0;
    while (Dr > k)
    {
        pp(Dr);
        ++cnt;
        pair < int , int > bst = {9999,9999};
        for (int i = 1;i <= n;++i)
            if (!S[i] && !was[i] && *(Lca[i].begin()) == Dr)
                bst = min(bst,{Count[i],i});
        int node = bst.y;
        pp(node);
        --S[D[0][node]];
        was[node] = 1;
        Lca[node].clear();
        Dr = 0;
        Count[node] = 0;
        for (int i = 1;i <= n;++i)
            if (!was[i])
                Lca[i].erase(Lca[i].find(get(i,node))),Dr = max(Dr,*Lca[i].begin()),Count[i] -= d[i][node] == 2;
    }
    fo << cnt << '\n';
    return 0;
}

