#include <bits/stdc++.h>
using namespace std;

vector<int> g[2020];
int dist[2020];
int root[2020];

void dfs(int curr, int prev) {
	for (int next : g[curr]) if (next != prev) {
		dist[next] = dist[curr] + 1;
		root[next] = root[curr];
		dfs(next, curr);
	}
}

int main() {
	int n, K;
	cin >> n >> K;

	for (int i = 0; i < n - 1; i++) {
		int u, v;
		scanf("%d %d", &u, &v);
		u--;
		v--;
		g[u].push_back(v);
		g[v].push_back(u);
	}

	int ans = INT_MAX;
	for (int i = 0; i < n; i++) {
		dist[i] = 0;

		for (int j : g[i]) {
			root[j] = j;
			dist[j] = 1;
			dfs(j, i);
		}

		int cnt = 0;
		map<int, int> mp;
		for (int j = 0; j < n; j++) {
			if (K % 2 == 0) {
				if (dist[j] > K / 2) {
					cnt++;
				}
			} else {
				if (dist[j] > (K + 1) / 2) {
					cnt++;
				} else if (dist[j] == (K + 1) / 2) {
					mp[root[j]]++;
				}
			}
		}
		int mx = 0;
		int sum = 0;
		for (auto kv : mp) {
			sum += kv.second;
			mx = max(mx, kv.second);
		}
		sum -= mx;
		ans = min(ans, sum + cnt);
	}
	cout << ans << endl; 
}

