using namespace std;

int main() {
    int n,k;
    cin >> n >> k;
    vector <vector <int> > graph(n + 1);
    for(int i = 0,u,v;i < n - 1;i++){
        cin >> u >> v;
        graph[u].push_back(v);
        graph[v].push_back(u);
    }
    int minv = 2001;
    for(int i = 1;i <= n;i++){
        bool visited[n + 1];
        for(int j = 0;j < n + 1;j++) visited[j] = false;
        int d = 1,vtd = 1;
        list <int> q;
        visited[i] = true;
        for(int j = 0;j < graph[i].size();j++){
            q.push_back(graph[i][j]);
            visited[graph[i][j]] = true;
        }
        while(!q.empty()){
            if(d >= k){ break; }
            if(d + 1 >= k){
                vtd++;
                d++;
                break;
            }
            list <int> child = q;
            vtd += child.size();
            if(q.size() == 1) d++;
            else d += 2;
            while(!child.empty()){
                int u = child.front();
                visited[u] = true;
                child.pop_front();
                q.pop_front();
                for(int j = 0;j < graph[u].size();j++){
                    if(!visited[graph[u][j]]){
                        q.push_back(graph[u][j]);
                        visited[graph[u][j]] = true;
                    }
                }
            }
        }
        minv = min(n - vtd,minv);
    }
    cout << minv;


}

