inline int read()
{
    int x=0,f=1;char ch=getchar();
    while(ch<'0'||ch>'9'){if(ch=='-')f=-1;ch=getchar();}
    while(ch>='0'&&ch<='9'){x=x*10+ch-'0';ch=getchar();}
    return x*f;
}
int n,K,head[MN+5],f[MN+5][MN+5],cnt,ans;
struct edge{int to,next;}e[MN*2+5];
inline void ins(int f,int t)
{
    e[++cnt]=(edge){t,head[f]};head[f]=cnt;
    e[++cnt]=(edge){f,head[t]};head[t]=cnt;
}
void Solve(int x,int fa)
{
    for(int i=0;i<=K;++i) f[x][i]=1;
    for(int i=head[x];i;i=e[i].next)
        if(e[i].to!=fa)
        {
            Solve(e[i].to,x);
            for(int j=1;j<=K;++j)
            {
                if(j<K) f[x][j]+=f[e[i].to][min(j-1,K-1-j)];
                f[x][j]=max(f[x][j],f[e[i].to][j-1]+1);
            }
            for(int j=1;j<=K;++j) f[x][j]=max(f[x][j],f[x][j-1]);
            ans=max(ans,f[x][K]);
        }
    //for(int j=0;j<=K;++j) printf("f[%d][%d]=%d\n",x,j,f[x][j]);
}
int main()
{
    n=read();K=read();
    for(int i=1;i<n;++i) ins(read(),read());
    Solve(1,0);
    printf("%d\n",n-ans);
    return 0;
}

