typedef vector< int > vi;
typedef vector< vi > vvi;

int N, K;
vi killed;
vvi G;

pair< int, vi > furthest( int u, int fa ){
    int max_dis = -1;
    vi vs = { u };
    for( int v : G[ u ] ){
        if( v == fa or killed[ v ] ) continue;
        pair< int, vi > chres = furthest( v, u );
        if( chres.first < max_dis ) continue;
        if( chres.first > max_dis )
            max_dis = chres.first,
            vs = chres.second;
        else
            vs.insert( vs.end(), chres.second.begin(), chres.second.end() );
    }
    return pair< int, vi >( max_dis + 1, vs );
}

void solve(){
    cin >> N >> K;
    G = vvi( N );
    for( int i = 0; i < N - 1; ++i ){
        int u, v; cin >> u >> v;
        --u, --v;
        G[ u ].push_back( v );
        G[ v ].push_back( u );
    }
    killed = vi( N );
    int _ = *( furthest( 0, -1 ).second.begin() );
    vi f1 = furthest( _, -1 ).second;
    vi f2 = furthest( *f1.begin(), -1 ).second;
    while( furthest( *f1.begin(), -1 ).first > K ){
        if( not ( f1.size() > f2.size() ) )
            swap( f1, f2 );
        for( int v : f2 )
            killed[ v ] = 1;
        f2 = furthest( *f1.begin(), -1 ).second;
    }
    cout << count( killed.begin(), killed.end(), 1 ) << "\n";
}

int main(){
    ios::sync_with_stdio( false );
    solve();
    return 0;
}

