  else
    idx[i] = idx[best];

  int id = idx[i];

  S[id].insert({-dep[i], i});

  for (int j : T[i]) 
    if (j != dad && j != best) 
      for (auto k : S[idx[j]])
	S[id].insert(k);

  while (!S[id].empty() && -(S[id].begin()->first) > min(K, 2 * dep[i] - 2))
    S[id].erase(S[id].begin());

  f[i] = S[id].size();
}

int kill[MAXN];

void dfs(int i, int dad = -1, int killed = 0) {
  kill[i] = killed + wei[i] - 1;

  int sum = 0;

  for (int j : T[i]) 
    if (j != dad)
      sum += wei[j] - f[j];

  for (int j : T[i])
    if (j != dad)
      dfs(j, i, killed + sum - wei[j] + f[j]);
}

int solve(int i) {
  FOR(j, 1, N + 1) S[j].clear();

  calc(i);
  dfs(i);

  int sol = 1e9;
  FOR(j, 1, N + 1)
    if (dep[j] <= K)
      sol = min(sol, kill[j]);

  return sol;
}

