	std::vector<std::vector<int>> g(n);
	for(int i = 0; i < n - 1; i++) {
		scanf("%d%d", &a[i], &b[i]);
		a[i]--; b[i]--;

		g[a[i]].push_back(i);
		g[b[i]].push_back(i);
	}

	auto calc_dist = [&](int s) {
		std::queue<int> qu({s});
		std::vector<int> dist(n, 1 << 30); dist[s] = 0;
		while(!qu.empty()) {
			auto v = qu.front(); qu.pop();

			for(auto id: g[v]) {
				int to = a[id] ^ b[id] ^ v;
				if(dist[to] <= dist[v] + 1) continue;
				dist[to] = dist[v] + 1;
				qu.push(to);
			}
		}
		return dist;
	};
	auto calc_cnt = [&](int s) {
		std::vector<int> cnt(n);
		auto dfs = [&](auto&& dfs, int v, int p) -> void {
			cnt[v] = 1;
			for(int id: g[v]) {
				int to = a[id] ^ b[id] ^ v;
				if(to == p) continue;
				dfs(dfs, to, v);
				cnt[v] += cnt[to];
			}
		};
		dfs(dfs, s, -1);

		return cnt;
	};

	int ans = 1 << 30;
	for(int i = 0; i < n; i++) {
		auto dist = calc_dist(i);
		auto size = calc_cnt(i);

		int sum = 0;
		for(int id: g[i]) {
			int to = a[id] ^ b[id] ^ i;
			sum += size[to];
		}
		for(int id: g[i]) {
			int to = a[id] ^ b[id] ^ i;

			auto dfs = [&](auto&& dfs, int v, int par, int d) -> int {
				int ret = d > k;
				for(int id: g[v]) {
					int to = a[id] ^ b[id] ^ v;
					if(to == par) continue;
					ret += dfs(dfs, to, v, d + 1);
				}
				return ret;
			};
			int ret = dfs(dfs, to, i, 1);

			ans = std::min(ans, (sum - size[to]) + ret);
		}
	}

	printf("%d\n", ans);
	return 0;
}

