/*
木なら中心がある。直径が指定されているので
中心を総当りして、各頂点から(半径?)調べる。
中心を指定して直径内の頂点を数える=>範囲外の個数が分かる。
範囲外の個数の最小値を調べる。
*/
vector< vector<int> > gra;
/*
curr:現在地
prev:行き止まり:prev方向には行かない
d:進める残りの距離
*/
int dfs(int curr,int prev,int d){//curr-prev
	if( d < 0 ){
		return 0;
	}
	int res = 1;
	int size = gra[curr].size();
	for(int i=0;i<size;++i){
		int next = gra[curr][i];
		if( next == prev ) continue;
		res += dfs(next,curr,d-1);
	}
	return res;
}
void solve(){
	int N,K;
	cin >> N >> K;
	gra.resize(N);
	for(int i=0;i<N-1;++i){
		int u,v;
		cin >> u >> v;
		--u;--v;
		gra[u].push_back(v);
		gra[v].push_back(u);
	}

	int ans = INF;//消す頂点数の最小値
	if( K%2 == 0 ){//探す直径が偶数:中心は１つ
		for(int i=0;i<N;++i){
			//iを中心として距離K/2までの頂点数
			int res = dfs(i,-1,K/2);
			//全体n-範囲内 = 消す頂点数
			ans = min(ans,N-res );
		}
	}else{//探す直径が奇数:中心は２つ
		for(int u=0;u<N;++u){
			int size = gra[u].size();
			for(int i=0;i<size;++i){
				int v = gra[u][i];
				if( v < u ) continue;
				//uからvへは行かない=uからvの子へいけない
				int res1 = dfs(u,v,(K-1)/2);
				//vからuへは行けない
				int res2 = dfs(v,u,(K-1)/2);
				//u-vの距離1を引いている。
				ans = min(ans,N-res1-res2);
			}
		}
	}
	cout << ans << endl;
}

