int gdp[2100][2100];
int n, k;
int ans = INF;
map<pair<int, int>, vi> pvd;

int dfs(int k, int p, int v, vector<vi> &g){
  if(v == -1) return 0;
  if(pvd.find(make_pair(p, v)) == pvd.end()){
    FOR(e, g[v]){
      if((*e) == p) continue;
      dfs(0, v, (*e), g);
    }
    vi x(n);
    x[0] = 1;
    REP(i, n){
      FOR(e, g[v]){
        if((*e) == p) continue;
        if(!i) x[0] += dfs(0, v, (*e), g);
        else x[i] += dfs(i - 1, v, (*e), g);
      }
    }
    pvd[make_pair(p, v)] = x;
  }
  vi ret = pvd[make_pair(p, v)];
  return ret[k];
}


void gdfs(int p, int v, vector<vi> &g){
  FOR(e, g[v]){
    if((*e) == p) continue;
    gdfs(v, (*e), g);
  }
  gdp[v][0] = 1;
  REP(i, n){
    FOR(e, g[v]){
      if((*e) == p) continue;
      if(!i) gdp[v][0] += gdp[(*e)][0];
      else gdp[v][i] += gdp[(*e)][i-1];
    }
  }
  // min_cost
  for(int x = 0; x <= (k / 2); x++){
    int cost = dfs(x, v, p, g);
    FOR(e, g[v]){
      if((*e) == p) continue;
      cost += gdp[(*e)][x];
    }
    int y = k - x;
    //cout << "cost" << v << " " << x << " " << cost << endl;
    FOR(e, g[v]){
      if((*e) == p) continue;
      cost -= gdp[(*e)][x];
      //check
      int ncost = cost + gdp[(*e)][y];
      ans = min(ans, ncost);
      //cout << " s  update" << (*e) << " " << ncost << endl;

      cost += gdp[(*e)][x];
    }
  }
}

