typedef vector<int> Node;
typedef vector<Node> Graph;
int N, K;
Graph G;
vector<int> depth;
void make_depth(int p, int v, int d) {
    depth[v] = d;
    for(int nv : G[v]) if(p != nv) {
        make_depth(v, nv, d+1);
    }
}
int get_size(int p, int v, int lb) {
    int ans = 0;
    if(depth[v] >= lb) ans ++;
    for(int nv : G[v]) if(p != nv) {
        ans += get_size(v, nv, lb);
    }
    return ans;
}
int solve(int root) {
    depth.resize(G.size());
    make_depth(-1, root, 0);
    vector<pair<int, int>> ps;
    for(int v : G[root]) {
        ps.push_back(make_pair(get_size(root, v, K/2+1),
                               get_size(root, v, K/2+2)));
    }
    int sum = 0;
    for(int i = 0; i < ps.size(); i++) {
        sum += ps[i].first;
    }
    int ans = sum;
    if(K % 2 == 1) {
        for(int i = 0; i < ps.size(); i++) {
            ans = min(ans, sum - ps[i].first + ps[i].second);
        }
    }
    return ans;
}

int main(){
    iostream_init();
    while(cin >> N >> K) {
        G.assign(N, Node());
        REP(i, N-1) {
            int u, v;
            cin >> u >> v;
            u--; v--;
            G[u].push_back(v);
            G[v].push_back(u);
        }
        int ans = INT_MAX;
        REP(i, N) ans = min(ans, solve(i));
        cout << ans << endl;
    }
    return 0;
}

