ll f(ll start, ll n, ll k) {
	REP(i, 1, n) {
		dist[i] = -1;
		fr[i] = -1;
		stk[i] = 0;
	}
	queue<ll> qu;
	qu.push(start);
	dist[start] = 0;
	REP(i, 0, SIZE(v[start])-1) {
		ll nbd = v[start][i];
		fr[nbd] = nbd;
