			ll next = v[cur][i];
			if (dist[next] == -1) {
				dist[next] = dist[cur] + 1;
				if (fr[cur] != -1) {
					fr[next] = fr[cur];
				}
				if (dist[next] <= k / 2) {
					ans++;
					qu.push(next);
				}
				if (dist[next] == k / 2 + 1) {
					stk[fr[next]]++;

				}
			}
