int defineDepth(Graph &T, vector<int> &p, vector<int> &dep,int root,int root2){
    int ret =0;
    queue<int> Q;
    Q.push(root);
    Q.push(root2);
    p[root]=root;
    p[root2]=root2;
    while(!Q.empty()){
        int nex=Q.front();
        Q.pop();
        for(auto &x: T[nex]){
            if(p[x.to]==-1){
                p[x.to]=x.from;
                Q.push(x.to);
                dep[x.to]=dep[x.from]+1;
                if(dep[x.to]>k/2) ++ret;
            }
        }
    }
    return ret;
}


