int dfs(int x,int pre){
	vint v(K+1);
	dp[x][0]=1;
	int h = 0;
	for(int y:vv[x]){
		if(y==pre) continue;
		maxs(h,dfs(y,x)+1);
		rep(i,K+1){
			v[i] += dp[y][i];
		}
		reep(i,1,K+1){
			maxs(dp[x][i],dp[y][i-1]+1);
		}
	}
	reep(j,1,K){
		int a = min(K-j,K/2);
		for(int y:vv[x]){
			if(y==pre) continue;
			maxs(dp[x][j],dp[y][j-1]+v[a-1]-dp[y][a-1]+1);
		}
