void f(int p,int oya){
	cs2[p][0]=1;
	int first=1;
	for(int i=0;i<vec[p].size();i++){
		int p2=vec[p][i];
		if(p2==oya)continue;
		f(p2,p);
		for(int i=0;i<n;i++){
			cs2[p][i+1]+=(first+cs2[p2][i]);
		}
		first=0;
	}
	int up=0;
	//printf("\n%d",p);
	for(int i=0;i<=n;i++){
