			up=cs2[p][i];
		}
		cs2[p][i]=up;
		//printf(" %d ",cs2[p][i]);
	}

}

void g(int p,int oya){
	int cs5[2001];
	cs4[p][0]=1;
	for(int i=0;i<vec[p].size();i++){
		int p2=vec[p][i];
		if(p2==oya)continue;
		g(p2,p);
		memcpy(cs5,cs2[p],sizeof(cs5));
		//printf("\n(%d %d)",p,p2);
