		//for(int j=0;j<=n;j++){
		//	printf("%d ",cs5[j]);
		//}
		//printf("\n");
		for(int j=0;j<k;j++){
			int a=j;
			int b=k-j-1;
			if(b>a+1){
				b=a+1;
			}

			int c=cs2[p2][a]+cs5[b];
			if(cs4[p][a+1]<c){
				cs4[p][a+1]=c;
			}
			if(ans<c){
				ans=c;
			}
		}
	}
	int up=0;
	for(int i=0;i<=n;i++){
		if(up<cs4[p][i]){
			up=cs4[p][i];
		}
		cs4[p][i]=up;
	}
	memcpy(cs2[p],cs4[p],sizeof(cs4[p]));
}

