bitset<maxn> ok[maxn];

int dist[maxn];

void bfs(int v, int n){
    fill(dist, dist + n, n);
    dist[v] = 0;
    vector<int> q{v};
    int cur = 0;
    while (cur < q.size()){
        v = q[cur++];
        for (int u : s[v]){
            if (dist[u] > dist[v] + 1){
                q.push_back(u);
                dist[u] = dist[v] + 1;
            }
        }
    }
}

int solve(){
    int n, k;
    cin >> n >> k;
    for (int i = 1; i < n; i++){
        int a, b;
        cin >> a >> b;
        s[a - 1].push_back(b - 1);
        s[b - 1].push_back(a - 1);
    }
    int res = -1;
    for (int i = 0; i < n; i++){
        bfs(i, n);
        for (int j = 0; j < n; j++){
            if (dist[j] <= k)
                ok[i].set(j);
        }
        // print(dist, n);
        for (int j = 0; j < i; j++){
            if (dist[j] == k && j < i)
                res = max(res, (int)(ok[i] & ok[j]).count());
        }
    }
    if (res == -1)
        res = n;
    cout << n - res << endl;
    return 0;
}

