int prep(int at, int pre) {
    sz[at] = 1;
    rep (i, to[at].size()) if (to[at][i] != pre) {
        int u = to[at][i];
        sz[at] += prep(u, at);
    }
    return sz[at];
}

void rec(int at, int pre) {
    rep (i, to[at].size()) if (to[at][i] != pre) {
        int u = to[at][i];
        rec(u, at);
        for (int k = K - 1; k >= 0; k--) {
//            printf("%d[%d]: %d\n", u+1, k, dp[u][k]);
//            printf("%d, %d\n", dp[at][min(k, K - k - 1)], dp[u][k]);
            int t = min(k, K-k-2);
            int b = dp[at][k+1] + (t >= 0 ? dp[u][t] : sz[u]);
//            printf("min(%d, %d)\n", dp[at][min(k+1, K-k-1)] + dp[u][k], b);
            dp[at][k+1] = min(dp[at][min(k+1, K-k-1)] + dp[u][k], b);
//            printf("%d[%d] / %d: %d\n", at+1, k+1, u+1, dp[at][k+1]);
        }
        dp[at][0] += sz[u];
        rep (i, K) dp[at][i+1] = min(dp[at][i+1], dp[at][i]);
//        rep (i, K+1) printf("%d[%d] / %d: %d\n", at+1, i, u+1, dp[at][i]);
    }
}

