int bfs(vector<vector<int>> &E,int start,int K){
	vector<int> dis(E.size(),Inf);

	dis[start] = 0;
	queue<int> que;
	que.push(start);
	int cnt = 1;
	while(que.size()!=0){
		int now = que.front();
		que.pop();
		for(int i=0;i<E[now].size();i++){
			int to = E[now][i];
			if(dis[to]!=Inf)continue;
			if(dis[now]==K)continue;
			cnt++;
			dis[to] = dis[now] + 1;
			que.push(to);
		}
	}

	return cnt;
}




