pii Dfs(int u,int p,int l) {
    pii ret=mpp(0,0);
    for(int i=0; i<SZ(G[u]); i++) {
        int vv=G[ u ][ i ];
        if( vv==p )continue;
        pii tmp=Dfs( vv,u, l+1 );
        ret.X+=tmp.X;///Gretaer than k/2;
        ret.Y+=tmp.Y;///Gretaer than k/2+1;
    }
    if( l>(k+1)/2 ) ret.X++,ret.Y++;
    else if( l>k/2 ) ret.X++;
    return ret;
}

int Solve(int r) {
    v.clear();
    int ret=0;
    for(int i=0; i<SZ(G[r]); i++) {
        int c=G[ r ][ i ];
        pii tmp=Dfs(c,r,1);
        v.pb(  tmp );
        ret+=( tmp.X );
    }
    if(k&1){
        int mx=0;
        for(int i=0;i<SZ(v);i++){
            mx=max( mx,-v[i].X+v[i].Y );
        }
        ret-=mx;
    }
    return ret;
}

