int n, k;
int rel[2020][2020];
int used[2020];

int bfs(int start) {
  queue<pii> q;
  pii f;
  f.fi = start;
  f.se = 0;
  q.push(f);
  int cnt = 0;
  while (!q.empty()) {
    pii s = q.front(); q.pop();
    if (s.se <= k / 2) {
      ++ cnt;
    } else {
      return cnt;
    }
    rep(i, n) {
      if (rel[s.fi][i] && !used[i]) {
        used[i] = 1;
        pii ns;
        ns.fi = i;
        ns.se = s.se + 1;
        q.push(ns);
      }
    }
  }
  return cnt;
}

