#include <bits/stdc++.h>
using namespace std;

#define li long long int
#define rep(i, to) for (li i = 0; i < ((li)(to)); i++)
typedef pair<li, li> PI;


vector<li> edge[2020];
li n, k;

inline li calc(li root, li parent, li lim) {
    stack<pair<PI, li>> stk;
    li cnt = 0;
    stk.push({{root, parent}, 0});
    while (!stk.empty()) {
        li now = stk.top().first.first;
        li from = stk.top().first.second;
        li now_d = stk.top().second;
        stk.pop();
        cnt++;
        if (now_d >= lim)continue;
        for (auto next : edge[now]) {
            if (next == from)continue;
            stk.push({{next, now}, now_d + 1});
        }
    }
    return cnt;
}

inline li solve_node() {
    li res = n;
    rep(i, n) {
        res = min(res, n - calc(i, -1, k / 2));
    }
    return res;
}

inline li solve_link() {
    li res = n;
    rep(i, n) {
        for (auto to : edge[i]) {
            res = min(res, n - calc(i, to, k / 2) - calc(to, i, k / 2));
        }
    }
    return res;
}

int main(void)
{
    cin >> n >> k;
    rep(i, n - 1) {
        li a, b;
        cin >> a >> b;
        a--;
        b--;
        edge[a].push_back(b);
        edge[b].push_back(a);
    }

    if (k % 2 == 0) {
        cout << solve_node() << endl;
    } else {
        cout << solve_link() << endl;
    }


    return 0;
}

