int trim(int v, int p, int k, const vector<vector<int>>& e, vector<int>& ans) {
    ans[v] = 0;
    for (auto u : e[v]) {
        if (u != p) ans[v] += trim(u, v, k - 1, e, ans);
    }
    if (k < 0) ans[v]++;
    return ans[v];
}

int Solve(int v, const vector<vector<int>>& e, int K) {
    if (e[v].size() == 1) {
        vector<int> ans(e.size());
        return trim(v, -1, K, e, ans);
    }
    if (K % 2 == 0) {
        vector<int> ans(e.size());
        return trim(v, -1, K / 2, e, ans);
    }
    vector<int> trim_short(e.size());
    trim(v, -1, K / 2, e, trim_short);
    vector<int> trim_long(e.size());
    trim(v, -1, (K + 1) / 2, e, trim_long);
    int short_ans = 0;
    for (auto u : e[v]) short_ans += trim_short[u];
    int min_ans = short_ans;
    for (auto u : e[v]) {
        int cur_ans = short_ans - trim_short[u] + trim_long[u];
        min_ans = min(min_ans, cur_ans);
    }
    return min_ans;
}

