vector<int> graph[2010];
int tmp[2010],dist[2010],dist2[2010];
bool ban[2010];

void dfs(int v,int p,int d,int* dist){
	if(ban[v]) return;
	dist[v]=d;
	for(auto &v2:graph[v]){
		if(v2==p) continue;
		dfs(v2,v,d+1,dist);
	}
	return;
}


int main(void){
	int n,k;
	cin >> n >> k;
	rep(i,n-1){
		int a,b;
		cin >> a >> b;
		graph[a-1].push_back(b-1);
		graph[b-1].push_back(a-1);
	}

	int ans=0;

	while(1){
		int u=0,v=0,cmax=0;

		dfs(0,-1,0,tmp);
		cmax=0;
		rep(i,n) if(!ban[i] && chmax(cmax,tmp[i])) u=i;

		dfs(u,-1,0,dist);
		cmax=0;
		rep(i,n) if(!ban[i] && chmax(cmax,dist[i])) v=i;

		dfs(v,-1,0,dist2);
		cmax=0;
		rep(i,n) if(!ban[i]) chmax(cmax,dist2[i]);		

		if(cmax<=k) break;

		int unum=0,vnum=0;
		rep(i,n) if(!ban[i] && dist[i]>k) unum++;		
		rep(i,n) if(!ban[i] && dist2[i]>k) vnum++;		

		if(unum>vnum)
			ban[u]=true;
		else
			ban[v]=true;

		ans++;
	}	

	cout << ans << endl;
	return 0;
}

