typedef long long LL;

LL ec = 0,nxt[4005],to[4005],hed[2005] = {0};
void add_edge(LL f,LL t){
	++ ec; to[ec] = t; nxt[ec] = hed[f]; hed[f] = ec;
}

LL n,k;
LL siz[2005],dep[2005],del[2005];
void dfs(LL u,LL f,LL c){
	siz[c] ++; dep[u] = dep[f] + 1;
	if(dep[u] > k) del[c] ++;
	for(LL i = hed[u];i;i = nxt[i]){
		LL v = to[i];
		if(v == f) continue;
		dfs(v,u,c);
	}
}

LL solve(LL u){
	LL mx = 0,sum = 0;
	dep[u] = 0;
	for(LL i = hed[u];i;i = nxt[i]){
		LL v = to[i];
		siz[v] = 0; del[v] = 0; dfs(v,u,v);
		mx = max(mx,siz[v] - del[v]);
		sum += siz[v];
	}
	return sum - mx;
}

int main(){
	ios::sync_with_stdio(false);
	LL u,v,ans = 0x3f3f3f3f3f3f3f3f;
	cin >> n >> k;
	for(LL i = 1;i < n;i ++){
		cin >> u >> v;
		add_edge(u,v);
		add_edge(v,u);
	}
	for(LL i = 1;i <= n;i ++) ans = min(ans,solve(i));
	cout << ans << endl;
	return 0;
}

