  os << edge.from << " -> " << edge.to << " (" << edge.cost << ")";
  return os;
}

// グラフテンプレート(隣接リスト)
template <typename E = Edge<ll>>
struct GraphL {
  // 頂点数、辺数
  int n, m;
  // 隣接リスト
  vector<vector<E>> adj;
  GraphL(int n_)
      : n(n_), m(0), adj(n_) {}

  template <typename... Args>
  void add_edge(int from, int to, Args... args) {
    adj[from].emplace_back(from, to, args...);
    m++;
  }
  vector<E> &operator[](int i) { return adj[i]; }
};
template <typename E = Edge<ll>>
ostream &operator<<(ostream &os, GraphL<E> graph) {
  os << "V = " << graph.n << ", E = " << graph.m << "\n";
  for (const auto &ev : graph.adj) {
    for (const auto &e : ev) {
      os << e << "\n";
    }
  }
  return os;
}

// 幅優先探索
template <typename E>
ll bfs(GraphL<E> &graph, int start, int K) {
  ll ret = 0;
  vector<bool> visited(graph.n, false);
  queue<pair<ll, ll>> q;
  q.emplace(start, 0);
  visited[start] = true;
  while (q.size()) {
    ll node = q.front().first;
    ll d = q.front().second;
    ret++;
    q.pop();
    if(d < K){
      for (auto &&e : graph.adj[node]) {
        if (!visited[e.to]) {
          visited[e.to] = true;
          q.emplace(e.to, d + 1);
        }
      }
    }
  }
  return ret;
}


