const int INF=12345678;

vector<int> G[2000];

int main()
{
    int n,k;
    cin >>n >>k;
    rep(i,n-1)
    {
        int a,b;
        cin >>a >>b;
        --a;
        --b;
        G[a].pb(b);
        G[b].pb(a);
    }

    int ans=0;
    vector<bool> alive(n,true);

    int start=0;
    while(1)
    {
        while(start<n && !alive[start]) ++start;

        queue<int> que;

        //startからの距離
        int ds[2000];
        fill(ds,ds+n,INF);
        ds[start]=0;
        que.push(start);
        while(!que.empty())
        {
            int now=que.front();
            que.pop();
            rep(i,G[now].size())
            {
                int nx=G[now][i];
                if(alive[nx] && ds[nx]>ds[now]+1)
                {
                    ds[nx]=ds[now]+1;
                    que.push(nx);
                }
            }
        }

        //startから最も離れた点t
        int DS=0;
        int t=0;
        rep(i,n)
        {
            if(alive[i])
            {
                if(DS<ds[i])
                {
                    DS=ds[i];
                    t=i;
                }
            }
        }

        //tからの距離
        int dt[2000];
        fill(dt,dt+n,INF);
        dt[t]=0;
        que.push(t);
        while(!que.empty())
        {
            int now=que.front();
            que.pop();
            rep(i,G[now].size())
            {
                int nx=G[now][i];
                if(alive[nx] && dt[nx]>dt[now]+1)
                {
                    dt[nx]=dt[now]+1;
                    que.push(nx);
                }
            }
        }

        //tから最も離れた点
        int DT=0;
        rep(i,n) if(alive[i]) DT=max(DT,dt[i]);

        //直径はk以下なので終わり
        if(DT<=k) break;

        vector<int> del;
        rep(i,n) if(alive[i] && DT==dt[i]) del.pb(i);

        rep(i,del.size())
        {
            ++ans;
            alive[del[i]]=false;
        }
    }

    cout << ans << endl;
    return 0;
}

