void dfs(int val,int cs)
{
	if(vis[val]==1)
	return;
	vis[val]=1;
	if(cs==k/2+1)
	return;
	for(int i=0;i<v[val].size();i++)
	{
		if(vis[v[val][i]])
		continue;
		cnt++;
		dfs(v[val][i],cs+1);
	}
	return;
}
int main()
{
