		int v = a[id] ^ b[id] ^ i;

		auto dfs = [&](auto&& dfs, int v, int par, int d) -> int {
			if(d > k / 2) return 0;
			int ret = 1;
			for(auto id: g[v]) {
				int to = a[id] ^ b[id] ^ v;
				ret += dfs(dfs, to, v, d + 1);
			}
			return ret;
		};

		if(k & 1) {
			// 中心が二つ
			for(auto id: g[i]) {
				int to = a[id] ^ b[id] ^ i;
				int ret = dfs(dfs, to, i, 0) + dfs(dfs, i, to, 0);

				ans = std::min(ans, n - ret);
			}
		} else {
			int ret = dfs(dfs, i, -1, 0);
			ans = std::min(ans, n - ret);
		}
	}

	printf("%d\n", ans);
	return 0;
}

