pair< int, int > dfs(int idx, int prev)
{ 
  pair< int, int > ret = make_pair(0, idx);
  for(int i = 0; i < graph[idx].size(); i++) {
    if(graph[idx][i] != prev) {
      pair< int, int > cost = dfs(graph[idx][i], idx);
      cost.first++;
      ret = max(ret, cost);
    }
  }
  return(ret);
}
