// ids: 頂点一覧
// 返値：距離一覧
vector<ll> diameter(set<ll> ids){

    ll p = *ids.begin();
    vector<ll> dis(N,0);
    dfs(p,0,-1,dis, ids);

    ll q = 0; // q: pから見た最遠点
    rep(i,0,N) if(dis[i] > dis[q]) q = i;

    vector<ll> res(N,0);
    dfs(q,0,-1,res, ids);

    return res;
}

