                if (dy[to] > dy[x] + 1) {
                    dy[to] = dy[x] + 1;
                    q.push(to);
                }
            }
        }
        int dist = -1;
        REP(i, N) {
            if (d[i] != MAX_N) {
                dist = max(dist, dy[i]);
            }
        }
        assert(dist != -1);
