void dfs(int v, int p, int dist, int remember) {
    if (dist == remember) ++cEquals;
    if (dist > remember) ++cGreater;
    for(int to:g[v]) if (to != p) dfs(to, v, dist+1, remember);
}

int solve(int v) {
    int mx = 0;
    int ret = 0;
    for(int to:g[v]) {
        cEquals = cGreater = 0;
        dfs(to, v, 1, (m+1)/2);
        ret += cGreater + (m%2 ? cEquals : 0);
        umax(mx, cEquals);
    }
    return ret - (m%2 ? mx : 0);
}

