class Solve {
public:
    Int N, K;
    vector<vector<int>> G;
    vector<pair<int, int>> edge;
    vector<int> d;

    void bfs(int s1, int s2 = -1) {
        fill(all(d), INF);
        d[s1] = 0;
        if (s2 != -1) d[s2] = 0;

        queue<int> que;
        que.push(s1);
        if (s2 != -1) que.push(s2);

        while (!que.empty()) {
            int top = que.front();
            que.pop();
            for (auto v : G[top]) {
                if (d[v] == INF) {
                    d[v] = d[top] + 1;
                    que.push(v);
                }
            }
        }
    }

    void solve() {
        cin >> N >> K;
        G.resize(N);
//        edge.resize(N);
        d.resize(N);
        for (int i = 0; i + 1 < N; ++i) {
            int a, b;
            cin >> a >> b;
            a--, b--;
            G[a].push_back(b);
            G[b].push_back(a);
            edge.emplace_back(a, b);
        }

        bfs(0);


        if (K == 1) {
            cout << N - 1 << endl;
        } else if (K % 2) {
            int ans = INF;
            for (auto e : edge) {
                int s1 = e.first;
                int s2 = e.second;
                bfs(s1, s2);
                int tmp = 0;
                for (int i = 0; i < N; ++i) {
                    if (d[i] > K / 2) {
                        tmp++;
                    }
                }
                chmin(ans, tmp);
            }
            cout << ans << endl;
        } else {
            int ans = INF;
            for (int i = 0; i < N; ++i) {
                bfs(i);
                int tmp = 0;
                for (int j = 0; j < N; ++j) {
                    if (d[j] > K / 2) {
                        tmp++;
                    }
                }
                chmin(ans, tmp);
            }
            cout << ans << endl;
        }


    }
};


int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    cout << fixed << setprecision(10);

    Solve().solve();


    return 0;
}

