                sz += d[to][0];
            }
            sz++;
            d[vertex][0] = sz;
            continue;
        }

        d[vertex][i] = INF;
        for (int j = 0; j < v.size(); j++) {
            int cur = v[j];
            if (h[cur] >= i - 1) {
                int cnt = d[cur][i - 1];
                for (int p = 0; p < v.size(); p++) {
                    if (p == j) {
                        continue;
                    }
                    cnt += d[v[p]][min(h[v[p]], min(k - i, i - 1))];
                }
                if (cnt < d[vertex][i]) {
                    d[vertex][i] = cnt;
                }
            }
        }
    }
    if (h[vertex] == 1) {
        d[vertex][1] = 0;
    }
}


