using Tree = vec<vec<int>>;
bool deleted[2020];
struct DistHelper {
  const Tree& tree;
  vec<int> dist;
  DistHelper(const Tree& tree) : tree(tree), dist(tree.size(), -inf) {}
  vec<int> build(int root) {
    dfs(root);
    return dist;
  }
  void dfs(int v, int p = -1, int d = 0) {
    dist[v] = d;
    for (int u : tree[v]) {
      if (u == p) continue;
      if (deleted[u]) continue;
      dfs(u, v, d + 1);
    }
  }
};

signed main() {
  int N = in(), K = in();
  Tree tree(N);
