    int diam = dista[b];

    if (diam <= K) break;
    int maxa = std::count_if(ALL(dista), [K](int x) { return x >= K; });
    int maxb = std::count_if(ALL(distb), [K](int x) { return x >= K; });
    if (maxa < maxb) {
      deleted[b] = true;
    } else {
      deleted[a] = true;
    }
    ans++;
  }
  cout << ans << endl;
  return 0;
}

