using namespace std;

int n,k,step[2007][2007],M,countMax,x,y,result;
vector<int> v[2007],leaf,delet;
bool lef[2007];

void reduceDiameter()
{
    M=countMax=0; delet.clear();
    for(int i=0;i<leaf.size();++i) for(int j=0;j<leaf.size();++j) if(i!=j && step[leaf[i]][leaf[j]]>M) M=step[leaf[i]][leaf[j]];

    for(int i=0;i<leaf.size() && M>k;++i)
    {
        x=0;
        for(int j=0;j<leaf.size();++j) if(i!=j && step[leaf[i]][leaf[j]]==M) ++x;

        if(x>countMax) {countMax=x; delet.clear(); delet.push_back(leaf[i]);}
        else if(x==countMax) delet.push_back(leaf[i]);
    }

    for(int i=0;i<delet.size();++i) for(int j=i+1;j<delet.size();++j) if(step[delet[i]][delet[j]]==M) {delet.erase(delet.begin()+j); --j;}
    for(int i=0;i<delet.size();++i) for(int j=0;j<leaf.size();++j) if(leaf[j]==delet[i]) {leaf.erase(leaf.begin()+j); break;}
    for(int i=0;i<delet.size() && M>k;++i) for(int j=0;j<v[delet[i]].size();++j) if(lef[v[delet[i]][j]]==false) {lef[v[delet[i]][j]]=true; leaf.push_back(v[delet[i]][j]);}
    result+=delet.size();
}

void bfs(int now,int from,int dis)
{
    step[x][now]=dis;
    for(int i=0;i<v[now].size();++i) if(v[now][i]!=from) bfs(v[now][i],now,dis+1);
}

void prepare()
{
    scanf("%i%i",&n,&k); M=2e9; result=0; /**/ for(int i=0;i<2007;++i) {v[i].clear(); lef[i]=false;} leaf.clear(); delet.clear();
    for(int i=0;i<n-1;++i) {scanf("%i%i",&x,&y); --x; --y; v[x].push_back(y); v[y].push_back(x);}
    for(int i=0;i<n;++i) {x=i; bfs(i,-1,0);}
    for(int i=0;i<n;++i) if(v[i].size()==1) {leaf.push_back(i); lef[i]=true;}
}

int main()
{
    prepare();
    for(;M>k;) reduceDiameter();
    printf("%i\n",result);
    return 0;
}

