int dp_down[N][N], dp_up[N][N], prec[N][N], cnt[N], par[N], depth[N];
vi vertices[N];
int n, k;


void dfs_down(int v, int p = -1)
{
    for (int i = k / 2 + 1; i <= k; ++i)
        dp_down[v][i] = N;

    cnt[v]++;
    par[v] = p;
    depth[v] = 1;

    int prec_down[N];
    fill(prec_down, prec_down + N, 0);

    for (int u : vertices[v]) {
        if (u == p)
            continue;

        dfs_down(u, v);
        cnt[v] += cnt[u];
        depth[v] = max(depth[v], depth[u] + 1);

        for (int i = 0; i <= k; ++i)
            prec_down[i] += dp_down[u][i];
    }

    for (int u : vertices[v])
    {
        if (u == p)
            continue;

        for (int i = 0; i <= k; ++i)
            prec_down[i] -= dp_down[u][i];

        for (int i = 1; i <= k; ++i) {
//            if (depth[u] < i - 1)
//                continue;

            if (i * 2 <= k)
                dp_down[v][i] += dp_down[u][i - 1];
            else if (k != i)
                inmin(dp_down[v][i], dp_down[u][i - 1] + prec_down[k - i - 1]);
            else
                inmin(dp_down[v][i], dp_down[u][i - 1] + cnt[v] - cnt[u] - 1);
        }


        for (int i = 0; i <= k; ++i)
            prec_down[i] += dp_down[u][i];
    }

    dp_down[v][0] = cnt[v] - 1;
}


void dfs_up(int v, int p = -1)
