const int N = 2000 + 7;
int n, k, dp[N][N];
vector<int> g[N];

void dfs(int a, int p) {
  dp[a][0] = 1;
  vector<int> kids;
  for (auto &b : g[a]) {
    if (b != p) {
      dfs(b, a);
      kids.push_back(b);
      dp[a][0] += dp[b][0];
    }
  }
  if (kids.empty()) {
    for (int i = 1; i <= k; i++) {
      dp[a][i] = 0;
    }
    return;
  }
  for (int l = 1; l <= k; l++) {
    dp[a][l] = dp[a][l - 1];
    for (auto &strong : kids) {
      int cur = dp[strong][l - 1];
      for (auto &b : kids) {
        if (b != strong) {
          cur += dp[b][min(l - 1, k - l)];
        }
      }
      dp[a][l] = min(dp[a][l], cur);
    }
  }
}

