#include <bits/stdc++.h>

using namespace std;

const int N = 2e3;
vector<int> edges[N];
int diam[N];
int sz[N];
int from[N];
int dst[N];
int used[N];

int bfs(int s) {
    memset(dst, -1, sizeof dst);
    queue<int> q; q.push(s); dst[s] = 0; from[s] = 0;
    while (!q.empty()) {
        int v = q.front(); q.pop();
        for (int u : edges[v]) {
            if (dst[u] == -1) {
                q.push(u); dst[u] = dst[v] + 1; from[u] = v;
            }
        }
    }
    return max_element(dst, dst + N) - dst;
}

void dfs(int v) {
    sz[v] = 1;
    used[v] = 1;
    for (int u : edges[v]) {
        if (diam[u] || used[u])
            continue;
        dfs(u);
        sz[v] += sz[u];
    }
}

void solve() {
    int n, k; cin >> n >> k;
    for (int i = 0; i < n - 1; i++) {
        int v, u; cin >> v >> u;
        edges[v].push_back(u); edges[u].push_back(v);
    }
    int v1 = bfs(1);
    int v2 = bfs(v1);
    if (dst[v2] < k) {
        cout << 0; return;
    }
    vector<int> dm;
    int p = v2;
    while (p) {
        dm.push_back(p);
        p = from[p];
    }
    for (auto v : dm) {
        diam[v] = 1;
    }
    for (auto v : dm) {
        dfs(v);
    }
    int bestans = n;
    int tmp = 0;
    for (int i = 0; i <= k - 2; i++)
        tmp += sz[dm[i]];
    for (int i = k - 1; i < dm.size(); i++) {
        tmp += sz[dm[i]];
        if (i - k >= 0)
            tmp -= sz[dm[i - k]];
        bestans = min(bestans, tmp);
    }
    cout << bestans;
}

int main() {
    ios::sync_with_stdio(NULL), cin.tie(0), cout.tie(0);
    cout.setf(ios::fixed), cout.precision(20);
    solve();
}

