    vector<ll>dist(n,LINF);
    queue<ll>q;
    q.push(root);
    dist[root]=0;
    while(size--){
        ll at=q.front();
        q.pop();
        diameter={dist[at],diameter.first};
        each(i,g[at])if(chmin(dist[i],dist[at]+1))q.push(i);
    }
    return diameter.first+diameter.second<=k;
}
