using namespace std;

const int N = 2000 + 5;

int n;
int lim;
vector<int> g[N];

int dist[N][N];

void dfs(int v, int fa, int anc) {
  for (auto u : g[v]) {
    if (u != fa) {
      dist[anc][u] = dist[anc][v] + 1;
      dfs(u, v, anc);
    }
  }
}

