    for (int i = 0; i < n; ++i) {
      for (auto j : g[i]) {
        int cnt = 0;
        for (int k = 0; k < n; ++k) {
          if (min(dist[i][k], dist[j][k]) > (lim - 1) / 2) {
            ++cnt;
          }
        }
        ans = min(ans, cnt);
      }
    }
    cout << ans << endl;
  } else {
    int ans = n;
    for (int i = 0; i < n; ++i) {
      int cnt = 0;
      for (int j = 0; j < n; ++j) {
        if (dist[i][j] > lim / 2) {
          ++cnt;
        }
      }
      ans = min(ans, cnt);
    }
    cout << ans << endl;
  }
  return 0;
}

#include <bits/stdc++.h>

using namespace std;
typedef pair<int, int> pii;
const int MAXN = 2010;

#define fi first
#define se second

int N, K;
vector<int> adj[MAXN];
int dist[MAXN];

pii dfs (int x, int p, int d) {
	pii res((d <= K / 2), (d <= (K + 1) / 2));
	for (int t : adj[x]) {
		if (t != p) { 
			pii p = dfs(t, x, d + 1);
			res.fi += p.fi;
			res.se += p.se;
		}
	}
	return res;
}

int main() {
	scanf("%d %d", &N, &K);
	for (int i = 1; i < N; i++) {
		int a, b;
		scanf("%d %d", &a, &b);
		adj[a].push_back(b);
		adj[b].push_back(a);
	}

	int ans = 0;
	for (int i = 1; i <= N; i++) {
		int r = 0, mxdiff = 0;
		for (int t : adj[i]) {
			pii p = dfs(t, i, 1);
			r += p.fi;
			mxdiff = max(mxdiff, p.se - p.fi);
		}
		ans = max(ans, r + mxdiff + 1);
	}
	printf("%d\n", N - ans);
}

