}
inline void dfs1(int x,int fa,int y,int z)
{
    if(y>z) return;
    bo[x]=1,cnt++;
    for(int k=h[x];k;k=a[k].ne)
    {
        if(a[k].to==fa) continue;
        dfs1(a[k].to,x,y+1,z);
    }
    return;
}
inline void dfs2(int x,int fa)
{
    d[x]=0;
    for(int k=h[x];k;k=a[k].ne)
    {
        if(a[k].to==fa||bo[a[k].to]==0) continue;
        dfs2(a[k].to,x);
        maxx=max(maxx,d[a[k].to]+1+d[x]);
        d[x]=max(d[x],d[a[k].to]+1);
    }
    return;
}
