using namespace std;

using vertex = int;
using edge = pair<vertex, vertex>;
using graph = map<vertex, vector<edge>>;

map<vertex, vertex> an;
vertex t;

priority_queue<pair<int, vertex>> diam(graph g, vertex s) {
  {
    queue<pair<vertex, int>> q;
    q.push({s, 0});

    set<vertex> visited;
    visited.insert(s);

    pair<vertex, int> p;
    while (!q.empty()) {
      p = q.front();
      visited.insert(p.first);
      q.pop();
      for (auto&& p2 : g[p.first]) {
        if (visited.find(p2.second) != visited.end()) continue;
        q.push({p2.second, p.second + 1});
        an[p2.second] = p.first;
      }
    }
    t = s = p.first;
  }
  {
    priority_queue<pair<int, vertex>> pq;
    pq.push({0, s});

    queue<pair<vertex, int>> q;
    q.push({s, 0});

    set<vertex> visited;
    visited.insert(s);

    pair<vertex, int> p;
    while (!q.empty()) {
      p = q.front();
      visited.insert(p.first);
      q.pop();
      for (auto&& p2 : g[p.first]) {
        if (visited.find(p2.second) != visited.end()) continue;
        q.push({p2.second, p.second + 1});
        pq.push({p.second + 1, p2.second});
      }
    }
    return pq;
  }
}

int main() {
  std::ios::sync_with_stdio(false);

  int N, K;
  cin >> N >> K;

  graph g;
  for (int i = 0; i < N - 1; ++i) {
    int a, b;
    cin >> a >> b;
    g[a].push_back({a, b});
    g[b].push_back({b, a});
  }

  priority_queue<pair<int, vertex>> q = diam(g, 1);
  int ans = 0;
  while (!q.empty()) {
    pair<int, vertex> p = q.top();
    if (p.first - K - ans <= 0) break;
    if (g[an[p.second]].size() < g[an[t]].size()) {
      ++ans;
      q.pop();
    } else {
      ans += g[an[t]].size();
      t = an[t];
    }
  }

  cout << ans << endl;
}

