		v[b].push_back(a);
	}

	int root;
	for(int i = 0; i < n; ++i){
		if(v[i].size() == 1){
			root = i;
			break;
		}
	}
	yet[root] = 1;
	dist(root);

	vector<int> d;
	for(int i = 0; i < maxk; ++i){
		d.push_back(0);
	}
	for(int i = 0; i < n; ++i){
		++d[ran[i]];
	}
	vector<int> din;
	for(int i = 0; i < d.size(); ++i){
		din.push_back(d[d.size() - 1 - i]);
	}
