void go (int i, int p) {
        for (int j : adj[i]) if (j != p && !dead[j]) {
                d[j] = d[i] + 1;
                go(j, i);
        }
}

int main () {
        scanf("%d %d", &N, &K);
        fo(i, 0, N-1) {
                int a, b; scanf("%d %d", &a, &b);
                edge.PB({a, b});
        }

