                printf("%d\n", N-2);
                return 0;
        }

        while (420) {

                fo(i, 1, N+1) adj[i].clear();
                for (auto i : edge) {
                        int a, b; tie(a,b) = i;
                        if (dead[a] || dead[b]) continue;
                        adj[a].PB(b), adj[b].PB(a);
                }

                //find root which you don't remove
                root = 1;
                fo(i, 1, N+1) if (!dead[i] && (int) adj[i].size() >= 2) root = i;
                //check for finishedness

                //find furthest place
                fo(i, 1, N+1) d[i] = 0;
                go(root, -1);
                //o is the furthest place
                o = 1; fo(i, 1, N+1) if (d[i] > d[o]) o = i;

                //dfs from furthest place
                fo(i, 1, N+1) d[i] = 0;
                go(o, -1);
                //find furthest place from furthest place
                mxi = 1; fo(i, 1, N+1) if (d[i] > d[mxi]) mxi = i;
