                if (num < rem) {
                        ans += num;
                        fo(i, 1, N+1) if (d[i] == d[mxi]) dead[i] = 1;
                } else {
                        ans += rem;
                        int cnt = 0;
                        for (int i : adj[k]) if ((int) adj[i].size() == 1) {
                                dead[i] = 1;
                                cnt++;
                        }
                        assert(cnt == rem);
