vector<vector<pair<int,int> > > at;
int DFS(int u, int p, int d, int id) {
	if (at[d].empty() || at[d].back().second != id)
		at[d].push_back(make_pair(0, id));
	++at[d].back().first;
	int ret = d;
	for(int i=0;i<g[u].size();++i)
		if (g[u][i] != p)
			ret = max(ret, DFS(g[u][i], u, d + 1, id));
	return ret;
}
int calc(int k, int a) {
	at.clear();
	at.resize(n);
	int id = 0;
	for (int i = 0; i < g[a].size(); ++i)
		DFS(g[a][i], a, 1, id++);
	int limit = (k + 1) / 2;
	int res = n;
	for (int i = 1; i<n; ++i)
		if (at[i].size() == 1) {
			limit = min(limit, i - 1 + (k & 1));
			break;
		}
	for (int i = limit + 1; i < n; ++i) {
		for (int j = 0; j < at[i].size(); ++j)
			res -= at[i][j].first;
		at[i].clear();
	}
	if (k & 1) {
		sort(at[limit].begin(), at[limit].end());
		for (int i = 0; i + 1 < at[limit].size(); ++i)
			res -= at[limit][i].first;
	}
	return res;
}
int main()
{
	scanf("%d%d", &n, &k);
	g.resize(n + 1);
	for (int i = 1, a, b; i < n; ++i) {
		scanf("%d%d", &a, &b);
		--a; --b;
		g[a].push_back(b);
		swap(a, b);
		g[a].push_back(b);
	}
	for (int i = 0; i < n; ++i)
		sort(g[i].begin(), g[i].end());
	int res = n;
	for (int i = 0; i < n; ++i) {
		res = min(res, n - calc(k, i));
		for (int j = 0; j < g[i].size(); ++j) {
			int u = i;
			int v = g[i][j];
			g[u].erase(lower_bound(g[u].begin(), g[u].end(), v));
			swap(u, v);
			g[u].erase(lower_bound(g[u].begin(), g[u].end(), v));
			swap(u, v);
			g[n].clear();
			g[n].push_back(u);
			g[n].push_back(v);
			++n;
			res = min(res, n - calc(k + 1, n - 1));
			--n;
			g[u].insert(lower_bound(g[u].begin(), g[u].end(), v), v);
			swap(u, v);
			g[u].insert(lower_bound(g[u].begin(), g[u].end(), v), v);
		}
	}
	printf("%d\n", res);
	return 0;
}

