//!    88   88   88  88.  .88  88  88    88    !//
//!    dP   dP   dP  '88888P8  dP  dP    dP    !//
//!============================================!//
int main()
{
    int N, K;
    std::cin >> N >> K;
    Graph G(N);
    int min = N;
    for (int i = 0, A, B; i < N - 1; i++) { std::cin >> A >> B, A--, B--, G.addEdge(A, B), G.addEdge(B, A); }
    for (int i = 0; i < N; i++) {
        for (const int to : G[i]) {
            std::vector<int> d(N, N);
            d[i] = 0, d[to] = 1;
            auto dfs = [&](auto&& self, const int s, const int p) -> void {
                for (const int to : G[s]) {
                    if (to == p) { continue; }
                    d[to] = d[s] + 1, self(self, to, s);
                }
            };
            dfs(dfs, to, i);
            int sum = 0;
            for (int i = 0; i < N; i++) {
                if (d[i] > K) { sum++; }
            }
            chmin(min, sum);
        }
    }
