				for(j = 0; j < N; j++){
					nowv = t->sorted_v[j];
					if(nowv->val > K / 2){
						count++;
					}
					for(k = 0; k < nowv->chilnum; k++){
						if(j > 0 || k != l){
							nowv->children[k]->val = nowv->val + 1;
						}
					}
				}
				ans = min(ans, count);
			}
		}
	}
	printf("%d\n", ans);
	return 0;
}

