public class Main {
	public static void main(String[] args) {
		InputReader r = new InputReader(System.in);
		int n = r.nextInt();
		int k = r.nextInt();
		ArrayList<Integer> adj[] = new ArrayList[n];
		for (int i = 0; i < adj.length; i++) {
			adj[i] = new ArrayList<Integer>();
		}
		for (int i = 0; i < n - 1; i++) {
			int from = r.nextInt() - 1;
			int to = r.nextInt() - 1;
			adj[from].add(to);
			adj[to].add(from);
		}
		int res = 1 << 28;
		for (int i = 0; i < n; i++) {
			LinkedList<Integer> q = new LinkedList<Integer>();
			q.add(i);
			q.add(0);
			boolean[] vis = new boolean[n];
			vis[i] = true;
			HashSet<Integer> set = new HashSet<Integer>();
			int last = -1;
			while (!q.isEmpty()) {
				int front = q.remove();
				set.add(front);
				last = front;
				int cost = q.remove();
				if (cost == k) {
					continue;
				}
				for (int x : adj[front]) {
					if (!vis[x]) {
						q.add(x);
						q.add(cost + 1);
						vis[x] = true;
					}
				}
			}
			vis = new boolean[n];
			vis[last] = true;
			q.add(last);
			q.add(0);
			int diameter = -1;
			while (!q.isEmpty()) {
				int front = q.remove();
				int cost = q.remove();
				diameter = cost;
				for (int x : adj[front]) {
					if (!vis[x] && set.contains(x)) {
						q.add(x);
						q.add(cost + 1);
						vis[x] = true;
					}
				}
			}
			if (diameter <= k)
				res = Math.min(res, n - set.size());
		}
		System.out.println(res);
	}

