import java.io.*;
import java.util.*;


public class Main {

	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		Printer pr = new Printer(System.out);

		int n = sc.nextInt();
		int k = sc.nextInt();

		List<List<Integer>> edges = new ArrayList<>(n);
		for (int i = 0; i < n; i++) {
			edges.add(new ArrayList<Integer>());
		}

		for (int i = 0; i < n - 1; i++) {
			int a = sc.nextInt() - 1;
			int b = sc.nextInt() - 1;
			edges.get(a).add(b);
			edges.get(b).add(a);
		}

		int ret = Integer.MAX_VALUE;
		for (int i = 0; i < n; i++) {
			int root = i;
			int[] parent = new int[n];
			int[] used = new int[n];
			Deque<Integer> st = new ArrayDeque<>();
			st.push(root);
			parent[root] = -1;
			used[root] = 0;
			int max = 0;
			int maxv = 0;
			while (!st.isEmpty()) {
				int e = st.pop();
				int pe = parent[e];

				for (int ne : edges.get(e)) {
					if (ne == pe) {
						continue;
					}
					st.push(ne);
					parent[ne] = e;
					used[ne] = used[e] + 1;
					if (used[ne] > max) {
						max = used[ne];
						maxv = ne;
					}
				}
			}

			root = maxv;
			parent = new int[n];
			used = new int[n];
			st = new ArrayDeque<>();
			st.push(root);
			parent[root] = -1;
			used[root] = 0;

			int cnt = 0;
			while (!st.isEmpty()) {
				int e = st.pop();
				int pe = parent[e];

				for (int ne : edges.get(e)) {
					if (ne == pe) {
						continue;
					}
					st.push(ne);
					parent[ne] = e;
					used[ne] = used[e] + 1;
					if (used[ne] > k) {
						cnt++;
					}
				}
			}

			ret = Math.min(ret, cnt);
		}

		pr.println(ret);

		pr.close();
		sc.close();
	}

	@SuppressWarnings("unused")
	private static class Scanner {
		BufferedReader br;
		Iterator<String> it;

