public class Main {

	public static final int INF = Integer.MAX_VALUE /2 - 1;

	public static int double_sweep(ArrayList<HashSet<Integer>> adj, boolean[] deleted, final int K){
		LinkedList<Integer> node_queue = new LinkedList<Integer>();
		LinkedList<Integer> parent_queue = new LinkedList<Integer>();
		int[] node_depth = new int[adj.size()];
		Arrays.fill(node_depth, INF);

		node_queue.add(0);
		parent_queue.add(-1);
		node_depth[0] = 0;

		int max_depth = 0, max_node = 0;
		while(!node_queue.isEmpty()){
			final int node   = node_queue.poll();
			final int parent = parent_queue.poll();
			//System.out.println(node);

			for(final int next : adj.get(node)){
				if(next == parent){ continue; }
				if(deleted[next]){ continue; }

				node_depth[next] = node_depth[node] + 1;
				if(max_depth < node_depth[next]){
					max_depth = node_depth[next];
					max_node = next;
				}
				node_queue.add(next);
				parent_queue.add(node);
			}
		}

		node_queue.clear();
		parent_queue.clear();
		Arrays.fill(node_depth, INF);

		node_queue.add(max_node);
		parent_queue.add(-1);
		node_depth[max_node] = 0;
		max_depth = 0;

		while(!node_queue.isEmpty()){
			final int node   = node_queue.poll();
			final int parent = parent_queue.poll();

			for(final int next : adj.get(node)){
				if(next == parent){ continue; }
				if(deleted[next]){ continue; }

				node_depth[next] = node_depth[node] + 1;
				max_depth = Math.max(max_depth, node_depth[next]);
				node_queue.add(next);
				parent_queue.add(node);
			}
		}

		if(max_depth <= K){ return 0; }

		int delete_count = 0;
		for(int i = 0; i < node_depth.length; i++){
			if(node_depth[i] == max_depth){
				deleted[i] = true;
				delete_count++;
			}
		}

		return delete_count;
	}

	public static void main(String[] args) throws IOException {
		final Scanner sc = new Scanner(System.in);

		final int N = sc.nextInt();
		final int K = sc.nextInt();

		ArrayList<HashSet<Integer>> adj = new ArrayList<HashSet<Integer>>();
		for(int i = 0; i < N; i++){
			adj.add(new HashSet<Integer>());
		}

		for(int i = 0; i < N - 1; i++){
			final int fst = sc.nextInt() - 1;
			final int snd = sc.nextInt() - 1;

			adj.get(fst).add(snd);
			adj.get(snd).add(fst);
		}

		boolean[] deleted = new boolean[N];
		int count = 0;
		while(true){
			final int ret = double_sweep(adj, deleted, K);
			if(ret == 0){ break; }

			count += ret;
		}
		System.out.println(count);
	}

	public static class Scanner implements Closeable {
		private BufferedReader br;
		private StringTokenizer tok;

		public Scanner(InputStream is) throws IOException {
			br = new BufferedReader(new InputStreamReader(is));
		}

		private void getLine() throws IOException {
			while (!hasNext()) {
				tok = new StringTokenizer(br.readLine());
			}
		}

		private boolean hasNext() {
			return tok != null && tok.hasMoreTokens();
		}

		public String next() throws IOException {
			getLine();
			return tok.nextToken();
		}

		public int nextInt() throws IOException {
			return Integer.parseInt(next());
		}

		public long nextLong() throws IOException {
			return Long.parseLong(next());
		}

		public double nextDouble() throws IOException {
			return Double.parseDouble(next());
		}

		public void close() throws IOException {
			br.close();
		}
	}
}

import java.util.ArrayList;
import java.util.Scanner;

public class Main {
    int n, k;
    E[] g;

    void run() {

        Scanner sc = new Scanner(System.in);

        n = sc.nextInt(); k = sc.nextInt();
        g = new E[n];
        for (int i = 0; i < n; i++) g[i] = new E();

        int[][] es = new int[n - 1][2];

        for (int i = 0; i < n - 1; i++) {
            int a = sc.nextInt() - 1, b = sc.nextInt() - 1;
            es[i][0] = a; es[i][1] = b;
            g[a].add(b);
            g[b].add(a);
        }

        int ans = 0;

        if (k % 2 == 0) {
            for (int i = 0; i < n; i++) {
                boolean[] visited = new boolean[n];
                ans = Math.max(ans, dfs(i, k / 2, visited));
            }
        } else {
            for (int i = 0; i < n - 1; i++) {
                boolean[] visited = new boolean[n];
                visited[es[i][0]] = visited[es[i][1]] = true;
                int tmp = dfs(es[i][0], k / 2, visited) + dfs(es[i][1], k / 2, visited);
                ans = Math.max(ans, tmp);
            }
        }

        System.out.println(n - ans);
    }

    int dfs(int c, int k, boolean[] visited) {
        visited[c] = true;
        if (k == 0) {
            return 1;
        }
        int sum = 1;
        for (int next: g[c]) if (!visited[next]) {
            sum += dfs(next, k - 1, visited);
        }
        return sum;
    }

    class E extends ArrayList<Integer>{}

    public static void main(String[] args) {
        new Main().run();
    }
}

