	public void solve() {
		N = in.nextInt();
		K = in.nextInt();
		g = new ArrayList[N];
		for (int i = 0; i < N; i++)
			g[i] = new ArrayList<Integer>();

		for (int i = 0; i < N - 1; i++) {
			int a = in.nextInt() - 1, b = in.nextInt() - 1;
			g[a].add(b);
			g[b].add(a);
		}

		int[][] dist = new int[N][N];
		for (int i = 0; i < N; i++) {
			dfs(dist[i], i, -1, 0);
		}

		int res = Integer.MAX_VALUE;
		if (K % 2 == 0) {
			for (int center = 0; center < N; center++) {
				int sum = N;
				for (int to = 0; to < N; to++) {
					if (dist[center][to] <= K / 2) sum--;
				}
				res = Math.min(res, sum);
			}
		} else {
			for (int centerU = 0; centerU < N; centerU++) for (int centerV : g[centerU]) {
				int sum = N;
				for (int to = 0; to < N; to++) {
					if (dist[centerU][to] <= (K - 1) / 2 || dist[centerV][to] <= (K - 1) / 2) sum--;
				}
				res = Math.min(res, sum);
			}
		}
		System.out.println(res);
	}

