import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.util.*;

public class Main {

    static int N;
    static int K;
    static Edge[] E;

    public static void main(String[] args) {
        FastScanner sc = new FastScanner(System.in);
        N = sc.nextInt();
        K = sc.nextInt();
        E = new Edge[N-1];
        for (int i = 0; i < N-1; i++) {
            E[i] = new Edge(sc.nextInt() - 1, sc.nextInt() - 1);
        }

        System.out.println(solve());
    }

    static int solve() {
        List<Edge>[] G = new List[N];
        for (int i = 0; i < N; i++) {
            G[i] = new ArrayList<>();
        }
        for (Edge e : E) {
            G[e.x].add(e);
            G[e.y].add(e);
        }


        int ans = Integer.MAX_VALUE;
        if( K % 2 == 0 ) {
            int r = K / 2;
            for (int v = 0; v < N; v++) {
                ans = Math.min(countOutOfRange(v, r, G), ans);
            }
        } else {
            int r = K / 2;
            for (Edge e : E) {
                ans = Math.min(countOutOfRange(e, r, G), ans);
            }
        }
        return ans;
    }

    static int countOutOfRange(Edge c, int r, List<Edge>[] G) {
        return _count(c.x, r, G, c) + _count(c.y, r, G, c);
    }

    static int countOutOfRange(int c, int r, List<Edge>[] G) {
        return _count(c, r, G, null);
    }

    private static int _count(int c, int r, List<Edge>[] G, Edge ignore) {
        ArrayDeque<State> q = new ArrayDeque<>();
        int[] dist = new int[N];
        Arrays.fill(dist, -1);
        dist[c] = 0;
        q.add(new State(c, 0));
        while(!q.isEmpty()) {
            State s = q.poll();
            if( dist[s.a] != s.d ) continue;

            for (Edge e : G[s.a]) {
                if( ignore != null && e == ignore ) continue;

                int b = e.opposite(s.a);
                if( dist[b] == -1 ) {
                    q.add( new State(b, s.d+1) );
                    dist[b] = s.d + 1;
                }
            }
        }

        int cnt = 0;
        for (int i = 0; i < N; i++) {
            if(dist[i] > r ) cnt++;
        }
        return cnt;
    }

    static class Edge {
        int x;
        int y;

        public Edge(int x, int y) {
            this.x = x;
            this.y = y;
        }

        public int opposite(int a) {
            return a == x ? y : x;
        }
    }

    static class State {
        int a;
        int d;

        public State(int a, int d) {
            this.a = a;
            this.d = d;
        }
    }

    @SuppressWarnings("unused")
    static class FastScanner {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner(InputStream in) {
            reader = new BufferedReader(new InputStreamReader(in));
            tokenizer = null;
        }

        String next() {
            if (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        String nextLine() {
            if (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    return reader.readLine();
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken("\n");
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        int[] nextIntArray(int n) {
            int[] a = new int[n];
            for (int i = 0; i < n; i++)
                a[i] = nextInt();
            return a;
        }

        long[] nextLongArray(int n) {
            long[] a = new long[n];
            for (int i = 0; i < n; i++)
                a[i] = nextLong();
            return a;
        }
    }
}

import java.io.BufferedReader;
import java.io.Closeable;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedList;
import java.util.StringTokenizer;

public class Main {

	public static final int INF = Integer.MAX_VALUE /2 - 1;

	public static int[] sweep(int start, ArrayList<HashSet<Integer>> adj, boolean[] deleted){
		LinkedList<Integer> node_queue = new LinkedList<Integer>();
		LinkedList<Integer> parent_queue = new LinkedList<Integer>();
		int[] node_depth = new int[adj.size()];
		Arrays.fill(node_depth, INF);

		node_queue.add(start);
		parent_queue.add(-1);
		node_depth[start] = 0;

		while(!node_queue.isEmpty()){
			final int node   = node_queue.poll();
			final int parent = parent_queue.poll();

			for(final int next : adj.get(node)){
				if(next == parent){ continue; }
				if(deleted[next]){ continue; }

				node_depth[next] = node_depth[node] + 1;
				node_queue.add(next);
				parent_queue.add(node);
			}
		}

		return node_depth;
	}

	public static int double_sweep(ArrayList<HashSet<Integer>> adj, boolean[] deleted, final int K){
		int pre_start = -1;
		for(int i = 0; i < deleted.length; i++){
			if(!deleted[i]){ pre_start = i; }
		}

		final int[] pre_sweeped = sweep(pre_start, adj, deleted);
		int pre_max_depth = 0, pre_max_node = pre_start;
		for(int i = 0; i < pre_sweeped.length; i++){
			if(deleted[i]){ continue; }

			if(pre_max_depth < pre_sweeped[i]){
				pre_max_depth = pre_sweeped[i];
				pre_max_node = i;
			}
		}

		final int[] fst_sweeped = sweep(pre_max_node, adj, deleted);
		int fst_max_depth = 0, fst_max_node = pre_max_node;
		for(int i = 0; i < fst_sweeped.length; i++){
			if(deleted[i]){ continue; }

			if(fst_max_depth < fst_sweeped[i]){
				fst_max_depth = fst_sweeped[i];
				fst_max_node = i;
			}
		}

		final int[] snd_sweeped = sweep(fst_max_node, adj, deleted);
		int snd_max_depth = 0, snd_max_node = fst_max_node;
		for(int i = 0; i < snd_sweeped.length; i++){
			if(deleted[i]){ continue; }

			if(snd_max_depth < snd_sweeped[i]){
				snd_max_depth = snd_sweeped[i];
				snd_max_node = i;
			}
		}

		int fst_count = 0, snd_count = 0;
		for(int i = 0; i < adj.size(); i++){
			if(deleted[i]){ continue; }

			if(fst_max_depth > K && fst_sweeped[i] == fst_max_depth){ fst_count++; }
			if(snd_max_depth > K && snd_sweeped[i] == snd_max_depth){ snd_count++; }
		}

		//System.out.println(fst_count + " : " + snd_count);

		int delete_count = 0;
		if(fst_count < snd_count){
			for(int i = 0; i < adj.size(); i++){
				if(deleted[i]){ continue; }

				if(fst_max_depth > K && fst_sweeped[i] == fst_max_depth){ 
					deleted[i] = true;
					delete_count++;
				}
			}
		}else{
			for(int i = 0; i < adj.size(); i++){
				if(deleted[i]){ continue; }

				if(snd_max_depth > K && snd_sweeped[i] == snd_max_depth){
					deleted[i] = true;
					delete_count++;
				}
			}
		}

		return delete_count;
	}

	public static void main(String[] args) throws IOException {
		final Scanner sc = new Scanner(System.in);

		final int N = sc.nextInt();
		final int K = sc.nextInt();

		ArrayList<HashSet<Integer>> adj = new ArrayList<HashSet<Integer>>();
		for(int i = 0; i < N; i++){
			adj.add(new HashSet<Integer>());
		}

		for(int i = 0; i < N - 1; i++){
			final int fst = sc.nextInt() - 1;
			final int snd = sc.nextInt() - 1;

			adj.get(fst).add(snd);
			adj.get(snd).add(fst);
		}

		boolean[] deleted = new boolean[N];
		int count = 0;
		while(true){
			final int ret = double_sweep(adj, deleted, K);
			if(ret == 0){ break; }

			count += ret;
		}
