            dfs2(root, -1, 0);
            int ret = 0;
            if (k % 2 == 0) {
                for (int j = 1; j <= n; j++) {
                    if (depth[j] > k / 2) {
                        ret++;
                    }
                }
                ans = Math.min(ans, ret);
            } else {
                int [] depth2 = new int [n+1];
                for (int j = 1; j <= n; j++) depth2[i] = depth[i];
                for (Integer p: adj[i]) {
                    dfs2(p, -1, 0);
                    for (int j = 1; j <= n; j++) {
                        if (depth[i] > k / 2 && depth2[i] > k / 2) ret++;
                    }
                    ans = Math.min(ans, ret);
                }
            }
        }
        System.out.println(ans);
    }

    static void dfs(int cur, int dep, int par) {
        if (dep > root) {
            bestDepth = dep;
            root = cur;
        }
        for (Integer next: adj[cur]) {
            if (next != par) {
                dfs(next, dep + 1, cur);
            }
        }
    }

    static void dfs2(int cur, int par, int dep) {
        depth[cur] = dep;
        for (Integer next: adj[cur]) {
            if (next != par) {
                dfs2(next, cur, dep + 1);
            }
        }
    }


