			int degmax = 0;
			for(int j=0;j<n;j++) {
				if (dist[i][j] <= r) {
					count++;
				}
				if (dist[i][j] == r) {
					degmax = Math.max(degmax, g.graph[j].size());
				}
			}
			if (k % 2 == 1) {
