	private void solve(FastIO io, String[] args) {
		/*
		 * author: 31536000
		 *
		 * 考察メモ
		 * Kが偶数であるとすると、必ず中心となる頂点が一つある
		 * そこで、その中心を決め打つと調べることができる
		 * 次に奇数の時、必ず中心となる辺が一つある
		 * よって、これも同様に求めることができる
		 */
		int N = io.nextInt(), K = io.nextInt();
		ArrayList<ArrayList<Integer>> graph = new ArrayList<>();
		for (@SuppressWarnings("unused")final int i : IntRange.open(N))  graph.add(new ArrayList<>());
		for (int i = 1;i < N;++ i) {
			int A = io.nextInt() - 1, B = io.nextInt() - 1;
			graph.get(A).add(B);
			graph.get(B).add(A);
		}
		int ans = N;
		if (K % 2 == 0) {
			for (int i = 0;i < N;++ i) {
				int[] dist = new int[N];
				int count = N;
				BreadthFirstSearch<Integer> bfs = new BreadthFirstSearch<Integer>();
				bfs.push(i);
				for (int j : bfs) {
					if (dist[j] > K / 2) continue;
					-- count;
					for (int k : graph.get(j)) if (bfs.push(k)) dist[k] = dist[j] + 1;
				}
				ans = Math.min(ans, count);
			}
		} else {
			for (int i = 0;i < N;++ i) {
				for (int j : graph.get(i)) {
					int[] dist = new int[N];
					int count = N;
					BreadthFirstSearch<Integer> bfs = new BreadthFirstSearch<Integer>();
					bfs.push(i);
					bfs.push(j);
					for (int k : bfs) {
						if (dist[k] > K / 2) continue;
						-- count;
						for (int l : graph.get(k)) if (bfs.push(l)) dist[l] = dist[k] + 1;
					}
					ans = Math.min(ans, count);
				}
			}
		}
		io.println(ans);
	}

