	{
		int n = ni(), K = ni();
		int[] from = new int[n-1];
		int[] to = new int[n-1];
		for(int i = 0;i < n-1;i++){
			from[i] = ni()-1;
			to[i] = ni()-1;
		}
		int[][] g = packU(n, from, to);
		int min = n;
		for(int i = 0;i < n;i++){
			min = Math.min(min, go(g, i, K));
		}
		out.println(min);
	}

	static int go(int[][] g, int root, int K)
	{
		int[][] pars = parents3(g, root);
		int[] par = pars[0], ord = pars[1], dep = pars[2];
		int n = g.length;
		if(K % 2 == 0){
			int ct = 0;
			for(int i = 0;i < n;i++){
				if(dep[i] > K/2)ct++;
			}
			return ct;
		}
		int[] dp = new int[n];
		for(int i = n-1;i >= 1;i--){
			int cur = ord[i];
			if(dep[cur] == K/2+1){
				dp[cur]++;
			}
			dp[par[cur]] += dp[cur];
		}
		int max = 0;
		for(int e : g[root]){
			max = Math.max(max, dp[e]);
		}
		int ct = 0;
		for(int i = 0;i < n;i++){
			if(dep[i] > K/2)ct++;
		}
		return ct-max;
	}

	public static int[][] parents3(int[][] g, int root) {
		int n = g.length;
		int[] par = new int[n];
		Arrays.fill(par, -1);

		int[] depth = new int[n];
		depth[0] = 0;

		int[] q = new int[n];
		q[0] = root;
		for (int p = 0, r = 1; p < r; p++) {
			int cur = q[p];
			for (int nex : g[cur]) {
				if (par[cur] != nex) {
					q[r++] = nex;
					par[nex] = cur;
					depth[nex] = depth[cur] + 1;
				}
			}
		}
		return new int[][] { par, q, depth };
	}


	static int[][] packU(int n, int[] from, int[] to) {
		int[][] g = new int[n][];
		int[] p = new int[n];
		for (int f : from)
			p[f]++;
		for (int t : to)
			p[t]++;
		for (int i = 0; i < n; i++)
			g[i] = new int[p[i]];
		for (int i = 0; i < from.length; i++) {
			g[from[i]][--p[from[i]]] = to[i];
			g[to[i]][--p[to[i]]] = from[i];
		}
		return g;
	}

