public class Main {
    public static void main(String[] args){
        Main gv = new Main();
        gv.solve();
    }

    private List<List<Integer>> str;
    private int[] dist;
    private int n,k;

    private void solve(){
        MyScanner sc = new MyScanner();
        out = new PrintWriter(new BufferedOutputStream(System.out));
        n = sc.nextInt();
        k = sc.nextInt();

        str = new ArrayList<>(n);
        for(int i=0 ;i<n;i++){
            str.add(new ArrayList<>());
        }
        for(int i=0;i<n-1;i++){
            int x = sc.nextInt();
            int y = sc.nextInt();

            str.get(x-1).add(y-1);
            str.get(y-1).add(x-1);
        }

        out.println(doCal());
        out.close();
    }

    private int doCal(){
        dist = new int[n];
        int c = k/2;
        int ret = Integer.MAX_VALUE;
        for(int i=0;i<n;i++){
            Arrays.fill(dist,Integer.MAX_VALUE);
            doBFS(i);
            int cnt = 0;
            for(int j=0;j<n;j++){
                if(dist[j] > c) cnt++;
            }
            ret = Math.min(cnt,ret);
        }
        return ret;
    }

    private void doBFS(int v){
        Queue<Integer> tmp = new LinkedList<>();
        dist[v] = 0;
        tmp.add(v);

        while(tmp.size() > 0){
            int u = tmp.poll();

            for(int i:str.get(u)){
                if(dist[i] == Integer.MAX_VALUE || dist[i] > dist[u]+1){
                    dist[i] = dist[u]+1;
                    tmp.add(i);
                }
            }
        }
    }

    public static PrintWriter out;

    private static class MyScanner{
        BufferedReader bufferedReader;
        StringTokenizer stringTokenizer;

        private MyScanner(){
            bufferedReader = new BufferedReader(new InputStreamReader(System.in));
        }

        private String next(){
            if(stringTokenizer == null || !stringTokenizer.hasMoreElements()){
                try {
                    stringTokenizer = new StringTokenizer(bufferedReader.readLine());
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return stringTokenizer.nextToken();
        }

        private int nextInt(){
            return Integer.parseInt(next());
        }
        private String nextLine(){
            String ret= "";
            try {
                ret= bufferedReader.readLine();
            } catch (IOException e) {
                e.printStackTrace();
            }
            return ret;
        }
    }
}

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Scanner;

public class Main {
	public static void main(String[] args) {
		solver();
	}

	static void solver() {
		Scanner sc = new Scanner(System.in);
		int n = sc.nextInt();
		int k = sc.nextInt();// modify the graphs to the one whose diameter is
		// equal or shorter than k.
		ArrayList<Integer>[] e = new ArrayList[n];
		for (int i = 0; i < n; i++) {
			e[i] = new ArrayList<Integer>();
		}
		for (int i = 0; i < n - 1; i++) {
			int a = sc.nextInt() - 1;
			int b = sc.nextInt() - 1;
			e[a].add(b);
			e[b].add(a);
		}
		depth = new int[n];
		if (k % 2 == 0) {
			int ans = Integer.MAX_VALUE / 4;
			for (int i = 0; i < n; i++) {
				Arrays.fill(depth, 0);
				bfs(i, -1, 0, e);
				int count = 0;
				for (int j = 0; j < n; j++) {
					if (depth[j] > k / 2)
						count++;
				}
				ans = Math.min(ans, count);
			}
			System.out.println(ans);
		} else if (k % 2 == 1) {
			int ans = Integer.MAX_VALUE / 4;
			for (int i = 0; i < n; i++) {
				Arrays.fill(depth, 0);
				bfs(i, -1, 0, e);
				int[] depth1 = Arrays.copyOf(depth, depth.length);
				for (int v : e[i]) {

					Arrays.fill(depth, 0);
					bfs(v, -1, 0, e);

					int[] depth2 = Arrays.copyOf(depth, depth.length);
					int count = 0;
					for (int j = 0; j < n; j++) {
						if (depth1[j] > k / 2 && depth2[j] > k / 2) {
							count++;
						}
					}
					ans = Math.min(ans, count);
				}
			}
			System.out.println(ans);
		}
	}

	static int[] depth;

	static void bfs(int v, int p, int d, ArrayList<Integer>[] e) {
		ArrayDeque<P> q = new ArrayDeque<P>();
		q.add(new P(v, p, d));
		while (!q.isEmpty()) {
			P u = q.poll();
			depth[u.me] = u.depth;
			for (int i = 0; i < e[u.me].size(); i++) {
				if (e[u.me].get(i) != u.parent)
					q.add(new P(e[u.me].get(i), u.me, u.depth + 1));
			}
		}
	}

	static class P {
		int parent;
		int me;
		int depth;

		P(int me, int parent, int depth) {
			this.me = me;
			this.parent = parent;
			this.depth = depth;
		}
	}

}

