    static class LCA {
        int root, V;
        ArrayList<Integer>[] edge;
        int[][] parent;
        int[] depth;

        LCA(int size) {
            root = 0;
            V = size;
            edge = Stream.generate(ArrayList::new).limit(size).toArray(ArrayList[]::new);
            parent = new int[70][V];
            depth = new int[V];

        }

        void unite(int u, int v) {
            edge[u].add(v);
            edge[v].add(u);
        }

        LCA(int r, ArrayList<Integer>[] ed) {
            root = r;
            V = ed.length;
            edge = ed;
            parent = new int[70][V];
            depth = new int[V];
            dfs(root, -1, 0);
            for (int k = 0; k < parent.length - 1; k++) {
                for (int v = 0; v < V; v++) {
                    if (parent[k][v] < 0) parent[k + 1][v] = -1;
                    else parent[k + 1][v] = parent[k][parent[k][v]];
                }
            }
        }

        void dfs(int v, int p, int dep) {
            parent[0][v] = p;
            depth[v] = dep;
            for (Integer to : edge[v]) {
                if (to != p) dfs(to, v, dep + 1);
            }
        }

        int len(int u, int v) {
            int oya = lca(u, v);
            return depth[u] - depth[oya] + depth[v] - depth[oya];

        }

        int lca(int u, int v) {
            if (depth[0] == 0 && depth[1] == 0) {
                dfs(root, -1, 0);
                for (int k = 0; k < parent.length - 1; k++) {
                    for (int vi = 0; vi < V; vi++) {
                        if (parent[k][vi] < 0) parent[k + 1][vi] = -1;
                        else parent[k + 1][vi] = parent[k][parent[k][vi]];
                    }
                }
            }
            if (depth[u] > depth[v]) {
                int tu = u;
                u = v;
                v = tu;
            }
            for (int k = 0; k < parent.length; k++) {
                if (((depth[v] - depth[u]) >> k & 1) == 1) {
                    v = parent[k][v];
                }

            }
            if (u == v) return u;
            for (int k = parent.length - 1; k >= 0; k--) {
                if (parent[k][u] != parent[k][v]) {
                    u = parent[k][u];
                    v = parent[k][v];
                }
            }
            return parent[0][u];
        }
    }

