public class Main {

	class Node{
		int idx;
		ArrayList<Node> edge;
		int[] cost;
		int child;
		boolean flg;
		public Node(int idx){
			this.idx = idx;
			cost = new int[N];
			Arrays.fill(cost, -1);
			edge = new ArrayList<>();
		}
	}

	int N;
	int K;
	Node[] nodes;
	int ans = Integer.MAX_VALUE;

	public void solve(){
		N = nextInt();
		K = nextInt();
		nodes = new Node[N];

		for(int i = 0; i < N; i++){
			nodes[i] = new Node(i);
		}

		for(int i = 0; i < N - 1; i++){
			int a = nextInt() - 1;
			int b = nextInt() - 1;
			nodes[a].edge.add(nodes[b]);
			nodes[b].edge.add(nodes[a]);
		}
		recur(nodes[0]);
		r2(nodes[0], 0);
		out.println(ans);

	}

	public int recur(Node n){
		if(n.flg){
			return 0;
		}
		int sum = 0;
		n.flg = true;
		for(Node nn : n.edge){
			sum += recur(nn);
		}
		n.flg = false;
		n.child = sum;

		return sum + 1;
	}

	public int r2(Node cur, int on){
		if(cur.flg){
			return 0;
		}
		if(ans <= on){
			return 0;
		}

		cur.flg = true;
		for(int i = 0; i <= (K - i); i++){
			for(int j = 0; j < cur.edge.size(); j++){
				if(cur.edge.get(j).flg) continue;
				int sum = r3(cur.edge.get(j), i);

				for(int k = 0; k < cur.edge.size(); k++){
					if(j == k) continue;
					sum += r3(cur.edge.get(k), K - i);
				}
				ans = Math.min(ans, sum + on);
			}
		}

		for(Node n : cur.edge){
			if(!n.flg){
				r2(n, on + cur.child + 1 - n.child);
			}
		}

		cur.flg = false;
		return 0;

	}


	public int r3(Node cur, int path){
		if(cur.flg){
			return 0;
		}

		if(path == 0){
			return cur.child + 1;
		}

		if(path == 1){
			return cur.child;
		}
		if(cur.cost[path] != -1){
			return cur.cost[path];
		}

		int sum = 0;
		cur.flg = true;
		for(Node nn : cur.edge){
			sum += r3(nn, path - 1);
		}
		cur.flg = false;

		return cur.cost[path] = sum ;

	}

