	static List<Integer>[]createGraph(int n)
    {List<Integer>[]g=new List[n];for(int i=0;i<n;i++)g[i]=new ArrayList<>();return g;}
	void solve() throws IOException{
		int n = in.nextInt();
		int k = in.nextInt();
		List<Integer>[] node = createGraph(n);
		int[] ea = new int[n-1];
		int[] eb = new int[n-1];
		for(int i=0; i<n-1; i++){
			int a = in.nextInt()-1;
			int b = in.nextInt()-1;
			node[a].add(b);
			node[b].add(a);
		}
		used = new BitSet(n);
		Queue<Pair> qu = new ArrayDeque<>();
		int max = 0;
		if(k%2==0){
			for(int i=0; i<n; i++){
				qu.add(new Pair(i, 1));
				max = Math.max(max, res(qu, k+1, node));
			}
		}else{
			for(int i=0; i<n-1; i++){
				qu.add(new Pair(ea[i], 2));
				qu.add(new Pair(eb[i], 2));
				max = Math.max(max, res(qu, k+1, node));
			}
		}
		System.out.println(n-max);
	}

	BitSet used;
	int res(Queue<Pair> qu, int k, List<Integer>[] node){
		used.clear();
		while(!qu.isEmpty()){
			Pair p = qu.poll();
			final int cur = p.a;
			final int dist = p.b;
			if(used.get(cur)) continue;
			used.set(cur);
			if(dist==k) continue;
			for(int v: node[cur]){
				qu.add(new Pair(v, dist+2));
			}
		}
		return used.cardinality();
	}
