public class Main {
    static int n;
    static int k;
    static ArrayList<Integer>[] edge;
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        k = sc.nextInt();
        edge = new ArrayList[n];
        for(int i=0; i<n; i++) edge[i] = new ArrayList<Integer>();
        for(int i=0; i<n-1; i++){
            int a = sc.nextInt() - 1;
            int b = sc.nextInt() - 1;
            edge[a].add(b);
            edge[b].add(a);
        }
        sc.close();

        int ans = Integer.MAX_VALUE;
        for(int i=0; i<n; i++){
            ans = Math.min(ans, countDelNum(i));
        }
        if(k%2==1 && ans > 0) ans--;
        System.out.println(ans);
    }

    public static int countDelNum(int root){
        int count = n;
        ArrayDeque<Integer[]> que = new ArrayDeque<Integer[]>();
        boolean[] use = new boolean[n];
        que.add(new Integer[]{root, 0});
        use[root] = true;
        while(que.size()>0){
            Integer[] cur = que.poll();
            if(cur[1] > k/2) break;
            for(int i=0; i<edge[cur[0]].size(); i++){
                Integer next = edge[cur[0]].get(i);
                if(!use[next]){
                    que.add(new Integer[]{next, cur[1]+1});
                    use[next] = true;
                }
            }
            count--;
        }
        return count;
    }
}

import java.util.LinkedList;
import java.util.List;
import java.util.Scanner;

public class Main {
	int n, k;
	List<Integer>[] e;
	boolean[] del;

	void depth(int i, boolean[] f, int[] depth, int d) {
		if (f[i] || del[i]) {
			return;
		}
		f[i] = true;
		depth[i] = d;
		for (Integer to : e[i]) {
			depth(to, f, depth, d + 1);
		}
	}

	void run() {
		Scanner sc = new Scanner(System.in);

		n = sc.nextInt();
		k = sc.nextInt();
		e = new LinkedList[n];
		for (int i = 0; i < n; i++) {
			e[i] = new LinkedList<Integer>();
		}
		for (int i = 0; i < n - 1; i++) {
			int a = sc.nextInt() - 1;
			int b = sc.nextInt() - 1;
			e[a].add(b);
			e[b].add(a);
		}

		int count = 0;
		del = new boolean[n];
		boolean f = true;
		while (f) {
			f = false;
			int[] depth = new int[n];
			for (int i = 0;; i++) {
				if (!del[i]) {
					depth(0, new boolean[n], depth, 0);
					break;
				}
			}
			int root = 0;
			for (int i = 0; i < n; i++) {
				if (depth[root] < depth[i]) {
					root = i;
				}
			}
			depth(root, new boolean[n], depth, 0);
			for (int i = 0; i < n; i++) {
				if (k < depth[i]) {
					count++;
					f = true;
					del[i] = true;
				}
			}
		}
		System.out.println(count);
	}

	public static void main(String[] args) {
		new Main().run();
	}
}

