public class Main {

    static int[] readArray(int size, InputReader in) {
        int[] a = new int[size];
        for (int i = 0; i < size; i++) {
            a[i] = in.nextInt();
        }
        return a;
    }

    static long[] readLongArray(int size, InputReader in) {
        long[] a = new long[size];
        for (int i = 0; i < size; i++) {
            a[i] = in.nextLong();
        }
        return a;
    }

    private static class Node {
        int num;
        Set<Node> children = new HashSet<>();

        public Node(int num) {
            this.num = num;
        }

        @Override
        public String toString() {
            return "Node:" + num;
        }
    }

    public static void main(String[] args) throws FileNotFoundException {
        InputReader in = new InputReader(System.in);
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));

        int n = in.nextInt();
        int k = in.nextInt();
        Node[] nodes = new Node[n + 1];
        for (int i = 1; i <= n; i++) {
            nodes[i] = new Node(i);
        }

        for (int i = 0; i < n - 1; i++) {
            int u = in.nextInt();
            int v = in.nextInt();

            nodes[u].children.add(nodes[v]);
            nodes[v].children.add(nodes[u]);
        }

        int min = solve(n, k, nodes, 1);
        out.println(min);

        out.close();
    }

    private static int solve(int n, int k, Node[] nodes, int nodeNum) {
        List<Node> longestPath = bfs(nodes[nodeNum], n, nodes);
        longestPath = bfs(nodes[longestPath.get(longestPath.size() - 1).num], n, nodes);
        int diameter = longestPath.size() - 1;

        int min = Integer.MAX_VALUE;
        if (diameter <= k) {
            return 0;
        }

        List<Node> subTreeStarts = new ArrayList<>();
        boolean[] visited = new boolean[n + 1];
        if (diameter % 2 == 1) {
            Node v = longestPath.get((diameter + 1) / 2);
            subTreeStarts.add(v);
            Node u = longestPath.get((diameter + 1) / 2 - 1);
            subTreeStarts.add(u);

            u.children.remove(v);
            v.children.remove(u);
        } else {
            int center = longestPath.get((diameter + 1) / 2).num;
            visited[center] = true;
            subTreeStarts.addAll(nodes[center].children);
            for (Node subTreeStart : subTreeStarts) {
                subTreeStart.children.remove(nodes[center]);
                nodes[center].children.remove(subTreeStart);
            }
        }

        Map<Integer, Map<Integer, Integer>> toCutForLevel = new HashMap<>();
        for (Node subTreeStart : subTreeStarts) {
            visited[subTreeStart.num] = true;
        }
        for (Node subTreeStart : subTreeStarts) {
            HashMap<Integer, Integer> subToCutForLevel = new HashMap<>();
            int res = dfs(subTreeStart, visited, subToCutForLevel, 0);
            subToCutForLevel.put(0, res);
            toCutForLevel.put(subTreeStart.num, subToCutForLevel);
        }


        int d = diameter % 2 == 0 ? diameter : (diameter - 1);
        for (int i = Math.max(0, (d - 2 * k) / 2); 2 * i <= d - k; i++) {
            int sum = 0;
            for (Map<Integer, Integer> subToCut : toCutForLevel.values()) {
                sum += subToCut.getOrDefault(i + k - d / 2, 0);
            }
            for (Map<Integer, Integer> subToCut : toCutForLevel.values()) {
                int s1 = sum - subToCut.getOrDefault(i + k - d / 2, 0);
                s1 += subToCut.getOrDefault(d / 2 - i, 0);
                min = Math.min(min, s1);
            }
        }

        if (k < (diameter + 1) / 2) {
            for (Integer subTreeStart : toCutForLevel.keySet()) {
                int s1 = n - toCutForLevel.get(subTreeStart).getOrDefault(0, 0);
                s1 += solve(n, k, nodes, subTreeStart);
                min = Math.min(min, s1);
            }
        }
        return min;
    }

    private static int dfs(Node node, boolean[] visited, HashMap<Integer, Integer> toCutForLevel, int level) {
        visited[node.num] = true;

        int res = 0;
        for (Node child : node.children) {
            if (!visited[child.num]) {
                res += dfs(child, visited, toCutForLevel, level + 1);
            }
        }
        toCutForLevel.put(level + 1, toCutForLevel.getOrDefault(level + 1, 0) + res);

        return res + 1;
    }

    private static List<Node> bfs(Node node, int n, Node[] nodes) {
        Queue<Node> q = new LinkedList<>();
        q.add(node);
        boolean[] used = new boolean[n + 1];
        int[] parents = new int[n + 1];
        int[] distances = new int[n + 1];
        used[node.num] = true;
        parents[node.num] = -1;

        while (!q.isEmpty()) {
            Node v = q.poll();
            for (Node to : v.children) {
                if (!used[to.num]) {
                    used[to.num] = true;
                    q.add(to);
                    distances[to.num] = distances[v.num] + 1;
                    parents[to.num] = v.num;
                }
            }
        }

        int maxNodeInd = -1;
        int maxDist = 0;
        for (int i = 1; i <= n; i++) {
            if (distances[i] > maxDist) {
                maxDist = distances[i];
                maxNodeInd = i;
            }
        }

        List<Node> path = new ArrayList<>();
        for (int v = maxNodeInd; v != -1; v = parents[v]) {
            path.add(nodes[v]);
        }
        Collections.reverse(path);
        return path;
    }


    private static void outputArray(long[] ans, PrintWriter out) {
        StringBuilder str = new StringBuilder();
        for (long an : ans) {
            str.append(an).append(' ');
        }
        out.println(str);
    }

    private static class InputReader {
        public BufferedReader reader;
        public StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                createTokenizer();
            }
            return tokenizer.nextToken();
        }

        private void createTokenizer() {
            try {
                tokenizer = new StringTokenizer(reader.readLine());
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }

        public String nextWord() {
            return next();
        }

        public String nextString() {
            try {
                return reader.readLine();
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public char nextChar() {
            return next().charAt(0);
        }

        public int[] nextInts() {
            if (tokenizer == null || !tokenizer.hasMoreTokens()) {
                createTokenizer();
            }
            List<Integer> res = new ArrayList<>();
            while (tokenizer.hasMoreElements()) {
                res.add(Integer.parseInt(tokenizer.nextToken()));
            }
            int[] resArray = new int[res.size()];
            for (int i = 0; i < res.size(); i++) {
                resArray[i] = res.get(i);
            }
            return resArray;
        }
    }
}

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Scanner;

public class Main
{
    private static class Edge
    {
        Vertex from, to;
        long fromDepth, toDepth;
        long fromCost, toCost;

        public Edge(Vertex from, Vertex to)
        {
            this.from = from;
            this.to = to;
            this.from.edges.add(this);
            this.to.edges.add(this);
        }

        void setFrom(Vertex newFrom)
        {
            // Swap if needed
            if (newFrom == to)
            {
                Vertex tmp = this.from;
                this.from = to;
                to = tmp;
            }
            else if (newFrom != from)
                throw new RuntimeException("Abracadabra froms do not agree");
        }
    }

    private static class GraphTraversalData
    {
        final long maxDepthFromThisVertex, maxCostFromThisVertex;

        GraphTraversalData(long maxDepthFromThisVertex, long maxCostFromThisVertex)
        {
            this.maxDepthFromThisVertex = maxDepthFromThisVertex;
            this.maxCostFromThisVertex = maxCostFromThisVertex;
        }
    }

    private static class Vertex
    {
        final long vindex;
        List<Edge> edges = new ArrayList<Edge>();

        Vertex(long vindex)
        {
            this.vindex = vindex;
        }

        public String toString()
        {
            return Long.toString(vindex);
        }

        public void populateData()
        {
            // First pass to figure out the out/to direction
            for (Edge edge : edges)
            {
                edge.setFrom(this);
                edge.to.traverseGraphAndSetToData(edge);
            }

            // Second pass to figure out the in/from direction
            traverseGraphAndSetFromData(null);
        }

        void traverseGraphAndSetFromData(Edge arrivedVia)
        {
            long totalCostViaOtherEdges, maxDViaOtherEdges;

            for (Edge edge : edges)
            {
                if (edge != arrivedVia)
                {
                    totalCostViaOtherEdges = 0;
                    maxDViaOtherEdges = 0;
                    for (Edge tmpEdge : edges)
                    {
                        if (tmpEdge != edge && tmpEdge != arrivedVia)
                        {
                            totalCostViaOtherEdges += tmpEdge.toCost;
                            maxDViaOtherEdges = Math.max(maxDViaOtherEdges, tmpEdge.toDepth);
                        }
                    }

                    if (arrivedVia != null)
                    {
                        totalCostViaOtherEdges += arrivedVia.fromCost;
                        maxDViaOtherEdges = Math.max(maxDViaOtherEdges, arrivedVia.fromDepth);
                    }

                    edge.fromCost = totalCostViaOtherEdges + 1;
                    edge.fromDepth = maxDViaOtherEdges + 1;

                    edge.to.traverseGraphAndSetFromData(edge);
                }
            }
        }

        private GraphTraversalData traverseGraphAndSetToData(Edge arrivedVia)
        {
            long maxDepthFromThisVertex = 0;
            long maxCostFromThisVertex = 1;
            for (Edge edge : edges)
            {
                if (edge != arrivedVia)
                {
                    edge.setFrom(this);
                    GraphTraversalData graphTraversalData = edge.to.traverseGraphAndSetToData(edge);
                    maxCostFromThisVertex += graphTraversalData.maxCostFromThisVertex;
                    maxDepthFromThisVertex = Math.max(maxDepthFromThisVertex, graphTraversalData.maxDepthFromThisVertex);
                }
            }

            arrivedVia.toDepth = maxDepthFromThisVertex + 1;
            arrivedVia.toCost = maxCostFromThisVertex;
            return new GraphTraversalData(arrivedVia.toDepth, maxCostFromThisVertex);
        }
    }

    public static void main(String[] args)
    {
      Scanner sc = new Scanner(System.in);
      int n = sc.nextInt();
      int d = sc.nextInt();
      String sampleInput = n + " " +d +"\n";
      for (int i = 0; i<n-1;i++){
        String a = sc.next();
        String b= sc.next();
        sampleInput = sampleInput + a+" "+b+"\n";
      }
        solve(sampleInput, false);
    }

    private static int solve(String input, boolean testMode)
    {
        String[] lines = input.split("\n");
        String[] NandK = lines[0].split(" ");
        //System.out.println("N is " + NandK[0] + ", K is " + NandK[1]);

