	static class TaskX {

		@SuppressWarnings("unchecked")
		public void solve(int testNumber, InputReader in, PrintWriter out) {

			int n = in.nextInt(), k = in.nextInt();
			List<Integer>[] g = new ArrayList[n];
			g = Stream.generate(ArrayList::new).limit(n).toArray(List[]::new);

			int[] a = new int[n], b = new int[n];
			for (int i = 0; i < n-1; i++) {
				a[i] = in.nextInt()-1;
				b[i] = in.nextInt()-1;
				g[a[i]].add(b[i]);
				g[b[i]].add(a[i]);
			}

			int count = INF;
			if (k % 2 == 0) {

				for (int i = 0; i < n; i++) {
					Queue<Integer> q = new ArrayDeque<>();
					boolean[] used = new boolean[n];
					int[] cost = new int[n];
					Arrays.fill(cost, INF);

					q.add(i);
					used[i] = true;
					cost[i] = 0;

					int tmp = 0;
					while (!q.isEmpty()) {
						int now = q.remove();

						for (int to : g[now]) {
							if (used[to]) continue;
							cost[to] = cost[now] + 1;
							if (cost[to] > k / 2) tmp++;
							used[to] = true;
							q.add(to);
						}
					}

					count = Math.min(count, tmp);
				}

			} else {

				for (int i = 0; i < n-1; i++) {
					Queue<Integer> q = new ArrayDeque<>();
					boolean[] used = new boolean[n];
					int[] cost = new int[n];
					Arrays.fill(cost, INF);

					q.add(a[i]);
					used[a[i]] = true;
					cost[a[i]] = 0;

					while (!q.isEmpty()) {
						int now = q.remove();

						for (int to : g[now]) {
							if (used[to]) continue;
							cost[to] = cost[now] + 1;
							used[to] = true;
							q.add(to);
						}
					}

					q.add(b[i]);
					Arrays.fill(used, false);
					used[b[i]] = true;
					cost[b[i]] = 0;

					while (!q.isEmpty()) {
						int now = q.remove();

						for (int to : g[now]) {
							if (used[to]) continue;
							if (cost[now] + 1 < cost[to]) {
								cost[to] = cost[now] + 1;
								used[to] = true;
								q.add(to);
							}
						}
					}

					int tmp = 0;
					for (int j = 0; j < n; j++) {
						if (cost[j] > k/2) tmp++;
					}

					count = Math.min(count, tmp);
				}
			}

			out.println(count);

		}
	}

