		Scanner sc = new Scanner(System.in);
		Printer pr = new Printer(System.out);

		int n = sc.nextInt();
		int k = sc.nextInt();

		List<List<Integer>> edges = new ArrayList<>(n);
		for (int i = 0; i < n; i++) {
			edges.add(new ArrayList<Integer>());
		}

		for (int i = 0; i < n - 1; i++) {
			int a = sc.nextInt() - 1;
			int b = sc.nextInt() - 1;
			edges.get(a).add(b);
			edges.get(b).add(a);
		}

		int ret = Integer.MAX_VALUE;
		Set<Integer> v = new HashSet<>();
		for (int i = 0; i < n; i++) {
			int root = i;
			int[] parent = new int[n];
			int[] used = new int[n];
			Deque<Integer> st = new ArrayDeque<>();
			st.push(root);
			parent[root] = -1;
			used[root] = 0;
			int max = 0;
			Set<Integer> maxv = new HashSet<>();
			while (!st.isEmpty()) {
				int e = st.pop();
				int pe = parent[e];

				for (int ne : edges.get(e)) {
					if (ne == pe) {
						continue;
					}
					st.push(ne);
					parent[ne] = e;
					used[ne] = used[e] + 1;
					if (used[ne] > max) {
						max = used[ne];
						maxv = new HashSet<>();
						maxv.add(ne);
					} else if (used[ne] == max) {
						maxv.add(ne);
					}
				}
			}
			v.addAll(maxv);
		}

		for (int i : v) {
			int root = i;
			int[] parent = new int[n];
			int[] used = new int[n];
			Deque<Integer> st = new ArrayDeque<>();
			st.push(root);
			parent[root] = -1;
			used[root] = 0;

			int cnt = 0;
			while (!st.isEmpty()) {
				int e = st.pop();
				int pe = parent[e];

				for (int ne : edges.get(e)) {
					if (ne == pe) {
						continue;
					}
					st.push(ne);
					parent[ne] = e;
					used[ne] = used[e] + 1;
					if (used[ne] > k) {
						cnt++;
					}
				}
			}

			ret = Math.min(ret, cnt);
		}

		pr.println(ret);

		pr.close();
		sc.close();
	}

