            a[i] = in.nextLong();
        }
        return a;
    }

    private static class Node {
        int num;
        Set<Node> children = new HashSet<>();

        public Node(int num) {
            this.num = num;
        }

        @Override
        public String toString() {
            return "Node:" + num;
        }
    }

    public static void main(String[] args) throws FileNotFoundException {
        InputReader in = new InputReader(System.in);
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));

        int n = in.nextInt();
        int k = in.nextInt();
        Node[] nodes = new Node[n + 1];
        for (int i = 1; i <= n; i++) {
            nodes[i] = new Node(i);
        }

        for (int i = 0; i < n - 1; i++) {
            int u = in.nextInt();
            int v = in.nextInt();

            nodes[u].children.add(nodes[v]);
            nodes[v].children.add(nodes[u]);
        }

        int min = solve(n, k, nodes, 1, 0);
        out.println(min);

        out.close();
    }

    private static int getDiameter(Node node, int n, Node[] nodes) {
        List<Node> longestPath = bfs(node, n, nodes, 0);
        longestPath = bfs(nodes[longestPath.get(longestPath.size() - 1).num], n, nodes, 0);
        return longestPath.size() - 1;
    }

    private static int solve(int n, int k, Node[] nodes, int nodeNum, int parent) {
        List<Node> longestPath = bfs(nodes[nodeNum], n, nodes, parent);
        longestPath = bfs(nodes[longestPath.get(longestPath.size() - 1).num], n, nodes, parent);
        int diameter = longestPath.size() - 1;

        int min = Integer.MAX_VALUE;
        if (diameter <= k) {
            return 0;
        }

        Map<Integer, Integer> subTreeStarts = new HashMap<>();
        Map<Integer, Integer> subSolutions = new HashMap<>();
        boolean[] visited = new boolean[n + 1];
        visited[parent] = true;
        if (diameter % 2 == 1) {
            Node v = longestPath.get((diameter + 1) / 2);
            Node u = longestPath.get((diameter + 1) / 2 - 1);
            subTreeStarts.put(u.num, v.num);
            subTreeStarts.put(v.num, u.num);
        } else {
            int center = longestPath.get((diameter + 1) / 2).num;
            visited[center] = true;
            for (Node child : nodes[center].children) {
                subTreeStarts.put(child.num, center);
            }
        }

        Map<Integer, Map<Integer, Integer>> toCutForLevel = new HashMap<>();
        for (Integer subTreeStart : subTreeStarts.keySet()) {
            visited[subTreeStart] = true;
        }
        for (Integer subTreeStart : subTreeStarts.keySet()) {
            HashMap<Integer, Integer> subToCutForLevel = new HashMap<>();
            int res = dfs(nodes[subTreeStart], visited, subToCutForLevel, 0);
            subToCutForLevel.put(0, res);
            toCutForLevel.put(subTreeStart, subToCutForLevel);
            Integer subTreeSize = toCutForLevel.get(subTreeStart).getOrDefault(0, 0);
            if (subTreeSize <= 1) {
                subSolutions.put(subTreeStart, 0);
            } else {
                subSolutions.put(subTreeStart, solve(n, k, nodes, subTreeStart, subTreeStarts.get(subTreeStart)));
            }
        }

        int d = diameter % 2 == 0 ? diameter : (diameter - 1);
        for (int i = Math.max(0, (d - 2 * k) / 2); 2 * i <= d - k; i++) {
            int sum = 0;
            for (Map<Integer, Integer> subToCut : toCutForLevel.values()) {
                sum += subToCut.getOrDefault(i + k - d / 2, 0);
            }
            for (Integer subTreeStart : toCutForLevel.keySet()) {
                int s1 = sum - toCutForLevel.get(subTreeStart).getOrDefault(i + k - d / 2, 0);
                s1 += Math.max(toCutForLevel.get(subTreeStart).getOrDefault(d / 2 - i, 0),
                        subSolutions.get(subTreeStart));
                min = Math.min(min, s1);
            }
        }

        if (k < (diameter + 1) / 2) {
            for (Integer subTreeStart : toCutForLevel.keySet()) {
                Integer subTreeSize = toCutForLevel.get(subTreeStart).getOrDefault(0, 0);
                if (subTreeSize <= 1) {
                    continue;
                }
                int s1 = n - subTreeSize;
                s1 += subSolutions.get(subTreeSize);
                min = Math.min(min, s1);
            }
        }
        return min;
    }

    private static int dfs(Node node, boolean[] visited, HashMap<Integer, Integer> toCutForLevel, int level) {
        visited[node.num] = true;

        int res = 0;
        for (Node child : node.children) {
            if (!visited[child.num]) {
                res += dfs(child, visited, toCutForLevel, level + 1);
            }
        }
        toCutForLevel.put(level + 1, toCutForLevel.getOrDefault(level + 1, 0) + res);

        return res + 1;
    }

    private static List<Node> bfs(Node node, int n, Node[] nodes, int parent) {
        Queue<Node> q = new LinkedList<>();
        q.add(node);
        boolean[] used = new boolean[n + 1];
        int[] parents = new int[n + 1];
        int[] distances = new int[n + 1];
        used[node.num] = true;
        used[parent] = true;
        parents[node.num] = -1;

        while (!q.isEmpty()) {
            Node v = q.poll();
            for (Node to : v.children) {
                if (!used[to.num]) {
                    used[to.num] = true;
                    q.add(to);
                    distances[to.num] = distances[v.num] + 1;
                    parents[to.num] = v.num;
                }
            }
        }

        int maxNodeInd = -1;
        int maxDist = 0;
        for (int i = 1; i <= n; i++) {
            if (distances[i] > maxDist) {
                maxDist = distances[i];
                maxNodeInd = i;
            }
        }

        List<Node> path = new ArrayList<>();
        for (int v = maxNodeInd; v != -1; v = parents[v]) {
            path.add(nodes[v]);
        }
        Collections.reverse(path);
        return path;
    }


    private static void outputArray(long[] ans, PrintWriter out) {
        StringBuilder str = new StringBuilder();
        for (long an : ans) {
            str.append(an).append(' ');
        }
        out.println(str);
    }

