		for (int i : IntRange.open(N)) graph.add(new ArrayList<>());
		for (int i = 1;i < N;++ i) {
			int A = io.nextInt() - 1, B = io.nextInt() - 1;
			graph.get(A).add(B);
			graph.get(B).add(A);
		}
		int ans = N;
		for (int i = 0;i < N;++ i) {
			for (int j : graph.get(i)) {
				int count = N - 1;
				int[] dist = new int[N];
				BreadthFirstSearch<Integer> bfs = new BreadthFirstSearch<>();
				dist[i] = K + 1;
				dist[j] = 1;
				bfs.hash.add(i);
				bfs.push(j);
				for (int k : bfs) {
					if (dist[k] > K) continue;
					-- count;
					for (int l : graph.get(k)) if (bfs.push(l)) dist[l] = dist[k] + 1;
				}
				ans = Math.min(ans, count);
			}
		}
		io.println(ans);
	}

