	/**
	 * 幅優先探索を自動的に行うライブラリです。
	 * @author 31536000
	 *
	 * @param <T> 幅優先探索の対象となる型
	 */
	public static class BreadthFirstSearch<T> implements Iterable<T>, Iterator<T>{
		CircularArray<Deque<T>> queue;
		HashSet<T> hash;
		int size;

		/**
		 * キューを1個用いるBFSを用意します。
		 */
		public BreadthFirstSearch() {
			this(1);
		}

		/**
		 * キューをn個用いるBFSを用意します。
		 * @param n 使うキューの数
		 */
		public BreadthFirstSearch(int n) {
			queue = new CircularArray<Deque<T>>(n);
			for (int i = 0;i < n;++ i) queue.set(i, new ArrayDeque<T>());
			hash = new HashSet<T>();
			size = 0;
		}

		/**
		 * キューを1個用いて、最初に調べる場所がtのBFSを作成します。
		 * @param t 最初に調べる値
		 */
		public BreadthFirstSearch(T t) {
			this(1, t);
		}

		/**
		 * キューをn個用いて、最初に調べる場所がtのBFSを作成します。
		 * @param n 使うキューの数
		 * @param t 最初に調べる値
		 */
		public BreadthFirstSearch(int n, T t) {
			this(n);
			push(t);
		}

		/**
		 * 第n番目のキューに新しくtを調べる対象に追加します。
		 * @param n 使うキューの場所(0はstackとして処理される)
		 * @param t 調べる値
		 * @return 既にtを調べたことがあるならfalse、まだ調べてないならtrue
		 */
		public boolean push(int n, T t) {
			if (n < 0 || n > queue.size()) throw new IndexOutOfBoundsException();
			if (n == 0) { // stackとして使う
				Deque<T> que = queue.front();
				if (!hash.add(t)) return false;
				que.addFirst(t);
			} else { // queueとして使う
				Deque<T> que = queue.get(n - 1);
				if (!hash.add(t)) return false;
				que.addLast(t);
			}
			++ size;
			return true;
		}

		/**
		 * 1番目のキューに新しくtを調べる対象に追加します。
		 * @param t 調べる値
		 * @return 既にtを調べたことがあるならfalse、まだ調べてないならtrue
		 */
		public boolean push(T t) {
			if (!hash.add(t)) return false;
			queue.front().addLast(t);
			++ size;
			return true;
		}

		/**
		 * 既にその要素を調べているか返します。
		 * @param t 調べる値
		 * @return 既に調べていたらtrue
		 */
		public boolean contains(T t) {
			return hash.contains(t);
		}

		/**
		 * BFSを初期化します。
		 */
		public void clear() {
			for (Deque<T> i : queue) i.clear();
			hash.clear();
			size = 0;
		}

		@Override
		public Iterator<T> iterator() {
			return this;
		}

		@Override
		public boolean hasNext() {
			return size > 0;
		}

		@Override
		public T next() {
			if (size <= 0) throw new NoSuchElementException();
			while (queue.front().isEmpty()) queue.rotateNext();
			-- size;
			return queue.front().pollFirst();
		}
	}

	/**
	 * 端がもう片側の端と繋がり、循環する固定長配列を提供します。
	 * @author 31536000
	 *
	 * @param <T> 配列の型
	 */
	public static class CircularArray<T> extends Array<T>{

		private static final long serialVersionUID = 8755553665486205607L;
		private int first = 0;
		/**
		 * 長さsizeで、初期の要素が全てnullの配列を作成します。
		 * @param size 要素数
		 */
		public CircularArray(int size) {
			super(size);
		}

		/**
		 * arrayを固定長配列として扱います。
		 * @param array 元となる配列
		 */
		public CircularArray(T[] array) {
			super(array);
		}

		/**
		 * index番目の要素を取得します。
		 * @param index 取得する要素のインデックス
		 * @return index番目の要素
		 */
		private int getIndex(int index) {
			index -= first;
			if (index >= size()) index %= size();
			else if (index < 0) index = size() + index % size();
			return index;
		}

		/**
		 * 先頭の要素を上書きします。<br>
		 * この関数はset(0, value)と同一です。
		 * @param value 上書きする要素
		 */
		public void setFront(T value) {
			super.set(first, value);
		}

		/**
		 * index番目の要素を上書きします。<br>
		 * この時、indexは要素数を法とする自然数上に丸められます。
		 * @param index 上書きする場所
		 * @param value 上書きする値
		 */
		@Override
		public T set(int index, T value) {
			return super.set(getIndex(index), value);
		}

		/**
		 * 末尾の要素を上書きします。<br>
		 * この関数はset(-1, value)と同一です。
		 * @param value 上書きする要素
		 */
		public void setBack(T value) {
			super.set(first == 0 ? size() - 1 : first - 1, value);
		}

		/**
		 * index番目の要素を取得します。<br>
		 * この時、indexは要素数を法とする自然数上に丸められます。
		 * @param index 取得する場所
		 * @return index番目の要素
		 */
		@Override
		public T get(int index) {
			return super.get(getIndex(index));
		}

		/**
		 * 先頭の要素を取得します。<br>
		 * この関数はget(0)と同一です。
		 * @return 先頭の要素
		 */
		@Override
		public T front() {
			return super.get(first);
		}

		/**
		 * 末尾の要素を取得します。<br>
		 * この関数はget(-1)と同一です。
		 * @return 末尾の要素
		 */
		@Override
		public T back() {
			return super.get(first == 0 ? size() - 1 : first - 1);
		}

		/**
		 * 先頭の位置をずらします。<br>
		 * 例えばrotateが1の時、get(1)で取り出せていた要素は次からget(0)で取り出せるようになります。
		 * @param rotate ずらす量
		 */
		public void rotate(int rotate) {
			first = getIndex(rotate);
		}

		/**
		 * 先頭の位置を一つ後にずらします。<br>
		 * この関数はrotate(1)と同一です。
		 */
		public void rotateNext() {
			if (++first >= size()) first = 0;
		}


		/**
		 * 先頭の位置を一つ前にずらします。<br>
		 * この関数はrotate(-1)と同一です。
		 */
		public void rotatePrevious() {
			if (--first < 0) first = size() - 1;
		}

		private class Iter implements Iterator<T> {
			private int index;
			private int count;

			Iter() {
				index = first;
				count = 0;
			}

			@Override
			public boolean hasNext() {
				return count < size();
			}

			@Override
			public T next() {
				T ret = get(index);
				if (++index >= size()) index = 0;
				++ count;
				return ret;
			}

			@Override
			public void remove() {
				throw new UnsupportedOperationException();
			}
		}

		@Override
		public Iterator<T> iterator() {
			return new Iter();
		}
	}

	public class Addition implements Abelian<Integer>{

		@Override
		public Integer apply(Integer left, Integer right) {
			return left + right;
		}

		@Override
		public Integer identity() {
			return 0;
		}

		@Override
		public Integer inverse(Integer element) {
			return -element;
		}

		@Override
		public Integer hyper(Integer element, int repeat) {
			return element * repeat;
		}

	}

	/**
	 * 累積和を計算します。
	 * @author 31536000
	 *
	 */
	public static class CumulativeSum<T> {
		private final Object[] leftSum, rightSum;
		private final Monoid<T> operate;

		@SuppressWarnings("unchecked")
		private CumulativeSum(T[] dat, Monoid<T> operate) {
			this.operate = operate;
			leftSum = new Object[dat.length + 1];
			rightSum = new Object[dat.length + 1];
			leftSum[0] = rightSum[dat.length] = operate.identity();
			for (int i = 0;i < dat.length;++ i) {
				leftSum[i + 1] = operate.apply((T)leftSum[i], dat[i]);
				rightSum[dat.length - i - 1] = operate.apply(dat[dat.length - i - 1], (T)rightSum[dat.length - i]);
			}
		}

		/**
		 * [0, index)の値の合計を返します。
		 * @param index 累積和の右辺
		 * @return [0, index)の値の合計
		 */
		public T getSum(int index) {
			@SuppressWarnings("unchecked")
			T ret = (T)leftSum[index];
			return ret;
		}

		/**
		 * [index, size)の値の合計を返します。
		 * @param index 累積和の左辺
		 * @return [index, size)の値の合計
		 */
		public T getLastSum(int index) {
			@SuppressWarnings("unchecked")
			T ret = (T)rightSum[index];
			return ret;
		}

		/**
		 * [0, index) + (index, size)の値の合計を返します。
		 * @param index 除外したい値
		 * @return indexを除く全区間の値の合計
		 */
		public T getAvoidSum(int index) {
			return getAvoidSum(index, index + 1);
		}

		/**
		 * [0, left) + [right, size)の値の合計を返します。
		 * @param left 除外する区間の左閉区間
		 * @param right 除外する区間の右開区間
		 * @return [left, right)を除く全区間の値の合計
		 */
		public T getAvoidSum(int left, int right) {
			return operate.apply(getSum(left), getLastSum(right));
		}

		/**
		 * rangeの区間を除いた値の合計を返します。
		 * @param range 除外する区間
		 * @return rangeの区間を除く全区間の値の合計
		 */
		public T getAvoidSum(IntRange range) {
			return getAvoidSum(range.getClosedLower(), range.getOpenUpper());
		}

		/**
		 * 区間[left, right)の値の合計を返します。
		 * @param left 左閉区間
		 * @param right 右開区間
		 * @param inverse 逆元
		 * @return 区間[left, right)の値の合計
		 */
		public T getSum(int left, int right, Inverse<T> inverse) {
			try {
				return operate.apply(inverse.inverse(getSum(left)), getSum(right));
			} catch (NullPointerException e) {
				if (left == 0) return getSum(right);
				if (right == rightSum.length) return getLastSum(left);
				throw e;
			}
		}

		/**
		 * rangeの区間の値の合計を返します。
		 * @param range 求める区間
		 * @param inverse 逆元
		 * @return rangeの区間の値の合計
		 */
		public T getSum(IntRange range, Inverse<T> inverse) {
			return getSum(range.getClosedLower(), range.getOpenUpper(), inverse);
		}

		/**
		 * 累積和を構築します。
		 * @param dat 構築する配列
		 * @param operate 結合法則
		 * @return 累積和
		 */
		public static <E> CumulativeSum<E> create(E[] dat, Monoid<E> operate) {
			return new CumulativeSum<>(dat, operate);
		}

		/**
		 * 累積和を構築します。
		 * @param dat 結合法則を満たす、構築する配列
		 * @return 累積和
		 */
		public static <E extends Monoid<E>> CumulativeSum<E> create(E[] dat) {
			return new CumulativeSum<>(dat, dat[0]);
		}
	}

	/**
	 * 高速な入出力を提供します。
	 * @author 31536000
	 *
	 */
	public static class FastIO {
		private InputStream in;
		private final byte[] buffer = new byte[1024];
		private int read = 0;
		private int length = 0;
		private PrintWriter out;
		private PrintWriter err;
		private boolean autoFlush = false;

		public FastIO() {
			this(System.in, System.out, System.err);
		}

		public FastIO(InputStream in, PrintStream out, PrintStream err) {
			this.in = in;
			this.out = new PrintWriter(out, false);
			this.err = new PrintWriter(err, false);
		}

		public final void setInputStream(InputStream in) {
			this.in = in;
		}

		public final void setInputStream(File in) {
			try {
				this.in = new FileInputStream(in);
			} catch (FileNotFoundException e) {
				e.printStackTrace();
			}
		}

		public final void setOutputStream(PrintStream out) {
			this.out = new PrintWriter(out, false);
		}

		public final void setOutputStream(File out) {
			try {
				this.out = new PrintWriter(new FileOutputStream(out), false);
			} catch (FileNotFoundException e) {
				e.printStackTrace();
			}
		}

		public final void setErrorStream(PrintStream err) {
			this.err = new PrintWriter(err, false);
		}

		public final void setErrorStream(File err) {
			try {
				this.err = new PrintWriter(new FileOutputStream(err), false);
			} catch (FileNotFoundException e) {
				e.printStackTrace();
			}
		}

		public final void setAutoFlush(boolean flush) {
			autoFlush = flush;
		}

		private boolean hasNextByte() {
			if (read < length) return true;
			read = 0;
			try {
				length = in.read(buffer);
			} catch (IOException e) {
				e.printStackTrace();
			}
			return length > 0;
		}

		private int readByte() {
			return hasNextByte() ? buffer[read++] : -1;
		}

		private static boolean isPrintableChar(int c) {
			return 33 <= c && c <= 126;
		}

		private static boolean isNumber(int c) {
			return '0' <= c && c <= '9';
		}

		public final boolean hasNext() {
			while (hasNextByte() && !isPrintableChar(buffer[read])) read++;
			return hasNextByte();
		}

		public final char nextChar() {
			if (!hasNextByte())  throw new NoSuchElementException();
			return (char)readByte();
		}

		public final char[][] nextChar(int height) {
			char[][] ret = new char[height][];
			for (int i = 0;i < ret.length;++ i) ret[i] = next().toCharArray();
			return ret;
		}

		public final String next() {
			if (!hasNext()) throw new NoSuchElementException();
			StringBuilder sb = new StringBuilder();
			int b;
			while (isPrintableChar(b = readByte())) sb.appendCodePoint(b);
			return sb.toString();
		}

		public final String nextLine() {
			StringBuilder sb = new StringBuilder();
			int b;
			while(!isPrintableChar(b = readByte()));
			do sb.appendCodePoint(b); while(isPrintableChar(b = readByte()) || b == ' ');
			return sb.toString();
		}

		public final long nextLong() {
			if (!hasNext()) throw new NoSuchElementException();
			long n = 0;
			boolean minus = false;
			int b = readByte();
			if (b == '-') {
				minus = true;
				b = readByte();
			}
			if (!isNumber(b)) throw new NumberFormatException();
			while (true) {
				if (isNumber(b)) {
					n *= 10;
					n += b - '0';
				} else if (b == -1 || !isPrintableChar(b)) return minus ? -n : n;
				else throw new NumberFormatException();
				b = readByte();
			}
		}

		public final int nextInt() {
			long nl = nextLong();
			if (nl < Integer.MIN_VALUE || nl > Integer.MAX_VALUE) throw new NumberFormatException();
			return (int) nl;
		}

		public final double nextDouble() {
			return Double.parseDouble(next());
		}

		public final int[] nextInt(int width) {
			int[] ret = new int[width];
			for (int i = 0;i < width;++ i) ret[i] = nextInt();
			return ret;
		}

		public final int[] nextInts() {
			return nextInts(" ");
		}

		public final int[] nextInts(String parse) {
			String[] get = nextLine().split(parse);
			int[] ret = new int[get.length];
			for (int i = 0;i < ret.length;++ i) ret[i] = Integer.valueOf(get[i]);
			return ret;
		}

		public final long[] nextLong(int width) {
			long[] ret = new long[width];
			for (int i = 0;i < width;++ i) ret[i] = nextLong();
			return ret;
		}

		public final long[] nextLongs() {
			return nextLongs(" ");
		}

		public final long[] nextLongs(String parse) {
			String[] get = nextLine().split(parse);
			long[] ret = new long[get.length];
			for (int i = 0;i < ret.length;++ i) ret[i] = Long.valueOf(get[i]);
			return ret;
		}

		public final int[][] nextInt(int width, int height) {
			int[][] ret = new int[height][width];
			for (int i = 0, j;i < height;++ i) for (j = 0;j < width;++ j) ret[i][j] = nextInt();
			return ret;
		}

		public final long[][] nextLong(int width, int height) {
			long[][] ret = new long[height][width];
			for (int i = 0, j;i < height;++ i) for (j = 0;j < width;++ j) ret[j][i] = nextLong();
			return ret;
		}

		public final boolean[] nextBoolean(char T) {
			char[] s = next().toCharArray();
			boolean[] ret = new boolean[s.length];
			for (int i = 0;i < ret.length;++ i) ret[i] = s[i] == T;
			return ret;
		}

		public final boolean[][] nextBoolean(char T, int height) {
			boolean[][] ret = new boolean[height][];
			for (int i = 0;i < ret.length;++ i) {
				char[] s = next().toCharArray();
				ret[i] = new boolean[s.length];
				for (int j = 0;j < ret[i].length;++ j) ret[i][j] = s[j] == T;
			}
			return ret;
		}

		public final Point nextPoint() {
			return new Point(nextInt(), nextInt());
		}

		public final Point[] nextPoint(int width) {
			Point[] ret = new Point[width];
			for (int i = 0;i < width;++ i) ret[i] = nextPoint();
			return ret;
		}

		@Override
		protected void finalize() throws Throwable {
			try {
				super.finalize();
			} finally {
				in.close();
				out.close();
				err.close();
			}
		}

		public final boolean print(boolean b) {
			out.print(b);
			if (autoFlush) flush();
			return b;
		}

		public final Object print(boolean b, Object t, Object f) {
			return b ? print(t) : print(f);
		}

		public final char print(char c) {
			out.print(c);
			if (autoFlush) flush();
			return c;
		}

		public final char[] print(char[] s) {
			out.print(s);
			return s;
		}

		public final double print(double d) {
			out.print(d);
			if (autoFlush) flush();
			return d;
		}

		public final double print(double d, int length) {
			if (d < 0) {
				out.print('-');
				d = -d;
			}
			d += Math.pow(10, -length) / 2;
			out.print((long)d);
			out.print('.');
			d -= (long)d;
			for (int i = 0;i < length;++ i) {
				d *= 10;
				out.print((int)d);
				d -= (int)d;
			}
			if (autoFlush) flush();
			return d;
		}

		public final float print(float f) {
			out.print(f);
			if (autoFlush) flush();
			return f;
		}

		public final int print(int i) {
			out.print(i);
			if (autoFlush) flush();
			return i;
		}

		public final long print(long l) {
			out.print(l);
			if (autoFlush) flush();
			return l;
		}

		public final Object print(Object obj) {
			if (obj != null && obj.getClass().isArray()) {
				if (obj instanceof boolean[][]) print(obj, "\n", " ");
				else if (obj instanceof byte[][]) print(obj, "\n", " ");
				else if (obj instanceof short[][]) print(obj, "\n", " ");
				else if (obj instanceof int[][]) print(obj, "\n", " ");
				else if (obj instanceof long[][]) print(obj, "\n", " ");
				else if (obj instanceof float[][]) print(obj, "\n", " ");
				else if (obj instanceof double[][]) print(obj, "\n", " ");
				else if (obj instanceof char[][]) print(obj, "\n", " ");
				else if (obj instanceof Object[][]) print(obj, "\n", " ");
				else print(obj, " ");
			} else {
				out.print(obj);
				if (autoFlush) flush();
			}
