		piar v = max(n, u.l, to);
		{
			int tmp = u.l;
			u.l = v.l;
			v.l = tmp;
		}
		int D = u.d[v.l], d = D - k;
		if (d <= 0) {
			out.println(0);
		} else {
			int res = Integer.MAX_VALUE;
			for (int i = 0; i <= d; ++i) {
				boolean a[] = new boolean[n];
				for (int j = 0; j < n; ++j) {
					a[j] |= u.d[j] > D - i;
					a[j] |= v.d[j] > D - (d - i);
				}
				int tmp = 0;
				for (int j = 0; j < n; ++j)
					if (a[j]) ++tmp;
				if (tmp < res) res = tmp;
			}
			out.println(res);
