			for (Integer g : to[s]) {
				if (d[g] == -1) {
					d[g] = d[s] + 1;
					q[qs++] = g;
					if (m < d[g]) {
						m = d[g];
						l = g;
					}
				}
			}
		}
		return new piar(l, d);
