        int k = sc.nextInt();

        List<List<Integer>> str = new ArrayList<>();

        for(int i=0;i<n;i++){
            str.add(new ArrayList<>());
        }

        for(int i=0;i<n-1;i++){
            int x = sc.nextInt();
            int y = sc.nextInt();

            str.get(x-1).add(y-1);
            str.get(y-1).add(x-1);
        }

        int ret = Integer.MAX_VALUE;

        if(k%2 == 0){
            for(int i=0;i<n;i++){
                Queue<Integer> q = new LinkedList<>();
                int[] dist = new int[n];
                Arrays.fill(dist,-1);
                dist[i] = 0;
                q.add(i);
                int cnt =0;

                while (!q.isEmpty()){
                    int v = q.poll();
                    if(dist[v] > k/2) cnt++;
                    for (int j:str.get(v)){
                        if(dist[j] == -1){
                            dist[j] = dist[v]+1;
                            q.add(j);
                        }
                    }
                }
                ret = Math.min(cnt,ret);
            }
        }else{
            for(int i=0;i<n;i++){
                for(int j:str.get(i)){
                    Queue<Integer> q = new LinkedList<>();
                    int[] dist = new int[n];
                    Arrays.fill(dist,-1);
                    dist[i] = 0;dist[j] = 0;
                    q.add(i);q.add(j);
                    int cnt =0;

                    while (!q.isEmpty()){
                        int v = q.poll();
                        if(dist[v] > k/2) cnt++;
                        for (int g:str.get(v)){
                            if(dist[g] == -1){
                                dist[g] = dist[v]+1;
                                q.add(g);
                            }
                        }
                    }
                    ret = Math.min(cnt,ret);
                }
            }
        }
        out.println(ret);
        out.close();
    }

