		}
	}
}

import java.io.*;
import java.util.*;

class Solver {
  final int n, k;
  final int[][] abs;
  List<List<Integer>> graph;

  Solver(int n, int k, int[][] abs) {
    this.n = n;
    this.k = k;
    this.abs = abs;
  }

  private int reachable(int[] initialNodes) {
    int count = 0;
    int[] costs = new int[n + 1];
    Arrays.fill(costs, -1);

    Deque<Integer> queue = new ArrayDeque<>();
    for (int initialNode : initialNodes) {
      costs[initialNode] = 0;
      count++;
      if (0 < k / 2) {
        queue.addLast(initialNode);
      }
    }
    while (!queue.isEmpty()) {
      int node = queue.pollFirst();
      for (int next : graph.get(node)) {
        if (costs[next] >= 0) {
          continue;
        }
        costs[next] = costs[node] + 1;
        count++;
        if (costs[next] < k / 2) {
          queue.addLast(next);
        }
      }
    }
    return n - count;
  }

  private int solveEven() {
    int answer = Integer.MAX_VALUE;
    for (int i = 1; i <= n; i++) {
      answer = Math.min(answer, reachable(new int[]{i}));
    }
    return answer;
  }

  private int solveOdd() {
    int answer = Integer.MAX_VALUE;
    for (int[] ab : abs) {
      answer = Math.min(answer, reachable(ab));
    }
    return answer;
  }

  public int solve() {
    graph = new ArrayList<>();
    for (int i = 0; i <= n; i++) {
      graph.add(new ArrayList<>());
    }
    for (int[] ab : abs) {
      int a = ab[0];
      int b = ab[1];
      graph.get(a).add(b);
      graph.get(b).add(a);
    }
    if (k % 2 == 0) {
      return solveEven();
    } else {
      return solveOdd();
    }
  }
}

public class Main {
  private static void execute(ContestReader reader, PrintWriter out) {
    int n = reader.nextInt();
    int k = reader.nextInt();
    int[][] abs = reader.nextInt(n - 1, 2);
    out.println(new Solver(n, k, abs).solve());
  }

  public static void main(String[] args) {
    ContestReader reader = new ContestReader(System.in);
    PrintWriter out = new PrintWriter(System.out);
    execute(reader, out);
    out.flush();
  }
}

