public class ShortenDiameter {
	static class P {
		int front, cost;
		public P(int f, int c){
			front = f;
			cost = c;
		}
	}
	public static void main(String[] args) {
		InputReader r = new InputReader(System.in);
		int n = r.nextInt();
		int k = r.nextInt();
		ArrayList<Integer> adj[] = new ArrayList[n];
		for (int i = 0; i < adj.length; i++) {
			adj[i] = new ArrayList<Integer>();
		}
		for (int i = 0; i < n - 1; i++) {
			int from = r.nextInt() - 1;
			int to = r.nextInt() - 1;
			adj[from].add(to);
			adj[to].add(from);
		}
		for(int i=0;i<n;i+=10){
			Collections.shuffle(adj[i]);
		}
		int res = 1 << 28;
		boolean[] vis = new boolean[n];
		for (int i = 0; i < n; i++) {
			LinkedList<P> q = new LinkedList<P>();
			q.add(new P(i,0));
			Arrays.fill(vis, false);
			vis[i] = true;
			HashSet<Integer> set = new HashSet<Integer>();
			int last = -1;
			while (!q.isEmpty()) {
				P f = q.removeFirst();
				int front = f.front;
				set.add(front);
				last = front;
				int cost = f.cost;
				if (cost == k) {
					continue;
				}
				for (int x : adj[front]) {
					if (!vis[x]) {
						q.add(new P(x, cost+1));
						vis[x] = true;
					}
				}
			}
			Arrays.fill(vis, false);
			vis[last] = true;
			q.add(new P(last,0));
			int diameter = -1;
			int reached = 0;
			HashSet<Integer> set2 = new HashSet<Integer>();
			while (!q.isEmpty()) {
				P f = q.remove();
				int front = f.front;
				int cost = f.cost;
				reached++;
				diameter = cost;
				if (diameter <= k) {
					last = front;
					set2.add(front);
					res = Math.min(res, n - reached);
				}
				for (int x : adj[front]) {
					if (!vis[x] && set.contains(x)) {
						q.add(new P(x, cost+1));
						vis[x] = true;
					}
				}
			}
		}
		System.out.println(res);
	}

