    static ArrayList<Integer>[] edge;
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        k = sc.nextInt();
        edge = new ArrayList[n];
        int[][] ab = new int[n-1][2];
        for(int i=0; i<n; i++) edge[i] = new ArrayList<Integer>();
        for(int i=0; i<n-1; i++){
            int a = sc.nextInt() - 1;
            int b = sc.nextInt() - 1;
            edge[a].add(b);
            edge[b].add(a);
            ab[i][0] = a;
            ab[i][1] = b;
        }
        sc.close();

        if(k == 1){
            System.out.println(n-2);
            return;
        }

        int ans = Integer.MAX_VALUE;
        if(k%2 == 0){
            for(int i=0; i<n; i++){
                ans = Math.min(ans, countDelNum(i, i));
            }
        }else{
            for(int i=0; i<n-1; i++){
                ans = Math.min(ans, countDelNum(ab[i][0], ab[i][1])
                                +countDelNum(ab[i][1], ab[i][0])-n);
            }
        }
        // for(int i=0; i<n; i++){
        //     int tmp = countDelNum(i);
        //     if(tmp < ans){
        //         ans = tmp;
        //     }
        // }
        System.out.println(ans);
    }

    public static int countDelNum(int root, int root2){
        int count = n;
        ArrayDeque<Integer[]> que = new ArrayDeque<Integer[]>();
        boolean[] use = new boolean[n];
        que.add(new Integer[]{root, 0});
        use[root] = true;
        use[root2] = true;
        while(que.size()>0){
            Integer[] cur = que.poll();
            if(cur[1] > k/2) break;
            for(int i=0; i<edge[cur[0]].size(); i++){
                Integer next = edge[cur[0]].get(i);
                if(!use[next]){
                    que.add(new Integer[]{next, cur[1]+1});
                    use[next] = true;
                }
            }
            count--;
        }
        return count;
    }
}

import java.util.Arrays;
import java.util.LinkedList;
import java.util.List;
import java.util.Scanner;

public class Main {
	List<Integer>[] e;

	void dfs(int k, boolean[] flag, int[] depth, int dep, boolean[] delete) {
		if (flag[k] || delete[k]) {
			return;
		}
		flag[k] = true;
		depth[k] = dep;
		for (Integer to : e[k]) {
			dfs(to, flag, depth, dep + 1, delete);
		}
	}

	void run() {
		Scanner sc = new Scanner(System.in);

		int n = sc.nextInt();
		int k = sc.nextInt();
		e = new LinkedList[n];
		for (int i = 0; i < n; i++) {
			e[i] = new LinkedList<Integer>();
		}
		for (int i = 0; i < n - 1; i++) {
			int a = sc.nextInt() - 1;
			int b = sc.nextInt() - 1;
			e[a].add(b);
			e[b].add(a);
		}

		boolean[] delete = new boolean[n];
		boolean loop = true;

		while (loop) {
			loop = false;
			int[] depth = new int[n];
			boolean[] flag = new boolean[n];
			int root = 0;
			for (int i = 0; i < n; i++) {
				if (!delete[i]) {
					root = i;
					break;
				}
			}
			dfs(root, flag, depth, 0, delete);
			for (int i = 0; i < n; i++) {
				if (!delete[k] && depth[root] < depth[i]) {
					root = i;
				}
			}
			Arrays.fill(flag, false);
			Arrays.fill(depth, 0);
			dfs(root, flag, depth, 0, delete);
			for (int i = 0; i < n; i++) {
				if (k < depth[i]) {
					delete[i] = true;
					loop = true;
				}
			}
		}
		int sum = 0;
		for (int i = 0; i < n; i++) {
			if (delete[i]) {
				sum++;
			}
		}
		System.out.println(sum);
	}

	public static void main(String[] args) {
		new Main().run();
	}
}

