public class Main {
    public static void main(String[] args) {
        InputReader in = new InputReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        int n = in.nextInt();
        int k = in.nextInt();

        graph = buildGraph(in, n, n-1);

        int max = 0;
        if (k % 2 == 0) {
            for (int i = 0; i < n ; i++) {
                max = Math.max(max, dfs(i, -1, k/2));
            }
        } else {
            for (int f = 0; f < n ; f++) {
                for (int t : graph[f]) {
                    max = Math.max(max, dfs(f, t, (k-1)/2)+dfs(t, f, (k-1)/2));
                }
            }
        }
        out.println(n - max);
        out.flush();
    }

    static int[][] graph;

    static int dfs(int now, int par, int d) {
        int sum = 1;
        if (d >= 1) {
            for (int to : graph[now]) {
                if (to == par) {
                    continue;
                }
                sum += dfs(to, now, d-1);
            }
        }
        return sum;
    }

    static int[][] buildGraph(InputReader in, int n, int m) {
        int[][] edges = new int[m][];
        int[][] graph = new int[n][];
        int[] deg = new int[n];
        for (int i = 0 ; i < m ; i++) {
            int a = in.nextInt()-1;
            int b = in.nextInt()-1;
            deg[a]++;
            deg[b]++;
            edges[i] = new int[]{a, b};
        }
        for (int i = 0 ; i < n ; i++) {
            graph[i] = new int[deg[i]];
        }
        for (int i = 0 ; i < m ; i++) {
            int a = edges[i][0];
            int b = edges[i][1];
            graph[a][--deg[a]] = b;
            graph[b][--deg[b]] = a;
        }
        return graph;
    }

    static class InputReader {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        private int next() {
            if (numChars == -1)
                throw new InputMismatchException();
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0)
                    return -1;
            }
            return buf[curChar++];
        }

        public char nextChar() {
            int c = next();
            while (isSpaceChar(c))
                c = next();
            if ('a' <= c && c <= 'z') {
                return (char) c;
            }
            if ('A' <= c && c <= 'Z') {
                return (char) c;
            }
            throw new InputMismatchException();
        }

        public String nextToken() {
            int c = next();
            while (isSpaceChar(c))
                c = next();
            StringBuilder res = new StringBuilder();
            do {
                res.append((char) c);
                c = next();
            } while (!isSpaceChar(c));
            return res.toString();
        }

        public int nextInt() {
            int c = next();
            while (isSpaceChar(c))
                c = next();
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = next();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9')
                    throw new InputMismatchException();
                res *= 10;
                res += c-'0';
                c = next();
            } while (!isSpaceChar(c));
            return res*sgn;
        }

        public long nextLong() {
            int c = next();
            while (isSpaceChar(c))
                c = next();
            long sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = next();
            }
            long res = 0;
            do {
                if (c < '0' || c > '9')
                    throw new InputMismatchException();
                res *= 10;
                res += c-'0';
                c = next();
            } while (!isSpaceChar(c));
            return res*sgn;
        }

        public boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public interface SpaceCharFilter {
            public boolean isSpaceChar(int ch);
        }
    }

    static void debug(Object... o) {
        System.err.println(Arrays.deepToString(o));
    }
}

import java.util.*;

class Main{
    static ArrayList<Integer>[] map;
    public static void main(String[] args){
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int x = sc.nextInt();
        map = new ArrayList[n+1];
        for(int i=0;i<=n;i++) map[i]=new ArrayList<>();
        for(int i=0;i<n-1;i++){
            int a = sc.nextInt();
            int b = sc.nextInt();
            map[a].add(b);
            map[b].add(a);
        }
        long ans = 0;
        for(int i=1;i<=n;i++) ans=Math.max(ans,bfs(i,x));
        System.out.println(n-ans);
    }
    static int bfs(int root, int x){
        ArrayList<Integer> cur = new ArrayList<>(), next = new ArrayList<>();
        HashSet<Integer> vis = new HashSet<>();
        cur.add(root);
        for(int d=0;d<=x/2;d++){
            for(int i=0;i<cur.size();i++){
                int now = cur.get(i);
                vis.add(now);
                for(int w:map[now]){
                    if(!vis.contains(w)) next.add(w);
                }
            }
            cur=next;
            next = new ArrayList<>();
        }
        int ans = vis.size();
        if(x%2==1&&next.size()>0) ans++;
        return ans;
    }
}

