public class Main{

    static int n,k;
    static List<Integer>[] edge;

    public static void main(String[] args){
        Scanner sc = new Scanner(System.in);

        n = Integer.parseInt(sc.next());
        k = Integer.parseInt(sc.next());

        edge = new List[n];
        for(int i=0; i<n; i++){
            edge[i] = new ArrayList<>();
        }

        for(int i=0; i<n-1; i++){
            int a = Integer.parseInt(sc.next());
            int b = Integer.parseInt(sc.next());
            edge[a-1].add(b-1);
            edge[b-1].add(a-1);
        }

        int[] distx = bfs(0);

        int max = -1;
        int idx1 = -1;
        for(int i=0; i<n; i++){
            if(max < distx[i]){
                max = distx[i];
                idx1 = i;
            }
        }

        int[] disty = bfs(idx1);

        int idx2 = -1;
        for(int i=0; i<n; i++){
            if(max < disty[i]){
                max = disty[i];
                idx2 = i;
            }
        }

        distx = bfs(idx2);

        //System.out.println("["+ idx1 + " " + idx2 + "]" + "max:" + max);

        PriorityQueue<Vertex> ky = new PriorityQueue<>();

        boolean[] mk = new boolean[n];
        Arrays.fill(mk, true);
        for(int i=0; i<n; i++){
            //System.out.println(distx[i] + " " + disty[i] + " = " + (distx[i]+disty[i]));
            if(distx[i]+disty[i] == max){
                mk[i] = false;
                ky.add(new Vertex(i, disty[i]));
            }
        }

        int[] ha = new int[ky.size()];
        int i = 0;
        while(ky.size()!=0){
            Vertex v = ky.poll();
            int s = v.ver;
            ha[i++] = dfs(s, s, mk);
        }

        int l = 0;
        int r = ha.length-1;
        int ans = 0;
        while((r-l-1) > k){
            if(ha[l] > ha[r]){
                r--;
                ans += ha[r];
            }else{
                l++;
                ans += ha[l];
            }
        }

        System.out.println(ans);

    }

    public static int dfs(int from, int to, boolean[] mk){
        int cnt = 1;
        for(int i=0; i<edge[to].size(); i++){
            int next = edge[to].get(i);
            if(next != from && mk[next]){
                cnt += dfs(to, next, mk);
            }
        }
        return cnt;
    }

    public static int[] bfs(int from){
        int[] dist = new int[n];
        Arrays.fill(dist, (int)1e9);
        dist[from] = 0;
        ArrayDeque<Integer> q = new ArrayDeque<>();
        q.add(from);
        int x = -1;//last
        while(q.size()!=0){
            int now = q.poll();
            for(int i=0; i<edge[now].size(); i++){
                int v = edge[now].get(i);
                if(dist[v] > dist[now]+1){
                    dist[v] = dist[now]+1;
                    q.add(v);
                    x = v;
                }
            }
        }
        return dist;
    }
}


class Vertex implements Comparable<Vertex>{
    public int ver = 0;
    public int cost = 0;

    public Vertex(int ver, int cost) {
        this.ver = ver;
        this.cost = cost;
    }

    @Override
    public int compareTo(Vertex o) {
        return this.cost - o.cost;
    }
}

import java.util.*;
import java.io.*;
import java.awt.geom.*;
import java.math.*;

public class Main {

	static final Scanner in = new Scanner(System.in);
	static final PrintWriter out = new PrintWriter(System.out,false);
	static boolean debug = false;

	static int[][] undirectedGraph(int n, int[] v1, int[] v2) {
		int[] cnt = new int[n];
		for (int i : v1) cnt[i]++;
		for (int i : v2) cnt[i]++;

		int[][] g = new int[n][];
		for (int i=0; i<n; i++) g[i] = new int[cnt[i]];
		for (int i=0; i<v1.length; i++) {
			int s = v1[i];
			int t = v2[i];
			g[s][--cnt[s]] = t;
			g[t][--cnt[t]] = s;
		}

		return g;
	}

	static int p = 0, q = 0;
	static int[] cnt;
	static boolean[] removed;

	static int doubleSweep(int[][] g, int n) {
        int[] d = new int[n];

        doubleSweepBfs(g,d,0);
        int max = 0;
        int t = 0;
        for (int i=0; i<n; i++) {
            if (d[i] == Integer.MAX_VALUE/2 || removed[i]) continue;
            if (max < d[i]) {
                max = d[i];
                t = i;
            }
        }

        doubleSweepBfs(g,d,t);
        p = t;
        max = 0;
        for (int i=0; i<n; i++) {
            if (d[i] == Integer.MAX_VALUE/2 || removed[i]) continue;
            if (max < d[i]) {
            	max = d[i];
            	q = i;
            }
        }

        return max;
    }

    static void doubleSweepBfs(int[][] g,int[] d, int s) {
        Arrays.fill(d,Integer.MAX_VALUE/2);
        ArrayDeque<Integer> que = new ArrayDeque<Integer>();
        que.add(s);
        d[s] = 0;
        while (!que.isEmpty()) {
            int cur = que.pollFirst();
            for (int to : g[cur]) {
            	if (removed[to]) continue;
                if (d[to] == Integer.MAX_VALUE/2) {
                    d[to] = d[cur] + 1;
                    que.add(to);
                }
            }
        }
    }


    static int rec(int[][] g, int cur, int prev) {
    	int res = 0;
    	for (int to : g[cur]) {
    		if (to == prev || removed[to]) continue;
    		res += rec(g, to, cur);
    	}
    	return cnt[cur] = Math.min(cnt[cur], res + 1);
    }


	static void solve() {
		int n = in.nextInt();
		int k = in.nextInt();
		removed = new boolean[n];
		int[] s = new int[n-1];
		int[] t = new int[n-1];
		for (int i=0; i<n-1; i++) {
			s[i] = in.nextInt() - 1;
			t[i] = in.nextInt() - 1;
		}

		int[][] g = undirectedGraph(n, s, t);
		int x = doubleSweep(g,n);
		if (x <= k) {
			out.println("0");
			return;
		}

		cnt = new int[n];
		Arrays.fill(cnt, Integer.MAX_VALUE/2);
		for (int i=0; i<n; i++) {
			rec(g, i, -1);
		}

		int ans = 0;
		while (true) {

			for (int to : g[p]) {
				if (!removed[to]) {
					p = to;
					break;
				}
			}
			for (int to : g[q]) {
				if (!removed[to]) {
					q = to;
					break;
				}
			}

			if (cnt[p] < cnt[q]) {
				ans += cnt[p] - 1;
				for (int to : g[p]) {
					if (cnt[to] == 1) {
						removed[to] = true;
					}
				}
			} else {
				ans += cnt[q] - 1;
				for (int to : g[q]) {
					if (cnt[to] == 1) {
						removed[to] = true;
					}
				}
			}
			int m = doubleSweep(g, n);
			if (m <= k) {
				out.println(ans);
				return;
			}
			for (int i=0; i<n; i++) {
				rec(g, i, -1);
			}
		}
	}

	public static void main(String[] args) {
		debug = args.length > 0;
		long start = System.nanoTime();

		solve();
		out.flush();

		long end = System.nanoTime();
		dump((end - start) / 1000000 + " ms");
		in.close();
		out.close();
	}

	static void dump(Object... o) { if (debug) System.err.println(Arrays.deepToString(o)); }
}

