			adj[i] = new ArrayList<Integer>();
		}
		for (int i = 0; i < n - 1; i++) {
			int from = r.nextInt() - 1;
			int to = r.nextInt() - 1;
			adj[from].add(to);
			adj[to].add(from);
		}
		int res = 1 << 28;
		for (int i = 0; i < n; i++) {
			LinkedList<Integer> q = new LinkedList<Integer>();
			q.add(i);
			q.add(0);
			boolean[] vis = new boolean[n];
			vis[i] = true;
			HashSet<Integer> set = new HashSet<Integer>();
			int last = -1;
			while (!q.isEmpty()) {
				int front = q.remove();
				set.add(front);
				last = front;
				int cost = q.remove();
				if (cost == k) {
					continue;
				}
				for (int x : adj[front]) {
					if (!vis[x]) {
						q.add(x);
						q.add(cost + 1);
						vis[x] = true;
					}
				}
			}
			vis = new boolean[n];
			vis[last] = true;
			q.add(last);
			q.add(0);
			int diameter = -1;
			int reached = 0;
			HashSet<Integer> set2 = new HashSet<Integer>();
			while (!q.isEmpty()) {
				int front = q.remove();
				int cost = q.remove();
				reached++;
				diameter = cost;
				if (diameter <= k) {
					last = front;
					set2.add(front);
					res = Math.min(res, n - reached);
				}
				for (int x : adj[front]) {
					if (!vis[x] && set.contains(x)) {
						q.add(x);
						q.add(cost + 1);
						vis[x] = true;
					}
				}
			}
			vis = new boolean[n];
			vis[last] = true;
			q.add(last);
			q.add(0);
			reached = 0;
			diameter = -1;
			while (!q.isEmpty()) {
				int front = q.remove();
				int cost = q.remove();
				reached++;
				diameter = cost;
				if (diameter <= k) {
					last = front;
					res = Math.min(res, n - reached);
				}
				for (int x : adj[front]) {
					if (!vis[x] && set2.contains(x)) {
						q.add(x);
						q.add(cost + 1);
						vis[x] = true;
					}
				}
			}
		}
		System.out.println(res);
	}

