using System;
using System.Collections.Generic;
using CompLib.Util;

public class Program
{
    private int N, K;
    private List<int>[] E;

    private int[,] Dist;

    public void Solve()
    {
        var sc = new Scanner();
        N = sc.NextInt();
        K = sc.NextInt();
        E = new List<int>[N];
        for (int i = 0; i < N; i++)
        {
            E[i] = new List<int>();
        }

        int[] a = new int[N - 1];
        int[] b = new int[N - 1];
        for (int i = 0; i < N - 1; i++)
        {
            a[i] = sc.NextInt() - 1;
            b[i] = sc.NextInt() - 1;
            E[a[i]].Add(b[i]);
            E[b[i]].Add(a[i]);
        }

        Dist = new int[N, N];
        for (int i = 0; i < N; i++)
        {
            Dist[i, i] = 0;
            Go(i, i, -1);
        }

        int ans = int.MaxValue;
        if (K % 2 == 0)
        {
            for (int m = 0; m < N; m++)
            {
                int cnt = 0;
                for (int i = 0; i < N; i++)
                {
                    if (Dist[m, i] > K / 2) cnt++;
                }

                ans = Math.Min(ans, cnt);
            }
        }
        else
        {
            for (int i = 0; i < N - 1; i++)
            {
                int cnt = 0;
                for (int j = 0; j < N; j++)
                {
                    if (Math.Min(Dist[a[i], j], Dist[b[i], j]) > K / 2) cnt++;
                }

                ans = Math.Min(ans, cnt);
            }
        }

        Console.WriteLine(ans);
    }

    void Go(int root, int cur, int par)
    {
        foreach (int to in E[cur])
        {
            if (par == to) continue;
            Dist[root, to] = Dist[root, cur] + 1;
            Go(root, to, cur);
        }
    }

    public static void Main(string[] args) => new Program().Solve();
}

