using Enu = System.Linq.Enumerable;

public class Program
{
    List<int>[] E;

    public void Solve()
    {
        int N = Reader.Int(), K = Reader.Int();
        E = Enu.Range(0, N).Select(i => new List<int>()).ToArray();

        for (int i = 0; i < N - 1; i++)
        {
            int a = Reader.Int() - 1, b = Reader.Int() - 1;
            E[a].Add(b);
            E[b].Add(a);
        }
        int ans = N;
        for (int start = 0; start < N; start++)
        {
            int currBest = int.MaxValue;
            foreach (int next in E[start])
            {
                var t = Count(next, start, 1, K);
                currBest = Math.Min(currBest, N - 1 - t.Item1 + t.Item2);
            }
            ans = Math.Min(ans, currBest);
        }

        Console.WriteLine(ans);
    }

    Tuple<int, int> Count(int at, int prev, int depth, int K)
    {
        int all = 1;
        int bad = 0;
        if (depth > K) bad = 1;

        foreach (int next in E[at])
            if (next != prev)
            {
                var curr = Count(next, at, depth + 1, K);
                all += curr.Item1;
                bad += curr.Item2;
            }

        return new Tuple<int, int>(all, bad);
    }


}


