class P
{
    static void Main()
    {
        var nk = Console.ReadLine().Split().Select(int.Parse).ToList();
        List<int>[] neighbours = Enumerable.Repeat(0, nk[0]).Select(_ => new List<int>()).ToArray();
        List<Tuple<int, int>> edges = new List<Tuple<int, int>>();
        for (int i = 0; i < nk[0] - 1; i++)
        {
            var ab = Console.ReadLine().Split().Select(x => int.Parse(x) - 1).ToList();
            neighbours[ab[0]].Add(ab[1]);
            neighbours[ab[1]].Add(ab[0]);
            edges.Add(new Tuple<int, int>(ab[0], ab[1]));
        }

        int[][][] datas = neighbours.Select(x => new int[x.Count][]).ToArray();

        Func<int, int, int[]> dfs = null;
        dfs = (x, from) =>
        {
            IEnumerable<int> enumerable = Enumerable.Repeat(0, 2000);
            for (int i = 0; i < datas[x].Length; i++)
            {
                var dest = neighbours[x][i];
                if (dest == from) continue;
                enumerable = enumerable.Zip(Enumerable.Repeat(0, 1).Concat(datas[x][i] != null ? datas[x][i] : (datas[x][i] = dfs(dest, x))), (a, b) => a + b);
            }
            var ret = enumerable.ToArray();
            ret[0] = 1;
            return ret;
        };
        for (int i = 0; i < nk[0]; i++) dfs(i, -1);

        int res = int.MaxValue;
        if (nk[1] % 2 == 0)
        {
            res = Enumerable.Range(0, nk[0]).Min(x => dfs(x, -1).Skip(nk[1] / 2 + 1).Sum());
        }
        else
        {
            res = edges.Min(x => dfs(x.Item1, x.Item2).Zip(dfs(x.Item2, x.Item1), (y, z) => y + z).Skip(nk[1] / 2 + 1).Sum());
        }
        Console.WriteLine(res);
    }

    static int[] Prime(int max)
    {
        if (max < 2) return new int[0];
        List<int> res = new List<int>();
        int sqrtMax = (int)Math.Sqrt(max);
        List<int> sieve = Enumerable.Range(2, max - 2).ToList();
        while (sieve.Count != 0)
        {
            int p = sieve[0];
            if (p > sqrtMax) break;
            res.Add(p);
            sieve.RemoveAll(x => x % p == 0);
        }
        res.AddRange(sieve);
        return res.ToArray();
    }
}

using System;
using System.Linq;//リストの使用
using System.Collections.Generic;
class Program
{
static int[] numsa = Array.ConvertAll(Console.ReadLine().Split(' '),int.Parse);
static int n = numsa[0];
static int k = numsa[1];
static List<int[]>[] nextList = new List<int[]>[n];//頂点番号ごとの隣接リスト。距離、隣接頂点番号
static int[] colors = new int[n];//最短距離未確定の頂点が0、確定で2
static int[] distances = new int[n];//各頂点への最短距離
static int[] distanceMemos = new int[2];//キューから捨てた最短距離と頂点番号
static int[] diameters = new int[n];
static int[,] nextmemos = new int[n-1,2];
static int answer = int.MaxValue;

	static void Main()
	{
    for(int i = 0; i < n; i++)nextList[i] = new List<int[]>();//リストの宣言が必要
    for(int i = 0; i < n-1; i++)
    {
      int[] nums = Array.ConvertAll(Console.ReadLine().Split(' '),int.Parse);

        nextmemos[i,0] = nums[0]-1;
        nextmemos[i,1] = nums[1]-1;

        int[] nextMemo = new int[2];
        nextMemo[1] = nums[1]-1;//隣接頂点番号
        nextMemo[0] = 1;//距離
        nextList[nums[0]-1].Add(nextMemo);//隣接リストの作成

        int[] nextMemoSub = new int[2];
        nextMemoSub[1] = nums[0]-1;//隣接頂点番号
        nextMemoSub[0] = 1;//距離
        nextList[nums[1]-1].Add(nextMemoSub);//隣接リストの作成
    }
    for(int i = 0; i < n; i++)
    {
      if(k % 2 == 0)//距離が偶数
      {
        Dijkstra(i);
        int memo = 0;
        for(int j = 0; j < n; j++)
        {
          if(distances[j] > k/2) memo++;
        }
        //Console.WriteLine(memo);
        answer = Math.Min(answer, memo);//取り除く個数の最小値の更新
      }
    }

    if(k % 2 == 1)//距離が奇数
    {
      for(int i = 0; i < n-1; i++)
      {
        int[,] distanceMemos = new int[n-1,2];
        Dijkstra(nextmemos[i,0]);
        for(int j = 0; j < n-1; j++) distanceMemos[j,0] = distances[j];
        Dijkstra(nextmemos[i,1]);
        for(int j = 0; j < n-1; j++) distanceMemos[j,1] = distances[j];

        int memo = 0;
        for(int j = 0; j < n-1; j++)
        {
          if(Math.Min(distanceMemos[j,0], distanceMemos[j,1]) > k/2) memo++;
        }
        answer = Math.Min(answer, memo);//取り除く個数の最小値の更新
      }
    }

    Console.WriteLine(answer);
	}

  static void Dijkstra(int startVertex)//O((|頂点数|+|辺数|)log頂点数)で各頂点への最短距離を求める
  {
    List<int[]> distanceList = new List<int[]>();//優先度付きキュー
    for(int i = 0; i < n; i++)
    {
      distances[i] = int.MaxValue;//最短距離を無限とおく
      colors[i] = 0;
    }

    int[] newDistance = new int[2];

    //スタート地点を決める
    newDistance[1] = startVertex;//スタート地点番号
    distances[startVertex] = 0;
    colors[startVertex] = 1;

    newDistance[0] = 0;//スタートからスタートまでの距離0
    distanceList.Add(newDistance);

    while(distanceList.Count() != 0)
    {
      distanceList = PopHeap(distanceList);
      int minVertex = distanceMemos[1];//最短頂点の番号
      colors[minVertex] = 2;
      if(distances[minVertex] < distanceMemos[0]) continue;//最小値が最短でないなら無視

      for(int i = 0; i < nextList[minVertex].Count(); i++)
      {
        int v = nextList[minVertex][(int)i][1];
        if(colors[v] == 2) continue;
        if(distances[v] > distances[minVertex] + nextList[minVertex][(int)i][0])
        {
          distances[v] = distances[minVertex] + nextList[minVertex][(int)i][0];
          int[] newDistanceSub = new int[2];
          newDistanceSub[0] = distances[v];
          newDistanceSub[1] = v;
          distanceList = PushHeap(distanceList, newDistanceSub);
          colors[v] = 1;
        }
      }
    }

  }

  //引数は、昇順にソート済みのリスト
  static List<int[]> PushHeap(List<int[]> nums, int[] addNums)//現在のヒープnumsにaddNumを追加
  {
    int n = nums.Count;
    nums.Add(addNums);

    while (n > 0)
    {
      int i = (n-1)/2;
      if (nums[n][0] < nums[i][0])//親のほうが大きいなら入れ替え。
      {
        int tmp = nums[n][0];
        int tmpSub = nums[n][1];
        nums[n][0] = nums[i][0];
        nums[n][1] = nums[i][1];
        nums[i][0] = tmp;
        nums[i][1] = tmpSub;
      }
      n = i;
    }
    return nums;
  }

  static List<int[]> PopHeap(List<int[]> nums)//ヒープnumsからポップ
  {
    int n = nums.Count - 1;
    distanceMemos[0] = nums[0][0];//捨てる値の保存
    distanceMemos[1] = nums[0][1];
    nums[0][0] = nums[n][0];//最小値である根を削除してリストの最後を持ってくる
    nums[0][1] = nums[n][1];
    nums.RemoveAt(n);

    for (int i = 0, j; (j = 2*i+1) < n; )
    {
      if ((j != n-1) && (nums[j][0] > nums[j+1][0]))// ２つの子のうち、値の小さい方を選ぶ
        j++;
      if (nums[i][0] > nums[j][0])//子が親より小さいなら入れ替え
      {
        int tmp = nums[j][0];
        int tmpSub = nums[j][1];
        nums[j][0] = nums[i][0];
        nums[j][1] = nums[i][1];
        nums[i][0] = tmp;
        nums[i][1] = tmpSub;
      }
      i = j;
    }
    return nums;
  }

}

