                while (q.Any())
                {
                    int p = q.Dequeue();
                    if (dist[p] >= lim)
                    {
                        q.Clear();
                        break;
                    }

                    foreach (var item in edge[p])
                    {
                        if (dist[item] < 0)
                        {
                            dist[item] = dist[p] + 1;
                            ++c;
                            q.Enqueue(item);
                        }
                    }
                }
                q.Enqueue(i[1]);
                while (q.Any())
                {
                    int p = q.Dequeue();
                    if (dist[p] >= lim)
                    {
                        q.Clear();
                        break;
                    }

                    foreach (var item in edge[p])
                    {
                        if (dist[item] < 0)
                        {
                            dist[item] = dist[p] + 1;
                            ++c;
                            q.Enqueue(item);
                        }
                    }
                }
                min = Math.Min(min, n - c);
            }
        }
        sw.WriteLine(min);
        sw.Flush();
    }

