class Myon
{
    public Myon() { }
    public static int Main()
    {
        new Myon().calc();
        return 0;
    }


    Scanner cin;
    List<int>[] es;

    void calc()
    {
        cin = new Scanner();
        int N = cin.nextInt();
        int K = cin.nextInt();
        es = new List<int>[N];
        for (int i = 0; i < N; i++)
        {
            es[i] = new List<int>();
        }

        for (int i = 0; i < N - 1; i++)
        {
            int a = cin.nextInt() - 1;
            int b = cin.nextInt() - 1;
            es[a].Add(b);
            es[b].Add(a);
        }

        int ans = 0;

        for (int i = 0; i < N; i++)
        {
            List<int> over = new List<int>();
            List<int> under = new List<int>();
            foreach (var item in es[i])
            {
                over.Add(dfs(item, i, (K + 1) / 2));
                under.Add(dfs(item, i, (K) / 2));
            }

            int sum = under.Sum();
            for (int j = 0; j < over.Count; j++)
            {
                ans = Math.Max(ans, sum - under[j] + over[j] + 1);
            }
        }

        ans = N - ans;

        Console.WriteLine(ans);
    }

    int dfs(int a, int pre, int dep)
    {
        if (dep <= 0) return 0;
        int ans = 1;
        foreach (var next in es[a])
        {
            if (next == pre) continue;
            ans += dfs(next, a, dep - 1);
        }
        return ans;
    }
}



