    public class Solver
    {
        public void Solve()
        {
            var n = sc.Integer();
            var k = sc.Integer();
            var G = Enumerate(n, x => new List<int>());
            for (int i = 0; i < n - 1; i++)
            {
                var a = sc.Integer() - 1;
                var b = sc.Integer() - 1;
                G[a].Add(b);
                G[b].Add(a);
            }
            Func<int, int, int[]> dfs = null;
            dfs = (prev, cur) =>
              {
                  Debug.WriteLine("{0} {1}", prev, cur);
                  var S = 1;
                  var ret = new int[S];
                  ret[0] = 1;
                  foreach (var to in G[cur])
                  {
                      if (to == prev) continue;
                      var res = dfs(cur, to);
                      var T = res.Length;
                      var next = new int[S + T];

                      for (int i = 0; i < S; i++)
                      {
                          next[i] = Math.Max(next[i], ret[i]);
                          for (int j = 0; j < T; j++)
                          {
                              if (i + j + 1 > k) continue;
                              var go = Math.Max(i, j + 1);
                              next[go] = Math.Max(next[go], ret[i] + res[j]);
                          }
                      }

                      S += T;
                      ret = next;
                  }
                  return ret;
              };
            var ans = dfs(-1, 0);
            var val = int.MinValue;
            for (int i = 0; i < ans.Length; i++)
            {
                if (i <= k) val = Math.Max(val, ans[i]);
            }
            IO.Printer.Out.WriteLine(n - val);
        }

