			int k = cin.Int();

			var ab = new Tuple<int, int>[n - 1];
			for (int i = 0; i < n - 1; i++) {
				int a = cin.Int() - 1;
				int b = cin.Int() - 1;
				ab[i] = new Tuple<int, int>(a, b);
			}

			var to = new List<int>[n];
			for (int i = 0; i < n; i++) {
				to[i] = new List<int>();
			}

			for (int i = 0; i < n - 1; i++) {
				int a = ab[i].Item1;
				int b = ab[i].Item2;
				to[a].Add(b);
				to[b].Add(a);
			}

			int ans = int.MaxValue;
			if (k % 2 == 0) {
				int d = k / 2;
				for (int i = 0; i < n; i++) {
					var ds = GetDistance(n, i, to);
					int count = ds.Where(x => x > d).Count();
					ans = Math.Min(ans, count);
				}
			} else {
				int d = (k - 1) / 2;
				for (int i = 0; i < n - 1; i++) {
					var ds = GetDistance(n, ab[i].Item1, ab[i].Item2, to);
					int count = ds.Where(x => x > d).Count();
					ans = Math.Min(ans, count);
				}
			}

			Console.WriteLine(ans);

		}

		private static int[] GetDistance(int n, int s, List<int>[] to)
		{
			var d = new int[n];
			for (int i = 0; i < n; i++) {
				d[i] = -1;
			}

			d[s] = 0;
			var q = new Queue<int>();
			q.Enqueue(s);
			while (q.Count > 0) {
				int cur = q.Dequeue();
				foreach (int next in to[cur]) {
					if (d[next] == -1) {
						d[next] = d[cur] + 1;
						q.Enqueue(next);
					}
				}
			}

			return d;
		}

		private static int[] GetDistance(int n, int a, int b, List<int>[] to)
		{
			var d = new int[n];
			for (int i = 0; i < n; i++) {
				d[i] = -1;
			}

			d[a] = 0;
			d[b] = 0;
			var q = new Queue<int>();
			q.Enqueue(a);
			q.Enqueue(b);
			while (q.Count > 0) {
				int cur = q.Dequeue();
				foreach (int next in to[cur]) {
					if (d[next] == -1) {
						d[next] = d[cur] + 1;
						q.Enqueue(next);
					}
				}
			}

			return d;
		}
	}

