class Program
{
    static void Main(string[] args)
    {
        Solve();
        //WriteLine(Solve());
    }
    static int[] nk;
    static List<int>[] adj;
    static void Solve()
    {
        nk = Input.ar;
        adj = Enumerable.Repeat(0, nk[0]).Select(_ => new List<int>()).ToArray();
        for(var i=0;i<nk[0]-1;i++)
        {
            var ab = Input.ar;
            ab[0]--;ab[1]--;
            adj[ab[0]].Add(ab[1]);
            adj[ab[1]].Add(ab[0]);
        }
        var res = int.MaxValue;
        for (var i = 0; i < nk[0]; i++)
            if (adj[i].Count == 1)
                res = Min(res, bfs(i));
        WriteLine(res);
    }
    static int bfs(int st)
    {
        var dist = Enumerable.Repeat(-1, nk[0]).ToArray();
        dist[st] = 0;
        var que = new Queue<int>();
        que.Enqueue(st);
        while (que.Any())
        {
            var p = que.Dequeue();
            foreach (var ad in adj[p])
            {
                if (dist[ad] != -1||dist[p]+1>nk[1]) continue;
                dist[ad] = dist[p] + 1;
                que.Enqueue(ad);
            }
        }
        return dist.Count(v => v == -1);
    }
}

