class Myon
{
    public Myon() { }
    public static int Main()
    {
        new Myon().calc();
        return 0;
    }

    Scanner cin;


    int ans;
    int N, K;
    List<int>[] es;

    void calc()
    {
        cin = new Scanner();
        N = cin.nextInt();
        K = cin.nextInt();
        es = new List<int>[N];
        for (int i = 0; i < N; i++)
        {
            es[i] = new List<int>();
        }
        for (int i = 0; i < N - 1; i++)
        {
            int a = cin.nextInt() - 1;
            int b = cin.nextInt() - 1;
            es[a].Add(b);
            es[b].Add(a);
        }

        ans = 0;
        dfs(0, -1);
        Console.WriteLine(N - ans);
    }

    int[] dfs(int now, int pre)
    {
        int[] all = new int[N + 2];
        for (int i = 1; i < N + 2; i++)
        {
            all[i] = 1;
        }
        List<int[]> l = new List<int[]>();
        foreach (var next in es[now])
        {
            if (next == pre) continue;
            int[] tmp = dfs(next, now);
            l.Add(tmp);
            for (int i = 0; i < N + 1; i++)
            {
                all[i + 1] += tmp[i];
            }
        }

        foreach (var ar in l)
        {
            for (int i = 1; i <= K; i++)
            {
                ans = Math.Max(ans, ar[i] + (all[K + 1 - i] - ar[K - i]));
            }
        }


        return all;
    }


}

