namespace ConsoleApp1
{
    public class node
    {
        public List<node> connect = new List<node>();
        public int index;
    }
    class Program
    {
        static void Main(string[] args)
        {
            var temp = Console.ReadLine().Split(' ').Select(x => long.Parse(x)).ToArray();
            var n = temp[0];
            var k = temp[1];

            node[] nodes = Enumerable.Range(1, (int)n+1).Select(x => new node { index = x }).ToArray();

            int[] a = new int[n + 1];
            int[] b = new int[n + 1];
            for (int i = 1; i < n; i++)
            {
                var t= Console.ReadLine().Split(' ').Select(x => int.Parse(x)).ToArray();
                a[i] = t[0];
                b[i] = t[1];
                nodes[a[i]].connect.Add(nodes[b[i]]);
                nodes[b[i]].connect.Add(nodes[a[i]]);
            }
            int ans = int.MaxValue;
            if (k%2==0)ans = (int)n - nodes.Select(x => search(x, null, (int)k/2)).Skip(1).Max();
            else
            {
                int[] temp1 = nodes.Select(x => search(x, null, (int)(k - 1) / 2)).ToArray();

                for (int i = 1; i < nodes.Length; i++)
                {
                    temp1[i] += nodes[i].connect.Select(x => search_l(x, nodes[i], ((int)k + 1) / 2)).Max();
                }

                ans = (int)n - temp1.Skip(1).Max();                
            }
        }

        /// <summary>k個以内のノード数(自分含めて)</summary>
        static int search(node node,node pre, int k)
        {
            if (k == 0) return 1;
            return node.connect.Where(x => x != pre).Select(x => search(x, node, k - 1)).Sum() + 1;
        }
        /// <summary>
        /// 距離nのノード数
        /// </summary>
        static int search_l(node node, node pre, int k)
        {
            if (k == 0) return 1;
            return node.connect.Where(x => x != pre).Select(x => search_l(x, node, k - 1)).Sum();
        }
    }
}

using System;
using System.Collections;
using System.Collections.Generic;
using System.Diagnostics;
using System.IO;
using System.Linq;
using System.Numerics;
using System.Text;
using Problem = Tmp.Problem;
namespace Tmp
{
	//using GeometryLong;
	class Problem : IDisposable
	{
		bool IsGCJ;
		int Repeat;
		Scanner sc;
		Printer pr;
		public Problem(bool isGCJ, Scanner scanner, Printer printer)
		{
			sc = scanner;
			pr = printer;
			IsGCJ = isGCJ;
			if (isGCJ) Repeat = sc.Get<int>();
			else Read();
		}
		public Problem(bool isGCJ) : this(isGCJ, new Scanner(), new Printer()) { }
		public Problem(bool isGCJ, Scanner scanner) : this(isGCJ, scanner, new Printer()) { }
		public Problem(bool isGCJ, Printer printer) : this(isGCJ, new Scanner(), printer) { }
		public void Solve()
		{
			if (IsGCJ) for (var i = 0; i < Repeat; i++) { Read(); pr.Write("Case #" + (i + 1) + ": "); SolveOne(); }
			else SolveOne();
		}
		public void Dispose()
		{
			sc.Dispose();
			pr.Dispose();
		}
		public int Size { get { return 1; } }
		public const uint Mod = 1000000007;
		RandomSFMT rand = Program.rand;
		int N, K;
		Tuple<int, int>[] rs;
		void Read()
		{
			sc.Read(out N, out K);
			rs = sc.ReadManyLines<int, int>(N - 1);
		}
		HashSet<int>[] es;
		bool[] removed;
		void SolveOne()
		{
			es = new HashSet<int>[N];
			for (var i = 0; i < N; i++) es[i] = new HashSet<int>();
			foreach (var r in rs)
			{
				int a = r.Item1 - 1, b = r.Item2 - 1;
				es[a].Add(b); es[b].Add(a);
			}
			removed = new bool[N];
			var max = 0;
			for (var i = 0; i < N; i++)
				if (es[i].Count == 1)
				{
					used = new bool[N];
					depth = new int[N];
					max = Math.Max(max, Calc(i));
				}
			foreach (var r in rs)
			{
				int a = r.Item1 - 1, b = r.Item2 - 1;
				used = new bool[N];
				depth = new int[N];
				removed[b] = true;
				es[a].Remove(b);
				max = Math.Max(max, Calc(a));
				removed[b] = false;
				es[a].Add(b);

				used = new bool[N];
				depth = new int[N];
				removed[a] = true;
				es[b].Remove(a);
				max = Math.Max(max, Calc(b));
				removed[a] = false;
				es[b].Add(a);
			}
			pr.WriteLine(N - max);
		}
		int Calc(int u)
		{
			DFS(-1, u, 0);
			var sum = N;
			for (var v = 0; v < N; v++) if (removed[v] = !used[v] || depth[v] > K) sum--;
			var r = Visit(-1, u);
			var t = Visit(-1, r.Item2);
			if (t.Item1 > K) return 0;
			else return sum;
		}
		bool[] used;
		int[] depth;
		void DFS(int p, int u, int d)
		{
			//if (d > K) return;
			used[u] = true;
			depth[u] = d;
			foreach (var v in es[u])
			{
				if (v == p || removed[v]) continue;
				DFS(u, v, d + 1);
			}
		}
		void Remove(int u)
		{
			removed[u] = true;
			foreach (var w in es[u]) es[w].Remove(u);
			es[u].Clear();
		}
		Tuple<int, int> Visit(int p, int v)
		{
			var r = new Tuple<int, int>(0, v);
			foreach (var w in es[v])
			{
				if (w == p || removed[w]) continue;
				var t = Visit(v, w);
				if (r.Item1 < t.Item1 + 1) r = new Tuple<int, int>(t.Item1 + 1, t.Item2);
			}
			return r;
		}
	}
}
