        var a = new int[n - 1][];
        for (int i = 0; i < n; i++)
            edge[i] = new List<int>();

        for (int i = 0; i < n - 1; i++)
        {
            a[i] = sc.IntArr.Select(x => x - 1).ToArray();
            edge[a[i][0]].Add(a[i][1]);
            edge[a[i][1]].Add(a[i][0]);
        }
        int lim = k >> 1;
        int min = n - 2;
        var q = new Queue<int>();
        if (k % 2 == 0)
        {
            for (int i = 0; i < n; i++)
            {
                var dist = new int[n];
                for (int j = 0; j < n; j++)
                    dist[j] = -1;

                int c = 1;
                dist[i] = 0;
                q.Enqueue(i);
                while (q.Any())
                {
                    int p = q.Dequeue();
                    if (dist[p] >= lim)
                        continue;

                    foreach (var item in edge[p])
                    {
                        if (dist[item] < 0)
                        {
                            dist[item] = dist[p] + 1;
                            ++c;
                            q.Enqueue(item);
                        }
                    }
                }
                min = Math.Min(min, n - c);
            }
        }
        else
        {
            foreach (var i in a)
            {
                var dist = new int[n];
                for (int j = 0; j < n; j++)
                    dist[j] = -1;

                int c = 2;
                dist[i[0]] = 0;
                dist[i[1]] = 0;
                q.Enqueue(i[0]);
                while (q.Any())
                {
                    int p = q.Dequeue();
                    if (dist[p] >= lim)
                        continue;

                    foreach (var item in edge[p])
                    {
                        if (dist[item] < 0)
                        {
                            dist[item] = dist[p] + 1;
                            ++c;
                            q.Enqueue(item);
                        }
                    }
                }
                q.Enqueue(i[1]);
                while (q.Any())
                {
                    int p = q.Dequeue();
                    if (dist[p] >= lim)
                        continue;

                    foreach (var item in edge[p])
                    {
                        if (dist[item] < 0)
                        {
                            dist[item] = dist[p] + 1;
                            ++c;
                            q.Enqueue(item);
