namespace AtCorder
{
	public class Program
	{
		static void Main(string[] args)
		{
			var cin = new Scanner2();
			int n = cin.Int();
			int k = cin.Int();
			var to = new List<int>[n];
			for (int i = 0; i < n; i++) {
				to[i] = new List<int>();
			}

			for (int i = 0; i < n - 1; i++) {
				int a = cin.Int() - 1;
				int b = cin.Int() - 1;
				to[a].Add(b);
				to[b].Add(a);
			}

			var d0 = GetDistance(n, 0, to);
			int tempMax = d0.Max();
			var hashi = new List<int>();
			for (int i = 0; i < n; i++) {
				if (d0[i] == tempMax) {
					hashi.Add(i);
				}
			}

			bool[] done = new bool[n];
			int tempAns = int.MaxValue;
			int ans = 0;
			foreach (int target in hashi) {
				var d = GetDistance(n, target, to);
				int count = d.Where(x => x > k).Count();
				tempAns = Math.Min(tempAns, count);

				done[target] = true;

				int max = d.Max();
				var revhashi = new List<int>();
				for (int i = 0; i < n; i++) {
					if (d[i] == max) {
						revhashi.Add(i);
					}
				}

				foreach (int revtarget in revhashi) {
					if (done[revtarget]) {
						continue;
					}

					var d2 = GetDistance(n, revtarget, to);
					int count2 = d2.Where(x => x > k).Count();
					tempAns = Math.Min(tempAns, count2);

					done[revtarget] = true;
				}
			}

			if (tempAns != int.MaxValue) {
				ans = tempAns;
			}

			Console.WriteLine(ans);
		}

		private static int[] GetDistance(int n, int s, List<int>[] to)
		{
			var d = new int[n];
			for (int i = 0; i < n; i++) {
				d[i] = -1;
			}

			d[s] = 0;
			var q = new Queue<int>();
			q.Enqueue(s);
			while (q.Count > 0) {
				int cur = q.Dequeue();
				foreach (int next in to[cur]) {
					if (d[next] == -1) {
						d[next] = d[cur] + 1;
						q.Enqueue(next);
					}
				}
			}

			return d;
		}
	}

	public class Scanner2
	{
		private readonly char[] delimiter_ = new char[] { ' ' };
		private readonly string filePath_;
		private readonly Func<string> reader_;
		private string[] buf_;
		private int index_;

		public Scanner2(string file = "")
		{
			if (string.IsNullOrWhiteSpace(file)) {
				reader_ = Console.ReadLine;
			} else {
				filePath_ = file;
				var fs = new StreamReader(file);
				reader_ = fs.ReadLine;
			}
			buf_ = new string[0];
			index_ = 0;
		}

		public string Next()
		{
			if (index_ < buf_.Length) {
				return buf_[index_++];
			}

			string st = reader_();
			while (st == "") {
				st = reader_();
			}

			buf_ = st.Split(delimiter_, StringSplitOptions.RemoveEmptyEntries);
			if (buf_.Length == 0) {
				return Next();
			}

			index_ = 0;
			return buf_[index_++];
		}

		public int Int() => int.Parse(Next());
		public long Long() => long.Parse(Next());
		public double Double() => double.Parse(Next());

		public int[] ArrayInt(int N, int add = 0)
		{
			int[] Array = new int[N];
			for (int i = 0; i < N; i++) {
				Array[i] = Int() + add;
			}
			return Array;
		}

		public long[] ArrayLong(int N, long add = 0)
		{
			long[] Array = new long[N];
			for (int i = 0; i < N; i++) {
				Array[i] = Long() + add;
			}
			return Array;
		}

		public double[] ArrayDouble(int N, double add = 0)
		{
			double[] Array = new double[N];
			for (int i = 0; i < N; i++) {
				Array[i] = Double() + add;
			}
			return Array;
		}

		public void Save(string text)
		{
			if (string.IsNullOrWhiteSpace(filePath_)) {
				return;
			}

			File.WriteAllText(filePath_ + "_output.txt", text);
		}
	}
}

