namespace ConsoleApplication1
{
    class Program
    {
        static void Main(string[] args)
        {
            var str = Console.ReadLine().Split();
            var n = Int32.Parse(str[0]);
            var k = Int32.Parse(str[1]);

            var graph = new bool[n, n];
            for (int i = 0; i < n; i++)
            {
                str = Console.ReadLine().Split();
                var a = Int32.Parse(str[0]) - 1;
                var b = Int32.Parse(str[1]) - 1;
                graph[a, b] = true;
                graph[b, a] = true;
            }

            Console.WriteLine(Solver.Solve(n, k, graph));
        }
    }

    public class Solver
    {
        static bool[] vertices;
        static int _n;
        static int _k;
        static bool[,] _graph;

        public static int Solve(int n, int k, bool[,] graph)
        {
            _n = n;
            _k = k;
            _graph = graph;

            vertices = new bool[n];
            for (int i = 0; i < n; i++) vertices[i] = true;

            var ret = 0;
            while (true)
            {
                var dia = GetDia(ref ret);
                if (dia <= k) break;
            }
            return ret;
        }

        static int GetDia(ref int ret)
        {
            var st = -1;
            for (int i = 0; i < _n; i++)
            {
                if (vertices[i])
                {
                    st = i;
                    break;
                }
            }
            if (st == -1) return 0;

            int a = 0, b = 0;
            var adist = GetFarest(st, ref a);
            var bdist = GetFarest(a, ref b);

            if (bdist > _k)
            {
                vertices[b] = false;
                ret++;
                return GetFarest(a, ref b);
            }
            return bdist;
        }

        static int GetFarest(int idx, ref int farestIdx)
        {
            var visit = new bool[_n];
            int maxDist = 0;
            Dfs(idx, visit, ref maxDist, 0, ref farestIdx);
            return maxDist;
        }

        static void Dfs(int idx, bool[] visit, ref int maxDist, int currentDist, ref int farestIdx)
        {
            if (visit[idx]) return;
            visit[idx] = true;

            if (currentDist > maxDist)
            {
                maxDist = currentDist;
                farestIdx = idx;
            }

            //go next
            for (int next = 0; next < _n; next++)
            {
                if (next == idx) continue;
                if (visit[next]) continue;
                if (!vertices[next]) continue;
                if (!_graph[idx, next]) continue;
                Dfs(next, visit, ref maxDist, currentDist + 1, ref farestIdx);
            }
        }
    }
}

using System;
