namespace CompetitiveProgramming
{
    class Solve
    {
        const int INF = (int)1e9 + 10;
        public Solve()
        {
            int N = Scanner.nextInt();
            int K = Scanner.nextInt();

            int[, ] c = new int[N, N];
            for (int i = 0; i < N; i++)
            {
                for (int j = 0; j < N; j++)
                {
                    c[i, j] = INF;
                }
            }
            for (int i = 0; i < N - 1; i++)
            {
                int A = Scanner.nextInt() - 1;
                int B = Scanner.nextInt() - 1;
                c[A, B] = 1;
                c[B, A] = 1;
            }

            int[] d = new int[N].Select(x => INF).ToArray();
            bool[] u = new bool[N];
            d[0] = 0;

            while (true)
            {
                int v = -1;
                for (int n = 0; n < N; n++)
                {
                    if (!u[n] && (v == -1 || d[n] < d[v])) {
                        v = n;
                    }
                }

                if (v == -1)
                {
                    break;
                }
                u[v] = true;
                for (int n = 0; n < N; n++)
                {
                    d[n] = Math.Min(d[n], d[v] + c[v, n]);
                }
            }

            int M = -1, node = -1;
            for (int i = 0; i < N; i++)
            {
                if (d[i] > M)
                {
                    M = d[i];
                    node = i;
                }
            }

            int[] e = new int[N].Select(x => INF).ToArray();
            bool[] r = new bool[N];
            e[node] = 0;

            while (true)
            {
                int v = -1;
                for (int n = 0; n < N; n++)
                {
                    if (!r[n] && (v == -1 || e[n] < e[v]))
                    {
                        v = n;
                    }
                }

                if (v == -1)
                {
                    break;
                }
                r[v] = true;
                for (int n = 0; n < N; n++)
                {
                    e[n] = Math.Min(e[n], e[v] + c[v, n]);
                }
            }

            ArrayList dist = new ArrayList();
            for (int i = 0; i < N; i++)
            {
                if (i == node)
                {
                    continue;
                }
                dist.Add(e[i]);
            }
            dist.Sort();

            int lp = 0, rp = N;
            for (int i = 0; i < N; i++)
            {
                int mp = (lp + rp) / 2;
                if (mp >= dist.Count)
                {
                    mp = dist.Count - 1;
                } else if (mp < 0)
                {
                    mp = 0;
                }
                if ((int)dist[mp] > K)
                {
                    rp = mp;
                } else
                {
                    lp = mp;
                }
            }
            Console.WriteLine((N - lp - 2).ToString());

        }
    }

