using System.Numerics;
using Enu = System.Linq.Enumerable;

public class Program
{
    List<int>[] E;

    public void Solve()
    {
        int N = Reader.Int(), K = Reader.Int();
        E = Enu.Range(0, N).Select(i => new List<int>()).ToArray();

        for (int i = 0; i < N - 1; i++)
        {
            int a = Reader.Int() - 1, b = Reader.Int() - 1;
            E[a].Add(b);
            E[b].Add(a);
        }
        int ans = N;
        for (int start = 0; start < N; start++)
            ans = Math.Min(ans, Count(start, -1, 0, K));

        Console.WriteLine(ans);
    }

    int Count(int at, int prev, int depth, int K)
    {
        int res = 0;
        if (depth >= K) res++;

        foreach (int next in E[at])
            if (next != prev)
                res += Count(next, at, depth + 1, K);

        return res;
    }


}


