                        for (int j = 0; j < graph[val[0]].Count; j++)
                        {
                            int index = graph[val[0]][j];
                            if (visited[index]) continue;

                            queue.Enqueue(new int[2] { index, val[1] + 1 });
                        }
                    }
                    res = Min(res, tmp);
                }
