class Myon
{
    public Myon() { }
    public static int Main()
    {
        new Myon().calc();
        return 0;
    }

    Scanner cin;


    int ans;
    int N, K;
    List<int>[] es;

    void calc()
    {
        cin = new Scanner();
        N = cin.nextInt();
        K = cin.nextInt();
        es = new List<int>[N];
        for (int i = 0; i < N; i++)
        {
            es[i] = new List<int>();
        }
        for (int i = 0; i < N - 1; i++)
        {
            int a = cin.nextInt() - 1;
            int b = cin.nextInt() - 1;
            es[a].Add(b);
            es[b].Add(a);
        }

        ans = 99999;

        for (int i = 0; i < N; i++)
        {
            foreach (int j in es[i])
            {
                calc(i, j);
            }
        }
        calc(0, -1);
        Console.WriteLine(ans);
    }

    void calc(int a, int b)
    {
        int[] dist;
        Queue<int> q;
        int nextfirst = 0;

        int MAX = 99999;

        dist = new int[N];
        for (int i = 0; i < N; i++)
        {
            dist[i] = MAX;
        }
        dist[a] = 0;
        q = new Queue<int>();
        q.Enqueue(a);

        while(q.Count != 0)
        {
            int now = q.Dequeue();
            nextfirst = now;
            foreach (var next in es[now])
            {
                if (dist[next] != MAX) continue;
                if (now == a && next == b) continue;
                dist[next] = dist[now] + 1;
                q.Enqueue(next);
            }
        }


        int maxd = 0;
        int cnt = 0;

        dist = new int[N];
        for (int i = 0; i < N; i++)
        {
            dist[i] = MAX;
        }
        dist[nextfirst] = 0;
        q = new Queue<int>();
        q.Enqueue(nextfirst);
        while (q.Count != 0)
        {
            int now = q.Dequeue();
            cnt++;
            maxd = dist[now];
            foreach (var next in es[now])
            {
                if (dist[next] != MAX) continue;
                if (now == a && next == b) continue;
                dist[next] = dist[now] + 1;
                q.Enqueue(next);
            }
        }



        if (maxd <= K)
        {
            ans = Math.Min(ans, N - cnt);
        }
    }


}

