    static int[] nk;
    static List<int>[] adj;
    static void Solve()
    {
        nk = Input.ar;
        adj = Enumerable.Repeat(0, nk[0]).Select(_ => new List<int>()).ToArray();
        var ab = Input.ar2D(nk[0] - 1);
        for (var i=0;i<nk[0]-1;i++)
        {
            ab[i][0]--;ab[i][1]--;
            adj[ab[i][0]].Add(ab[i][1]);
            adj[ab[i][1]].Add(ab[i][0]);
        }
        var res = int.MaxValue;
        if (nk[1] % 2 == 0)
            for (var i = 0; i < nk[0]; i++)
                res = Min(res, bfs(i));
        else foreach (var e in ab)
                res = Min(res, bfs(e[0], e[1]));

        WriteLine(res);
    }
    static int bfs(params int[] st)
    {
        var dist = Enumerable.Repeat(-1, nk[0]).ToArray();
        var que = new Queue<int>();
        foreach (var v in st)
        {
            dist[v] = 0;
            que.Enqueue(v);
        }
        while (que.Any())
        {
            var p = que.Dequeue();
            foreach (var ad in adj[p])
            {
                if (dist[ad] != -1||dist[p]+1>nk[1]/2) continue;
                dist[ad] = dist[p] + 1;
                que.Enqueue(ad);
            }
        }
        return dist.Count(v => v == -1);
    }
