					dfs(u, v, d);
				}
			}
		}

		long ans = long.MaxValue;
		if(K % 2 == 0)
		{
			for(long i = 0; i < N; i++)
			{
				var d = new long[N];
				dfs(i, -1, d);
				chmin(ref ans, d.Count(x => (x > K / 2)));
			}
		}
		else
		{
			for(long i = 0; i < N - 1; i++)
			{
				var d = new long[N];
				dfs(A[i], B[i], d);
				dfs(B[i], A[i], d);
				chmin(ref ans, d.Count(x => (x > (K - 1) / 2)));
			}
		}

		WriteLine(ans);
	}
}

