        }
        var res = int.MaxValue;
        if (nk[1] % 2 == 0)
        {
            for (var i = 0; i < nk[0]; i++)
                if (adj[i].Count == 1)
                    res = Min(res, bsfs(i));
        }
        else foreach (var e in ab)
                res = Min(res, bfs(e[0], e[1]));

        WriteLine(res);
    }
    static int bfs(params int[] st)
    {
        var dist = Enumerable.Repeat(-1, nk[0]).ToArray();
        var que = new Queue<int>();
        foreach (var v in st)
        {
            dist[v] = 0;
            que.Enqueue(v);
        }
        while (que.Any())
        {
            var p = que.Dequeue();
            foreach (var ad in adj[p])
            {
                if (dist[ad] != -1||dist[p]+1>nk[1]/2) continue;
                dist[ad] = dist[p] + 1;
                que.Enqueue(ad);
            }
        }
        return dist.Count(v => v == -1);
    }
    static int bsfs(int st)
    {
        var dist = Enumerable.Repeat(-1, nk[0]).ToArray();
        dist[st] = 0;
        var que = new Queue<int>();
        que.Enqueue(st);
        while (que.Any())
        {
            var p = que.Dequeue();
            foreach (var ad in adj[p])
            {
                if (dist[ad] != -1 || dist[p] + 1 > nk[1]) continue;
                dist[ad] = dist[p] + 1;
                que.Enqueue(ad);
            }
        }
        return dist.Count(v => v == -1);
    }
