			//using (var sw = new StreamWriter("output.txt"))
			{
				task.Solve(sr, sw);
				//Console.ReadKey();
			}
		}
	}

	internal class Task
	{
		public void Solve(InputReader sr, TextWriter sw)
		{
			var input = sr.ReadArray(Int32.Parse);
			var n = input[0];
			var k = input[1];
			var graph = new Graph(n);
			for (var i = 0; i < n - 1; i++) {
				input = sr.ReadArray(Int32.Parse);
				graph.Insert(input[0] - 1, input[1] - 1);
			}
			sw.WriteLine(graph.Min(k));
		}
	}

	class Graph
	{
		private readonly List<int>[] edges;

		public Graph(int n)
		{
			edges = new List<int>[n];
		}

		public void Insert(int x, int y)
		{
			if (edges[x] == null) {
				edges[x] = new List<int>();
			}
			edges[x].Add(y);
			if (edges[y] == null) {
				edges[y] = new List<int>();
			}
			edges[y].Add(x);
		}

		public int Min(int k)
		{
			var min = Int32.MaxValue;
			for (var i = 0; i < edges.Length; i++) {
				var distances = new int[edges.Length];
				Bfs(i, distances);
				var curr = distances.Count(item => item > k / 2);
				min = Math.Min(min, curr);
			}

			return min;
		}

		private void Bfs(int s, int[] distances)
		{
			var queue = new Queue<Tuple<int, int>>();
			queue.Enqueue(new Tuple<int, int>(s, 0));
			var states = new State[edges.Length];
			while (queue.Count > 0) {
				var next = queue.Dequeue();
				distances[next.Item1] = next.Item2;
				if (edges[next.Item1] != null) {
					for (var i = 0; i < edges[next.Item1].Count; i++) {
						if (states[edges[next.Item1][i]] == State.NotDiscovered) {
							states[edges[next.Item1][i]] = State.Discovered;
							queue.Enqueue(new Tuple<int, int>(edges[next.Item1][i], next.Item2 + 1));
						}
					}
				}
				states[next.Item1] = State.Processed;
			}
		}
	}

	enum State
	{
		NotDiscovered,
		Discovered,
