	class Graph
	{
		private readonly List<int>[] edges;
		private readonly int k;
		private int answer = 0;

		public Graph(int vertexCount, int k)
		{
			edges = new List<int>[vertexCount];
			this.k = k;
		}

		public List<int>[] Edges
		{
			get { return edges; }
		}

		public void Insert(int x, int y)
		{
			if (edges[x] == null) {
				edges[x] = new List<int>();
			}
			edges[x].Add(y);
			if (edges[y] == null) {
				edges[y] = new List<int>();
			}
			edges[y].Add(x);
		}

		public int Max(int start)
		{
			var states = new State[edges.Length];

			Dfs(0, states, 0);

			return answer;
		}

		private SortedSet<int> Dfs(int v, State[] states, int currLen)
		{
			states[v] = State.Discovered;
			var lens = new List<SortedSet<int>>();
			if (edges[v] != null) {
				for (var i = 0; i < edges[v].Count; i++) {
					if (states[edges[v][i]] == State.NotDiscovered) {
						lens.Add(Dfs(edges[v][i], states, currLen + 1));
					}
				}
			}
			states[v] = State.Processed;
			if (lens.Count == 1) {
				if (lens[0].Max > k) {
					answer++;
					return new SortedSet<int>();
				}
				else {
					return new SortedSet<int> { lens[0].Max + 1 };
				}
			}
			if (lens.Count == 0) {
				return new SortedSet<int> { 1 };
			}
			var maxes = new int[lens.Count];
			for (var i = 0; i < lens.Count; i++) {
				maxes[i] = lens[i].Max;
			}
			Array.Sort(maxes, (x, y) => -x.CompareTo(y));
			var max = maxes[0];
			var nextMax = maxes[1];
			if (max + nextMax > k) {
				answer++;
				return new SortedSet<int>();
			}

			return new SortedSet<int> { max + 1 };
		}
	}

	enum State
	{
		NotDiscovered,
		Discovered,
		Processed
	}
}

