'use strict';

Array.prototype._sort = Array.prototype.sort;
Array.prototype.sort = function (fn) {
	if (fn) {
		return this._sort(fn);

	} else if (typeof this[0] === 'number') {
		return this._sort((a, b) => a - b);

	} else {
		return this._sort();
	}
};

function gcd(a, b) {
	while (true) {
		if (a > b) {
			a = a % b;
			if (a === 0) return b;
		} else {
			b = b % a;
			if (b === 0) return a;
		}
	}
}

function tree(pairs) {
	let tree = new Map();
	for (let ab of pairs) {
		let a = ab[0], b = ab[1];

		if (!tree.has(a)) tree.set(a, new Set());
		if (!tree.has(b)) tree.set(b, new Set());

		let nodeA = tree.get(a),
			nodeB = tree.get(b);

		nodeA.add(b);
		nodeB.add(a);
	}

	return tree;
}

