class Graph {
	constructor() {
		this.nodes = new Map();
		this.edges = [];
	}

	static fromNodePair(pairs) {
		let graph = new Graph(),
			nodes = graph.nodes,
			edges = graph.edges;

		for (let ab of pairs) {
			let a = ab[0], b = ab[1];

			if (!nodes.has(a)) nodes.set(a, new Set());
			if (!nodes.has(b)) nodes.set(b, new Set());

			let nodeA = nodes.get(a),
				nodeB = nodes.get(b);

			nodeA.add(b);
			nodeB.add(a);
			edges.push([a, b]);
		}

		return graph;
	}
}

