let result = N;
const r = Math.floor(K / 2);

for (let i = 0; i < N; i++) {
	let visited = new Set(),
		que = [],
		d = 0;

	if (K & 1) {
		if (i >= N - 1) break;
		que.push(edges[i][0]);
		que.push(edges[i][1]);
		visited.add(que[0]);
		visited.add(que[1]);
	} else {
		que.push(i + 1);
		visited.add(i + 1);
	}

	while (que.length > 0) {
		let nextQue = [];
		d++;

		for (let fromNode of que) {
			for (let nextNode of nodes.get(fromNode)) {
				if (visited.has(nextNode)) continue;

				nextQue.push(nextNode);
				visited.add(nextNode);
			}
		}

		que = nextQue;

		if (d === r) {
			result = Math.min(result, N - visited.size);
			break
		}
	}
}

