int solveDiameter(Vertex start) {
    int m;
    foreach(i; 0..2) {
        clear();
        m = 0;
        start.depth = 0;
        auto list = DList!(Vertex)(start);
        while (!list.empty) {
            Vertex v = list.front;
            assert(v.flag);
            v.visited = true;
            if (v.depth > m) {
                m = v.depth;
                start = v;
            }
            list.removeFront;
            v.edges.each!((e) {
                if (e.end.visited || !e.end.flag) return;
                list.insertBack(e.end);
                e.end.depth = v.depth+1;
                v.next = e.end;
                e.end.prev = v;
                v.cnt++;
            });
        }
        vPair[i] = start;
    }
    return m;
}

