int N, K;
int[][] edge;

int dfs(int n, int prev, int d) {
    int ret = 1;
    if (d == 0) return ret;

    foreach (m; edge[n]) {
        if (m == prev) continue;
        ret += dfs(m, n, d-1);
    }
    return ret;
}

int dfs2(int n, int prev, int d) {
    if (d == 1 && prev == -1) return edge[n].length.to!int;
    else if (d == 1) return edge[n].length.to!int - 1;

    int ret = 0;
    foreach (m; edge[n]) {
        if (m == prev) continue;
        ret = max(ret, dfs2(m, n, d-1));
    }

    return ret;
}


void main() {
