    edge = new int[][](N);
    foreach (i; 0..N-1) {
        s = readln.split.map!(to!int).array;
        edge[s[0]-1] ~= s[1]-1;
        edge[s[1]-1] ~= s[0]-1;
    }

    int ans = 1 << 29;
    foreach (i; 0..N) { // 各頂点を木の中心と仮定
        int tmp = dfs(i, -1, K/2);
        if (K % 2 == 1) tmp += dfs2(i, -1, K/2+1);
        ans = min(ans, N-tmp);
    }

    writeln(K == 1 ? N-2 : ans);
}

