        foreach (i; 0..N) { // 各頂点を木の中心と仮定
            fill(visited, false);
            dfs(i, -1, K/2);
            ans = min(ans, N-visited.sum);
        }
    }
    else {
        foreach (i; 0..N) {
            foreach (j; edge[i]) {
                if (j < i) continue;
                fill(visited, false);
                dfs(i, -1, K/2);
                dfs(j, -1, K/2);
                ans = min(ans, N-visited.sum);
            }
        }
    }

    writeln(K == 1 ? N-2 : ans);
}

