			a[u] ~= v;
			a[v] ~= u;
		}

		int res = 0;
		int leaves;
		auto b = new bool [n];

		void recur (int v, int p, int d)
		{
			if (d < 0)
			{
				leaves += 1;
				return;
			}

			b[v] = true;
			int c = 0;
			foreach (u; a[v])
			{
				if (u != p)
				{
					c += 1;
					recur (u, v, d - 1);
				}
			}
		}

		foreach (v; 0..n)
		{
			b[] = false;
			int add = 0;
			b[v] = true;
			foreach (u; a[v])
			{
				leaves = 0;
				recur (u, v, k / 2 - 1);
				add = max (add, leaves);
			}
			res = max (res, sum (b) + (k & 1) * add);
		}

		if (k == 1)
		{
			res = 2;
		}

		writeln (n - res);
	}
}

