	else						// If K is odd things will be complicated
		for(int i = 1; i <= N; i++)					// Raise two nodes as one root, then the tree can be halved
			for(vector<int>::iterator itr = Adj[i].begin(); itr != Adj[i].end(); ++itr)
			{
				int nans = 0;
				DFS(i, *itr, 0);
