def DFSans(start,diam):
  visited=[0]*N
  q=deque()
  for s in start:
    q.append((s,0))
    visited[s-1]=1
  while q:
    search,start_diam=q.pop()
    if start_diam>=diam:
      continue
    for n in Graph[search]:
      if visited[n-1]:
        continue
      q.append((n,start_diam+1))
      visited[n-1]=1
    #print(q,visited)
  return N-sum(visited)

