def compute(adj, u, dia):

    vis = [False]*len(adj)

    dis = [0]*len(adj)

    q = Queue(maxsize = len(adj))

    q.put(u)
    vis[u] = True

    while (q.qsize() > 0):

        elem = q.get()

        for v in adj[elem]:

            if (vis[v] == False):
                q.put(v)

                vis[v] = True

                dis[v] = dis[elem] + 1

    count = 0

    for a in dis:

        if (a > dia/2):
            count += 1

    return count


