def computeDist(tree, nk, i):
    visited = [0] * (nk[0] + 1)
    queue = []
    visited[i] = 1
    queue.append(i)
    dist = [0] * (nk[0] + 1)
    dist[i] = 0
    while queue:
        s = queue.pop(0)
        for u in tree[s]:
            if not visited[u]:
                queue.append(u)
                visited[u] = 1
                dist[u] = dist[s] + 1
    return len([i for i in dist if i > nk[1] // 2])

