def MAXDIST(s):
    dist = [None] * N
    que = deque([s])
    dist[s] = 0
    while que:
        v = que.popleft()
        d = dist[v]
        for w in G[v]:
            if dist[w] is not None:
                continue
            dist[w] = d + 1
            que.append(w)
    d = 0
    for x in dist:
        if x is not None:
            d = max(d, x)
    return dist.index(d)

def cut_tree(s):
    dist = [None] * N
    que = deque([s])
    dist[s] = 0
    while que:
        v = que.popleft()
        d = dist[v]
        if d == K:
            break
        for w in G[v]:
            if dist[w] is not None:
                continue
            dist[w] = d + 1
            que.append(w)
    cut_list = tuple(i for i in range(N) if dist[i] is None)
    return cut_list

def main():
    ans = 0
    tmp = G
    while True:
        for i,x in enumerate(G):
            if x:
                sta = i
        u = MAXDIST(sta)
        cut_list = cut_tree(u)
        ans += len(cut_list)
        if not cut_list:
            break
        for i in range(N):
            for E in cut_list:
                if i == E:
