def get_diamiter(v, parent, dep, edge):
    max_dep, cnt, cnt_prev, ret_v = dep, 1, 0, v
    for e in edge[v]:
        if e != parent:
            cand_dep, cand_cnt, cand_prev, cand_v = get_diamiter(e, v, dep + 1, edge)
            if cand_dep > max_dep:
                max_dep, cnt, cnt_prev, ret_v = cand_dep, cand_cnt, cnt_prev, cand_v
            elif cand_dep == max_dep:
                cnt += cand_cnt
                cnt_prev += cand_prev
    return max_dep, cnt, (1 if dep + 1 == max_dep else cnt_prev), ret_v

def remove(v, edge):
    for row in edge:
        if v in row:
            row.remove(v)

def main(N, K, edge):
    ans = 0
    _, _, _, v = get_diamiter(0, -1, 0, edge)
    while True:
        d, c1, p1, v1 = get_diamiter(v, -1, 0, edge)
        if d <= K:
            break
        _, c2, p2, v2 = get_diamiter(v1, -1, 0, edge)
        if c1 < c2 or (c1 == c2 and p1 < p2):
            remove(v1, edge)
            v = v2
        else:
            remove(v2, edge)
            v = v1
        ans += 1
    print(ans)


