import sys
from collections import deque, defaultdict


def bfs(links, s=0):
    ans = [0] * len(links)
    q = deque([(0, s, -1)])
    while q:
        cost, v, p = q.popleft()
        ans[v] = cost
        cost += 1
        q.extend((cost, u, v) for u in links[v] if u != p)
    return ans


def solve(n, k, ab):
    if k == 1:
        return n - 2

    links = [set() for _ in range(n)]
    for a, b in zip(ab[0::2], ab[1::2]):
        a -= 1
        b -= 1
        links[a].add(b)
        links[b].add(a)

    ans = n
    thr = k // 2
    if k % 2 == 0:
        for v in range(n):
            ans = min(ans, sum(d > thr for d in bfs(links, v)))
    else:
        cache = {}
        for a, b in zip(ab[0::2], ab[1::2]):
            a -= 1
            b -= 1
            if a in cache:
                da = cache[a]
            else:
                da = cache[a] = bfs(links, a)
            if b in cache:
                db = cache[b]
            else:
                db = cache[b] = bfs(links, b)
            ans = min(ans, sum(d1 > thr and d2 > thr for d1, d2 in zip(da, db)))
    return ans


