use std::collections::*;
use std::cmp::*;
use std::cmp::Ordering::*;

macro_rules! dump {($($e:expr), +) => {print!(concat!($(stringify!($e), " = {:?}\n"), +), $($e), +)}}

fn main() {
  let (n,k) = get::tuple::<usize,usize>();
  let es = get::tuples::<usize,usize>(n-1);

  let mut t = vec![vec![]; n];
  for &(u,v) in &es {
    t[u-1].push(v-1);
    t[v-1].push(u-1)
  }

  let mut rmin = std::usize::MAX;
  if k%2 == 0 {
    for i in 0 .. n {
      let nr = nreach(&t, i, None, k/2);
      rmin = min(rmin, n - nr)
    }
  } else {
    for &(i,j) in &es {
      let nri = nreach(&t, i-1, Some(j-1), (k-1)/2);
      let nrj = nreach(&t, j-1, Some(i-1), (k-1)/2);
      rmin = min(rmin, n - nri - nrj)
    }
  }

  println!("{}", rmin)
}

fn nreach(t: &Vec<Vec<usize>>, u: usize, up: Option<usize>, d: usize) -> usize {
  let mut q = VecDeque::new();
  q.push_back((u,up,d));
  let mut count = 1;
  while let Some((v,vp,xd)) = q.pop_front() {
    if xd == 0 {continue}
    for &w in t[v].iter().filter(|&&w|Some(w)!=vp) {
      count += 1;
      q.push_back((w,Some(v),xd-1))
    }
  }
  count
}

