fn main() {
    input! {
        n:usize, k:i64,
        l:[(usize1, usize1); n-1]
    };
    let mut dist = vec![vec![-1i64; n]; n];
    for i in 0..n {
        let mut q = vec![];
        q.push((0, i));
        dist[i][i] = 0;
        while let Some((d, s)) = q.pop() {
            for ref e in &l {
                if e.0 == s && dist[i][e.1] < 0 {
                    dist[i][e.1] = d + 1;
                    q.push((d + 1, e.1));
                }
                if e.1 == s && dist[i][e.0] < 0 {
                    dist[i][e.0] = d + 1;
                    q.push((d + 1, e.0));
                }
            }
        }
    }

    if k % 2 == 0 {
        let res = (0..n)
            .map(|i| dist[i].iter().filter(|&&d| d <= k / 2).count())
            .max()
            .unwrap();
        println!("{}", n - res);
    } else {
        let hf = k / 2;
        let res = l
            .iter()
            .map(|&(f, t)| {
                (0..n)
                    .filter(|&i| dist[f][i] <= hf || dist[t][i] <= hf)
                    .count()
            }).max()
            .unwrap();
        println!("{}", n - res);
    }
}

