fn dfs(gr: &Vec<Vec<usize>>, depth: i64, prev: usize, v: usize) -> usize{
    if depth < 0 {
        0
    } else {
        let mut res = 1;
        for next in &gr[v]{
            let next = *next;
            if next != prev{
                res += dfs(&gr, depth - 1, v, next);
            }
        }
        res
    }
}

