fn is_max_i64(num: i64) -> bool {
    if num == i64::max_value() {
        true
    } else {
        false
    }
}

struct WarshallFloyd {
    pub cost: Vec<Vec<i64>>,
}
impl WarshallFloyd {
    fn calc(&mut self) -> i64 {
        let node_num = self.cost.len();
        assert!(node_num == self.cost[0].len(), "invalid cost");
        let mut diameter = 0;
        for k in 0..node_num {
            for i in 0..node_num {
                for j in 0..node_num {
                    if is_max_i64(self.cost[i][k]) | is_max_i64(self.cost[k][j]) {
                        continue;
                    }
                    let newcost = min(self.cost[i][j], self.cost[i][k] + self.cost[k][j]);
                    self.cost[i][j] = newcost;
                    diameter = max(diameter, newcost);
                }
            }
        }
        diameter
    }
}

fn main() {
    let mut pr = ContestPrinter::new();
    let (N, K) = readl!(usize, usize);
    let mut wf = WarshallFloyd{ cost: vec![vec![i64::max_value(); N]; N] };
    let mut ab = Vec::new();
    for i in 0..N-1 {
        let (a, b) = readl!(usize, usize);
        wf.cost[a-1][b-1] = 1;
        wf.cost[b-1][a-1] = 1;
        ab.push((a-1, b-1));
    }

    let d = wf.calc();
    let mut ans = i64::max_value();
    if d > K as i64 {
        if (d % 2) == 0 {
            let k2 = K as i64 / 2;
            for i in 0..N { // center node
                let mut cnt = 0; 
                for j in 0..N {
                    if i == j { continue; }
                    if wf.cost[i][j] > k2 { cnt += 1; }
                }
                ans = min(ans, cnt);
            }
        } else {
            let k12 = (K as i64 - 1) / 2;
            for i in 0..ab.len() {; // center edge
                let mut cnt = 0;
                let (a, b) = ab[i];
                for j in 0..N {
                    if (a == j) | (b == j) { continue; }
                    if min(wf.cost[a][j], wf.cost[b][j]) > k12 {
                        cnt += 1;
                    }
                }
                ans = min(ans, cnt);
            }
        }
    } else {
        ans = 0;
    }

    pr.println(ans);
}

