impl Graph {
    fn depth_dfs(&self, u: usize, p: usize, d: u64, depth: &mut Vec<u64>) {
        depth[u] = d;
        for a in self.adjacency(u).iter().filter(|a| a.to != p) {
            self.depth_dfs(a.to, u, d + 1, depth);
        }
    }
