fn run() {
    input! {
        n: usize,
        k: usize,
        e: [(usize1, usize1); n - 1],
    }
    let mut g = vec![vec![]; n];
    for &(a, b) in &e {
        g[a].push(b);
        g[b].push(a);
    }
    let mut ans = 0;
    let r = k / 2;
    if k % 2 == 0 {
        for i in 0..n {
            let mut cnt = 0;
            let mut stack = vec![(i, i, 0)];
            while let Some((v, p, d)) = stack.pop() {
                if d > r {
                    continue;
                }
                cnt += 1;
                for &u in &g[v] {
                    if u != p {
                        stack.push((u, v, d + 1));
                    }
                }
            }
            ans =std::cmp::max(ans, cnt);
        }
    } else {
        for &(a, b) in &e {
            let mut cnt = 0;
            let mut stack = vec![(a, b, 0), (b, a, 0)];
            while let Some((v, p, d)) = stack.pop() {
                if d > r {
                    continue;
                }
                cnt += 1;
                for &u in &g[v] {
                    if u != p {
                        stack.push((u, v, d + 1));
                    }
                }
            }
            ans = std::cmp::max(ans, cnt);
        }
    }
    println!("{}", n - ans);
}

