fn dfs(g: &Vec<Vec<usize>>, r: usize, i: usize, j: usize) -> usize {
    if r == 0 {
        1            
    } else {
        1 + (&g[i]).into_iter()
            .filter(|x| **x != j)
            .fold(0, |sum, a| sum + dfs(g, r-1, *a, i))
    }
}

