fn main() {
    let stdin = std::io::stdin();
    let line = stdin.lock().lines().next().unwrap().unwrap();
    let mut split = line.split(' ').map(|x| x.parse::<usize>().unwrap());
    let (n, k) = (split.next().unwrap(), split.next().unwrap());
    let mut edges = Vec::new();
    let mut nbrs = vec![Vec::new(); n];
    for line in stdin.lock().lines().take(n - 1).map(|x| x.unwrap()) {
        let mut split = line.split(' ').map(|x| x.parse::<usize>().unwrap());
        let (a, b) = (split.next().unwrap() - 1, split.next().unwrap() - 1);
        edges.push((a, b));
        nbrs[a].push(b);
        nbrs[b].push(a);
    }

    let mut max_count = 0;
    if k % 2 == 0 {
        for center in 0..n {
            let count = count_in_radius(&nbrs, center, n, k / 2 + 1);
            if max_count < count {
                max_count = count;
            }
        }
    } else {
        for center in edges {
            let count =
                count_in_radius(&nbrs, center.0, center.1, k / 2 + 1) +
                count_in_radius(&nbrs, center.1, center.0, k / 2 + 1);
            if max_count < count {
                max_count = count;
            }
        }
    }
    println!("{}", n - max_count);
}

fn count_in_radius(nbrs: &Vec<Vec<usize>>, v: usize, prev: usize,
                   radius: usize) -> usize {
    if radius == 0 {
        return 0;
    }
    let mut count = 1;
    for &next in &nbrs[v] {
        if next != prev {
            count += count_in_radius(nbrs, next, v, radius - 1);
        }
    }
    count
}

