fn bfs(graph: &Vec<Vec<usize>>, start: usize, d: usize) -> i32 {
    let mut visited: Vec<i32> = vec![-1; graph.len()];
    let mut q: VecDeque<usize> = VecDeque::new();
    visited[start] = 0;
    q.push_back(start);
    let mut cnt = 0;
    while !q.is_empty() {
        let &c_idx = q.front().unwrap();
        let c_cost = visited[c_idx];
        for n_idx in graph[c_idx].iter() {
            let c = visited[*n_idx];
            if c < 0 {
                let n_cost = c_cost + 1;
                if n_cost > d as i32 { cnt += 1; }
                visited[*n_idx] = n_cost;
                q.push_back(*n_idx);
            }
        }
        q.pop_front();
    }
    cnt
}

