        g[a-1].push(b-1);
        g[b-1].push(a-1);
        ab.push((a-1, b-1));
    }

    let mut ans = i32::max_value();
    if (K % 2) == 0 {
        let k2 = K / 2;
        for i in 0..N { // center node
            ans = min(ans, bfs(&g, i, k2));
        }
    } else {
        let k12 = (K - 1) / 2;
        for i in 0..ab.len() {; // center edge
            let (a, b) = ab[i];
            ans = min(ans, bfs(&g, a, k12));
            ans = min(ans, bfs(&g, b, k12));
        }
    }

    pr.println(ans);
}

