type Graph = Vec<Vec<usize>>;

fn solve(l: usize, r: usize, k: usize, g: &Graph) -> usize {
    let n = g.len();
    let mut visited = vec![false; n];
    visited[l] = true;
    visited[r] = true;

    let mut que = VecDeque::new();
    if l == r {
        que.push_back(l);
    } else {
        que.push_back(l);
        que.push_back(r);
    }
    for step in 0..k {
        let mut next_que = VecDeque::new();
        while let Some(v) = que.pop_front() {
            for &t in &g[v] {
                if visited[t] {
                    continue;
                }
                visited[t] = true;
                next_que.push_back(t);
            }
        }
        que = next_que;
    }

    let mut visited_count = 0;
    for i in 0..n {
        if visited[i] {
            visited_count += 1;
        }
    }
    n - visited_count
}

fn main() {
    input! {
        n: usize, k: usize,
        edges: [(usize1, usize1); n-1]
    };
    let mut ans = n;
    let mut g = vec![vec![]; n];
    for &e in &edges {
        g[e.0].push(e.1);
        g[e.1].push(e.0);
    }

    if k % 2 == 1 {
        for e in edges {
            ans = min(ans, solve(e.0, e.1, (k-1)/2, &g));
        }
    } else {
        for i in 0..n {
            ans = min(ans, solve(i, i, k/2, &g));
        }
    }
    println!("{}", ans);
}

