fn main(){
    let n: usize = read();
    let k: usize = read();

    let mut po: Vec<Vec<usize>> = vec![Vec::new();n];
    let mut edge: Vec<(usize, usize)> = Vec::new();
    for _ in 0..n-1 {
        let a = read::<usize>() - 1;
        let b = read::<usize>() - 1;
        po[a].push(b);
        po[b].push(a);
        edge.push((a, b));
    }

    let inf = 1 << 31;
    let mut ans = n;
    for i in 0..n {
        let mut que: VecDeque<(usize, usize)> = VecDeque::new();
        let mut dis: Vec<usize> = vec![inf;n];
        if k % 2 == 0 {
            dis[i] = 0;
            que.push_back((i, 0));
        } else {
            if i == n - 1 { break; }
            let (a, b) = edge[i];
            dis[a] = 0;
            dis[b] = 0;
            que.push_back((a, 0));
            que.push_back((b, 0));
        }
        while !que.is_empty() {
            let (v, d) = que.pop_front().unwrap();
            for &j in &po[v] {
                if dis[j] == inf {
                    dis[j] = d + 1;
                    que.push_back((j, d + 1));
                }
            }
        }
        ans = min(ans,
            (0..n).filter(|&x| dis[x] > k / 2).count()
        );
    }
    println!("{}", ans);
}

fn read<T: FromStr>() -> T {
    let stdin = stdin();
    let stdin = stdin.lock();
    let token: String = stdin
        .bytes()
        .map(|c| c.expect("failed to read char") as char) 
        .skip_while(|c| c.is_whitespace())
        .take_while(|c| !c.is_whitespace())
        .collect();
    token.parse().ok().expect("failed to parse token")
}

