fn dfs(now: usize, par: usize, depth: usize, graph: &Vec<Vec<usize>>) -> usize {
    if depth == 0 {
        return 1;
    }
    let mut ret = 1;
    for &to in &graph[now] {
        if to == par {
            continue
        }
        ret += dfs(to, now, depth-1, graph);
    }
    ret
}

fn main() {
    let (n, k): (usize, usize) = read();
    let mut graph: Vec<Vec<usize>> = vec![vec![]; n];
    for i in 0..n-1 {
        let (a, b): (usize, usize) = read();
        graph[a-1].push(b-1);
        graph[b-1].push(a-1);
    }

    let mut best = 0;
    if k % 2 == 1 {
        let half = (k-1)/2;
        for i in 0..n {
            for &j in &graph[i] {
                if i < j {
                    best = max(best, dfs(i, j, half, &graph) + dfs(j, i, half, &graph))
                }
            }
        }
    } else {
        let half = k/2;
        for i in 0..n {
            best = max(best, dfs(i, n, half, &graph));
        }
    }

    println!("{}", n-best);
}

