fn make_tree(
    cur_idx: usize,
    parent_idx: usize,
    nodes: &Vec<Vec<usize>>,
    tree: &mut Vec<Vec<usize>>,
) {
    for child_idx in nodes[cur_idx].iter() {
        if *child_idx == parent_idx {
            continue;
        }
        tree[cur_idx].push(*child_idx);
        make_tree(*child_idx, cur_idx, nodes, tree);
    }
}

fn dfs(
    cur_idx: usize,
    cur_deep: usize,
    max_depth: usize,
    tree: &Vec<Vec<usize>>,
    nodes: &mut Vec<usize>,
) {
    if cur_deep > max_depth {
        return;
    }
    nodes.push(cur_idx);
    for &child_idx in tree[cur_idx].iter() {
        dfs(child_idx, cur_deep + 1, max_depth, tree, nodes);
    }
}

fn main() {
    let v: Vec<usize> = read_vec();
    let (n, k) = (v[0], v[1]);
    let mut nodes = vec![Vec::new(); n];
    let mut edges = Vec::new();
    for i in 0..n - 1 {
        let v: Vec<usize> = read_vec();
        let (a, b) = (v[0] - 1, v[1] - 1);
        nodes[a].push(b);
        nodes[b].push(a);
        edges.push((a, b));
    }

    let mut ans = 0;
    if k % 2 == 0 {
        for root in 0..n {
            let mut tree: Vec<Vec<usize>> = vec![Vec::new(); n];
            make_tree(root, n, &nodes, &mut tree);
            let mut nodes = Vec::new();
            dfs(root, 0, k / 2, &tree, &mut nodes);
            ans = max(ans, nodes.len());
        }
    } else {
        for (node1, node2) in edges {
            let mut tree: Vec<Vec<usize>> = vec![Vec::new(); n];
            make_tree(node1, node2, &nodes, &mut tree);
            let mut nodes1 = Vec::new();
            dfs(node1, 0, (k - 1) / 2, &tree, &mut nodes1);

            let mut tree: Vec<Vec<usize>> = vec![Vec::new(); n];
            make_tree(node2, node1, &nodes, &mut tree);
            let mut nodes2 = Vec::new();
            dfs(node2, 0, (k - 1) / 2, &tree, &mut nodes2);
            ans = max(ans, nodes1.len() + nodes2.len());
        }
    }
    println!("{}", n - ans);
}

