fn main() {
  let (n,k) = get::tuple::<usize,usize>();
  let es = get::tuples::<usize,usize>(n-1);

  let mut t = vec![vec![]; n];
  for &(u,v) in &es {
    t[u-1].push(v-1);
    t[v-1].push(u-1)
  }

  let d = diameter(&t);
  let mut rmin = std::usize::MAX;
  if d%2 == 0 {
    for i in 0 .. n {
      let nr = nreach_v(&t, i, k/2);
      rmin = min(rmin, n - nr)
    }
  } else {
    for &(i,j) in &es {
      let nr = nreach_e(&t, i-1, j-1, k/2);
      rmin = min(rmin, n - nr)
    }
  }

  println!("{}", rmin)
}

fn nreach_v(t: &Vec<Vec<usize>>, i: usize, d: usize) -> usize {
  let mut q = VecDeque::new();
  q.push_back((i,d,None));
  let mut count = 1;
  while let Some((v,x,prev)) = q.pop_front() {
    if x == 0 {continue}
    for &w in t[v].iter().filter(|&&w|Some(w)!=prev) {
      count += 1;
      q.push_back((w,x-1,Some(v)))
    }
  }
  count
}

fn nreach_e(t: &Vec<Vec<usize>>, i: usize, j: usize, d: usize) -> usize {
  let mut q = VecDeque::new();
  q.push_back((i,d,Some(j)));
  let mut count_i = 1;
  while let Some((v,x,prev)) = q.pop_front() {
    if x == 0 {continue}
    for &w in t[v].iter().filter(|&&w|Some(w)!=prev) {
      count_i += 1;
      q.push_back((w,x-1,Some(v)))
    }
  }
  let mut q = VecDeque::new();
  q.push_back((j,d,Some(i)));
  let mut count_j = 1;
  while let Some((v,x,prev)) = q.pop_front() {
    if x == 0 {continue}
    for &w in t[v].iter().filter(|&&w|Some(w)!=prev) {
      count_j += 1;
      q.push_back((w,x-1,Some(v)))
    }
  }
  max(count_i,count_j) + 1
}

fn diameter(t: &Vec<Vec<usize>>) -> usize {
  let (u,_) = ultimate(t, 0);
  let (_,dv) = ultimate(t, u);
  dv
}

fn ultimate(t: &Vec<Vec<usize>>, u: usize) -> (usize,usize) {
  let mut q = VecDeque::new();
  q.push_back((u,0,None));
  let mut ult = 0;
  let mut dmax = 0;
  while let Some((v,d,prev)) = q.pop_front() {
    for &w in t[v].iter().filter(|&&w|Some(w)!=prev) {
      if dmax < d+1 {
        ult = w;
        dmax = d+1
      }
      q.push_back((w,d+1,Some(v)))
    }
  }
  (ult, dmax)
}


