#[derive(Eq, PartialEq, Clone, Debug)]
struct Rev<T>(pub T);

impl<T: PartialOrd> PartialOrd for Rev<T> {
    fn partial_cmp(&self, other: &Rev<T>) -> Option<Ordering> {
        other.0.partial_cmp(&self.0)
    }
}

impl<T: Ord> Ord for Rev<T> {
    fn cmp(&self, other: &Rev<T>) -> Ordering {
        other.0.cmp(&self.0)
    }
}

fn dfs(i: usize, max_d: usize, e: &Vec<Vec<usize>>, visited: &mut Vec<bool>) -> usize {
    visited[i] = true;
    if max_d == 0 {
        1
    } else {
        let v: Vec<usize> = e[i].iter().filter(|&&t| !visited[t]).cloned().collect();
        1 +
            v.iter()
                .map(|&t| dfs(t, max_d - 1, e, visited))
                .sum::<usize>()
    }
}

fn main() {
    let (n, k) = get!(usize, usize);
    let e = get!(usize, usize; n-1);

    let mut g = vec![Vec::new(); n];

    for &(a, b) in &e {
        g[a - 1].push(b - 1);
        g[b - 1].push(a - 1);
    }

    if k % 2 == 0 {
        let ans = n -
            (0..n)
                .map(|i| {
                    let mut visited = vec![false; n];
                    visited[i] = true;
                    dfs(i, k / 2, &g, &mut visited)
                })
                .max()
                .unwrap();
        println!("{}", ans);
    } else {
        let ans = n -
            e.iter()
                .map(|&(a, b)| {
                    let mut visited = vec![false; n];
                    visited[a - 1] = true;
                    visited[b - 1] = true;
                    dfs(a - 1, k / 2, &g, &mut visited) + dfs(b - 1, k / 2, &g, &mut visited)
                })
                .max()
                .unwrap();
        println!("{}", ans);
    }
}

macro_rules! input {
    (source = $s:expr, $($r:tt)*) => {
        let mut iter = $s.split_whitespace();
        let mut next = || { iter.next().unwrap() };
        input_inner!{next, $($r)*}
    };
    ($($r:tt)*) => {
        let stdin = std::io::stdin();
        let mut bytes = std::io::Read::bytes(std::io::BufReader::new(stdin.lock()));
        let mut next = move || -> String {
            bytes
                .by_ref()
                .map(|r| r.unwrap() as char)
                .skip_while(|c| c.is_whitespace())
                .take_while(|c| !c.is_whitespace())
                .collect()
        };
        input_inner!{next, $($r)*}
    };
}

macro_rules! input_inner {
    ($next:expr) => {};
    ($next:expr, ) => {};

    ($next:expr, $var:ident : $t:tt $($r:tt)*) => {
        let $var = read_value!($next, $t);
        input_inner!{$next $($r)*}
    };

    ($next:expr, mut $var:ident : $t:tt $($r:tt)*) => {
        let mut $var = read_value!($next, $t);
        input_inner!{$next $($r)*}
    };
}

macro_rules! read_value {
    ($next:expr, ( $($t:tt),* )) => {
        ( $(read_value!($next, $t)),* )
    };

    ($next:expr, [ $t:tt ; $len:expr ]) => {
        (0..$len).map(|_| read_value!($next, $t)).collect::<Vec<_>>()
    };

    ($next:expr, [ $t:tt ]) => {
        {
            let len = read_value!($next, usize);
            (0..len).map(|_| read_value!($next, $t)).collect::<Vec<_>>()
        }
    };

    ($next:expr, chars) => {
        read_value!($next, String).chars().collect::<Vec<char>>()
    };

    ($next:expr, usize1) => {
        read_value!($next, usize) - 1
    };

    ($next:expr, $t:ty) => {
        $next().parse::<$t>().expect("Parse error")
    };
}

#[allow(unused_imports)]
use std::cmp::{min, max};

fn main() {
    input!{
        n: usize,
        k: usize,
        es: [(usize1, usize1); n - 1]
    }
    let mut t = vec![vec![]; n];
    for &(a, b) in &es {
        t[a].push(b);
        t[b].push(a);
    }
    let mut ans = n;
    if k % 2 == 0 {
        for i in 0..n {
            ans = min(ans, dfs(i, i, k / 2, &t));
        }
    } else {
        for &(a, b) in &es {
            ans = min(ans, dfs(b, a, k / 2, &t) + dfs(a, b, k / 2, &t))
        }
    }
    println!("{}", ans);
}

fn dfs(v: usize, p: usize, d: usize, t: &Vec<Vec<usize>>) -> usize {
    let mut ret = 0;
    for &c in &t[v] {
        if c == p {
            continue;
        }
        if d > 0 {
            ret += dfs(c, v, d - 1, t);
        } else {
            ret += 1 + dfs(c, v, 0, t);
        }
    }
    ret
}

