macro_rules! dump {($($e:expr), +) => {print!(concat!($(stringify!($e), " = {:?}\n"), +), $($e), +)}}

fn main() {
  let (n,k) = get::tuple::<usize,usize>();
  let es = get::tuples::<usize,usize>(n-1);

  let mut t = vec![vec![]; n];
  for (u,v) in es {
    t[u-1].push(v-1);
    t[v-1].push(u-1)
  }

  let ult = (0..n).map(|i|ultimate(&t,i)).collect::<Vec<_>>();
  let vroot = |u: usize| *t[u].iter().max_by(|&&v,&&w|(ult[v],nchild(&t,v,u)).cmp(&(ult[w],nchild(&t,w,u)))).unwrap();

  if *ult.iter().min().unwrap() > k {println!("{}", n-(k+1)); return}

  let ans = (0..n).filter(|&u|ult[u]==k).map(|u|nchild(&t,u,vroot(u))).sum::<usize>();
  println!("{}", ans)
}

fn ultimate(t: &Vec<Vec<usize>>, u: usize) -> usize {
  let mut q = VecDeque::new();
  q.push_back((u,0,None));
  let mut dmax = 0;
  while let Some((v,d,prev)) = q.pop_front() {
    for &w in t[v].iter().filter(|&&w|Some(w)!=prev) {
      dmax = max(dmax, d+1);
      q.push_back((w,d+1,Some(v)))
    }
  }
  dmax
}

fn nchild(t: &Vec<Vec<usize>>, u: usize, p: usize) -> usize {
  let mut q = VecDeque::new();
  let mut n = 0;
  for &v in &t[u] {
    if v!=p {
      n += 1;
      q.push_back((v,Some(u)))
    }
  }
  while let Some((v,prev)) = q.pop_front() {
    for &w in t[v].iter().filter(|&&w|Some(w)!=prev) {
      n += 1;
      q.push_back((w,Some(v)))
    }
  }
  n
}

